static int Run(string[] args)
{
    // Cubit.Tool: shader | worldcheck | simcheck | scene | atlascheck | scenecheck | enginecheck | streamcheck
    if (args.Length == 0)
{
    Console.WriteLine("用法: Cubit.Tool shader [根目录] | worldcheck [seed] | headless [seed] | simcheck [seed] | benchmarkcheck [seed] [--json-output 路径] | voxelstoragesessionbenchmarkcheck [seed] | scene [场景路径] | atlascheck | scenecheck");
    return 0;
}

if (args[0] == "shader")
{
    return CompileShaders(args.Length >= 2 ? args[1] : Directory.GetCurrentDirectory());
}

var seed = 20260808u;
if ((args[0] == "worldcheck" || args[0] == "headless" || args[0] == "simcheck" || args[0] == "lightcheck" || args[0] == "voxelbenchmarkcheck" || args[0] == "voxelstoragebenchmarkcheck" || args[0] == "voxelstoragesessionbenchmarkcheck" || args[0] == "benchmarkcheck") && args.Length >= 2)
{
    _ = uint.TryParse(args[1], out seed);
}

if (args[0] == "worldcheck")
{
    return WorldCheck(seed);
}

if (args[0] == "atlascheck")
{
    var data = Cubit.Voxel.Textures.TextureAtlas.AtlasData;
    var w = Cubit.Voxel.Textures.TextureAtlas.AtlasWidth;
    var h = Cubit.Voxel.Textures.TextureAtlas.AtlasHeight;
    var (u0, v0, u1, v1) = Cubit.Voxel.Textures.TextureAtlas.GetUv(0);
    var tilePixels = 0; long r = 0, g = 0, b = 0;
    for (var y = (int)(v0 * h); y < (int)(v1 * h); y++)
    {
        for (var x = (int)(u0 * w); x < (int)(u1 * w); x++)
        {
            var i = (y * w + x) * 4;
            r += data[i]; g += data[i + 1]; b += data[i + 2]; tilePixels++;
        }
    }
    Console.WriteLine($"atlas {w}x{h} 瓦片0(草顶)平均色 R={r / tilePixels} G={g / tilePixels} B={b / tilePixels}");
    return 0;
}
