static int DebugCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var hidden = ProjectDebugOverlaySnapshot.Hidden;
    Check(
        "隐藏调试快照没有可绘制内容",
        !hidden.IsVisible && hidden.LeftLines.Count == 0 && hidden.RightLines.Count == 0);

    IProjectDebugOverlaySource source = new StubDebugOverlaySource();
    var visible = source.CaptureSnapshot();
    Check(
        "项目调试源以不可变双列快照输出",
        visible.IsVisible && visible.LeftLines.SequenceEqual(["left"]) && visible.RightLines.SequenceEqual(["right"]));

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
    if (projectRoot is null || !Directory.Exists(projectRoot))
    {
        Check("正式项目可用于 F3 调试快照验收", false, projectRoot ?? "missing");
    }
    else
    {
        try
        {
            // ProjectIO.Load refreshes derived metadata, so exercise the formal scene through the
            // existing isolated project-copy helper rather than touching the authored project.
            using var session = CreateVoxelProjectSession(
                new FakeRenderBackend(),
                20260808u,
                workerCount: 1,
                worldType: WorldType.Flat);
            var projectSource = session.Scene.Runtime.Context.GetRequiredService<IProjectDebugOverlaySource>();

            session.Scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.ToggleDebugOverlay, true));
            var firstPress = projectSource.CaptureSnapshot();
            session.Scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.ToggleDebugOverlay, true));
            var repeatedPress = projectSource.CaptureSnapshot();
            session.Scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.ToggleDebugOverlay, false));

            Check(
                "F3 重复按下只切换一次且保持显示",
                firstPress.IsVisible && repeatedPress.IsVisible,
                $"first={firstPress.IsVisible} repeated={repeatedPress.IsVisible}");

            var lines = firstPress.LeftLines.Concat(firstPress.RightLines).ToArray();
            var requiredPrefixes = new[] { "XYZ:", "Chunk:", "World:", "Time:", "Sky:", "Clouds:", "Stream:", "Target:", "Physics:" };
            Check(
                "正式项目 F3 快照包含玩家、世界和物理字段",
                requiredPrefixes.All(prefix => lines.Any(line => line.StartsWith(prefix, StringComparison.Ordinal))),
                string.Join(" | ", lines));
        }
        catch (Exception exception)
        {
            Check("正式项目 F3 调试状态服务可用", false, exception.Message);
        }
    }

    var standaloneState = new MyFirstCubitProject.VoxelDebugOverlayState();
    standaloneState.Attach(new Node { Name = "Root" });
    standaloneState.Toggle();
    var placeholder = standaloneState.CaptureSnapshot();
    Check(
        "缺少作者节点时 F3 快照保留标签占位且不抛出",
        placeholder.IsVisible && placeholder.LeftLines.Concat(placeholder.RightLines).Any(line => line.StartsWith("XYZ:", StringComparison.Ordinal)),
        string.Join(" | ", placeholder.LeftLines.Concat(placeholder.RightLines)));

    var sharedImGuiProject = repositoryRoot is null ? null : Path.Combine(repositoryRoot, "src", "Cubit.ImGui", "Cubit.ImGui.csproj");
    var sharedImGuiSource = sharedImGuiProject is null ? string.Empty : ReadWorkspaceText(sharedImGuiProject);
    Check(
        "共享 ImGui 呈现程序集存在且不依赖编辑器或领域程序集",
        sharedImGuiProject is not null && File.Exists(sharedImGuiProject) &&
        sharedImGuiSource.Contains("Cubit.Core", StringComparison.Ordinal) &&
        sharedImGuiSource.Contains("Hexa.NET.ImGui", StringComparison.Ordinal) &&
        !ContainsAny(sharedImGuiSource, "Cubit.Editor", "Cubit.Sample", "Voxel", "Physics", "MyFirstCubitProject"),
        sharedImGuiProject ?? "missing");

    var sampleImGuiProject = repositoryRoot is null ? null : Path.Combine(repositoryRoot, "hosts", "Cubit.Sample", "Cubit.Sample.csproj");
    var sampleImGuiSource = sampleImGuiProject is null ? string.Empty : ReadWorkspaceText(sampleImGuiProject);
    Check(
        "桌面样例直接引用共享 ImGui 呈现程序集",
        sampleImGuiSource.Contains("Cubit.ImGui", StringComparison.Ordinal),
        sampleImGuiProject ?? "missing");

    var desktopSampleDirectory = repositoryRoot is null ? null : Path.Combine(repositoryRoot, "hosts", "Cubit.Sample");
    var projectDesktopDirectory = workspaceRoot is null
        ? null
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "MyFirstCubitProject.Desktop");
    var desktopProgramPath = desktopSampleDirectory is null ? null : Path.Combine(desktopSampleDirectory, "Program.cs");
    var gameScenePath = desktopSampleDirectory is null ? null : Path.Combine(desktopSampleDirectory, "GameScene.cs");
    var projectPresentationPath = projectDesktopDirectory is null ? null : Path.Combine(projectDesktopDirectory, "MyFirstCubitDesktopPresentation.cs");
    var desktopProgramSource = desktopProgramPath is null ? string.Empty : ReadWorkspaceText(desktopProgramPath);
    var gameSceneSource = gameScenePath is null ? string.Empty : ReadWorkspaceText(gameScenePath);
    var sceneCreationIndex = desktopProgramSource.IndexOf("scene = new GameScene(", StringComparison.Ordinal);
    var overlayCreationIndex = desktopProgramSource.IndexOf("projectPresentation = ImGuiProjectPresentationHost.Create(", StringComparison.Ordinal);
    var sceneUpdateIndex = desktopProgramSource.IndexOf("scene?.ProcessFrame(delta);", StringComparison.Ordinal);
    var overlayUpdateIndex = desktopProgramSource.IndexOf("projectPresentation?.Update(delta);", StringComparison.Ordinal);

    Check(
        "桌面 F3 映射为项目调试开关",
        desktopProgramSource.Contains("Key.F3 => ProjectInputControl.ToggleDebugOverlay", StringComparison.Ordinal),
        desktopProgramPath ?? "missing");
    Check(
        "桌面菜单鼠标坐标按 framebuffer 比例映射",
        desktopProgramSource.Contains("framebufferSize.Width / (float)inputSize.X", StringComparison.Ordinal) &&
        desktopProgramSource.Contains("position.X * scaleX", StringComparison.Ordinal) &&
        desktopProgramSource.Contains("position.Y * scaleY", StringComparison.Ordinal),
        desktopProgramPath ?? "missing");
    Check(
        "桌面通用呈现宿主在项目场景创建后初始化",
        projectPresentationPath is not null && File.Exists(projectPresentationPath) &&
        sceneCreationIndex >= 0 && overlayCreationIndex > sceneCreationIndex,
        projectPresentationPath ?? "missing");
    Check(
        "桌面通用呈现宿主每帧在场景推进后更新",
        sceneUpdateIndex >= 0 && overlayUpdateIndex > sceneUpdateIndex,
        desktopProgramPath ?? "missing");
    Check(
        "桌面指针模式切换后同步当前鼠标坐标",
        desktopProgramSource.Contains("nextMenuPointerActive != menuPointerActive", StringComparison.Ordinal) &&
        desktopProgramSource.Contains("var pointerInputSize = view.Size", StringComparison.Ordinal) &&
        desktopProgramSource.Contains("projectPresentation.OnMouseMove(", StringComparison.Ordinal) &&
        desktopProgramSource.Contains("lastMouse.X * pointerScaleX", StringComparison.Ordinal) &&
        desktopProgramSource.Contains("var pointerPosition = mouse.Position", StringComparison.Ordinal) &&
        desktopProgramSource.Contains("pointerPosition.X * clickScaleX", StringComparison.Ordinal) &&
        desktopProgramSource.Contains("mouseReady = true", StringComparison.Ordinal),
        desktopProgramPath ?? "missing");
    Check(
        "桌面通用呈现宿主会在窗口关闭时释放",
        desktopProgramSource.Contains("projectPresentation?.Dispose();", StringComparison.Ordinal),
        desktopProgramPath ?? "missing");
    Check(
        "桌面场景只从运行时上下文读取项目调试快照",
        gameSceneSource.Contains("public IProjectDebugOverlaySource? DebugOverlaySource", StringComparison.Ordinal) &&
        gameSceneSource.Contains("Runtime.Context.TryGetService<IProjectDebugOverlaySource>", StringComparison.Ordinal) &&
        !ContainsAny(gameSceneSource, "VoxelWorldNode", "PlayerController", "BlockRegistry", "PhysicsWorld3D", "VoxelDebugOverlayState"),
        gameScenePath ?? "missing");

    CheckVanillaF3Overlay(repositoryRoot, workspaceRoot, Check);

    Console.WriteLine(failures == 0 ? "debugcheck 全部通过" : $"debugcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static void CheckVanillaF3Overlay(
    string? repositoryRoot,
    string? workspaceRoot,
    Action<string, bool, string> check)
{
    var policyPath = repositoryRoot is null
        ? null
        : Path.Combine(repositoryRoot, "src", "Cubit.Core", "Rendering", "VulkanRenderPassPolicy.cs");
    var policy = policyPath is null ? string.Empty : ReadWorkspaceText(policyPath);
    var overlayColorAttachment = ExtractMethodBody(policy, "CreateSwapchainOverlayColorAttachment");
    check(
        "F3 覆盖 pass 保留场景颜色",
        overlayColorAttachment.Contains("LoadOp = AttachmentLoadOp.Load", StringComparison.Ordinal) &&
        overlayColorAttachment.Contains("InitialLayout = ImageLayout.PresentSrcKhr", StringComparison.Ordinal) &&
        overlayColorAttachment.Contains("FinalLayout = ImageLayout.PresentSrcKhr", StringComparison.Ordinal),
        policyPath ?? "missing");

    var imguiPath = repositoryRoot is null
        ? null
        : Path.Combine(repositoryRoot, "src", "Cubit.ImGui", "ImGuiRenderer.cs");
    var imgui = imguiPath is null ? string.Empty : ReadWorkspaceText(imguiPath);
    check(
        "共享 ImGui 支持 nearest 静态纹理",
        imgui.Contains("CreateStaticTexture", StringComparison.Ordinal) &&
        imgui.Contains("ImGuiTextureFilter.Nearest", StringComparison.Ordinal) &&
        imgui.Contains("ReleaseStaticTexture", StringComparison.Ordinal),
        imguiPath ?? "missing");

    var projectDesktopDirectory = workspaceRoot is null
        ? null
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "MyFirstCubitProject.Desktop");
    var rendererPath = projectDesktopDirectory is null
        ? null
        : Path.Combine(projectDesktopDirectory, "MyFirstCubitDesktopPresentation.cs");
    var fontPath = projectDesktopDirectory is null
        ? null
        : Path.Combine(projectDesktopDirectory, "MinecraftAsciiBitmapFont.cs");
    var projectPath = projectDesktopDirectory is null
        ? null
        : Path.Combine(projectDesktopDirectory, "MyFirstCubitProject.Desktop.csproj");
    var assetPath = workspaceRoot is null
        ? null
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "assets", "minecraft", "textures", "font", "ascii.png");
    var renderer = rendererPath is null ? string.Empty : ReadWorkspaceText(rendererPath);
    var font = fontPath is null ? string.Empty : ReadWorkspaceText(fontPath);
    var project = projectPath is null ? string.Empty : ReadWorkspaceText(projectPath);

    check(
        "F3 使用全视口透明画布和随原版视口比例缩放",
        renderer.Contains("VanillaSingleplayerUiLayout.Fit(displaySize)", StringComparison.Ordinal) &&
        renderer.Contains("debugScale", StringComparison.Ordinal) &&
        renderer.Contains("linePitch", StringComparison.Ordinal) &&
        renderer.Contains("SetNextWindowPos(Vector2.Zero", StringComparison.Ordinal) &&
        renderer.Contains("SetNextWindowSize(displaySize", StringComparison.Ordinal) &&
        renderer.Contains("NoBackground", StringComparison.Ordinal) &&
        renderer.Contains("AddRectFilled", StringComparison.Ordinal) &&
        !renderer.Contains("CalcTextSize", StringComparison.Ordinal) &&
        !renderer.Contains("AddText", StringComparison.Ordinal),
        rendererPath ?? "missing");
    check(
        "F3 位图字体为英文 ASCII 并有未知字符后备",
        font.Contains("CellSize = 8", StringComparison.Ordinal) &&
        font.Contains("FallbackGlyph = '?'", StringComparison.Ordinal) &&
        font.Contains("AddImage", StringComparison.Ordinal) &&
        font.Contains("ColorComponents.RedGreenBlueAlpha", StringComparison.Ordinal),
        fontPath ?? "missing");
    check(
        "F3 位图资源由项目管理且不依赖参考目录路径",
        assetPath is not null && IsPngWithDimensions(assetPath, 128, 128) &&
        project.Contains("MyFirstCubitProject.Desktop", StringComparison.Ordinal) &&
        font.Contains("ProjectIO.ReadProjectFileBytes", StringComparison.Ordinal) &&
        font.Contains("assets/minecraft/textures/font/ascii.png", StringComparison.Ordinal) &&
        !ContainsAny(renderer, "mc26.1.2", "26.1.2.jar.src") &&
        !ContainsAny(font, "mc26.1.2", "26.1.2.jar.src"),
        assetPath ?? "missing");

    var crosshairPath = projectDesktopDirectory is null
        ? null
        : Path.Combine(projectDesktopDirectory, "VanillaCrosshairLayout.cs");
    var crosshairSource = crosshairPath is null ? string.Empty : ReadWorkspaceText(crosshairPath);
    check(
        "项目准星布局实现存在且不读取参考目录",
        File.Exists(crosshairPath) &&
        crosshairSource.Contains("CanvasSize = 15", StringComparison.Ordinal) &&
        !ContainsAny(crosshairSource, "mc26.1.2", "26.1.2.jar.src"),
        crosshairPath ?? "missing");

    if (File.Exists(crosshairPath))
    {
        var layout = MyFirstCubitProject.Desktop.VanillaCrosshairLayout.Calculate(1280, 720);
        check(
            "准星按原版 15x15 像素布局居中",
            layout.Canvas == new MyFirstCubitProject.Desktop.PixelRect(632, 352, 15, 15) &&
            layout.Horizontal == new MyFirstCubitProject.Desktop.PixelRect(635, 359, 9, 1) &&
            layout.Vertical == new MyFirstCubitProject.Desktop.PixelRect(639, 355, 1, 9),
            $"canvas={layout.Canvas} horizontal={layout.Horizontal} vertical={layout.Vertical}");
        var scaledLayout = MyFirstCubitProject.Desktop.VanillaCrosshairLayout.Calculate(1280, 720, 2);
        check(
            "准星在 1280x720 使用 2x 像素尺寸",
            scaledLayout.Canvas == new MyFirstCubitProject.Desktop.PixelRect(625, 345, 30, 30) &&
            scaledLayout.Horizontal == new MyFirstCubitProject.Desktop.PixelRect(631, 359, 18, 2) &&
            scaledLayout.Vertical == new MyFirstCubitProject.Desktop.PixelRect(639, 351, 2, 18),
            $"canvas={scaledLayout.Canvas} horizontal={scaledLayout.Horizontal} vertical={scaledLayout.Vertical}");
        var largeLayout = MyFirstCubitProject.Desktop.VanillaCrosshairLayout.Calculate(1920, 1080, 3);
        check(
            "准星在 1920x1080 使用 3x 像素尺寸",
            largeLayout.Canvas == new MyFirstCubitProject.Desktop.PixelRect(937, 517, 45, 45) &&
            largeLayout.Horizontal == new MyFirstCubitProject.Desktop.PixelRect(946, 538, 27, 3) &&
            largeLayout.Vertical == new MyFirstCubitProject.Desktop.PixelRect(958, 526, 3, 27),
            $"canvas={largeLayout.Canvas} horizontal={largeLayout.Horizontal} vertical={largeLayout.Vertical}");
        check(
            "准星拒绝小于 15 像素的视口",
            ThrowsArgumentException(() => MyFirstCubitProject.Desktop.VanillaCrosshairLayout.Calculate(14, 720)) &&
            ThrowsArgumentException(() => MyFirstCubitProject.Desktop.VanillaCrosshairLayout.Calculate(1280, 14)),
            "width/height < 15");
    }

    check(
        "项目呈现层只在 Playing 绘制准星",
        renderer.Contains("RenderCrosshair", StringComparison.Ordinal) &&
        renderer.Contains("IsGameplayActive", StringComparison.Ordinal) &&
        renderer.Contains("pixelScale", StringComparison.Ordinal) &&
        renderer.Contains("VanillaSingleplayerUiLayout.Fit(displaySize)", StringComparison.Ordinal),
        rendererPath ?? "missing");

    var controllerPath = workspaceRoot is null
        ? null
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "SingleplayerMenuController.cs");
    var menuRendererPath = projectDesktopDirectory is null
        ? null
        : Path.Combine(projectDesktopDirectory, "SingleplayerMenuRenderer.cs");
    var controller = controllerPath is null ? string.Empty : ReadWorkspaceText(controllerPath);
    var menuRenderer = menuRendererPath is null ? string.Empty : ReadWorkspaceText(menuRendererPath);
    check(
        "保存返回标题动作延后到项目 Process 边界",
        menuRenderer.Contains("QueueReturnToTitle", StringComparison.Ordinal) &&
        controller.Contains("_returnToTitleRequested", StringComparison.Ordinal) &&
        controller.Contains("QueueReturnToTitle", StringComparison.Ordinal) &&
        controller.Contains("_returnToTitleRequested = false", StringComparison.Ordinal),
        controllerPath ?? "missing");

    check(
        "F3 系统规格使用 Core/Vulkan 平台信息且排除 Java",
        renderer.Contains("HostSystemInfo.LogicalProcessorCount", StringComparison.Ordinal) &&
        renderer.Contains("HostSystemInfo.CpuModel", StringComparison.Ordinal) &&
        renderer.Contains("RuntimeInformation.ProcessArchitecture", StringComparison.Ordinal) &&
        renderer.Contains("PhysicalDeviceName", StringComparison.Ordinal) &&
        renderer.Contains("SwapchainFormat", StringComparison.Ordinal) &&
        !renderer.Contains("java.version", StringComparison.Ordinal),
        rendererPath ?? "missing");
    check(
        "Core CPU 型号提供器返回非空诊断值",
        !string.IsNullOrWhiteSpace(HostSystemInfo.CpuModel),
        HostSystemInfo.CpuModel);

    var fullscreenViewport = MyFirstCubitProject.Desktop.VanillaSingleplayerUiLayout.Fit(new Vector2(1920f, 1080f));
    check(
        "全屏 1920x1080 使用 3x F3 字形比例",
        MathF.Abs(fullscreenViewport.Scale - 3f) <= 1e-5f,
        $"scale={fullscreenViewport.Scale:F1}");
    check(
        "F3 两列统一字号、行距加大且右列右对齐",
        renderer.Contains("rightAligned: true", StringComparison.Ordinal) &&
        renderer.Contains("var linePitch = 14f * debugScale", StringComparison.Ordinal) &&
        !renderer.Contains("var columnScale", StringComparison.Ordinal),
        rendererPath ?? "missing");
}

static int EngineCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var engineSource = File.ReadAllText(Path.Combine(
        Directory.GetCurrentDirectory(),
        "src",
        "Cubit.Core",
        "Engine",
        "Engine.cs"));
    Check(
        "Engine 在调用 Update 前归一化平台帧时长",
        engineSource.Contains("NormalizeFrameDelta(delta)", StringComparison.Ordinal)
            && engineSource.Contains("MaximumFrameDeltaSeconds", StringComparison.Ordinal),
        "非法或过长平台 delta 不得传入游戏和音频模块");
    var updateInvocationIndex = engineSource.IndexOf("Update?.Invoke(frameDelta);", StringComparison.Ordinal);
    var tailCloseCheckIndex = updateInvocationIndex < 0
        ? -1
        : engineSource.IndexOf("if (_closing)", updateInvocationIndex, StringComparison.Ordinal);
    var renderFrameIndex = updateInvocationIndex < 0
        ? -1
        : engineSource.IndexOf("_vulkan?.RenderFrame();", updateInvocationIndex, StringComparison.Ordinal);
    Check(
        "Update 请求关闭时引擎跳过尾随 Vulkan 提交并在回调尾部关闭窗口",
        updateInvocationIndex >= 0 && tailCloseCheckIndex > updateInvocationIndex && renderFrameIndex > tailCloseCheckIndex &&
        engineSource.Contains("RequestPlatformClose();", StringComparison.Ordinal) &&
        engineSource.Contains("_renderCallbackDepth", StringComparison.Ordinal),
        "RequestClose 不得在 Update 回调中立即失效交换链");

    var window = new EngineCheckWindow();
    using var engine = new Engine(window) { SelfDriven = true };
    var updateCount = 0;
    engine.Update += _ => Interlocked.Increment(ref updateCount);
    Exception? runError = null;
    var runThread = new Thread(() =>
    {
        try
        {
            engine.Run();
        }
        catch (Exception exception)
        {
            runError = exception;
        }
    })
    {
        IsBackground = true,
        Name = "CubitToolEngineCheck",
    };
    runThread.Start();

    var entered = window.RunEntered.Wait(TimeSpan.FromSeconds(2));
    Thread.Sleep(100);
    Check("SelfDriven 在窗口 Load 前不调用 Update", entered && Volatile.Read(ref updateCount) == 0,
        $"entered={entered} updates={Volatile.Read(ref updateCount)}");

    engine.Dispose();
    window.Close();
    var stopped = runThread.Join(TimeSpan.FromSeconds(2));
    var renderThread = typeof(Engine)
        .GetField("_renderThread", BindingFlags.Instance | BindingFlags.NonPublic)
        ?.GetValue(engine) as Thread;
    Check("Dispose 排空 SelfDriven 渲染线程并返回", stopped && (renderThread is null || !renderThread.IsAlive),
        $"runStopped={stopped} renderAlive={renderThread?.IsAlive}");
    Check("Engine 生命周期检查未产生运行异常", runError is null, runError?.GetType().Name ?? "none");

    Exception? secondDisposeError = null;
    try
    {
        engine.Dispose();
    }
    catch (Exception exception)
    {
        secondDisposeError = exception;
    }
    Check("Engine.Dispose 可重复调用", secondDisposeError is null, secondDisposeError?.GetType().Name ?? "none");

    Console.WriteLine(failures == 0 ? "enginecheck 全部通过" : $"enginecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int SceneFirstCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var runtimeType = typeof(Node).Assembly.GetType("Cubit.Core.Project.ProjectRuntime");
    Check("Core 提供 scene-first 项目运行时", runtimeType is not null, runtimeType?.FullName ?? "missing");

    var cubitRoot = FindCubitRepositoryRoot();
    var workspaceRoot = cubitRoot is null ? null : Directory.GetParent(cubitRoot)?.FullName;
    var gameScenePath = cubitRoot is null ? null : Path.Combine(cubitRoot, "hosts", "Cubit.Sample", "GameScene.cs");
    var voxelScenePath = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目", "scenes", "gameplay.cscene");
    var gameSceneSource = gameScenePath is not null && File.Exists(gameScenePath) ? File.ReadAllText(gameScenePath) : "";
    var voxelSceneSource = voxelScenePath is not null && File.Exists(voxelScenePath) ? File.ReadAllText(voxelScenePath) : "";
    Check(
        "体素宿主不创建默认作者节点",
        !gameSceneSource.Contains("ResetToDefault", StringComparison.Ordinal)
            && !gameSceneSource.Contains("new VoxelWorldNode", StringComparison.Ordinal)
            && !gameSceneSource.Contains("new Camera3D", StringComparison.Ordinal)
            && !gameSceneSource.Contains("AddChild(", StringComparison.Ordinal),
        gameScenePath ?? "未找到 GameScene.cs");
    Check(
        "体素项目主场景声明 World Camera OverworldSky 与玩家实体场景",
        voxelSceneSource.Contains("VoxelWorldNode", StringComparison.Ordinal)
            && voxelSceneSource.Contains("Camera3D", StringComparison.Ordinal)
            && voxelSceneSource.Contains("OverworldSkyNode", StringComparison.Ordinal)
            && voxelSceneSource.Contains("SceneInstance", StringComparison.Ordinal)
            && voxelSceneSource.Contains("scenes/entities/player.cscene", StringComparison.Ordinal),
        voxelScenePath ?? "未找到 gameplay.cscene");

    var root = Path.Combine(Path.GetTempPath(), $"cubit_scene_first_{Guid.NewGuid():N}");
    try
    {
        var project = ProjectIO.Create(root, "Scene First 验证项目");
        File.WriteAllText(project.MainScenePath, SceneIO.WithDocumentUid("""
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "AuthoredRoot",
          "Properties": null,
          "Children": [
            {
              "Type": "Cubit.Core.Scene.BoxMesh3D",
              "Name": "AuthoredBox",
              "Properties": { "Size": 2.0 },
              "Children": null
            }
          ]
        }
""", project.SceneCatalog.MainScene.Uid));

        IDisposable? runtime = null;
        Exception? constructionError = null;
        try
        {
            runtime = runtimeType is null
                ? null
                : Activator.CreateInstance(
                    runtimeType,
                    [project, new FakeRenderBackend(), Array.Empty<IEnginePlugin>(), null, null, null,
                        new JobSystemOptions { WorkerCount = 1 }, null]) as IDisposable;
        }
        catch (Exception exception)
        {
            constructionError = exception;
        }

        var tree = runtime is null
            ? null
            : runtimeType?.GetProperty("Tree")?.GetValue(runtime) as SceneTree;
        var jobs = runtime is null
            ? null
            : runtimeType?.GetProperty("Jobs")?.GetValue(runtime) as JobSystem;
        Check(
            "运行时树来自项目 mainScene 且接受宿主 Job 配置",
            constructionError is null && tree?.GetNode("/Root/AuthoredBox") is BoxMesh3D && jobs?.WorkerCount == 1,
            constructionError?.GetBaseException().Message ?? "未加载 AuthoredBox");

        File.WriteAllText(project.MainScenePath, SceneIO.WithDocumentUid("""
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "AuthoredRoot",
          "Properties": null,
          "Children": [
            {
              "Type": "Cubit.Core.Scene.BoxMesh3D",
              "Name": "ReloadedBox",
              "Properties": { "Size": 3.0 },
              "Children": null
            }
          ]
        }
""", project.SceneCatalog.MainScene.Uid));
        Exception? reloadError = null;
        try
        {
            runtimeType?.GetMethod("ReloadMainScene")?.Invoke(runtime, null);
        }
        catch (TargetInvocationException exception)
        {
            reloadError = exception.InnerException ?? exception;
        }
        catch (Exception exception)
        {
            reloadError = exception;
        }

        Check(
            "重载只读取项目 mainScene 而非默认场景",
            runtime is not null && reloadError is null && tree?.GetNode("/Root/ReloadedBox") is BoxMesh3D,
            reloadError?.Message ?? "未加载 ReloadedBox");
        runtime?.Dispose();
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, true);
        }
    }

    Console.WriteLine(failures == 0 ? "scenefirstcheck 全部通过" : $"scenefirstcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectMetadataCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    static JsonObject? ReadUidCache(string path) =>
        File.Exists(path) ? JsonNode.Parse(File.ReadAllText(path)) as JsonObject : null;

    static JsonObject? FindEntry(JsonObject? cache, string relativePath) =>
        cache?["files"]?.AsArray()
            .Select(node => node as JsonObject)
            .FirstOrDefault(node => string.Equals(
                node?["path"]?.GetValue<string>(),
                relativePath,
                StringComparison.Ordinal));

    static bool HasNestedUid(JsonObject scene)
    {
        foreach (var child in scene["Children"]?.AsArray().Select(node => node as JsonObject) ?? [])
        {
            if (child is not null && (child.ContainsKey("uid") || HasNestedUid(child)))
            {
                return true;
            }
        }

        return false;
    }

    var root = Path.Combine(Path.GetTempPath(), $"cubit_project_metadata_{Guid.NewGuid():N}");
    try
    {
        var project = ProjectIO.Create(root, "项目元数据验证");
        var metadataDirectory = Path.Combine(root, ".cubit");
        var importedDirectory = Path.Combine(metadataDirectory, "imported");
        var cachePath = Path.Combine(metadataDirectory, "uid-cache.json");
        Check(
            "创建项目时建立 Cubit 私有元数据目录",
            Directory.Exists(metadataDirectory) && Directory.Exists(importedDirectory),
            metadataDirectory);
        Check("项目元数据 API 存在", typeof(ProjectIO).Assembly.GetType("Cubit.Core.Project.ProjectMetadata") is not null);

        var cache = ReadUidCache(cachePath);
        var manifestEntry = FindEntry(cache, ProjectIO.ManifestFileName);
        var sceneEntry = FindEntry(cache, ProjectIO.DefaultMainScene);
        Check(
            "清单和主场景都登记稳定 UID",
            manifestEntry?["uid"]?.GetValue<string>()?.StartsWith("cuid://", StringComparison.Ordinal) == true &&
            sceneEntry?["uid"]?.GetValue<string>()?.StartsWith("cuid://", StringComparison.Ordinal) == true &&
            manifestEntry?["uid"]?.GetValue<string>() != sceneEntry?["uid"]?.GetValue<string>(),
            cachePath);

        var sceneDocument = JsonNode.Parse(File.ReadAllText(project.MainScenePath)) as JsonObject;
        var sceneUid = sceneDocument?["uid"]?.GetValue<string>();
        Check(
            "主场景在文件内保存与缓存一致的 UID",
            !string.IsNullOrWhiteSpace(sceneUid) &&
            sceneUid == sceneEntry?["uid"]?.GetValue<string>(),
            sceneUid ?? "missing");
        Check(
            "场景 UID 只存在于文件根而非子节点",
            sceneDocument is not null && !HasNestedUid(sceneDocument),
            sceneDocument is null ? "missing" : "检查子节点 uid 字段");

        var legacyChild = sceneDocument?["Children"]?.AsArray().FirstOrDefault() as JsonObject;
        if (legacyChild is not null)
        {
            legacyChild["uid"] = null;
            File.WriteAllText(project.MainScenePath, sceneDocument!.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));
        }

        _ = ProjectIO.Load(root);
        var normalizedSceneDocument = JsonNode.Parse(File.ReadAllText(project.MainScenePath)) as JsonObject;
        Check(
            "加载项目会规范化旧场景的空子节点 UID",
            normalizedSceneDocument is not null && !HasNestedUid(normalizedSceneDocument),
            normalizedSceneDocument is null ? "missing" : "重新加载后检查");

        var secondaryScenePath = Path.Combine(root, "scenes", "secondary.cscene");
        File.WriteAllText(secondaryScenePath, """
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Secondary",
          "Properties": null,
          "Children": null
        }
        """);
        _ = ProjectIO.Load(root);
        var secondaryEntry = FindEntry(ReadUidCache(cachePath), "scenes/secondary.cscene");
        var secondaryDocument = JsonNode.Parse(File.ReadAllText(secondaryScenePath)) as JsonObject;
        Check(
            "项目内非主场景也保存与缓存一致的 UID",
            secondaryDocument?["uid"]?.GetValue<string>() == secondaryEntry?["uid"]?.GetValue<string>() &&
            !string.IsNullOrWhiteSpace(secondaryEntry?["uid"]?.GetValue<string>()),
            secondaryEntry?["uid"]?.GetValue<string>() ?? "missing");

        var assetsDirectory = Path.Combine(root, "assets");
        Directory.CreateDirectory(assetsDirectory);
        var originalAssetPath = Path.Combine(assetsDirectory, "sample.asset");
        File.WriteAllText(originalAssetPath, "uid rename verification");
        _ = ProjectIO.Load(root);
        var firstAssetEntry = FindEntry(ReadUidCache(cachePath), "assets/sample.asset");
        var firstAssetUid = firstAssetEntry?["uid"]?.GetValue<string>();
        Check(
            "新增项目资源被 UID 缓存登记",
            firstAssetUid?.StartsWith("cuid://", StringComparison.Ordinal) == true,
            firstAssetUid ?? "missing");

        File.Move(originalAssetPath, Path.Combine(assetsDirectory, "renamed.asset"));
        _ = ProjectIO.Load(root);
        var renamedEntry = FindEntry(ReadUidCache(cachePath), "assets/renamed.asset");
        Check(
            "同内容资源改名后保留 UID",
            !string.IsNullOrWhiteSpace(firstAssetUid) &&
            renamedEntry?["uid"]?.GetValue<string>() == firstAssetUid,
            $"before={firstAssetUid} after={renamedEntry?["uid"]?.GetValue<string>()}");

        var firstSaveDirectory = Path.Combine(root, "saves", "world-one");
        var secondSaveDirectory = Path.Combine(root, "saves", "world-two");
        Directory.CreateDirectory(firstSaveDirectory);
        File.WriteAllBytes(Path.Combine(firstSaveDirectory, "itemdrops.cubit.bin"), [1, 2, 3, 4]);
        _ = ProjectIO.Load(root);
        Directory.CreateDirectory(secondSaveDirectory);
        File.WriteAllBytes(Path.Combine(secondSaveDirectory, "itemdrops.cubit.bin"), [1, 2, 3, 4]);
        _ = ProjectIO.Load(root);
        var cacheAfterRuntimeSaves = ReadUidCache(cachePath);
        var runtimeSaveEntries = cacheAfterRuntimeSaves?["files"]?.AsArray()
            .Select(node => node as JsonObject)
            .Where(node => node?["path"]?.GetValue<string>().StartsWith("saves/", StringComparison.Ordinal) == true)
            .ToArray() ?? [];
        Check(
            "运行时 saves 目录不参与项目源 UID 缓存",
            runtimeSaveEntries.Length == 0,
            string.Join(',', runtimeSaveEntries.Select(entry => entry?["path"]?.GetValue<string>() ?? "missing")));
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "projectmetadatacheck 全部通过" : $"projectmetadatacheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

