static int DesktopCloseCheck()
{
    var failures = 0;
    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var closeRequest = new Cubit.Sample.Platform.FrameCloseRequest();
    var frameStages = new List<string>();
    frameStages.Add("begin-render");
    closeRequest.Request();
    frameStages.Add(closeRequest.IsRequested ? "request-recorded" : "request-missing");
    frameStages.Add("render-complete");
    var closeAfterRender = closeRequest.TryConsume();
    frameStages.Add(closeAfterRender ? "close-after-render" : "close-missing");

    Check(
        "关闭请求不会在 ImGui 当前帧内抢先释放呈现资源",
        frameStages.SequenceEqual(["begin-render", "request-recorded", "render-complete", "close-after-render"]),
        string.Join(',', frameStages));
    Check(
        "关闭请求只在帧边界消费一次",
        !closeRequest.IsRequested && !closeRequest.TryConsume());

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var desktopProgramPath = repositoryRoot is null
        ? null
        : Path.Combine(repositoryRoot, "hosts", "Cubit.Sample", "Program.cs");
    var desktopProgram = desktopProgramPath is null ? string.Empty : ReadWorkspaceText(desktopProgramPath);
    var requestIndex = desktopProgram.IndexOf("projectPresentation = ImGuiProjectPresentationHost.Create(engine.Vulkan!, scene.Runtime, closeRequest.Request)", StringComparison.Ordinal);
    var updateIndex = desktopProgram.IndexOf("projectPresentation?.Update(delta);", StringComparison.Ordinal);
    var consumeIndex = desktopProgram.IndexOf("closeRequest.TryConsume()", StringComparison.Ordinal);
    var closeIndex = desktopProgram.IndexOf("engine.RequestClose();", StringComparison.Ordinal);
    var closingIndex = desktopProgram.IndexOf("view.Closing += () =>", StringComparison.Ordinal);
    var runIndex = desktopProgram.IndexOf("engine.Run();", StringComparison.Ordinal);
    var presentationDisposeIndex = desktopProgram.IndexOf("projectPresentation?.Dispose();", StringComparison.Ordinal);
    var sceneDisposeIndex = desktopProgram.IndexOf("scene?.Dispose();", StringComparison.Ordinal);
    var inputDispatchIndex = desktopProgram.IndexOf("void DispatchPresentationInput", StringComparison.Ordinal);
    Check(
        "桌面宿主在呈现帧完成后才消费关闭请求并调用 Engine.RequestClose",
        requestIndex >= 0 && updateIndex >= 0 && consumeIndex > updateIndex && closeIndex > consumeIndex &&
        desktopProgram.Contains("Volatile.Read(ref shutdownRequested)", StringComparison.Ordinal),
        desktopProgramPath ?? "missing");
    Check(
        "窗口 Closing 只标记停止，呈现和场景资源在 Engine.Run 返回后释放",
        closingIndex >= 0 && runIndex > closingIndex && presentationDisposeIndex > runIndex && sceneDisposeIndex > runIndex &&
        !desktopProgram[closingIndex..runIndex].Contains("Dispose();", StringComparison.Ordinal),
        desktopProgramPath ?? "missing");
    Check(
        "关闭已请求后 GLFW 尾随键鼠事件不会再访问项目呈现对象",
        inputDispatchIndex >= 0 &&
        desktopProgram.Contains("if (Volatile.Read(ref shutdownRequested) != 0)", StringComparison.Ordinal) &&
        desktopProgram.Split("DispatchPresentationInput(", StringSplitOptions.None).Length >= 6,
        desktopProgramPath ?? "missing");

    Console.WriteLine(failures == 0 ? "desktopclosecheck 全部通过" : $"desktopclosecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int HostPurityCheck(string[] args)
{
    var failures = 0;
    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    Check(
        "hostpuritycheck 使用固定版本",
        args.Length == 2 && args[1] == "20260817",
        string.Join(' ', args));

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = string.IsNullOrWhiteSpace(repositoryRoot)
        ? null
        : Directory.GetParent(repositoryRoot)?.FullName;
    Check("定位工作区根目录", workspaceRoot is not null, workspaceRoot ?? "missing");
    if (workspaceRoot is null)
    {
        return 1;
    }

    var desktopHost = Path.Combine(repositoryRoot!, "hosts", "Cubit.Sample", "GameScene.cs");
    var desktopProgram = Path.Combine(repositoryRoot!, "hosts", "Cubit.Sample", "Program.cs");
    var desktopProject = Path.Combine(repositoryRoot!, "hosts", "Cubit.Sample", "Cubit.Sample.csproj");
    var androidHost = Path.Combine(repositoryRoot!, "hosts", "Cubit.Sample.Android", "MainActivity.cs");
    var androidProject = Path.Combine(repositoryRoot!, "hosts", "Cubit.Sample.Android", "Cubit.Sample.Android.csproj");
    var sampleRoot = Path.Combine(repositoryRoot!, "hosts");
    var projectRoot = Path.Combine(workspaceRoot, "我的第一个cubit项目");
    var projectManifest = Path.Combine(projectRoot, "project.cubit.json");
    var projectAssembly = Path.Combine(projectRoot, "src", "MyFirstCubitProject.csproj");

    var desktopHostSource = ReadWorkspaceText(desktopHost);
    var desktopProgramSource = ReadWorkspaceText(desktopProgram);
    var desktopProjectSource = ReadWorkspaceText(desktopProject);
    var androidHostSource = ReadWorkspaceText(androidHost);
    var androidProjectSource = ReadWorkspaceText(androidProject);
    var manifestSource = ReadWorkspaceText(projectManifest);
    var platformHostSources = Directory.Exists(sampleRoot)
        ? Directory.EnumerateFiles(sampleRoot, "*.cs", SearchOption.AllDirectories)
            .Where(path => !IsGeneratedBuildPath(path))
            .Select(ReadWorkspaceText)
            .ToArray()
        : [];

    Check(
        "桌面宿主不引用体素或项目节点类型",
        !ContainsAny(desktopHostSource, "Cubit.Voxel", "VoxelWorldNode", "PlayerController", "VoxelInputState", "BlockRegistry") &&
        !ContainsAny(desktopProgramSource, "Cubit.Voxel", "VoxelInputState", "BlockRegistry", "PlayerController"),
        desktopHost);
    Check(
        "Android 宿主不引用体素或项目节点类型",
        !ContainsAny(androidHostSource, "Cubit.Voxel", "VoxelInputState", "BlockRegistry", "VoxelWorldNode", "PlayerController"),
        androidHost);
    Check(
        "全部平台宿主源码不解释项目或体素玩法",
        !platformHostSources.Any(source => ContainsAny(
            source,
            "Cubit.Voxel",
            "Cubit.Mcp.Voxel",
            "MyFirstCubitProject",
            "VoxelInputState",
            "VoxelWorldNode",
            "BlockRegistry",
            "PlayerController",
            "WorldGenerator",
            "SceneMigration",
            "SetBreak(",
            "SetPlace(",
            "SetSelectedBlock(",
            "ClassDB.Register")),
        $"sources={platformHostSources.Length}");
    Check(
        "平台宿主不链接单个项目源码文件",
        !ContainsAny(desktopProjectSource, "PlayerController.cs", "Compile Include=\"..\\..\\我的第一个cubit项目") &&
        !ContainsAny(androidProjectSource, "PlayerController.cs", "Compile Include=\"..\\..\\我的第一个cubit项目"),
        $"{desktopProject}; {androidProject}");
    Check(
        "项目拥有独立 C# 程序集",
        File.Exists(projectAssembly),
        projectAssembly);
    Check(
        "项目清单声明显式运行时引导器",
        manifestSource.Contains("\"runtime\"", StringComparison.Ordinal) &&
        manifestSource.Contains("\"assembly\"", StringComparison.Ordinal) &&
        manifestSource.Contains("\"type\"", StringComparison.Ordinal),
        projectManifest);

    try
    {
        var input = new InputServer();
        using var session = ProjectRuntimeBootstrapLoader.Create(
            ProjectIO.Load(projectRoot),
            new FakeRenderBackend(),
            context => context.AddService(input),
            new JobSystemOptions { WorkerCount = 1 });
        var voxelInput = session.Runtime.Context.GetRequiredService<VoxelInputState>();
        session.Runtime.Scenes.Switch("gameplay");
        var player = session.Runtime.Tree.GetNode(new NodePath("/Root/Physics/Player"));

        Check(
            "项目 runtime 在主场景反序列化前注册项目节点类型",
            string.Equals(player?.GetType().FullName, "MyFirstCubitProject.PlayerController", StringComparison.Ordinal),
            $"id={session.Runtime.Scenes.CurrentSceneId} children={string.Join(',', session.Runtime.Tree.Root.Children.Select(node => node.Name))} player={player?.GetPath().Value ?? "missing"}");
        Check(
            "体素输入服务由项目启用的官方插件提供",
            true,
            voxelInput.GetType().Assembly.GetName().Name ?? "unknown");

        session.RouteInput(new ProjectInputEvent(ProjectInputControl.PrimaryPointer, true));
        session.RouteInput(new ProjectInputEvent(ProjectInputControl.SecondaryPointer, true));
        session.RouteInput(new ProjectInputEvent(ProjectInputControl.Digit6, true));
        var routedInput = voxelInput.BuildSnapshot();
        Check(
            "项目标题页拦截体素操作输入",
            !routedInput.Break && !routedInput.Place && routedInput.SelectedBlock == BlockRegistry.Grass,
            $"break={routedInput.Break} place={routedInput.Place} selected={routedInput.SelectedBlock}");

        var menuState = session.Runtime.Context.GetRequiredService<MyFirstCubitProject.SingleplayerMenuState>();
        menuState.ShowWorldSelection();
        menuState.BeginOpeningWorld();
        menuState.BeginPlaying();
        session.RouteInput(new ProjectInputEvent(ProjectInputControl.PrimaryPointer, true));
        session.RouteInput(new ProjectInputEvent(ProjectInputControl.SecondaryPointer, true));
        session.RouteInput(new ProjectInputEvent(ProjectInputControl.Digit6, true));
        routedInput = voxelInput.BuildSnapshot();
        Check(
            "项目游戏中路由独立解释原始控制",
            routedInput.Break && routedInput.Place && routedInput.SelectedBlock == BlockRegistry.GetId("my_first:oak_leaves"),
            $"break={routedInput.Break} place={routedInput.Place} selected={routedInput.SelectedBlock}");
    }
    catch (Exception exception)
    {
        Check("项目 runtime 可启动并提供领域组合", false, exception.ToString());
    }

    Console.WriteLine(failures == 0 ? "hostpuritycheck 全部通过" : $"hostpuritycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static string ReadWorkspaceText(string path) => File.Exists(path) ? File.ReadAllText(path) : string.Empty;

static string ExtractMethodBody(string source, string methodName)
{
    var methodIndex = source.IndexOf(methodName, StringComparison.Ordinal);
    if (methodIndex < 0)
    {
        return string.Empty;
    }

    var openingBrace = source.IndexOf('{', methodIndex);
    if (openingBrace < 0)
    {
        return string.Empty;
    }

    var depth = 0;
    for (var index = openingBrace; index < source.Length; index++)
    {
        if (source[index] == '{')
        {
            depth++;
        }
        else if (source[index] == '}' && --depth == 0)
        {
            return source[openingBrace..(index + 1)];
        }
    }

    return string.Empty;
}

static bool IsPngWithDimensions(string path, int expectedWidth, int expectedHeight)
{
    if (!File.Exists(path))
    {
        return false;
    }

    var bytes = File.ReadAllBytes(path);
    if (bytes.Length < 24 ||
        !bytes.AsSpan(0, 8).SequenceEqual(new byte[] { 137, 80, 78, 71, 13, 10, 26, 10 }) ||
        !bytes.AsSpan(12, 4).SequenceEqual("IHDR"u8))
    {
        return false;
    }

    var width = System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(bytes.AsSpan(16, 4));
    var height = System.Buffers.Binary.BinaryPrimitives.ReadInt32BigEndian(bytes.AsSpan(20, 4));
    return width == expectedWidth && height == expectedHeight;
}

static bool ContainsAny(string text, params string[] values) => values.Any(value => text.Contains(value, StringComparison.Ordinal));

static bool IsGeneratedBuildPath(string path)
{
    var directory = new DirectoryInfo(Path.GetDirectoryName(path) ?? string.Empty);
    while (directory is not null)
    {
        if (string.Equals(directory.Name, "bin", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(directory.Name, "obj", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        directory = directory.Parent;
    }

    return false;
}

