static int ProjectSceneMigrationCheck()
{
    var workspace = FindCubitRepositoryRoot();
    var projectRoot = workspace is null ? null : Path.Combine(Directory.GetParent(workspace)?.FullName ?? "", "我的第一个cubit项目");
    var expected = new[] { "boot", "title", "world-selection", "create-world", "gameplay" };
    var failures = 0;
    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    if (projectRoot is null || !File.Exists(Path.Combine(projectRoot, ProjectIO.ManifestFileName)))
    {
        Check("定位首个项目", false, projectRoot ?? "missing");
    }
    else
    {
        try
        {
            var project = ProjectIO.Load(projectRoot);
            var ids = project.SceneCatalog.Entries.Select(entry => entry.Id).OrderBy(id => id).ToArray();
            Check("首个项目迁移到五场景目录", ids.SequenceEqual(expected.OrderBy(id => id)), string.Join(',', ids));
            Check("首个项目 mainScene 指向 boot", project.SceneCatalog.MainScene.Id == "boot", project.Manifest.MainScene);
            Check("boot 保留旧 main 场景根 UID", project.SceneCatalog.MainScene.Uid == "cuid://d3ea319d769144639af2fce37a3a9d98", project.SceneCatalog.MainScene.Uid);
            Check("五个真实场景文件均存在", expected.All(id => project.SceneCatalog.TryGetById(id, out _)));
            using (var runtimeSession = ProjectRuntimeBootstrapLoader.Create(
                       project,
                       new FakeRenderBackend(),
                       jobSystemOptions: new JobSystemOptions { WorkerCount = 1 }))
            {
                runtimeSession.Runtime.ProcessFrame(0.016);
                Check(
                    "真实项目 boot 首帧自动进入 title",
                    runtimeSession.Runtime.Scenes.CurrentSceneId == "title" &&
                    runtimeSession.Runtime.Tree.GetNode("/Root/SingleplayerMenu") is not null,
                    $"id={runtimeSession.Runtime.Scenes.CurrentSceneId} children={string.Join(',', runtimeSession.Runtime.Tree.Root.Children.Select(node => node.Name))}");
            }
        }
        catch (Exception exception)
        {
            Check("首个项目迁移状态可加载", false, exception.Message);
        }
    }

    var legacyFixture = Path.Combine(Path.GetTempPath(), $"cubit_scene_migration_fixture_{Guid.NewGuid():N}");
    try
    {
        var fixtureProject = ProjectIO.Create(legacyFixture, "迁移器 fixture");
        File.WriteAllText(fixtureProject.MainScenePath, """
        {
          "uid": "cuid://d3ea319d769144639af2fce37a3a9d98",
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Root",
          "Children": [
            { "Type": "Cubit.Voxel.World.VoxelWorldNode", "Name": "World" },
            { "Type": "Cubit.Core.Scene.Camera3D", "Name": "Camera" },
            { "Type": "Cubit.Physics.Scene.PhysicsWorld3D", "Name": "Physics" },
            { "Type": "MyFirstCubitProject.MenuMusicController", "Name": "MenuMusic" },
            { "Type": "MyFirstCubitProject.SingleplayerMenuController", "Name": "SingleplayerMenu" }
          ]
        }
        """);
        var migrated = MyFirstCubitProject.ProjectSceneMigration.Migrate(legacyFixture);
        var migratedAgain = MyFirstCubitProject.ProjectSceneMigration.Migrate(legacyFixture);
        var migratedProject = ProjectIO.Load(legacyFixture);
        Check("项目场景迁移器可从旧 main 生成五场景", migrated && migratedProject.SceneCatalog.MainScene.Id == "boot");
        Check("项目场景迁移器幂等重复执行不改动", !migratedAgain && !File.Exists(Path.Combine(legacyFixture, "scenes", "main.cscene")));
        Check("项目场景迁移器保留旧根 UID", migratedProject.SceneCatalog.MainScene.Uid == "cuid://d3ea319d769144639af2fce37a3a9d98");
    }
    catch (Exception exception)
    {
        Check("项目场景迁移器 fixture 执行", false, exception.Message);
    }
    finally
    {
        if (Directory.Exists(legacyFixture)) Directory.Delete(legacyFixture, recursive: true);
    }

    Console.WriteLine(failures == 0 ? "projectscenemigrationcheck 全部通过" : $"projectscenemigrationcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

