    var changed = MyFirstCubitProject.ProjectSceneMigration.AttachPlayerEntityScene(projectDirectory);
    Console.WriteLine(changed ? "已补齐玩家实体 SceneInstance UID" : "玩家实体 SceneInstance 已是最新");
    return 0;
}

static int EditorCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var workspaceRoot = FindCubitRepositoryRoot();
    var editorNodePath = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "src", "Cubit.Editor", "EditorNode.cs");
    var editorNodeSource = editorNodePath is not null && File.Exists(editorNodePath) ? File.ReadAllText(editorNodePath) : string.Empty;
    Check(
        "Editor UI 提供项目场景目录入口",
        editorNodeSource.Contains("SceneCatalog", StringComparison.Ordinal) &&
        editorNodeSource.Contains("OpenScene", StringComparison.Ordinal),
        editorNodePath ?? "missing");

    var root = Path.Combine(Path.GetTempPath(), $"cubit_editor_multiscene_{Guid.NewGuid():N}");
    try
    {
        var created = ProjectIO.Create(root, "Editor 多场景验收");
        var altPath = Path.Combine(root, "scenes", "alt.cscene");
        File.WriteAllText(created.ManifestPath, """
        {
          "formatVersion": 1,
          "name": "Editor 多场景验收",
          "mainScene": "scenes/main.cscene",
          "preview": { "assembly": "preview/Cubit.Tool.dll", "type": "EditorPreviewProbe" },
          "scenes": [
            { "id": "main", "path": "scenes/main.cscene" },
            { "id": "alt", "path": "scenes/alt.cscene" }
          ]
        }
        """);
        Directory.CreateDirectory(Path.Combine(root, "preview"));
        File.Copy(typeof(EditorPreviewProbe).Assembly.Location, Path.Combine(root, "preview", "Cubit.Tool.dll"));
        File.WriteAllText(created.MainScenePath, """
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Root",
          "Properties": null,
          "Children": [
            { "Type": "Cubit.Core.Scene.BoxMesh3D", "Name": "MainBox", "Properties": null, "Children": null }
          ]
        }
        """);
        File.WriteAllText(altPath, """
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Root",
          "Properties": null,
          "Children": [
            { "Type": "Cubit.Core.Scene.BoxMesh3D", "Name": "AltBox", "Properties": null, "Children": null }
          ]
        }
        """);

        using var session = new ProjectSceneSession(new FakeRenderBackend(), root);
        using var editorHost = new EditorMcpHost(() => session, _ => throw new InvalidOperationException("测试中不切换项目"), vulkan: null!);
        var idProperty = typeof(ProjectSceneSession).GetProperty("CurrentSceneId");
        var openMethod = typeof(ProjectSceneSession).GetMethod("OpenScene");
        Check("Editor 会话记录当前场景 ID", idProperty is not null && idProperty.GetValue(session) as string == "main");
        Check("Editor 会话提供任意场景打开入口", openMethod is not null);
        if (openMethod is not null)
        {
            openMethod.Invoke(session, ["alt"]);
            Check(
                "Editor 可打开非 mainScene 场景",
                idProperty?.GetValue(session) as string == "alt" && Path.GetFileName(session.ScenePath) == "alt.cscene" &&
                session.Tree.GetNode("/Root/AltBox") is BoxMesh3D,
                $"id={idProperty?.GetValue(session)} path={session.ScenePath} tree={session.Tree.Root.Children.Count} alt={session.Tree.GetNode("/Root/AltBox") is not null}");
            session.Save();
            Check("Editor 保存当前非主场景不改写 mainScene", File.ReadAllText(created.MainScenePath).Contains("MainBox", StringComparison.Ordinal));
            var mcpLoad = editorHost.LoadScene("alt", apply: true);
            var mcpSave = editorHost.SaveScene("alt");
            Check(
                "Editor MCP scene.load/save 使用当前场景 ID",
                mcpLoad.Contains("AltBox", StringComparison.Ordinal) && mcpSave.EndsWith("alt.cscene", StringComparison.OrdinalIgnoreCase));
            session.StartPreview();
            session.StopPreview();
            Check(
                "停止预览恢复当前作者场景而非强制 mainScene",
                idProperty?.GetValue(session) as string == "alt" && session.Tree.GetNode("/Root/AltBox") is BoxMesh3D);
        }
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  Editor 多场景验收异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(root)) Directory.Delete(root, recursive: true);
    }

    Console.WriteLine(failures == 0 ? "editorcheck 全部通过" : $"editorcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectMultisceneCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var root = Path.Combine(Path.GetTempPath(), $"cubit_project_multiscene_{Guid.NewGuid():N}");
    var ids = new[] { "boot", "title", "world-selection", "create-world", "gameplay" };
    try
    {
        var project = ProjectIO.Create(root, "五场景目录验收");
        var scenes = ids.Select(id => new { id, path = $"scenes/{id}.cscene" }).ToArray();
        File.WriteAllText(project.ManifestPath, JsonSerializer.Serialize(new
        {
            formatVersion = 1,
            name = "五场景目录验收",
            mainScene = scenes[0].path,
            scenes,
        }, new JsonSerializerOptions { WriteIndented = true }));
        foreach (var scene in scenes)
        {
            File.WriteAllText(
                Path.Combine(root, scene.path.Replace('/', Path.DirectorySeparatorChar)),
                $$"""
                {
                  "Type": "Cubit.Core.Scene.Node",
                  "Name": "Root",
                  "Properties": null,
                  "Children": [
                    { "Type": "Cubit.Core.Scene.BoxMesh3D", "Name": "{{scene.id}}-node", "Properties": null, "Children": null }
                  ]
                }
                """);
        }

        project = ProjectIO.Load(root);
        Check("项目目录包含 boot/title/world-selection/create-world/gameplay 五个场景", project.SceneCatalog.Entries.Select(entry => entry.Id).OrderBy(id => id).SequenceEqual(ids.OrderBy(id => id)), string.Join(',', project.SceneCatalog.Entries.Select(entry => entry.Id)));
        Check("五个场景均有稳定 UID", project.SceneCatalog.Entries.All(entry => entry.Uid.StartsWith(ProjectMetadata.UidPrefix, StringComparison.Ordinal)));

        using var runtime = new ProjectRuntime(project, new FakeRenderBackend(), Array.Empty<IEnginePlugin>(), jobSystemOptions: new JobSystemOptions { WorkerCount = 1 });
        var switched = new List<string>();
        foreach (var id in ids)
        {
            runtime.Scenes.Switch(id);
            switched.Add(runtime.Scenes.CurrentSceneId ?? "");
        }

        Check("运行时可按项目场景 ID 逐一切换五个场景", switched.SequenceEqual(ids), string.Join(',', switched));
        Check("五场景切换后当前路径来自场景目录", runtime.Scenes.CurrentScenePath?.EndsWith("gameplay.cscene", StringComparison.OrdinalIgnoreCase) == true);
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  五场景项目验收异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(root)) Directory.Delete(root, recursive: true);
    }

    Console.WriteLine(failures == 0 ? "projectmultiscenecheck 全部通过" : $"projectmultiscenecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int EditorRegistryCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var editorContractsAssembly = typeof(Cubit.Editor.Contracts.IEditorDock).Assembly;
    var editorDockContract = editorContractsAssembly?.GetType("Cubit.Editor.Contracts.IEditorDock");
    var inspectorProviderContract = editorContractsAssembly?.GetType("Cubit.Editor.Contracts.IEditorInspectorProvider");
    var viewportToolContract = editorContractsAssembly?.GetType("Cubit.Editor.Contracts.IEditorViewportTool");
    Check(
        "Editor 提供不依赖 ImGui 的插件绘制契约",
        editorDockContract is not null && inspectorProviderContract is not null && viewportToolContract is not null,
        $"assembly={editorContractsAssembly is not null} dock={editorDockContract is not null} inspector={inspectorProviderContract is not null} viewport={viewportToolContract is not null}");

    var root = Path.Combine(Path.GetTempPath(), $"cubit_editor_registry_{Guid.NewGuid():N}");
    try
    {
        var project = ProjectIO.Create(root, "Editor registry 隔离验收");
        File.WriteAllText(project.ManifestPath, """
        {
          "formatVersion": 1,
          "name": "Editor registry 隔离验收",
          "mainScene": "scenes/main.cscene",
          "plugins": [
            { "id": "cubit.physics", "version": "1.0.0" }
          ]
        }
        """);
        File.WriteAllText(project.MainScenePath, SceneIO.WithDocumentUid("""
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Root",
          "Properties": null,
          "Children": [
            { "Type": "Cubit.Physics.Scene.PhysicsWorld3D", "Name": "Physics", "Properties": null, "Children": null }
          ]
        }
        """, project.SceneCatalog.MainScene.Uid));

        using var session = new ProjectSceneSession(new FakeRenderBackend(), root);
        var registryProperty = typeof(ProjectSceneSession).GetProperty("SceneRegistry");
        var registry = registryProperty?.GetValue(session) as SceneRegistry;
        Check(
            "Editor 项目会话拥有独立 SceneRegistry",
            registryProperty is not null && registry is not null,
            $"property={registryProperty is not null} registry={registry is not null}");
        Check(
            "Editor 场景通过会话 registry 加载插件节点",
            session.Tree.GetNode("/Root/Physics") is PhysicsWorld3D && registry?.InstantiateNode("PhysicsWorld3D") is PhysicsWorld3D);
        Check(
            "Editor 插件节点不污染全局 ClassDB",
            Cubit.Core.ObjectSystem.ClassDB.Instantiate("PhysicsWorld3D") is null);
        var cubitRoot = FindCubitRepositoryRoot();
        var editorNodePath = cubitRoot is null
            ? null
            : Path.Combine(cubitRoot, "src", "Cubit.Editor", "EditorNode.cs");
        var editorNodeSource = editorNodePath is not null && File.Exists(editorNodePath)
            ? File.ReadAllText(editorNodePath)
            : string.Empty;
        Check(
            "Editor Inspector 和类型列表不直接依赖静态 ClassDB",
            editorNodeSource.Length > 0 && !editorNodeSource.Contains("ClassDB.", StringComparison.Ordinal),
            editorNodePath ?? "missing");
        Check(
            "Editor 消费会话级编辑器扩展 registry",
            editorNodeSource.Contains("PluginRegistry.EditorExtensions", StringComparison.Ordinal) &&
            editorNodeSource.Contains("FindInspectorProvider", StringComparison.Ordinal) &&
            editorNodeSource.Contains("GetEditorExtensions(PluginRegistrationKind.ViewportTool)", StringComparison.Ordinal) &&
            editorNodeSource.Contains("RenameSelectedNode", StringComparison.Ordinal) &&
            editorNodeSource.Contains("DeleteSelectedNode", StringComparison.Ordinal),
            editorNodePath ?? "missing");
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  Editor registry 隔离异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "editorregistrycheck 全部通过" : $"editorregistrycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int EditorWorkflowCheck()
{
    var failures = 0;
    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var editorType = typeof(Cubit.Editor.EditorNode);
    var create = editorType.GetMethod("CreateNode", BindingFlags.Instance | BindingFlags.Public);
    var rename = editorType.GetMethod("RenameSelectedNode", BindingFlags.Instance | BindingFlags.Public);
    var delete = editorType.GetMethod("DeleteSelectedNode", BindingFlags.Instance | BindingFlags.Public);
    var categories = editorType.GetMethod("GetInspectorPropertyGroups", BindingFlags.Static | BindingFlags.Public);
    Check(
        "Editor 暴露节点创建、重命名、删除和 Inspector 分组入口",
        create is not null && rename is not null && delete is not null && categories is not null,
        $"create={create is not null} rename={rename is not null} delete={delete is not null} groups={categories is not null}");

    var groupType = editorType.GetNestedType("InspectorPropertyGroup", BindingFlags.Public);
    Check("Inspector 分组元数据类型公开", groupType is not null, groupType?.FullName ?? "missing");

    var operationsType = editorType.Assembly.GetType("Cubit.Editor.EditorSceneOperations");
    var createWithRegistry = operationsType?.GetMethod("CreateNode", BindingFlags.Static | BindingFlags.Public);
    var renameNode = operationsType?.GetMethod("RenameNode", BindingFlags.Static | BindingFlags.Public);
    var deleteNode = operationsType?.GetMethod("DeleteNode", BindingFlags.Static | BindingFlags.Public);
    Check(
        "Editor 将场景树编辑逻辑收敛为可测试操作服务",
        operationsType is not null && createWithRegistry is not null && renameNode is not null && deleteNode is not null,
        $"type={operationsType is not null} create={createWithRegistry is not null} rename={renameNode is not null} delete={deleteNode is not null}");

    using (var tree = new SceneTree())
    {
        var registry = new SceneRegistry();
        var first = Cubit.Editor.EditorSceneOperations.CreateNode(tree, registry, tree.Root, "Node");
        var second = Cubit.Editor.EditorSceneOperations.CreateNode(tree, registry, tree.Root, "Node");
        var renameConflict = second is null || !Cubit.Editor.EditorSceneOperations.RenameNode(second, first?.Name ?? "Node");
        var renamed = second is not null && Cubit.Editor.EditorSceneOperations.RenameNode(second, "Second");
        var deleted = second is not null && Cubit.Editor.EditorSceneOperations.DeleteNode(second);
        var rootDeleteRejected = !Cubit.Editor.EditorSceneOperations.DeleteNode(tree.Root);
        Check(
            "Editor 场景树操作保持 registry、同级命名和根节点保护",
            first?.Name == "Node" && second?.Name == "Second" && renameConflict && renamed && deleted && rootDeleteRejected && tree.Root.Children.Count == 1,
            $"first={first?.Name} second={second?.Name} conflict={renameConflict} renamed={renamed} deleted={deleted} root={rootDeleteRejected} count={tree.Root.Children.Count}");
    }

    using (var defaultNameTree = new SceneTree())
    {
        var camera = Cubit.Editor.EditorSceneOperations.CreateNode(
            defaultNameTree,
            new SceneRegistry(),
            defaultNameTree.Root,
            "Camera3D");
        Check(
            "节点创建器使用类型名作为默认节点名",
            camera?.Name == "Camera3D",
            $"actual={camera?.Name ?? "null"}");
    }

    var groups = Cubit.Editor.EditorNode.GetInspectorPropertyGroups(typeof(BoxMesh3D));
    Check(
        "Inspector 属性按导出/通用分组",
        groups.Any(group => group.Name == "导出属性" && group.Properties.Any(property => property.Name == "Size")),
        string.Join(',', groups.Select(group => group.Name)));
    var sizeProperty = typeof(BoxMesh3D).GetProperty(nameof(BoxMesh3D.Size));
    var displayNameMethod = editorType.GetMethod("GetInspectorPropertyDisplayName", BindingFlags.Static | BindingFlags.Public);
    var displayName = sizeProperty is null || displayNameMethod is null
        ? null
        : displayNameMethod.Invoke(null, [sizeProperty]) as string;
    Check("Inspector 优先使用 ExportAttribute 显示名", displayName == "尺寸", displayName ?? "missing");
    var inspectorEditors = editorType.GetMethod("GetInspectorPropertyEditorKind", BindingFlags.Static | BindingFlags.Public);
    var vectorProperty = typeof(Node3D).GetProperty(nameof(Node3D.Position));
    var floatEditor = sizeProperty is null || inspectorEditors is null
        ? null
        : inspectorEditors.Invoke(null, [sizeProperty]) as string;
    var vectorEditor = vectorProperty is null || inspectorEditors is null
        ? null
        : inspectorEditors.Invoke(null, [vectorProperty]) as string;
    var boolProperty = typeof(SceneInstance).GetProperty(nameof(SceneInstance.Flatten));
    var boolEditor = boolProperty is null || inspectorEditors is null
        ? null
        : inspectorEditors.Invoke(null, [boolProperty]) as string;
    Check(
        "Inspector 提供浮点、布尔和 Vector3 编辑器",
        floatEditor == "Float" && boolEditor == "Boolean" && vectorEditor == "Vector3",
        $"float={floatEditor ?? "missing"} bool={boolEditor ?? "missing"} vector={vectorEditor ?? "missing"}");

    var commandHistoryType = editorType.Assembly.GetType("Cubit.Editor.EditorCommandHistory");
    var commandType = editorType.Assembly.GetType("Cubit.Editor.IEditorCommand");
    var createCommand = operationsType?.GetMethod("CreateNodeCommand", BindingFlags.Static | BindingFlags.Public);
    var deleteCommand = operationsType?.GetMethod("DeleteNodeCommand", BindingFlags.Static | BindingFlags.Public);
    var renameCommand = operationsType?.GetMethod("RenameNodeCommand", BindingFlags.Static | BindingFlags.Public);
    var propertyCommand = operationsType?.GetMethod("SetPropertyCommand", BindingFlags.Static | BindingFlags.Public);
    Check(
        "Editor 提供可撤销的场景编辑命令契约",
        commandHistoryType is not null && commandType is not null &&
        createCommand is not null && deleteCommand is not null &&
        renameCommand is not null && propertyCommand is not null,
        $"history={commandHistoryType is not null} command={commandType is not null} " +
        $"create={createCommand is not null} delete={deleteCommand is not null} " +
        $"rename={renameCommand is not null} property={propertyCommand is not null}");

    var nodeTypeEntries = editorType.GetMethod("GetNodeTypeEntries", BindingFlags.Static | BindingFlags.Public);
    var nodeHistory = editorType.GetMethod("GetNodeCreateHistory", BindingFlags.Instance | BindingFlags.Public);
    Check(
        "Editor 节点创建器提供类型归属与搜索历史入口",
        nodeTypeEntries is not null && nodeHistory is not null,
        $"entries={nodeTypeEntries is not null} history={nodeHistory is not null}");
    if (nodeTypeEntries is not null)
    {
        var entryList = nodeTypeEntries.Invoke(null, [new SceneRegistry(), null]) as IReadOnlyList<object>;
        var hasCoreEntry = entryList?.Any(entry =>
        {
            var entryType = entry.GetType();
            return string.Equals(entryType.GetProperty("TypeName")?.GetValue(entry) as string, "Node", StringComparison.OrdinalIgnoreCase) &&
                !string.IsNullOrWhiteSpace(entryType.GetProperty("Group")?.GetValue(entry) as string) &&
                !string.IsNullOrWhiteSpace(entryType.GetProperty("Owner")?.GetValue(entry) as string);
        }) == true;
        Check("节点创建器条目包含引擎归属分组", hasCoreEntry, $"count={entryList?.Count ?? 0}");
    }

    using (var commandTree = new SceneTree())
    {
        var registry = new SceneRegistry();
        var history = new Cubit.Editor.EditorCommandHistory();
        var createNodeCommand = Cubit.Editor.EditorSceneOperations.CreateNodeCommand(
            commandTree, registry, commandTree.Root, "Node");
        history.Execute(createNodeCommand);
        var created = createNodeCommand.CreatedNode;
        var createRoundTrip = created is not null && commandTree.Root.Children.Count == 1 && history.Undo();
        var createUndo = created is not null && commandTree.Root.Children.Count == 0 && history.Redo();
        var createRedo = created is not null && commandTree.Root.Children.Count == 1 &&
            ReferenceEquals(commandTree.Root.Children[0], created);
        Check(
            "节点创建命令支持撤销和重做",
            createRoundTrip && createUndo && createRedo,
            $"roundTrip={createRoundTrip} undo={createUndo} redo={createRedo}");

        var siblingA = Cubit.Editor.EditorSceneOperations.CreateNode(commandTree, registry, commandTree.Root, "Node");
        var siblingB = Cubit.Editor.EditorSceneOperations.CreateNode(commandTree, registry, commandTree.Root, "Node");
        var siblingC = Cubit.Editor.EditorSceneOperations.CreateNode(commandTree, registry, commandTree.Root, "Node");
        if (siblingA is not null && siblingB is not null && siblingC is not null)
        {
            var deleteHistory = new Cubit.Editor.EditorCommandHistory();
            deleteHistory.Execute(Cubit.Editor.EditorSceneOperations.DeleteNodeCommand(siblingB));
            var removed = commandTree.Root.Children.Count == 3 &&
                commandTree.Root.Children[0] == created && commandTree.Root.Children[2] == siblingC;
            var restored = deleteHistory.Undo() && commandTree.Root.Children.Count == 4 &&
                ReferenceEquals(commandTree.Root.Children[2], siblingB);
            var removedAgain = deleteHistory.Redo() && commandTree.Root.Children.Count == 3 &&
                ReferenceEquals(commandTree.Root.Children[2], siblingC);
            Check(
                "删除命令恢复父级和原始兄弟顺序",
                removed && restored && removedAgain,
                $"removed={removed} restored={restored} redo={removedAgain}");
        }
        else
        {
            Check("删除命令恢复父级和原始兄弟顺序", false, "节点创建失败");
        }

        if (created is not null)
        {
            var oldName = created.Name;
            var editHistory = new Cubit.Editor.EditorCommandHistory();
            editHistory.Execute(Cubit.Editor.EditorSceneOperations.RenameNodeCommand(created, "Edited"));
            var renamed = created.Name == "Edited";
            var renameUndone = editHistory.Undo() && created.Name == oldName;
            var renameRedone = editHistory.Redo() && created.Name == "Edited";
            var nameProperty = typeof(Node).GetProperty(nameof(Node.Name));
            editHistory.Undo();
            var propertyCommandWorked = nameProperty is not null;
            if (nameProperty is not null)
            {
                editHistory.Execute(Cubit.Editor.EditorSceneOperations.SetPropertyCommand(created, nameProperty, "PropertyEdited"));
                var redoCleared = !editHistory.CanRedo;
                propertyCommandWorked = created.Name == "PropertyEdited" && editHistory.Undo() && created.Name == oldName;
                Check(
                    "新编辑命令清理 redo 并支持 Inspector 属性恢复",
                    propertyCommandWorked && redoCleared && editHistory.Redo() && created.Name == "PropertyEdited",
                    $"renamed={renamed} undo={renameUndone} redo={renameRedone} property={propertyCommandWorked} redoCleared={redoCleared}");
            }
            else
            {
                Check("新编辑命令清理 redo 并支持 Inspector 属性恢复", false, "Node.Name 属性不存在");
            }
        }
        else
        {
            Check("新编辑命令清理 redo 并支持 Inspector 属性恢复", false, "节点创建失败");
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var firstProjectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
    using (var authoringTree = new SceneTree())
    {
        authoringTree.LifecycleEnabled = false;
        var probe = new EditorLifecycleProbeNode();
        authoringTree.Root.AddChild(probe);
        authoringTree.ProcessFrame(1d);
        Check(
            "编辑态场景树不执行项目节点生命周期",
            probe.EnterCount == 0 && probe.ReadyCount == 0 && probe.ProcessCount == 0 && probe.PhysicsCount == 0,
            $"enter={probe.EnterCount} ready={probe.ReadyCount} process={probe.ProcessCount} physics={probe.PhysicsCount}");
    }
    if (firstProjectRoot is not null && Directory.Exists(firstProjectRoot))
    {
        var firstProjectManifestPath = Path.Combine(firstProjectRoot, ProjectIO.ManifestFileName);
        var firstProjectManifest = File.Exists(firstProjectManifestPath)
            ? File.ReadAllText(firstProjectManifestPath)
            : string.Empty;
        Check(
            "首个 Minecraft 项目声明编辑器程序集入口",
            firstProjectManifest.Contains("\"editor\"", StringComparison.Ordinal),
            firstProjectManifestPath);

        try
        {
            using var firstProjectSession = new ProjectSceneSession(new FakeRenderBackend(), firstProjectRoot);
            var projectFlow = firstProjectSession.Tree.GetNode("/Root/ProjectFlow");
            Check(
                "编辑器可加载首个项目作者节点并读取其场景属性",
                projectFlow?.GetType().FullName == "MyFirstCubitProject.ProjectFlowController",
                projectFlow?.GetType().FullName ?? "missing");

            firstProjectSession.OpenScene("gameplay");
            var projectWorld = firstProjectSession.Tree.GetNode("/Root/World");
            var projectPlayer = firstProjectSession.Tree.GetNode("/Root/Physics/Player");
            var moveSpeed = projectPlayer?.GetType().GetProperty("MoveSpeed")?.GetValue(projectPlayer);
            Check(
                "编辑器可加载首个项目 gameplay 场景并保留项目属性",
                projectWorld?.GetType().FullName == "Cubit.Voxel.World.VoxelWorldNode" &&
                projectPlayer?.GetType().FullName == "MyFirstCubitProject.PlayerController" &&
                moveSpeed is float speed && Math.Abs(speed - 8f) < 0.001f,
                $"world={projectWorld?.GetType().FullName ?? "missing"} player={projectPlayer?.GetType().FullName ?? "missing"} moveSpeed={moveSpeed ?? "missing"}");
        }
        catch (Exception exception)
        {
            Check("编辑器可加载首个项目作者节点并读取其场景属性", false, exception.Message);
            Check("编辑器可加载首个项目 gameplay 场景并保留项目属性", false, exception.Message);
        }
    }

    Console.WriteLine(failures == 0 ? "editorworkflowcheck 全部通过" : $"editorworkflowcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectEditorExtensionCheck()
{
    var failures = 0;
    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var sessionType = typeof(ProjectSceneSession);
    var registryProperty = sessionType.GetProperty("ProjectEditorRegistry", BindingFlags.Instance | BindingFlags.Public);
    Check(
        "项目会话暴露独立项目编辑器 registry",
        registryProperty is not null,
        registryProperty?.PropertyType.FullName ?? "missing");

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
    if (projectRoot is null || !Directory.Exists(projectRoot))
    {
        Check("首个项目可用于项目编辑器扩展验收", false, projectRoot ?? "missing");
        return failures == 0 ? 0 : 1;
    }

    try
    {
        using var session = new ProjectSceneSession(new FakeRenderBackend(), projectRoot);
        var registry = registryProperty?.GetValue(session);
        var extensions = registry?.GetType().GetProperty("Extensions")?.GetValue(registry) as System.Collections.IEnumerable;
        var extensionList = extensions?.Cast<object>().ToArray() ?? [];
        var kinds = extensionList
            .Select(extension => extension.GetType().GetProperty("Kind")?.GetValue(extension)?.ToString() ?? "")
            .ToArray();
        var ids = extensionList
            .Select(extension => extension.GetType().GetProperty("Id")?.GetValue(extension)?.ToString() ?? "")
            .ToArray();
        var requiredIds = new[]
        {
            "player-controller", "voxel-world", "overworld-sky", "overworld-clouds", "player-model",
            "combat-target", "first-person-arm", "menu-music", "singleplayer-menu", "player-ecs",
            "player-pose", "combat-systems", "player-death", "player-model-part", "project-content-status",
            "project-viewport-status", "project-resource-editor",
        };
        Check(
            "首个项目注册 Inspector、Dock 和视口工具",
            extensionList.Length >= requiredIds.Length &&
            requiredIds.All(requiredId => ids.Contains(requiredId, StringComparer.OrdinalIgnoreCase)) &&
            kinds.Contains("Inspector", StringComparer.OrdinalIgnoreCase) &&
            kinds.Contains("Dock", StringComparer.OrdinalIgnoreCase) &&
            kinds.Contains("ViewportTool", StringComparer.OrdinalIgnoreCase),
            $"count={extensionList.Length} ids={string.Join(',', ids)} kinds={string.Join(',', kinds)}");

        session.OpenScene("gameplay");
        var player = session.Tree.GetNode("/Root/Physics/Player");
        var findInspector = registry?.GetType().GetMethod("FindInspector", BindingFlags.Instance | BindingFlags.Public);
        var inspector = player is null || findInspector is null
            ? null
            : findInspector.Invoke(registry, [player.GetType()]);
        var groups = inspector?.GetType().GetProperty("PropertyGroups")?.GetValue(inspector) as System.Collections.IEnumerable;
        var groupNames = groups?.Cast<object>()
            .Select(group => group.GetType().GetProperty("Name")?.GetValue(group) as string ?? "")
            .ToArray() ?? [];
        Check(
            "玩家 Inspector 提供项目语义分组",
            inspector is not null && groupNames.Contains("移动") && groupNames.Contains("视角"),
            $"target={player?.GetType().Name ?? "missing"} groups={string.Join(',', groupNames)}");
        var gameplayProperty = player?.GetType().GetProperty("GameplayActive");
        var readOnlyKind = gameplayProperty is null
            ? null
            : Cubit.Editor.EditorNode.GetInspectorPropertyEditorKind(gameplayProperty);
        Check(
            "Inspector 将项目计算属性标记为只读",
            readOnlyKind == "ReadOnly",
            $"property={gameplayProperty?.Name ?? "missing"} editor={readOnlyKind ?? "missing"}");
        var nodeEntries = Cubit.Editor.EditorNode.GetNodeTypeEntriesForProject(
            session.SceneRegistry,
            session.PluginRegistry,
            session.ProjectEditorRegistry);
        var playerEntry = nodeEntries.FirstOrDefault(entry =>
            entry.Type == player?.GetType());
        Check(
            "节点创建器显示项目语义标题与分类",
            playerEntry?.DisplayName == "玩家控制器" && playerEntry.Group == "项目 / 玩家",
            $"title={playerEntry?.DisplayName ?? "missing"} group={playerEntry?.Group ?? "missing"}");
        var playerInspectorInstance = session.ProjectEditorRegistry.CreateExtension(
            ProjectEditorExtensionKind.Inspector,
            "player-controller");
        var contentDockInstance = session.ProjectEditorRegistry.CreateExtension(
            ProjectEditorExtensionKind.Dock,
            "project-content-status");
        var resourceDockInstance = session.ProjectEditorRegistry.CreateExtension(
            ProjectEditorExtensionKind.Dock,
            "project-resource-editor");
        var viewportToolInstance = session.ProjectEditorRegistry.CreateExtension(
            ProjectEditorExtensionKind.ViewportTool,
            "project-viewport-status");
        Check(
            "项目 Inspector、Dock 和视口工具可实例化",
            playerInspectorInstance is IProjectEditorInspectorProvider &&
            contentDockInstance is IProjectEditorDock &&
            resourceDockInstance is IProjectEditorDock &&
            viewportToolInstance is IProjectEditorViewportTool,
            $"inspector={playerInspectorInstance.GetType().Name} dock={contentDockInstance.GetType().Name} resource={resourceDockInstance.GetType().Name} viewport={viewportToolInstance.GetType().Name}");
        if (contentDockInstance is IProjectEditorDock contentDock)
        {
            var dockContext = new RecordingProjectEditorUiContext();
            contentDock.Draw(session.Tree.Root, dockContext);
            Check(
                "项目内容 Dock 提供刷新按钮并展示校验结果",
                dockContext.ButtonLabels.Contains("刷新内容校验", StringComparer.Ordinal) &&
                dockContext.Texts.Any(text => text.StartsWith("内容校验: 通过", StringComparison.Ordinal)),
                string.Join(" | ", dockContext.Texts));
        }
        if (resourceDockInstance is IProjectEditorDock resourceDock)
        {
            var resourceContext = new RecordingProjectEditorUiContext
            {
                ButtonHandler = label => label == "选择 my_first:water",
            };
            resourceDock.Draw(session.Tree.Root, resourceContext);
            Check(
                "项目资源 Dock 浏览方块、物品和模型资产",
                resourceContext.ButtonLabels.Contains("选择 my_first:water", StringComparer.Ordinal) &&
                resourceContext.InputTextLabels.Contains("名称", StringComparer.Ordinal) &&
                resourceContext.InputTextLabels.Contains("色调", StringComparer.Ordinal) &&
                resourceContext.Texts.Any(text => text.StartsWith("方块资源 14 个", StringComparison.Ordinal)) &&
                resourceContext.Texts.Any(text => text.StartsWith("项目物品资源 19 个", StringComparison.Ordinal)) &&
                resourceContext.Texts.Any(text => text.StartsWith("项目模型资源 24 个", StringComparison.Ordinal)) &&
                resourceContext.Texts.Any(text => text == "Key: my_first:water"),
                string.Join(" | ", resourceContext.Texts));
        }

        if (player is not null)
        {
            var cameraPathProperty = player.GetType().GetProperty("CameraPath");
            var playerGroups = session.ProjectEditorRegistry.GetPropertyGroups(player.GetType());
            var validPathDiagnostic = cameraPathProperty is null
                ? "missing property"
                : Cubit.Editor.EditorNode.GetProjectNodeReferenceDiagnostic(
                    player,
                    cameraPathProperty,
                    playerGroups);
            Check(
                "项目 Inspector 接受已存在的节点路径",
                cameraPathProperty is not null && validPathDiagnostic is null,
                validPathDiagnostic ?? "valid");
            var originalCameraPath = player.GetType().GetProperty("CameraPath")?.GetValue(player) as string;
            player.GetType().GetProperty("CameraPath")?.SetValue(player, "/Root/Missing");
            var invalidPathDiagnostic = cameraPathProperty is null
                ? null
                : Cubit.Editor.EditorNode.GetProjectNodeReferenceDiagnostic(
                    player,
                    cameraPathProperty,
                    playerGroups);
            player.GetType().GetProperty("CameraPath")?.SetValue(player, originalCameraPath);
            Check(
                "项目 Inspector 拒绝不存在的节点路径",
                invalidPathDiagnostic?.Contains("/Root/Missing", StringComparison.Ordinal) == true,
                invalidPathDiagnostic ?? "missing diagnostic");
        }

        var editorNodePath = Path.Combine(repositoryRoot ?? "", "src", "Cubit.Editor", "EditorNode.cs");
        var editorNodeSource = File.Exists(editorNodePath) ? File.ReadAllText(editorNodePath) : string.Empty;
        Check(
            "Editor 消费项目编辑器 registry",
            editorNodeSource.Contains("ProjectEditorRegistry", StringComparison.Ordinal) &&
            editorNodeSource.Contains("ProjectEditorExtensionKind", StringComparison.Ordinal),
            editorNodePath);
    }
    catch (Exception exception)
    {
        Check("项目编辑器扩展会话加载", false, exception.Message);
    }

    Console.WriteLine(failures == 0
        ? "projecteditorextensioncheck 全部通过"
        : $"projecteditorextensioncheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectContentCheck()
{
    var failures = 0;
    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
    if (projectRoot is null || !Directory.Exists(projectRoot))
    {
        Check("首个项目可用于内容校验", false, projectRoot ?? "missing");
        return 1;
    }

    try
    {
        var result = ProjectContentValidator.Validate(projectRoot);
        Check("项目内容校验成功", result.Succeeded, string.Join("; ", result.Diagnostics));
        Check("校验发现全部项目方块定义", result.BlockDefinitionCount >= 14,
            $"blocks={result.BlockDefinitionCount}");
        Check("校验发现 water.json 且识别为流体", result.WaterDefinitionFound,
            $"water={result.WaterDefinitionFound}");
        Check("校验发现项目物品与模型目录", result.ItemDefinitionCount > 0 && result.ModelCount > 0,
            $"items={result.ItemDefinitionCount} models={result.ModelCount}");
        Check("校验不启动运行时服务", !result.RuntimeServicesStarted,
            $"runtime={result.RuntimeServicesStarted}");

        var fixtureRoot = Path.Combine(Path.GetTempPath(), $"cubit_project_content_{Guid.NewGuid():N}");
        try
        {
            var fixtureBlocks = Path.Combine(fixtureRoot, "assets", "voxel", "blocks", "my_first");
            Directory.CreateDirectory(fixtureBlocks);
            File.WriteAllText(
                Path.Combine(fixtureRoot, "assets", "voxel", "block-ids.json"),
                "{\"formatVersion\":1,\"firstProjectBlockId\":8,\"nextId\":9,\"blocks\":[{\"key\":\"my_first:broken\",\"id\":8}],\"reservedIds\":[]}");
            File.WriteAllText(
                Path.Combine(fixtureBlocks, "broken.json"),
                "{\"key\":\"my_first:broken\",\"name\":\"损坏\",\"topTexture\":\"missing\"}");
            var broken = ProjectContentValidator.Validate(fixtureRoot);
            Check("内容校验能拒绝缺失 water 定义的项目", !broken.Succeeded &&
                broken.Diagnostics.Any(diagnostic => diagnostic.Contains("my_first:water", StringComparison.Ordinal)),
                string.Join("; ", broken.Diagnostics));
        }
        finally
        {
            if (Directory.Exists(fixtureRoot))
            {
                Directory.Delete(fixtureRoot, recursive: true);
            }
        }
    }
    catch (Exception exception)
    {
        Check("项目内容校验可执行", false, exception.Message);
    }

    Console.WriteLine(failures == 0
        ? "projectcontentcheck 全部通过"
        : $"projectcontentcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectAssetCheck()
{
    var failures = 0;
    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var fixtureRoot = Path.Combine(Path.GetTempPath(), $"cubit_project_asset_{Guid.NewGuid():N}");
    try
    {
        var blockDirectory = Path.Combine(fixtureRoot, "assets", "voxel", "blocks", "my_first");
        Directory.CreateDirectory(blockDirectory);
        File.WriteAllText(
            Path.Combine(fixtureRoot, "assets", "voxel", "block-ids.json"),
            "{\"formatVersion\":1,\"firstProjectBlockId\":8,\"nextId\":9,\"blocks\":[{\"key\":\"my_first:granite\",\"id\":8}],\"reservedIds\":[]}");
        var definitionPath = Path.Combine(blockDirectory, "granite.json");
        File.WriteAllText(
            definitionPath,
            "{\n  \"key\": \"my_first:granite\",\n  \"name\": \"花岗岩\",\n  \"topTexture\": \"granite\",\n  \"sideTexture\": \"granite\",\n  \"bottomTexture\": \"granite\"\n}\n");

        var assets = ProjectBlockAssetEditor.Load(fixtureRoot);
        Check("项目资源编辑器按持久编号加载方块", assets.Count == 1 &&
            assets[0].Definition.Key == "my_first:granite" && assets[0].PersistentId == 8,
            $"count={assets.Count} id={(assets.Count == 0 ? 0 : assets[0].PersistentId)}");
        var saved = ProjectBlockAssetEditor.TrySave(
            fixtureRoot,
            "my_first:granite",
            "新花岗岩",
            "#aabbcc");
        var savedJson = File.ReadAllText(definitionPath);
        using var savedDocument = JsonDocument.Parse(savedJson);
        var savedObject = savedDocument.RootElement;
        var savedName = savedObject.TryGetProperty("name", out var savedNameProperty)
            ? savedNameProperty.GetString()
            : null;
        var savedTint = savedObject.TryGetProperty("tint", out var savedTintProperty)
            ? savedTintProperty.GetString()
            : null;
        Check("项目资源编辑器原子写回名称和色调", saved.Succeeded &&
            savedName == "新花岗岩" && savedTint == "#aabbcc",
            saved.Diagnostic ?? "saved");
        var metadata = ProjectMetadata.Open(fixtureRoot);
        var entry = metadata.GetRequired("assets/voxel/blocks/my_first/granite.json");
        var expectedHash = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(definitionPath))).ToLowerInvariant();
        Check("项目资源写回刷新 UID 哈希缓存", entry.ContentHash == expectedHash &&
            entry.Uid.StartsWith(ProjectMetadata.UidPrefix, StringComparison.Ordinal),
            $"uid={entry.Uid} hash={entry.ContentHash}");
        var rejected = ProjectBlockAssetEditor.TrySave(fixtureRoot, "my_first:missing", "不存在", "#ffffff");
        Check("项目资源编辑器拒绝未知方块 Key", !rejected.Succeeded &&
            rejected.Diagnostic?.Contains("my_first:missing", StringComparison.Ordinal) == true,
            rejected.Diagnostic ?? "missing diagnostic");

        var dockRoot = Path.Combine(Path.GetTempPath(), $"cubit_project_resource_dock_{Guid.NewGuid():N}");
        try
        {
            var dockProject = ProjectIO.Create(dockRoot, "资源面板验收");
            var dockBlocks = Path.Combine(dockRoot, "assets", "voxel", "blocks", "my_first");
            Directory.CreateDirectory(dockBlocks);
            File.WriteAllText(
                Path.Combine(dockRoot, "assets", "voxel", "block-ids.json"),
                "{\"formatVersion\":1,\"firstProjectBlockId\":8,\"nextId\":9,\"blocks\":[{\"key\":\"my_first:granite\",\"id\":8}],\"reservedIds\":[]}");
            var dockDefinitionPath = Path.Combine(dockBlocks, "granite.json");
            File.WriteAllText(
                dockDefinitionPath,
                "{\"key\":\"my_first:granite\",\"name\":\"花岗岩\",\"tint\":\"#ffffff\"}\n");
            dockProject.Metadata.Refresh();
            var dockType = typeof(RuntimeBootstrap).Assembly.GetType(
                "MyFirstCubitProject.ProjectEditorExtensions+ProjectResourceEditorDock")
                ?? throw new InvalidOperationException("找不到项目资源 Dock 类型");
            var dock = Activator.CreateInstance(
                dockType,
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                binder: null,
                args: [dockProject],
                culture: null) as IProjectEditorDock
                ?? throw new InvalidOperationException("无法创建项目资源 Dock");
            var dockRootNode = new Node { Name = "Root" };
            dock.Draw(
                dockRootNode,
                new RecordingProjectEditorUiContext
                {
                    ButtonHandler = label => label == "选择 my_first:granite",
                });
            dock.Draw(
                dockRootNode,
                new RecordingProjectEditorUiContext
                {
                    ButtonHandler = label => label == "保存方块资源",
                    InputTextHandler = (label, current) => label switch
                    {
                        "名称" => "编辑花岗岩",
                        "色调" => "#123456",
                        _ => current,
                    },
                });
            var afterSave = ReadJsonObject(dockDefinitionPath);
            dock.Draw(
                dockRootNode,
                new RecordingProjectEditorUiContext
                {
                    ButtonHandler = label => label == "撤销资源修改",
                });
            var afterUndo = ReadJsonObject(dockDefinitionPath);
            dock.Draw(
                dockRootNode,
                new RecordingProjectEditorUiContext
                {
                    ButtonHandler = label => label == "重做资源修改",
                });
            var afterRedo = ReadJsonObject(dockDefinitionPath);
            Check("项目资源 Dock 保存支持撤销和重做", 
                afterSave.GetProperty("name").GetString() == "编辑花岗岩" &&
                afterSave.GetProperty("tint").GetString() == "#123456" &&
                afterUndo.GetProperty("name").GetString() == "花岗岩" &&
                afterUndo.GetProperty("tint").GetString() == "#ffffff" &&
                afterRedo.GetProperty("name").GetString() == "编辑花岗岩" &&
                afterRedo.GetProperty("tint").GetString() == "#123456");
        }
        finally
        {
            if (Directory.Exists(dockRoot))
            {
                Directory.Delete(dockRoot, recursive: true);
            }
        }

        static JsonElement ReadJsonObject(string path)
        {
            using var document = JsonDocument.Parse(File.ReadAllText(path));
            return document.RootElement.Clone();
        }
    }
    catch (Exception exception)
    {
        Check("项目资源编辑器验收可执行", false, exception.Message);
    }
    finally
    {
        if (Directory.Exists(fixtureRoot))
        {
            Directory.Delete(fixtureRoot, recursive: true);
        }
    }

    Console.WriteLine(failures == 0
        ? "projectassetcheck 全部通过"
        : $"projectassetcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int EditorMcpCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var editorAssembly = typeof(Cubit.Editor.EditorNode).Assembly;
    var hostType = editorAssembly.GetType("Cubit.Editor.Mcp.EditorMcpHost");
    Check(
        "Editor 提供独立 MCP 宿主",
        hostType is not null && typeof(IMcpEngineHost).IsAssignableFrom(hostType) &&
        typeof(IMcpExtensionProvider).IsAssignableFrom(hostType) &&
        typeof(IMcpRequestDispatcher).IsAssignableFrom(hostType),
        hostType?.FullName ?? "missing");

    var projectRoot = Path.Combine(Path.GetTempPath(), $"cubit_editor_mcp_{Guid.NewGuid():N}");
    var voxelProjectRoot = Path.Combine(Path.GetTempPath(), $"cubit_editor_mcp_voxel_{Guid.NewGuid():N}");
    try
    {
        var project = ProjectIO.Create(projectRoot, "Editor MCP 验收");
        var previewDirectory = Path.Combine(projectRoot, "preview");
        Directory.CreateDirectory(previewDirectory);
        File.Copy(typeof(EditorPreviewProbe).Assembly.Location, Path.Combine(previewDirectory, "Cubit.Tool.dll"));
        File.WriteAllText(project.ManifestPath, """
        {
          "formatVersion": 1,
          "name": "Editor MCP 验收",
          "mainScene": "scenes/main.cscene",
          "preview": {
            "assembly": "preview/Cubit.Tool.dll",
            "type": "EditorPreviewProbe"
          },
          "plugins": [
            { "id": "cubit.physics", "version": "1.0.0" },
            { "id": "cubit.animation", "version": "1.0.0" },
            { "id": "cubit.audio", "version": "1.0.0" },
            { "id": "cubit.content", "version": "1.0.0" },
            { "id": "cubit.scripting", "version": "1.0.0" }
          ]
        }
        """);
        File.WriteAllText(project.MainScenePath, SceneIO.WithDocumentUid("""
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Root",
          "Properties": null,
          "Children": [
            { "Type": "Cubit.Physics.Scene.PhysicsWorld3D", "Name": "Physics", "Properties": null, "Children": null },
            { "Type": "Cubit.Animation.AnimationPlayer", "Name": "Animation", "Properties": null, "Children": null },
            { "Type": "Cubit.Core.Scene.EcsNode", "Name": "Ecs", "Properties": null, "Children": null },
            { "Type": "Cubit.Core.Scene.BoxMesh3D", "Name": "Box", "Properties": null, "Children": null },
            {
              "Type": "Cubit.Scripting.ScriptAttachmentNode",
              "Name": "ScriptAttachment",
              "Properties": {
                "Attachment": {
                  "TargetPath": { "Value": "/Root/Box" },
                  "TypeName": "ScriptingProbe",
                  "PropertyOverrides": { "ExportedValue": 17 }
                }
              },
              "Children": null
            }
          ]
        }
        """, project.SceneCatalog.MainScene.Uid));

        using var session = new ProjectSceneSession(new FakeRenderBackend(), projectRoot);
        using var editorHost = new EditorMcpHost(
            () => session,
            _ => throw new InvalidOperationException("验收中不允许切换项目"),
            vulkan: null!);
        using var transport = new McpHttpServer(editorHost);
        using var http = new HttpClient { BaseAddress = new Uri($"http://127.0.0.1:{transport.Port}/") };

        var authoringTools = McpToolNames(PostEditorMcpJson(http, editorHost, "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/list\"}"));
        Check(
            "Editor 作者态只公开场景与预览控制，不泄露运行模块工具",
            authoringTools.Contains("editor.preview.start") &&
            !authoringTools.Contains("physics.list_worlds") &&
            !authoringTools.Contains("audio.status") &&
            !authoringTools.Contains("content.import") &&
            !authoringTools.Contains("scripting.status"),
            $"tools={string.Join(',', authoringTools.OrderBy(name => name, StringComparer.Ordinal))}");

        var startResponse = PostEditorMcpJson(http, editorHost, "{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/call\",\"params\":{\"name\":\"editor.preview.start\",\"arguments\":{}}}");
        var startText = McpToolText(startResponse);
        var previewTools = McpToolNames(PostEditorMcpJson(http, editorHost, "{\"jsonrpc\":\"2.0\",\"id\":3,\"method\":\"tools/list\"}"));
        var expectedPreviewTools = new[]
        {
            "physics.list_worlds", "animation.list_players", "audio.status", "content.import", "scripting.status", "ecs.list_nodes",
        };
        Check(
            "Editor 预览后通过 HTTP 公开已注入官方模块工具",
            startText.Contains("\"previewing\":true", StringComparison.Ordinal) && session.IsPreviewing &&
            expectedPreviewTools.All(previewTools.Contains),
            $"previewing={session.IsPreviewing} missing={string.Join(',', expectedPreviewTools.Where(name => !previewTools.Contains(name)))}");

        var stopResponse = PostEditorMcpJson(http, editorHost, "{\"jsonrpc\":\"2.0\",\"id\":4,\"method\":\"tools/call\",\"params\":{\"name\":\"editor.preview.stop\",\"arguments\":{}}}");
        var stopText = McpToolText(stopResponse);
        var restoredTools = McpToolNames(PostEditorMcpJson(http, editorHost, "{\"jsonrpc\":\"2.0\",\"id\":5,\"method\":\"tools/list\"}"));
        Check(
            "Editor 停止预览后释放服务并隐藏官方模块工具",
            stopText.Contains("\"previewing\":false", StringComparison.Ordinal) && !session.IsPreviewing && session.Tree.Paused &&
            expectedPreviewTools.All(name => !restoredTools.Contains(name)),
            $"previewing={session.IsPreviewing} paused={session.Tree.Paused}");

        var voxelProject = ProjectIO.Create(voxelProjectRoot, "Editor MCP Voxel 验收");
        var voxelPreviewDirectory = Path.Combine(voxelProjectRoot, "preview");
        Directory.CreateDirectory(voxelPreviewDirectory);
        File.Copy(typeof(EditorPreviewProbe).Assembly.Location, Path.Combine(voxelPreviewDirectory, "Cubit.Tool.dll"));
        File.WriteAllText(voxelProject.ManifestPath, """
        {
          "formatVersion": 1,
          "name": "Editor MCP Voxel 验收",
          "mainScene": "scenes/main.cscene",
          "preview": {
            "assembly": "preview/Cubit.Tool.dll",
            "type": "EditorPreviewProbe"
          },
          "plugins": [
            { "id": "cubit.voxel", "version": "1.0.0" },
            { "id": "cubit.audio", "version": "1.0.0" }
          ]
        }
        """);
        File.WriteAllText(voxelProject.MainScenePath, """
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Root",
          "Properties": null,
          "Children": [
            {
              "Type": "Cubit.Voxel.World.VoxelWorldNode",
              "Name": "World",
              "Properties": { "WorldType": 1, "GenerateRadius": 0 },
              "Children": null
            },
            { "Type": "Cubit.Core.Scene.Camera3D", "Name": "Camera", "Properties": null, "Children": null }
          ]
        }
        """);

        using (var voxelSession = new ProjectSceneSession(new FakeRenderBackend(), voxelProjectRoot))
        using (var voxelHost = new EditorMcpHost(
                   () => voxelSession,
                   _ => throw new InvalidOperationException("验收中不允许切换项目"),
                   vulkan: null!))
        using (var voxelTransport = new McpHttpServer(voxelHost))
        using (var voxelHttp = new HttpClient { BaseAddress = new Uri($"http://127.0.0.1:{voxelTransport.Port}/") })
        {
            var voxelAuthoringTools = McpToolNames(PostEditorMcpJson(voxelHttp, voxelHost, "{\"jsonrpc\":\"2.0\",\"id\":6,\"method\":\"tools/list\"}"));
            var voxelStart = PostEditorMcpJson(voxelHttp, voxelHost, "{\"jsonrpc\":\"2.0\",\"id\":7,\"method\":\"tools/call\",\"params\":{\"name\":\"editor.preview.start\",\"arguments\":{}}}");
            var voxelPreviewTools = McpToolNames(PostEditorMcpJson(voxelHttp, voxelHost, "{\"jsonrpc\":\"2.0\",\"id\":8,\"method\":\"tools/list\"}"));
            var voxelStop = PostEditorMcpJson(voxelHttp, voxelHost, "{\"jsonrpc\":\"2.0\",\"id\":9,\"method\":\"tools/call\",\"params\":{\"name\":\"editor.preview.stop\",\"arguments\":{}}}");
            var voxelRestoredTools = McpToolNames(PostEditorMcpJson(voxelHttp, voxelHost, "{\"jsonrpc\":\"2.0\",\"id\":10,\"method\":\"tools/list\"}"));
            Check(
                "Editor 体素项目在作者态不泄露清单内运行工具",
                !voxelAuthoringTools.Contains("world.get_block") && !voxelAuthoringTools.Contains("audio.status"));
            Check(
                "Editor 体素预览只公开 Voxel 和 Audio adapter",
                McpToolText(voxelStart).Contains("\"previewing\":true", StringComparison.Ordinal) &&
                voxelPreviewTools.Contains("world.get_block") &&
                voxelPreviewTools.Contains("audio.status") &&
                !voxelPreviewTools.Contains("physics.list_worlds") &&
                !voxelPreviewTools.Contains("animation.list_players") &&
                !voxelPreviewTools.Contains("content.import") &&
                !voxelPreviewTools.Contains("scripting.status") &&
                !voxelPreviewTools.Contains("input.set_break"),
                $"tools={string.Join(',', voxelPreviewTools.OrderBy(name => name, StringComparer.Ordinal))}");
            Check(
                "Editor 体素预览停止后立即撤销 Voxel 和 Audio adapter",
                McpToolText(voxelStop).Contains("\"previewing\":false", StringComparison.Ordinal) &&
                !voxelRestoredTools.Contains("world.get_block") &&
                !voxelRestoredTools.Contains("audio.status"));
        }

        var launchOptions = Cubit.Editor.EditorLaunchOptions.Parse(["--project", projectRoot, "--mcp-http", "0"]);
        Check(
            "Editor 启动参数支持本地 MCP HTTP 与项目同时指定",
            launchOptions.ProjectPath == projectRoot && !launchOptions.McpStdio && launchOptions.McpHttpPort == 0 && launchOptions.Error is null,
            $"project={launchOptions.ProjectPath} stdio={launchOptions.McpStdio} port={launchOptions.McpHttpPort} error={launchOptions.Error}");
    }
    finally
    {
        if (Directory.Exists(projectRoot))
        {
            Directory.Delete(projectRoot, recursive: true);
        }

        if (Directory.Exists(voxelProjectRoot))
        {
            Directory.Delete(voxelProjectRoot, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "editormcpcheck 全部通过" : $"editormcpcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static HashSet<string> McpToolNames(string response)
{
    using var document = JsonDocument.Parse(response);
    return document.RootElement
        .GetProperty("result")
        .GetProperty("tools")
        .EnumerateArray()
        .Select(tool => tool.GetProperty("name").GetString())
        .Where(name => !string.IsNullOrWhiteSpace(name))
        .Cast<string>()
        .ToHashSet(StringComparer.Ordinal);
}

static string McpToolText(string response)
{
    using var document = JsonDocument.Parse(response);
    return document.RootElement
        .GetProperty("result")
        .GetProperty("content")[0]
        .GetProperty("text")
        .GetString() ?? "";
}

static string PostEditorMcpJson(HttpClient http, EditorMcpHost host, string json)
{
    using var response = WaitForEditorMcpTask(
        http.PostAsync("/mcp", new StringContent(json, System.Text.Encoding.UTF8, "application/json")),
        host);
    return WaitForEditorMcpTask(response.Content.ReadAsStringAsync(), host);
}

static T WaitForEditorMcpTask<T>(Task<T> task, EditorMcpHost host)
{
    var deadline = DateTime.UtcNow.AddSeconds(3);
    while (!task.IsCompleted)
    {
        host.PumpMcpRequests();
        if (DateTime.UtcNow >= deadline)
        {
            throw new TimeoutException("Editor MCP HTTP 验收等待响应超时");
        }

        Thread.Sleep(1);
    }

    host.PumpMcpRequests();
    return task.GetAwaiter().GetResult();
}

static int EditorPreviewCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var core = typeof(Node).Assembly;
    var previewReference = core.GetType("Cubit.Core.Project.CubitProjectPreviewReference");
    var bootstrap = core.GetType("Cubit.Core.Project.IProjectPreviewBootstrap");
    var context = core.GetType("Cubit.Core.Project.ProjectPreviewContext");
    Check(
        "Core 项目预览契约类型齐全",
        previewReference is not null && bootstrap is not null && context is not null,
        $"reference={previewReference is not null} bootstrap={bootstrap is not null} context={context is not null}");
    var forbiddenCoreReferences = core.GetReferencedAssemblies()
        .Select(reference => reference.Name)
        .Where(name => name is not null &&
            (name.StartsWith("Cubit.Editor", StringComparison.Ordinal) ||
             name.StartsWith("Cubit.Voxel", StringComparison.Ordinal) ||
             name.StartsWith("Cubit.Sample", StringComparison.Ordinal)))
        .ToArray();
    Check("Core 预览契约不反向引用 Editor 或领域程序集", forbiddenCoreReferences.Length == 0,
        string.Join(',', forbiddenCoreReferences));

    var sessionType = typeof(ProjectSceneSession);
    var members = new[] { "CanStartPreview", "IsPreviewing", "StartPreview", "StopPreview" };
    var missing = members.Where(member => sessionType.GetMember(member).Length == 0).ToArray();
    Check("编辑器项目会话公开显式预览入口", missing.Length == 0, string.Join(',', missing));

    var root = Path.Combine(Path.GetTempPath(), $"cubit_editor_preview_{Guid.NewGuid():N}");
    try
    {
        var project = ProjectIO.Create(root, "预览清单校验");
        File.WriteAllText(project.ManifestPath, """
        {
          "formatVersion": 1,
          "name": "预览清单校验",
          "mainScene": "scenes/main.cscene",
          "preview": { "assembly": "bin/Game.dll" }
        }
        """);
        Check(
            "项目清单拒绝半配置预览声明",
            CaptureException(() => ProjectIO.Load(root)) is InvalidDataException);
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, true);
        }
    }

    var missingAssemblyProjectRoot = Path.Combine(Path.GetTempPath(), $"cubit_editor_preview_missing_{Guid.NewGuid():N}");
    try
    {
        var project = ProjectIO.Create(missingAssemblyProjectRoot, "缺失预览程序集校验");
        File.WriteAllText(project.ManifestPath, """
        {
          "formatVersion": 1,
          "name": "缺失预览程序集校验",
          "mainScene": "scenes/main.cscene",
          "preview": {
            "assembly": "preview/Missing.dll",
            "type": "EditorPreviewProbe"
          }
        }
        """);
        EditorPreviewProbe.Reset();
        using var session = new ProjectSceneSession(new FakeRenderBackend(), missingAssemblyProjectRoot);
        var error = CaptureException(session.StartPreview);
        Check(
            "缺失预览程序集保留作者场景且不执行代码",
            error is FileNotFoundException && !session.IsPreviewing && session.Tree.Paused &&
            session.Tree.Root.Children.Count == 0 && EditorPreviewProbe.ConfigureCalls == 0,
            error?.Message ?? "未抛出异常");
    }
    finally
    {
        if (Directory.Exists(missingAssemblyProjectRoot))
        {
            Directory.Delete(missingAssemblyProjectRoot, true);
        }
    }

    var previewProjectRoot = Path.Combine(Path.GetTempPath(), $"cubit_editor_preview_runtime_{Guid.NewGuid():N}");
    try
    {
        var project = ProjectIO.Create(previewProjectRoot, "预览运行时校验");
        var previewDirectory = Path.Combine(previewProjectRoot, "preview");
        Directory.CreateDirectory(previewDirectory);
        var probeAssemblyPath = typeof(EditorPreviewProbe).Assembly.Location;
        File.Copy(probeAssemblyPath, Path.Combine(previewDirectory, "Cubit.Tool.dll"));
        File.WriteAllText(project.ManifestPath, """
        {
          "formatVersion": 1,
          "name": "预览运行时校验",
          "mainScene": "scenes/main.cscene",
          "preview": {
            "assembly": "preview/Cubit.Tool.dll",
            "type": "EditorPreviewProbe"
          }
        }
        """);

        EditorPreviewProbe.Reset();
        var renderer = new FakeRenderBackend();
        using var session = new ProjectSceneSession(renderer, previewProjectRoot);
        Check(
            "打开项目不执行预览引导器",
            session.CanStartPreview && !session.IsPreviewing && session.Tree.Paused && EditorPreviewProbe.ConfigureCalls == 0,
            $"canStart={session.CanStartPreview} previewing={session.IsPreviewing} calls={EditorPreviewProbe.ConfigureCalls}");

        session.StartPreview();
        var previewEcs = session.Tree.GetNode("/Root/PreviewEcs") as EcsNode;
        Check(
            "显式预览在入树前配置 ECS 与通用网格",
            session.IsPreviewing && !session.Tree.Paused &&
            previewEcs is { IsInitialized: true, Jobs: not null } &&
            previewEcs.World.EntityCount == 1 &&
            session.Tree.GetNode("/Root/PreviewAnchor") is BoxMesh3D && renderer.MeshUploadCount >= 1,
            $"previewing={session.IsPreviewing} ecs={previewEcs?.IsInitialized} entities={previewEcs?.World.EntityCount} uploads={renderer.MeshUploadCount}");

        session.ProcessFrame(session.Tree.PhysicsDelta);
        var previewQuery = previewEcs?.World.Query<Vector3>();
        var previewPosition = default(Vector3);
        if (previewQuery is { Count: 1 } query)
        {
            var enumerator = query.GetEnumerator();
            if (enumerator.MoveNext())
            {
                previewPosition = enumerator.Current.Component;
            }
        }
        Check("预览 ECS System 由会话共享 JobSystem 驱动", previewQuery is { Count: 1 } && previewPosition.X == 1f,
            $"entities={previewEcs?.World.EntityCount} count={previewQuery?.Count} x={previewPosition.X}");
        Check("预览运行时拒绝保存作者场景", CaptureException(session.Save) is InvalidOperationException);

        session.StopPreview();
        Check(
            "停止预览恢复暂停的作者场景",
            !session.IsPreviewing && session.Tree.Paused && session.Tree.GetNode("/Root/PreviewEcs") is null &&
            session.Tree.Root.Children.Count == 0,
            $"previewing={session.IsPreviewing} previewEcs={session.Tree.GetNode("/Root/PreviewEcs") is not null}");
    }
    finally
    {
        if (Directory.Exists(previewProjectRoot))
        {
            Directory.Delete(previewProjectRoot, true);
        }
    }

    var cubitRoot = FindCubitRepositoryRoot();
    var ecsProjectRoot = cubitRoot is null
        ? null
        : Path.Combine(Directory.GetParent(cubitRoot)?.FullName ?? "", "通用3D-ECS示例项目");
    if (ecsProjectRoot is null || !File.Exists(Path.Combine(ecsProjectRoot, ProjectIO.ManifestFileName)))
    {
        Check("Core-only ECS 示例可由编辑器显式预览", false, ecsProjectRoot ?? "未找到 Cubit 根目录");
    }
    else
    {
        var renderer = new FakeRenderBackend();
        using var session = new ProjectSceneSession(renderer, ecsProjectRoot);
        var authoredEcs = session.Tree.GetNode("/Root/SwarmEcs") as EcsNode;
        var authoringState = !session.IsPreviewing && session.HasCamera && authoredEcs is { IsInitialized: true } &&
            authoredEcs.World.EntityCount == 0;
        session.StartPreview();
        var previewEcs = session.Tree.GetNode("/Root/SwarmEcs") as EcsNode;
        session.ProcessFrame(session.Tree.PhysicsDelta);
        var previewState = session.IsPreviewing && !session.Tree.Paused && session.HasCamera &&
            previewEcs is { IsInitialized: true, Jobs: not null } && previewEcs.World.EntityCount == 4096 &&
            renderer.MeshUploadCount >= 1;
        session.StopPreview();
        var restoredEcs = session.Tree.GetNode("/Root/SwarmEcs") as EcsNode;
        Check(
            "Core-only ECS 示例可由编辑器显式预览",
            authoringState && previewState &&
            !session.IsPreviewing && session.Tree.Paused && session.HasCamera && restoredEcs is { IsInitialized: true } &&
            restoredEcs.World.EntityCount == 0,
            $"authoring={authoringState} preview={previewState} previewEntities={previewEcs?.World.EntityCount} uploads={renderer.MeshUploadCount} restored={restoredEcs?.World.EntityCount} camera={session.HasCamera}");
    }

    Console.WriteLine(failures == 0 ? "editorpreviewcheck 全部通过" : $"editorpreviewcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int PartitionCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var core = typeof(Node).Assembly;
    var cell = core.GetType("Cubit.Core.Spatial.PartitionCell");
    var extent = core.GetType("Cubit.Core.Spatial.PartitionExtent");
    var ticket = core.GetType("Cubit.Core.Spatial.PartitionTicket");
    var kind = core.GetType("Cubit.Core.Spatial.PartitionChangeKind");
    var change = core.GetType("Cubit.Core.Spatial.PartitionChange");
    var partition = core.GetType("Cubit.Core.Spatial.WorldPartition");
    Check(
        "Core WorldPartition API 类型齐全",
        cell is not null && extent is not null && ticket is not null && kind is not null &&
        change is not null && partition is not null,
        $"cell={cell is not null} extent={extent is not null} ticket={ticket is not null} " +
        $"kind={kind is not null} change={change is not null} partition={partition is not null}");

    var partitionInstance = new WorldPartition(new Vector3(10f, 20f, 30f));
    var negativeCell = partitionInstance.ToCell(new Vector3(-0.01f, -20f, -30.01f));
    var negativeBounds = partitionInstance.GetCellBounds(new PartitionCell(-1, -1, -1));
    Check(
        "WorldPartition 负坐标按 Floor 映射",
        negativeCell == new PartitionCell(-1, -1, -2),
        $"cell={negativeCell}");
    Check(
        "WorldPartition 返回精确 cell AABB",
        negativeBounds.Min == new Vector3(-10f, -20f, -30f) && negativeBounds.Max == Vector3.Zero,
        $"min={negativeBounds.Min} max={negativeBounds.Max}");
    Check(
        "WorldPartition 拒绝非法尺寸和范围",
        CaptureException(() => new WorldPartition(new Vector3(0f, 1f, 1f))) is ArgumentOutOfRangeException &&
        CaptureException(() => partitionInstance.Refresh(
            Vector3.Zero,
            new PartitionExtent(-1, 0, 0),
            new List<PartitionChange>())) is ArgumentOutOfRangeException);
    Check(
        "WorldPartition 拒绝无界目标容量",
        CaptureException(() => partitionInstance.Refresh(
            Vector3.Zero,
            new PartitionExtent(1000, 1000, 0),
            new List<PartitionChange>())) is ArgumentOutOfRangeException);

    var lifecycle = new WorldPartition(Vector3.One);
    var lifecycleChanges = new List<PartitionChange>();
    var firstCount = lifecycle.Refresh(Vector3.Zero, new PartitionExtent(1, 0, 0), lifecycleChanges);
    var firstEnters = lifecycleChanges.Where(change => change.Kind == PartitionChangeKind.Enter).ToArray();
    Check(
        "首次刷新按近到远输出完整 Enter",
        firstCount == 3 && firstEnters.Select(change => change.Ticket.Cell).SequenceEqual(
        [
            new PartitionCell(0, 0, 0),
            new PartitionCell(-1, 0, 0),
            new PartitionCell(1, 0, 0),
        ]),
        string.Join(',', firstEnters.Select(change => $"{change.Ticket.Cell}:{change.DistanceSquared}")));
    var originalCenterTicket = firstEnters.Single(change => change.Ticket.Cell == new PartitionCell(0, 0, 0)).Ticket;

    lifecycleChanges.Clear();
    Check(
        "相同刷新没有变更",
        lifecycle.Refresh(Vector3.Zero, new PartitionExtent(1, 0, 0), lifecycleChanges) == 0 && lifecycleChanges.Count == 0);

    lifecycleChanges.Clear();
    var movedCount = lifecycle.Refresh(new Vector3(2f, 0f, 0f), new PartitionExtent(0), lifecycleChanges);
    Check(
        "移动焦点输出 Enter 与远到近 Exit",
        movedCount == 4 && lifecycleChanges.Select(change => change.Kind).SequenceEqual(
        [
            PartitionChangeKind.Enter,
            PartitionChangeKind.Exit,
            PartitionChangeKind.Exit,
            PartitionChangeKind.Exit,
        ]) &&
        lifecycleChanges.Skip(1).Select(change => change.Ticket.Cell).SequenceEqual(
        [
            new PartitionCell(-1, 0, 0),
            new PartitionCell(0, 0, 0),
            new PartitionCell(1, 0, 0),
        ]),
        string.Join(',', lifecycleChanges.Select(change => $"{change.Kind}:{change.Ticket.Cell}:{change.DistanceSquared}")));
    Check("退出立即使 ticket 失效", !lifecycle.IsCurrent(originalCenterTicket));

    lifecycleChanges.Clear();
    _ = lifecycle.Refresh(Vector3.Zero, new PartitionExtent(0), lifecycleChanges);
    var replacementCenterTicket = lifecycleChanges.Single(change => change.Kind == PartitionChangeKind.Enter).Ticket;
    Check(
        "重新进入分区获得新 generation",
        replacementCenterTicket.Cell == originalCenterTicket.Cell &&
        replacementCenterTicket.Generation != originalCenterTicket.Generation &&
        !lifecycle.IsCurrent(originalCenterTicket) && lifecycle.IsCurrent(replacementCenterTicket),
        $"old={originalCenterTicket} new={replacementCenterTicket}");

    lifecycleChanges.Clear();
    Check(
        "Clear 稳定退出并使 ticket 失效",
        lifecycle.Clear(lifecycleChanges) == 1 &&
        lifecycleChanges is [{ Kind: PartitionChangeKind.Exit, Ticket.Cell: { X: 0, Y: 0, Z: 0 } }] &&
        lifecycle.DesiredCount == 0 && !lifecycle.IsCurrent(replacementCenterTicket));

    var threadError = CaptureException(() =>
        Task.Run(() => lifecycle.IsCurrent(replacementCenterTicket)).GetAwaiter().GetResult());
    Check(
        "WorldPartition 拒绝后台线程状态访问",
        threadError is InvalidOperationException,
        threadError?.Message ?? "");

    var repositoryRoot = FindCubitRepositoryRoot();
    var partitionSource = repositoryRoot is null
        ? string.Empty
        : File.ReadAllText(Path.Combine(repositoryRoot, "src", "Cubit.Core", "Spatial", "WorldPartition.cs"));
    var forbiddenTerms = new[] { "Voxel", "Chunk", "Node", "Entity", "RID", "Mesh", "JobSystem", "Schedule", "Task.Run" }
        .Where(term => partitionSource.Contains(term, StringComparison.Ordinal))
        .ToArray();
    var invalidConstructorParameter = typeof(WorldPartition)
        .GetConstructors()
        .SelectMany(constructor => constructor.GetParameters())
        .Any(parameter => typeof(Delegate).IsAssignableFrom(parameter.ParameterType) ||
                          parameter.ParameterType == typeof(JobSystem));
    Check(
        "WorldPartition 保持 Core 分区意图边界",
        !string.IsNullOrEmpty(partitionSource) && forbiddenTerms.Length == 0 && !invalidConstructorParameter,
        $"forbidden={string.Join(',', forbiddenTerms)} callbackOrJobs={invalidConstructorParameter}");

    Console.WriteLine(failures == 0 ? "partitioncheck 全部通过" : $"partitioncheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int SpatialCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var core = typeof(Node).Assembly;
    var aabb = core.GetType("Cubit.Core.Spatial.Aabb3");
    var tree = core.GetType("Cubit.Core.Spatial.DynamicAabbTree`1");
    var handle = core.GetType("Cubit.Core.Spatial.SpatialHandle");
    var staticItem = core.GetType("Cubit.Core.Spatial.StaticBvhItem`1");
    var staticTree = core.GetType("Cubit.Core.Spatial.StaticBvh`1");
    var staticQueryHit = core.GetType("Cubit.Core.Spatial.StaticBvhQueryHit`1");
    var staticRayHitType = core.GetType("Cubit.Core.Spatial.StaticBvhRayHit`1");
    Check("Core Spatial API 类型齐全", aabb is not null && tree is not null && handle is not null,
        $"aabb={aabb is not null} tree={tree is not null} handle={handle is not null}");

    Check(
        "Core Static BVH API types exist",
        staticItem is not null && staticTree is not null && staticQueryHit is not null && staticRayHitType is not null,
        $"item={staticItem is not null} tree={staticTree is not null} query={staticQueryHit is not null} ray={staticRayHitType is not null}");

    var unit = new Aabb3(Vector3.Zero, Vector3.One);
    var overlap = new Aabb3(new Vector3(0.5f), new Vector3(1.5f));
    var disjoint = new Aabb3(new Vector3(2f), new Vector3(3f));
    Check("Aabb3 范围相交与包含", unit.Intersects(overlap) && !unit.Intersects(disjoint) &&
        unit.Contains(new Aabb3(new Vector3(0.25f), new Vector3(0.75f))));
    Check("Aabb3 射线命中距离正确", unit.Raycast(new Vector3(-2f, 0.5f, 0.5f), Vector3.UnitX, 8f, out var unitDistance) &&
        MathF.Abs(unitDistance - 2f) < 0.0001f, $"distance={unitDistance}");
    Check("Aabb3 拒绝非法范围", CaptureException(() => new Aabb3(Vector3.One, Vector3.Zero)) is ArgumentException);
    Check("空间索引拒绝非法 margin 与射线", CaptureException(() => new DynamicAabbTree<string>(-0.1f)) is ArgumentOutOfRangeException &&
        CaptureException(() => unit.Raycast(Vector3.Zero, Vector3.Zero, 1f, out _)) is ArgumentException);

    var staticItems = new List<StaticBvhItem<string>>
    {
        new("left", new Aabb3(new Vector3(-3f, 0f, 0f), new Vector3(-2f, 1f, 1f))),
        new("visible", new Aabb3(new Vector3(0.25f), new Vector3(0.75f))),
        new("far", new Aabb3(new Vector3(6f, 0f, 0f), new Vector3(7f, 1f, 1f))),
        new("tie-first", new Aabb3(new Vector3(2f, 0f, 0f), new Vector3(3f, 1f, 1f))),
        new("tie-second", new Aabb3(new Vector3(2f, 0f, 0f), new Vector3(3f, 1f, 1f))),
    };
    var staticBvh = new StaticBvh<string>(staticItems, maxLeafItems: 1);
    staticItems[0] = new StaticBvhItem<string>("moved", new Aabb3(new Vector3(20f), new Vector3(21f)));
    var staticSnapshotHits = new List<StaticBvhQueryHit<string>>();
    var staticSnapshotCount = staticBvh.Query(new Aabb3(new Vector3(-4f, -1f, -1f), new Vector3(-1f, 2f, 2f)), staticSnapshotHits);
    Check(
        "Static BVH snapshots caller items",
        staticSnapshotCount == 1 && staticSnapshotHits is [{ Index: 0, Value: "left" }],
        string.Join(',', staticSnapshotHits.Select(hit => $"{hit.Index}:{hit.Value}")));

    var staticRangeHits = new List<StaticBvhQueryHit<string>>();
    var staticRangeCount = staticBvh.Query(new Aabb3(new Vector3(1.5f, -1f, -1f), new Vector3(3.5f, 2f, 2f)), staticRangeHits);
    Check(
        "Static BVH range query returns actual leaf bounds",
        staticRangeCount == 2 && staticRangeHits.Select(hit => hit.Value).OrderBy(value => value).SequenceEqual(["tie-first", "tie-second"]),
        string.Join(',', staticRangeHits.Select(hit => hit.Value)));

    var staticFrustumHits = new List<StaticBvhQueryHit<string>>();
    var staticFrustumCount = staticBvh.Query(new Frustum(Matrix4x4.Identity), staticFrustumHits);
    Check(
        "Static BVH frustum query prunes static objects",
        staticFrustumCount == 1 && staticFrustumHits is [{ Index: 1, Value: "visible" }],
        string.Join(',', staticFrustumHits.Select(hit => $"{hit.Index}:{hit.Value}")));

    var staticRayHit = staticBvh.Raycast(Vector3.Zero, Vector3.UnitX, 10f, out var staticRay);
    Check(
        "Static BVH ray query chooses nearest stable input index",
        staticRayHit && staticRay is { Index: 3, Value: "tie-first" } && MathF.Abs(staticRay.Distance - 2f) < 0.0001f,
        $"index={staticRay.Index} value={staticRay.Value} distance={staticRay.Distance}");

    var emptyStaticBvh = new StaticBvh<string>([]);
    Check(
        "Static BVH permits empty immutable snapshots",
        emptyStaticBvh.Count == 0 && emptyStaticBvh.Query(unit, new List<StaticBvhQueryHit<string>>()) == 0 &&
        !emptyStaticBvh.Raycast(Vector3.Zero, Vector3.UnitX, 1f, out _));
    Check(
        "Static BVH rejects invalid construction input",
        CaptureException(() => new StaticBvh<string>(staticItems, 0)) is ArgumentOutOfRangeException &&
        CaptureException(() => new StaticBvh<string>([new StaticBvhItem<string>(null!, unit)])) is ArgumentNullException);

    var concurrentStaticFailures = 0;
    Parallel.For(0, 16, _ =>
    {
        try
        {
            var localHits = new List<StaticBvhQueryHit<string>>();
            if (staticBvh.Query(new Frustum(Matrix4x4.Identity), localHits) != 1 || localHits[0].Value != "visible")
            {
                Interlocked.Increment(ref concurrentStaticFailures);
            }
        }
        catch
        {
            Interlocked.Increment(ref concurrentStaticFailures);
        }
    });
    Check("Static BVH permits independent concurrent readers", concurrentStaticFailures == 0, $"failures={concurrentStaticFailures}");

    var treeInstance = new DynamicAabbTree<string>(0.5f);
    var left = treeInstance.Insert("left", new Aabb3(new Vector3(-4f, 0f, 0f), new Vector3(-3f, 1f, 1f)));
    var middle = treeInstance.Insert("middle", unit);
    var moving = treeInstance.Insert("moving", new Aabb3(new Vector3(4f, 0f, 0f), new Vector3(5f, 1f, 1f)));
    Check("动态树插入并计数", treeInstance.Count == 3 && left.IsValid && middle.IsValid && moving.IsValid);

    var rangeHits = new List<SpatialQueryHit<string>>();
    var appended = treeInstance.Query(new Aabb3(new Vector3(-4.5f, -1f, -1f), new Vector3(1.5f, 2f, 2f)), rangeHits);
    Check("动态树范围查询只返回实际相交叶子", appended == 2 &&
        rangeHits.Select(hit => hit.Value).OrderBy(value => value).SequenceEqual(["left", "middle"]),
        string.Join(',', rangeHits.Select(hit => hit.Value)));
    var appendedHits = new List<SpatialQueryHit<string>>
    {
        new(new SpatialHandle(99, 1), "sentinel", unit),
    };
    var appendedAfterSentinel = treeInstance.Query(new Aabb3(new Vector3(-4.5f, -1f, -1f), new Vector3(1.5f, 2f, 2f)), appendedHits);
    Check("动态树查询追加到调用方结果列表", appendedAfterSentinel == 2 && appendedHits.Count == 3 && appendedHits[0].Value == "sentinel");

    var stayedInFatBounds = !treeInstance.Update(moving, new Aabb3(new Vector3(4.4f, 0f, 0f), new Vector3(5.4f, 1f, 1f)));
    rangeHits.Clear();
    treeInstance.Query(new Aabb3(new Vector3(4f, -1f, -1f), new Vector3(4.2f, 2f, 2f)), rangeHits);
    Check("fat AABB 不产生查询假阳性", stayedInFatBounds && rangeHits.Count == 0,
        $"reinsert={!stayedInFatBounds} hits={rangeHits.Count}");
    Check("越出 fat AABB 后重插入", treeInstance.Update(moving, new Aabb3(new Vector3(8f, 0f, 0f), new Vector3(9f, 1f, 1f))));

    var frustumHits = new List<SpatialQueryHit<string>>();
    var identityFrustum = new Frustum(Matrix4x4.Identity);
    treeInstance.Query(identityFrustum, frustumHits);
    Check("动态树视锥查询使用实际 AABB", frustumHits.Select(hit => hit.Value).SequenceEqual(["middle"]),
        string.Join(',', frustumHits.Select(hit => hit.Value)));

    var rayTree = new DynamicAabbTree<string>();
    var tieA = rayTree.Insert("tie-a", new Aabb3(new Vector3(2f, 0f, 0f), new Vector3(3f, 1f, 1f)));
    _ = rayTree.Insert("tie-b", new Aabb3(new Vector3(2f, 0f, 0f), new Vector3(3f, 1f, 1f)));
    var rayHit = rayTree.Raycast(Vector3.Zero, Vector3.UnitX, 10f, out var hit);
    Check("动态树射线选择最近且稳定的句柄", rayHit && hit.Handle == tieA && hit.Value == "tie-a" &&
        MathF.Abs(hit.Distance - 2f) < 0.0001f, $"hit={hit.Value} distance={hit.Distance}");

    Check("动态树移除并使旧句柄失效", treeInstance.Remove(left) && !treeInstance.Remove(left) &&
        !treeInstance.TryGet(left, out _) && treeInstance.Count == 2);
    var replacement = treeInstance.Insert("replacement", new Aabb3(new Vector3(-4f, 0f, 0f), new Vector3(-3f, 1f, 1f)));
    Check("槽位复用递增 generation", replacement.Index == left.Index && replacement.Generation != left.Generation &&
        treeInstance.TryGet(replacement, out var replacementHit) && replacementHit.Value == "replacement",
        $"old={left} new={replacement}");

    var backgroundError = CaptureException(() =>
        Task.Run(() => treeInstance.Query(unit, new List<SpatialQueryHit<string>>())).GetAwaiter().GetResult());
    Check("动态树拒绝后台线程访问", backgroundError is InvalidOperationException, backgroundError?.Message ?? "");

    var stressTree = new DynamicAabbTree<int>();
    var stressHandles = new List<SpatialHandle>();
    for (var index = 0; index < 64; index++)
    {
        var minimum = new Vector3(index * 3f, 0f, 0f);
        stressHandles.Add(stressTree.Insert(index, new Aabb3(minimum, minimum + Vector3.One)));
    }

    var stressHits = new List<SpatialQueryHit<int>>();
    var stressCount = stressTree.Query(new Aabb3(new Vector3(-1f), new Vector3(192f, 2f, 2f)), stressHits);
    Check("动态树扩容和旋转后保留全部叶子", stressTree.Count == 64 && stressCount == 64 &&
        stressHits.Select(hit => hit.Value).OrderBy(value => value).SequenceEqual(Enumerable.Range(0, 64)));
    for (var index = 0; index < stressHandles.Count; index += 2)
    {
        _ = stressTree.Remove(stressHandles[index]);
    }

    stressHits.Clear();
    stressTree.Query(new Aabb3(new Vector3(-1f), new Vector3(192f, 2f, 2f)), stressHits);
    Check("动态树大量移除后包围盒保持正确", stressTree.Count == 32 && stressHits.Count == 32 &&
        stressHits.All(hit => hit.Value % 2 == 1));
    var clearedHandle = stressHandles[1];
    stressTree.Clear();
    Check("Clear 使先前句柄失效并重置计数", stressTree.Count == 0 && !stressTree.TryGet(clearedHandle, out _));

    Console.WriteLine(failures == 0 ? "spatialcheck 全部通过" : $"spatialcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int HeadlessCommand(uint seed)
{
    var world = new VoxelWorld(seed, WorldType.Noise);
    world.GenerateAround(0, 0, 3);
    var randomTicks = 0;
    world.OnBlockRandomTick += (_, _, _, _) => randomTicks++;
    var scheduledHits = 0;
    world.OnBlockScheduledTick += (_, _, _, _) => scheduledHits++;
    world.ScheduleTick(24, 40, 24, 100);

    const int ticks = 1200; // 60 秒 @20Hz
    for (var i = 0; i < ticks; i++) world.Tick();

    var dir = Path.Combine(Path.GetTempPath(), $"cubit_headless_{Guid.NewGuid():N}");
    world.Save(dir);
    var loaded = VoxelWorld.LoadFile(dir);
    var reloadOk = loaded.Store.ChunkKeys.Length == world.Store.ChunkKeys.Length;
    Directory.Delete(dir, true);

    // 确定性：同种子同 tick 序列应完全一致
    var w2 = new VoxelWorld(seed, WorldType.Noise);
    w2.GenerateAround(0, 0, 3);
    var rt2 = 0;
    w2.OnBlockRandomTick += (_, _, _, _) => rt2++;
    w2.ScheduleTick(24, 40, 24, 100);
    for (var i = 0; i < ticks; i++) w2.Tick();
    var deterministic = randomTicks == rt2 && scheduledHits == 1;

    Console.WriteLine($"headless: seed={seed} ticks={ticks} tickCount={world.TickCount} chunks={world.Store.ChunkKeys.Length} randomTicks={randomTicks} scheduledHits={scheduledHits} reload={reloadOk} deterministic={deterministic}");
    return reloadOk && deterministic ? 0 : 1;
}

static int DisplayCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var display = new DisplaySettings { LogicalWidth = 1280, LogicalHeight = 720, KeepAspect = true };

    // 1) 同宽高比（16:9）：铺满无黑边
    var same = display.ComputeRenderRect(1920, 1080);
    Check("同宽高比铺满", same is { X: 0, Y: 0, Width: 1920, Height: 1080 }, $"{same}");

    // 2) 物理更宽（20:9，如 2800x1260）：高度铺满，宽度按 16:9 收缩 → 左右黑边
    var wide = display.ComputeRenderRect(2800, 1260);
    var wideOk = wide.Width == 2240 && wide.Height == 1260 && wide.X == 280 && wide.Y == 0;
    Check("宽屏 letterbox（左右黑边）", wideOk, $"{wide}");
    Check("宽屏渲染区宽高比≈16:9", MathF.Abs(wide.Width / (float)wide.Height - 16f / 9f) < 0.01f, $"{wide.Width / (float)wide.Height:F3}");

    // 3) 物理更高（竖屏）：宽度铺满，高度按 16:9 收缩 → 上下黑边
    var tall = display.ComputeRenderRect(1260, 2800);
    var tallOk = tall.Width == 1260 && tall.Height == 708 && tall.X == 0 && tall.Y == (2800 - 708) / 2;
    Check("竖屏 letterbox（上下黑边）", tallOk, $"{tall}");
    Check("竖屏渲染区宽高比≈16:9", MathF.Abs(tall.Width / (float)tall.Height - 16f / 9f) < 0.01f, $"{tall.Width / (float)tall.Height:F3}");

    // 4) KeepAspect=false：铺满（允许拉伸）
    display.KeepAspect = false;
    var stretch = display.ComputeRenderRect(2800, 1260);
    Check("关闭保持宽高比后铺满", stretch is { X: 0, Y: 0, Width: 2800, Height: 1260 }, $"{stretch}");

    // 5) 非法尺寸容错
    var bad = display.ComputeRenderRect(0, 0);
    Check("非法尺寸容错", bad is { Width: 0, Height: 0 }, $"{bad}");

    // 6) 编辑器视口中的纹理按自身宽高比居中，不能随 dock 区域拉伸。
    var fitted = DisplaySettings.ComputeAspectFitRect(960, 850, 1600, 900);
    Check(
        "纹理在视口区域内等比居中",
        fitted is { X: 0, Y: 155, Width: 960, Height: 540 },
        $"{fitted}");

    Console.WriteLine(failures == 0 ? "displaycheck 全部通过" : $"displaycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ViewportCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var editorWindowPolicy = typeof(Cubit.Editor.EditorLaunchOptions).Assembly
        .GetType("Cubit.Editor.EditorWindowPolicy");
    var initialWidth = editorWindowPolicy?.GetProperty("InitialWidth")?.GetValue(null) as int?;
    var initialHeight = editorWindowPolicy?.GetProperty("InitialHeight")?.GetValue(null) as int?;
    Check(
        "编辑器初始窗口完整容纳三栏布局",
        initialWidth == 1200 && initialHeight == 720,
        $"size={initialWidth?.ToString() ?? "未定义"}x{initialHeight?.ToString() ?? "未定义"}");

    var externalTextureRef = Cubit.ImGui.Rendering.ImGuiRenderer.CreateExternalTextureRef(ulong.MaxValue);
    Check(
        "外部纹理引用不保留短期 ImTextureData 指针",
        (ulong)externalTextureRef.GetTexID() == ulong.MaxValue,
        $"texId={(ulong)externalTextureRef.GetTexID()}");

    var swapchainAttachment = Cubit.Core.Rendering.VulkanRenderPassPolicy.CreateSceneColorAttachment(
        Silk.NET.Vulkan.Format.B8G8R8A8Srgb,
        offscreen: false);
    var offscreenAttachment = Cubit.Core.Rendering.VulkanRenderPassPolicy.CreateSceneColorAttachment(
        Silk.NET.Vulkan.Format.B8G8R8A8Srgb,
        offscreen: true);
    var offscreenReadDependency = Cubit.Core.Rendering.VulkanRenderPassPolicy.CreateOffscreenReadDependency();
    var swapchainPass = new Silk.NET.Vulkan.RenderPass(101);
    var offscreenPass = new Silk.NET.Vulkan.RenderPass(202);
    var selectedPass = Cubit.Core.Rendering.VulkanRenderPassPolicy.SelectSceneRenderPass(
        offscreen: true,
        swapchainPass,
        offscreenPass);
    var overlayColor = Cubit.Core.Rendering.VulkanRenderPassPolicy.CreateSwapchainOverlayColorAttachment(
        Silk.NET.Vulkan.Format.B8G8R8A8Srgb);
    var overlayDepth = Cubit.Core.Rendering.VulkanRenderPassPolicy.CreateOverlayDepthAttachment();
    var overlayDepthState = Cubit.Core.Rendering.VulkanRenderPassPolicy.CreateOverlayDepthStencilState();
    Check(
        "交换链场景最终进入呈现布局",
        swapchainAttachment.FinalLayout == Silk.NET.Vulkan.ImageLayout.PresentSrcKhr,
        swapchainAttachment.FinalLayout.ToString());
    Check(
        "离屏场景最终进入采样布局",
        offscreenAttachment.FinalLayout == Silk.NET.Vulkan.ImageLayout.ShaderReadOnlyOptimal,
        offscreenAttachment.FinalLayout.ToString());
    Check(
        "离屏颜色写入对后续片元采样可见",
        (offscreenReadDependency.SrcStageMask & Silk.NET.Vulkan.PipelineStageFlags.ColorAttachmentOutputBit) != 0
            && (offscreenReadDependency.DstStageMask & Silk.NET.Vulkan.PipelineStageFlags.FragmentShaderBit) != 0
            && (offscreenReadDependency.SrcAccessMask & Silk.NET.Vulkan.AccessFlags.ColorAttachmentWriteBit) != 0
            && (offscreenReadDependency.DstAccessMask & Silk.NET.Vulkan.AccessFlags.ShaderReadBit) != 0);
    Check(
        "离屏深度写入对后续深度附件可见",
        (offscreenReadDependency.SrcStageMask & Silk.NET.Vulkan.PipelineStageFlags.LateFragmentTestsBit) != 0
            && (offscreenReadDependency.DstStageMask & Silk.NET.Vulkan.PipelineStageFlags.EarlyFragmentTestsBit) != 0
            && (offscreenReadDependency.SrcAccessMask & Silk.NET.Vulkan.AccessFlags.DepthStencilAttachmentWriteBit) != 0
            && (offscreenReadDependency.DstAccessMask & Silk.NET.Vulkan.AccessFlags.DepthStencilAttachmentWriteBit) != 0);
    Check("离屏场景实际选择离屏 render pass", selectedPass.Handle == offscreenPass.Handle, $"handle={selectedPass.Handle}");
    Check(
        "编辑器覆盖层保留场景颜色并最终呈现",
        overlayColor.InitialLayout == Silk.NET.Vulkan.ImageLayout.PresentSrcKhr
            && overlayColor.FinalLayout == Silk.NET.Vulkan.ImageLayout.PresentSrcKhr);
    Check(
        "编辑器覆盖层包含兼容深度附件",
        overlayDepth.Format == Silk.NET.Vulkan.Format.D32Sfloat
            && overlayDepth.FinalLayout == Silk.NET.Vulkan.ImageLayout.DepthStencilAttachmentOptimal);
    Check(
        "编辑器覆盖层深度从未定义布局开始",
        overlayDepth.InitialLayout == Silk.NET.Vulkan.ImageLayout.Undefined,
        overlayDepth.InitialLayout.ToString());
    Check(
        "编辑器覆盖层关闭深度测试与写入",
        !overlayDepthState.DepthTestEnable
            && !overlayDepthState.DepthWriteEnable
            && overlayDepthState.DepthCompareOp == Silk.NET.Vulkan.CompareOp.Always,
        $"test={overlayDepthState.DepthTestEnable} write={overlayDepthState.DepthWriteEnable}");
    Check(
        "栅栏超时禁止销毁交换链资源",
        !Cubit.Core.Rendering.VulkanRenderPassPolicy.CanDestroySwapchainResources(Silk.NET.Vulkan.Result.Timeout));
    Check(
        "栅栏超时禁止复用帧槽",
        !Cubit.Core.Rendering.VulkanRenderPassPolicy.CanReuseFrameSlot(Silk.NET.Vulkan.Result.Timeout));
    Check(
        "栅栏完成后允许销毁交换链资源",
        Cubit.Core.Rendering.VulkanRenderPassPolicy.CanDestroySwapchainResources(Silk.NET.Vulkan.Result.Success));
    Check(
        "在途栅栏等待成功后提交前必须复位",
        Cubit.Core.Rendering.VulkanRenderPassPolicy.MustResetFenceBeforeSubmit(
            wasPending: true,
            Silk.NET.Vulkan.Result.Success));
    Check(
        "在途栅栏等待超时后不得复位",
        !Cubit.Core.Rendering.VulkanRenderPassPolicy.MustResetFenceBeforeSubmit(
            wasPending: true,
            Silk.NET.Vulkan.Result.Timeout));

    // 与 frustumcheck 同一相机/矩阵约定（行主序存储，GPU 端按列主序解释）。
    var camera = new FlyCamera(new Vector3(24f, 34f, 24f), MathF.PI * 0.25f, -0.35f);
    var vp = camera.ViewMatrix * camera.ProjectionMatrix(16f / 9f);
    const float height = 720f;

    // Vector4.Transform(v, M)（行向量）与 GPU 端 M^T * v 分量一致，故可直接得到裁剪坐标。
    Vector4 ToNdc(Vector3 world)
    {
        var clip = Vector4.Transform(new Vector4(world, 1f), vp);
        return new Vector4(clip.X / clip.W, clip.Y / clip.W, clip.Z / clip.W, clip.W);
    }

    // 相机前方偏下的点（地形）与偏上的点（天空），两者都在视锥内（w>0）。
    var below = camera.Position + camera.Forward * 10f + new Vector3(0f, -5f, 0f);
    var above = camera.Position + camera.Forward * 10f + new Vector3(0f, 5f, 0f);
    var ndcBelow = ToNdc(below);
    var ndcAbove = ToNdc(above);
    Check("两点均在相机前方（w>0）", ndcBelow.W > 0f && ndcAbove.W > 0f, $"wBelow={ndcBelow.W:F1} wAbove={ndcAbove.W:F1}");

    // Vulkan NDC：y 向下（+1 底 / -1 顶）。当前投影 m22=+f，故“下方点”落在 NDC 顶部（y<0）。
    Check("投影约定：下方点 NDC y<0（裁剪顶部）", ndcBelow.Y < 0f, $"y={ndcBelow.Y:F3}");
    Check("投影约定：上方点 NDC y>0（裁剪底部）", ndcAbove.Y > 0f, $"y={ndcAbove.Y:F3}");

    // 负高度视口（VulkanContext 当前实现）：framebufferY = H*(1-ndcY)/2，把裁剪顶部映射到屏幕下方。
    // 修复前（正高度视口）：framebufferY = H*(1+ndcY)/2，下方点画在屏幕上方——即“天空在下、地形在上”的翻转 bug。
    float FlipY(float ndcY) => height * (1f - ndcY) / 2f;
    float OldY(float ndcY) => height * (1f + ndcY) / 2f;
    Check("负高度视口：下方点渲染到屏幕下半（地形在下）", FlipY(ndcBelow.Y) > height / 2f, $"y={FlipY(ndcBelow.Y):F0}");
    Check("负高度视口：上方点渲染到屏幕上半（天空在上）", FlipY(ndcAbove.Y) < height / 2f, $"y={FlipY(ndcAbove.Y):F0}");
    Check("旧视口确有翻转 bug（回归护栏）", OldY(ndcBelow.Y) < height / 2f && OldY(ndcAbove.Y) > height / 2f, $"below={OldY(ndcBelow.Y):F0} above={OldY(ndcAbove.Y):F0}");

    Console.WriteLine(failures == 0 ? "viewportcheck 全部通过" : $"viewportcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int RegionCheck(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var world = new VoxelWorld(seed, WorldType.Noise);
    world.GenerateAround(0, 0, 3);
    world.GenerateAround(40, 40, 2); // 跨 region 边界（cx=38..42 → r.1.1）

    var dir = Path.Combine(Path.GetTempPath(), $"cubit_region_{Guid.NewGuid():N}");
    world.Save(dir);
    var regionFiles = Directory.GetFiles(dir, "*.cubitregion");
    Check("region 文件生成（r.0.0 + r.1.1）",
        File.Exists(Path.Combine(dir, "r.0.0.cubitregion")) && File.Exists(Path.Combine(dir, "r.1.1.cubitregion")),
        $"files={regionFiles.Length}");

    var loaded = VoxelWorld.LoadFile(dir);
    Check("region 加载区块数一致", loaded.Store.ChunkKeys.Length == world.Store.ChunkKeys.Length, $"{loaded.Store.ChunkKeys.Length}/{world.Store.ChunkKeys.Length}");

    static bool WorldEqual(VoxelWorld a, VoxelWorld b, int minY = Chunk.MinY, int maxYExclusive = Chunk.MaxYExclusive)
    {
        if (a.Store.ChunkKeys.Length != b.Store.ChunkKeys.Length) return false;
        foreach (var key in a.Store.ChunkKeys)
        {
            for (var y = minY; y < maxYExclusive; y++)
            {
                for (var z = 0; z < Chunk.SizeZ; z++)
                {
                    for (var x = 0; x < Chunk.SizeX; x++)
                    {
                        var wx = key.X * Chunk.SizeX + x;
                        var wz = key.Z * Chunk.SizeZ + z;
                        if (b.GetBlock(wx, y, wz) != a.GetBlock(wx, y, wz)
                            || LightingEngine.GetLight(b.Store, wx, y, wz) != LightingEngine.GetLight(a.Store, wx, y, wz))
                        {
                            return false;
                        }
                    }
                }
            }
        }

        return true;
    }

    Check("region 往返逐方块+光照一致", WorldEqual(world, loaded));
    Check(
        "region 状态加载为可重新网格化的 Lighted",
        loaded.Store.GetStatus(0, 0) == ChunkStatus.Lighted,
        $"{loaded.Store.GetStatus(0, 0)}");

    var legacy = Path.Combine(Path.GetTempPath(), $"cubit_legacy_{Guid.NewGuid():N}.cw");
    WorldFile.SaveLegacy(world, legacy);
    var migratedDir = Path.Combine(Path.GetTempPath(), $"cubit_migrate_{Guid.NewGuid():N}");
    WorldFile.MigrateLegacyFile(legacy, migratedDir);
    var migrated = VoxelWorld.LoadFile(migratedDir);
    Check("v2→v4 迁移后保留旧格式可表示的 Y=0..63 数据", WorldEqual(world, migrated, 0, Chunk.MinY + Chunk.LegacySectionCount * Chunk.SectionSizeY));

    var auto = VoxelWorld.LoadFile(legacy);
    Check("Load 自动迁移旧版单文件",
        auto.Store.ChunkKeys.Length == world.Store.ChunkKeys.Length && auto.GetBlock(24, 33, 24) == world.GetBlock(24, 33, 24),
        $"chunks={auto.Store.ChunkKeys.Length}");

    Directory.Delete(dir, true);
    Directory.Delete(migratedDir, true);
    File.Delete(legacy);

    Console.WriteLine(failures == 0 ? "regioncheck 全部通过" : $"regioncheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int PackCommand(string[] args)
{
    if (args.Length < 3 || (args[1] != "validate" && args[1] != "load" && args[1] != "gen"))
    {
        Console.WriteLine("用法: Cubit.Tool pack validate|load|gen <目录> [seed]");
        return 1;
    }

    switch (args[1])
    {
        case "validate": return PackValidate(args[2]);
        case "load":
            var names = BlockRegistry.LoadContentPack(args[2]);
            Console.WriteLine($"已加载 {names.Count} 个方块: {string.Join(", ", names)}（注册表共 {BlockRegistry.Count}）");
            return 0;
        case "gen":
            var seed = args.Length >= 4 && uint.TryParse(args[3], out var s) ? s : 20260808u;
            return PackGen(args[2], seed);
    }

    return 1;
}

static int PackValidate(string dir)
{
    var failures = 0;
    var blockDir = Path.Combine(dir, "blocks");
    if (Directory.Exists(blockDir))
    {
        var ids = new HashSet<ushort>();
        foreach (var file in Directory.EnumerateFiles(blockDir, "*.json"))
        {
            try
            {
                var def = Resource.FromJson<BlockDef>(File.ReadAllText(file));
                if (string.IsNullOrWhiteSpace(def.Name)) { Console.WriteLine($"FAIL {Path.GetFileName(file)}: 缺少名称"); failures++; continue; }
                if (def.TopTexture.Length == 0 || def.SideTexture.Length == 0) { Console.WriteLine($"FAIL {Path.GetFileName(file)}: 缺少纹理"); failures++; continue; }
                if (!ids.Add(def.Id)) { Console.WriteLine($"FAIL {Path.GetFileName(file)}: ID {def.Id} 重复"); failures++; continue; }
                Console.WriteLine($"OK   {Path.GetFileName(file)}: {def.Name} (id={def.Id})");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"FAIL {Path.GetFileName(file)}: {ex.Message}");
                failures++;
            }
        }
    }

    var srPath = Path.Combine(dir, "worldgen", "surface_rules.json");
    if (File.Exists(srPath))
    {
        try
        {
            var rules = SurfaceRules.FromJson(File.ReadAllText(srPath));
            foreach (var rule in rules.Rules)
            {
                if (BlockRegistry.FindId(rule.Block) is null)
                {
                    Console.WriteLine($"FAIL surface_rules.json: 未注册方块 {rule.Block}");
                    failures++;
                }
            }

            Console.WriteLine($"OK   surface_rules.json: {rules.Rules.Count} 条规则");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"FAIL surface_rules.json: {ex.Message}");
            failures++;
        }
    }

    Console.WriteLine(failures == 0 ? "pack validate 通过" : $"pack validate 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int PackGen(string dir, uint seed)
{
    var names = BlockRegistry.LoadContentPack(dir);
    Console.WriteLine($"已加载方块: {string.Join(", ", names)}");
    SurfaceRules? rules = null;
    var srPath = Path.Combine(dir, "worldgen", "surface_rules.json");
    if (File.Exists(srPath)) rules = SurfaceRules.FromJson(File.ReadAllText(srPath));
    var world = new VoxelWorld(seed, WorldType.Noise, rules);
    world.GenerateAround(0, 0, 1);
    var groundY = WorldGenerator.GetHeight(24, 24, seed);
    var top = world.GetBlock(24, groundY, 24);
    Console.WriteLine($"世界生成: chunks={world.Store.ChunkKeys.Length} 地表(24,{groundY},24)={BlockRegistry.GetName(top.Id)}");
    return 0;
}

static int PackCheck(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var dir = Path.Combine(Path.GetTempPath(), $"cubit_pack_{Guid.NewGuid():N}");
    Directory.CreateDirectory(Path.Combine(dir, "blocks"));
    Directory.CreateDirectory(Path.Combine(dir, "worldgen"));
    try
    {
        var def = new BlockDef { Id = 100, Name = "测试石", TopTexture = "stone", SideTexture = "stone", BottomTexture = "stone" };
        File.WriteAllText(Path.Combine(dir, "blocks", "test_block.json"), def.ToJson());
        var rules = new SurfaceRules
        {
            Rules =
            [
                new SurfaceRules.Rule { When = "bedrock", Block = "石头" },
                new SurfaceRules.Rule { When = "top", Block = "测试石" },
                new SurfaceRules.Rule { When = "deep", Block = "石头" },
            ],
        };
        var rulesJson = JsonSerializer.Serialize(rules);
        File.WriteAllText(Path.Combine(dir, "worldgen", "surface_rules.json"), rulesJson);

        BlockRegistry.LoadContentPack(dir);
        Check("内容包方块注册", BlockRegistry.FindId("测试石") is 100, $"id={BlockRegistry.FindId("测试石")}");

        var validateResult = PackValidate(dir);
        Check("pack validate 通过", validateResult == 0);

        var rulesBack = SurfaceRules.FromJson(rulesJson);
        var world = new VoxelWorld(seed, WorldType.Noise, rulesBack);
        world.GenerateAround(0, 0, 1);
        var groundY = WorldGenerator.GetHeight(24, 24, seed);
        var top = world.GetBlock(24, groundY, 24);
        Check("表面规则数据驱动（地表=测试石）", top.Id == 100, $"top={BlockRegistry.GetName(top.Id)} at y={groundY}");
    }
    finally
    {
        if (Directory.Exists(dir)) Directory.Delete(dir, true);
    }

    Console.WriteLine(failures == 0 ? "packcheck 全部通过" : $"packcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int McpCompositionCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var projectDirectory = Path.Combine(Path.GetTempPath(), $"cubit_mcp_composition_{Guid.NewGuid():N}");
    try
    {
        var createdProject = ProjectIO.Create(projectDirectory, "MCP composition check");
        var manifest = new CubitProjectManifest
        {
            FormatVersion = ProjectIO.CurrentFormatVersion,
            Name = "MCP composition check",
            MainScene = createdProject.Manifest.MainScene,
            Plugins =
            [
                new CubitPluginReference { Id = " cubit.Voxel ", Version = "1.0.0" },
                new CubitPluginReference { Id = "CUBIT.AUDIO", Version = "1.0.0" },
                new CubitPluginReference { Id = " cubit.physics ", Version = "1.0.0" },
                new CubitPluginReference { Id = "cubit.animation", Version = "1.0.0" },
                new CubitPluginReference { Id = "cubit.content", Version = "1.0.0" },
                new CubitPluginReference { Id = "cubit.scripting", Version = "1.0.0" },
                new CubitPluginReference { Id = "com.example.weather", Version = "1.0.0" },
            ],
        };
        File.WriteAllText(createdProject.ManifestPath, JsonSerializer.Serialize(manifest));
        var project = ProjectIO.Load(projectDirectory);
        Check("临时项目保留带大小写和空白的 MCP 插件声明", project.Manifest.Plugins.Select(plugin => plugin.Id).SequenceEqual(
        [
            " cubit.Voxel ", "CUBIT.AUDIO", " cubit.physics ", "cubit.animation", "cubit.content", "cubit.scripting", "com.example.weather",
        ]));

        using var tree = new SceneTree();
        var engineContext = new EngineContext();
        var runtimeService = new McpCompositionRuntimeService();
        var context = new McpProjectExtensionContext
        {
            Project = project,
            Tree = tree,
            EngineContext = engineContext,
            ResolveRuntimeService = type => type == typeof(McpCompositionRuntimeService) ? runtimeService : null,
        };
        var voxel = new McpCompositionProbeModule("CUBIT.voxel", "Cubit.Mcp.Voxel");
        var audio = new McpCompositionProbeModule("cubit.audio", "Cubit.Mcp.Audio");
        var undeclared = new McpCompositionProbeModule("cubit.pixel", "Cubit.Mcp.Probe.Pixel");

        var composition = McpProjectExtensionComposer.Compose(context, [undeclared, audio, voxel]);
        Check("项目 MCP adapter composer 实现 extension provider", composition is IMcpExtensionProvider);
        Check("运行服务解析器可由泛型上下文获取", context.TryGetRuntimeService<McpCompositionRuntimeService>(out var resolved) && ReferenceEquals(resolved, runtimeService));
        Check("反序 module 输入仍按清单顺序匹配大小写和空白 ID",
            composition.GetTools().Select(tool => tool.Name).SequenceEqual(["probe.voxel.tool.0", "probe.audio.tool.0"]));
        Check("未声明 probe module 不创建也不公开工具", undeclared.CreateCount == 0 && composition.GetTools().All(tool => tool.Name != "probe.pixel.tool.0"));

        var statusResource = composition.GetResources().SingleOrDefault(resource => resource.Uri == "cubit://mcp/extensions");
        Check("项目 MCP adapter 状态资源存在", statusResource is not null);
        if (statusResource is not null)
        {
            using var status = JsonDocument.Parse(statusResource.Read());
            var active = status.RootElement.GetProperty("activeAdapters").EnumerateArray()
                .Select(adapter => (
                    adapter.GetProperty("pluginId").GetString(),
                    adapter.GetProperty("expectedAssemblyName").GetString()))
                .ToArray();
            var unavailable = status.RootElement.GetProperty("unavailableAdapters").EnumerateArray()
                .Select(adapter => (
                    adapter.GetProperty("pluginId").GetString(),
                    adapter.GetProperty("expectedAssemblyName").GetString()))
                .ToArray();
            Check("状态资源按清单顺序列出 active adapter ID 与程序集", active.SequenceEqual(
            [
                ("cubit.Voxel", "Cubit.Mcp.Voxel"),
                ("CUBIT.AUDIO", "Cubit.Mcp.Audio"),
            ]));
            Check("未提供的官方 adapter 按清单列出 ID 与期望程序集", unavailable
                .Where(adapter => !string.Equals(adapter.Item1, "com.example.weather", StringComparison.OrdinalIgnoreCase))
                .SequenceEqual(
            [
                ("cubit.physics", "Cubit.Mcp.Physics"),
                ("cubit.animation", "Cubit.Mcp.Animation"),
                ("cubit.content", "Cubit.Mcp.Content"),
                ("cubit.scripting", "Cubit.Mcp.Scripting"),
            ]));
            Check("第三方插件不伪装为缺失的官方 MCP adapter",
                unavailable.All(adapter => !string.Equals(adapter.Item1, "com.example.weather", StringComparison.OrdinalIgnoreCase)));
        }

        Check("声明的 module 只创建一次", voxel.CreateCount == 1 && audio.CreateCount == 1);
        voxel.Revision = 1;
        Check("composition 不缓存 provider 工具",
            composition.GetTools().Select(tool => tool.Name).SequenceEqual(["probe.voxel.tool.1", "probe.audio.tool.0"]));
        Check("composition 不缓存 provider 资源",
            composition.GetResources().Any(resource => resource.Uri == "cubit://probe/voxel/1") &&
            composition.GetResources().All(resource => resource.Uri != "cubit://probe/voxel/0"));
        Check("composition 不缓存 provider 提示词",
            composition.GetPrompts().Any(prompt => prompt.Name == "probe.voxel.prompt.1") &&
            composition.GetPrompts().All(prompt => prompt.Name != "probe.voxel.prompt.0"));

        Check("空 module ID 被拒绝", ThrowsArgumentException(() =>
            McpProjectExtensionComposer.Compose(context, [new McpCompositionProbeModule("   ", "Cubit.Mcp.Probe.Empty")] )));
        Check("大小写和空白重复 module ID 被拒绝", ThrowsArgumentException(() =>
            McpProjectExtensionComposer.Compose(context,
            [
                new McpCompositionProbeModule(" cubit.voxel", "Cubit.Mcp.Probe.One"),
                new McpCompositionProbeModule("CUBIT.VOXEL ", "Cubit.Mcp.Probe.Two"),
            ])));

        var ecs = new McpCompositionProbeModule("cubit.core.ecs", "Cubit.Mcp.Probe.Ecs", alwaysAvailable: true);
        var ecsComposition = McpProjectExtensionComposer.Compose(context, [ecs]);
        Check("AlwaysAvailable core ECS module 自动加入", ecs.CreateCount == 1 &&
            ecsComposition.GetTools().Select(tool => tool.Name).SequenceEqual(["probe.core.ecs.tool.0"]));

        var optionalEcs = new McpCompositionProbeModule("cubit.core.ecs", "Cubit.Mcp.Probe.OptionalEcs");
        var optionalEcsComposition = McpProjectExtensionComposer.Compose(context, [optionalEcs]);
        Check("非 AlwaysAvailable core ECS module 不自动加入", optionalEcs.CreateCount == 0 &&
            !optionalEcsComposition.GetTools().Any());

        AudioServer? composedAudioServer = null;
        var audioContext = new McpProjectExtensionContext
        {
            Project = project,
            Tree = tree,
            EngineContext = engineContext,
            ResolveRuntimeService = type => type == typeof(AudioServer) ? composedAudioServer : null,
        };
        var audioModuleType = typeof(AudioMcpExtension).Assembly.GetType(
            "Cubit.Mcp.Audio.AudioMcpProjectExtensionModule");
        var audioModule = audioModuleType is null
            ? null
            : Activator.CreateInstance(audioModuleType) as IMcpProjectExtensionModule;
        Check("Audio 项目 MCP adapter 已显式链接", audioModule is not null);
        if (audioModule is not null)
        {
            var audioComposition = McpProjectExtensionComposer.Compose(audioContext, [audioModule]);
            Check("未注入 AudioServer 时不公开音频工具", !audioComposition.GetTools().Any(tool => tool.Name == "audio.status"));

            composedAudioServer = new AudioServer(null, new DiagnosticBag());
            var audioToolNames = audioComposition.GetTools().Select(tool => tool.Name).ToArray();
            Check("注入 AudioServer 后公开全部七项音频工具", audioToolNames.SequenceEqual(
            [
                "audio.status", "audio.list_buses", "audio.set_bus_volume", "audio.set_bus_muted",
                "audio.list_players", "audio.play_player", "audio.stop_player",
            ]));

            composedAudioServer.Dispose();
            composedAudioServer = null;
            Check("移除 AudioServer 后下次查询隐藏音频工具", !audioComposition.GetTools().Any(tool => tool.Name == "audio.status"));
        }

        var voxelModuleType = Assembly.Load("Cubit.Mcp.Voxel").GetType(
            "Cubit.Mcp.Voxel.VoxelMcpProjectExtensionModule");
        var voxelModule = voxelModuleType is null
            ? null
            : Activator.CreateInstance(voxelModuleType) as IMcpProjectExtensionModule;
        Check("Voxel 项目 MCP adapter 已显式链接", voxelModule is not null);
        if (voxelModule is not null)
        {
            VoxelInputState? composedVoxelInput = null;
            var voxelContext = new McpProjectExtensionContext
            {
                Project = project,
                Tree = tree,
                EngineContext = engineContext,
                ResolveRuntimeService = type => type == typeof(VoxelInputState) ? composedVoxelInput : null,
            };
            var voxelComposition = McpProjectExtensionComposer.Compose(voxelContext, [voxelModule]);
            Check("没有 VoxelWorldNode 时隐藏体素工具", !voxelComposition.GetTools().Any());

            using var voxelRenderServer = new RenderingServer(new FakeRenderBackend());
            using var voxelJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
            var voxelRoot = new Node { Name = "VoxelRoot" };
            voxelRoot.AddChild(new VoxelWorldNode
            {
                Name = "World",
                WorldType = WorldType.Flat,
                GenerateRadius = 0,
                Server = voxelRenderServer,
                Jobs = voxelJobs,
            });
            tree.ReplaceChildren(voxelRoot);
            Check("VoxelWorldNode 进入场景后只公开五项世界工具", voxelComposition.GetTools()
                .Select(tool => tool.Name)
                .SequenceEqual(
                [
                    "world.get_block", "world.set_block", "world.raycast", "world.get_chunk_status", "world.list_registry",
                ]));

            composedVoxelInput = new VoxelInputState();
            Check("注入 VoxelInputState 后公开八项体素工具", voxelComposition.GetTools()
                .Select(tool => tool.Name)
                .SequenceEqual(
                [
                    "world.get_block", "world.set_block", "world.raycast", "world.get_chunk_status", "world.list_registry",
                    "input.set_break", "input.set_place", "input.set_selected_block",
                ]));
            Check("体素 adapter 保留注册表资源和三项提示词",
                voxelComposition.GetResources().Any(resource => resource.Uri == "cubit://world/registry") &&
                voxelComposition.GetPrompts().Select(prompt => prompt.Name)
                    .SequenceEqual(["world-flat", "world-noise", "query-block"]));
            tree.ReplaceChildren(new Node { Name = "Empty" });
        }

        var physicsModuleType = Assembly.Load("Cubit.Mcp.Physics").GetType(
            "Cubit.Mcp.Physics.PhysicsMcpProjectExtensionModule");
        var physicsModule = physicsModuleType is null
            ? null
            : Activator.CreateInstance(physicsModuleType) as IMcpProjectExtensionModule;
        Check("Physics 项目 MCP adapter 已显式链接", physicsModule is not null);
        if (physicsModule is not null)
        {
            var physicsComposition = McpProjectExtensionComposer.Compose(context, [physicsModule]);
            Check("没有 PhysicsWorld3D 时隐藏物理工具", !physicsComposition.GetTools().Any());

            var physicsRoot = new Node { Name = "PhysicsRoot" };
            physicsRoot.AddChild(new PhysicsWorld3D { Name = "World" });
            tree.ReplaceChildren(physicsRoot);
            Check("PhysicsWorld3D 进入场景后公开物理工具", physicsComposition.GetTools()
                .Select(tool => tool.Name)
                .SequenceEqual(["physics.list_worlds", "physics.raycast"]));
        }

        var animationModuleType = Assembly.Load("Cubit.Mcp.Animation").GetType(
            "Cubit.Mcp.Animation.AnimationMcpProjectExtensionModule");
        var animationModule = animationModuleType is null
            ? null
            : Activator.CreateInstance(animationModuleType) as IMcpProjectExtensionModule;
        Check("Animation 项目 MCP adapter 已显式链接", animationModule is not null);
        if (animationModule is not null)
        {
            var animationComposition = McpProjectExtensionComposer.Compose(context, [animationModule]);
            Check("没有 AnimationPlayer 时隐藏动画工具", !animationComposition.GetTools().Any());

            var animationRoot = new Node { Name = "AnimationRoot" };
            animationRoot.AddChild(new AnimationPlayer { Name = "Player" });
            tree.ReplaceChildren(animationRoot);
            Check("AnimationPlayer 进入场景后公开动画工具", animationComposition.GetTools()
                .Select(tool => tool.Name)
                .SequenceEqual(["animation.list_players", "animation.play", "animation.pause", "animation.stop", "animation.seek"]));
        }

        var ecsModuleType = Assembly.Load("Cubit.Mcp.Ecs").GetType(
            "Cubit.Mcp.Ecs.EcsMcpProjectExtensionModule");
        var ecsModule = ecsModuleType is null
            ? null
            : Activator.CreateInstance(ecsModuleType) as IMcpProjectExtensionModule;
        Check("ECS 项目 MCP adapter 已显式链接", ecsModule is not null);
        if (ecsModule is not null)
        {
            var ecsNodeComposition = McpProjectExtensionComposer.Compose(context, [ecsModule]);
            Check("没有 EcsNode 时隐藏 ECS 工具", !ecsNodeComposition.GetTools().Any());

            var ecsRoot = new Node { Name = "EcsRoot" };
            ecsRoot.AddChild(new EcsNode { Name = "Ecs" });
            tree.ReplaceChildren(ecsRoot);
            Check("EcsNode 进入场景后公开 ECS 工具", ecsNodeComposition.GetTools()
                .Select(tool => tool.Name)
                .SequenceEqual(["ecs.list_nodes"]));
        }

        var contentModuleType = Assembly.Load("Cubit.Mcp.Content").GetType(
            "Cubit.Mcp.Content.ContentMcpProjectExtensionModule");
        var scriptingModuleType = Assembly.Load("Cubit.Mcp.Scripting").GetType(
            "Cubit.Mcp.Scripting.ScriptingMcpProjectExtensionModule");
        var contentModule = contentModuleType is null
            ? null
            : Activator.CreateInstance(contentModuleType) as IMcpProjectExtensionModule;
        var scriptingModule = scriptingModuleType is null
            ? null
            : Activator.CreateInstance(scriptingModuleType) as IMcpProjectExtensionModule;
        Check("Content 项目 MCP adapter 已显式链接", contentModule is not null);
        Check("Scripting 项目 MCP adapter 已显式链接", scriptingModule is not null);
        if (contentModule is not null && scriptingModule is not null)
        {
            ContentService? composedContentService = null;
            ScriptRuntime? composedScriptRuntime = null;
            var serviceContext = new McpProjectExtensionContext
            {
                Project = project,
                Tree = tree,
                EngineContext = engineContext,
                ResolveRuntimeService = type => type == typeof(ContentService)
                    ? composedContentService
                    : type == typeof(ScriptRuntime)
                        ? composedScriptRuntime
                        : null,
            };
            var serviceComposition = McpProjectExtensionComposer.Compose(serviceContext, [contentModule, scriptingModule]);
            Check("没有 ContentService 或 ScriptRuntime 时隐藏服务工具", !serviceComposition.GetTools().Any());

            composedContentService = new ContentService([new SceneJsonContentImporter()]);
            using var scriptingRuntime = new ScriptRuntime(tree, project.RootDirectory, new DiagnosticBag());
            composedScriptRuntime = scriptingRuntime;
            Check("注入服务后公开 Content 与 Scripting 工具", serviceComposition.GetTools()
                .Select(tool => tool.Name)
                .SequenceEqual(["content.list_importers", "content.import", "scripting.status", "scripting.stop"]));

            composedContentService = null;
            composedScriptRuntime = null;
            Check("服务移除后下次查询隐藏 Content 与 Scripting 工具", !serviceComposition.GetTools().Any());
        }

        var sampleProgramPath = Path.GetFullPath(Path.Combine(
            Directory.GetCurrentDirectory(), "hosts", "Cubit.Sample", "Program.cs"));
        var sampleProgramSource = File.Exists(sampleProgramPath) ? File.ReadAllText(sampleProgramPath) : "";
        Check(
            "平台宿主通过项目 runtime 装配领域 MCP adapter",
            sampleProgramSource.Contains("McpProjectExtensionComposer.Compose", StringComparison.Ordinal) &&
            sampleProgramSource.Contains("IProjectMcpExtensionSource", StringComparison.Ordinal) &&
            !sampleProgramSource.Contains("VoxelMcpProjectExtensionModule", StringComparison.Ordinal) &&
            !sampleProgramSource.Contains("AudioMcpProjectExtensionModule", StringComparison.Ordinal),
            sampleProgramPath);
    }
    finally
    {
        if (Directory.Exists(projectDirectory))
        {
            Directory.Delete(projectDirectory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "mcpcompositioncheck 全部通过" : $"mcpcompositioncheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static bool ThrowsArgumentException(Action action)
{
    try
    {
        action();
        return false;
    }
    catch (ArgumentException)
    {
        return true;
    }
}

static McpProjectExtensionComposition ComposeProjectMcpExtensions(GameScene scene)
{
    ArgumentNullException.ThrowIfNull(scene);
    var modules = scene.Bootstrap is IProjectMcpExtensionSource source
        ? source.CreateMcpExtensionModules()
        : Enumerable.Empty<IMcpProjectExtensionModule>();
    return McpProjectExtensionComposer.Compose(
        new McpProjectExtensionContext
        {
            Project = scene.Runtime.Project,
            Tree = scene.Tree,
            EngineContext = scene.Runtime.Context,
            ResolveRuntimeService = type => scene.Runtime.Context.TryGetService(type, out var service)
                ? service
                : null,
        },
        modules);
}

static int McpCommand()
{
    // 无头 MCP 宿主：Fake 渲染器 + 游戏场景，stdio 换行分隔 JSON-RPC
    var originalOut = Console.Out;
    Console.SetOut(TextWriter.Null); // 抑制场景构造日志，stdout 只走 MCP 协议
    Environment.SetEnvironmentVariable("VOXEL_WORLDTYPE", "flat");
    var renderer = new FakeRenderBackend();
    using var session = CreateVoxelProjectSession(renderer, 20260808u);
    var scene = session.Scene;
    Console.SetOut(originalOut);
    var host = new McpEngineHostWithExtensions(
        new GameSceneMcpHost(scene, null, session.Input),
        [ComposeProjectMcpExtensions(scene)]);
    using var server = new McpServer(host, Console.OpenStandardInput(), Console.OpenStandardOutput());
    server.Run();
    return 0;
}

static int McpCheck(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var mcpCoreSource = Path.Combine(Directory.GetCurrentDirectory(), "src", "Cubit.Mcp", "McpServer.cs");
    var mcpSourceText = File.Exists(mcpCoreSource) ? File.ReadAllText(mcpCoreSource) : "";
    Check(
        "MCP 核心不硬编码体素类型",
        !mcpSourceText.Contains("VoxelWorldNode", StringComparison.Ordinal) &&
        !mcpSourceText.Contains("Node/Camera3D/VoxelWorldNode", StringComparison.Ordinal),
        mcpCoreSource);

    Environment.SetEnvironmentVariable("VOXEL_WORLDTYPE", "flat");
    var renderer = new FakeRenderBackend();
    using var session = CreateVoxelProjectSession(renderer, seed);
    var scene = session.Scene;
    var playerNode = scene.Tree.GetNode("/Root/Physics/Player") as MyFirstCubitProject.PlayerController
        ?? throw new InvalidOperationException("找不到玩家控制器");
    playerNode.SetGameplayActive(true);
    var worldNode = RequireVoxelWorld(scene);
    var worldReadyDeadline = Stopwatch.StartNew();
    while (worldNode.World?.GetBlock(24, 4, 24).Id != BlockRegistry.Grass &&
           worldReadyDeadline.Elapsed < TimeSpan.FromSeconds(10))
    {
        scene.ProcessFrame(1d / 60d);
        Thread.Sleep(1);
    }

    Check(
        "异步流式生成后出生区块可供 MCP 查询",
        worldNode.World?.GetBlock(24, 4, 24).Id == BlockRegistry.Grass,
        $"elapsed={worldReadyDeadline.Elapsed.TotalMilliseconds:F1}ms pending={worldNode.Streamer?.PendingCount ?? -1}");
    var gameHost = new GameSceneMcpHost(scene, null, session.Input);
    var host = new McpEngineHostWithExtensions(
        gameHost,
        [ComposeProjectMcpExtensions(scene)]);

    // 一次性喂入多个 JSON-RPC 请求（同步跑完再读输出）
    var sb = new System.Text.StringBuilder();
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/list\"}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":3,\"method\":\"tools/call\",\"params\":{\"name\":\"scene.get_tree\",\"arguments\":{}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":4,\"method\":\"tools/call\",\"params\":{\"name\":\"world.get_block\",\"arguments\":{\"x\":24,\"y\":4,\"z\":24}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":5,\"method\":\"tools/call\",\"params\":{\"name\":\"run.status\",\"arguments\":{}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":6,\"method\":\"tools/call\",\"params\":{\"name\":\"run.pause\",\"arguments\":{\"paused\":true}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":7,\"method\":\"tools/call\",\"params\":{\"name\":\"scene.set_property\",\"arguments\":{\"nodePath\":\"/Root/World\",\"property\":\"GenerateRadius\",\"value\":\"2\"}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":8,\"method\":\"tools/call\",\"params\":{\"name\":\"scene.get_property\",\"arguments\":{\"nodePath\":\"/Root/World\",\"property\":\"GenerateRadius\"}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":9,\"method\":\"tools/call\",\"params\":{\"name\":\"input.set_action\",\"arguments\":{\"action\":\"forward\",\"pressed\":true}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":10,\"method\":\"tools/call\",\"params\":{\"name\":\"input.snapshot\",\"arguments\":{}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":11,\"method\":\"tools/call\",\"params\":{\"name\":\"input.set_selected_block\",\"arguments\":{\"block\":\"橡木原木\"}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":12,\"method\":\"resources/list\"}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":13,\"method\":\"resources/read\",\"params\":{\"uri\":\"cubit://scene/tree\"}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":14,\"method\":\"prompts/list\"}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":15,\"method\":\"prompts/get\",\"params\":{\"name\":\"query-block\",\"arguments\":{\"x\":1,\"y\":2,\"z\":3}}}");
    var scenePath = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "cubit_mcp_test.cscene");
    var projectPath = Path.Combine(Path.GetTempPath(), $"cubit_mcp_project_{Guid.NewGuid():N}");
    var escapedProjectPath = projectPath.Replace("\\", "\\\\");
    var expectedMcpRootChildren = CaptureRootChildSignatures(scene.Tree.Root);
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":16,\"method\":\"tools/call\",\"params\":{\"name\":\"scene.add_node\",\"arguments\":{\"parentPath\":\"/Root\",\"type\":\"Camera3D\",\"name\":\"TestCam\"}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":17,\"method\":\"tools/call\",\"params\":{\"name\":\"scene.get_tree\",\"arguments\":{}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":18,\"method\":\"tools/call\",\"params\":{\"name\":\"scene.remove_node\",\"arguments\":{\"nodePath\":\"/Root/TestCam\"}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":19,\"method\":\"tools/call\",\"params\":{\"name\":\"scene.save\",\"arguments\":{\"path\":\"" + scenePath.Replace("\\", "\\\\") + "\"}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":20,\"method\":\"tools/call\",\"params\":{\"name\":\"scene.load\",\"arguments\":{\"path\":\"" + scenePath.Replace("\\", "\\\\") + "\"}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":21,\"method\":\"tools/call\",\"params\":{\"name\":\"project.create\",\"arguments\":{\"path\":\"" + escapedProjectPath + "\",\"name\":\"MCP 测试项目\"}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":22,\"method\":\"tools/call\",\"params\":{\"name\":\"project.create\",\"arguments\":{\"path\":\"" + escapedProjectPath + "\"}}}");
    sb.AppendLine("{\"jsonrpc\":\"2.0\",\"id\":23,\"method\":\"tools/call\",\"params\":{\"name\":\"audio.status\",\"arguments\":{}}}");

    using var input = new MemoryStream(System.Text.Encoding.UTF8.GetBytes(sb.ToString()));
    using var output = new MemoryStream();
    using (var server = new McpServer(host, input, output))
    {
        server.Run();
    }

    var lines = System.Text.Encoding.UTF8.GetString(output.ToArray()).Split('\n', StringSplitOptions.RemoveEmptyEntries);
    Check("响应行数 = 请求数", lines.Length == 23, $"n={lines.Length}");

    var byId = new Dictionary<int, string>();
    foreach (var line in lines)
    {
        using var doc = JsonDocument.Parse(line);
        if (doc.RootElement.TryGetProperty("id", out var idEl) && idEl.TryGetInt32(out var id))
        {
            byId[id] = line;
        }
    }
    Check("23 个响应均有 id", byId.Count == 23);

    string? TextOf(int id)
    {
        if (!byId.TryGetValue(id, out var line)) return null;
        using var doc = JsonDocument.Parse(line);
        if (doc.RootElement.TryGetProperty("result", out var res)
            && res.TryGetProperty("content", out var content)
            && content[0].TryGetProperty("text", out var text))
        {
            return text.GetString();
        }

        return null;
    }

    bool IsErrorOf(int id)
    {
        using var doc = JsonDocument.Parse(byId[id]);
        if (doc.RootElement.TryGetProperty("error", out _))
        {
            return true;
        }

        return doc.RootElement.GetProperty("result").GetProperty("isError").GetBoolean();
    }

    using (var doc0 = JsonDocument.Parse(byId[1]))
    {
        var pv = doc0.RootElement.GetProperty("result").GetProperty("protocolVersion").GetString();
        Check("initialize 协议版本", pv == McpServer.ProtocolVersion, $"pv={pv}");
    }

    using (var doc1 = JsonDocument.Parse(byId[2]))
    {
        var tools = doc1.RootElement.GetProperty("result").GetProperty("tools");
        var names = tools.EnumerateArray()
            .Select(tool => tool.GetProperty("name").GetString())
            .ToArray();
        Check("tools/list ≥ 15 个工具", tools.GetArrayLength() >= 15, $"n={tools.GetArrayLength()}");
        Check("tools/list 包含 project.create", names.Contains("project.create"));
    }

    var tree = TextOf(3);
    Check("scene.get_tree 返回场景树", tree is not null && tree.Contains("Root") && tree.Contains("World"), tree ?? "null");
    var block = TextOf(4);
    Check("world.get_block 返回草方块", block is not null && block.Contains("草方块"), block ?? "null");
    var status = TextOf(5);
    Check("run.status 返回运行状态", status is not null && status.Contains("tickRate"), status ?? "null");
    Check("run.pause 生效", TextOf(6) == "ok");
    Check("scene.set_property 生效", TextOf(7) == "ok");
    var prop = TextOf(8);
    Check("scene.get_property 回读 2", prop is not null && prop.Contains("2"), prop ?? "null");
    Check("input.set_action 生效", TextOf(9) == "ok", TextOf(9) ?? "null");
    var snapshot = TextOf(10);
    Check("input.snapshot 反映动作", snapshot is not null && snapshot.Contains("\"forward\":true"), snapshot ?? "null");
    Check("input.set_selected_block 生效", TextOf(11) == "ok", TextOf(11) ?? "null");
    using (var docR = JsonDocument.Parse(byId[12]))
    {
        var n = docR.RootElement.GetProperty("result").GetProperty("resources").GetArrayLength();
        Check("resources/list 包含 composer 状态共 5 个资源", n == 5, $"n={n}");
    }
    using (var docP = JsonDocument.Parse(byId[14]))
    {
        var n = docP.RootElement.GetProperty("result").GetProperty("prompts").GetArrayLength();
        Check("prompts/list 返回 5 个提示词", n == 5, $"n={n}");
    }
    using (var docP2 = JsonDocument.Parse(byId[15]))
    {
        var text = docP2.RootElement.GetProperty("result").GetProperty("messages")[0].GetProperty("content").GetProperty("text").GetString() ?? "";
        Check("prompts/get 返回模板并嵌入参数", text.Contains("world.get_block") && text.Contains("(x=1, y=2, z=3)"), text);
    }
    Check("scene.add_node 生效", TextOf(16)?.Contains("ok") == true, TextOf(16) ?? "null");
    var treeAfterAdd = TextOf(17);
    Check("scene.get_tree 含新节点", treeAfterAdd is not null && treeAfterAdd.Contains("TestCam"), treeAfterAdd ?? "null");
    Check("scene.remove_node 生效", TextOf(18) == "ok", TextOf(18) ?? "null");
    Check("scene.save 生效", TextOf(19)?.StartsWith("saved:") == true, TextOf(19) ?? "null");
    var preview = TextOf(20);
    var hasProtocolPreviewChildCount = TryReadSceneSummaryChildCount(preview, out var protocolPreviewChildCount);
    var rootNodesBeforeDirectPreview = scene.Tree.Root.Children.ToArray();
    var directPreview = gameHost.LoadScene(scenePath, apply: false);
    var hasDirectPreviewChildCount = TryReadSceneSummaryChildCount(directPreview, out var directPreviewChildCount);
    Check(
        "scene.load 预览保持已保存的根节点集合",
        hasProtocolPreviewChildCount && protocolPreviewChildCount == expectedMcpRootChildren.Length &&
        hasDirectPreviewChildCount && directPreviewChildCount == rootNodesBeforeDirectPreview.Length &&
        HasRootChildSignatures(scene.Tree.Root, expectedMcpRootChildren) &&
        scene.Tree.Root.Children.SequenceEqual(rootNodesBeforeDirectPreview),
        $"expected={string.Join(',', expectedMcpRootChildren)} protocolChildren={protocolPreviewChildCount} directChildren={directPreviewChildCount} actual={string.Join(',', CaptureRootChildSignatures(scene.Tree.Root))}");
    using (var docR2 = JsonDocument.Parse(byId[13]))
    {
        var resText = docR2.RootElement.GetProperty("result").GetProperty("contents")[0].GetProperty("text").GetString() ?? "";
        Check("resources/read 返回场景树", resText.Contains("Root") && resText.Contains("World"), resText[..Math.Min(60, resText.Length)]);
    }

    Check("project.create 首次调用成功", !IsErrorOf(21), TextOf(21) ?? "null");
    if (Directory.Exists(projectPath))
    {
        var createdProject = ProjectIO.Load(projectPath);
        var createdRoot = SceneIO.LoadFromJson(createdProject.MainScenePath, new SceneRegistry());
        Check("project.create 通过真实 MCP 创建项目",
            createdProject.Manifest.Name == "MCP 测试项目" &&
            createdRoot.Name == "Root" &&
            createdRoot.Children.Count == 0);
    }
    else
    {
        Check("project.create 通过真实 MCP 创建项目", false, "项目目录未创建");
    }
    Check("project.create 重复调用不覆盖", IsErrorOf(22), TextOf(22) ?? "null");
    Check("示例 MCP Audio 适配器可读取服务状态", TextOf(23)?.Contains("activeVoiceCount") == true, TextOf(23) ?? "null");

    if (Directory.Exists(projectPath)) Directory.Delete(projectPath, true);
    if (File.Exists(scenePath)) File.Delete(scenePath);
    scene.Dispose();

    Console.WriteLine(failures == 0 ? "mcpcheck 全部通过" : $"mcpcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int McpDispatchCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var inner = new McpDispatchProbeHost();
    var host = new McpEngineHostWithExtensions(inner, []);
    using var server = new McpServer(host, Stream.Null, Stream.Null);
    var response = server.HandleRequest("{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/call\",\"params\":{\"name\":\"engine.info\",\"arguments\":{}}}");

    Check(
        "MCP 请求经组合宿主调度到所有者线程",
        inner.DispatchCount == 1 && inner.HandlerThreadId == Environment.CurrentManagedThreadId,
        $"dispatches={inner.DispatchCount} handlerThread={inner.HandlerThreadId}");
    var probeResponse = false;
    if (response is not null)
    {
        using var document = JsonDocument.Parse(response);
        probeResponse = document.RootElement
            .GetProperty("result")
            .GetProperty("content")[0]
            .GetProperty("text")
            .GetString() == "{\"engine\":\"probe\"}";
    }

    Check("经调度的请求仍返回 MCP 响应", probeResponse, response ?? "null");

    using var dispatcher = new MainThreadMcpDispatcher(TimeSpan.FromSeconds(1), maximumPendingRequests: 4);
    var executionThread = 0;
    var queued = Task.Run(() => dispatcher.DispatchMcpRequest(() =>
    {
        executionThread = Environment.CurrentManagedThreadId;
        return "queued";
    }));
    var deadline = DateTime.UtcNow.AddSeconds(1);
    while (!queued.IsCompleted && DateTime.UtcNow < deadline)
    {
        dispatcher.Pump();
        Thread.Sleep(1);
    }

    Check(
        "后台请求由主线程 Pump 执行",
        queued.IsCompletedSuccessfully && queued.Result == "queued" && executionThread == dispatcher.OwnerThreadId,
        $"completed={queued.IsCompletedSuccessfully} executionThread={executionThread} owner={dispatcher.OwnerThreadId}");

    var toggleExtension = new ToggleMcpExtension();
    var dynamicHost = new McpEngineHostWithExtensions(new McpDispatchProbeHost(), [toggleExtension]);
    using var dynamicServer = new McpServer(dynamicHost, Stream.Null, Stream.Null);
    var beforeToggle = dynamicServer.HandleRequest("{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/list\"}") ?? "";
    toggleExtension.Enabled = true;
    var afterToggle = dynamicServer.HandleRequest("{\"jsonrpc\":\"2.0\",\"id\":3,\"method\":\"tools/list\"}") ?? "";
    Check(
        "MCP 工具能力随宿主运行状态重新计算",
        !beforeToggle.Contains("test.toggle", StringComparison.Ordinal) && afterToggle.Contains("test.toggle", StringComparison.Ordinal),
        $"before={beforeToggle.Contains("test.toggle", StringComparison.Ordinal)} after={afterToggle.Contains("test.toggle", StringComparison.Ordinal)}");

    Console.WriteLine(failures == 0 ? "mcpdispatchcheck 全部通过" : $"mcpdispatchcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int McpModulesCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    Assembly? extensionsAssembly;
    try
    {
        extensionsAssembly = Assembly.Load("Cubit.Mcp.OfficialModules");
    }
    catch (FileNotFoundException)
    {
        extensionsAssembly = null;
    }

    Check(
        "官方模块 MCP 适配程序集可加载",
        extensionsAssembly is not null,
        "Cubit.Mcp.OfficialModules");
    if (extensionsAssembly is null)
    {
        Console.WriteLine($"mcpmodulescheck 失败 {failures} 项");
        return 1;
    }

    var extensionType = extensionsAssembly.GetType("Cubit.Mcp.OfficialModules.OfficialModulesMcpExtension");
    var contentImporterInfoType = typeof(McpContentImporterInfo);
    var compositeHostType = typeof(McpServer).Assembly.GetType("Cubit.Mcp.McpEngineHostWithExtensions");
    Check(
        "官方模块 MCP 扩展类型实现 IMcpExtensionProvider",
        extensionType is not null && typeof(IMcpExtensionProvider).IsAssignableFrom(extensionType),
        extensionType?.FullName ?? "missing");
    Check(
        "内容 MCP 通过独立 adapter 的宿主描述导入器而不扩展 ContentService API",
        contentImporterInfoType.Assembly.GetName().Name == "Cubit.Mcp.Content",
        contentImporterInfoType.FullName ?? "missing");
    Check(
        "MCP 宿主支持叠加多个领域扩展",
        compositeHostType is not null && typeof(IMcpEngineHost).IsAssignableFrom(compositeHostType) &&
        typeof(IMcpExtensionProvider).IsAssignableFrom(compositeHostType),
        compositeHostType?.FullName ?? "missing");
    var toolProgramPath = Path.Combine(Directory.GetCurrentDirectory(), "tools", "Cubit.Tool", "Program.cs");
    var toolProgramSource = File.Exists(toolProgramPath) ? File.ReadAllText(toolProgramPath) : "";
    var legacyOfficialModulesConstructor = "new OfficialModules" + "McpExtension(scene.Tree, scene.AudioServer)";
    Check(
        "Tool MCP 入口通过项目 composer 装配官方 adapter",
        toolProgramSource.Contains("ComposeProjectMcpExtensions(scene)", StringComparison.Ordinal) &&
        !toolProgramSource.Contains(legacyOfficialModulesConstructor, StringComparison.Ordinal) &&
        toolProgramSource.Contains("new McpEngineHostWithExtensions(", StringComparison.Ordinal),
        toolProgramPath);
    var sampleProjectPath = Path.GetFullPath(Path.Combine(Directory.GetCurrentDirectory(), "hosts", "Cubit.Sample", "Cubit.Sample.csproj"));
    var sampleProgramPath = Path.GetFullPath(Path.Combine(Directory.GetCurrentDirectory(), "hosts", "Cubit.Sample", "Program.cs"));
    var voxelProjectDirectory = Path.GetFullPath(Path.Combine(Directory.GetCurrentDirectory(), "..", "我的第一个cubit项目", "src"));
    var voxelProjectPath = Path.Combine(voxelProjectDirectory, "MyFirstCubitProject.csproj");
    var voxelRuntimeBootstrapPath = Path.Combine(voxelProjectDirectory, "RuntimeBootstrap.cs");
    var voxelProjectSource = File.Exists(voxelProjectPath) ? File.ReadAllText(voxelProjectPath) : "";
    var voxelRuntimeBootstrapSource = File.Exists(voxelRuntimeBootstrapPath) ? File.ReadAllText(voxelRuntimeBootstrapPath) : "";
    var sampleProgramSource = File.Exists(sampleProgramPath) ? File.ReadAllText(sampleProgramPath) : "";
    Check(
        "体素项目 runtime 以独立 Voxel 和 Audio MCP 适配包公开已声明模块",
        voxelProjectSource.Contains("Cubit.Mcp.Audio", StringComparison.Ordinal) &&
        voxelProjectSource.Contains("Cubit.Mcp.Voxel", StringComparison.Ordinal) &&
        voxelRuntimeBootstrapSource.Contains("IProjectMcpExtensionSource", StringComparison.Ordinal) &&
        voxelRuntimeBootstrapSource.Contains("new VoxelMcpProjectExtensionModule()", StringComparison.Ordinal) &&
        voxelRuntimeBootstrapSource.Contains("new AudioMcpProjectExtensionModule()", StringComparison.Ordinal) &&
        sampleProgramSource.Contains("McpProjectExtensionComposer.Compose", StringComparison.Ordinal) &&
        sampleProgramSource.Contains("new McpEngineHostWithExtensions(", StringComparison.Ordinal) &&
        !sampleProgramSource.Contains("VoxelMcpProjectExtensionModule", StringComparison.Ordinal) &&
        !sampleProgramSource.Contains("AudioMcpProjectExtensionModule", StringComparison.Ordinal),
        voxelRuntimeBootstrapPath);
    if (extensionType is null || compositeHostType is null ||
        !typeof(IMcpExtensionProvider).IsAssignableFrom(extensionType))
    {
        Console.WriteLine($"mcpmodulescheck 失败 {failures} 项");
        return 1;
    }

    var projectRoot = Path.Combine(Path.GetTempPath(), $"cubit_mcp_modules_{Guid.NewGuid():N}");
    AudioServer? audioServer = null;
    try
    {
        var createdProject = ProjectIO.Create(projectRoot, "MCP 官方模块检查");
        var manifest = new CubitProjectManifest
        {
            FormatVersion = ProjectIO.CurrentFormatVersion,
            Name = createdProject.Manifest.Name,
            MainScene = createdProject.Manifest.MainScene,
            Plugins =
            [
                new CubitPluginReference { Id = "cubit.physics", Version = "1.0.0" },
                new CubitPluginReference { Id = "cubit.animation", Version = "1.0.0" },
                new CubitPluginReference { Id = "cubit.audio", Version = "1.0.0" },
                new CubitPluginReference { Id = "cubit.content", Version = "1.0.0" },
                new CubitPluginReference { Id = "cubit.scripting", Version = "1.0.0" },
            ],
        };
        File.WriteAllText(createdProject.ManifestPath, JsonSerializer.Serialize(manifest));
        var project = ProjectIO.Load(projectRoot);
        using var moduleTree = new SceneTree();
        var root = new Node { Name = "Root" };
        root.AddChild(new PhysicsWorld3D { Name = "Physics" });
        root.AddChild(new AnimationPlayer { Name = "Animations" });
        root.AddChild(new EcsNode { Name = "Ecs" });
        moduleTree.ReplaceChildren(root);

        audioServer = new AudioServer(null, new DiagnosticBag());
        var contentService = new ContentService([new SceneJsonContentImporter()]);
        using var scriptRuntime = new ScriptRuntime(moduleTree, project.RootDirectory, new DiagnosticBag());
        var contentImporterInfo = new McpContentImporterInfo(
            "cubit.scene-json",
            "1.0.0",
            [".cscene"]);
        IReadOnlyList<McpContentImporterInfo> contentImporters = [contentImporterInfo];

        Check("内容 MCP 导入器描述可由宿主提供", contentImporterInfo.Extensions.Count == 1);
        Check("内容 MCP 导入器扩展名是不可变快照", contentImporterInfo.Extensions is IList<string> { IsReadOnly: true });
        var runtimeContext = new EngineContext()
            .AddService(audioServer)
            .AddService(contentService)
            .AddService(scriptRuntime);
        var projectContext = new McpProjectExtensionContext
        {
            Project = project,
            Tree = moduleTree,
            EngineContext = runtimeContext,
            ResolveRuntimeService = type => type == typeof(AudioServer)
                ? runtimeContext.TryGetService<AudioServer>(out var resolvedAudio) ? resolvedAudio : null
                : type == typeof(ContentService)
                    ? runtimeContext.TryGetService<ContentService>(out var resolvedContent) ? resolvedContent : null
                    : type == typeof(ScriptRuntime)
                        ? runtimeContext.TryGetService<ScriptRuntime>(out var resolvedRuntime) ? resolvedRuntime : null
                        : null,
        };
        IMcpProjectExtensionModule[] modules =
        [
            new PhysicsMcpProjectExtensionModule(),
            new AnimationMcpProjectExtensionModule(),
            new AudioMcpProjectExtensionModule(),
            new ContentMcpProjectExtensionModule(contentImporters),
            new ScriptingMcpProjectExtensionModule(),
            new EcsMcpProjectExtensionModule(),
        ];
        var extension = Activator.CreateInstance(
            extensionType,
            projectContext,
            modules) as IMcpExtensionProvider;
        Check("官方模块 facade 组合已链接 adapter 而不创建服务", extension is not null);
        if (extension is null)
        {
            Console.WriteLine($"mcpmodulescheck 失败 {failures} 项");
            return 1;
        }

        var baseHost = new McpDispatchProbeHost(moduleTree);
        var providers = new[] { extension };
        var compositeHost = Activator.CreateInstance(compositeHostType, baseHost, providers) as IMcpEngineHost;
        Check("组合宿主保留基础 MCP 宿主能力", compositeHost is not null);
        if (compositeHost is null)
        {
            Console.WriteLine($"mcpmodulescheck 失败 {failures} 项");
            return 1;
        }

        using var server = new McpServer(compositeHost, Stream.Null, Stream.Null);
        var listResponse = server.HandleRequest("{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/list\"}");
        var names = new HashSet<string>(StringComparer.Ordinal);
        if (listResponse is not null)
        {
            using var listDocument = JsonDocument.Parse(listResponse);
            foreach (var tool in listDocument.RootElement.GetProperty("result").GetProperty("tools").EnumerateArray())
            {
                if (tool.GetProperty("name").GetString() is { } name)
                {
                    names.Add(name);
                }
            }
        }

        var expectedTools = new[]
        {
            "physics.list_worlds", "physics.raycast", "animation.list_players", "animation.play", "animation.pause", "animation.stop", "animation.seek",
            "audio.status", "audio.list_buses", "audio.set_bus_volume", "audio.set_bus_muted", "audio.list_players", "audio.play_player", "audio.stop_player",
            "content.list_importers", "content.import", "scripting.status", "scripting.stop", "ecs.list_nodes",
        };
        Check(
            "官方模块工具完整注册到同一 MCP 宿主",
            expectedTools.All(names.Contains),
            $"missing={string.Join(',', expectedTools.Where(name => !names.Contains(name)))}");

        string? CallTool(string name, string arguments = "{}")
        {
            var response = server.HandleRequest($"{{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/call\",\"params\":{{\"name\":\"{name}\",\"arguments\":{arguments}}}}}");
            if (response is null)
            {
                return null;
            }

            using var document = JsonDocument.Parse(response);
            return document.RootElement.GetProperty("result").GetProperty("content")[0].GetProperty("text").GetString();
        }

        Check("Physics MCP 返回已存在的物理世界", CallTool("physics.list_worlds")?.Contains("/Root/Physics") == true);
        Check("Animation MCP 返回已存在的播放器", CallTool("animation.list_players")?.Contains("/Root/Animations") == true);
        Check("Audio MCP 返回服务状态", CallTool("audio.status")?.Contains("activeVoiceCount") == true);
        Check("Content MCP 返回已注册导入器", CallTool("content.list_importers")?.Contains("scene-json") == true);
        Check("Scripting MCP 只报告未运行状态", CallTool("scripting.status")?.Contains("\"isRunning\":false") == true);
        Check("ECS MCP 返回已存在的 EcsNode", CallTool("ecs.list_nodes")?.Contains("/Root/Ecs") == true);
        Check("核心与官方模块工具指向同一作者场景", CallTool("scene.get_tree")?.Contains("/Root/Physics") == true);

        var audioOnlyRuntimeContext = new EngineContext().AddService(audioServer);
        var audioOnlyProjectContext = new McpProjectExtensionContext
        {
            Project = project,
            Tree = moduleTree,
            EngineContext = audioOnlyRuntimeContext,
            ResolveRuntimeService = type => type == typeof(AudioServer) &&
                audioOnlyRuntimeContext.TryGetService<AudioServer>(out var resolvedAudio)
                ? resolvedAudio
                : null,
        };
        var audioOnlyExtension = Activator.CreateInstance(
            extensionType,
            audioOnlyProjectContext,
            modules) as IMcpExtensionProvider;
        var audioOnlyHost = audioOnlyExtension is null
            ? null
            : Activator.CreateInstance(compositeHostType, baseHost, new[] { audioOnlyExtension }) as IMcpEngineHost;
        var audioOnlyNames = new HashSet<string>(StringComparer.Ordinal);
        if (audioOnlyHost is not null)
        {
            using var audioOnlyServer = new McpServer(audioOnlyHost, Stream.Null, Stream.Null);
            var audioOnlyResponse = audioOnlyServer.HandleRequest("{\"jsonrpc\":\"2.0\",\"id\":3,\"method\":\"tools/list\"}");
            if (audioOnlyResponse is not null)
            {
                using var audioOnlyDocument = JsonDocument.Parse(audioOnlyResponse);
                foreach (var tool in audioOnlyDocument.RootElement.GetProperty("result").GetProperty("tools").EnumerateArray())
                {
                    if (tool.GetProperty("name").GetString() is { } name)
                    {
                        audioOnlyNames.Add(name);
                    }
                }
            }
        }

        Check(
            "未注入的官方服务不向 MCP 宣称可用",
            audioOnlyNames.Contains("audio.status") &&
            !audioOnlyNames.Contains("content.import") &&
            !audioOnlyNames.Contains("scripting.status"),
            $"tools={string.Join(',', audioOnlyNames.OrderBy(name => name, StringComparer.Ordinal))}");
    }
    finally
    {
        audioServer?.Dispose();
        if (Directory.Exists(projectRoot))
        {
            Directory.Delete(projectRoot, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "mcpmodulescheck 全部通过" : $"mcpmodulescheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int TickCheck(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    // 1) 计划刻：5 tick 后触发一次且只触发一次
    var world = new VoxelWorld(seed, WorldType.Flat);
    world.GenerateAround(0, 0, 1);
    var scheduledHits = new List<(int X, int Y, int Z, long Tick)>();
    world.OnBlockScheduledTick += (_, x, y, z) => scheduledHits.Add((x, y, z, world.TickCount));
    world.ScheduleTick(24, 5, 24, 5);
    for (var i = 0; i < 10; i++) world.Tick();
    Check("计划刻 5 tick 后触发一次",
        scheduledHits.Count == 1 && scheduledHits[0].Tick == 5 && scheduledHits[0].X == 24,
        $"hits={scheduledHits.Count} tick={(scheduledHits.Count > 0 ? scheduledHits[0].Tick : -1)}");

    // 2) 随机刻确定性：同种子同 tick 序列一致，异种子不同
    static int[] RunRandomTrace(uint s)
    {
        var w = new VoxelWorld(s, WorldType.Flat);
        w.GenerateAround(0, 0, 1);
        var trace = new List<int>();
        w.OnBlockRandomTick += (_, x, y, z) => trace.Add(x * 100000 + y * 1000 + z);
        for (var i = 0; i < 20; i++) w.Tick();
        return trace.ToArray();
    }
    var t1 = RunRandomTrace(seed);
    var t2 = RunRandomTrace(seed);
    var t3 = RunRandomTrace(seed + 1);
    Check("随机刻同种子确定性", t1.Length == t2.Length && t1.SequenceEqual(t2), $"n={t1.Length}");
    Check("随机刻异种子不同", !t1.SequenceEqual(t3) || t3.Length == 0, $"n1={t1.Length} n3={t3.Length}");

    // 3) BlockEntity 框架：注册测试实体并确定性 tick
    BlockEntityRegistry.Register(BlockRegistry.Grass, () => new TickProbeEntity());
    var w2 = new VoxelWorld(seed, WorldType.Flat);
    w2.GenerateAround(0, 0, 1);
    var entity = w2.AddBlockEntity(BlockRegistry.Grass, 24, 5, 24);
    Check("BlockEntity 创建并定位", entity is TickProbeEntity { X: 24, Y: 5, Z: 24 });
    for (var i = 0; i < 40; i++) w2.Tick();
    Check("BlockEntity 每 tick 驱动", entity is TickProbeEntity { Ticks: 40 }, $"ticks={(entity as TickProbeEntity)?.Ticks}");

    Console.WriteLine(failures == 0 ? "tickcheck 全部通过" : $"tickcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int FrustumCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    // 固定相机（与 Camera3D 默认一致）：位置 (24,34,24)，yaw=π/4，pitch=-0.35，FOV 70°，16:9
    var camera = new FlyCamera(new Vector3(24f, 34f, 24f), MathF.PI * 0.25f, -0.35f);
    var vp = camera.ViewMatrix * camera.ProjectionMatrix(16f / 9f);
    var frustum = new Frustum(vp);

    // 1) 前方点必在视锥内（可见必画）
    var front = camera.Position + camera.Forward * 10f;
    Check("前方点在视锥内（可见必画）", frustum.Contains(front), $"p=({front.X:F1},{front.Y:F1},{front.Z:F1})");

    // 2) 正后方点必被剔除（不可见必剔）
    var behind = camera.Position - camera.Forward * 10f;
    Check("正后方点被剔除（不可见必剔）", !frustum.Contains(behind), $"p=({behind.X:F1},{behind.Y:F1},{behind.Z:F1})");

    // 3) 相机所在区块（16..32, MinY..MaxYExclusive, 16..32）必与视锥相交
    Check("相机所在区块必可见", frustum.Intersects(new Vector3(16f, Chunk.MinY, 16f), new Vector3(32f, Chunk.MaxYExclusive, 32f)));

    // 4) 远处侧后方区块必被剔除
    var behindMin = new Vector3(camera.Position.X - 200f, Chunk.MinY, camera.Position.Z - 200f);
    Check("远处侧后方区块被剔除", !frustum.Intersects(behindMin, behindMin + new Vector3(16f, Chunk.SizeY, 16f)));

    // 5) 视线方向 30 格外的区块必可见
    var aheadMin = camera.Position + camera.Forward * 30f - new Vector3(8f, 0f, 8f);
    aheadMin.Y = Chunk.MinY;
    Check("前方 30 格区块必可见", frustum.Intersects(aheadMin, aheadMin + new Vector3(16f, Chunk.SizeY, 16f)));

    // 6) 确定性：同矩阵两次构造结果一致
    var frustum2 = new Frustum(vp);
    Check("同矩阵构造结果一致", frustum2.Contains(front) == frustum.Contains(front));

    Console.WriteLine(failures == 0 ? "frustumcheck 全部通过" : $"frustumcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int LightCheck(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    // 平坦世界天空光
    var flat = new VoxelWorld(seed, WorldType.Flat);
    flat.GenerateAround(0, 0, 1);
    var skyAboveFlat = LightingEngine.GetLight(flat.Store, 24, WorldGenerator.FlatLayers.Length, 24).Sky;
    var skyGrassFlat = LightingEngine.GetLight(flat.Store, 24, WorldGenerator.FlatLayers.Length - 1, 24).Sky;
    var skyDirtFlat = LightingEngine.GetLight(flat.Store, 24, WorldGenerator.FlatLayers.Length - 2, 24).Sky;
    Check("平坦：地表上方天空光 15", skyAboveFlat == 15, $"sky={skyAboveFlat}");
    Check("平坦：不透明地表不保存天空光", skyGrassFlat == 0 && skyAboveFlat == 15, $"grass={skyGrassFlat} above={skyAboveFlat}");
    Check("平坦：地表下方天空光 0", skyDirtFlat == 0, $"dirt={skyDirtFlat}");

    // 噪声世界天空光（露空=15，不透明体素本身与地下=0）
    var world = new VoxelWorld(seed);
    world.GenerateAround(0, 0, 1);
    var groundY = WorldGenerator.GetHeight(24, 24, seed);
    var skyExposed = LightingEngine.GetLight(world.Store, 24, groundY + 1, 24).Sky;
    var skySurface = LightingEngine.GetLight(world.Store, 24, groundY, 24).Sky;
    var skyBelow = LightingEngine.GetLight(world.Store, 24, groundY - 1, 24).Sky;
    Check("噪声：露空方块天空光 15", skyExposed == 15, $"sky={skyExposed} y={groundY + 1}");
    Check("噪声：不透明地表不保存天空光", skySurface == 0, $"surface={skySurface}");
    Check("噪声：地下天空光 0", skyBelow == 0, $"below={skyBelow}");

    var monotonic = true;
    for (var y = Chunk.MaxYExclusive - 1; y > groundY + 1; y--)
    {
        if (LightingEngine.GetLight(world.Store, 24, y, 24).Sky != 15)
        {
            monotonic = false;
            break;
        }
    }
    Check("噪声：露空列天空光恒定 15", monotonic);

    // 天空光穿过开口后要向侧面散射；屋檐下不是 0，也不能与露天空气同为 15。
    var overhangStore = new ChunkStore();
    var overhangChunk = new Chunk();
    overhangChunk.SetBlock(9, 10, 8, BlockRegistry.GetState(BlockRegistry.Stone));
    overhangStore.AddChunk(0, 0, overhangChunk);
    LightingEngine.RelightChunk(overhangStore, 0, 0);
    var skyBesideOverhang = LightingEngine.GetLight(overhangStore, 8, 9, 8).Sky;
    var skyUnderOverhang = LightingEngine.GetLight(overhangStore, 9, 9, 8).Sky;
    var skyInRoof = LightingEngine.GetLight(overhangStore, 9, 10, 8).Sky;
    Check(
        "屋檐下接收一级衰减的侧向天空光",
        skyBesideOverhang == LightingEngine.MaxLight && skyUnderOverhang == LightingEngine.MaxLight - 1,
        $"beside={skyBesideOverhang} under={skyUnderOverhang}");
    Check("屋檐方块自身不成为天空光源", skyInRoof == 0, $"roof={skyInRoof}");

    // 相邻区块的露天空气也必须能照入整片屋顶下方，不能因 16 格边界断光。
    var crossChunkStore = new ChunkStore();
    var westChunk = new Chunk();
    var eastChunk = new Chunk();
    for (var localX = 0; localX < Chunk.SizeX; localX++)
    {
        for (var localZ = 0; localZ < Chunk.SizeZ; localZ++)
        {
            eastChunk.SetBlock(localX, 10, localZ, BlockRegistry.GetState(BlockRegistry.Stone));
        }
    }

    crossChunkStore.AddChunk(0, 0, westChunk);
    crossChunkStore.AddChunk(1, 0, eastChunk);
    LightingEngine.RelightChunk(crossChunkStore, 0, 0);
    LightingEngine.RelightChunk(crossChunkStore, 1, 0);
    var skyAcrossChunkBoundary = LightingEngine.GetLight(crossChunkStore, 16, 9, 8).Sky;
    Check(
        "天空光跨区块侧向传播不断光",
        skyAcrossChunkBoundary == LightingEngine.MaxLight - 1,
        $"sky={skyAcrossChunkBoundary}");

    // 在边界放置遮挡块后，邻区不能继续保留旧的 14 级天空光。
    var runtimeBoundaryWorld = new VoxelWorld(seed, WorldType.Flat);
    var runtimeWestChunk = new Chunk();
    var runtimeEastChunk = new Chunk();
    for (var localX = 0; localX < Chunk.SizeX; localX++)
    {
        for (var localZ = 0; localZ < Chunk.SizeZ; localZ++)
        {
            runtimeEastChunk.SetBlock(localX, 10, localZ, BlockRegistry.GetState(BlockRegistry.Stone));
        }
    }

    runtimeBoundaryWorld.Store.AddChunk(0, 0, runtimeWestChunk);
    runtimeBoundaryWorld.Store.AddChunk(1, 0, runtimeEastChunk);
    LightingEngine.RelightChunk(runtimeBoundaryWorld.Store, 0, 0);
    LightingEngine.RelightChunk(runtimeBoundaryWorld.Store, 1, 0);
    var placedBoundaryRoof = runtimeBoundaryWorld.SetBlockDeferred(15, 10, 8, BlockRegistry.GetState(BlockRegistry.Stone), out var boundaryAffected);
    var skyAfterBoundaryPlacement = LightingEngine.GetLight(runtimeBoundaryWorld.Store, 16, 9, 8).Sky;
    Check(
        "边界挖放同步相邻区块天空光",
        placedBoundaryRoof && boundaryAffected.Contains((1, 0)) && skyAfterBoundaryPlacement == LightingEngine.MaxLight - 2,
        $"sky={skyAfterBoundaryPlacement} affected={string.Join(',', boundaryAffected.Select(key => $"({key.X},{key.Z})"))}");

    // 普通放置不能把旧的天空光保留在不透明方块内，否则会造成材质异常偏亮。
    var placedBlockWorld = new VoxelWorld(seed, WorldType.Flat);
    placedBlockWorld.GenerateAround(0, 0, 0);
    var placedOpaque = placedBlockWorld.SetBlockDeferred(8, 12, 8, BlockRegistry.GetState(BlockRegistry.Stone), out _);
    var placedOpaqueSky = LightingEngine.GetLight(placedBlockWorld.Store, 8, 12, 8).Sky;
    Check("运行时放置的不透明方块不残留天空光", placedOpaque && placedOpaqueSky == 0, $"sky={placedOpaqueSky}");

    // 方块光必须逐格衰减，且移除光源后不能在空气中保留陈旧亮度。
    var emitterId = BlockRegistry.RegisterAuto(new BlockDef
    {
        Id = 0,
        Name = "光照回归光源",
        LightLevel = LightingEngine.MaxLight,
    });
    var blockLightWorld = new VoxelWorld(seed, WorldType.Flat);
    blockLightWorld.GenerateAround(0, 0, 0);
    var emitterPosition = (X: 8, Y: 6, Z: 8);
    var adjacentPosition = (X: 9, Y: 6, Z: 8);
    var placedEmitter = blockLightWorld.SetBlockDeferred(
        emitterPosition.X,
        emitterPosition.Y,
        emitterPosition.Z,
        new BlockState(emitterId),
        out _);
    var sourceLight = LightingEngine.GetLight(
        blockLightWorld.Store,
        emitterPosition.X,
        emitterPosition.Y,
        emitterPosition.Z).Block;
    var adjacentLight = LightingEngine.GetLight(
        blockLightWorld.Store,
        adjacentPosition.X,
        adjacentPosition.Y,
        adjacentPosition.Z).Block;
    Check("方块光源本身为 15", placedEmitter && sourceLight == LightingEngine.MaxLight, $"source={sourceLight}");
    Check("方块光向相邻空气衰减", adjacentLight == LightingEngine.MaxLight - 1, $"adjacent={adjacentLight}");

    var removedEmitter = blockLightWorld.SetBlockDeferred(
        emitterPosition.X,
        emitterPosition.Y,
        emitterPosition.Z,
        BlockState.Air,
        out _);
    var residualSourceLight = LightingEngine.GetLight(
        blockLightWorld.Store,
        emitterPosition.X,
        emitterPosition.Y,
        emitterPosition.Z).Block;
    var residualAdjacentLight = LightingEngine.GetLight(
        blockLightWorld.Store,
        adjacentPosition.X,
        adjacentPosition.Y,
        adjacentPosition.Z).Block;
    Check(
        "移除方块光源后清除陈旧光照",
        removedEmitter && residualSourceLight == 0 && residualAdjacentLight == 0,
        $"source={residualSourceLight} adjacent={residualAdjacentLight}");

    // 在封闭通道中放置普通石头也会改变方块光传播，不能只重算天空光列。
    var tunnelWorld = new VoxelWorld(seed, WorldType.Flat);
    tunnelWorld.GenerateAround(0, 0, 0);
    for (var x = 7; x <= 11; x++)
    {
        tunnelWorld.Store.SetBlock(x, 5, 8, BlockRegistry.GetState(BlockRegistry.Stone));
        tunnelWorld.Store.SetBlock(x, 7, 8, BlockRegistry.GetState(BlockRegistry.Stone));
        tunnelWorld.Store.SetBlock(x, 6, 7, BlockRegistry.GetState(BlockRegistry.Stone));
        tunnelWorld.Store.SetBlock(x, 6, 9, BlockRegistry.GetState(BlockRegistry.Stone));
    }

    tunnelWorld.Store.SetBlock(7, 6, 8, BlockRegistry.GetState(BlockRegistry.Stone));
    tunnelWorld.Store.SetBlock(11, 6, 8, BlockRegistry.GetState(BlockRegistry.Stone));
    LightingEngine.RelightChunk(tunnelWorld.Store, 0, 0);
    _ = tunnelWorld.SetBlockDeferred(8, 6, 8, new BlockState(emitterId), out _);
    var tunnelLitBeforeBlocking = LightingEngine.GetLight(tunnelWorld.Store, 10, 6, 8).Block;
    var placedTunnelBarrier = tunnelWorld.SetBlockDeferred(9, 6, 8, BlockRegistry.GetState(BlockRegistry.Stone), out _);
    var tunnelLightAfterBlocking = LightingEngine.GetLight(tunnelWorld.Store, 10, 6, 8).Block;
    Check(
        "普通不透明方块阻断方块光",
        placedTunnelBarrier && tunnelLitBeforeBlocking == LightingEngine.MaxLight - 2 && tunnelLightAfterBlocking == 0,
        $"before={tunnelLitBeforeBlocking} after={tunnelLightAfterBlocking}");

    Console.WriteLine(failures == 0 ? "lightcheck 全部通过" : $"lightcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int SceneCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    // 1) 树构建、路径、父子关系
    var tree = new SceneTree();
    var world = new Node { Name = "World" };
    var camera = new Node { Name = "Camera" };
    tree.Root.AddChild(world);
    world.AddChild(camera);
    Check("树构建与父子关系", camera.Parent == world && world.Parent == tree.Root && camera.Tree == tree);
    Check("路径解析（绝对/相对）", tree.GetNode("/root/World/Camera") == camera && world.GetNode("Camera") == camera);
    Check("GetPath", camera.GetPath().Value == "/Root/World/Camera", camera.GetPath().Value);

    // 2.1) 固定步输入不变量：频率和帧 delta 不能把累加器推进到 NaN/无效状态。
    var invalidTickRate = CaptureException(() => tree.SimulationTicksPerSecond = 0);
    var negativeDelta = CaptureException(() => tree.ProcessFrame(-1d));
    var nonFiniteDelta = CaptureException(() => tree.ProcessFrame(double.NaN));
    Check(
        "SceneTree 拒绝非正模拟频率",
        invalidTickRate is ArgumentOutOfRangeException,
        invalidTickRate?.GetType().Name ?? "none");
    Check(
        "SceneTree 拒绝负 delta",
        negativeDelta is ArgumentOutOfRangeException,
        negativeDelta?.GetType().Name ?? "none");
    Check(
        "SceneTree 拒绝非有限 delta",
        nonFiniteDelta is ArgumentOutOfRangeException,
        nonFiniteDelta?.GetType().Name ?? "none");

    Exception? offThreadProcessError = null;
    var processThread = new Thread(() =>
        offThreadProcessError = CaptureException(() => tree.ProcessFrame(1d / 60d)));
    processThread.Start();
    processThread.Join();
    Check(
        "SceneTree 只允许所有者线程驱动",
        offThreadProcessError is InvalidOperationException,
        offThreadProcessError?.GetType().Name ?? "none");

    var offThreadChild = new Node { Name = "OffThread" };
    Exception? offThreadMutationError = null;
    var mutationThread = new Thread(() =>
        offThreadMutationError = CaptureException(() => tree.Root.AddChild(offThreadChild)));
    mutationThread.Start();
    mutationThread.Join();
    Check(
        "运行树结构变更拒绝 worker 线程",
        offThreadMutationError is InvalidOperationException && !tree.Root.Children.Contains(offThreadChild),
        offThreadMutationError?.GetType().Name ?? "none");

    // 2) 生命周期顺序：先进树（自上而下），再 Ready（自下而上）
    var order = new List<string>();
    var lifeA = new LifeNode("A", order);
    var lifeB = new LifeNode("B", order);
    lifeA.AddChild(lifeB); // 未进树，不触发
    tree.Root.AddChild(lifeA);
    var expected = "EnterTree:A,EnterTree:B,Ready:B,Ready:A";
    Check("生命周期顺序（EnterTree 顶→底, Ready 底→顶）", string.Join(",", order) == expected, string.Join(",", order));

    // 3) 信号（原生 C# event）
    var emitter = new SignalNode();
    tree.Root.AddChild(emitter);
    var received = 0;
    emitter.Ping += () => received++;
    emitter.EmitPing();
    emitter.EmitPing();
    Check("C# 事件信号", received == 2, $"received={received}");

    // 4) 分组
    var g1 = new Node { Name = "G1" };
    var g2 = new Node { Name = "G2" };
    tree.Root.AddChild(g1);
    tree.Root.AddChild(g2);
    g1.AddToGroup("enemies");
    g2.AddToGroup("enemies");
    Check("分组查询", tree.GetNodesInGroup("enemies").Count == 2);
    g1.RemoveFromGroup("enemies");
    Check("退组", tree.GetNodesInGroup("enemies").Count == 1 && !g1.IsInGroup("enemies"));


    // 5) 固定模拟 tick（60 帧 × 1/60 = 1 秒，默认 20Hz = 20 tick）
    var phys = new PhysNode();
    tree.Root.AddChild(phys);
    for (var i = 0; i < 60; i++)
    {
        tree.ProcessFrame(1.0 / 60.0);
    }
    Check("模拟 tick 1 秒 = 20 次 PhysicsProcess", phys.PhysicsCount == 20, $"physics={phys.PhysicsCount}");
    Check("每帧 Process = 60 次", phys.ProcessCount == 60, $"process={phys.ProcessCount}");
    tree.ProcessFrame(100);
    Check("超大 delta 防螺旋死亡", phys.PhysicsCount <= 20 + 5, $"physics={phys.PhysicsCount}");

    // 5.1) ProcessPriority：数值小者先处理
    var prioOrder = new List<string>();
    var prioA = new PriorityNode("A", 10, prioOrder);
    var prioB = new PriorityNode("B", -5, prioOrder);
    tree.Root.AddChild(prioA);
    tree.Root.AddChild(prioB);
    tree.ProcessFrame(1.0 / 20.0);
    Check("ProcessPriority 小者先处理", string.Join(",", prioOrder) == "B,A", $"order={string.Join(",", prioOrder)}");
    tree.Root.RemoveChild(prioA);
    tree.Root.RemoveChild(prioB);

    // 5.2) 暂停：模拟不推进，Process 仍运行
    tree.Paused = true;
    var physicsBeforePause = phys.PhysicsCount;
    tree.ProcessFrame(1.0);
    tree.Paused = false;
    Check("暂停时模拟不推进", phys.PhysicsCount == physicsBeforePause, $"physics={phys.PhysicsCount}");

    // 6) 资源 JSON 序列化往返
    var res = new TestResource { ResourceName = "测试方块", Value = 42 };
    var json = res.ToJson();
    var back = Resource.FromJson<TestResource>(json);
    Check("资源 JSON 往返", back.ResourceName == "测试方块" && back.Value == 42, "json ok");

    // 7) 移除触发 ExitTree
    var exited = new List<string>();
    var ex = new LifeNode("X", exited);
    tree.Root.AddChild(ex);
    tree.Root.RemoveChild(ex);
    Check("移除触发 ExitTree", exited.Count == 3 && exited[2] == "ExitTree:X", string.Join(",", exited));

    // 7.1) 从反序列化使用的脱离容器取出子节点只是重组，不能伪造退出生命周期。
    var detachedLifecycle = new List<string>();
    var detachedContainer = new Node { Name = "DetachedContainer" };
    var detachedChild = new LifeNode("DetachedChild", detachedLifecycle);
    detachedContainer.AddChild(detachedChild);
    detachedContainer.RemoveChild(detachedChild);
    Check(
        "脱离场景容器移除子节点不触发 ExitTree",
        detachedLifecycle.Count == 0 && detachedChild.Parent is null && detachedChild.Tree is null,
        string.Join(",", detachedLifecycle));

    // 8) BlockDef 资源 JSON 往返
    var blockJson = BlockRegistry.Get(BlockRegistry.Grass).ToJson();
    var blockBack = Resource.FromJson<BlockDef>(blockJson);
    Check("BlockDef 资源 JSON 往返", blockBack.Id == BlockRegistry.Grass && blockBack.Name == "草方块" && blockBack.TopTexture == "grass_block_top");

    // 9) WorldConfig 资源 JSON 往返
    var cfg = new WorldConfig { ResourceName = "默认世界", Seed = 42, WorldType = WorldType.Flat, GenerateRadius = 2 };
    var cfgBack = Resource.FromJson<WorldConfig>(cfg.ToJson());
    Check("WorldConfig 资源 JSON 往返", cfgBack.Seed == 42 && cfgBack.WorldType == WorldType.Flat && cfgBack.GenerateRadius == 2);

    // 10) 场景文件保存/加载（SceneIO）
    var scenePath = Path.Combine(Path.GetTempPath(), "cubit_scenecheck.cscene");
    var sceneRoot = new Node { Name = "Root" };
    sceneRoot.AddChild(new Camera3D { Name = "Camera" });
    sceneRoot.AddChild(new BoxMesh3D { Name = "Box", Size = 7f });
    SceneIO.SaveToJson(sceneRoot, scenePath);
    var loadedScene = SceneIO.LoadFromJson(scenePath, new SceneRegistry());
    var loadedCamera = loadedScene.Children.FirstOrDefault(n => n.Name == "Camera") as Camera3D;
    var loadedBox = loadedScene.Children.FirstOrDefault(n => n.Name == "Box") as BoxMesh3D;
    Check("场景文件保存/加载（类型/名称/[Export]属性/子节点）",
        loadedScene.Children.Count == 2 &&
        loadedCamera is not null &&
        loadedBox is { Size: 7f },
        $"children={loadedScene.Children.Count}");
    File.Delete(scenePath);

    // 11) ReplaceChildren：切换运行树（编辑器地基）
    var replaceOrder = new List<string>();
    var oldA = new LifeNode("OldA", replaceOrder);
    var oldB = new LifeNode("OldB", replaceOrder);
    tree.Root.AddChild(oldA);
    tree.Root.AddChild(oldB);
    var newRoot = new Node { Name = "Root" };
    newRoot.AddChild(new Node { Name = "NewA" });
    newRoot.AddChild(new Node { Name = "NewB" });
    tree.ReplaceChildren(newRoot);
    Check("ReplaceChildren 替换子节点", tree.Root.Children.Count == 2 && tree.Root.Children[0].Name == "NewA" && tree.Root.Children[1].Name == "NewB");
    Check("ReplaceChildren 旧节点 ExitTree 并脱离", oldA.Parent is null && oldA.Tree is null && replaceOrder.Contains("ExitTree:OldA"));
    Check("ReplaceChildren 新节点进树", tree.Root.Children[0].Tree == tree && tree.Root.Children[0].Parent == tree.Root);

    // 11.1) 关闭场景树必须让全部节点退出树，释放流式线程与 GPU/RID 前端资源。
    var disposeOrder = new List<string>();
    var disposableTree = new SceneTree();
    disposableTree.Root.AddChild(new LifeNode("Dispose", disposeOrder));
    disposableTree.Dispose();
    Check(
        "SceneTree.Dispose 触发子节点 ExitTree",
        disposeOrder.Contains("ExitTree:Dispose") && disposableTree.Root.Children.Count == 0,
        string.Join(",", disposeOrder));

    // 12) 场景文件替换运行树（headless：注入渲染服务器后 Ready 建世界）
    var editorRenderer = new FakeRenderBackend();
    using var editorSession = CreateVoxelProjectSession(editorRenderer, 20260808u);
    var gameScene = editorSession.Scene;
    var editorHost = new Cubit.Sample.GameSceneMcpHost(
        gameScene,
        null,
        editorSession.Input);
    var expectedEditorRootChildren = CaptureRootChildSignatures(gameScene.Tree.Root);
    var rootNodesBeforePreview = gameScene.Tree.Root.Children.ToArray();
    var mainSceneUid = SceneIO.GetDocumentUid(File.ReadAllText(gameScene.Runtime.Project.MainScenePath));
    editorHost.SaveScene(gameScene.Runtime.Project.MainScenePath);
    var savedMainSceneUid = SceneIO.GetDocumentUid(File.ReadAllText(gameScene.Runtime.Project.MainScenePath));
    Check(
        "MCP 保存项目主场景保持 UID",
        !string.IsNullOrWhiteSpace(mainSceneUid) && savedMainSceneUid == mainSceneUid,
        $"before={mainSceneUid ?? "missing"} after={savedMainSceneUid ?? "missing"}");
    var editorScenePath = Path.Combine(Path.GetTempPath(), "cubit_editorcheck.cscene");
    editorHost.SaveScene(editorScenePath);
    var preview = editorHost.LoadScene(editorScenePath, false);
    var hasPreviewChildCount = TryReadSceneSummaryChildCount(preview, out var previewChildCount);
    Check(
        "scene.load 预览不改动运行树",
        hasPreviewChildCount && previewChildCount == expectedEditorRootChildren.Length &&
        HasRootChildSignatures(gameScene.Tree.Root, expectedEditorRootChildren) &&
        gameScene.Tree.Root.Children.SequenceEqual(rootNodesBeforePreview),
        $"expected={string.Join(',', expectedEditorRootChildren)} previewChildren={previewChildCount} actual={string.Join(',', CaptureRootChildSignatures(gameScene.Tree.Root))}");
    var applied = editorHost.LoadScene(editorScenePath, true);
    var appliedWorld = gameScene.Tree.GetNode("/Root/World") as Cubit.Voxel.World.VoxelWorldNode;
    var rootNodesBeforeApply = rootNodesBeforePreview;
    Check(
        "scene.load 替换运行树（注入服务器+Ready 建世界）",
        HasRootChildSignatures(gameScene.Tree.Root, expectedEditorRootChildren) &&
        rootNodesBeforeApply.All(node => node.Parent is null && node.Tree is null) &&
        appliedWorld?.World is not null,
        applied);

    // 13) scene.reset 重新读取项目主场景
    var rootNodesBeforeReset = gameScene.Tree.Root.Children.ToArray();
    editorHost.ResetScene();
    Check(
        "scene.reset 重新读取项目主场景",
        HasRootChildSignatures(gameScene.Tree.Root, expectedEditorRootChildren) &&
        rootNodesBeforeReset.All(node => node.Parent is null && node.Tree is null) &&
        gameScene.Tree.GetNode("/Root/Camera") is Camera3D &&
        RequireVoxelWorld(gameScene).World is not null,
        string.Join(',', CaptureRootChildSignatures(gameScene.Tree.Root)));
    File.Delete(editorScenePath);

    // 14) ClassDB 类型系统（Godot 方法：类型注册 + 元数据）
    Check(
        "会话 registry 已知类型（短名）",
        gameScene.Runtime.SceneRegistry.KnownNodeTypes.Contains("Camera3D") &&
        gameScene.Runtime.SceneRegistry.KnownNodeTypes.Contains("VoxelWorldNode"));
    Check("ClassDB 实例化（短名/全名）", Cubit.Core.ObjectSystem.ClassDB.Instantiate("Camera3D") is Camera3D && Cubit.Core.ObjectSystem.ClassDB.Instantiate(typeof(Camera3D).FullName!) is Camera3D);
    Check("ClassDB 未知类型返回 null", Cubit.Core.ObjectSystem.ClassDB.Instantiate("NoSuchType_XYZ") is null);
    var voxelType = gameScene.Runtime.SceneRegistry.ResolveNodeType("VoxelWorldNode");
    var seedProp = voxelType?.GetProperty("Seed");
    Check("会话 registry 属性元数据（[Export]）", seedProp is not null && System.Reflection.CustomAttributeExtensions.GetCustomAttribute<Cubit.Core.Scene.ExportAttribute>(seedProp) is not null);
    var trySetBlockById = voxelType?.GetMethod(
        "TrySetBlock",
        [typeof(int), typeof(int), typeof(int), typeof(ushort)]);
    var trySetBlockByState = voxelType?.GetMethod(
        "TrySetBlock",
        [typeof(int), typeof(int), typeof(int), typeof(BlockState)]);
    Check(
        "会话 registry 方块编辑方法元数据",
        trySetBlockById is not null && trySetBlockByState is not null);

    // 15) 正式项目格式：创建、往返、Core-only 场景和路径边界
    var projectDir = Path.Combine(Path.GetTempPath(), $"cubit_projectcheck_{Guid.NewGuid():N}");
    try
    {
        var project = ProjectIO.Create(projectDir, "测试项目");
        Check("项目清单与主场景已创建",
            File.Exists(project.ManifestPath) && File.Exists(project.MainScenePath));
        Check("项目清单往返",
            project.Manifest.FormatVersion == 1 &&
            project.Manifest.Name == "测试项目" &&
            project.Manifest.MainScene == "scenes/main.cscene" &&
            project.SceneCatalog.Entries.Count == 1 &&
            project.SceneCatalog.MainScene.Path == "scenes/main.cscene");

        var projectRoot = SceneIO.LoadFromJson(project.MainScenePath, new SceneRegistry());
        Check("默认项目只包含空作者根节点",
            projectRoot.Name == "Root" &&
            projectRoot.Children.Count == 0 &&
            projectRoot.Children.All(node => node.GetType().Assembly == typeof(Node).Assembly));

        var originalManifest = File.ReadAllText(project.ManifestPath);
        var duplicateRejected = false;
        try
        {
            ProjectIO.Create(projectDir, "覆盖测试");
        }
        catch (InvalidOperationException)
        {
            duplicateRejected = true;
        }
        Check("重复创建拒绝覆盖",
            duplicateRejected && File.ReadAllText(project.ManifestPath) == originalManifest);

        var invalidDir = Path.Combine(Path.GetTempPath(), $"cubit_project_invalid_{Guid.NewGuid():N}");
        Directory.CreateDirectory(invalidDir);
        File.WriteAllText(Path.Combine(invalidDir, ProjectIO.ManifestFileName),
            "{\"formatVersion\":1,\"name\":\"越界\",\"mainScene\":\"../outside.cscene\"}");
        var traversalRejected = false;
        try
        {
            ProjectIO.Load(invalidDir);
        }
        catch (InvalidDataException)
        {
            traversalRejected = true;
        }
        Check("mainScene 越界被拒绝", traversalRejected);
        Directory.Delete(invalidDir, true);

        var absoluteDir = Path.Combine(Path.GetTempPath(), $"cubit_project_absolute_{Guid.NewGuid():N}");
        Directory.CreateDirectory(absoluteDir);
        File.WriteAllText(Path.Combine(absoluteDir, ProjectIO.ManifestFileName),
            JsonSerializer.Serialize(new
            {
                formatVersion = 1,
                name = "绝对路径",
                mainScene = Path.Combine(Path.GetTempPath(), "outside.cscene"),
            }));
        var absoluteRejected = false;
        try
        {
            ProjectIO.Load(absoluteDir);
        }
        catch (InvalidDataException)
        {
            absoluteRejected = true;
        }
        Check("mainScene 绝对路径被拒绝", absoluteRejected);
        Directory.Delete(absoluteDir, true);

        var missingDir = Path.Combine(Path.GetTempPath(), $"cubit_project_missing_{Guid.NewGuid():N}");
        Directory.CreateDirectory(missingDir);
        File.WriteAllText(Path.Combine(missingDir, ProjectIO.ManifestFileName),
            "{\"formatVersion\":1,\"name\":\"缺失场景\",\"mainScene\":\"scenes/main.cscene\"}");
        var missingRejected = false;
        try
        {
            ProjectIO.Load(missingDir);
        }
        catch (FileNotFoundException)
        {
            missingRejected = true;
        }
        Check("缺失主场景被拒绝", missingRejected);
        Directory.Delete(missingDir, true);

        var versionDir = Path.Combine(Path.GetTempPath(), $"cubit_project_version_{Guid.NewGuid():N}");
        Directory.CreateDirectory(versionDir);
        File.WriteAllText(Path.Combine(versionDir, ProjectIO.ManifestFileName),
            "{\"formatVersion\":99,\"name\":\"未来版本\",\"mainScene\":\"scenes/main.cscene\"}");
        var versionRejected = false;
        try
        {
            ProjectIO.Load(versionDir);
        }
        catch (InvalidDataException)
        {
            versionRejected = true;
        }
        Check("未知项目版本被拒绝", versionRejected);
        Directory.Delete(versionDir, true);

        var linkedProjectDir = Path.Combine(Path.GetTempPath(), $"cubit_project_link_{Guid.NewGuid():N}");
        var linkedOutsideDir = Path.Combine(Path.GetTempPath(), $"cubit_project_link_outside_{Guid.NewGuid():N}");
        var linkedSceneDir = Path.Combine(linkedProjectDir, "linked-scenes");
        try
        {
            Directory.CreateDirectory(linkedProjectDir);
            Directory.CreateDirectory(linkedOutsideDir);
            var linkedRoot = new Node { Name = "Root" };
            SceneIO.SaveToJson(linkedRoot, Path.Combine(linkedOutsideDir, "main.cscene"));
            File.WriteAllText(Path.Combine(linkedProjectDir, ProjectIO.ManifestFileName),
                "{\"formatVersion\":1,\"name\":\"链接逃逸\",\"mainScene\":\"linked-scenes/main.cscene\"}");
            CreateDirectoryJunction(linkedSceneDir, linkedOutsideDir);

            var linkedLoadRejected = false;
            try
            {
                ProjectIO.Load(linkedProjectDir);
            }
            catch (InvalidDataException)
            {
                linkedLoadRejected = true;
            }

            Check("项目加载拒绝目录 Junction 逃逸", linkedLoadRejected);
        }
        finally
        {
            DeleteDirectoryJunction(linkedSceneDir);
            if (Directory.Exists(linkedProjectDir)) Directory.Delete(linkedProjectDir, true);
            if (Directory.Exists(linkedOutsideDir)) Directory.Delete(linkedOutsideDir, true);
        }

        var migrationPath = Path.Combine(projectDir, "legacy.cscene");
        File.WriteAllText(migrationPath, "{\"Type\":\"Cubit.Core.World.VoxelWorldNode\",\"Name\":\"World\"}");
        var migrated = VoxelSceneMigration.MigrateLegacyScene(migrationPath);
        var migratedBytes = File.ReadAllBytes(migrationPath);
        var migratedAgain = VoxelSceneMigration.MigrateLegacyScene(migrationPath);
        Check(
            "示例场景迁移一次且幂等",
            migrated && !migratedAgain && migratedBytes.SequenceEqual(File.ReadAllBytes(migrationPath)) &&
            File.ReadAllText(migrationPath).Contains("Cubit.Voxel.World.VoxelWorldNode", StringComparison.Ordinal));
    }
    finally
    {
        if (Directory.Exists(projectDir))
        {
            Directory.Delete(projectDir, true);
        }
    }

    // 16) 正式项目编辑器会话：Core 3D 场景驱动、网格/相机提交、无相机非致命
    var sessionProjectDir = Path.Combine(Path.GetTempPath(), $"cubit_editor_project_{Guid.NewGuid():N}");
    try
    {
        ProjectIO.Create(sessionProjectDir, "编辑器会话测试");
        var sessionProject = ProjectIO.Load(sessionProjectDir);
        File.WriteAllText(sessionProject.MainScenePath, """
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Root",
          "Properties": null,
          "Children": [
            {
              "Type": "Cubit.Core.Scene.Camera3D",
              "Name": "Camera3D",
              "Properties": null,
              "Children": null
            },
            {
              "Type": "Cubit.Core.Scene.BoxMesh3D",
              "Name": "BoxMesh3D",
              "Properties": null,
              "Children": null
            }
          ]
        }
        """);
        var sessionRenderer = new FakeRenderBackend();
        try
        {
            using var projectSession = new ProjectSceneSession(sessionRenderer, sessionProjectDir);
            Check("正式项目会话加载 Root/Camera3D/BoxMesh3D",
                projectSession.Tree.Root.Children.Count == 2 &&
                projectSession.Tree.GetNode("/Root/Camera3D") is Camera3D &&
                projectSession.Tree.GetNode("/Root/BoxMesh3D")?.GetType().FullName == "Cubit.Core.Scene.BoxMesh3D");
            projectSession.ProcessFrame(1.0 / 60.0);
            Check("正式项目会话向渲染服务器提交相机", sessionRenderer.CameraUpdateCount == 1);
            Check("正式项目会话上传通用 3D 网格",
                sessionRenderer.MeshUploadCount >= 1 && sessionRenderer.ActiveMeshCount == 1,
                $"uploads={sessionRenderer.MeshUploadCount} active={sessionRenderer.ActiveMeshCount}");
            projectSession.Save();
            Check("正式项目会话保存主场景", File.Exists(projectSession.ScenePath));
        }
        catch (InvalidOperationException loadException)
        {
            Check("正式项目会话加载 Root/Camera3D/BoxMesh3D", false, loadException.Message);
            Check("正式项目会话上传通用 3D 网格", false, loadException.Message);
        }

        var noCameraRoot = new Node { Name = "Root" };
        SceneIO.SaveToJson(noCameraRoot, sessionProject.MainScenePath);
        var noCameraRenderer = new FakeRenderBackend();
        using var noCameraSession = new ProjectSceneSession(noCameraRenderer, sessionProjectDir);
        noCameraSession.ProcessFrame(1.0 / 60.0);
        Check("无 Camera3D 项目可非致命打开",
            !noCameraSession.HasCamera && noCameraRenderer.CameraUpdateCount == 0);
    }
    finally
    {
        if (Directory.Exists(sessionProjectDir)) Directory.Delete(sessionProjectDir, true);
    }

    var saveLinkProjectDir = Path.Combine(Path.GetTempPath(), $"cubit_project_save_link_{Guid.NewGuid():N}");
    var saveLinkOutsideDir = Path.Combine(Path.GetTempPath(), $"cubit_project_save_outside_{Guid.NewGuid():N}");
    var saveLinkSceneDir = Path.Combine(saveLinkProjectDir, "scenes");
    var originalSceneDir = Path.Combine(saveLinkProjectDir, "scenes-original");
    try
    {
        ProjectIO.Create(saveLinkProjectDir, "保存链接逃逸测试");
        using var saveSession = new ProjectSceneSession(new FakeRenderBackend(), saveLinkProjectDir);
        Directory.Move(saveLinkSceneDir, originalSceneDir);
        Directory.CreateDirectory(saveLinkOutsideDir);
        var outsideScenePath = Path.Combine(saveLinkOutsideDir, "main.cscene");
        const string sentinel = "项目外文件不得覆盖";
        File.WriteAllText(outsideScenePath, sentinel);
        CreateDirectoryJunction(saveLinkSceneDir, saveLinkOutsideDir);

        var linkedSaveRejected = false;
        try
        {
            saveSession.Save();
        }
        catch (InvalidDataException)
        {
            linkedSaveRejected = true;
        }

        Check(
            "项目保存前复验并拒绝目录 Junction 逃逸",
            linkedSaveRejected && File.ReadAllText(outsideScenePath) == sentinel);
    }
    finally
    {
        DeleteDirectoryJunction(saveLinkSceneDir);
        if (Directory.Exists(saveLinkProjectDir)) Directory.Delete(saveLinkProjectDir, true);
        if (Directory.Exists(saveLinkOutsideDir)) Directory.Delete(saveLinkOutsideDir, true);
    }

    var launchOptions = Cubit.Editor.EditorLaunchOptions.Parse(["--project", sessionProjectDir]);
    Check("编辑器 --project 参数解析", launchOptions.ProjectPath == sessionProjectDir && launchOptions.Error is null);
    var invalidLaunchOptions = Cubit.Editor.EditorLaunchOptions.Parse(["--project"]);
    Check("编辑器缺失项目路径时保持空项目",
        invalidLaunchOptions.ProjectPath is null && invalidLaunchOptions.Error is not null);
    tree.Dispose();
    Console.WriteLine(failures == 0 ? "scenecheck 全部通过" : $"scenecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int SceneCommand(string path)
{
    var root = new Node { Name = "Root" };
    root.AddChild(new Camera3D { Name = "Camera" });
    root.AddChild(new BoxMesh3D { Name = "Box", Size = 4f });
    SceneIO.SaveToJson(root, path);
    Console.WriteLine($"场景已保存: {path} ({new FileInfo(path).Length} bytes)");

    var loaded = SceneIO.LoadFromJson(path, new SceneRegistry());
    var camera = loaded.Children.FirstOrDefault(n => n.Name == "Camera") as Camera3D;
    var box = loaded.Children.FirstOrDefault(n => n.Name == "Box") as BoxMesh3D;
    Console.WriteLine($"场景已加载: {loaded.Name} 子节点={loaded.Children.Count}");
    Console.WriteLine($"回读校验: Camera({camera?.Name}) Box(size={box?.Size})");
    return camera is not null && box is { Size: 4f } ? 0 : 1;
}

static int SceneCatalogCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var implicitRoot = CreateCatalogProject(
        "implicit",
        "scenes/main.cscene",
        [("main", "scenes/main.cscene")]);
    try
    {
        var project = ProjectIO.Load(implicitRoot);
        Check(
            "旧单场景项目建立隐式目录",
            project.SceneCatalog.Entries.Count == 1 &&
            project.SceneCatalog.MainScene.Id == "main" &&
            project.SceneCatalog.MainScene.Path == "scenes/main.cscene");
    }
    finally
    {
        DeleteTemporaryDirectory(implicitRoot);
    }

    var explicitRoot = CreateCatalogProject(
        "explicit",
        "scenes/boot.cscene",
        [("boot", "scenes/boot.cscene"), ("title", "scenes/title.cscene")]);
    try
    {
        var project = ProjectIO.Load(explicitRoot);
        Check(
            "显式目录解析场景 ID 和主场景",
            project.SceneCatalog.Entries.Count == 2 &&
            project.SceneCatalog.GetById("TITLE").Path == "scenes/title.cscene" &&
            project.SceneCatalog.MainScene.Id == "boot");
        Check(
            "显式目录按 ID 返回项目内绝对路径",
            ProjectIO.GetScenePath(project, "title") ==
            Path.Combine(explicitRoot, "scenes", "title.cscene"));
    }
    finally
    {
        DeleteTemporaryDirectory(explicitRoot);
    }

    var duplicateIdRoot = CreateCatalogProject(
        "duplicate-id",
        "scenes/boot.cscene",
        [("boot", "scenes/boot.cscene"), ("BOOT", "scenes/title.cscene")]);
    Check("重复场景 ID 被拒绝", LoadCatalogFails(duplicateIdRoot));
    DeleteTemporaryDirectory(duplicateIdRoot);

    var duplicatePathRoot = CreateCatalogProject(
        "duplicate-path",
        "scenes/boot.cscene",
        [("boot", "scenes/boot.cscene"), ("title", "scenes/boot.cscene")]);
    Check("重复场景路径被拒绝", LoadCatalogFails(duplicatePathRoot));
    DeleteTemporaryDirectory(duplicatePathRoot);

    var missingRoot = CreateCatalogProject(
        "missing",
        "scenes/boot.cscene",
        [("boot", "scenes/boot.cscene"), ("missing", "scenes/missing.cscene")],
        createMissingScene: true);
    Check("场景文件缺失被拒绝", LoadCatalogFails(missingRoot));
    DeleteTemporaryDirectory(missingRoot);

    var mainNotListedRoot = CreateCatalogProject(
        "main-not-listed",
        "scenes/other.cscene",
        [("boot", "scenes/boot.cscene")],
        createMainScene: true);
    Check("mainScene 未列入目录被拒绝", LoadCatalogFails(mainNotListedRoot));
    DeleteTemporaryDirectory(mainNotListedRoot);

    Console.WriteLine(failures == 0 ? "scenecatalogcheck 全部通过" : $"scenecatalogcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static string CreateCatalogProject(
        string name,
        string mainScene,
        (string Id, string Path)[] scenes,
        bool createMissingScene = false,
        bool createMainScene = false)
    {
        var root = Path.Combine(Path.GetTempPath(), $"cubit_scenecatalog_{name}_{Guid.NewGuid():N}");
        Directory.CreateDirectory(root);
        foreach (var scene in scenes)
        {
            if (createMissingScene && scene.Path.EndsWith("missing.cscene", StringComparison.Ordinal))
            {
                continue;
            }

            SceneIO.SaveToJson(
                new Node { Name = scene.Id },
                Path.Combine(root, scene.Path.Replace('/', Path.DirectorySeparatorChar)));
        }

        if (createMainScene)
        {
            SceneIO.SaveToJson(
                new Node { Name = "Other" },
                Path.Combine(root, mainScene.Replace('/', Path.DirectorySeparatorChar)));
        }

        var sceneJson = string.Join(",", scenes.Select(scene =>
            $"{{\"id\":\"{scene.Id}\",\"path\":\"{scene.Path}\"}}"));
        File.WriteAllText(
            Path.Combine(root, ProjectIO.ManifestFileName),
            $"{{\"formatVersion\":{ProjectIO.CurrentFormatVersion},\"name\":\"{name}\",\"mainScene\":\"{mainScene}\",\"scenes\":[{sceneJson}]}}");
        return root;
    }

    static bool LoadCatalogFails(string root)
    {
        try
        {
            _ = ProjectIO.Load(root);
            return false;
        }
        catch (InvalidDataException)
        {
            return true;
        }
        catch (FileNotFoundException)
        {
            return true;
        }
    }

    static void DeleteTemporaryDirectory(string path)
    {
        if (Directory.Exists(path))
        {
            Directory.Delete(path, recursive: true);
        }
    }
}

static int SceneInstancingCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var root = Path.Combine(Path.GetTempPath(), $"cubit_scene_instancing_{Guid.NewGuid():N}");
    try
    {
        var created = ProjectIO.Create(root, "场景实例切换验收");
        var altPath = Path.Combine(root, "scenes", "alt.cscene");
        File.WriteAllText(created.ManifestPath, """
        {
          "formatVersion": 1,
          "name": "场景实例切换验收",
          "mainScene": "scenes/main.cscene",
          "scenes": [
            { "id": "main", "path": "scenes/main.cscene" },
            { "id": "alt", "path": "scenes/alt.cscene" },
            { "id": "observing", "path": "scenes/observing.cscene" },
            { "id": "failing", "path": "scenes/failing.cscene" }
          ]
        }
        """);
        File.WriteAllText(created.MainScenePath, """
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Root",
          "Properties": null,
          "Children": [
            { "Type": "Cubit.Core.Scene.BoxMesh3D", "Name": "MainBox", "Properties": null, "Children": null }
          ]
        }
        """);
        File.WriteAllText(altPath, """
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Root",
          "Properties": null,
          "Children": [
            { "Type": "Cubit.Core.Scene.BoxMesh3D", "Name": "AltBox", "Properties": null, "Children": null }
          ]
        }
        """);
        File.WriteAllText(Path.Combine(root, "scenes", "observing.cscene"), """
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Root",
          "Properties": null,
          "Children": [
            { "Type": "SceneSwitchStateProbeNode", "Name": "Probe", "Properties": null, "Children": null }
          ]
        }
        """);
        File.WriteAllText(Path.Combine(root, "scenes", "failing.cscene"), """
        {
          "Type": "Cubit.Core.Scene.Node",
          "Name": "Root",
          "Properties": null,
          "Children": [
            { "Type": "SceneSwitchFailureNode", "Name": "Failure", "Properties": null, "Children": null }
          ]
        }
        """);

        var project = ProjectIO.Load(root);
        using var runtime = new ProjectRuntime(
            project,
            new FakeRenderBackend(),
            Array.Empty<IEnginePlugin>(),
            registerProjectTypes: (_, registry) =>
            {
                registry.RegisterNode<SceneSwitchFailureNode>();
                registry.RegisterNode<SceneSwitchStateProbeNode>();
            },
            jobSystemOptions: new JobSystemOptions { WorkerCount = 1 });
        var scenesProperty = typeof(ProjectRuntime).GetProperty("Scenes");
        var scenes = scenesProperty?.GetValue(runtime);
        var serviceType = scenes?.GetType();
        var loadMethod = serviceType?.GetMethod("Load");
        var switchMethod = serviceType?.GetMethod("Switch");
        var replaceMethod = serviceType?.GetMethod("Replace");
        var currentIdProperty = serviceType?.GetProperty("CurrentSceneId");
        Check(
            "ProjectRuntime 提供显式 RuntimeSceneService",
            scenesProperty is not null && scenes is not null && loadMethod is not null && switchMethod is not null && replaceMethod is not null,
            $"property={scenesProperty is not null} service={scenes is not null} load={loadMethod is not null} switch={switchMethod is not null} replace={replaceMethod is not null}");
        Check(
            "运行时初始场景来自 mainScene",
            runtime.Tree.GetNode("/Root/MainBox") is BoxMesh3D && currentIdProperty?.GetValue(scenes) as string == "main");

        if (scenes is not null && loadMethod is not null && switchMethod is not null && replaceMethod is not null)
        {
            var detached = loadMethod.Invoke(scenes, ["alt"]) as Node;
            Check(
                "RuntimeSceneService 按场景 ID 加载 detached scene",
                detached?.Children.OfType<BoxMesh3D>().Any(node => node.Name == "AltBox") == true);
            switchMethod.Invoke(scenes, ["alt"]);
            Check(
                "RuntimeSceneService 切换场景并更新当前 ID",
                runtime.Tree.GetNode("/Root/AltBox") is BoxMesh3D && currentIdProperty?.GetValue(scenes) as string == "alt");

            SceneSwitchStateProbeNode.ReadCurrentSceneId = () => currentIdProperty?.GetValue(scenes) as string;
            switchMethod.Invoke(scenes, ["observing"]);
            Check(
                "目标场景 Ready 阶段可见目标 CurrentSceneId",
                SceneSwitchStateProbeNode.ObservedCurrentSceneId == "observing",
                $"observed={SceneSwitchStateProbeNode.ObservedCurrentSceneId ?? "null"}");
            switchMethod.Invoke(scenes, ["alt"]);

            var missingError = CaptureException(() => switchMethod.Invoke(scenes, ["missing"]));
            var rootError = missingError is TargetInvocationException invocation ? invocation.InnerException : missingError;
            Check(
                "切换缺失场景失败且保留旧场景",
                rootError is KeyNotFoundException or InvalidOperationException && runtime.Tree.GetNode("/Root/AltBox") is BoxMesh3D &&
                currentIdProperty?.GetValue(scenes) as string == "alt",
                rootError?.Message ?? "none");

            var replacementRoot = new Node { Name = "Root" };
            replacementRoot.AddChild(new BoxMesh3D { Name = "ReplacementBox" });
            replaceMethod.Invoke(scenes, [replacementRoot, null]);
            Check(
                "RuntimeSceneService Replace 使用显式 detached root",
                runtime.Tree.GetNode("/Root/ReplacementBox") is BoxMesh3D && currentIdProperty?.GetValue(scenes) is null);

            switchMethod.Invoke(scenes, ["alt"]);
            var readyFailure = CaptureException(() => switchMethod.Invoke(scenes, ["failing"]));
            var readyRootError = readyFailure is TargetInvocationException readyInvocation ? readyInvocation.InnerException : readyFailure;
            Check(
                "目标场景 Ready 失败时恢复旧场景",
                readyRootError is InvalidOperationException && runtime.Tree.GetNode("/Root/AltBox") is BoxMesh3D &&
                currentIdProperty?.GetValue(scenes) as string == "alt",
                readyRootError?.Message ?? "none");
        }
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  RuntimeSceneService 验收异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "sceneinstancingcheck 全部通过" : $"sceneinstancingcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int SceneInstanceCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var projectRoot = Path.Combine(Path.GetTempPath(), $"cubit_scene_instance_{Guid.NewGuid():N}");
    try
    {
        var created = ProjectIO.Create(projectRoot, "场景实例检查");
        var manifest = JsonNode.Parse(File.ReadAllText(created.ManifestPath))!.AsObject();
        manifest["scenes"] = new JsonArray(
            new JsonObject { ["id"] = "main", ["path"] = "scenes/main.cscene" },
            new JsonObject { ["id"] = "child", ["path"] = "scenes/child.cscene" });
        File.WriteAllText(created.ManifestPath, manifest.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));

        var childPath = Path.Combine(projectRoot, "scenes", "child.cscene");
        var childRoot = new Node { Name = "ChildRoot" };
        childRoot.AddChild(new BoxMesh3D { Name = "NestedBox", Size = 2f });
        SceneIO.SaveToJson(childRoot, childPath);
        var project = ProjectIO.Load(projectRoot);
        var childEntry = project.SceneCatalog.GetById("child");

        var mainRoot = new Node { Name = "MainRoot" };
        mainRoot.AddChild(new SceneInstance
        {
            Name = "ChildInstance",
            ScenePath = childEntry.Path,
            SceneUid = childEntry.Uid,
        });
        ProjectIO.SaveScene(project, "main", mainRoot);
        project = ProjectIO.Load(projectRoot);

        var registry = new SceneRegistry();
        var packed = PackedScene.Open(project, "main", registry);
        var instantiated = packed.Instantiate();
        var instance = instantiated.Children.SingleOrDefault() as SceneInstance;
        Check(
            "PackedScene 按项目路径和 UID 实例化 detached 场景",
            instance is not null && instance.ScenePath == childEntry.Path &&
            instance.Children.OfType<BoxMesh3D>().SingleOrDefault() is { Name: "NestedBox", Size: 2f } &&
            instantiated.Name == "MainRoot",
            $"root={instantiated.Name} child={instance?.Name} children={instance?.Children.Count}");

        var missingPathRoot = new Node { Name = "MainRoot" };
        missingPathRoot.AddChild(new SceneInstance
        {
            Name = "MissingPath",
            ScenePath = "scenes/missing.cscene",
            SceneUid = childEntry.Uid,
        });
        ProjectIO.SaveScene(project, "main", missingPathRoot);
        project = ProjectIO.Load(projectRoot);
        Check(
            "PackedScene 拒绝项目目录外或缺失场景路径",
            CaptureException(() => PackedScene.Open(project, "main", new SceneRegistry()).Instantiate()) is InvalidDataException);

        var invalidUidRoot = new Node { Name = "MainRoot" };
        invalidUidRoot.AddChild(new SceneInstance
        {
            Name = "InvalidUid",
            ScenePath = childEntry.Path,
            SceneUid = "cuid://00000000000000000000000000000000",
        });
        ProjectIO.SaveScene(project, "main", invalidUidRoot);
        project = ProjectIO.Load(projectRoot);
        Check(
            "PackedScene 拒绝引用 UID 不匹配",
            CaptureException(() => PackedScene.Open(project, "main", new SceneRegistry()).Instantiate()) is InvalidDataException);

        var cycleRoot = new Node { Name = "ChildRoot" };
        var mainEntry = project.SceneCatalog.GetById("main");
        cycleRoot.AddChild(new SceneInstance
        {
            Name = "MainCycle",
            ScenePath = mainEntry.Path,
            SceneUid = mainEntry.Uid,
        });
        ProjectIO.SaveScene(project, "child", cycleRoot);
        var validMainRoot = new Node { Name = "MainRoot" };
        validMainRoot.AddChild(new SceneInstance
        {
            Name = "ChildInstance",
            ScenePath = childEntry.Path,
            SceneUid = childEntry.Uid,
        });
        ProjectIO.SaveScene(project, "main", validMainRoot);
        project = ProjectIO.Load(projectRoot);
        Check(
            "PackedScene 拒绝递归场景引用",
            CaptureException(() => PackedScene.Open(project, "main", new SceneRegistry()).Instantiate()) is InvalidDataException);
    }
    catch (Exception exception)
    {
        Check("场景实例 fixture 执行", false, exception.Message);
    }
    finally
    {
        if (Directory.Exists(projectRoot))
        {
            Directory.Delete(projectRoot, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "sceneinstancecheck 全部通过" : $"sceneinstancecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int TypeRegistryCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var first = new SceneRegistry();
    var second = new SceneRegistry();
    first.RegisterNode<PluginProbeNodeA>(typeName: "SharedNode");
    second.RegisterNode<PluginProbeNodeB>(typeName: "SharedNode");

    Check(
        "两个会话可注册同名节点但实例化各自类型",
        first.InstantiateNode("SharedNode") is PluginProbeNodeA &&
        second.InstantiateNode("SharedNode") is PluginProbeNodeB);
    Check(
        "项目类型不会污染其他会话",
        first.InstantiateNode(nameof(PluginProbeNodeB)) is null &&
        second.InstantiateNode(nameof(PluginProbeNodeA)) is null);
    Check(
        "Core 内置节点只在当前 registry 可见",
        first.InstantiateNode(nameof(Camera3D)) is Camera3D &&
        second.InstantiateNode(nameof(EcsNode)) is EcsNode);

    var duplicate = CaptureException(() => first.RegisterNode<PluginProbeNodeB>(typeName: "SharedNode"));
    Check("同一会话拒绝短名冲突", duplicate is InvalidOperationException, duplicate?.Message ?? "none");

    var sessionRegistry = new SceneRegistry();
    using (var sessionPlugins = CreateToolPluginManagerWithRegistry([
               new PluginProbe(
                   "plugin.session.registry",
                   new Version(1, 0, 0),
                   [],
                   registry => registry.RegisterNode<PluginProbeNodeA>(typeName: "SessionOnlyNode")),
           ], sessionRegistry))
    {
        sessionPlugins.Configure([
            new CubitPluginReference { Id = "plugin.session.registry", Version = "1.0.0" },
        ]);
        Check(
            "运行会话插件节点进入显式 registry 而非静态 ClassDB",
            sessionRegistry.InstantiateNode("SessionOnlyNode") is PluginProbeNodeA &&
            Cubit.Core.ObjectSystem.ClassDB.Instantiate("SessionOnlyNode") is null);
    }

    var sceneJson = SceneIO.SerializeToJson(new Node
    {
        Name = "Root",
    });
    var rootWithProbe = new Node { Name = "Root" };
    rootWithProbe.AddChild(new PluginProbeNodeA { Name = "Probe" });
    sceneJson = SceneIO.SerializeToJson(rootWithProbe);
    var loaded = SceneIO.DeserializeFromJson(sceneJson, first);
    Check(
        "SceneIO 显式 registry 递归实例化",
        loaded.Children.SingleOrDefault() is PluginProbeNodeA);

    var unknownTypeJson = sceneJson.Replace(
        "PluginProbeNodeA",
        "PluginProbeNodeB",
        StringComparison.Ordinal);
    var unknown = CaptureException(() => SceneIO.DeserializeFromJson(unknownTypeJson, first));
    Check(
        "显式 registry 拒绝未注册节点而不扫描 AppDomain",
        unknown is InvalidOperationException && unknown.Message.Contains("未注册", StringComparison.Ordinal),
        unknown?.Message ?? "none");

    var implicitSceneIoOverloads = typeof(SceneIO).GetMethods(BindingFlags.Public | BindingFlags.Static)
        .Where(method => method.Name is "DeserializeFromJson" or "LoadFromJson")
        .Where(method => method.GetParameters().Any(parameter => parameter.IsOptional))
        .ToArray();
    Check(
        "SceneIO 不公开无 registry 的隐式解析入口",
        implicitSceneIoOverloads.Length == 0,
        string.Join(',', implicitSceneIoOverloads.Select(method => method.Name)));

    var implicitProjectSceneLoads = typeof(ProjectIO).GetMethods(BindingFlags.Public | BindingFlags.Static)
        .Where(method => method.Name == "LoadMainScene")
        .Where(method => method.GetParameters().Length == 1)
        .ToArray();
    Check(
        "ProjectIO 不公开无 registry 的主场景加载入口",
        implicitProjectSceneLoads.Length == 0,
        string.Join(',', implicitProjectSceneLoads.Select(method => method.Name)));

    var implicitPluginManagerConstructors = typeof(PluginManager).GetConstructors()
        .Where(constructor => constructor.GetParameters().Any(parameter =>
            parameter.ParameterType == typeof(SceneRegistry) && parameter.IsOptional))
        .ToArray();
    Check(
        "PluginManager 不公开可省略 registry 的构造入口",
        implicitPluginManagerConstructors.Length == 0,
        implicitPluginManagerConstructors.Length.ToString());

    Console.WriteLine(failures == 0 ? "typeregistrycheck 全部通过" : $"typeregistrycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

