static int VoxelStreamLoadCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var directory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_streamload_{Guid.NewGuid():N}");
    try
    {
        var source = new VoxelWorld(20260808u, WorldType.Flat);
        source.GenerateChunkAt(0, 0);
        WorldFile.Save(source, directory);

        var metadataOnly = WorldFile.LoadMetadata(directory);
        Check(
            "LoadMetadata 不读取任何区块",
            metadataOnly.Store.ChunkKeys.Length == 0,
            $"chunks={metadataOnly.Store.ChunkKeys.Length}");

        using var storage = new WorldFileStorage(directory);
        Check(
            "region 按坐标读取已保存区块",
            storage.TryLoadChunk(0, 0, out var persisted) && persisted.Chunk is not null,
            "(0,0)");
        Check(
            "region 未命中坐标不生成假区块",
            !storage.TryLoadChunk(3, 3, out _),
            "(3,3)");

        var loadedWorld = WorldFile.LoadMetadata(directory);
        Check(
            "加载快照提交后只存在目标区块",
            loadedWorld.CommitLoadedChunk(0, 0, persisted) && loadedWorld.Store.ChunkKeys.Length == 1,
            $"chunks={loadedWorld.Store.ChunkKeys.Length}");

        var streamedWorld = WorldFile.LoadMetadata(directory);
        using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 2 });
        using var streamer = new ChunkStreamer(streamedWorld, jobs, storage);
        streamer.RequestArea(0, 0, 1);
        var deadline = Stopwatch.StartNew();
        while (deadline.Elapsed < TimeSpan.FromSeconds(10) && streamedWorld.Store.ChunkKeys.Length < 9)
        {
            streamer.Pump();
            Thread.Sleep(5);
        }

        Check(
            "ChunkStreamer 优先读取存档并为缺失区块生成",
            streamedWorld.Store.ChunkKeys.Length == 9 &&
            streamer.LoadedCount == 1 &&
            streamer.GeneratedCount == 8,
            $"chunks={streamedWorld.Store.ChunkKeys.Length} loaded={streamer.LoadedCount} generated={streamer.GeneratedCount}");
        Check(
            "按区块加载结果保持存档方块数据",
            streamedWorld.GetBlock(0, 0, 0) == source.GetBlock(0, 0, 0),
            $"stored={streamedWorld.GetBlock(0, 0, 0)} source={source.GetBlock(0, 0, 0)}");
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  Voxel 按区块流式读取异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(directory))
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "voxelstreamloadcheck 全部通过" : $"voxelstreamloadcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelSectionDirtyCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var chunk = new Chunk();
    Check("新建区块 Section 脏位图为空", chunk.DirtySectionMask == 0, $"mask=0x{chunk.DirtySectionMask:X}");

    chunk.SetBlock(0, Chunk.MinY, 0, BlockRegistry.Stone);
    chunk.SetBlock(0, Chunk.MaxYExclusive - 1, 0, BlockRegistry.Stone);
    Check(
        "负 Y 与上边界方块修改标记对应 Section",
        chunk.DirtySectionMask == ((1UL << 0) | (1UL << (Chunk.SectionCount - 1))),
        $"mask=0x{chunk.DirtySectionMask:X}");

    chunk.GetSection(10).SetLight(0, 0, 0, LightingEngine.MaxLight, 0);
    Check(
        "中间 Section 光照修改进入脏位图",
        (chunk.DirtySectionMask & (1UL << 10)) != 0,
        $"mask=0x{chunk.DirtySectionMask:X}");

    chunk.ClearDirtySections((1UL << 0) | (1UL << 10));
    Check(
        "按掩码清除不影响其他 Section 脏标记",
        chunk.DirtySectionMask == (1UL << (Chunk.SectionCount - 1)),
        $"mask=0x{chunk.DirtySectionMask:X}");
    chunk.ClearDirtySections();
    Check("清除全部 Section 脏标记", chunk.DirtySectionMask == 0, $"mask=0x{chunk.DirtySectionMask:X}");

    chunk.SetBlock(0, Chunk.MinY, 0, BlockState.Air);
    Check("实际内容变化再次置脏", chunk.DirtySectionMask == (1UL << 0), $"mask=0x{chunk.DirtySectionMask:X}");
    chunk.ClearDirtySections();
    chunk.SetBlock(0, Chunk.MinY, 0, BlockState.Air);
    Check("重复写入相同方块不虚假置脏", chunk.DirtySectionMask == 0, $"mask=0x{chunk.DirtySectionMask:X}");

    var stableWorld = new VoxelWorld(20260808u, WorldType.Flat);
    stableWorld.GenerateChunkAt(0, 0);
    stableWorld.ClearDirtyChunks(stableWorld.DirtyChunkKeys);
    var stableChunk = stableWorld.Store.GetChunk(0, 0)!;
    LightingEngine.RelightSky(stableWorld.Store, 0, 0);
    LightingEngine.RelightBlockLight(stableChunk);
    Check(
        "重复天空光/方块光重算不虚假置脏 Section",
        stableChunk.DirtySectionMask == 0,
        $"mask=0x{stableChunk.DirtySectionMask:X}");

    var generatedProbeWorld = new VoxelWorld(20260808u, WorldType.Noise);
    var generatedProbe = generatedProbeWorld.CreateGeneratedChunk(0, 0, CancellationToken.None)!;
    Check(
        "新生成区块首次保存前标记全部 Section",
        generatedProbe.DirtySectionMask == ((1UL << Chunk.SectionCount) - 1),
        $"mask=0x{generatedProbe.DirtySectionMask:X}");

    var world = new VoxelWorld(20260808u, WorldType.Flat);
    var westChunk = new Chunk();
    var eastChunk = new Chunk();
    for (var x = 0; x < Chunk.SizeX; x++)
    {
        for (var z = 0; z < Chunk.SizeZ; z++)
        {
            eastChunk.SetBlock(x, 10, z, BlockRegistry.Stone);
        }
    }

    world.Store.AddChunk(0, 0, westChunk);
    world.Store.AddChunk(1, 0, eastChunk);
    LightingEngine.RelightChunk(world.Store, 0, 0);
    LightingEngine.RelightChunk(world.Store, 1, 0);
    world.ClearDirtyChunks(world.DirtyChunkKeys);
    var changed = world.SetBlockDeferred(Chunk.SizeX - 1, 10, 8, BlockRegistry.Stone, out _);
    var dirtyKeys = world.DirtyChunkKeys;
    Check(
        "跨区块天空光变化将邻区纳入 dirty 集合",
        changed && dirtyKeys.Contains((0, 0)) && dirtyKeys.Contains((1, 0)),
        string.Join(',', dirtyKeys.Select(key => $"({key.X},{key.Z})")));

    var canceledWorld = new VoxelWorld(20260808u, WorldType.Flat);
    canceledWorld.GenerateChunkAt(0, 0);
    canceledWorld.GenerateChunkAt(1, 0);
    canceledWorld.ClearDirtyChunks(canceledWorld.DirtyChunkKeys);
    using (var cancellation = new CancellationTokenSource())
    {
        cancellation.Cancel();
        try
        {
            LightingEngine.RelightSkyAround(canceledWorld.Store, 0, 0, cancellation.Token);
        }
        catch (OperationCanceledException)
        {
        }
    }

    Check(
        "光照取消后 Section dirty 仍进入世界保存集合",
        canceledWorld.DirtyChunkKeys.Contains((0, 0)),
        string.Join(',', canceledWorld.DirtyChunkKeys.Select(key => $"({key.X},{key.Z})")));

    Console.WriteLine(failures == 0 ? "voxelsectiondirtycheck 全部通过" : $"voxelsectiondirtycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelSectionPatchCheck(uint seed)
{
    var failures = 0;
    var directory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_section_patch_{Guid.NewGuid():N}");

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    try
    {
        var source = new VoxelWorld(seed, WorldType.Flat);
        source.GenerateChunkAt(0, 0);
        WorldFile.Save(source, directory);
        var regionPath = WorldFile.RegionPath(directory, 0, 0);
        var baselineRegionBytes = new FileInfo(regionPath).Length;
        var patchPath = SectionPatchStorage.PatchPath(directory, 0, 0);

        PersistedChunk persisted;
        using (var storage = new SectionPatchStorage(directory, maxCachedChunks: 0))
        {
            Check(
                "Section patch 读取 v4 基准区块",
                storage.TryLoadChunk(0, 0, out persisted),
                $"base={baselineRegionBytes}");
            var edited = persisted.Chunk;
            edited.SetBlock(0, Chunk.MaxYExclusive - 1, 0, BlockRegistry.Stone);
            var dirtyMask = edited.DirtySectionMask;
            storage.SaveChunk(
                0,
                0,
                new PersistedChunk(edited, persisted.Status, persisted.TicketLevel));
            edited.ClearDirtySections();

            Check(
                "单方块编辑只产生最高 Section dirty",
                dirtyMask == (1UL << (Chunk.SectionCount - 1)),
                $"mask=0x{dirtyMask:X}");
            Check(
                "Section patch 不增长基准 region",
                new FileInfo(regionPath).Length == baselineRegionBytes,
                $"bytes={baselineRegionBytes}->{new FileInfo(regionPath).Length}");
            Check(
                "Section patch 日志追加负载",
                File.Exists(patchPath) && new FileInfo(patchPath).Length > 0,
                File.Exists(patchPath) ? $"patch={new FileInfo(patchPath).Length}" : "missing");
        }

        var patchBytes = File.ReadAllBytes(patchPath);
        using (var storage = new SectionPatchStorage(directory, maxCachedChunks: 0))
        {
            Check(
                "Section patch 叠加读取修改后的方块",
                storage.TryLoadChunk(0, 0, out var restored) &&
                restored.Chunk.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == BlockRegistry.Stone &&
                restored.Status == persisted.Status &&
                restored.TicketLevel == persisted.TicketLevel);
        }

        using (var metadataStorage = new SectionPatchStorage(directory, maxCachedChunks: 0))
        {
            Check("Section patch 状态记录读取成功", metadataStorage.TryLoadChunk(0, 0, out var metadataChunk));
            if (metadataChunk.Chunk is not null)
            {
                metadataChunk.Chunk.ClearDirtySections();
                metadataStorage.SaveChunk(
                    0,
                    0,
                    new PersistedChunk(metadataChunk.Chunk, ChunkStatus.Ready, TicketLevel.EntitySimulation));
            }
        }

        using (var metadataReadStorage = new SectionPatchStorage(directory, maxCachedChunks: 0))
        {
            Check(
                "无 Section 变化时仍保存 status/ticket",
                metadataReadStorage.TryLoadChunk(0, 0, out var metadataRestored) &&
                metadataRestored.Status == ChunkStatus.Ready &&
                metadataRestored.TicketLevel == TicketLevel.EntitySimulation,
                $"status={metadataRestored.Status} ticket={metadataRestored.TicketLevel}");
        }

        var corrupted = patchBytes.ToArray();
        corrupted[^1] ^= 0x5A;
        File.WriteAllBytes(patchPath, corrupted);
        try
        {
            using var corruptedStorage = new SectionPatchStorage(directory, maxCachedChunks: 0);
            var corruption = CaptureException(() => corruptedStorage.TryLoadChunk(0, 0, out _));
            Check(
                "完整 Section patch CRC 损坏被拒绝",
                corruption is InvalidDataException && corruption.Message.Contains("CRC32", StringComparison.Ordinal),
                corruption?.Message ?? "none");
        }
        finally
        {
            File.WriteAllBytes(patchPath, patchBytes);
        }

        using (var stream = new FileStream(patchPath, FileMode.Append, FileAccess.Write, FileShare.Read))
        using (var writer = new BinaryWriter(stream))
        {
            writer.Write(4096);
            writer.Write((byte)0x7F);
            writer.Flush();
            stream.Flush(flushToDisk: true);
        }

        using (var truncatedStorage = new SectionPatchStorage(directory, maxCachedChunks: 0))
        {
            Check(
                "Section patch 末尾截断记录可恢复上一条有效记录",
                truncatedStorage.TryLoadChunk(0, 0, out var recovered) &&
                recovered.Chunk.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == BlockRegistry.Stone);
        }

        using (var appendAfterTail = new SectionPatchStorage(directory, maxCachedChunks: 0))
        {
            Check("截断尾后仍可读取基准修改", appendAfterTail.TryLoadChunk(0, 0, out var resumed));
            if (resumed.Chunk is not null)
            {
                resumed.Chunk.SetBlock(1, Chunk.MaxYExclusive - 1, 0, BlockRegistry.Sand);
                appendAfterTail.SaveChunk(0, 0, resumed);
                resumed.Chunk.ClearDirtySections();
            }
        }

        using (var resumedStorage = new SectionPatchStorage(directory, maxCachedChunks: 0))
        {
            Check(
                "截断尾后追加的新 Section 记录可读取",
                resumedStorage.TryLoadChunk(0, 0, out var resumed) &&
                resumed.Chunk.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == BlockRegistry.Stone &&
                resumed.Chunk.GetBlock(1, Chunk.MaxYExclusive - 1, 0) == BlockRegistry.Sand);
        }

        var readSamples = new double[16];
        using (var readStorage = new SectionPatchStorage(directory, maxCachedChunks: 0))
        {
            for (var sample = 0; sample < readSamples.Length; sample++)
            {
                var timer = Stopwatch.StartNew();
                var loaded = readStorage.TryLoadChunk(0, 0, out _);
                timer.Stop();
                Check("Section patch 随机读取成功", loaded);
                readSamples[sample] = timer.Elapsed.TotalMilliseconds;
            }
        }

        using (var compactionStorage = new SectionPatchStorage(directory, maxCachedChunks: 0))
        {
            var compactionEditsValid = true;
            for (var edit = 0; edit < 720; edit++)
            {
                if (!compactionStorage.TryLoadChunk(0, 0, out var editable) || editable.Chunk is null)
                {
                    compactionEditsValid = false;
                    break;
                }

                editable.Chunk.SetBlock(
                    2,
                    Chunk.MaxYExclusive - 1,
                    0,
                    edit % 2 == 0 ? BlockRegistry.Stone : BlockRegistry.Sand);
                compactionStorage.SaveChunk(0, 0, editable);
                editable.Chunk.ClearDirtySections();
            }

            Check("patch compaction 720 次编辑读取/写入成功", compactionEditsValid);
        }

        var compactedPatchBytes = new FileInfo(patchPath).Length;
        Check(
            "Section patch 重复编辑后受控压缩",
            compactedPatchBytes < 64 * 1024,
            $"bytes={compactedPatchBytes}");

        Console.WriteLine(JsonSerializer.Serialize(new
        {
            schema = "cubit.voxel-section-patch-check/v1",
            seed,
            baselineRegionBytes,
            patchBytes = patchBytes.Length,
            finalPatchBytes = compactedPatchBytes,
            editedSectionCount = 1,
            baseRegionUnchanged = new FileInfo(regionPath).Length == baselineRegionBytes,
            randomReadMedianMilliseconds = Median(readSamples),
        }));
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  Section patch 自检异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(directory))
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "voxelsectionpatchcheck 全部通过" : $"voxelsectionpatchcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelSectionPatchRecoveryCheck(uint seed)
{
    var failures = 0;
    var directory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_section_patch_recovery_{Guid.NewGuid():N}");

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    try
    {
        var world = new VoxelWorld(seed, WorldType.Flat);
        for (var cz = -3; cz <= 3; cz++)
        {
            for (var cx = -3; cx <= 3; cx++)
            {
                world.GenerateChunkAt(cx, cz);
            }
        }

        WorldFile.Save(world, directory);
        var keys = world.Store.ChunkKeys.OrderBy(key => key.Z).ThenBy(key => key.X).ToArray();
        using (var storage = new SectionPatchStorage(directory, maxCachedChunks: 0))
        {
            for (var index = 0; index < keys.Length; index++)
            {
                var key = keys[index];
                if (!storage.TryLoadChunk(key.X, key.Z, out var persisted))
                {
                    Check("多 region patch 初始读取", false, $"coord=({key.X},{key.Z})");
                    continue;
                }

                persisted.Chunk.SetBlock(0, Chunk.MaxYExclusive - 1, 0, BlockRegistry.Stone);
                storage.SaveChunk(key.X, key.Z, persisted);
                persisted.Chunk.ClearDirtySections();
            }
        }

        var groups = keys
            .GroupBy(key => WorldFile.ChunkToRegion(key.X, key.Z))
            .ToArray();
        var missingFormalRecovered = 0;
        var staleTemporaryDiscarded = 0;
        foreach (var group in groups)
        {
            var patchPath = SectionPatchStorage.PatchPath(directory, group.Key.RegionX, group.Key.RegionZ);
            var temporaryPath = patchPath + ".tmp";
            if (!File.Exists(patchPath))
            {
                Check("多 region patch 日志存在", false, patchPath);
                continue;
            }

            File.Copy(patchPath, temporaryPath, overwrite: true);
            File.Delete(patchPath);
            var recoveredKey = group.First();
            using (var storage = new SectionPatchStorage(directory, maxCachedChunks: 0))
            {
                var recovered = storage.TryLoadChunk(recoveredKey.X, recoveredKey.Z, out var persisted) &&
                    persisted.Chunk.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == BlockRegistry.Stone;
                Check(
                    "正式 patch 缺失时从临时文件恢复",
                    recovered && File.Exists(patchPath) && !File.Exists(temporaryPath),
                    $"region=({group.Key.RegionX},{group.Key.RegionZ})");
                if (recovered && File.Exists(patchPath) && !File.Exists(temporaryPath))
                {
                    missingFormalRecovered++;
                }
            }

            File.Copy(patchPath, temporaryPath, overwrite: true);
            using (var storage = new SectionPatchStorage(directory, maxCachedChunks: 0))
            {
                var retained = storage.TryLoadChunk(recoveredKey.X, recoveredKey.Z, out var persisted) &&
                    persisted.Chunk.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == BlockRegistry.Stone;
                Check(
                    "正式 patch 有效时丢弃遗留临时文件",
                    retained && File.Exists(patchPath) && !File.Exists(temporaryPath),
                    $"region=({group.Key.RegionX},{group.Key.RegionZ})");
                if (retained && File.Exists(patchPath) && !File.Exists(temporaryPath))
                {
                    staleTemporaryDiscarded++;
                }
            }
        }

        Check(
            "四个 region 均完成两种恢复路径",
            groups.Length == 4 && missingFormalRecovered == groups.Length && staleTemporaryDiscarded == groups.Length,
            $"regions={groups.Length} recovered={missingFormalRecovered} discarded={staleTemporaryDiscarded}");
        Console.WriteLine(JsonSerializer.Serialize(new
        {
            schema = "cubit.voxel-section-patch-recovery/v1",
            seed,
            chunkCount = keys.Length,
            regionCount = groups.Length,
            missingFormalRecovered,
            staleTemporaryDiscarded,
        }));
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  多 region Section patch 恢复异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(directory))
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "voxelsectionpatchrecoverycheck 全部通过" : $"voxelsectionpatchrecoverycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelSectionPatchBenchmarkCheck(uint seed)
{
    var failures = 0;
    var root = Path.Combine(Path.GetTempPath(), $"cubit_voxel_section_patch_benchmark_{Guid.NewGuid():N}");
    var regionDirectory = Path.Combine(root, "region");
    var patchDirectory = Path.Combine(root, "patch");

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    static (int X, int Z)[] CreateFixture(uint fixtureSeed, string directory)
    {
        var world = new VoxelWorld(fixtureSeed, WorldType.Flat);
        for (var cz = -3; cz <= 3; cz++)
        {
            for (var cx = -3; cx <= 3; cx++)
            {
                world.GenerateChunkAt(cx, cz);
            }
        }

        WorldFile.Save(world, directory);
        return world.Store.ChunkKeys.OrderBy(key => key.Z).ThenBy(key => key.X).ToArray();
    }

    static (long BaselineRegionBytes, long RegionBytes, long PatchBytes, double ReadMedianMilliseconds, bool Restored) RunVariant(
        string directory,
        bool usePatch,
        IReadOnlyList<(int X, int Z)> keys)
    {
        var baselineRegionBytes = Directory.EnumerateFiles(directory, "*.cubitregion")
            .Sum(path => new FileInfo(path).Length);
        using (var disposable = usePatch
                   ? (IDisposable)new SectionPatchStorage(directory, maxCachedChunks: 0)
                   : new WorldFileStorage(directory, maxCachedChunks: 0))
        {
            var storage = (IChunkStorage)disposable;
            var writer = (IChunkStorageWriter)disposable;
            for (var index = 0; index < keys.Count; index++)
            {
                var key = keys[index];
                if (!storage.TryLoadChunk(key.X, key.Z, out var persisted))
                {
                    return (baselineRegionBytes, 0, 0, 0, false);
                }

                persisted.Chunk.SetBlock(
                    0,
                    Chunk.MaxYExclusive - 1,
                    0,
                    index % 2 == 0 ? BlockRegistry.Stone : BlockRegistry.Sand);
                writer.SaveChunk(key.X, key.Z, persisted);
                persisted.Chunk.ClearDirtySections();
            }
        }

        var regionBytes = Directory.EnumerateFiles(directory, "*.cubitregion")
            .Sum(path => new FileInfo(path).Length);
        var patchBytes = Directory.EnumerateFiles(directory, "*.cubitsectionlog")
            .Sum(path => new FileInfo(path).Length);
        var readSamples = new double[Math.Min(32, keys.Count)];
        var allRestored = true;
        using (var disposable = usePatch
                   ? (IDisposable)new SectionPatchStorage(directory, maxCachedChunks: 0)
                   : new WorldFileStorage(directory, maxCachedChunks: 0))
        {
            var storage = (IChunkStorage)disposable;
            for (var sample = 0; sample < readSamples.Length; sample++)
            {
                var sampleIndex = (sample * 17) % keys.Count;
                var key = keys[sampleIndex];
                var timer = Stopwatch.StartNew();
                var loaded = storage.TryLoadChunk(key.X, key.Z, out var persisted);
                timer.Stop();
                readSamples[sample] = timer.Elapsed.TotalMilliseconds;
                var expected = sampleIndex % 2 == 0 ? BlockRegistry.Stone : BlockRegistry.Sand;
                allRestored &= loaded && persisted.Chunk.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == expected;
            }

            for (var index = 0; index < keys.Count; index++)
            {
                var key = keys[index];
                allRestored &= storage.TryLoadChunk(key.X, key.Z, out var persisted) &&
                    persisted.Chunk.GetBlock(0, Chunk.MaxYExclusive - 1, 0) ==
                    (index % 2 == 0 ? BlockRegistry.Stone : BlockRegistry.Sand);
            }
        }

        return (baselineRegionBytes, regionBytes, patchBytes, Median(readSamples), allRestored);
    }

    try
    {
        Directory.CreateDirectory(regionDirectory);
        Directory.CreateDirectory(patchDirectory);
        var regionKeys = CreateFixture(seed, regionDirectory);
        var patchKeys = CreateFixture(seed, patchDirectory);
        var regionCount = Directory.EnumerateFiles(regionDirectory, "*.cubitregion").Count();
        var patchFixtureCount = Directory.EnumerateFiles(patchDirectory, "*.cubitregion").Count();
        Check(
            "跨 region 基准覆盖 49 区块",
            regionKeys.Length == 49 && patchKeys.Length == 49 && regionCount == 4 && patchFixtureCount == 4,
            $"regionChunks={regionKeys.Length} patchChunks={patchKeys.Length} regions={regionCount}/{patchFixtureCount}");

        var region = RunVariant(regionDirectory, usePatch: false, regionKeys);
        var patch = RunVariant(patchDirectory, usePatch: true, patchKeys);
        Check(
            "region 与 patch 使用相同基准大小",
            region.BaselineRegionBytes == patch.BaselineRegionBytes,
            $"region={region.BaselineRegionBytes} patch={patch.BaselineRegionBytes}");
        Check("默认 v4 region 编辑序列可恢复", region.Restored, $"bytes={region.RegionBytes}");
        Check("Section patch 编辑序列可恢复", patch.Restored, $"region={patch.RegionBytes} patch={patch.PatchBytes}");
        Check("Section patch 日志确实产生增量", patch.PatchBytes > 0, $"patch={patch.PatchBytes}");
        Check(
            "两种后端随机读取均有效",
            region.ReadMedianMilliseconds > 0d && patch.ReadMedianMilliseconds > 0d,
            $"region={region.ReadMedianMilliseconds:F4}ms patch={patch.ReadMedianMilliseconds:F4}ms");

        var report = new
        {
            schema = "cubit.voxel-section-patch-benchmark/v1",
            seed,
            chunkCount = regionKeys.Length,
            regionCount,
            editedSectionCount = regionKeys.Length,
            standard = new
            {
                baselineRegionBytes = region.BaselineRegionBytes,
                afterRegionBytes = region.RegionBytes,
                regionDeltaBytes = region.RegionBytes - region.BaselineRegionBytes,
                randomReadMedianMilliseconds = region.ReadMedianMilliseconds,
            },
            patch = new
            {
                baselineRegionBytes = patch.BaselineRegionBytes,
                afterRegionBytes = patch.RegionBytes,
                patchLogBytes = patch.PatchBytes,
                totalAfterBytes = patch.RegionBytes + patch.PatchBytes,
                totalDeltaBytes = patch.RegionBytes + patch.PatchBytes - patch.BaselineRegionBytes,
                randomReadMedianMilliseconds = patch.ReadMedianMilliseconds,
            },
            patchIsOptionalExperiment = true,
        };
        Console.WriteLine(JsonSerializer.Serialize(report));
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  Section patch 跨 region 基准异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "voxelsectionpatchbenchmarkcheck 全部通过" : $"voxelsectionpatchbenchmarkcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelStorageSessionBenchmarkCheck(uint seed)
{
    const int sessionCount = 5;
    var failures = 0;
    var root = Path.Combine(Path.GetTempPath(), $"cubit_voxel_storage_session_{Guid.NewGuid():N}");
    var regionDirectory = Path.Combine(root, "region");
    var patchDirectory = Path.Combine(root, "patch");

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    static (int X, int Z)[] CreateFixture(uint fixtureSeed, string directory)
    {
        var world = new VoxelWorld(fixtureSeed, WorldType.Flat);
        for (var cz = -3; cz <= 3; cz++)
        {
            for (var cx = -3; cx <= 3; cx++)
            {
                world.GenerateChunkAt(cx, cz);
            }
        }

        WorldFile.Save(world, directory);
        return world.Store.ChunkKeys.OrderBy(key => key.Z).ThenBy(key => key.X).ToArray();
    }

    static bool ApplyEdits(string directory, bool usePatch, IReadOnlyList<(int X, int Z)> keys)
    {
        using var disposable = usePatch
            ? (IDisposable)new SectionPatchStorage(directory, maxCachedChunks: 0)
            : new WorldFileStorage(directory, maxCachedChunks: 0);
        var storage = (IChunkStorage)disposable;
        var writer = (IChunkStorageWriter)disposable;
        for (var index = 0; index < keys.Count; index++)
        {
            var key = keys[index];
            if (!storage.TryLoadChunk(key.X, key.Z, out var persisted))
            {
                return false;
            }

            persisted.Chunk.SetBlock(
                0,
                Chunk.MaxYExclusive - 1,
                0,
                index % 2 == 0 ? BlockRegistry.Stone : BlockRegistry.Sand);
            writer.SaveChunk(key.X, key.Z, persisted);
            persisted.Chunk.ClearDirtySections();
        }

        return true;
    }

    static (double FirstReadMedianMilliseconds, double RemainingReadMedianMilliseconds, bool Restored) RunSessions(
        string directory,
        bool usePatch,
        IReadOnlyList<(int X, int Z)> keys,
        int sessions)
    {
        var firstReads = new double[sessions];
        var remainingReads = new List<double>(sessions * Math.Max(0, keys.Count - 1));
        var restored = true;
        for (var session = 0; session < sessions; session++)
        {
            // 只清理托管对象和本会话存储索引；Windows/Linux 文件系统缓存不会被此命令清空。
            GC.Collect();
            GC.WaitForPendingFinalizers();
            GC.Collect();
            using var disposable = usePatch
                ? (IDisposable)new SectionPatchStorage(directory, maxCachedChunks: 0)
                : new WorldFileStorage(directory, maxCachedChunks: 0);
            var storage = (IChunkStorage)disposable;
            for (var index = 0; index < keys.Count; index++)
            {
                var key = keys[index];
                var timer = Stopwatch.StartNew();
                var loaded = storage.TryLoadChunk(key.X, key.Z, out var persisted);
                timer.Stop();
                var elapsed = timer.Elapsed.TotalMilliseconds;
                if (index == 0)
                {
                    firstReads[session] = elapsed;
                }
                else
                {
                    remainingReads.Add(elapsed);
                }

                var expected = index % 2 == 0 ? BlockRegistry.Stone : BlockRegistry.Sand;
                restored &= loaded && persisted.Chunk.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == expected;
            }
        }

        return (Median(firstReads), Median(remainingReads), restored);
    }

    static (string Root, string Format) GetStorageDeviceInfo(string directory)
    {
        var root = Path.GetPathRoot(directory) ?? string.Empty;
        try
        {
            return (root, string.IsNullOrEmpty(root) ? "unknown" : new DriveInfo(root).DriveFormat);
        }
        catch (Exception)
        {
            return (root, "unavailable");
        }
    }

    try
    {
        Directory.CreateDirectory(regionDirectory);
        Directory.CreateDirectory(patchDirectory);
        var regionKeys = CreateFixture(seed, regionDirectory);
        var patchKeys = CreateFixture(seed, patchDirectory);
        Check(
            "进程级冷会话基准覆盖 49 区块和 4 个 region",
            regionKeys.Length == 49 && patchKeys.Length == 49 &&
            Directory.EnumerateFiles(regionDirectory, "*.cubitregion").Count() == 4 &&
            Directory.EnumerateFiles(patchDirectory, "*.cubitregion").Count() == 4,
            $"regionChunks={regionKeys.Length} patchChunks={patchKeys.Length}");
        var regionBaselineBytes = Directory.EnumerateFiles(regionDirectory, "*.cubitregion")
            .Sum(path => new FileInfo(path).Length);
        var patchBaselineBytes = Directory.EnumerateFiles(patchDirectory, "*.cubitregion")
            .Sum(path => new FileInfo(path).Length);
        Check("两种会话基准使用相同 v4 region 大小", regionBaselineBytes == patchBaselineBytes,
            $"region={regionBaselineBytes} patch={patchBaselineBytes}");
        Check("默认 v4 region 编辑 fixture 成功", ApplyEdits(regionDirectory, usePatch: false, regionKeys));
        Check("Section patch 编辑 fixture 成功", ApplyEdits(patchDirectory, usePatch: true, patchKeys));

        var region = RunSessions(regionDirectory, usePatch: false, regionKeys, sessionCount);
        var patch = RunSessions(patchDirectory, usePatch: true, patchKeys, sessionCount);
        var regionBytes = Directory.EnumerateFiles(regionDirectory, "*.cubitregion")
            .Sum(path => new FileInfo(path).Length);
        var patchRegionBytes = Directory.EnumerateFiles(patchDirectory, "*.cubitregion")
            .Sum(path => new FileInfo(path).Length);
        var patchLogBytes = Directory.EnumerateFiles(patchDirectory, "*.cubitsectionlog")
            .Sum(path => new FileInfo(path).Length);
        Check("默认 v4 region 多会话读取结果可恢复", region.Restored, $"firstMedian={region.FirstReadMedianMilliseconds:F4}ms");
        Check("Section patch 多会话读取结果可恢复", patch.Restored, $"firstMedian={patch.FirstReadMedianMilliseconds:F4}ms");
        Check("Section patch 会话基线 region 不被覆盖", patchRegionBytes == patchBaselineBytes,
            $"baseline={patchBaselineBytes} patch={patchRegionBytes}");
        Check("Section patch 会话日志存在", patchLogBytes > 0, $"patchLog={patchLogBytes}");

        var device = GetStorageDeviceInfo(root);
        var report = new
        {
            schema = "cubit.voxel-storage-session-benchmark/v1",
            seed,
            sessionCount,
            chunkCount = regionKeys.Length,
            cacheLimit = 0,
            managedCacheCleared = true,
            osFileCacheCleared = false,
            deviceRoot = device.Root,
            filesystem = device.Format,
            standard = new
            {
                regionBytes,
                baselineRegionBytes = regionBaselineBytes,
                firstReadMedianMilliseconds = region.FirstReadMedianMilliseconds,
                remainingReadMedianMilliseconds = region.RemainingReadMedianMilliseconds,
            },
            patch = new
            {
                regionBytes = patchRegionBytes,
                baselineRegionBytes = patchBaselineBytes,
                patchLogBytes,
                totalBytes = patchRegionBytes + patchLogBytes,
                firstReadMedianMilliseconds = patch.FirstReadMedianMilliseconds,
                remainingReadMedianMilliseconds = patch.RemainingReadMedianMilliseconds,
            },
            interpretation = "新建存储会话并清理托管缓存的进程级对照；未调用操作系统丢弃文件缓存接口，不代表真实冷盘或 Android 设备结果。",
        };
        Console.WriteLine(JsonSerializer.Serialize(report));
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  进程级冷会话存储基准异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, recursive: true);
        }
    }

    Console.WriteLine(failures == 0
        ? "voxelstoragesessionbenchmarkcheck 全部通过"
        : $"voxelstoragesessionbenchmarkcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelIncrementalSaveCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var directory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_incremental_{Guid.NewGuid():N}");
    try
    {
        var source = new VoxelWorld(20260808u, WorldType.Flat);
        source.GenerateChunkAt(0, 0);
        source.GenerateChunkAt(2, 2);
        source.GenerateChunkAt(40, 40);
        WorldFile.Save(source, directory);

        var centerRegion = WorldFile.RegionPath(directory, 0, 0);
        var beforeLength = new FileInfo(centerRegion).Length;
        var lazyWorld = WorldFile.LoadMetadata(directory);
        using var storage = new WorldFileStorage(directory);
        Check(
            "惰性世界只提交显式读取区块",
            storage.TryLoadChunk(0, 0, out var center) &&
            lazyWorld.CommitLoadedChunk(0, 0, center) &&
            lazyWorld.Store.ChunkKeys.Length == 1);

        var changed = lazyWorld.SetBlockDeferred(
            0,
            Chunk.MaxYExclusive - 1,
            0,
            BlockRegistry.Stone,
            out _);
        Check(
            "修改已加载区块会标记 dirty",
            changed && lazyWorld.DirtyChunkKeys.SequenceEqual([(0, 0)]),
            string.Join(',', lazyWorld.DirtyChunkKeys.Select(key => $"({key.X},{key.Z})")));

        WorldFile.SaveDirty(lazyWorld, storage);
        var afterLength = new FileInfo(centerRegion).Length;
        Check(
            "增量保存追加区块负载并清除 dirty",
            afterLength > beforeLength && lazyWorld.DirtyChunkKeys.Length == 0,
            $"bytes={beforeLength}->{afterLength}");

        var restored = WorldFile.Load(directory);
        Check(
            "增量保存不丢失未加载区块",
            restored.Store.ChunkKeys.Length == 3 &&
            restored.Store.HasChunk(2, 2) &&
            restored.Store.HasChunk(40, 40),
            $"chunks={restored.Store.ChunkKeys.Length}");
        Check(
            "增量保存保留修改区块数据",
            restored.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == BlockRegistry.Stone,
            restored.GetBlock(0, Chunk.MaxYExclusive - 1, 0).ToString());
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  Voxel 增量保存异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(directory))
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "voxelincrementalsavecheck 全部通过" : $"voxelincrementalsavecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectVoxelStreamCheck()
{
    var failures = 0;
    var root = Path.Combine(Path.GetTempPath(), $"cubit_project_voxel_stream_{Guid.NewGuid():N}");

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    try
    {
        WritePersistentProjectFixture(root);
        var repository = new MyFirstCubitProject.WorldRepository(root);
        var summary = repository.Create("惰性项目世界", 20260808u, WorldType.Flat);
        var initial = repository.Load(summary);
        initial.GenerateChunkAt(0, 0);
        initial.GenerateChunkAt(2, 2);
        initial.GenerateChunkAt(40, 40);
        repository.Save(summary, initial);

        using (var session = repository.Open(summary))
        {
            Check(
                "项目 Open 只读取元数据",
                session.World.Store.ChunkKeys.Length == 0,
                $"chunks={session.World.Store.ChunkKeys.Length}");
            Check(
                "项目惰性会话读取附近区块",
                session.Storage.TryLoadChunk(0, 0, out var persisted) &&
                session.World.CommitLoadedChunk(0, 0, persisted) &&
                session.World.Store.ChunkKeys.Length == 1);

            var previousTopBlock = session.World.GetBlock(0, Chunk.MaxYExclusive - 1, 0);
            var changed = session.World.SetBlockDeferred(
                0,
            Chunk.MaxYExclusive - 1,
                0,
                BlockRegistry.Stone,
                out _);
            Check(
                "项目惰性会话记录 dirty 区块",
                changed && session.World.DirtyChunkKeys.Length == 1,
                $"changed={changed} before={previousTopBlock} after={session.World.GetBlock(0, Chunk.MaxYExclusive - 1, 0)} dirty={string.Join(',', session.World.DirtyChunkKeys.Select(key => $"({key.X},{key.Z})"))}");
            repository.Save(summary, session.World, session.Storage);
            Check("项目惰性保存后清除 dirty", session.World.DirtyChunkKeys.Length == 0);
        }

        var restored = repository.Load(summary);
        Check(
            "项目惰性保存保留未加载远端区块",
            restored.Store.ChunkKeys.Length == 3 &&
            restored.Store.HasChunk(2, 2) &&
            restored.Store.HasChunk(40, 40),
            $"chunks={restored.Store.ChunkKeys.Length}");
        Check(
            "项目惰性保存保留附近修改",
            restored.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == BlockRegistry.Stone,
            restored.GetBlock(0, Chunk.MaxYExclusive - 1, 0).ToString());
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  项目惰性世界会话异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "projectvoxelstreamcheck 全部通过" : $"projectvoxelstreamcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectChatCheck()
{
    var failures = 0;
    var position = new System.Numerics.Vector3(0f, 64f, 0f);
    var sky = new MyFirstCubitProject.OverworldSkyState(0);
    var executor = new MyFirstCubitProject.ProjectCommandExecutor(
        () => true,
        () => new MyFirstCubitProject.PlayerMotionState { Position = position, IsOnFloor = true },
        state => position = state.Position,
        () => sky,
        state => sky = state);

    var tp = executor.Execute("/tp 1 65 -2");
    if (!tp.Success || position != new System.Numerics.Vector3(1f, 65f, -2f)) { failures++; Console.WriteLine("chat tp fail"); }
    if (executor.Execute("/tp 1 nope 2").Success) { failures++; Console.WriteLine("chat bad y fail"); }
    if (executor.Execute("/tp 1 2").Success) { failures++; Console.WriteLine("chat arity fail"); }
    if (executor.Execute("/tp 40000000 2 3").Success) { failures++; Console.WriteLine("chat bounds fail"); }
    var time = executor.Execute("/time set 6000");
    if (!time.Success || sky.DayTime != 6000) { failures++; Console.WriteLine($"chat time fail {time.Success} {sky.DayTime}"); }
    if (executor.Execute("/time set -1").Success) { failures++; Console.WriteLine("chat neg time fail"); }
    if (executor.Execute("/unknown").Success) { failures++; Console.WriteLine("chat unknown fail"); }

    var chat = new MyFirstCubitProject.ProjectChatState();
    chat.Open();
    if (!chat.IsOpen || !chat.ConsumeOpeningText('T')) { failures++; Console.WriteLine("chat open fail"); }
    foreach (var character in "/time set 6000")
    {
        chat.Append(character);
    }

    var enteredCommand = chat.TakeInput();
    if (enteredCommand != "/time set 6000") { failures++; Console.WriteLine($"chat append fail [{enteredCommand}]"); }
    var enteredResult = executor.Execute(enteredCommand);
    if (!enteredResult.Success || sky.DayTime != 6000) { failures++; Console.WriteLine("chat entered command fail"); }
    chat.Close();
    if (chat.IsOpen) { failures++; Console.WriteLine("chat close fail"); }

    var autocompleteType = typeof(MyFirstCubitProject.ProjectChatState).Assembly.GetType(
        "MyFirstCubitProject.ProjectCommandAutocomplete");
    var suggestionsMethod = autocompleteType?.GetMethod(
        "GetSuggestions",
        BindingFlags.Public | BindingFlags.Static);
    var rootSuggestions = suggestionsMethod?.Invoke(null, ["/t"]) as IReadOnlyList<string>;
    var timeSuggestions = suggestionsMethod?.Invoke(null, ["/time s"]) as IReadOnlyList<string>;
    if (rootSuggestions is null ||
        !rootSuggestions.SequenceEqual(["/teleport", "/time", "/tp"]) ||
        timeSuggestions is null || !timeSuggestions.SequenceEqual(["/time set"]))
    {
        failures++;
        Console.WriteLine("chat autocomplete catalog fail");
    }

    chat.Open("/t");
    var suggestionsProperty = typeof(MyFirstCubitProject.ProjectChatState).GetProperty(
        "Suggestions",
        BindingFlags.Public | BindingFlags.Instance);
    var acceptSuggestion = typeof(MyFirstCubitProject.ProjectChatState).GetMethod(
        "AcceptSuggestion",
        BindingFlags.Public | BindingFlags.Instance);
    var cycleSuggestion = typeof(MyFirstCubitProject.ProjectChatState).GetMethod(
        "CycleSuggestion",
        BindingFlags.Public | BindingFlags.Instance);
    var selectSuggestion = typeof(MyFirstCubitProject.ProjectChatState).GetMethod(
        "SelectSuggestion",
        BindingFlags.Public | BindingFlags.Instance);
    var acceptSuggestionAt = typeof(MyFirstCubitProject.ProjectChatState).GetMethod(
        "AcceptSuggestionAt",
        BindingFlags.Public | BindingFlags.Instance);
    var stateSuggestions = suggestionsProperty?.GetValue(chat) as IReadOnlyList<string>;
    var acceptedFirst = acceptSuggestion?.Invoke(chat, null) as bool?;
    cycleSuggestion?.Invoke(chat, [1]);
    var acceptedSecond = acceptSuggestion?.Invoke(chat, null) as bool?;
    if (stateSuggestions is null || !stateSuggestions.SequenceEqual(rootSuggestions ?? []) ||
        acceptedFirst != true || acceptedSecond != true || chat.Input != "/time")
    {
        failures++;
        Console.WriteLine("chat autocomplete state fail");
    }
    chat.Open("/t");
    var selectedByPointer = selectSuggestion?.Invoke(chat, [1]) as bool?;
    if (selectedByPointer != true || chat.SelectedSuggestionIndex != 1 || chat.Input != "/t")
    {
        failures++;
        Console.WriteLine("chat autocomplete hover selection fail");
    }
    var acceptedClickedSuggestion = acceptSuggestionAt?.Invoke(chat, [2]) as bool?;
    if (acceptedClickedSuggestion != true || chat.SelectedSuggestionIndex != 2 || chat.Input != "/tp")
    {
        failures++;
        Console.WriteLine("chat autocomplete mouse selection fail");
    }
    chat.Close();

    var suggestionListType = typeof(MyFirstCubitProject.Desktop.MyFirstCubitDesktopPresentation).Assembly.GetType(
        "MyFirstCubitProject.Desktop.ProjectChatSuggestionList");
    var suggestionList = suggestionListType is null ? null : Activator.CreateInstance(suggestionListType);
    var tryGetSuggestionIndex = suggestionListType?.GetMethod(
        "TryGetSuggestionIndex",
        BindingFlags.Public | BindingFlags.Instance);
    var scrollSuggestions = suggestionListType?.GetMethod(
        "Scroll",
        BindingFlags.Public | BindingFlags.Instance);
    var suggestionOffset = suggestionListType?.GetProperty(
        "Offset",
        BindingFlags.Public | BindingFlags.Instance);
    var firstHitArguments = new object?[] { 8, 3f, 277f, null };
    var firstHit = suggestionList is null || tryGetSuggestionIndex is null
        ? null
        : tryGetSuggestionIndex.Invoke(suggestionList, firstHitArguments) as bool?;
    var scrollArguments = new object?[] { 8, 3f, 277f, -1f };
    var scrolled = suggestionList is null || scrollSuggestions is null
        ? null
        : scrollSuggestions.Invoke(suggestionList, scrollArguments) as bool?;
    var scrolledHitArguments = new object?[] { 8, 3f, 277f, null };
    var scrolledHit = suggestionList is null || tryGetSuggestionIndex is null
        ? null
        : tryGetSuggestionIndex.Invoke(suggestionList, scrolledHitArguments) as bool?;
    var ignoredScrollArguments = new object?[] { 8, 500f, 277f, -1f };
    var ignoredScroll = suggestionList is null || scrollSuggestions is null
        ? null
        : scrollSuggestions.Invoke(suggestionList, ignoredScrollArguments) as bool?;
    if (suggestionList is not null && scrollSuggestions is not null)
    {
        for (var index = 0; index < 4; index++)
        {
            _ = scrollSuggestions.Invoke(suggestionList, [8, 3f, 277f, -1f]);
        }
    }

    var offsetAtBottom = suggestionList is null || suggestionOffset is null
        ? null
        : suggestionOffset.GetValue(suggestionList) as int?;
    if (suggestionList is not null && scrollSuggestions is not null)
    {
        for (var index = 0; index < 4; index++)
        {
            _ = scrollSuggestions.Invoke(suggestionList, [8, 3f, 277f, 1f]);
        }
    }

    var offsetAtTop = suggestionList is null || suggestionOffset is null
        ? null
        : suggestionOffset.GetValue(suggestionList) as int?;
    if (firstHit != true || firstHitArguments[3] is not 0 ||
        scrolled != true || scrolledHit != true || scrolledHitArguments[3] is not 1 ||
        ignoredScroll != false || offsetAtBottom != 3 || offsetAtTop != 0)
    {
        failures++;
        Console.WriteLine("chat autocomplete pointer scroll behavior fail");
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var chatRendererPath = workspaceRoot is null
        ? string.Empty
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "MyFirstCubitProject.Desktop", "ProjectChatRenderer.cs");
    var chatRendererSource = File.Exists(chatRendererPath) ? File.ReadAllText(chatRendererPath) : string.Empty;
    var presentationPath = workspaceRoot is null
        ? string.Empty
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "MyFirstCubitProject.Desktop", "MyFirstCubitDesktopPresentation.cs");
    var presentationSource = File.Exists(presentationPath) ? File.ReadAllText(presentationPath) : string.Empty;
    var presentationHostPath = repositoryRoot is null
        ? string.Empty
        : Path.Combine(repositoryRoot, "src", "Cubit.ImGui", "ProjectImGuiPresentationHost.cs");
    var presentationHostSource = File.Exists(presentationHostPath) ? File.ReadAllText(presentationHostPath) : string.Empty;
    var sampleProgramPath = repositoryRoot is null
        ? string.Empty
        : Path.Combine(repositoryRoot, "hosts", "Cubit.Sample", "Program.cs");
    var sampleProgramSource = File.Exists(sampleProgramPath) ? File.ReadAllText(sampleProgramPath) : string.Empty;
    if (!chatRendererSource.Contains("case Key.Tab", StringComparison.Ordinal) ||
        !chatRendererSource.Contains("_state.AcceptSuggestion()", StringComparison.Ordinal) ||
        !chatRendererSource.Contains("_state.Suggestions", StringComparison.Ordinal) ||
        !chatRendererSource.Contains("ProjectChatSuggestionList", StringComparison.Ordinal) ||
        chatRendererSource.Contains("ImGuiApi.InvisibleButton($\"##chat-suggestion-", StringComparison.Ordinal) ||
        chatRendererSource.Contains("ImGuiApi.IsItemClicked()", StringComparison.Ordinal) ||
        !chatRendererSource.Contains("_state.SelectSuggestion(index)", StringComparison.Ordinal) ||
        !chatRendererSource.Contains("_state.AcceptSuggestionAt(index)", StringComparison.Ordinal) ||
        !chatRendererSource.Contains("OnMouseWheel", StringComparison.Ordinal) ||
        !chatRendererSource.Contains("ImGuiWindowFlags.NoInputs", StringComparison.Ordinal) ||
        !presentationSource.Contains("if (_chat.IsOpen)", StringComparison.Ordinal) ||
        !presentationSource.Contains("_chat.OnMouseMove(x, y);", StringComparison.Ordinal) ||
        !presentationSource.Contains("_chat.OnMouseButton(button, down);", StringComparison.Ordinal) ||
        !presentationSource.Contains("_chat.OnMouseWheel(y);", StringComparison.Ordinal) ||
        !presentationHostSource.Contains("void OnMouseWheel(float y);", StringComparison.Ordinal) ||
        !presentationHostSource.Contains("_presentation.OnMouseWheel(y);", StringComparison.Ordinal) ||
        !sampleProgramSource.Contains("mouse.Scroll +=", StringComparison.Ordinal) ||
        !sampleProgramSource.Contains("presentation.OnMouseWheel(wheel.Y)", StringComparison.Ordinal))
    {
        failures++;
        Console.WriteLine("chat autocomplete presentation fail");
    }

    Console.WriteLine(failures == 0
        ? "projectchatcheck 全部通过"
        : $"projectchatcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectPlayerEcsCheck()
{
    var failures = 0;
    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    Check("首个项目根目录可定位", projectRoot is not null && Directory.Exists(projectRoot), projectRoot ?? "missing");
    if (projectRoot is null || !Directory.Exists(projectRoot))
    {
        Console.WriteLine($"projectplayerecscheck 失败 {failures} 项");
        return 1;
    }

    var sourceDirectory = Path.Combine(projectRoot, "src");
    var sourceText = Directory.Exists(sourceDirectory)
        ? string.Join("\n", Directory.GetFiles(sourceDirectory, "*.cs", SearchOption.AllDirectories).Select(File.ReadAllText))
        : string.Empty;
    var gameplayPath = Path.Combine(projectRoot, "scenes", "gameplay.cscene");
    var gameplayText = File.Exists(gameplayPath) ? File.ReadAllText(gameplayPath) : string.Empty;
    var playerScenePath = Path.Combine(projectRoot, "scenes", "entities", "player.cscene");
    var playerSceneText = File.Exists(playerScenePath) ? File.ReadAllText(playerScenePath) : string.Empty;
    Check(
        "项目声明玩家 ECS 桥接类型",
        sourceText.Contains("PlayerEcsBridgeNode", StringComparison.Ordinal),
        sourceDirectory);
    Check(
        "gameplay 场景作者化声明玩家 ECS 桥接节点",
        gameplayText.Contains("Cubit.Core.Scene.SceneInstance", StringComparison.Ordinal) &&
        playerSceneText.Contains("PlayerEcsBridgeNode", StringComparison.Ordinal),
        $"gameplay={gameplayPath} player={playerScenePath}");
    Check(
        "玩家控制器声明 ECS 桥接路径",
        sourceText.Contains("EcsBridgePath", StringComparison.Ordinal),
        sourceDirectory);
    var motionStateType = typeof(PhysicsWorld3D).Assembly.GetType("Cubit.Physics.Scene.CharacterMotionState");
    var immediateMoveMethod = typeof(PhysicsWorld3D).GetMethod("MoveCharacterImmediate", BindingFlags.Public | BindingFlags.Instance);
    Check(
        "Physics 插件提供 ECS 角色运动数据契约",
        motionStateType is not null && immediateMoveMethod is not null,
        $"state={motionStateType is not null} move={immediateMoveMethod is not null}");

    try
    {
        using var session = CreateVoxelProjectSession(new FakeRenderBackend(), 20260808u, workerCount: 1, worldType: WorldType.Flat);
        var bridge = session.Scene.Tree.GetNode(new NodePath("/Root/Physics/PlayerEcs")) as MyFirstCubitProject.PlayerEcsBridgeNode;
        var player = session.Scene.Tree.GetNode(new NodePath("/Root/Physics/Player")) as MyFirstCubitProject.PlayerController;
        var ecsNode = bridge?.Children.OfType<EcsNode>().SingleOrDefault();
        var playerEntity = bridge?.PlayerEntity ?? default;
        var ecsWorld = ecsNode?.World;
        Check(
            "玩家 ECS 桥接在正式 gameplay 场景创建唯一 Entity",
            bridge is { IsPlayerBound: true, PlayerEntityCount: 1 } && player is not null,
            $"bridge={bridge is not null} bound={bridge?.IsPlayerBound} entities={bridge?.PlayerEntityCount} player={player is not null}");
        Check(
            "玩家 ECS 使用宿主注入的共享 JobSystem",
            ecsNode is { IsInitialized: true } && ReferenceEquals(ecsNode.Jobs, session.Scene.Runtime.Jobs),
            $"initialized={ecsNode?.IsInitialized} shared={ReferenceEquals(ecsNode?.Jobs, session.Scene.Runtime.Jobs)}");
        var initialInventory = bridge?.ReadInventoryState();
        Check(
            "玩家 ECS 初始快捷栏包含可放置方块",
            initialInventory is { } inventory &&
            inventory.GetSlot(0) == new MyFirstCubitProject.ProjectInventorySlot(BlockRegistry.Grass, MyFirstCubitProject.ProjectInventoryState.MaxStackSize) &&
            inventory.GetSlot(6).ItemId == BlockRegistry.GetId("my_first:water") &&
            inventory.GetSlot(6).Count == 1,
            initialInventory is null ? "missing" : $"slot0={initialInventory.Value.GetSlot(0)} slot6={initialInventory.Value.GetSlot(6)}");
        var bridgeLimitChanged = bridge?.TrySetInventoryItemMaxStackSize(BlockRegistry.Grass, 16) == true;
        var bridgeLimitedInventory = bridge?.ReadInventoryState();
        Check(
            "玩家 ECS 桥接应用物品堆叠上限并重排库存",
            bridgeLimitChanged && bridgeLimitedInventory is { } limited &&
            limited.GetSlot(0).Count == 16 && limited.GetSlot(7).Count == 16 &&
            limited.GetSlot(8).Count == 16 && limited.GetSlot(6).Count == 1,
            bridgeLimitedInventory is null ? "missing" : $"changed={bridgeLimitChanged} max={MyFirstCubitProject.ProjectItemCatalog.GetMaxStackSize(BlockRegistry.Grass)} slots={string.Join(',', Enumerable.Range(0, 9).Select(index => bridgeLimitedInventory.Value.GetSlot(index).Count))}");
        _ = bridge?.TrySetInventoryItemMaxStackSize(BlockRegistry.Grass, MyFirstCubitProject.ProjectInventoryState.MaxStackSize);

        var progressSummary = new MyFirstCubitProject.WorldSummary(
            "world-opening-progress",
            "进度回归",
            1u,
            WorldType.Flat,
            DateTimeOffset.UtcNow,
            DateTimeOffset.UtcNow);
        Check(
            "世界进入进度拒绝越界任务数",
            CaptureException(() => new MyFirstCubitProject.WorldOpeningProgress(
                progressSummary,
                MyFirstCubitProject.WorldOpeningStage.WaitSpawnChunks,
                101,
                100)) is ArgumentOutOfRangeException);
        Check(
            "世界进入失败快照必须包含错误",
            CaptureException(() => new MyFirstCubitProject.WorldOpeningProgress(
                progressSummary,
                MyFirstCubitProject.WorldOpeningStage.Failed,
                0,
                100)) is ArgumentException);

        var menuState = session.Scene.Runtime.Context.GetRequiredService<MyFirstCubitProject.SingleplayerMenuState>();
        menuState.ShowWorldSelection();
        menuState.BeginOpeningWorld();
        menuState.BeginPlaying();
        player?.SetGameplayActive(true);
        session.Scene.Tree.Paused = false;
        var voxelInput = session.Scene.Runtime.Context.GetRequiredService<VoxelInputState>();
        session.Scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.Digit6, true));
        session.Scene.ProcessFrame(1d / 20d);
        var selectedInventory = bridge?.ReadInventoryState();
        Check(
            "数字键选择同步 ECS 快捷栏选中槽位",
            selectedInventory is { SelectedHotbarSlot: 5 } selected &&
            selected.GetSlot(5).ItemId == BlockRegistry.GetId("my_first:oak_leaves") &&
            voxelInput.BuildSnapshot().SelectedBlock == BlockRegistry.GetId("my_first:oak_leaves"),
            selectedInventory is null ? "missing" : $"slot={selectedInventory.Value.SelectedHotbarSlot} block={voxelInput.BuildSnapshot().SelectedBlock}");
        session.Input.SetAction(InputAction.Forward, true);
        session.Scene.ProcessFrame(1d / 20d);
        var input = bridge?.ReadSimulationInput() ?? default;
        Check(
            "玩家 ECS System 在固定步读取通用输入",
            input.Forward && !input.Back,
            $"forward={input.Forward} back={input.Back}");
        Check(
            "正式玩家 ECS 挂载项目空间兴趣 System",
            bridge?.InterestSystem is { DesiredPartitionCount: > 0 },
            $"desired={bridge?.InterestSystem?.DesiredPartitionCount}");
        var motion = bridge?.ReadMotionState() ?? default;
        Check(
            "玩家 ECS 运动状态与 Node 表现保持单向同步",
            player is not null && motion.Position == player.Position && motion.Velocity == player.Velocity,
            $"ecsPosition={motion.Position} nodePosition={player?.Position} ecsVelocity={motion.Velocity} nodeVelocity={player?.Velocity}");

        using (var failureSession = CreateVoxelProjectSession(new FakeRenderBackend(), 20260808u, workerCount: 1, worldType: WorldType.Flat))
        {
            var failureMenu = failureSession.Scene.Tree.GetNode(new NodePath("/Root/SingleplayerMenu")) as MyFirstCubitProject.SingleplayerMenuController;
            var failureWorld = failureSession.Scene.Tree.GetNode(new NodePath("/Root/World")) as VoxelWorldNode;
            var missingWorld = new MyFirstCubitProject.WorldSummary(
                "world-opening-missing",
                "缺失世界",
                1u,
                WorldType.Flat,
                DateTimeOffset.UtcNow,
                DateTimeOffset.UtcNow);
            failureMenu?.SelectWorld(missingWorld);
            var openingFailureStarted = failureMenu?.OpenSelectedWorld() == true;
            failureSession.Scene.ProcessFrame(0d);
            var openingFailureCleaned = failureMenu is { } failedMenu &&
                failedMenu.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.WorldSelection &&
                failedMenu.OpeningProgress?.Stage == MyFirstCubitProject.WorldOpeningStage.Failed &&
                !string.IsNullOrWhiteSpace(failedMenu.LastError) &&
                failureWorld?.Streamer is null;
            Check(
                "世界进入异常释放临时会话并返回选档",
                openingFailureStarted && openingFailureCleaned,
                $"started={openingFailureStarted} cleaned={openingFailureCleaned} " +
                $"screen={failureMenu?.State.Screen} stage={failureMenu?.OpeningProgress?.Stage} " +
                $"error={failureMenu?.LastError} streamer={(failureWorld?.Streamer is null ? "null" : "active")}");
        }

        session.Input.SetAction(InputAction.Forward, false);
        session.Dispose();
        Check(
            "玩家场景卸载后 ECS Entity 失效",
            ecsWorld is not null && !ecsWorld.IsAlive(playerEntity),
            $"entity={playerEntity} alive={ecsWorld?.IsAlive(playerEntity)}");
    }
    catch (Exception exception)
    {
        Check("玩家 ECS 正式场景运行桥接", false, exception.ToString());
    }

    Console.WriteLine(failures == 0
        ? "projectplayerecscheck 全部通过"
        : $"projectplayerecscheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectPlayerGameplayCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var projectAssembly = typeof(MyFirstCubitProject.PlayerController).Assembly;
    var gateType = projectAssembly.GetType("MyFirstCubitProject.PlayerVoxelInteractionGate");
    var interactionKindType = projectAssembly.GetType("MyFirstCubitProject.PlayerVoxelInteractionKind");
    var edgeGuardType = projectAssembly.GetType("MyFirstCubitProject.PlayerSneakEdgeGuard");
    Check("项目层提供方块交互按键门禁", gateType is not null && interactionKindType is not null,
        $"gate={gateType is not null} kind={interactionKindType is not null}");
    Check("项目层提供潜行边缘位移保护", edgeGuardType is not null, edgeGuardType?.FullName ?? "missing");

    if (gateType is not null && interactionKindType is not null)
    {
        try
        {
            var gate = Activator.CreateInstance(gateType, [0.1d]);
            var consume = gateType.GetMethod("TryConsume", [interactionKindType, typeof(bool), typeof(double)]);
            var breakKind = Enum.Parse(interactionKindType, "Break");
            var placeKind = Enum.Parse(interactionKindType, "Place");
            var firstBreak = consume?.Invoke(gate, [breakKind, true, 0d]) as bool?;
            var heldBreak = consume?.Invoke(gate, [breakKind, true, 0.05d]) as bool?;
            var repeatedBreak = consume?.Invoke(gate, [breakKind, true, 0.10d]) as bool?;
            _ = consume?.Invoke(gate, [breakKind, false, 0.11d]);
            var tooSoonBreak = consume?.Invoke(gate, [breakKind, true, 0.12d]) as bool?;
            _ = consume?.Invoke(gate, [breakKind, false, 0.21d]);
            var nextBreak = consume?.Invoke(gate, [breakKind, true, 0.21d]) as bool?;
            var firstPlace = consume?.Invoke(gate, [placeKind, true, 0d]) as bool?;
            var heldPlace = consume?.Invoke(gate, [placeKind, true, 0.10d]) as bool?;
            var repeatedPlace = consume?.Invoke(gate, [placeKind, true, 0.20d]) as bool?;
            Check(
                "长按方块交互首击立即触发、冷却后持续重复且短点击仍被防抖",
                firstBreak == true && heldBreak == false && repeatedBreak == true && tooSoonBreak == false &&
                nextBreak == true && firstPlace == true && heldPlace == false && repeatedPlace == true,
                $"break={firstBreak}/{heldBreak}/{repeatedBreak}/{tooSoonBreak}/{nextBreak} " +
                $"place={firstPlace}/{heldPlace}/{repeatedPlace}");
        }
        catch (Exception exception)
        {
            Check("方块交互按键门禁执行", false, exception.Message);
        }
    }

    if (edgeGuardType is not null)
    {
        try
        {
            var limit = edgeGuardType.GetMethod("LimitHorizontalDisplacement", BindingFlags.Public | BindingFlags.Static);
            Func<int, int, int, bool> singleSupportBlock = static (x, y, z) => x == 0 && y == 0 && z == 0;
            var result = limit?.Invoke(null, [
                new Vector3(1f, 0f, 0f),
                new Vector3(0.5f, 0f, 0.5f),
                0.35f,
                1f,
                0.65f,
                singleSupportBlock]) as Vector3?;
            Check(
                "潜行在单格边缘按原版 0.05 步长裁剪水平位移",
                result is Vector3 displacement && displacement.X is > 0f and < 1f && MathF.Abs(displacement.Z) < 0.0001f,
                result?.ToString() ?? "missing");
        }
        catch (Exception exception)
        {
            Check("潜行边缘保护执行", false, exception.Message);
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var playerControllerPath = workspaceRoot is null
        ? null
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "PlayerController.cs");
    var playerControllerSource = playerControllerPath is not null && File.Exists(playerControllerPath)
        ? File.ReadAllText(playerControllerPath)
        : string.Empty;
    Check(
        "潜行边缘保护不因刚离地一拍的 IsOnFloor=false 而跳过",
        playerControllerSource.Contains("if (crouching && ecsMotion is { } crouchingMotion)", StringComparison.Ordinal) &&
        !playerControllerSource.Contains("crouching && (ecsMotion?.IsOnFloor", StringComparison.Ordinal),
        playerControllerPath ?? "missing");

    var crouchFromMotion = typeof(MyFirstCubitProject.PlayerActionState).GetMethod(
        "FromMotion",
        BindingFlags.Public | BindingFlags.Static,
        [typeof(MyFirstCubitProject.PlayerMotionState), typeof(bool)]);
    var crouchAction = crouchFromMotion?.Invoke(null,
        [new MyFirstCubitProject.PlayerMotionState
        {
            Position = Vector3.Zero,
            Velocity = Vector3.UnitX,
            IsOnFloor = true,
        }, true]);
    Check(
        "潜行运动状态写入 Sneak locomotion 与 Crouch 标志",
        crouchAction is MyFirstCubitProject.PlayerActionState action &&
        action.Locomotion == MyFirstCubitProject.PlayerLocomotionMode.Sneak &&
        (action.Flags & MyFirstCubitProject.PlayerActionFlags.Crouch) != 0,
        crouchAction?.ToString() ?? "missing");

    try
    {
        using var session = CreateVoxelProjectSession(new FakeRenderBackend(), 20260808u, workerCount: 1, worldType: WorldType.Flat);
        var menuState = session.Scene.Runtime.Context.GetRequiredService<MyFirstCubitProject.SingleplayerMenuState>();
        menuState.ShowWorldSelection();
        menuState.BeginOpeningWorld();
        menuState.BeginPlaying();
        var player = session.Scene.Tree.GetNode("/Root/Physics/Player") as MyFirstCubitProject.PlayerController;
        var bridge = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs") as MyFirstCubitProject.PlayerEcsBridgeNode;
        player?.SetGameplayActive(true);
        session.Scene.Tree.Paused = false;
        session.Input.SetAction(InputAction.Down, true);
        session.Input.SetAction(InputAction.Forward, true);
        session.Scene.ProcessFrame(1d / 20d);
        var runtimeAction = bridge?.ReadActionState() ?? default;
        Check(
            "Shift 输入在项目运行时进入潜行表现状态",
            runtimeAction.Locomotion == MyFirstCubitProject.PlayerLocomotionMode.Sneak &&
            (runtimeAction.Flags & MyFirstCubitProject.PlayerActionFlags.Crouch) != 0,
            $"locomotion={runtimeAction.Locomotion} flags={runtimeAction.Flags}");
    }
    catch (Exception exception)
    {
        Check("潜行项目运行时桥接", false, exception.Message);
    }

    Console.WriteLine(failures == 0
        ? "projectplayergameplaycheck 全部通过"
        : $"projectplayergameplaycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectPlayerPersistenceCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var projectAssembly = typeof(MyFirstCubitProject.WorldRepository).Assembly;
    var snapshotType = projectAssembly.GetType("MyFirstCubitProject.PlayerEntitySnapshot");
    var projectileSnapshotType = projectAssembly.GetType("MyFirstCubitProject.ProjectProjectileSnapshot");
    var monsterSnapshotType = projectAssembly.GetType("MyFirstCubitProject.ProjectMonsterSnapshot");
    var playerStateProperty = typeof(MyFirstCubitProject.WorldOpenSession).GetProperty("PlayerState");
    var projectileStateProperty = typeof(MyFirstCubitProject.WorldOpenSession).GetProperty("Projectiles");
    var monsterStateProperty = typeof(MyFirstCubitProject.WorldOpenSession).GetProperty("Monsters");
    var saveSnapshotMethod = typeof(MyFirstCubitProject.WorldRepository).GetMethod("SavePlayerState");
    var saveProjectileMethod = typeof(MyFirstCubitProject.WorldRepository).GetMethod("SaveProjectiles");
    var saveMonsterMethod = typeof(MyFirstCubitProject.WorldRepository).GetMethod("SaveMonsters");
    var deleteWorldMethod = typeof(MyFirstCubitProject.WorldRepository).GetMethod("Delete", [typeof(MyFirstCubitProject.WorldSummary)]);
    var menuStateType = projectAssembly.GetType("MyFirstCubitProject.SingleplayerMenuState");
    var menuScreenType = projectAssembly.GetType("MyFirstCubitProject.SingleplayerMenuScreen");
    var deleteConfirmValue = menuScreenType?.GetField("DeleteConfirm")?.GetValue(null);
    var openingWorldValue = menuScreenType?.GetField("OpeningWorld")?.GetValue(null);
    var showDeleteConfirmMethod = menuStateType?.GetMethod("ShowDeleteConfirm");
    var cancelDeleteMethod = menuStateType?.GetMethod("CancelDelete");
    var beginOpeningWorldMethod = menuStateType?.GetMethod("BeginOpeningWorld");
    var bridgeType = projectAssembly.GetType("MyFirstCubitProject.PlayerEcsBridgeNode");
    var captureProjectileMethod = bridgeType?.GetMethod("CaptureProjectiles");
    var restoreProjectileMethod = bridgeType?.GetMethod("RestoreProjectiles");
    var captureMonsterMethod = bridgeType?.GetMethod("CaptureMonsters");
    var restoreMonsterMethod = bridgeType?.GetMethod("RestoreMonsters");
    Check(
        "项目提供独立玩家实体快照类型",
        snapshotType is not null,
        snapshotType?.FullName ?? "missing");
    Check(
        "项目提供独立 Projectile 实体快照类型",
        projectileSnapshotType is not null,
        projectileSnapshotType?.FullName ?? "missing");
    Check(
        "项目提供独立 Monster 实体快照类型",
        monsterSnapshotType is not null,
        monsterSnapshotType?.FullName ?? "missing");
    Check(
        "世界打开会话携带玩家实体快照",
        playerStateProperty is not null,
        playerStateProperty?.PropertyType.FullName ?? "missing");
    Check(
        "世界打开会话携带 Projectile 实体快照",
        projectileStateProperty is not null,
        projectileStateProperty?.PropertyType.FullName ?? "missing");
    Check(
        "世界打开会话携带 Monster 实体快照",
        monsterStateProperty is not null,
        monsterStateProperty?.PropertyType.FullName ?? "missing");
    Check(
        "项目仓库提供原子玩家实体快照保存入口",
        saveSnapshotMethod is not null,
        saveSnapshotMethod?.ToString() ?? "missing");
    Check(
        "项目仓库提供原子 Projectile 实体快照保存入口",
        saveProjectileMethod is not null,
        saveProjectileMethod?.ToString() ?? "missing");
    Check(
        "项目仓库提供原子 Monster 实体快照保存入口",
        saveMonsterMethod is not null,
        saveMonsterMethod?.ToString() ?? "missing");
    Check("菜单状态包含删除确认屏幕", deleteConfirmValue is not null, "DeleteConfirm");
    Check("菜单状态包含世界加载屏幕", openingWorldValue is not null, "OpeningWorld");
    Check("菜单状态提供删除确认/取消入口", showDeleteConfirmMethod is not null && cancelDeleteMethod is not null,
        $"show={showDeleteConfirmMethod is not null} cancel={cancelDeleteMethod is not null}");
    Check("菜单状态提供开始加载入口", beginOpeningWorldMethod is not null, "BeginOpeningWorld");
    Check("项目仓库提供按摘要删除入口", deleteWorldMethod is not null, "Delete(WorldSummary)");

    var menuControllerType = projectAssembly.GetType("MyFirstCubitProject.SingleplayerMenuController");
    var requestDeleteMethod = menuControllerType?.GetMethod("RequestDeleteSelectedWorld");
    var cancelControllerDeleteMethod = menuControllerType?.GetMethod("CancelDelete");
    var confirmDeleteMethod = menuControllerType?.GetMethod("ConfirmDelete");
    Check(
        "单人菜单控制器提供删除确认动作",
        requestDeleteMethod is not null && cancelControllerDeleteMethod is not null && confirmDeleteMethod is not null,
        $"request={requestDeleteMethod is not null} cancel={cancelControllerDeleteMethod is not null} confirm={confirmDeleteMethod is not null}");
    Check(
        "玩家 ECS 桥接提供 Projectile 捕获/恢复入口",
        captureProjectileMethod is not null && restoreProjectileMethod is not null,
        $"capture={captureProjectileMethod is not null} restore={restoreProjectileMethod is not null}");
    Check(
        "玩家 ECS 桥接提供 Monster 捕获/恢复入口",
        captureMonsterMethod is not null && restoreMonsterMethod is not null,
        $"capture={captureMonsterMethod is not null} restore={restoreMonsterMethod is not null}");
    var menuControllerSourcePath = Path.Combine(
        Directory.GetParent(FindCubitRepositoryRoot() ?? string.Empty)?.FullName ?? string.Empty,
        "我的第一个cubit项目",
        "src",
        "SingleplayerMenuController.cs");
    var menuControllerSource = File.Exists(menuControllerSourcePath)
        ? File.ReadAllText(menuControllerSourcePath)
        : string.Empty;
    Check(
        "退出清理逐项安全释放并保留首个异常",
        menuControllerSource.Contains("SafeDisposeSession", StringComparison.Ordinal) &&
        menuControllerSource.Contains("finally", StringComparison.Ordinal) &&
        menuControllerSource.Contains("firstFailure ??= exception", StringComparison.Ordinal),
        menuControllerSourcePath);

    try
    {
        using (var deleteSession = CreateVoxelProjectSession(
            new FakeRenderBackend(),
            20260808u,
            workerCount: 1,
            worldType: WorldType.Flat))
        {
            var deleteMenu = deleteSession.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
            var deleteRepository = deleteSession.Scene.Runtime.Context.GetRequiredService<MyFirstCubitProject.WorldRepository>();
            var deletable = deleteRepository.Create("删除确认回归世界", 20260808u, WorldType.Flat);
            deleteMenu?.ShowWorldSelection();
            deleteMenu?.SelectWorld(deletable);

            var requestStarted = requestDeleteMethod is not null &&
                deleteMenu is not null &&
                CaptureException(() => requestDeleteMethod.Invoke(deleteMenu, null)) is null;
            var remainsAfterRequest = deleteRepository.List().Any(world => world.Id == deletable.Id);
            Check(
                "请求删除只进入确认界面且不删除世界",
                requestStarted && deleteMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.DeleteConfirm && remainsAfterRequest,
                $"started={requestStarted} screen={deleteMenu?.State.Screen} remains={remainsAfterRequest}");

            var cancelled = cancelControllerDeleteMethod is not null &&
                deleteMenu is not null &&
                CaptureException(() => cancelControllerDeleteMethod.Invoke(deleteMenu, null)) is null;
            var remainsAfterCancel = deleteRepository.List().Any(world => world.Id == deletable.Id);
            Check(
                "取消删除返回选档且保留世界",
                cancelled && deleteMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.WorldSelection && remainsAfterCancel,
                $"cancelled={cancelled} screen={deleteMenu?.State.Screen} remains={remainsAfterCancel}");

            if (deleteMenu is not null && requestDeleteMethod is not null)
            {
                requestDeleteMethod.Invoke(deleteMenu, null);
            }
            var confirmed = confirmDeleteMethod is not null &&
                deleteMenu is not null &&
                CaptureException(() => confirmDeleteMethod.Invoke(deleteMenu, null)) is null;
            var removedAfterConfirm = !deleteRepository.List().Any(world => world.Id == deletable.Id);
            Check(
                "确认删除永久移除世界并清除选择",
                confirmed && deleteMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.WorldSelection &&
                deleteMenu.SelectedWorld is null && removedAfterConfirm && string.IsNullOrWhiteSpace(deleteMenu.LastError),
                $"confirmed={confirmed} screen={deleteMenu?.State.Screen} selected={deleteMenu?.SelectedWorld?.Id ?? "null"} removed={removedAfterConfirm} error={deleteMenu?.LastError ?? "null"}");

            var missing = new MyFirstCubitProject.WorldSummary(
                "world-delete-missing",
                "缺失删除世界",
                1u,
                WorldType.Flat,
                DateTimeOffset.UtcNow,
                DateTimeOffset.UtcNow);
            deleteMenu?.SelectWorld(missing);
            if (deleteMenu is not null && requestDeleteMethod is not null)
            {
                requestDeleteMethod.Invoke(deleteMenu, null);
            }
            var failedDelete = confirmDeleteMethod is not null &&
                deleteMenu is not null &&
                CaptureException(() => confirmDeleteMethod.Invoke(deleteMenu, null)) is null;
            Check(
                "删除失败返回选档并保留可诊断错误",
                failedDelete && deleteMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.WorldSelection &&
                !string.IsNullOrWhiteSpace(deleteMenu.LastError),
                $"failed={failedDelete} screen={deleteMenu?.State.Screen} error={deleteMenu?.LastError ?? "null"}");
        }

        using var openingProgressSession = CreateVoxelProjectSession(
            new FakeRenderBackend(),
            20260808u,
            workerCount: 1,
            worldType: WorldType.Flat);
        var openingMenu = openingProgressSession.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        var firstCreated = openingMenu?.CreateWorld("连续打开一号世界", "20260808", WorldType.Flat) == true;
        for (var frame = 0; firstCreated && openingMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.OpeningWorld && frame < 900; frame++)
        {
            openingProgressSession.Scene.ProcessFrame(1d / 60d);
            Thread.Sleep(1);
        }

        var repository = openingProgressSession.Scene.Runtime.Context.GetRequiredService<MyFirstCubitProject.WorldRepository>();
        var secondSummary = repository.Create("连续打开二号世界", 20260809u, WorldType.Flat);
        openingMenu = openingProgressSession.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        openingMenu?.SelectWorld(secondSummary);
        var secondStarted = openingMenu?.OpenSelectedWorld() == true;
        var secondProgress = openingMenu?.OpeningProgress;
        Check(
            "连续打开第二个世界时加载进度从零开始",
            firstCreated && secondStarted && secondProgress is
            {
                Summary: { Id: var id },
                Stage: MyFirstCubitProject.WorldOpeningStage.OpenMetadata,
                CompletedTasks: 0,
            } && id == secondSummary.Id,
            $"first={firstCreated} second={secondStarted} summary={secondProgress?.Summary.Id} " +
            $"stage={secondProgress?.Stage} completed={secondProgress?.CompletedTasks}");
        openingProgressSession.Scene.ProcessFrame(0d);
    }
    catch (Exception exception)
    {
        Check("连续打开世界进度隔离回归", false, exception.ToString());
    }

    foreach (var invalidRadius in new[] { 0, -1 })
    {
        try
        {
            using var invalidRadiusSession = CreateVoxelProjectSession(
                new FakeRenderBackend(),
                20260808u,
                workerCount: 1,
                worldType: WorldType.Flat);
            var invalidRadiusMenu = invalidRadiusSession.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
            var invalidRadiusWorld = invalidRadiusSession.Scene.Tree.GetNode("/Root/World") as VoxelWorldNode;
            invalidRadiusWorld!.GenerateRadius = invalidRadius;
            var invalidRadiusStarted = invalidRadiusMenu?.CreateWorld(
                $"非法半径世界 {invalidRadius}",
                "20260808",
                WorldType.Flat) == true;
            invalidRadiusMenu = invalidRadiusSession.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
            invalidRadiusWorld = invalidRadiusSession.Scene.Tree.GetNode("/Root/World") as VoxelWorldNode;
            invalidRadiusWorld!.GenerateRadius = invalidRadius;
            var invalidRadiusException = CaptureException(() =>
            {
                invalidRadiusSession.Scene.ProcessFrame(0d);
                invalidRadiusSession.Scene.ProcessFrame(0d);
            });
            Check(
                $"GenerateRadius={invalidRadius} 进入前明确失败并回选档",
                invalidRadiusStarted && invalidRadiusException is null &&
                invalidRadiusMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.WorldSelection &&
                invalidRadiusMenu.OpeningProgress?.Stage == MyFirstCubitProject.WorldOpeningStage.Failed &&
                !string.IsNullOrWhiteSpace(invalidRadiusMenu.LastError) &&
                invalidRadiusWorld.Streamer is null,
                $"started={invalidRadiusStarted} exception={invalidRadiusException?.GetType().Name ?? "none"} " +
                $"screen={invalidRadiusMenu?.State.Screen} stage={invalidRadiusMenu?.OpeningProgress?.Stage} " +
                $"error={invalidRadiusMenu?.LastError} streamer={(invalidRadiusWorld.Streamer is null ? "null" : "active")}");
        }
        catch (Exception exception)
        {
            Check($"GenerateRadius={invalidRadius} 失败清理流程", false, exception.ToString());
        }
    }

    try
    {
        using var failedTransferSession = CreateVoxelProjectSession(
            new FakeRenderBackend(),
            20260808u,
            workerCount: 1,
            worldType: WorldType.Flat);
        var failedTransferMenu = failedTransferSession.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        var failedTransferRepository = failedTransferSession.Scene.Runtime.Context.GetRequiredService<MyFirstCubitProject.WorldRepository>();
        var failedTransferSummary = failedTransferRepository.Create("失败转移所有权", 20260810u, WorldType.Flat);
        using var transferredSession = failedTransferRepository.Open(failedTransferSummary);
        var menuType = typeof(MyFirstCubitProject.SingleplayerMenuController);
        var contextType = menuType.GetNestedType("WorldOpeningContext", BindingFlags.Instance | BindingFlags.NonPublic);
        var openingContext = RuntimeHelpers.GetUninitializedObject(contextType!);
        contextType!.GetField("<Summary>k__BackingField", BindingFlags.Instance | BindingFlags.NonPublic)
            ?.SetValue(openingContext, failedTransferSummary);
        var openingField = menuType.GetField("_opening", BindingFlags.Instance | BindingFlags.NonPublic);
        var progressField = menuType.GetField("_openingProgress", BindingFlags.Instance | BindingFlags.NonPublic);
        var currentSessionField = menuType.GetField("_openSession", BindingFlags.Instance | BindingFlags.NonPublic);
        var failOpeningMethod = menuType.GetMethod("FailOpening", BindingFlags.Instance | BindingFlags.NonPublic);
        openingField?.SetValue(failedTransferMenu, openingContext);
        progressField?.SetValue(
            failedTransferMenu,
            new MyFirstCubitProject.WorldOpeningProgress(
                failedTransferSummary,
                MyFirstCubitProject.WorldOpeningStage.RestorePlayer,
                90,
                100));
        currentSessionField?.SetValue(failedTransferMenu, transferredSession);
        var cleanupException = CaptureException(() => failOpeningMethod!.Invoke(
            failedTransferMenu,
            [openingContext, "强制呈现失败"]));
        var storageDisposed = CaptureException(() => transferredSession.Storage.TryLoadChunk(0, 0, out _)) is ObjectDisposedException;
        Check(
            "RestorePlayer 后失败路径释放已转移的当前世界会话",
            cleanupException is null && storageDisposed && currentSessionField?.GetValue(failedTransferMenu) is null,
            $"exception={cleanupException?.GetType().Name ?? "none"} storageDisposed={storageDisposed} " +
            $"currentSession={(currentSessionField?.GetValue(failedTransferMenu) is null ? "null" : "active")}");
    }
    catch (Exception exception)
    {
        Check("RestorePlayer 会话转移失败清理回归", false, exception.ToString());
    }

    var root = Path.Combine(Path.GetTempPath(), $"cubit_player_persistence_{Guid.NewGuid():N}");
    try
    {
        var projectLinkRoot = Path.Combine(Path.GetTempPath(), $"cubit_project_root_link_{Guid.NewGuid():N}");
        var projectLinkOutside = Path.Combine(Path.GetTempPath(), $"cubit_project_root_outside_{Guid.NewGuid():N}");
        try
        {
            Directory.CreateDirectory(projectLinkOutside);
            CreateDirectoryJunction(projectLinkRoot, projectLinkOutside);
            var rootError = CaptureException(() => new MyFirstCubitProject.WorldRepository(projectLinkRoot));
            Check(
                "仓库构造拒绝重解析项目根目录",
                rootError is IOException,
                rootError?.Message ?? "none");
        }
        finally
        {
            if (Directory.Exists(projectLinkRoot))
            {
                DeleteDirectoryJunction(projectLinkRoot);
            }

            if (Directory.Exists(projectLinkOutside))
            {
                Directory.Delete(projectLinkOutside, recursive: true);
            }
        }

        var parentLink = Path.Combine(Path.GetTempPath(), $"cubit_project_parent_link_{Guid.NewGuid():N}");
        var parentOutside = Path.Combine(Path.GetTempPath(), $"cubit_project_parent_outside_{Guid.NewGuid():N}");
        var missingProjectRoot = Path.Combine(parentLink, "missing-project");
        try
        {
            Directory.CreateDirectory(parentOutside);
            CreateDirectoryJunction(parentLink, parentOutside);
            var ancestorError = CaptureException(() => new MyFirstCubitProject.WorldRepository(missingProjectRoot));
            Check(
                "仓库构造拒绝位于项目外 Junction 下的缺失项目目录",
                ancestorError is IOException && !Directory.Exists(Path.Combine(parentOutside, "saves")),
                ancestorError?.Message ?? "none");
        }
        finally
        {
            if (Directory.Exists(parentLink))
            {
                DeleteDirectoryJunction(parentLink);
            }

            if (Directory.Exists(parentOutside))
            {
                Directory.Delete(parentOutside, recursive: true);
            }
        }

        WritePersistentProjectFixture(root);
        var repository = new MyFirstCubitProject.WorldRepository(root);
        var summary = repository.Create("实体持久化检查", 20260808u, WorldType.Flat);
        var worldDirectory = Path.Combine(root, "saves", summary.Id);
        var metadataPath = Path.Combine(worldDirectory, "world.cubit.json");
        var originalMetadata = File.ReadAllText(metadataPath);
        var tamperedMetadata = JsonNode.Parse(originalMetadata)?.AsObject()
            ?? throw new InvalidDataException("测试元数据解析失败");
        tamperedMetadata["Id"] = "world-metadata-mismatch";
        File.WriteAllText(metadataPath, tamperedMetadata.ToJsonString());
        var metadataMismatch = CaptureException(() => deleteWorldMethod?.Invoke(repository, [summary]));
        Check(
            "删除前重新校验元数据 ID 且保留不匹配目录",
            metadataMismatch is TargetInvocationException { InnerException: InvalidDataException } &&
            Directory.Exists(worldDirectory),
            metadataMismatch?.Message ?? "none");
        File.WriteAllText(metadataPath, originalMetadata);

        var junctionRoot = Path.Combine(Path.GetTempPath(), $"cubit_delete_junction_{Guid.NewGuid():N}");
        var junctionOutside = Path.Combine(Path.GetTempPath(), $"cubit_delete_junction_outside_{Guid.NewGuid():N}");
        var junctionDirectory = Path.Combine(junctionRoot, "saves", "world-junction-test");
        var outsideSentinel = Path.Combine(junctionOutside, "must-remain.txt");
        try
        {
            Directory.CreateDirectory(Path.Combine(junctionRoot, "saves"));
            WritePersistentProjectFixture(junctionRoot);
            Directory.CreateDirectory(junctionOutside);
            File.WriteAllText(outsideSentinel, "outside");
            CreateDirectoryJunction(junctionDirectory, junctionOutside);
            var junctionRepository = new MyFirstCubitProject.WorldRepository(junctionRoot);
            var junctionSummary = new MyFirstCubitProject.WorldSummary(
                "world-junction-test", "链接目录", 1, WorldType.Flat, DateTimeOffset.UtcNow, DateTimeOffset.UtcNow);
            var junctionError = CaptureException(() => junctionRepository.Delete(junctionSummary));
            Check(
                "删除拒绝指向项目外的世界 Junction 且保留 outside 内容",
                (junctionError is IOException || junctionError is InvalidDataException) && File.Exists(outsideSentinel),
                junctionError?.Message ?? "none");
        }
        finally
        {
            if (Directory.Exists(junctionDirectory))
            {
                DeleteDirectoryJunction(junctionDirectory);
            }

            if (Directory.Exists(junctionRoot))
            {
                Directory.Delete(junctionRoot, recursive: true);
            }

            if (Directory.Exists(junctionOutside))
            {
                Directory.Delete(junctionOutside, recursive: true);
            }
        }
        var menuState = new MyFirstCubitProject.SingleplayerMenuState();
        menuState.ShowWorldSelection();
        menuStateType?.GetMethod("ShowDeleteConfirm")?.Invoke(menuState, null);
        Check("删除确认状态可进入并取消", menuState.Screen.ToString() == "DeleteConfirm",
            menuState.Screen.ToString());
        menuStateType?.GetMethod("CancelDelete")?.Invoke(menuState, null);
        Check("取消删除返回世界选择", menuState.Screen == MyFirstCubitProject.SingleplayerMenuScreen.WorldSelection,
            menuState.Screen.ToString());
        menuStateType?.GetMethod("BeginOpeningWorld")?.Invoke(menuState, null);
        Check("开始加载进入 OpeningWorld", menuState.Screen.ToString() == "OpeningWorld",
            menuState.Screen.ToString());
        var expected = new MyFirstCubitProject.PlayerEntitySnapshot(
            new Vector3(24.5f, 5.905f, 24.5f),
            new Vector3(1.25f, -0.5f, 0.75f),
            true,
            2);
        var expectedProjectile = new MyFirstCubitProject.ProjectProjectileSnapshot(
            new Vector3(35f, 8f, 36f),
            new Vector3(2f, -0.25f, 0.5f),
            12,
            1.25f,
            30f);
        var expectedMonster = new MyFirstCubitProject.ProjectMonsterSnapshot(
            new Vector3(38f, 8f, 39f),
            new Vector3(0.5f, 0f, -0.25f),
            21,
            2f,
            600f);
        repository.SavePlayerState(summary, expected);
        repository.SaveProjectiles(summary, [expectedProjectile]);
        repository.SaveMonsters(summary, [expectedMonster]);
        var statePath = Path.Combine(root, "saves", summary.Id, "entities.cubit.bin");
        var projectilePath = Path.Combine(root, "saves", summary.Id, "projectiles.cubit.bin");
        var monsterPath = Path.Combine(root, "saves", summary.Id, "monsters.cubit.bin");
        Check(
            "玩家实体快照使用独立二进制文件并清理临时文件",
            File.Exists(statePath) && !File.Exists(statePath + ".new"),
            statePath);
        Check(
            "Projectile 实体快照使用独立二进制文件并清理临时文件",
            File.Exists(projectilePath) && !File.Exists(projectilePath + ".new"),
            projectilePath);
        Check(
            "Monster 实体快照使用独立二进制文件并清理临时文件",
            File.Exists(monsterPath) && !File.Exists(monsterPath + ".new"),
            monsterPath);
        using (var opened = repository.Open(summary))
        {
            Check(
                "世界会话恢复玩家实体快照",
                opened.PlayerState is { } actual && actual == expected,
                opened.PlayerState?.ToString() ?? "missing");
            Check(
                "世界会话恢复 Projectile 实体快照",
                opened.Projectiles.Count == 1 && opened.Projectiles[0] == expectedProjectile,
                opened.Projectiles.Count == 0 ? "missing" : opened.Projectiles[0].ToString());
            Check(
                "世界会话恢复 Monster 实体快照",
                opened.Monsters.Count == 1 && opened.Monsters[0] == expectedMonster,
                opened.Monsters.Count == 0 ? "missing" : opened.Monsters[0].ToString());
        }

        var originalPlayerBytes = File.ReadAllBytes(statePath);
        var corruptedBytes = originalPlayerBytes.ToArray();
        corruptedBytes[^1] ^= 0x5A;
        File.WriteAllBytes(statePath, corruptedBytes);
        var corruption = CaptureException(() => repository.Open(summary));
        Check(
            "损坏玩家实体快照被拒绝且不会泄漏存储句柄",
            corruption is InvalidDataException,
            corruption?.Message ?? "none");
        File.WriteAllBytes(statePath, originalPlayerBytes);
        var projectileCorruptedBytes = File.ReadAllBytes(projectilePath);
        projectileCorruptedBytes[^1] ^= 0x27;
        File.WriteAllBytes(projectilePath, projectileCorruptedBytes);
        var projectileCorruption = CaptureException(() => repository.Open(summary));
        Check(
            "损坏 Projectile 实体快照被拒绝且不会泄漏存储句柄",
            projectileCorruption is InvalidDataException &&
            projectileCorruption.Message.Contains("Projectile", StringComparison.OrdinalIgnoreCase),
            projectileCorruption?.Message ?? "none");
        File.WriteAllBytes(projectilePath, MyFirstCubitProject.ProjectProjectileSnapshot.EncodeMany([expectedProjectile]));
        var monsterCorruptedBytes = File.ReadAllBytes(monsterPath);
        monsterCorruptedBytes[^1] ^= 0x1C;
        File.WriteAllBytes(monsterPath, monsterCorruptedBytes);
        var monsterCorruption = CaptureException(() => repository.Open(summary));
        Check(
            "损坏 Monster 实体快照被拒绝且不会泄漏存储句柄",
            monsterCorruption is InvalidDataException &&
            monsterCorruption.Message.Contains("Monster", StringComparison.OrdinalIgnoreCase),
            monsterCorruption?.Message ?? "none");

        deleteWorldMethod?.Invoke(repository, [summary]);
        Check("删除世界永久移除存档目录", !Directory.Exists(Path.Combine(root, "saves", summary.Id)), summary.Id);

        var escaped = new MyFirstCubitProject.WorldSummary("world-../outside", "越界", 1, WorldType.Flat,
            DateTimeOffset.UtcNow, DateTimeOffset.UtcNow);
        var escapeError = CaptureException(() => deleteWorldMethod?.Invoke(repository, [escaped]));
        Check("删除拒绝路径逃逸 ID", escapeError is ArgumentException ||
            escapeError is TargetInvocationException { InnerException: ArgumentException }, escapeError?.Message ?? "none");
    }
    catch (Exception exception)
    {
        Check("玩家实体快照 fixture 执行", false, exception.ToString());
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, recursive: true);
        }

    }

    try
    {
        using var session = CreateVoxelProjectSession(new FakeRenderBackend(), 20260808u, workerCount: 1, worldType: WorldType.Flat);
        var menu = session.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        var bridge = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs") as MyFirstCubitProject.PlayerEcsBridgeNode;
        var created = menu?.CreateWorld("玩家恢复检查", "20260808", WorldType.Flat) == true;
        Check("真实项目流程可创建用于实体持久化的世界", created, menu?.LastError ?? "none");
        var openingDeadline = Stopwatch.StartNew();
        while (created && menu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.OpeningWorld &&
               openingDeadline.Elapsed < TimeSpan.FromSeconds(10))
        {
            session.Scene.ProcessFrame(1d / 60d);
            Thread.Sleep(1);
        }
        var savedState = new MyFirstCubitProject.PlayerEntitySnapshot(
            new Vector3(31.25f, 8.5f, 29.75f),
            new Vector3(0.5f, -1.25f, 0.25f),
            false,
            1);
        bridge?.SetMotionState(savedState.ToMotion());
        var playerForQueue = session.Scene.Tree.GetNode("/Root/Physics/Player") as MyFirstCubitProject.PlayerController;
        playerForQueue?.RestoreMotionState(savedState.ToMotion());
        bridge?.SpawnItemDrop(new Vector3(42f, 8f, 42f), itemId: 7, count: 3, lifetimeSeconds: 120f);
        bridge?.SpawnProjectile(new Vector3(44f, 8f, 44f), Vector3.Zero, projectileId: 12, lifetimeSeconds: 120f);
        bridge?.SpawnMonster(new Vector3(46f, 8f, 46f), Vector3.Zero, monsterId: 21, lifetimeSeconds: 600f);
        menu?.State.TogglePause();
        var returnToTitleTimer = Stopwatch.StartNew();
        menu?.QueueReturnToTitle();
        session.Scene.ProcessFrame(1d / 60d);
        returnToTitleTimer.Stop();
        Check(
            "暂停菜单队列保存并返回标题在有限时间内完成",
            menu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.Title &&
            session.Scene.Runtime.Scenes.CurrentSceneId == "title" &&
            returnToTitleTimer.Elapsed < TimeSpan.FromSeconds(5),
            $"screen={menu?.State.Screen} scene={session.Scene.Runtime.Scenes.CurrentSceneId} elapsed={returnToTitleTimer.Elapsed.TotalMilliseconds:F1}ms");
        session.Scene.ProcessFrame(0d);
        var reopenedMenu = session.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        var summary = reopenedMenu?.Worlds.FirstOrDefault(item => item.DisplayName == "玩家恢复检查");
        reopenedMenu?.SelectWorld(summary);
        var reopened = reopenedMenu?.OpenSelectedWorld() == true;
        var reopenDeadline = Stopwatch.StartNew();
        while (reopened && reopenedMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.OpeningWorld &&
               reopenDeadline.Elapsed < TimeSpan.FromSeconds(10))
        {
            session.Scene.ProcessFrame(1d / 60d);
            Thread.Sleep(1);
        }
        var reopenedBridge = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs") as MyFirstCubitProject.PlayerEcsBridgeNode;
        var reopenedWorldNode = session.Scene.Tree.GetNode("/Root/World") as VoxelWorldNode;
        var storageOwnershipField = typeof(VoxelWorldNode).GetField("_storageOwnedByCaller", BindingFlags.Instance | BindingFlags.NonPublic);
        Check("真实项目流程重新打开世界", reopened, $"opened={reopened} error={reopenedMenu?.LastError ?? "none"}");
        Check(
            "世界会话存储句柄由 WorldOpenSession 明确拥有",
            reopenedWorldNode is not null && storageOwnershipField?.GetValue(reopenedWorldNode) is true,
            $"node={reopenedWorldNode is not null} callerOwned={storageOwnershipField?.GetValue(reopenedWorldNode)}");
        var restoredMotion = reopenedBridge?.ReadMotionState() ?? default;
        Check(
            "真实项目流程恢复玩家 ECS 位置/速度",
            reopenedBridge is not null &&
            Vector3.Distance(restoredMotion.Position, savedState.Position) < 0.25f &&
            MathF.Abs(restoredMotion.Velocity.X - savedState.Velocity.X) < 0.01f &&
            MathF.Abs(restoredMotion.Velocity.Z - savedState.Velocity.Z) < 0.01f,
            $"saved={savedState.Position}/{savedState.Velocity} restored={restoredMotion.Position}/{restoredMotion.Velocity}");
        session.Scene.ProcessFrame(session.Scene.Tree.PhysicsDelta);
        var motionAfterFirstRestoredTick = reopenedBridge?.ReadMotionState() ?? default;
        Check(
            "存档恢复后的首个固定 tick 不提前消耗玩家运动快照",
            reopenedBridge is not null &&
            Vector3.Distance(motionAfterFirstRestoredTick.Position, savedState.Position) < 0.0001f &&
            Vector3.Distance(motionAfterFirstRestoredTick.Velocity, savedState.Velocity) < 0.0001f,
            $"saved={savedState.Position}/{savedState.Velocity} after={motionAfterFirstRestoredTick.Position}/{motionAfterFirstRestoredTick.Velocity}");
        var restoredDrops = reopenedBridge?.CaptureItemDrops() ?? [];
        Check(
            "真实项目流程恢复 ItemDrop ECS 状态",
            restoredDrops.Count == 1 && restoredDrops[0].ItemId == 7 && restoredDrops[0].Count == 3 &&
            restoredDrops[0].Position == new Vector3(42f, 8f, 42f),
            $"drops={restoredDrops.Count} state={(restoredDrops.Count == 0 ? "missing" : restoredDrops[0].ToString())}");
        var restoredProjectiles = reopenedBridge?.CaptureProjectiles() ?? [];
        Check(
            "真实项目流程恢复 Projectile ECS 状态",
            restoredProjectiles.Count == 1 && restoredProjectiles[0].ProjectileId == 12 &&
            restoredProjectiles[0].Position == new Vector3(44f, 8f, 44f),
            $"projectiles={restoredProjectiles.Count} state={(restoredProjectiles.Count == 0 ? "missing" : restoredProjectiles[0].ToString())}");
        var restoredMonsters = reopenedBridge?.CaptureMonsters() ?? [];
        Check(
            "真实项目流程恢复 Monster ECS 状态",
            restoredMonsters.Count == 1 && restoredMonsters[0].MonsterId == 21 &&
            restoredMonsters[0].Position == new Vector3(46f, 8f, 46f),
            $"monsters={restoredMonsters.Count} state={(restoredMonsters.Count == 0 ? "missing" : restoredMonsters[0].ToString())}");
        var gameplayMenuAfterReopen = session.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        gameplayMenuAfterReopen?.ReturnToTitle();
        session.Scene.ProcessFrame(0d);
        Check(
            "世界会话结束后借用存储标记清理",
            storageOwnershipField?.GetValue(reopenedWorldNode) is false,
            $"callerOwnedAfterExit={storageOwnershipField?.GetValue(reopenedWorldNode)}");
    }
    catch (Exception exception)
    {
        Check("真实项目玩家实体持久化流程", false, exception.ToString());
    }

    try
    {
        using var corruptedMetadataSession = CreateVoxelProjectSession(
            new FakeRenderBackend(),
            20260808u,
            workerCount: 1,
            worldType: WorldType.Flat);
        var corruptedMenu = corruptedMetadataSession.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        var corruptedWorldNode = corruptedMetadataSession.Scene.Tree.GetNode("/Root/World") as VoxelWorldNode;
        var created = corruptedMenu?.CreateWorld("损坏元数据加载", "20260808", WorldType.Flat) == true;
        var openingDeadline = Stopwatch.StartNew();
        while (created && corruptedMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.OpeningWorld &&
               openingDeadline.Elapsed < TimeSpan.FromSeconds(10))
        {
            corruptedMetadataSession.Scene.ProcessFrame(1d / 60d);
            Thread.Sleep(1);
        }

        corruptedMenu?.ReturnToTitle();
        corruptedMetadataSession.Scene.ProcessFrame(0d);
        corruptedMenu = corruptedMetadataSession.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        corruptedWorldNode = corruptedMetadataSession.Scene.Tree.GetNode("/Root/World") as VoxelWorldNode;
        var corruptedSummary = corruptedMenu?.Worlds.FirstOrDefault(item => item.DisplayName == "损坏元数据加载");
        var metadataPath = corruptedSummary is null
            ? null
            : Path.Combine(
                corruptedMetadataSession.Scene.Runtime.Project.RootDirectory,
                "saves",
                corruptedSummary.Id,
                "world.cubit.json");
        if (metadataPath is not null)
        {
            File.WriteAllText(metadataPath, "{ invalid world metadata");
        }

        corruptedMenu?.SelectWorld(corruptedSummary);
        var openingStarted = corruptedMenu?.OpenSelectedWorld() == true;
        corruptedMenu = corruptedMetadataSession.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        corruptedWorldNode = corruptedMetadataSession.Scene.Tree.GetNode("/Root/World") as VoxelWorldNode;
        var openingException = CaptureException(() => corruptedMetadataSession.Scene.ProcessFrame(0d));
        var temporarySessionReleased = corruptedMenu is not null &&
            corruptedMenu.GetType().GetField("_openSession", BindingFlags.Instance | BindingFlags.NonPublic)?.GetValue(corruptedMenu) is null;
        var failedState = corruptedMenu is { } menuAfterFailure &&
            menuAfterFailure.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.WorldSelection &&
            menuAfterFailure.OpeningProgress?.Stage == MyFirstCubitProject.WorldOpeningStage.Failed &&
            !string.IsNullOrWhiteSpace(menuAfterFailure.LastError) &&
            corruptedWorldNode?.Streamer is null;
        Check(
            "损坏世界元数据进入失败会话清理并回到选档",
            created && openingStarted && openingException is null && failedState && temporarySessionReleased,
            $"created={created} started={openingStarted} exception={openingException?.GetType().Name ?? "none"} " +
            $"screen={corruptedMenu?.State.Screen} stage={corruptedMenu?.OpeningProgress?.Stage} " +
            $"error={corruptedMenu?.LastError} streamer={(corruptedWorldNode?.Streamer is null ? "null" : "active")} " +
            $"sessionReleased={temporarySessionReleased}");
    }
    catch (Exception exception)
    {
        Check("损坏世界元数据进入失败清理流程", false, exception.ToString());
    }

    try
    {
        using var session = CreateVoxelProjectSession(new FakeRenderBackend(), 20260808u, workerCount: 1, worldType: WorldType.Flat);
        var menu = session.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        var player = session.Scene.Tree.GetNode("/Root/Physics/Player") as MyFirstCubitProject.PlayerController;
        var bridge = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs") as MyFirstCubitProject.PlayerEcsBridgeNode;
        var created = menu?.CreateWorld("真实移动坐标检查", "20260808", WorldType.Flat) == true;
        menu = session.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        for (var frame = 0; created && frame < 180; frame++)
        {
            session.Scene.ProcessFrame(1d / 60d);
            Thread.Sleep(1);
        }
        var openingDeadline = Stopwatch.StartNew();
        while (created && menu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.OpeningWorld &&
               openingDeadline.Elapsed < TimeSpan.FromSeconds(10))
        {
            session.Scene.ProcessFrame(1d / 60d);
            Thread.Sleep(1);
        }

        var beforeMove = bridge?.ReadMotionState() ?? default;
        session.Input.SetAction(InputAction.Forward, true);
        for (var frame = 0; created && frame < 30; frame++)
        {
            session.Scene.ProcessFrame(1d / 60d);
            Thread.Sleep(1);
        }

        session.Input.SetAction(InputAction.Forward, false);
        var afterMove = bridge?.ReadMotionState() ?? default;
        var moved = Vector3.Distance(beforeMove.Position, afterMove.Position) > 0.1f;
        for (var frame = 0; created && frame < 360; frame++)
        {
            session.Scene.ProcessFrame(1d / 60d);
            Thread.Sleep(1);
        }

        var activeSummary = menu?.Worlds.FirstOrDefault(item => item.DisplayName == "真实移动坐标检查");
        MyFirstCubitProject.PlayerEntitySnapshot? autosavedState = null;
        if (activeSummary is not null)
        {
            var probeRepository = new MyFirstCubitProject.WorldRepository(session.Scene.Runtime.Project.RootDirectory);
            using var probeSession = probeRepository.Open(activeSummary);
            autosavedState = probeSession.PlayerState;
        }
        Check(
            "运行中低频自动保存玩家坐标",
            autosavedState is { } autosaved && autosaved.Position == afterMove.Position,
            $"after={afterMove.Position} autosaved={autosavedState?.Position.ToString() ?? "missing"}");

        menu?.ReturnToTitle();
        session.Scene.ProcessFrame(0d);
        menu = session.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
        var summary = menu?.Worlds.FirstOrDefault(item => item.DisplayName == "真实移动坐标检查");
        menu?.SelectWorld(summary);
        var reopened = menu?.OpenSelectedWorld() == true;
        var reopenDeadline = Stopwatch.StartNew();
        while (reopened && menu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.OpeningWorld &&
               reopenDeadline.Elapsed < TimeSpan.FromSeconds(10))
        {
            session.Scene.ProcessFrame(1d / 60d);
            Thread.Sleep(1);
        }
        bridge = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs") as MyFirstCubitProject.PlayerEcsBridgeNode;
        var restored = bridge?.ReadMotionState() ?? default;
        Check(
            "真实移动后保存并恢复玩家坐标",
            created && moved && reopened && restored.Position == afterMove.Position,
            $"created={created} moved={moved} reopened={reopened} before={beforeMove.Position} after={afterMove.Position} restored={restored.Position}");
    }
    catch (Exception exception)
    {
        Check("真实移动玩家坐标持久化流程", false, exception.ToString());
    }

    Console.WriteLine(failures == 0
        ? "projectplayerpersistencecheck 全部通过"
        : $"projectplayerpersistencecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

}

static int ProjectEntityInterestCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var assembly = typeof(MyFirstCubitProject.WorldRepository).Assembly;
    var systemType = assembly.GetType("MyFirstCubitProject.ProjectEntityInterestSystem");
    var tierType = assembly.GetType("MyFirstCubitProject.ProjectEntityInterestTier");
    Check("项目提供独立空间兴趣 System", systemType is not null, systemType?.FullName ?? "missing");
    Check("项目提供 Hidden/Tracked/Ticking 兴趣层级", tierType is not null, tierType?.FullName ?? "missing");

    try
    {
        using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var tree = new SceneTree();
        var node = new EcsNode { Name = "InterestEcs", Jobs = jobs };
        var focus = node.World.CreateEntity();
        node.World.AddComponent(focus, new MyFirstCubitProject.PlayerMotionState
        {
            Position = Vector3.Zero,
        });
        var ticking = node.World.CreateEntity();
        node.World.AddComponent(ticking, new MyFirstCubitProject.ProjectEntitySpatialState
        {
            Position = new Vector3(16f, 0f, 0f),
        });
        node.World.AddComponent(ticking, new MyFirstCubitProject.ProjectEntityInterestState());
        var tracked = node.World.CreateEntity();
        node.World.AddComponent(tracked, new MyFirstCubitProject.ProjectEntitySpatialState
        {
            Position = new Vector3(32f, 0f, 0f),
        });
        node.World.AddComponent(tracked, new MyFirstCubitProject.ProjectEntityInterestState());
        var hidden = node.World.CreateEntity();
        node.World.AddComponent(hidden, new MyFirstCubitProject.ProjectEntitySpatialState
        {
            Position = new Vector3(160f, 0f, 0f),
        });
        node.World.AddComponent(hidden, new MyFirstCubitProject.ProjectEntityInterestState());
        var interest = new MyFirstCubitProject.ProjectEntityInterestSystem(focus, new Vector3(16f, 16f, 16f), 2, 1);
        node.AddSystem(interest);
        tree.Root.AddChild(node);
        tree.ProcessFrame(tree.PhysicsDelta);
        var tickingState = node.World.GetComponent<MyFirstCubitProject.ProjectEntityInterestState>(ticking);
        var trackedState = node.World.GetComponent<MyFirstCubitProject.ProjectEntityInterestState>(tracked);
        var hiddenState = node.World.GetComponent<MyFirstCubitProject.ProjectEntityInterestState>(hidden);
        Check("空间兴趣更新目标分区数量", interest.DesiredPartitionCount == 25, $"desired={interest.DesiredPartitionCount}");
        Check("空间兴趣层级区分 Ticking/Tracked/Hidden",
            tickingState.Tier == MyFirstCubitProject.ProjectEntityInterestTier.Ticking &&
            trackedState.Tier == MyFirstCubitProject.ProjectEntityInterestTier.Tracked &&
            hiddenState.Tier == MyFirstCubitProject.ProjectEntityInterestTier.Hidden,
            $"ticking={tickingState.Tier} tracked={trackedState.Tier} hidden={hiddenState.Tier}");
        Check("空间兴趣刷新输出稳定 Enter 变化", interest.LastPartitionChanges.Count == 25,
            $"changes={interest.LastPartitionChanges.Count}");
    }
    catch (Exception exception)
    {
        Check("项目空间兴趣 fixture 执行", false, exception.ToString());
    }

    Console.WriteLine(failures == 0
        ? "projectentityinterestcheck 全部通过"
        : $"projectentityinterestcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectItemDropCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var assembly = typeof(MyFirstCubitProject.WorldRepository).Assembly;
    var stateType = assembly.GetType("MyFirstCubitProject.ProjectItemDropState");
    var systemType = assembly.GetType("MyFirstCubitProject.ProjectItemDropSystem");
    var factoryType = assembly.GetType("MyFirstCubitProject.ProjectItemDropFactory");
    var inventoryType = assembly.GetType("MyFirstCubitProject.ProjectInventoryState");
    var snapshotType = assembly.GetType("MyFirstCubitProject.ProjectItemDropSnapshot");
    var presentationType = assembly.GetType("MyFirstCubitProject.ProjectItemDropPresentationSystem");
    Check("项目提供 ItemDrop ECS 状态", stateType is not null, stateType?.FullName ?? "missing");
    Check("项目提供 ItemDrop 生命周期 System", systemType is not null, systemType?.FullName ?? "missing");
    Check("项目提供 ItemDrop 生成工厂", factoryType is not null, factoryType?.FullName ?? "missing");
    Check("项目提供项目库存组件", inventoryType is not null, inventoryType?.FullName ?? "missing");
    Check("项目提供 ItemDrop 独立快照类型", snapshotType is not null, snapshotType?.FullName ?? "missing");
    Check("项目提供 ItemDrop 批量表现快照 System", presentationType is not null, presentationType?.FullName ?? "missing");

    try
    {
        using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var tree = new SceneTree();
        var node = new EcsNode { Name = "DropEcs", Jobs = jobs };
        var focus = node.World.CreateEntity();
        node.World.AddComponent(focus, new MyFirstCubitProject.PlayerMotionState { Position = Vector3.Zero });

        var near = node.World.CreateEntity();
        node.World.AddComponent(near, new MyFirstCubitProject.ProjectEntitySpatialState { Position = new Vector3(16f, 0f, 0f) });
        node.World.AddComponent(near, new MyFirstCubitProject.ProjectEntityInterestState());
        node.World.AddComponent(near, new MyFirstCubitProject.ProjectItemDropState
        {
            ItemId = 5,
            Count = 1,
            LifetimeSeconds = 0.1f,
        });

        var tracked = node.World.CreateEntity();
        node.World.AddComponent(tracked, new MyFirstCubitProject.ProjectEntitySpatialState { Position = new Vector3(32f, 0f, 0f) });
        node.World.AddComponent(tracked, new MyFirstCubitProject.ProjectEntityInterestState());
        node.World.AddComponent(tracked, new MyFirstCubitProject.ProjectItemDropState
        {
            ItemId = 5,
            Count = 1,
            LifetimeSeconds = 0.1f,
        });

        var hidden = node.World.CreateEntity();
        node.World.AddComponent(hidden, new MyFirstCubitProject.ProjectEntitySpatialState { Position = new Vector3(160f, 0f, 0f) });
        node.World.AddComponent(hidden, new MyFirstCubitProject.ProjectEntityInterestState());
        node.World.AddComponent(hidden, new MyFirstCubitProject.ProjectItemDropState
        {
            ItemId = 5,
            Count = 1,
            LifetimeSeconds = 0.1f,
        });

        node.AddSystem(new MyFirstCubitProject.ProjectEntityInterestSystem(focus, new Vector3(16f, 16f, 16f), 2, 1));
        node.World.AddComponent(focus, MyFirstCubitProject.ProjectInventoryState.CreateEmpty());
        var factoryDrop = MyFirstCubitProject.ProjectItemDropFactory.Spawn(
            node.World,
            new Vector3(0.5f, 0f, 0f),
            itemId: 7,
            count: 3,
            lifetimeSeconds: 10f);
        node.AddSystem(new MyFirstCubitProject.ProjectItemDropSystem(focus));
        var presentation = new MyFirstCubitProject.ProjectItemDropPresentationSystem();
        node.AddSystem(presentation);
        tree.Root.AddChild(node);
        tree.ProcessFrame(0.05d);
        var nearAfterFirst = node.World.GetComponent<MyFirstCubitProject.ProjectItemDropState>(near);
        var trackedAfterFirst = node.World.GetComponent<MyFirstCubitProject.ProjectItemDropState>(tracked);
        var hiddenAfterFirst = node.World.GetComponent<MyFirstCubitProject.ProjectItemDropState>(hidden);
        Check("ItemDrop 仅在 Ticking 层级推进年龄",
            nearAfterFirst.AgeSeconds > 0f && trackedAfterFirst.AgeSeconds == 0f && hiddenAfterFirst.AgeSeconds == 0f,
            $"near={nearAfterFirst.AgeSeconds:F3} tracked={trackedAfterFirst.AgeSeconds:F3} hidden={hiddenAfterFirst.AgeSeconds:F3}");
        Check("ItemDrop RenderPrepare 批量快照过滤 Hidden",
            presentation.VisibleDrops.Any(drop => drop.Entity == near || drop.Entity == tracked) &&
            presentation.VisibleDrops.All(drop => drop.Entity != hidden),
            $"visible={presentation.VisibleDrops.Count}");
        var firstFrameDrops = presentation.VisibleDrops;
        var firstFrameEntities = firstFrameDrops.Select(drop => drop.Entity).ToArray();
        Check("ItemDrop 表现快照首帧顺序稳定",
            firstFrameEntities.SequenceEqual(firstFrameDrops
                .OrderBy(drop => drop.Tier)
                .ThenBy(drop => drop.Entity.Index)
                .Select(drop => drop.Entity)),
            string.Join(",", firstFrameEntities.Select(entity => entity.Index)));
        var mutableSnapshot = firstFrameDrops as IList<MyFirstCubitProject.ProjectItemDropPresentationSnapshot>;
        var firstFrameValues = firstFrameDrops.ToArray();
        var mutationError = mutableSnapshot is null
            ? new InvalidOperationException("快照不是 IList 视图")
            : CaptureException(() => mutableSnapshot[0] = default);
        if (mutationError is null && mutableSnapshot is not null)
        {
            mutableSnapshot[0] = firstFrameValues[0];
        }
        Check("ItemDrop 表现快照对外不可变", mutationError is NotSupportedException,
            mutationError?.GetType().Name ?? "mutation accepted");
        tree.ProcessFrame(0.1d);
        Check("ItemDrop 表现快照不被下一帧改写",
            firstFrameDrops.Count == firstFrameEntities.Length &&
            firstFrameDrops.Select(drop => drop.Entity).SequenceEqual(firstFrameEntities) &&
            !ReferenceEquals(firstFrameDrops, presentation.VisibleDrops),
            $"old={firstFrameDrops.Count} new={presentation.VisibleDrops.Count}");
        Check("ItemDrop 寿命到期通过 CommandBuffer 销毁",
            !node.World.IsAlive(near) && node.World.IsAlive(tracked) && node.World.IsAlive(hidden),
            $"near={node.World.IsAlive(near)} tracked={node.World.IsAlive(tracked)} hidden={node.World.IsAlive(hidden)}");
        Check("ItemDropFactory 创建的近处掉落物可被拾取",
            !node.World.IsAlive(factoryDrop) &&
            node.World.GetComponent<MyFirstCubitProject.ProjectInventoryState>(focus).GetCount(7) == 3,
            $"alive={node.World.IsAlive(factoryDrop)} count={node.World.GetComponent<MyFirstCubitProject.ProjectInventoryState>(focus).GetCount(7)}");

        var snapshot = new MyFirstCubitProject.ProjectItemDropSnapshot(
            new Vector3(4f, 5f, 6f), 9, 2, 1.25f, 30f);
        var encoded = MyFirstCubitProject.ProjectItemDropSnapshot.EncodeMany([snapshot]);
        var decoded = MyFirstCubitProject.ProjectItemDropSnapshot.DecodeMany(encoded);
        Check("ItemDrop 快照二进制往返", decoded.Count == 1 && decoded[0] == snapshot,
            decoded.Count == 0 ? "missing" : decoded[0].ToString());
        encoded[^1] ^= 0x4A;
        var corrupt = CaptureException(() => MyFirstCubitProject.ProjectItemDropSnapshot.DecodeMany(encoded));
        Check("ItemDrop 快照损坏校验拒绝", corrupt is InvalidDataException, corrupt?.Message ?? "none");
    }
    catch (Exception exception)
    {
        Check("项目 ItemDrop fixture 执行", false, exception.ToString());
    }

    Console.WriteLine(failures == 0
        ? "projectitemdropcheck 全部通过"
        : $"projectitemdropcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectInventoryCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    try
    {
        var projectRoot = Path.GetFullPath(Path.Combine(Directory.GetCurrentDirectory(), "..", "我的第一个cubit项目"));
        var projectBlockIds = MyFirstCubitProject.ProjectBlockIdMap.Load(projectRoot);
        BlockRegistry.LoadContentPack(
            Path.Combine(projectRoot, "assets", "voxel"),
            projectBlockIds.Assignments);
        var inventory = MyFirstCubitProject.ProjectInventoryState.CreateEmpty();
        Check("库存固定为 9 格快捷栏 + 27 格背包", MyFirstCubitProject.ProjectInventoryState.SlotCount == 36 && MyFirstCubitProject.ProjectInventoryState.HotbarSlotCount == 9);
        Check("新库存所有槽位为空", inventory.Slots!.All(slot => slot.IsEmpty));

        var projectAssembly = typeof(MyFirstCubitProject.ProjectInventoryState).Assembly;
        var hotbarCatalogType = projectAssembly.GetType("MyFirstCubitProject.ProjectHotbarCatalog");
        var defaultInventoryFactory = hotbarCatalogType?.GetMethod(
            "CreateDefaultInventory",
            System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static,
            binder: null,
            types: Type.EmptyTypes,
            modifiers: null);
        var defaultInventory = defaultInventoryFactory?.Invoke(null, null) as MyFirstCubitProject.ProjectInventoryState?;
        Check(
            "新世界默认快捷栏包含数字键可选方块",
            defaultInventory is { } defaults &&
            defaults.GetSlot(0) == new MyFirstCubitProject.ProjectInventorySlot(BlockRegistry.Grass, MyFirstCubitProject.ProjectInventoryState.MaxStackSize) &&
            defaults.GetSlot(1) == new MyFirstCubitProject.ProjectInventorySlot(BlockRegistry.Dirt, MyFirstCubitProject.ProjectInventoryState.MaxStackSize) &&
            defaults.GetSlot(2) == new MyFirstCubitProject.ProjectInventorySlot(BlockRegistry.Stone, MyFirstCubitProject.ProjectInventoryState.MaxStackSize) &&
            defaults.GetSlot(3) == new MyFirstCubitProject.ProjectInventorySlot(BlockRegistry.Sand, MyFirstCubitProject.ProjectInventoryState.MaxStackSize) &&
            defaults.GetSlot(4) == new MyFirstCubitProject.ProjectInventorySlot(
                BlockRegistry.GetId("my_first:oak_log"), MyFirstCubitProject.ProjectInventoryState.MaxStackSize) &&
            defaults.GetSlot(5) == new MyFirstCubitProject.ProjectInventorySlot(
                BlockRegistry.GetId("my_first:oak_leaves"), MyFirstCubitProject.ProjectInventoryState.MaxStackSize) &&
            defaults.GetSlot(6).ItemId == 21 &&
            defaults.GetSlot(6).Count == 1,
            defaultInventoryFactory is null
                ? "missing ProjectHotbarCatalog.CreateDefaultInventory"
                : defaultInventory is { } defaultState
                    ? $"slots={string.Join(',', Enumerable.Range(0, MyFirstCubitProject.ProjectHotbarCatalog.DefaultSlotCount).Select(slot => defaultState.GetSlot(slot).ItemId))}"
                    : "unexpected loadout");
        Check(
            "快捷栏橡木槽位使用原版橡木方块纹理定义",
            defaultInventory is { } oakDefaults &&
            BlockRegistry.Get(oakDefaults.GetSlot(4).ItemId).SideTexture == "oak_log" &&
            BlockRegistry.Get(oakDefaults.GetSlot(4).ItemId).TopTexture == "oak_log_top" &&
            BlockRegistry.Get(oakDefaults.GetSlot(5).ItemId).SideTexture == "oak_leaves",
            defaultInventory is { } oakState
                ? $"log={BlockRegistry.Get(oakState.GetSlot(4).ItemId).SideTexture} leaves={BlockRegistry.Get(oakState.GetSlot(5).ItemId).SideTexture}"
                : "missing");
        var graniteId = BlockRegistry.GetId("my_first:granite");
        Check(
            "项目花岗岩使用原版花岗岩纹理",
            BlockRegistry.Get(graniteId).TopTexture == "granite" &&
            BlockRegistry.Get(graniteId).SideTexture == "granite" &&
            BlockRegistry.Get(graniteId).BottomTexture == "granite",
            $"top={BlockRegistry.Get(graniteId).TopTexture} side={BlockRegistry.Get(graniteId).SideTexture}");

        var itemCatalogType = typeof(MyFirstCubitProject.ProjectItemCatalog);
        var configureItemsMethod = itemCatalogType.GetMethod("ConfigureProjectDirectory", [typeof(string)]);
        var setStackMethod = itemCatalogType.GetMethod("TrySetMaxStackSize", [typeof(ushort), typeof(int)]);
        var itemRulesPath = Path.Combine(projectRoot, "assets", "gameplay", "items.json");
        Check(
            "项目物品定义资产存在且可加载",
            File.Exists(itemRulesPath) && configureItemsMethod is not null,
            $"asset={File.Exists(itemRulesPath)} configure={configureItemsMethod is not null}");
        if (configureItemsMethod is not null)
        {
            try
            {
                configureItemsMethod.Invoke(null, [projectRoot]);
            }
            catch (Exception exception)
            {
                Check("项目物品定义资产加载成功", false, exception.InnerException?.Message ?? exception.Message);
            }
        }

        Check(
            "项目物品目录区分可堆叠与不可堆叠物品",
            MyFirstCubitProject.ProjectItemCatalog.GetMaxStackSize(graniteId) == 64 &&
            MyFirstCubitProject.ProjectItemCatalog.GetMaxStackSize(BlockRegistry.GetId("my_first:water")) == 1,
            $"granite={MyFirstCubitProject.ProjectItemCatalog.GetMaxStackSize(graniteId)} water={MyFirstCubitProject.ProjectItemCatalog.GetMaxStackSize(BlockRegistry.GetId("my_first:water"))}");
        Check(
            "项目物品目录提供游戏内堆叠上限编辑入口",
            setStackMethod is not null,
            "TrySetMaxStackSize(ushort,int)");
        var itemVisualsPath = Path.Combine(projectRoot, "assets", "gameplay", "item-visuals.json");
        var itemVisualCatalogType = projectAssembly.GetType("MyFirstCubitProject.ProjectItemVisualCatalog");
        Check(
            "项目物品视觉目录存在并覆盖全部已注册物品",
            File.Exists(itemVisualsPath),
            itemVisualsPath);
        if (File.Exists(itemVisualsPath))
        {
            try
            {
                var visualDocument = System.Text.Json.JsonDocument.Parse(File.ReadAllText(itemVisualsPath));
                var visualKeys = visualDocument.RootElement
                    .GetProperty("items")
                    .EnumerateArray()
                    .Select(item => item.GetProperty("key").GetString())
                    .Where(key => !string.IsNullOrWhiteSpace(key))
                    .ToHashSet(StringComparer.Ordinal);
                var registeredKeys = BlockRegistry.Definitions
                    .Where(definition => definition.Id != BlockRegistry.Air)
                    .Select(definition => definition.Key)
                    .ToArray();
                Check(
                    "每个物品拥有独立原版视觉定义",
                    registeredKeys.All(visualKeys.Contains) && visualKeys.Count == registeredKeys.Length,
                    $"registered={registeredKeys.Length} visuals={visualKeys.Count}");
                var visualEntries = visualDocument.RootElement
                    .GetProperty("items")
                    .EnumerateArray()
                    .ToDictionary(item => item.GetProperty("key").GetString()!, StringComparer.Ordinal);
                Check(
                    "内置木/叶/基岩不再复用错误方块纹理",
                    visualEntries["cubit.voxel:wood"].GetProperty("side").GetString()?.EndsWith("oak_log.png", StringComparison.Ordinal) == true &&
                    visualEntries["cubit.voxel:leaves"].GetProperty("side").GetString()?.EndsWith("oak_leaves.png", StringComparison.Ordinal) == true &&
                    visualEntries["cubit.voxel:bedrock"].GetProperty("side").GetString()?.EndsWith("bedrock.png", StringComparison.Ordinal) == true &&
                    visualEntries["cubit.voxel:grass"].GetProperty("overlay").GetString()?.EndsWith("grass_block_side_overlay.png", StringComparison.Ordinal) == true,
                    "wood=oak_log leaves=oak_leaves bedrock=bedrock grass=side_overlay");

                if (itemVisualCatalogType?.GetMethod("ConfigureProjectDirectory", [typeof(string)]) is { } configureVisuals)
                {
                    try
                    {
                        configureVisuals.Invoke(null, [projectRoot]);
                        var visualDefinitions = itemVisualCatalogType
                            .GetProperty("Definitions", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static)
                            ?.GetValue(null) as System.Collections.ICollection;
                        Check(
                            "项目物品视觉定义加载并校验资源",
                            visualDefinitions?.Count == registeredKeys.Length,
                            $"loaded={visualDefinitions?.Count ?? -1}");
                        var iconBakerType = typeof(MyFirstCubitProject.Desktop.VanillaCrosshairLayout).Assembly
                            .GetType("MyFirstCubitProject.Desktop.ProjectItemIconBaker");
                        var bakeMethod = iconBakerType?.GetMethod(
                            "Bake",
                            System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static,
                            binder: null,
                            types: [typeof(string), itemVisualCatalogType.Assembly.GetType("MyFirstCubitProject.ProjectItemVisualDefinition")!],
                            modifiers: null);
                        var bakePassed = bakeMethod is not null &&
                            ((System.Collections.IEnumerable?)itemVisualCatalogType
                                .GetProperty("Definitions", System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static)
                                ?.GetValue(null)) is { } definitionsEnumerable &&
                            definitionsEnumerable.Cast<object>().All(definition =>
                            {
                                var result = bakeMethod.Invoke(null, [projectRoot, definition]);
                                var resultType = result?.GetType();
                                var data = resultType?.GetField("Item1")?.GetValue(result) as byte[];
                                var width = resultType?.GetField("Item2")?.GetValue(result) as int?;
                                var height = resultType?.GetField("Item3")?.GetValue(result) as int?;
                                return data is { Length: > 0 } && width is > 0 && height is > 0 && data.Length == width * height * 4;
                            });
                        Check(
                            "原版 cube/generated 模型均可烘焙为库存图标",
                            bakePassed,
                            bakeMethod is null ? "ProjectItemIconBaker.Bake missing" : "all item icons baked");
                    }
                    catch (Exception exception)
                    {
                        Check("项目物品视觉定义加载并校验资源", false, exception.InnerException?.Message ?? exception.Message);
                    }
                }
            }
            catch (Exception exception)
            {
                Check("项目物品视觉目录可解析", false, exception.Message);
            }
        }
        Check(
            "项目物品视觉目录提供按稳定 Key 查询入口",
            itemVisualCatalogType?.GetMethod("ConfigureProjectDirectory", [typeof(string)]) is not null &&
            itemVisualCatalogType.GetMethod("GetDefinition", [typeof(ushort)]) is not null,
            "ProjectItemVisualCatalog");
        var editableInventory = MyFirstCubitProject.ProjectInventoryState.CreateEmpty();
        editableInventory.Add(graniteId, 20);
        var limitChanged = MyFirstCubitProject.ProjectItemCatalog.TrySetMaxStackSize(graniteId, 16);
        var repacked = editableInventory.TryRepackItem(graniteId, 16);
        Check(
            "修改堆叠上限后库存自动按新上限重排",
            limitChanged && repacked &&
            editableInventory.GetSlot(0).Count == 16 && editableInventory.GetSlot(1).Count == 4,
            $"changed={limitChanged} repacked={repacked} slot0={editableInventory.GetSlot(0)} slot1={editableInventory.GetSlot(1)}");
        _ = MyFirstCubitProject.ProjectItemCatalog.TrySetMaxStackSize(graniteId, 64);
        Check(
            "空快捷栏槽位仍可选中",
            defaultInventory is { } emptySlotDefaults &&
            MyFirstCubitProject.ProjectHotbarCatalog.DefaultSlotCount == MyFirstCubitProject.ProjectInventoryState.HotbarSlotCount &&
            emptySlotDefaults.GetSlot(7).IsEmpty && emptySlotDefaults.GetSlot(8).IsEmpty,
            defaultInventory is { } emptyState
                ? $"count={MyFirstCubitProject.ProjectHotbarCatalog.DefaultSlotCount} slot7={emptyState.GetSlot(7)} slot8={emptyState.GetSlot(8)}"
                : "missing");

        var inventoryInput = new MyFirstCubitProject.ProjectInventoryInputState();
        var voxelInput = new VoxelInputState();
        var inputRouter = new MyFirstCubitProject.VoxelProjectInputRouter(
            voxelInput,
            new MyFirstCubitProject.VoxelDebugOverlayState(),
            inventoryInput);
        inputRouter.Handle(new ProjectInputEvent(ProjectInputControl.Digit4, true));
        Check(
            "数字键选择同步快捷栏槽位",
            inventoryInput.TryConsumeHotbarSlot(out var requestedSlot) && requestedSlot == 3,
            $"slot={requestedSlot}");
        inputRouter.Handle(new ProjectInputEvent(ProjectInputControl.Digit8, true));
        Check(
            "数字 8 可选择空快捷栏槽位并切为空气",
            inventoryInput.TryConsumeHotbarSlot(out var emptyRequestedSlot) && emptyRequestedSlot == 7 &&
            voxelInput.BuildSnapshot().SelectedBlock == BlockRegistry.Air,
            $"slot={emptyRequestedSlot} block={voxelInput.BuildSnapshot().SelectedBlock}");
        inputRouter.Handle(new ProjectInputEvent(ProjectInputControl.Digit9, true));
        Check(
            "数字 9 可选择空快捷栏槽位",
            inventoryInput.TryConsumeHotbarSlot(out var lastEmptyRequestedSlot) && lastEmptyRequestedSlot == 8,
            $"slot={lastEmptyRequestedSlot}");

        var waterId = BlockRegistry.GetId("my_first:water");
        var waterInventory = MyFirstCubitProject.ProjectInventoryState.CreateEmpty();
        var waterRemainder = waterInventory.Add(waterId, 2);
        Check(
            "水桶按原版规则不可堆叠",
            waterRemainder == 0 && waterInventory.GetSlot(0) == new MyFirstCubitProject.ProjectInventorySlot(waterId, 1) &&
            waterInventory.GetSlot(1) == new MyFirstCubitProject.ProjectInventorySlot(waterId, 1),
            $"remainder={waterRemainder} slot0={waterInventory.GetSlot(0)} slot1={waterInventory.GetSlot(1)}");
        Check(
            "不可堆叠物品拒绝超过单件数量",
            CaptureException(() => waterInventory.SetSlot(0, new MyFirstCubitProject.ProjectInventorySlot(waterId, 2))) is InvalidDataException,
            "water count=2");

        var scrollRequestMethod = typeof(MyFirstCubitProject.ProjectInventoryInputState).GetMethod("RequestHotbarScroll");
        var scrollConsumeMethod = typeof(MyFirstCubitProject.ProjectInventoryInputState).GetMethod("TryConsumeHotbarScroll");
        Check(
            "物品栏输入状态提供滚轮选择请求",
            scrollRequestMethod is not null && scrollConsumeMethod is not null,
            $"request={scrollRequestMethod is not null} consume={scrollConsumeMethod is not null}");
        if (scrollRequestMethod is not null && scrollConsumeMethod is not null)
        {
            scrollRequestMethod.Invoke(inventoryInput, [1]);
            var consumeArgs = new object?[] { 0 };
            var consumed = (bool)scrollConsumeMethod.Invoke(inventoryInput, consumeArgs)!;
            Check("滚轮请求可消费并保留方向", consumed && (int)consumeArgs[0]! == 1, $"consumed={consumed} direction={consumeArgs[0]}");
        }
        var relativeSelectionMethod = typeof(MyFirstCubitProject.ProjectInventoryState).GetMethod("SelectHotbarRelative");
        object cyclingInventoryBox = MyFirstCubitProject.ProjectInventoryState.CreateEmpty();
        var cycledBack = relativeSelectionMethod is not null &&
            (bool)relativeSelectionMethod.Invoke(cyclingInventoryBox, [-1])!;
        var cyclingInventory = (MyFirstCubitProject.ProjectInventoryState)cyclingInventoryBox;
        Check(
            "滚轮向上从第一格循环到第九格",
            cycledBack && cyclingInventory.SelectedHotbarSlot == 8,
            $"method={relativeSelectionMethod is not null} slot={cyclingInventory.SelectedHotbarSlot}");
        var cycledForward = relativeSelectionMethod is not null &&
            (bool)relativeSelectionMethod.Invoke(cyclingInventoryBox, [1])!;
        cyclingInventory = (MyFirstCubitProject.ProjectInventoryState)cyclingInventoryBox;
        Check(
            "滚轮向下从第九格循环到第一格",
            cycledForward && cyclingInventory.SelectedHotbarSlot == 0,
            $"method={relativeSelectionMethod is not null} slot={cyclingInventory.SelectedHotbarSlot}");

        var remainder = inventory.Add(7, 70);
        Check("相同物品按 64 上限堆叠", remainder == 0 && inventory.GetSlot(0).Count == 64 && inventory.GetSlot(1).Count == 6);
        Check("快捷栏选择范围生效", inventory.SelectHotbarSlot(4) && inventory.SelectedHotbarSlot == 4);
        Check("拆分移动只转移请求数量", inventory.TryMove(1, 2, 3) && inventory.GetSlot(1).Count == 3 && inventory.GetSlot(2).Count == 3);
        Check("不同物品可显式交换槽位", inventory.SetSlot(3, new MyFirstCubitProject.ProjectInventorySlot(8, 12)) &&
            inventory.SwapSlots(2, 3) && inventory.GetSlot(2).ItemId == 8 && inventory.GetSlot(3).ItemId == 7);

        var full = MyFirstCubitProject.ProjectInventoryState.CreateEmpty();
        var fullRemainder = full.Add(9, int.MaxValue);
        Check("背包满载返回未装入数量", fullRemainder == int.MaxValue - MyFirstCubitProject.ProjectInventoryState.SlotCount * MyFirstCubitProject.ProjectInventoryState.MaxStackSize &&
            full.Slots!.All(slot => slot.ItemId == 9 && slot.Count == MyFirstCubitProject.ProjectInventoryState.MaxStackSize));

        var snapshot = MyFirstCubitProject.ProjectInventorySnapshot.FromState(inventory);
        var encoded = MyFirstCubitProject.ProjectInventorySnapshot.Encode(snapshot);
        var decoded = MyFirstCubitProject.ProjectInventorySnapshot.Decode(encoded);
        Check("库存快照二进制往返", decoded.Equals(snapshot));
        encoded[^1] ^= 0x6D;
        var corrupt = CaptureException(() => MyFirstCubitProject.ProjectInventorySnapshot.Decode(encoded));
        Check("库存快照损坏校验拒绝", corrupt is InvalidDataException, corrupt?.Message ?? "none");

        Check(
            "可破坏实体方块生成同 ID 掉落",
            MyFirstCubitProject.ProjectBlockDropRules.TryGetDrop(
                new BlockState(BlockRegistry.Stone),
                out var stoneDrop) &&
            stoneDrop == new MyFirstCubitProject.ProjectInventorySlot(BlockRegistry.Stone, 1),
            $"drop={stoneDrop}");
        Check(
            "流体和基岩不生成掉落",
            !MyFirstCubitProject.ProjectBlockDropRules.TryGetDrop(
                new BlockState(BlockRegistry.Bedrock),
                out _) &&
            !MyFirstCubitProject.ProjectBlockDropRules.TryGetDrop(
                new BlockState(21),
                out _));

        var inventoryAssetPaths = new[]
        {
            "assets/minecraft/textures/gui/container/inventory.png",
            "assets/minecraft/textures/gui/sprites/container/slot_highlight_back.png",
            "assets/minecraft/textures/gui/sprites/container/slot_highlight_front.png",
            "assets/minecraft/textures/gui/sprites/hud/hotbar.png",
            "assets/minecraft/textures/gui/sprites/hud/hotbar_selection.png",
            "assets/minecraft/textures/block/bedrock.png",
            "assets/minecraft/textures/block/grass_block_side_overlay.png",
            "assets/minecraft/textures/block/granite.png",
            "assets/minecraft/textures/item/water_bucket.png",
        };
        Check(
            "项目资产包含原版库存界面纹理",
            inventoryAssetPaths.All(relativePath => File.Exists(ProjectIO.ResolveProjectPath(projectRoot, relativePath))),
            string.Join(", ", inventoryAssetPaths.Where(relativePath => !File.Exists(ProjectIO.ResolveProjectPath(projectRoot, relativePath)))));
        var inventoryRendererPath = Path.Combine(projectRoot, "src", "MyFirstCubitProject.Desktop", "ProjectInventoryRenderer.cs");
        var inventoryRendererSource = File.ReadAllText(inventoryRendererPath);
        Check(
            "库存渲染器加载原版背景与快捷栏纹理",
            inventoryRendererSource.Contains("textures/gui/container/inventory.png", StringComparison.Ordinal) &&
            inventoryRendererSource.Contains("textures/gui/sprites/hud/hotbar.png", StringComparison.Ordinal) &&
            inventoryRendererSource.Contains("CreateStaticTexture", StringComparison.Ordinal) &&
            inventoryRendererSource.Contains("AddImage", StringComparison.Ordinal));
        Check(
            "库存与快捷栏 UI 使用独立放大比例",
            inventoryRendererSource.Contains("InventoryUiScale", StringComparison.Ordinal) &&
            inventoryRendererSource.Contains("HudHotbarUiScale", StringComparison.Ordinal) &&
            inventoryRendererSource.Contains("ScaleAround", StringComparison.Ordinal));
        Check(
            "库存渲染器使用原版物品纹理",
            inventoryRendererSource.Contains("ProjectItemVisualCatalog.Definitions", StringComparison.Ordinal) &&
            inventoryRendererSource.Contains("ProjectItemIconBaker.Bake", StringComparison.Ordinal) &&
            inventoryRendererSource.Contains("GetItemTexture", StringComparison.Ordinal));
        var itemVisualsSource = File.ReadAllText(itemVisualsPath);
        Check(
            "物品视觉目录保留原版 items 模型类型和独立资源",
            itemVisualsSource.Contains("\"model\": \"cube\"", StringComparison.Ordinal) &&
            itemVisualsSource.Contains("\"model\": \"generated\"", StringComparison.Ordinal) &&
            itemVisualsSource.Contains("textures/item/water_bucket.png", StringComparison.Ordinal) &&
            itemVisualsSource.Contains("textures/block/granite.png", StringComparison.Ordinal));
        Check(
            "库存界面提供项目物品规则编辑面板",
            inventoryRendererSource.Contains("Item Rules", StringComparison.Ordinal) &&
            inventoryRendererSource.Contains("TrySetInventoryItemMaxStackSize", StringComparison.Ordinal) &&
            inventoryRendererSource.Contains("SaveProjectDirectory", StringComparison.Ordinal),
            "in-game stack limit editor");
        var desktopPresentationPath = Path.Combine(projectRoot, "src", "MyFirstCubitProject.Desktop", "MyFirstCubitDesktopPresentation.cs");
        var desktopPresentationSource = File.ReadAllText(desktopPresentationPath);
        Check(
            "桌面游戏态滚轮转发快捷栏选择",
            desktopPresentationSource.Contains("_inventory.OnMouseWheel", StringComparison.Ordinal),
            "MyFirstCubitDesktopPresentation wheel route");
        var playerControllerPath = Path.Combine(projectRoot, "src", "PlayerController.cs");
        var playerControllerSource = File.ReadAllText(playerControllerPath);
        Check(
            "空快捷栏禁止放置空气",
            playerControllerSource.Contains("SelectedBlock == BlockRegistry.Air", StringComparison.Ordinal),
            "PlayerController placement guard");
        var repository = new MyFirstCubitProject.WorldRepository(projectRoot);
        var summary = repository.Create("库存往返自检", 20260827u, WorldType.Flat);
        try
        {
            var persistedState = MyFirstCubitProject.ProjectInventoryState.CreateEmpty();
            persistedState.Add(BlockRegistry.Stone, 5);
            persistedState.SelectHotbarSlot(3);
            var persistedSnapshot = MyFirstCubitProject.ProjectInventorySnapshot.FromState(persistedState);
            repository.SaveInventory(summary, persistedSnapshot);
            using var opened = repository.Open(summary);
            Check(
                "世界打开恢复独立库存快照",
                opened.InventoryState?.Equals(persistedSnapshot) == true,
                opened.InventoryState is null ? "missing" : "restored");
            Check(
                "库存快照使用独立文件",
                File.Exists(Path.Combine(projectRoot, "saves", summary.Id, "inventory.cubit.bin")));
        }
        finally
        {
            repository.Delete(summary);
        }
    }
    catch (Exception exception)
    {
        Check("项目库存 fixture 执行", false, exception.ToString());
    }

    Console.WriteLine(failures == 0
        ? "projectinventorycheck 全部通过"
        : $"projectinventorycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectProjectileCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var assembly = typeof(MyFirstCubitProject.WorldRepository).Assembly;
    var stateType = assembly.GetType("MyFirstCubitProject.ProjectProjectileState");
    var systemType = assembly.GetType("MyFirstCubitProject.ProjectProjectileSystem");
    var factoryType = assembly.GetType("MyFirstCubitProject.ProjectProjectileFactory");
    var snapshotType = assembly.GetType("MyFirstCubitProject.ProjectProjectileSnapshot");
    var presentationType = assembly.GetType("MyFirstCubitProject.ProjectProjectilePresentationSystem");
    var targetRegistryType = assembly.GetType("MyFirstCubitProject.ProjectCombatTargetRegistry");
    var healthType = assembly.GetType("MyFirstCubitProject.ProjectHealthState");
    var damageType = assembly.GetType("MyFirstCubitProject.ProjectProjectileDamageSystem");
    var bindingType = assembly.GetType("MyFirstCubitProject.ProjectCombatTargetBinding");
    var collisionType = assembly.GetType("MyFirstCubitProject.ProjectProjectileCollisionSystem");
    var hitEventType = assembly.GetType("MyFirstCubitProject.ProjectProjectileHitEvent");
    var bridgeType = assembly.GetType("MyFirstCubitProject.PlayerEcsBridgeNode");
    Check("项目提供 Projectile ECS 状态", stateType is not null, stateType?.FullName ?? "missing");
    Check("项目提供 Projectile 生命周期 System", systemType is not null, systemType?.FullName ?? "missing");
    Check("项目提供 Projectile 生成工厂", factoryType is not null, factoryType?.FullName ?? "missing");
    Check("项目提供 Projectile 独立持久化快照", snapshotType is not null, snapshotType?.FullName ?? "missing");
    Check("项目提供 Projectile 批量表现快照 System", presentationType is not null, presentationType?.FullName ?? "missing");
    Check("项目提供 Combat ColliderId 映射注册表", targetRegistryType is not null, targetRegistryType?.FullName ?? "missing");
    Check("项目提供项目层健康组件", healthType is not null, healthType?.FullName ?? "missing");
    Check("项目提供 Projectile 伤害 System", damageType is not null, damageType?.FullName ?? "missing");
    Check("项目提供 Combat 目标生命周期 Binding", bindingType is not null, bindingType?.FullName ?? "missing");
    Check("项目提供 Projectile 碰撞适配 System", collisionType is not null, collisionType?.FullName ?? "missing");
    Check("项目提供 Projectile 命中事件数据", hitEventType is not null, hitEventType?.FullName ?? "missing");
    Check("项目提供 Projectile 命中事件消费入口", collisionType?.GetMethod("ConsumeHits") is not null,
        collisionType?.FullName ?? "missing");
    Check("玩家 ECS 桥接提供 Projectile 生成入口", bridgeType?.GetMethod("SpawnProjectile") is not null,
        bridgeType?.FullName ?? "missing");
    Check("玩家 ECS 桥接提供 Combat 目标注册表入口",
        bridgeType?.GetProperty("CombatTargets") is not null,
        bridgeType?.FullName ?? "missing");

    if (snapshotType is not null)
    {
        var snapshot = new MyFirstCubitProject.ProjectProjectileSnapshot(
            new Vector3(4f, 5f, 6f),
            new Vector3(1.25f, -0.5f, 0.75f),
            11,
            1.5f,
            20f);
        var encoded = MyFirstCubitProject.ProjectProjectileSnapshot.EncodeMany([snapshot]);
        var decoded = MyFirstCubitProject.ProjectProjectileSnapshot.DecodeMany(encoded);
        Check("Projectile 快照二进制往返", decoded.Count == 1 && decoded[0] == snapshot,
            decoded.Count == 0 ? "missing" : decoded[0].ToString());
        encoded[^1] ^= 0x36;
        var corruption = CaptureException(() => MyFirstCubitProject.ProjectProjectileSnapshot.DecodeMany(encoded));
        Check("Projectile 快照损坏校验拒绝", corruption is InvalidDataException, corruption?.Message ?? "none");
    }

    if (stateType is null || systemType is null || factoryType is null || collisionType is null || hitEventType is null ||
        collisionType.GetMethod("ConsumeHits") is null)
    {
        Console.WriteLine($"projectprojectilecheck 失败 {failures} 项");
        return 1;
    }

    try
    {
        using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var tree = new SceneTree();
        var node = new EcsNode { Name = "ProjectileEcs", Jobs = jobs };
        var focus = node.World.CreateEntity();
        node.World.AddComponent(focus, new MyFirstCubitProject.PlayerMotionState { Position = Vector3.Zero });
        node.AddSystem(new MyFirstCubitProject.ProjectEntityInterestSystem(
            focus,
            new Vector3(16f, 16f, 16f),
            trackedRadius: 2,
            tickingRadius: 1));

        var factory = factoryType.GetMethod("Spawn", BindingFlags.Public | BindingFlags.Static)
            ?? throw new MissingMethodException(factoryType.FullName, "Spawn");
        var ticking = (EntityId)(factory.Invoke(null, new object?[]
        {
            node.World,
            Vector3.Zero,
            new Vector3(10f, 0f, 0f),
            (ushort)3,
            0.2f,
        }) ?? throw new InvalidOperationException("Projectile Spawn 未返回 EntityId"));
        var tracked = (EntityId)(factory.Invoke(null, new object?[]
        {
            node.World,
            new Vector3(32f, 0f, 0f),
            new Vector3(10f, 0f, 0f),
            (ushort)4,
            1f,
        }) ?? throw new InvalidOperationException("Projectile Spawn 未返回 EntityId"));
        var hidden = (EntityId)(factory.Invoke(null, new object?[]
        {
            node.World,
            new Vector3(160f, 0f, 0f),
            new Vector3(10f, 0f, 0f),
            (ushort)5,
            1f,
        }) ?? throw new InvalidOperationException("Projectile Spawn 未返回 EntityId"));

        var projectileSystem = (IEcsSystem)(Activator.CreateInstance(systemType, focus)
            ?? throw new InvalidOperationException("Projectile System 创建失败"));
        node.AddSystem(projectileSystem);
        var presentation = new MyFirstCubitProject.ProjectProjectilePresentationSystem();
        node.AddSystem(presentation);
        Check("Projectile System 纯数据路径可交给 JobSystem",
            !projectileSystem.Descriptor.RequiresMainThread,
            $"requiresMainThread={projectileSystem.Descriptor.RequiresMainThread}");
        tree.Root.AddChild(node);
        tree.ProcessFrame(0.05d);

        var getSpatial = typeof(EcsWorld).GetMethod(nameof(EcsWorld.GetComponent))!
            .MakeGenericMethod(typeof(MyFirstCubitProject.ProjectEntitySpatialState));
        var getState = typeof(EcsWorld).GetMethod(nameof(EcsWorld.GetComponent))!
            .MakeGenericMethod(stateType);
        var positionOf = (EntityId entity) =>
            ((MyFirstCubitProject.ProjectEntitySpatialState)(getSpatial.Invoke(node.World, new object?[] { entity })
                ?? throw new InvalidOperationException("Projectile 缺少空间组件"))).Position;
        var ageOf = (EntityId entity) =>
            (float)(stateType.GetField("AgeSeconds")?.GetValue(getState.Invoke(node.World, new object?[] { entity }))
                ?? throw new InvalidOperationException("Projectile 缺少年龄组件"));

        var tickingPosition = positionOf(ticking);
        var trackedPosition = positionOf(tracked);
        var hiddenPosition = positionOf(hidden);
        Check("Projectile 仅在 Ticking 层级积分位置和年龄",
            Math.Abs(tickingPosition.X - 0.5f) < 0.001f && ageOf(ticking) > 0f,
            $"position={tickingPosition} age={ageOf(ticking):F3}");
        Check("Projectile Tracked/Hidden 不推进模拟",
            trackedPosition == new Vector3(32f, 0f, 0f) &&
            hiddenPosition == new Vector3(160f, 0f, 0f) &&
            ageOf(tracked) == 0f && ageOf(hidden) == 0f,
            $"tracked={trackedPosition}/{ageOf(tracked):F3} hidden={hiddenPosition}/{ageOf(hidden):F3}");

        var firstPresentation = presentation.VisibleProjectiles;
        var firstPresentationEntities = firstPresentation.Select(item => item.Entity).ToArray();
        Check("Projectile RenderPrepare 快照过滤 Hidden 且排序稳定",
            firstPresentation.Any(item => item.Entity == ticking || item.Entity == tracked) &&
            firstPresentation.All(item => item.Entity != hidden) &&
            firstPresentationEntities.SequenceEqual(firstPresentation
                .OrderBy(item => item.Tier)
                .ThenBy(item => item.Entity.Index)
                .Select(item => item.Entity)),
            $"visible={firstPresentation.Count}");

        tree.ProcessFrame(0.2d);
        Check("Projectile 表现快照不被下一帧改写",
            firstPresentation.Count == firstPresentationEntities.Length &&
            firstPresentation.Select(item => item.Entity).SequenceEqual(firstPresentationEntities) &&
            !ReferenceEquals(firstPresentation, presentation.VisibleProjectiles),
            $"old={firstPresentation.Count} new={presentation.VisibleProjectiles.Count}");
        Check("Projectile 寿命到期通过 CommandBuffer 销毁",
            !node.World.IsAlive(ticking) && node.World.IsAlive(tracked) && node.World.IsAlive(hidden),
            $"ticking={node.World.IsAlive(ticking)} tracked={node.World.IsAlive(tracked)} hidden={node.World.IsAlive(hidden)}");

        {
            using var physicsTree = new SceneTree();
            var physics = new PhysicsWorld3D { Name = "Physics" };
            var target = new StaticBody3D { Name = "Target", Position = new Vector3(2f, 0f, 0f) };
            target.AddChild(new CollisionShape3D
            {
                Shape = new BoxShape3D { Size = Vector3.One },
            });
            physics.AddChild(target);
            physicsTree.Root.AddChild(physics);
            physicsTree.ProcessFrame(0.05d);
            Check("Projectile Physics fixture 已登记静态碰撞体",
                physics.ColliderCount == 1,
                $"colliders={physics.ColliderCount}");
            var fixtureRayHits = new List<PhysicsRayHit3D>();
            var fixtureRayCount = physics.Raycast(
                Vector3.Zero,
                Vector3.UnitX,
                4f,
                new PhysicsQueryFilter(),
                fixtureRayHits);
            Check("Projectile Physics fixture 射线可命中静态碰撞体",
                fixtureRayCount == 1,
                $"hits={fixtureRayCount}");

            var collisionNode = new EcsNode { Name = "ProjectileCollisionEcs", Jobs = jobs };
            var collisionFocus = collisionNode.World.CreateEntity();
            collisionNode.World.AddComponent(
                collisionFocus,
                new MyFirstCubitProject.PlayerMotionState { Position = Vector3.Zero });
            collisionNode.AddSystem(new MyFirstCubitProject.ProjectEntityInterestSystem(
                collisionFocus,
                new Vector3(16f, 16f, 16f),
                trackedRadius: 2,
                tickingRadius: 1));
            var collisionFactory = factoryType.GetMethod("Spawn", BindingFlags.Public | BindingFlags.Static)
                ?? throw new MissingMethodException(factoryType.FullName, "Spawn");
            var collisionProjectile = (EntityId)(collisionFactory.Invoke(null, new object?[]
            {
                collisionNode.World,
                Vector3.Zero,
                new Vector3(40f, 0f, 0f),
                (ushort)8,
                1f,
            }) ?? throw new InvalidOperationException("Projectile Spawn 未返回 EntityId"));
            var collisionMovement = (IEcsSystem)(Activator.CreateInstance(systemType, collisionFocus)
                ?? throw new InvalidOperationException("Projectile System 创建失败"));
            var collisionAdapter = (IEcsSystem)(Activator.CreateInstance(
                    collisionType,
                    collisionFocus,
                    physics,
                    null,
                    uint.MaxValue)
                ?? throw new InvalidOperationException("Projectile Collision System 创建失败"));
            collisionNode.AddSystem(collisionMovement);
            collisionNode.AddSystem(collisionAdapter);
            Check("Projectile 碰撞适配器保留 Physics 主线程边界",
                collisionAdapter.Descriptor.RequiresMainThread,
                $"requiresMainThread={collisionAdapter.Descriptor.RequiresMainThread}");
            physics.AddChild(collisionNode);
            Check("Projectile 碰撞 EcsNode 已初始化并注册 System",
                collisionNode.IsInitialized && collisionNode.Scheduler!.BuildBatches(EcsSystemPhase.FixedUpdate)
                    .SelectMany(batch => batch)
                    .Contains(collisionAdapter),
                $"initialized={collisionNode.IsInitialized}");
            physicsTree.ProcessFrame(0.1d);

            var consumedHits = collisionType.GetMethod("ConsumeHits")?.Invoke(collisionAdapter, null);
            var hitEnumerable = consumedHits
                as System.Collections.IEnumerable;
            var hits = hitEnumerable?.Cast<object>().ToArray() ?? [];
            var colliderId = hits.Length == 1
                ? (long?)Convert.ToInt64(hitEventType.GetProperty("ColliderId")?.GetValue(hits[0]))
                : null;
            Check("Projectile 穿越静态碰撞体生成命中事件并销毁",
                !collisionNode.World.IsAlive(collisionProjectile) && hits.Length == 1,
                $"alive={collisionNode.World.IsAlive(collisionProjectile)} hits={hits.Length}");
            Check("Projectile 命中事件只暴露稳定 ColliderId",
                colliderId is > 0 && hitEventType.GetProperty("Collider") is null,
                $"colliderId={colliderId?.ToString() ?? "missing"}");
            var consumedAgain = collisionType.GetMethod("ConsumeHits")?.Invoke(collisionAdapter, null)
                as System.Collections.IEnumerable;
            Check("Projectile 命中事件消费后清空队列",
                consumedAgain is null || !consumedAgain.Cast<object>().Any(),
                consumedAgain is null ? "missing" : "remaining");

            var damageNode = new EcsNode { Name = "ProjectileDamageEcs", Jobs = jobs };
            var damageFocus = damageNode.World.CreateEntity();
            damageNode.World.AddComponent(
                damageFocus,
                new MyFirstCubitProject.PlayerMotionState { Position = Vector3.Zero });
            damageNode.AddSystem(new MyFirstCubitProject.ProjectEntityInterestSystem(
                damageFocus,
                new Vector3(16f, 16f, 16f),
                trackedRadius: 2,
                tickingRadius: 1));
            var damageFactory = factoryType.GetMethod("Spawn", BindingFlags.Public | BindingFlags.Static)
                ?? throw new MissingMethodException(factoryType.FullName, "Spawn");
            damageFactory.Invoke(null, new object?[]
            {
                damageNode.World,
                Vector3.Zero,
                new Vector3(40f, 0f, 0f),
                (ushort)8,
                1f,
            });
            var damageCollision = new MyFirstCubitProject.ProjectProjectileCollisionSystem(
                damageFocus,
                physics,
                null);
            var targetRegistry = new MyFirstCubitProject.ProjectCombatTargetRegistry();
            var targetBinding = MyFirstCubitProject.ProjectCombatTargetBinding.Attach(
                damageNode.World,
                targetRegistry,
                fixtureRayHits[0].ColliderId,
                new Vector3(2f, 0f, 0f),
                maximumHealth: 10f);
            var targetEntity = targetBinding.Entity;
            var damageSystem = new MyFirstCubitProject.ProjectProjectileDamageSystem(
                damageCollision,
                targetRegistry,
                static projectileId => projectileId == 8 ? 3f : 0f);
            damageNode.AddSystem(new MyFirstCubitProject.ProjectProjectileSystem(damageFocus));
            damageNode.AddSystem(damageCollision);
            damageNode.AddSystem(damageSystem);
            Check("Projectile Damage System 保留主线程事件消费边界",
                damageSystem.Descriptor.RequiresMainThread,
                $"requiresMainThread={damageSystem.Descriptor.RequiresMainThread}");
            physics.AddChild(damageNode);
            physicsTree.ProcessFrame(0.05d);
            var health = damageNode.World.GetComponent<MyFirstCubitProject.ProjectHealthState>(targetEntity);
            Check("Projectile ColliderId 映射并应用项目伤害",
                health.Current == 7f && health.Maximum == 10f,
                $"health={health.Current}/{health.Maximum}");
            targetBinding.Dispose();
            Check("Combat 目标 Binding Dispose 解除映射并销毁 Entity",
                targetRegistry.Count == 0 && !damageNode.World.IsAlive(targetEntity),
                $"registry={targetRegistry.Count} alive={damageNode.World.IsAlive(targetEntity)}");
        }
    }
    catch (Exception exception)
    {
        Check("项目 Projectile fixture 执行", false, exception.ToString());
    }

    Console.WriteLine(failures == 0
        ? "projectprojectilecheck 全部通过"
        : $"projectprojectilecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectCombatTargetCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var assembly = typeof(MyFirstCubitProject.WorldRepository).Assembly;
    var bridgeType = assembly.GetType("MyFirstCubitProject.ProjectCombatTargetBridgeNode");
    Check("项目提供作者化 Combat Target Bridge Node", bridgeType is not null, bridgeType?.FullName ?? "missing");
    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var gameplayPath = workspaceRoot is null
        ? null
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "scenes", "gameplay.cscene");
    Check("正式 gameplay 不偷偷创建 Combat Target Bridge Node",
        gameplayPath is not null &&
        !File.ReadAllText(gameplayPath).Contains("ProjectCombatTargetBridgeNode", StringComparison.Ordinal),
        gameplayPath ?? "missing");

    if (bridgeType is not null)
    {
        try
        {
            using var session = CreateVoxelProjectSession(
                new FakeRenderBackend(),
                20260808u,
                workerCount: 1,
                worldType: WorldType.Flat);
            var playerBridge = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs") as MyFirstCubitProject.PlayerEcsBridgeNode;
            var target = new MyFirstCubitProject.ProjectCombatTargetBridgeNode
            {
                Name = "FixtureTarget",
                Position = new Vector3(30f, 6f, 30f),
                EcsBridgePath = "/Root/Physics/PlayerEcs",
                CollisionShapePath = "Shape",
                MaximumHealth = 10f,
            };
            target.AddChild(new CollisionShape3D
            {
                Name = "Shape",
                Shape = new BoxShape3D { Size = Vector3.One },
            });
            playerBridge?.AddChild(target);
            session.Scene.Tree.Paused = false;
            session.Scene.ProcessFrame(0.1d);
            var physicsWorld = session.Scene.Tree.GetNode("/Root/Physics") as PhysicsWorld3D;
            var targetShape = target.GetNode("Shape") as CollisionShape3D;
            Check("Combat Target fixture 进入 SceneTree 并登记 Physics 形状",
                target.Parent is not null && targetShape?.ColliderId > 0,
                $"parent={target.Parent?.GetPath().Value ?? "detached"} collider={targetShape?.ColliderId} physicsColliders={physicsWorld?.ColliderCount}");
            var world = playerBridge?.EcsWorld;
            var targetEntity = target.TargetEntity;
            Check("作者化 Combat Target 在 Physics 登记后创建 ECS Binding",
                target.IsTargetBound && target.RegisteredColliderId > 0 &&
                playerBridge?.CombatTargets?.Count == 1 && world?.IsAlive(targetEntity) == true,
                $"bound={target.IsTargetBound} collider={target.RegisteredColliderId} registry={playerBridge?.CombatTargets?.Count}");
            Check("Combat Target Binding 创建项目健康组件",
                world is not null && world.HasComponent<MyFirstCubitProject.ProjectHealthState>(targetEntity),
                targetEntity.ToString());
            playerBridge?.RemoveChild(target);
            Check("作者化 Combat Target 退出树清理映射和 Entity",
                playerBridge?.CombatTargets?.Count == 0 && (world is null || !world.IsAlive(targetEntity)),
                $"registry={playerBridge?.CombatTargets?.Count} alive={world?.IsAlive(targetEntity)}");
        }
        catch (Exception exception)
        {
            Check("Combat Target Bridge fixture 执行", false, exception.ToString());
        }
    }

    Console.WriteLine(failures == 0
        ? "projectcombattargetcheck 全部通过"
        : $"projectcombattargetcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectMonsterCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var assembly = typeof(MyFirstCubitProject.WorldRepository).Assembly;
    var stateType = assembly.GetType("MyFirstCubitProject.ProjectMonsterState");
    var factoryType = assembly.GetType("MyFirstCubitProject.ProjectMonsterFactory");
    var systemType = assembly.GetType("MyFirstCubitProject.ProjectMonsterSystem");
    var snapshotType = assembly.GetType("MyFirstCubitProject.ProjectMonsterSnapshot");
    var aiStateType = assembly.GetType("MyFirstCubitProject.ProjectMonsterAiState");
    var aiSystemType = assembly.GetType("MyFirstCubitProject.ProjectMonsterAiSystem");
    var spawnPolicyType = assembly.GetType("MyFirstCubitProject.ProjectMonsterSpawnPolicy");
    var spawnSystemType = assembly.GetType("MyFirstCubitProject.ProjectMonsterSpawnSystem");
    var spawnResolverType = assembly.GetType("MyFirstCubitProject.ProjectMonsterSpawnPositionResolver");
    var voxelResolverType = assembly.GetType("MyFirstCubitProject.ProjectVoxelMonsterSpawnPositionResolver");
    var navigationType = assembly.GetType("MyFirstCubitProject.IProjectMonsterNavigationQuery");
    var pathStateType = assembly.GetType("MyFirstCubitProject.ProjectMonsterPathState");
    var pathPolicyType = assembly.GetType("MyFirstCubitProject.ProjectMonsterPathPolicy");
    var pathSystemType = assembly.GetType("MyFirstCubitProject.ProjectMonsterPathSystem");
    var attackStateType = assembly.GetType("MyFirstCubitProject.ProjectMonsterAttackState");
    var attackEventType = assembly.GetType("MyFirstCubitProject.ProjectMonsterAttackEvent");
    var attackSystemType = assembly.GetType("MyFirstCubitProject.ProjectMonsterAttackSystem");
    var attackDamageType = assembly.GetType("MyFirstCubitProject.ProjectMonsterAttackDamageSystem");
    var deathSystemType = assembly.GetType("MyFirstCubitProject.ProjectHealthDeathSystem");
    var entityBindingType = assembly.GetType("MyFirstCubitProject.ProjectCombatEntityBinding");
    var playerDeathStateType = assembly.GetType("MyFirstCubitProject.ProjectPlayerDeathState");
    var playerDeathEventType = assembly.GetType("MyFirstCubitProject.ProjectPlayerDeathEvent");
    var playerDeathSystemType = assembly.GetType("MyFirstCubitProject.ProjectPlayerDeathSystem");
    var targetQueryType = assembly.GetType("MyFirstCubitProject.IProjectMonsterTargetQuery");
    var targetRegistryType = assembly.GetType("MyFirstCubitProject.ProjectMonsterTargetRegistry");
    var presentationType = assembly.GetType("MyFirstCubitProject.ProjectMonsterPresentationSystem");
    var bridgeType = assembly.GetType("MyFirstCubitProject.PlayerEcsBridgeNode");
    Check("项目提供 Monster ECS 状态", stateType is not null, stateType?.FullName ?? "missing");
    Check("项目提供 Monster 生成工厂", factoryType is not null, factoryType?.FullName ?? "missing");
    Check("项目提供 Monster 生命周期 System", systemType is not null, systemType?.FullName ?? "missing");
    Check("项目提供 Monster 独立持久化快照", snapshotType is not null, snapshotType?.FullName ?? "missing");
    Check("项目提供 Monster AI 状态", aiStateType is not null, aiStateType?.FullName ?? "missing");
    Check("项目提供 Monster AI System", aiSystemType is not null, aiSystemType?.FullName ?? "missing");
    Check("项目提供 Monster 生成策略", spawnPolicyType is not null, spawnPolicyType?.FullName ?? "missing");
    Check("项目提供 Monster 生成 System", spawnSystemType is not null, spawnSystemType?.FullName ?? "missing");
    Check("项目提供 Monster 生成位置验证委托", spawnResolverType is not null, spawnResolverType?.FullName ?? "missing");
    Check("项目提供 Voxel Monster 生成位置验证器", voxelResolverType is not null, voxelResolverType?.FullName ?? "missing");
    Check("项目提供 Monster 导航查询契约", navigationType is not null, navigationType?.FullName ?? "missing");
    Check("项目提供 Monster 路径状态", pathStateType is not null, pathStateType?.FullName ?? "missing");
    Check("项目提供 Monster 路径策略", pathPolicyType is not null, pathPolicyType?.FullName ?? "missing");
    Check("项目提供 Monster 路径 System", pathSystemType is not null, pathSystemType?.FullName ?? "missing");
    Check("项目提供 Monster 攻击状态", attackStateType is not null, attackStateType?.FullName ?? "missing");
    Check("项目提供 Monster 攻击事件", attackEventType is not null, attackEventType?.FullName ?? "missing");
    Check("项目提供 Monster 攻击 System", attackSystemType is not null, attackSystemType?.FullName ?? "missing");
    Check("项目提供 Monster 攻击伤害消费 System", attackDamageType is not null, attackDamageType?.FullName ?? "missing");
    Check("项目提供通用项目健康死亡 System", deathSystemType is not null, deathSystemType?.FullName ?? "missing");
    Check("项目提供动态 ECS Combat 目标绑定", entityBindingType is not null, entityBindingType?.FullName ?? "missing");
    Check("项目提供玩家死亡状态", playerDeathStateType is not null, playerDeathStateType?.FullName ?? "missing");
    Check("项目提供玩家死亡事件", playerDeathEventType is not null, playerDeathEventType?.FullName ?? "missing");
    Check("项目提供玩家死亡 System", playerDeathSystemType is not null, playerDeathSystemType?.FullName ?? "missing");
    Check("项目提供 Monster 多目标查询契约", targetQueryType is not null, targetQueryType?.FullName ?? "missing");
    Check("项目提供 Monster 目标注册表", targetRegistryType is not null, targetRegistryType?.FullName ?? "missing");
    Check("项目提供 Monster 批量表现 System", presentationType is not null, presentationType?.FullName ?? "missing");
    Check("项目桥接提供显式 Monster 生成配置入口",
        bridgeType?.GetMethod("ConfigureMonsterSpawning", BindingFlags.Public | BindingFlags.Instance) is not null,
        "ConfigureMonsterSpawning");
    Check("项目桥接提供显式 Monster 寻路配置入口",
        bridgeType?.GetMethod("ConfigureMonsterPathfinding", BindingFlags.Public | BindingFlags.Instance) is not null,
        "ConfigureMonsterPathfinding");
    Check("项目桥接提供显式 Monster Combat 配置入口",
        bridgeType?.GetMethod("ConfigureMonsterCombat", BindingFlags.Public | BindingFlags.Instance) is not null,
        "ConfigureMonsterCombat");
    Check("项目桥接提供 Monster 攻击状态配置入口",
        bridgeType?.GetMethod("ConfigureMonsterAttack", BindingFlags.Public | BindingFlags.Instance) is not null,
        "ConfigureMonsterAttack");
    Check("项目桥接提供动态 ECS Combat 绑定入口",
        bridgeType?.GetMethod("BindCombatEntity", BindingFlags.Public | BindingFlags.Instance) is not null,
        "BindCombatEntity");
    Check("项目桥接提供玩家死亡事件消费入口",
        bridgeType?.GetMethod("ConsumePlayerDeathEvents", BindingFlags.Public | BindingFlags.Instance) is not null,
        "ConsumePlayerDeathEvents");
    Check("项目桥接提供死亡前存活玩家保存检查点入口",
        bridgeType?.GetMethod("CaptureSaveState", BindingFlags.Public | BindingFlags.Instance) is not null,
        "CaptureSaveState");
    Check("项目桥接提供 Monster 目标注册入口",
        bridgeType?.GetMethod("RegisterMonsterTarget", BindingFlags.Public | BindingFlags.Instance) is not null,
        "RegisterMonsterTarget");
    if (stateType is null || factoryType is null || systemType is null || snapshotType is null ||
        aiStateType is null || aiSystemType is null || spawnPolicyType is null || spawnSystemType is null ||
        spawnResolverType is null || voxelResolverType is null || navigationType is null || pathStateType is null ||
        pathPolicyType is null || pathSystemType is null || attackStateType is null || attackEventType is null ||
        attackSystemType is null || attackDamageType is null || deathSystemType is null || entityBindingType is null ||
        playerDeathStateType is null || playerDeathEventType is null || playerDeathSystemType is null ||
        targetQueryType is null || targetRegistryType is null || presentationType is null)
    {
        Console.WriteLine($"projectmonstercheck 失败 {failures} 项");
        return 1;
    }

    try
    {
        using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var tree = new SceneTree();
        var node = new EcsNode { Name = "MonsterEcs", Jobs = jobs };
        var focus = node.World.CreateEntity();
        node.World.AddComponent(focus, new MyFirstCubitProject.PlayerMotionState { Position = Vector3.Zero });
        node.AddSystem(new MyFirstCubitProject.ProjectEntityInterestSystem(
            focus,
            new Vector3(16f, 16f, 16f),
            trackedRadius: 2,
            tickingRadius: 1));

        var factory = factoryType.GetMethod("Spawn", BindingFlags.Public | BindingFlags.Static)
            ?? throw new MissingMethodException(factoryType.FullName, "Spawn");
        var ticking = (EntityId)(factory.Invoke(null, new object?[]
        {
            node.World, Vector3.Zero, new Vector3(10f, 0f, 0f), (ushort)1, 0.2f,
        }) ?? throw new InvalidOperationException("Monster Spawn 未返回 EntityId"));
        var tracked = (EntityId)(factory.Invoke(null, new object?[]
        {
            node.World, new Vector3(32f, 0f, 0f), new Vector3(10f, 0f, 0f), (ushort)2, 1f,
        }) ?? throw new InvalidOperationException("Monster Spawn 未返回 EntityId"));
        var hidden = (EntityId)(factory.Invoke(null, new object?[]
        {
            node.World, new Vector3(160f, 0f, 0f), new Vector3(10f, 0f, 0f), (ushort)3, 1f,
        }) ?? throw new InvalidOperationException("Monster Spawn 未返回 EntityId"));
        var aiNear = (EntityId)(factory.Invoke(null, new object?[]
        {
            node.World, new Vector3(8f, 0f, 0f), Vector3.Zero, (ushort)4, 1f,
        }) ?? throw new InvalidOperationException("Monster Spawn 未返回 EntityId"));
        node.World.AddComponent(aiNear, new MyFirstCubitProject.ProjectMonsterAiState
        {
            DetectionRadius = 16f,
            FollowSpeed = 4f,
        });
        var aiFar = (EntityId)(factory.Invoke(null, new object?[]
        {
            node.World, new Vector3(32f, 0f, 0f), Vector3.Zero, (ushort)5, 1f,
        }) ?? throw new InvalidOperationException("Monster Spawn 未返回 EntityId"));
        node.World.AddComponent(aiFar, new MyFirstCubitProject.ProjectMonsterAiState
        {
            DetectionRadius = 16f,
            FollowSpeed = 4f,
        });
        var aiSystem = (IEcsSystem)(Activator.CreateInstance(aiSystemType, focus)
            ?? throw new InvalidOperationException("Monster AI System 创建失败"));
        node.AddSystem(aiSystem);
        Check("Monster AI 纯数据 System 可交给 JobSystem",
            !aiSystem.Descriptor.RequiresMainThread,
            $"requiresMainThread={aiSystem.Descriptor.RequiresMainThread}");
        var system = (IEcsSystem)(Activator.CreateInstance(systemType, focus)
            ?? throw new InvalidOperationException("Monster System 创建失败"));
        node.AddSystem(system);
        Check("Monster 纯数据 System 可交给 JobSystem",
            !system.Descriptor.RequiresMainThread,
            $"requiresMainThread={system.Descriptor.RequiresMainThread}");
        tree.Root.AddChild(node);
        tree.ProcessFrame(0.05d);

        var getState = typeof(EcsWorld).GetMethod(nameof(EcsWorld.GetComponent))!
            .MakeGenericMethod(stateType);
        var getSpatial = typeof(EcsWorld).GetMethod(nameof(EcsWorld.GetComponent))!
            .MakeGenericMethod(typeof(MyFirstCubitProject.ProjectEntitySpatialState));
        var getAi = typeof(EcsWorld).GetMethod(nameof(EcsWorld.GetComponent))!
            .MakeGenericMethod(aiStateType);
        var ageOf = (EntityId entity) =>
            (float)(stateType.GetField("AgeSeconds")?.GetValue(getState.Invoke(node.World, new object?[] { entity }))
                ?? throw new InvalidOperationException("Monster 缺少年龄组件"));
        var positionOf = (EntityId entity) =>
            ((MyFirstCubitProject.ProjectEntitySpatialState)(getSpatial.Invoke(node.World, new object?[] { entity })
                ?? throw new InvalidOperationException("Monster 缺少空间组件"))).Position;
        var targetOf = (EntityId entity) =>
            (EntityId)(aiStateType.GetField("TargetEntity")?.GetValue(getAi.Invoke(node.World, new object?[] { entity }))
                ?? throw new InvalidOperationException("Monster 缺少 AI 目标组件"));
        var velocityOf = (EntityId entity) =>
            (Vector3)(stateType.GetField("Velocity")?.GetValue(getState.Invoke(node.World, new object?[] { entity }))
                ?? throw new InvalidOperationException("Monster 缺少速度组件"));
        Check("Monster 仅在 Ticking 层级积分位置和年龄",
            Math.Abs(positionOf(ticking).X - 0.5f) < 0.001f && ageOf(ticking) > 0f,
            $"position={positionOf(ticking)} age={ageOf(ticking):F3}");
        Check("Monster Tracked/Hidden 不推进模拟",
            positionOf(tracked) == new Vector3(32f, 0f, 0f) &&
            positionOf(hidden) == new Vector3(160f, 0f, 0f) &&
            ageOf(tracked) == 0f && ageOf(hidden) == 0f,
            $"tracked={positionOf(tracked)}/{ageOf(tracked):F3} hidden={positionOf(hidden)}/{ageOf(hidden):F3}");
        Check("Monster AI 选择感知半径内玩家并生成水平跟随速度",
            targetOf(aiNear) == focus && velocityOf(aiNear).X < -3.9f &&
            targetOf(aiFar) == default && velocityOf(aiFar) == Vector3.Zero,
            $"nearTarget={targetOf(aiNear)} nearVelocity={velocityOf(aiNear)} farTarget={targetOf(aiFar)} farVelocity={velocityOf(aiFar)}");
        tree.ProcessFrame(0.2d);
        Check("Monster 寿命到期通过 CommandBuffer 销毁",
            !node.World.IsAlive(ticking) && node.World.IsAlive(tracked) && node.World.IsAlive(hidden),
            $"ticking={node.World.IsAlive(ticking)} tracked={node.World.IsAlive(tracked)} hidden={node.World.IsAlive(hidden)}");

        var snapshot = new MyFirstCubitProject.ProjectMonsterSnapshot(
            new Vector3(4f, 5f, 6f),
            new Vector3(1.25f, -0.5f, 0.75f),
            21,
            1.5f,
            20f);
        var encoded = MyFirstCubitProject.ProjectMonsterSnapshot.EncodeMany([snapshot]);
        var decoded = MyFirstCubitProject.ProjectMonsterSnapshot.DecodeMany(encoded);
        Check("Monster 快照二进制往返", decoded.Count == 1 && decoded[0] == snapshot,
            decoded.Count == 0 ? "missing" : decoded[0].ToString());
        encoded[^1] ^= 0x51;
        var corruption = CaptureException(() => MyFirstCubitProject.ProjectMonsterSnapshot.DecodeMany(encoded));
        Check("Monster 快照损坏校验拒绝", corruption is InvalidDataException, corruption?.Message ?? "none");

        using var spawnJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var spawnTree = new SceneTree();
        var spawnNode = new EcsNode { Name = "MonsterSpawnEcs", Jobs = spawnJobs };
        var spawnFocus = spawnNode.World.CreateEntity();
        spawnNode.World.AddComponent(spawnFocus, new MyFirstCubitProject.PlayerMotionState
        {
            Position = new Vector3(10f, 5f, -4f),
        });
        spawnNode.AddSystem(new MyFirstCubitProject.ProjectEntityInterestSystem(
            spawnFocus,
            new Vector3(16f, 16f, 16f),
            trackedRadius: 2,
            tickingRadius: 1));
        var spawnPolicy = new MyFirstCubitProject.ProjectMonsterSpawnPolicy(
            MonsterId: 99,
            MaximumCount: 2,
            IntervalSeconds: 0.1f,
            SpawnRadius: 4f,
            MinimumDistance: 2f,
            LifetimeSeconds: 30f,
            MaxPlacementAttempts: 16);
        static bool AcceptMonsterSpawnPosition(Vector3 candidate, out Vector3 resolved)
        {
            resolved = candidate;
            return true;
        }

        MyFirstCubitProject.ProjectMonsterSpawnPositionResolver acceptResolver = AcceptMonsterSpawnPosition;
        var spawnSystem = new MyFirstCubitProject.ProjectMonsterSpawnSystem(
            spawnFocus,
            spawnPolicy,
            acceptResolver,
            seed: 123u);
        spawnNode.AddSystem(spawnSystem);
        var presentationSystem = new MyFirstCubitProject.ProjectMonsterPresentationSystem();
        spawnNode.AddSystem(presentationSystem);
        Check("Monster 表现 System 保留主线程 RenderPrepare 边界",
            presentationSystem.Descriptor.RequiresMainThread &&
            presentationSystem.Descriptor.Phase == EcsSystemPhase.RenderPrepare,
            $"phase={presentationSystem.Descriptor.Phase} requiresMainThread={presentationSystem.Descriptor.RequiresMainThread}");
        spawnTree.Root.AddChild(spawnNode);
        spawnTree.ProcessFrame(0.11d);
        var spawnedAfterFirstInterval = spawnNode.World.Query<MyFirstCubitProject.ProjectMonsterState>().Count;
        Check("Monster 生成按间隔创建一个 ECS Entity", spawnedAfterFirstInterval == 1,
            $"count={spawnedAfterFirstInterval}");
        Check("Monster RenderPrepare 输出可见批量快照",
            presentationSystem.VisibleMonsters.Count == spawnedAfterFirstInterval,
            $"visible={presentationSystem.VisibleMonsters.Count}");
        var spawnedPositions = new List<Vector3>();
        foreach (var item in spawnNode.World.Query<
            MyFirstCubitProject.ProjectMonsterState,
            MyFirstCubitProject.ProjectEntitySpatialState>())
        {
            spawnedPositions.Add(item.Component2.Position);
        }
        var firstDistance = spawnedPositions.Count == 1
            ? Vector3.Distance(spawnedPositions[0], new Vector3(10f, 5f, -4f))
            : 0f;
        Check("Monster 生成位置遵守半径和最小距离", spawnedPositions.Count == 1 &&
            firstDistance >= spawnPolicy.MinimumDistance && firstDistance <= spawnPolicy.SpawnRadius,
            $"distance={firstDistance:F3}");
        spawnTree.ProcessFrame(0.11d);
        var spawnedAtLimit = spawnNode.World.Query<MyFirstCubitProject.ProjectMonsterState>().Count;
        Check("Monster 生成遵守数量上限", spawnedAtLimit == spawnPolicy.MaximumCount,
            $"count={spawnedAtLimit}");
        spawnTree.ProcessFrame(0.5d);
        var spawnedAfterLimit = spawnNode.World.Query<MyFirstCubitProject.ProjectMonsterState>().Count;
        Check("Monster 达到数量上限后不继续创建", spawnedAfterLimit == spawnPolicy.MaximumCount,
            $"count={spawnedAfterLimit}");

        var voxelWorld = new VoxelWorld(20260808u, WorldType.Flat);
        voxelWorld.GenerateChunkAt(0, 0);
        var voxelResolver = new MyFirstCubitProject.ProjectVoxelMonsterSpawnPositionResolver(voxelWorld);
        var loadedPosition = voxelResolver.TryResolve(
            new Vector3(2.5f, 100f, 2.5f),
            out var groundedPosition);
        var unloadedPosition = voxelResolver.TryResolve(
            new Vector3(32.5f, 100f, 2.5f),
            out _);
        Check("Voxel Monster 生成验证器返回已加载地表上方位置",
            loadedPosition && groundedPosition == new Vector3(2.5f, 5f, 2.5f),
            $"resolved={loadedPosition} position={groundedPosition}");
        Check("Voxel Monster 生成验证器拒绝未加载区块",
            !unloadedPosition,
            $"resolved={unloadedPosition}");

        using var pathJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var pathTree = new SceneTree();
        var pathNode = new EcsNode { Name = "MonsterPathEcs", Jobs = pathJobs };
        var pathFocus = pathNode.World.CreateEntity();
        pathNode.World.AddComponent(pathFocus, new MyFirstCubitProject.PlayerMotionState
        {
            Position = new Vector3(2.5f, 1f, 0.5f),
        });
        pathNode.AddSystem(new MyFirstCubitProject.ProjectEntityInterestSystem(
            pathFocus,
            new Vector3(16f, 16f, 16f),
            trackedRadius: 1,
            tickingRadius: 1));
        var pathMonster = MyFirstCubitProject.ProjectMonsterFactory.Spawn(
            pathNode.World,
            new Vector3(0.5f, 1f, 0.5f),
            Vector3.Zero,
            monsterId: 100,
            lifetimeSeconds: 30f);
        pathNode.World.AddComponent(pathMonster, new MyFirstCubitProject.ProjectMonsterAiState
        {
            DetectionRadius = 16f,
            FollowSpeed = 4f,
        });
        MyFirstCubitProject.ProjectMonsterAttackFactory.Configure(
            pathNode.World,
            pathMonster,
            attackRange: 3f,
            damage: 3f,
            cooldownSeconds: 0.2f);
        var navigationQuery = new TestMonsterNavigationQuery([(1, 0)]);
        var pathPolicy = new MyFirstCubitProject.ProjectMonsterPathPolicy(
            SearchRadius: 4,
            RepathIntervalSeconds: 1f,
            MaxStepHeight: 1);
        var pathSystem = new MyFirstCubitProject.ProjectMonsterPathSystem(
            pathFocus,
            navigationQuery,
            pathPolicy);
        pathNode.AddSystem(new MyFirstCubitProject.ProjectMonsterAiSystem(pathFocus));
        pathNode.AddSystem(pathSystem);
        var attackSystem = new MyFirstCubitProject.ProjectMonsterAttackSystem(pathFocus);
        pathNode.AddSystem(attackSystem);
        var attackDamageSystem = new MyFirstCubitProject.ProjectMonsterAttackDamageSystem(attackSystem);
        pathNode.AddSystem(attackDamageSystem);
        var deathSystem = new MyFirstCubitProject.ProjectHealthDeathSystem();
        pathNode.AddSystem(deathSystem);
        Check("Monster 攻击/伤害/死亡 System 保持职责与线程边界",
            attackSystem.Descriptor.RequiresMainThread &&
            attackDamageSystem.Descriptor.RequiresMainThread &&
            deathSystem.Descriptor.StructuralChanges &&
            !deathSystem.Descriptor.RequiresMainThread,
            $"attackMain={attackSystem.Descriptor.RequiresMainThread} damageMain={attackDamageSystem.Descriptor.RequiresMainThread} deathStructural={deathSystem.Descriptor.StructuralChanges}");
        var targetBinding = MyFirstCubitProject.ProjectCombatEntityBinding.Attach(
            pathNode.World,
            pathFocus,
            maximumHealth: 10f,
            despawnWhenDead: false);
        Check("动态 Combat 绑定挂载健康组件但不接管玩家 Entity",
            targetBinding.IsAttached &&
            pathNode.World.HasComponent<MyFirstCubitProject.ProjectHealthState>(pathFocus) &&
            !pathNode.World.HasComponent<MyFirstCubitProject.ProjectHealthDespawnState>(pathFocus),
            $"attached={targetBinding.IsAttached}");
        var monsterBinding = MyFirstCubitProject.ProjectCombatEntityBinding.Attach(
            pathNode.World,
            pathMonster,
            maximumHealth: 1f,
            despawnWhenDead: true);
        Check("动态 Combat 绑定可为 Monster 启用死亡回收标记",
            monsterBinding.IsAttached &&
            pathNode.World.HasComponent<MyFirstCubitProject.ProjectHealthDespawnState>(pathMonster),
            $"attached={monsterBinding.IsAttached}");
        Check("Monster 路径 System 是有界纯数据 System",
            !pathSystem.Descriptor.RequiresMainThread && !pathSystem.Descriptor.StructuralChanges,
            $"requiresMainThread={pathSystem.Descriptor.RequiresMainThread} structural={pathSystem.Descriptor.StructuralChanges}");
        pathTree.Root.AddChild(pathNode);
        pathTree.ProcessFrame(0.05d);
        var pathState = pathNode.World.GetComponent<MyFirstCubitProject.ProjectMonsterPathState>(pathMonster);
        var pathMonsterState = pathNode.World.GetComponent<MyFirstCubitProject.ProjectMonsterState>(pathMonster);
        Check("Monster 寻路绕开阻挡格生成首个路径点",
            pathState.HasWaypoint && pathState.Waypoint.Z > 1f &&
            MathF.Abs(pathMonsterState.Velocity.X) < 0.001f && pathMonsterState.Velocity.Z > 0f,
            $"waypoint={pathState.Waypoint} velocity={pathMonsterState.Velocity}");
        var reachedWaypoint = pathState.Waypoint;
        pathNode.World.GetComponent<MyFirstCubitProject.ProjectEntitySpatialState>(pathMonster).Position = reachedWaypoint;
        pathTree.ProcessFrame(0.05d);
        var nextPathState = pathNode.World.GetComponent<MyFirstCubitProject.ProjectMonsterPathState>(pathMonster);
        var nextPathMonsterState = pathNode.World.GetComponent<MyFirstCubitProject.ProjectMonsterState>(pathMonster);
        Check("Monster 到达路径点后立即规划下一格",
            nextPathState.HasWaypoint && nextPathState.Waypoint != reachedWaypoint &&
            nextPathMonsterState.Velocity.LengthSquared() > 0.01f,
            $"previous={reachedWaypoint} next={nextPathState.Waypoint} velocity={nextPathMonsterState.Velocity}");
        var healthAfterAttack = pathNode.World.GetComponent<MyFirstCubitProject.ProjectHealthState>(pathFocus);
        Check("Monster 攻击命中后消费伤害事件", Math.Abs(healthAfterAttack.Current - 7f) < 0.001f,
            $"health={healthAfterAttack.Current}");
        pathTree.ProcessFrame(0.05d);
        var healthDuringCooldown = pathNode.World.GetComponent<MyFirstCubitProject.ProjectHealthState>(pathFocus);
        Check("Monster 攻击冷却期间不重复造成伤害", Math.Abs(healthDuringCooldown.Current - 7f) < 0.001f,
            $"health={healthDuringCooldown.Current}");
        pathTree.ProcessFrame(0.2d);
        var healthAfterSecondAttack = pathNode.World.GetComponent<MyFirstCubitProject.ProjectHealthState>(pathFocus);
        Check("Monster 冷却结束后再次攻击", Math.Abs(healthAfterSecondAttack.Current - 4f) < 0.001f,
            $"health={healthAfterSecondAttack.Current}");
        pathTree.ProcessFrame(0.25d);
        pathTree.ProcessFrame(0.25d);
        Check("零生命玩家目标保留 Entity 供项目流程处理", pathNode.World.IsAlive(pathFocus),
            $"targetAlive={pathNode.World.IsAlive(pathFocus)}");
        pathNode.World.GetComponent<MyFirstCubitProject.ProjectHealthState>(pathMonster).Current = 0f;
        pathTree.ProcessFrame(0.05d);
        Check("零生命 Monster 通过 CommandBuffer 回收", !pathNode.World.IsAlive(pathMonster),
            $"monsterAlive={pathNode.World.IsAlive(pathMonster)}");
        targetBinding.Dispose();
        monsterBinding.Dispose();
        Check("动态 Combat 绑定在 Entity 已销毁后可幂等解绑", !targetBinding.IsAttached,
            $"attached={targetBinding.IsAttached}");

        using var deathJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var deathTree = new SceneTree();
        var deathNode = new EcsNode { Name = "PlayerDeathEcs", Jobs = deathJobs };
        var deathPlayer = deathNode.World.CreateEntity();
        deathNode.World.AddComponent(deathPlayer, new MyFirstCubitProject.PlayerMotionState());
        deathNode.World.AddComponent(deathPlayer, MyFirstCubitProject.ProjectHealthState.Create(2f));
        deathNode.World.AddComponent(deathPlayer, new MyFirstCubitProject.ProjectPlayerDeathState());
        var playerDeathSystem = new MyFirstCubitProject.ProjectPlayerDeathSystem(deathPlayer);
        deathNode.AddSystem(playerDeathSystem);
        Check("玩家死亡 System 不要求主线程且不做结构销毁",
            !playerDeathSystem.Descriptor.RequiresMainThread && !playerDeathSystem.Descriptor.StructuralChanges,
            $"main={playerDeathSystem.Descriptor.RequiresMainThread} structural={playerDeathSystem.Descriptor.StructuralChanges}");
        deathTree.Root.AddChild(deathNode);
        deathTree.ProcessFrame(0.05d);
        deathNode.World.GetComponent<MyFirstCubitProject.ProjectHealthState>(deathPlayer).Current = 0f;
        deathTree.ProcessFrame(0.05d);
        var deathEvents = playerDeathSystem.ConsumeDeaths();
        var deathState = deathNode.World.GetComponent<MyFirstCubitProject.ProjectPlayerDeathState>(deathPlayer);
        Check("玩家生命归零只生成一次死亡事件且保留 Entity",
            deathState.IsDead && deathEvents.Count == 1 && deathEvents[0].PlayerEntity == deathPlayer &&
            deathNode.World.IsAlive(deathPlayer),
            $"dead={deathState.IsDead} events={deathEvents.Count} alive={deathNode.World.IsAlive(deathPlayer)}");
        deathTree.ProcessFrame(0.05d);
        Check("玩家死亡事件消费后不会重复发送",
            playerDeathSystem.ConsumeDeaths().Count == 0,
            "events=0");
        var saveCheckpoint = new MyFirstCubitProject.PlayerEntitySnapshot(
            new Vector3(8f, 2f, 8f),
            new Vector3(1f, 0f, 0f),
            true,
            0);
        deathNode.World.GetComponent<MyFirstCubitProject.PlayerMotionState>(deathPlayer) = saveCheckpoint.ToMotion();
        Check("玩家死亡状态不改变独立存档快照格式", MyFirstCubitProject.PlayerEntitySnapshot.Decode(
                MyFirstCubitProject.PlayerEntitySnapshot.Encode(saveCheckpoint)) == saveCheckpoint,
            saveCheckpoint.ToString());

        using var multiTargetJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var multiTargetTree = new SceneTree();
        var multiTargetNode = new EcsNode { Name = "MonsterMultiTargetEcs", Jobs = multiTargetJobs };
        var multiFocus = multiTargetNode.World.CreateEntity();
        multiTargetNode.World.AddComponent(multiFocus, new MyFirstCubitProject.PlayerMotionState
        {
            Position = new Vector3(8f, 1f, 0f),
        });
        var alternateTarget = multiTargetNode.World.CreateEntity();
        multiTargetNode.World.AddComponent(alternateTarget, new MyFirstCubitProject.ProjectEntitySpatialState
        {
            Position = new Vector3(2f, 1f, 0f),
        });
        var multiMonster = MyFirstCubitProject.ProjectMonsterFactory.Spawn(
            multiTargetNode.World,
            Vector3.Zero,
            Vector3.Zero,
            monsterId: 101,
            lifetimeSeconds: 30f);
        multiTargetNode.World.AddComponent(multiMonster, new MyFirstCubitProject.ProjectMonsterAiState
        {
            DetectionRadius = 16f,
            FollowSpeed = 4f,
        });
        var targetRegistry = new MyFirstCubitProject.ProjectMonsterTargetRegistry(multiFocus);
        targetRegistry.Register(alternateTarget);
        var multiAi = new MyFirstCubitProject.ProjectMonsterAiSystem(multiFocus, targetRegistry);
        multiTargetNode.World.AddComponent(
            alternateTarget,
            MyFirstCubitProject.ProjectHealthState.Create(10f));
        MyFirstCubitProject.ProjectMonsterAttackFactory.Configure(
            multiTargetNode.World,
            multiMonster,
            attackRange: 3f,
            damage: 2f,
            cooldownSeconds: 1f);
        var multiAttack = new MyFirstCubitProject.ProjectMonsterAttackSystem(multiFocus, targetRegistry);
        multiTargetNode.AddSystem(multiAttack);
        multiTargetNode.AddSystem(new MyFirstCubitProject.ProjectMonsterAttackDamageSystem(multiAttack));
        multiTargetNode.AddSystem(new MyFirstCubitProject.ProjectEntityInterestSystem(
            multiFocus,
            new Vector3(16f, 16f, 16f),
            trackedRadius: 1,
            tickingRadius: 1));
        multiTargetNode.AddSystem(multiAi);
        multiTargetTree.Root.AddChild(multiTargetNode);
        multiTargetTree.ProcessFrame(0.05d);
        var selectedTarget = multiTargetNode.World.GetComponent<MyFirstCubitProject.ProjectMonsterAiState>(multiMonster).TargetEntity;
        Check("Monster 多目标 AI 选择最近动态目标", selectedTarget == alternateTarget,
            $"selected={selectedTarget} alternate={alternateTarget}");
        var alternateHealth = multiTargetNode.World.GetComponent<MyFirstCubitProject.ProjectHealthState>(alternateTarget);
        Check("Monster 多目标攻击伤害 AI 选中的动态目标", Math.Abs(alternateHealth.Current - 8f) < 0.001f,
            $"alternateHealth={alternateHealth.Current:F3}");
        targetRegistry.Unregister(alternateTarget);
        multiTargetTree.ProcessFrame(0.05d);
        selectedTarget = multiTargetNode.World.GetComponent<MyFirstCubitProject.ProjectMonsterAiState>(multiMonster).TargetEntity;
        Check("Monster 目标解绑后回退到玩家焦点", selectedTarget == multiFocus,
            $"selected={selectedTarget} focus={multiFocus}");
    }
    catch (Exception exception)
    {
        Check("项目 Monster fixture 执行", false, exception.ToString());
    }

    Console.WriteLine(failures == 0
        ? "projectmonstercheck 全部通过"
        : $"projectmonstercheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectCombatTargetFeatureCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var assembly = typeof(MyFirstCubitProject.WorldRepository).Assembly;
    var featureType = assembly.GetType("MyFirstCubitProject.ProjectCombatSystemsNode");
    var damageResolverType = assembly.GetType("MyFirstCubitProject.IProjectProjectileDamageResolver");
    Check("项目提供显式 Combat feature Node", featureType is not null, featureType?.FullName ?? "missing");
    Check(
        "Combat feature Node 暴露目标 registry",
        featureType?.GetProperty("CombatTargets") is not null,
        "CombatTargets");
    Check(
        "Combat feature Node 暴露可选 ProjectileDamage System",
        featureType?.GetProperty("ProjectileDamageSystem") is not null,
        "ProjectileDamageSystem");
    Check(
        "Combat feature Node 接收引擎上下文",
        featureType?.GetInterface("Cubit.Core.Plugins.IEngineContextConsumer") is not null,
        string.Join(',', featureType?.GetInterfaces().Select(type => type.FullName) ?? []));
    Check("项目提供资产驱动 Projectile 伤害解析契约", damageResolverType is not null, damageResolverType?.FullName ?? "missing");

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null
        ? null
        : Directory.GetParent(repositoryRoot)?.FullName;
    var bridgePath = workspaceRoot is null
        ? string.Empty
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "PlayerEcsBridgeNode.cs");
    var scenePath = workspaceRoot is null
        ? string.Empty
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "scenes", "gameplay.cscene");
    var playerScenePath = workspaceRoot is null
        ? string.Empty
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "scenes", "entities", "player.cscene");
    var bridgeSource = File.Exists(bridgePath) ? File.ReadAllText(bridgePath) : string.Empty;
    var sceneSource = string.Join(
        Environment.NewLine,
        File.Exists(scenePath) ? File.ReadAllText(scenePath) : string.Empty,
        File.Exists(playerScenePath) ? File.ReadAllText(playerScenePath) : string.Empty);
    var damageAssetPath = workspaceRoot is null
        ? string.Empty
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "assets", "gameplay", "projectile-damage.json");
    Check(
        "玩家桥接不直接拥有 Combat target registry",
        !bridgeSource.Contains("new ProjectCombatTargetRegistry(", StringComparison.Ordinal),
        bridgePath);
    Check(
        "正式 gameplay 显式声明 Combat feature",
        sceneSource.Contains("MyFirstCubitProject.ProjectCombatSystemsNode", StringComparison.Ordinal),
        scenePath);
    Check(
        "正式 gameplay 显式启用 Projectile 伤害",
        sceneSource.Contains("EnableProjectileDamage", StringComparison.Ordinal) &&
        File.Exists(damageAssetPath),
        damageAssetPath);

    if (featureType is not null && workspaceRoot is not null)
    {
        try
        {
            using var session = CreateVoxelProjectSession(
                new FakeRenderBackend(),
                20260808u,
                workerCount: 1,
                worldType: WorldType.Flat);
            var feature = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs/CombatSystems")
                as MyFirstCubitProject.ProjectCombatSystemsNode;
            var resolver = session.Scene.Runtime.Context
                .GetRequiredService<MyFirstCubitProject.IProjectProjectileDamageResolver>();
            Check(
                "项目 Runtime 从资产注入 Projectile 伤害 resolver",
                resolver.Resolve(7) == 3f && resolver.Resolve(65535) == 0f,
                $"id7={resolver.Resolve(7):F1} unknown={resolver.Resolve(65535):F1}");
            Check(
                "正式 Combat feature 注册 ProjectileDamage System",
                feature?.EnableProjectileDamage == true && feature.ProjectileDamageSystem is not null &&
                feature.ProjectileDamageSystem.Descriptor.RequiresMainThread,
                $"enabled={feature?.EnableProjectileDamage} system={feature?.ProjectileDamageSystem is not null} " +
                $"main={feature?.ProjectileDamageSystem?.Descriptor.RequiresMainThread}");
        }
        catch (Exception exception)
        {
            Check("Combat feature 真实场景加载", false, exception.ToString());
        }
    }

    Console.WriteLine(failures == 0
        ? "projectcombattargetfeaturecheck 全部通过"
        : $"projectcombattargetfeaturecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

