        File.Exists(playerScenePath) ? File.ReadAllText(playerScenePath) : string.Empty);
    Check(
        "玩家桥接不直接安装 Player Death System",
        !bridgeSource.Contains("new ProjectPlayerDeathSystem(", StringComparison.Ordinal),
        bridgePath);
    Check(
        "正式 gameplay 显式声明 Player Death feature",
        sceneSource.Contains("MyFirstCubitProject.ProjectPlayerDeathSystemsNode", StringComparison.Ordinal),
        scenePath);

    if (featureType is not null && workspaceRoot is not null)
    {
        using var session = CreateVoxelProjectSession(
            new FakeRenderBackend(),
            20260808u,
            workerCount: 1,
            worldType: WorldType.Flat);
        var bridge = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs")
            as MyFirstCubitProject.PlayerEcsBridgeNode;
        var feature = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs/PlayerDeathSystems")
            as MyFirstCubitProject.ProjectPlayerDeathSystemsNode;
        var world = bridge?.EcsWorld;
        Check(
            "Player Death feature 注册到玩家共享 EcsWorld",
            bridge is not null && feature is not null && feature.Enabled &&
            feature.PlayerDeathSystem is not null && ReferenceEquals(world, feature.EcsWorld) &&
            world!.HasComponent<MyFirstCubitProject.ProjectHealthState>(bridge.PlayerEntity) &&
            world.HasComponent<MyFirstCubitProject.ProjectPlayerDeathState>(bridge.PlayerEntity),
            $"feature={feature is not null} enabled={feature?.Enabled} system={feature?.PlayerDeathSystem is not null} " +
            $"shared={ReferenceEquals(world, feature?.EcsWorld)} health={world?.HasComponent<MyFirstCubitProject.ProjectHealthState>(bridge?.PlayerEntity ?? default)}");
        Check(
            "Player Death feature 保留非主线程非结构销毁边界",
            feature?.PlayerDeathSystem?.Descriptor.RequiresMainThread == false &&
            feature.PlayerDeathSystem.Descriptor.StructuralChanges == false,
            $"main={feature?.PlayerDeathSystem?.Descriptor.RequiresMainThread} structural={feature?.PlayerDeathSystem?.Descriptor.StructuralChanges}");
        session.Scene.Tree.Paused = false;
        bridge?.SetGameplayActive(true);
        if (bridge is not null && world is not null)
        {
            world.GetComponent<MyFirstCubitProject.ProjectHealthState>(bridge.PlayerEntity).Current = 0f;
            session.Scene.ProcessFrame(0.05d);
            var death = world.GetComponent<MyFirstCubitProject.ProjectPlayerDeathState>(bridge.PlayerEntity);
            var menu = session.Scene.Tree.GetNode("/Root/SingleplayerMenu")
                as MyFirstCubitProject.SingleplayerMenuController;
            Check(
                "玩家生命归零发布死亡状态并保留 Entity",
                death.IsDead && world.IsAlive(bridge.PlayerEntity) &&
                (menu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.Death ||
                 feature?.PlayerDeathSystem?.ConsumeDeaths().Count == 1),
                $"dead={death.IsDead} alive={world.IsAlive(bridge.PlayerEntity)} screen={menu?.State.Screen}");
        }
    }

    Console.WriteLine(failures == 0
        ? "projectplayerdeathfeaturecheck 全部通过"
        : $"projectplayerdeathfeaturecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

