        File.Exists(playerScenePath) ? File.ReadAllText(playerScenePath) : string.Empty);
    Check(
        "玩家桥接不直接安装 Projectile lifetime System",
        !bridgeSource.Contains("new ProjectProjectileSystem(", StringComparison.Ordinal),
        bridgePath);
    Check(
        "玩家桥接不直接安装 Projectile collision System",
        !bridgeSource.Contains("new ProjectProjectileCollisionSystem(", StringComparison.Ordinal),
        bridgePath);
    Check(
        "玩家桥接不直接安装 Projectile 表现 System",
        !bridgeSource.Contains("new ProjectProjectilePresentationSystem(", StringComparison.Ordinal),
        bridgePath);
    Check(
        "正式 gameplay 显式声明 Projectile feature",
        sceneSource.Contains("MyFirstCubitProject.ProjectProjectileSystemsNode", StringComparison.Ordinal),
        $"{scenePath}; {playerScenePath}");

