            new FakeRenderBackend(),
            20260808u,
            workerCount: 1,
            worldType: WorldType.Flat);
        var bridge = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs")
            as MyFirstCubitProject.PlayerEcsBridgeNode;
        var feature = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs/ProjectileSystems")
            as MyFirstCubitProject.ProjectProjectileSystemsNode;
        var bridgeWorld = bridge?.EcsWorld;
        Check(
            "Projectile feature 注册到玩家共享 EcsWorld",
            bridge is not null && feature is not null &&
            feature.ProjectileSystem is not null && feature.ProjectileCollisionSystem is not null &&
            feature.ProjectilePresentationSystem is not null &&
            ReferenceEquals(bridgeWorld, feature.EcsWorld),
            $"feature={feature is not null} lifetime={feature?.ProjectileSystem is not null} " +
            $"collision={feature?.ProjectileCollisionSystem is not null} presentation={feature?.ProjectilePresentationSystem is not null} " +
            $"shared={ReferenceEquals(bridgeWorld, feature?.EcsWorld)}");
        Check(
            "Projectile feature 保留 worker/Physics/RenderPrepare 边界",
            feature?.ProjectileSystem?.Descriptor.RequiresMainThread == false &&
            feature.ProjectileCollisionSystem?.Descriptor.RequiresMainThread == true &&
            feature.ProjectilePresentationSystem?.Descriptor.RequiresMainThread == true &&
            feature.ProjectilePresentationSystem?.Descriptor.Phase == EcsSystemPhase.RenderPrepare,
            $"lifetimeMain={feature?.ProjectileSystem?.Descriptor.RequiresMainThread} " +
            $"collisionMain={feature?.ProjectileCollisionSystem?.Descriptor.RequiresMainThread} " +
            $"presentationPhase={feature?.ProjectilePresentationSystem?.Descriptor.Phase}");
        session.Scene.Tree.Paused = false;
        bridge?.SetGameplayActive(true);
        var projectile = bridge?.SpawnProjectile(
            bridge.ReadMotionState().Position + new Vector3(2f, 1f, 0f),
            Vector3.Zero,
            projectileId: 7,
            lifetimeSeconds: 30f) ?? default;
        session.Scene.ProcessFrame(0.05d);
        Check(
            "Projectile feature 驱动固定步和 RenderPrepare 快照",
            bridgeWorld?.IsAlive(projectile) == true &&
            feature?.ProjectilePresentationSystem?.VisibleProjectiles.Any(item => item.Entity == projectile) == true,
            $"alive={bridgeWorld?.IsAlive(projectile)} visible={feature?.ProjectilePresentationSystem?.VisibleProjectiles.Count}");
    }

    Console.WriteLine(failures == 0
        ? "projectprojectilefeaturecheck 全部通过"
        : $"projectprojectilefeaturecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

