    var sceneSource = string.Join(
        Environment.NewLine,
        File.Exists(scenePath) ? File.ReadAllText(scenePath) : string.Empty,
        File.Exists(playerScenePath) ? File.ReadAllText(playerScenePath) : string.Empty);
    Check(
        "玩家桥接不直接安装 ItemDrop lifetime System",
        !bridgeSource.Contains("new ProjectItemDropSystem(", StringComparison.Ordinal),
        bridgePath);
    Check(
        "玩家桥接不直接安装 ItemDrop 表现 System",
        !bridgeSource.Contains("new ProjectItemDropPresentationSystem(", StringComparison.Ordinal),
        bridgePath);
    Check(
        "正式 gameplay 显式声明 ItemDrop feature",
        sceneSource.Contains("MyFirstCubitProject.ProjectItemDropSystemsNode", StringComparison.Ordinal),
        $"{scenePath}; {playerScenePath}");

    if (featureType is not null && workspaceRoot is not null)
    {
        using var session = CreateVoxelProjectSession(
            new FakeRenderBackend(),
            20260808u,
            workerCount: 1,
            worldType: WorldType.Flat);
        var bridge = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs")
            as MyFirstCubitProject.PlayerEcsBridgeNode;
        var feature = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs/ItemDropSystems")
            as MyFirstCubitProject.ProjectItemDropSystemsNode;
        var bridgeWorld = bridge?.EcsWorld;
        Check(
            "ItemDrop feature 注册到玩家共享 EcsWorld",
            bridge is not null && feature is not null &&
            feature.ItemDropSystem is not null && feature.ItemDropPresentationSystem is not null &&
            ReferenceEquals(bridgeWorld, feature.EcsWorld),
            $"feature={feature is not null} lifetime={feature?.ItemDropSystem is not null} " +
            $"presentation={feature?.ItemDropPresentationSystem is not null} shared={ReferenceEquals(bridgeWorld, feature?.EcsWorld)}");
        session.Scene.Tree.Paused = false;
        bridge?.SetGameplayActive(true);
        var drop = bridge?.SpawnItemDrop(
            bridge.ReadMotionState().Position + new Vector3(2f, 0f, 0f),
            itemId: 7,
            count: 1,
            lifetimeSeconds: 30f) ?? default;
        session.Scene.ProcessFrame(0.05d);
        Check(
            "ItemDrop feature 驱动固定步和 RenderPrepare 快照",
            bridgeWorld?.IsAlive(drop) == true &&
            feature?.ItemDropPresentationSystem?.VisibleDrops.Any(item => item.Entity == drop) == true,
            $"alive={bridgeWorld?.IsAlive(drop)} visible={feature?.ItemDropPresentationSystem?.VisibleDrops.Count}");
    }

    Console.WriteLine(failures == 0
        ? "projectitemdropfeaturecheck 全部通过"
        : $"projectitemdropfeaturecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectMonsterFeatureCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var assembly = typeof(MyFirstCubitProject.WorldRepository).Assembly;
    var featureType = assembly.GetType("MyFirstCubitProject.ProjectMonsterSystemsNode");
    Check("项目提供显式 Monster feature Node", featureType is not null, featureType?.FullName ?? "missing");
    Check(
        "Monster feature Node 暴露 System 诊断属性",
        featureType?.GetProperty("MonsterSystem") is not null &&
        featureType.GetProperty("MonsterAiSystem") is not null &&
        featureType.GetProperty("MonsterPresentationSystem") is not null,
        "MonsterSystem/MonsterAiSystem/MonsterPresentationSystem");

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null
        ? null
        : Directory.GetParent(repositoryRoot)?.FullName;
    var bridgePath = workspaceRoot is null
        ? string.Empty
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "PlayerEcsBridgeNode.cs");
    var bridgeSource = File.Exists(bridgePath) ? File.ReadAllText(bridgePath) : string.Empty;
    Check(
        "玩家桥接不直接安装 Monster lifetime System",
        !bridgeSource.Contains("new ProjectMonsterSystem(", StringComparison.Ordinal),
        bridgePath);
    Check(
        "玩家桥接不直接安装 Monster AI System",
        !bridgeSource.Contains("new ProjectMonsterAiSystem(", StringComparison.Ordinal),
        bridgePath);
    Check(
        "玩家桥接不直接安装 Monster 表现 System",
        !bridgeSource.Contains("new ProjectMonsterPresentationSystem(", StringComparison.Ordinal),
        bridgePath);

    if (repositoryRoot is not null && workspaceRoot is not null && featureType is not null)
    {
        var sourceProjectRoot = Path.Combine(workspaceRoot, "我的第一个cubit项目");
        var sourceManifestPath = Path.Combine(sourceProjectRoot, ProjectIO.ManifestFileName);
        var sourceScenePath = Path.Combine(sourceProjectRoot, "scenes", "gameplay.cscene");
        var noFeatureSession = CreateVoxelProjectSession(
            new FakeRenderBackend(),
            20260808u,
            workerCount: 1,
            worldType: WorldType.Flat,
            projectRootOverride: sourceProjectRoot);
        try
        {
            var noFeatureBridge = noFeatureSession.Scene.Tree.GetNode("/Root/Physics/PlayerEcs")
                as MyFirstCubitProject.PlayerEcsBridgeNode;
            Check(
                "正式 gameplay 场景不声明 Monster feature",
                noFeatureBridge is not null && noFeatureBridge.MonsterSystem is null,
                $"feature={noFeatureBridge?.MonsterSystem is not null}");

            MyFirstCubitProject.ProjectMonsterSpawnPositionResolver acceptsPosition =
                static (Vector3 candidate, out Vector3 resolved) =>
                {
                    resolved = candidate;
                    return true;
                };
            var spawnError = CaptureException(() => noFeatureBridge!.ConfigureMonsterSpawning(
                new MyFirstCubitProject.ProjectMonsterSpawnPolicy(1, 1, 1f, 2f, 0.5f, 10f, 4),
                acceptsPosition));
            Check(
                "缺少 Monster feature 时配置调用失败且不创建回退节点",
                spawnError is InvalidOperationException &&
                spawnError.Message.Contains("ProjectMonsterSystemsNode", StringComparison.Ordinal),
                spawnError?.Message ?? "none");
        }
        finally
        {
            noFeatureSession.Dispose();
        }

        var featureFixtureRoot = CreateMonsterFeatureFixtureRoot(sourceProjectRoot, sourceManifestPath, sourceScenePath, duplicate: false);
        try
        {
            using var featureSession = CreateVoxelProjectSession(
                new FakeRenderBackend(),
                20260808u,
                workerCount: 1,
                worldType: WorldType.Flat,
                projectRootOverride: featureFixtureRoot);
            var featureBridge = featureSession.Scene.Tree.GetNode("/Root/Physics/PlayerEcs")
                as MyFirstCubitProject.PlayerEcsBridgeNode;
            var feature = featureSession.Scene.Tree.GetNode("/Root/Physics/PlayerEcs/MonsterSystems")
                as MyFirstCubitProject.ProjectMonsterSystemsNode;
            var featureNode = feature
                ?? throw new InvalidOperationException("作者化 Monster feature 节点未加载");
            var featureBridgeNode = featureBridge
                ?? throw new InvalidOperationException("作者化 Monster feature 缺少玩家桥接");
            var sharedWorld = ReferenceEquals(featureNode.EcsWorld, featureBridgeNode.EcsWorld);
            featureSession.Scene.Tree.Paused = false;
            featureBridgeNode.SetGameplayActive(true);
            Check(
                "作者化 Monster feature 注册到玩家共享 EcsWorld",
                featureNode.MonsterSystem is not null && featureNode.MonsterAiSystem is not null &&
                featureNode.MonsterPresentationSystem is not null && sharedWorld,
                $"lifetime={featureNode.MonsterSystem is not null} " +
                $"ai={featureNode.MonsterAiSystem is not null} presentation={featureNode.MonsterPresentationSystem is not null} shared={sharedWorld}");
            Check(
                "Monster feature 保留纯数据与 RenderPrepare 线程边界",
                featureNode.MonsterSystem?.Descriptor.RequiresMainThread == false &&
                featureNode.MonsterPresentationSystem?.Descriptor.RequiresMainThread == true &&
                featureNode.MonsterPresentationSystem?.Descriptor.Phase == EcsSystemPhase.RenderPrepare,
                $"lifetimeMain={featureNode.MonsterSystem?.Descriptor.RequiresMainThread} " +
                $"presentationPhase={featureNode.MonsterPresentationSystem?.Descriptor.Phase}");

            var featureEntity = featureBridgeNode.SpawnMonster(
                featureBridgeNode.ReadMotionState().Position,
                Vector3.Zero,
                monsterId: 1,
                lifetimeSeconds: 30f);
            featureSession.Scene.ProcessFrame(0.05d);
            var featureInterest = featureBridgeNode.EcsWorld!.GetComponent<MyFirstCubitProject.ProjectEntityInterestState>(featureEntity);
            Check(
                "作者化 Monster feature 驱动固定步和表现快照",
                featureBridgeNode.EcsWorld!.IsAlive(featureEntity) &&
                featureNode.MonsterPresentationSystem!.VisibleMonsters.Any(item => item.Entity == featureEntity),
                $"alive={featureBridgeNode.EcsWorld!.IsAlive(featureEntity)} tier={featureInterest.Tier} " +
                $"cell={featureInterest.Cell} visible={featureNode.MonsterPresentationSystem!.VisibleMonsters.Count}");
            var featureWorld = featureBridgeNode.EcsWorld;
            var featurePlayer = featureBridgeNode.PlayerEntity;
            featureSession.Dispose();
            Check(
                "Monster feature 退出后共享玩家 Entity 失效",
                featureWorld is not null && !featureWorld.IsAlive(featurePlayer),
                $"alive={featureWorld?.IsAlive(featurePlayer)}");
        }
        finally
        {
            if (Directory.Exists(featureFixtureRoot))
            {
                Directory.Delete(featureFixtureRoot, recursive: true);
            }
        }

        var duplicateFixtureRoot = CreateMonsterFeatureFixtureRoot(sourceProjectRoot, sourceManifestPath, sourceScenePath, duplicate: true);
        try
        {
            Exception? duplicateError = null;
            try
            {
                using var duplicateSession = CreateVoxelProjectSession(
                    new FakeRenderBackend(),
                    20260808u,
                    workerCount: 1,
                    worldType: WorldType.Flat,
                    projectRootOverride: duplicateFixtureRoot);
            }
            catch (Exception exception)
            {
                duplicateError = exception;
            }

            Check(
                "重复 Monster feature 被作者场景诊断拒绝",
                duplicateError is not null &&
                duplicateError.ToString().Contains("只能作者化一个 ProjectMonsterSystemsNode", StringComparison.Ordinal),
                duplicateError?.Message ?? "none");
        }
        finally
        {
            if (Directory.Exists(duplicateFixtureRoot))
            {
                Directory.Delete(duplicateFixtureRoot, recursive: true);
            }
        }

        static string CreateMonsterFeatureFixtureRoot(
            string sourceProjectRoot,
            string sourceManifestPath,
            string sourceScenePath,
            bool duplicate)
        {
            var fixtureRoot = Path.Combine(Path.GetTempPath(), $"cubit_monster_feature_fixture_{Guid.NewGuid():N}");
            Directory.CreateDirectory(Path.Combine(fixtureRoot, "scenes"));
            File.Copy(sourceManifestPath, Path.Combine(fixtureRoot, ProjectIO.ManifestFileName));
            var scene = JsonNode.Parse(File.ReadAllText(sourceScenePath)) as JsonObject
                ?? throw new InvalidDataException("Monster feature fixture 场景不是 JSON 对象");
            var physics = scene["Children"]?.AsArray()
                .Select(node => node as JsonObject)
                .Single(node => node?["Name"]?.GetValue<string>() == "Physics")
                ?? throw new InvalidDataException("Monster feature fixture 缺少 Physics");
            var bridge = physics["Children"]?.AsArray()
                .Select(node => node as JsonObject)
                .Single(node => node?["Name"]?.GetValue<string>() == "PlayerEcs")
                ?? throw new InvalidDataException("Monster feature fixture 缺少 PlayerEcs");
            var children = bridge["Children"]?.AsArray()
                ?? throw new InvalidDataException("Monster feature fixture 缺少 PlayerEcs 子节点数组");
            children.Add(new JsonObject
            {
                ["Type"] = "MyFirstCubitProject.ProjectMonsterSystemsNode",
                ["Name"] = "MonsterSystems",
            });
            if (duplicate)
            {
                children.Add(new JsonObject
                {
                    ["Type"] = "MyFirstCubitProject.ProjectMonsterSystemsNode",
                    ["Name"] = "MonsterSystemsDuplicate",
                });
            }

            File.WriteAllText(
                Path.Combine(fixtureRoot, "scenes", "gameplay.cscene"),
                scene.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));
            foreach (var sourceScene in Directory.EnumerateFiles(
                         Path.Combine(sourceProjectRoot, "scenes"),
                         "*.cscene"))
            {
                if (string.Equals(Path.GetFileName(sourceScene), "gameplay.cscene", StringComparison.OrdinalIgnoreCase))
                {
                    continue;
                }

                File.Copy(
                    sourceScene,
                    Path.Combine(fixtureRoot, "scenes", Path.GetFileName(sourceScene)),
                    overwrite: true);
            }

            var sourceAssetsRoot = Path.Combine(sourceProjectRoot, "assets");
            if (Directory.Exists(sourceAssetsRoot))
            {
                foreach (var sourceFile in Directory.EnumerateFiles(sourceAssetsRoot, "*", SearchOption.AllDirectories))
                {
                    var relative = Path.GetRelativePath(sourceProjectRoot, sourceFile);
                    var targetFile = Path.Combine(fixtureRoot, relative);
                    Directory.CreateDirectory(Path.GetDirectoryName(targetFile)!);
                    File.Copy(sourceFile, targetFile, overwrite: true);
                }
            }

            return fixtureRoot;
        }
    }

    Console.WriteLine(failures == 0
        ? "projectmonsterfeaturecheck 全部通过"
        : $"projectmonsterfeaturecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelUnloadCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var directory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_unload_{Guid.NewGuid():N}");
    try
    {
        var source = new VoxelWorld(20260808u, WorldType.Flat);
        source.GenerateChunkAt(0, 0);
        source.GenerateChunkAt(2, 2);
        source.GenerateChunkAt(40, 40);
        WorldFile.Save(source, directory);

        var world = WorldFile.Load(directory);
        var changed = world.SetBlockDeferred(2 * Chunk.SizeX, Chunk.MaxYExclusive - 1, 2 * Chunk.SizeZ, BlockRegistry.Stone, out _);
        using var storage = new WorldFileStorage(directory);
        using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var streamer = new ChunkStreamer(world, jobs, storage);
        streamer.RequestArea(0, 0, 0);

        Check(
            "视距变更只登记待保存卸载而不在 RequestArea 同步执行",
            world.Store.ChunkKeys.Length == 3 && world.Store.HasChunk(0, 0) &&
            world.Store.HasChunk(2, 2) && world.Store.HasChunk(40, 40),
            $"chunks={world.Store.ChunkKeys.Length}");

        var unloadDeadline = Stopwatch.StartNew();
        while (unloadDeadline.Elapsed < TimeSpan.FromSeconds(10) && world.Store.ChunkKeys.Length > 1)
        {
            streamer.Pump();
            Thread.Sleep(1);
        }

        Check(
            "持久化 streamer 卸载视距外区块",
            world.Store.ChunkKeys.Length == 1 && world.Store.HasChunk(0, 0),
            $"chunks={world.Store.ChunkKeys.Length}");
        Check(
            "卸载前保存 dirty 区块",
            changed && storage.TryLoadChunk(2, 2, out var persisted) &&
            persisted.Chunk.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == BlockRegistry.Stone);
        Check(
            "卸载不影响远端 region 的其他区块",
            storage.TryLoadChunk(40, 40, out _));

        var transientWorld = new VoxelWorld(20260808u, WorldType.Flat);
        transientWorld.GenerateChunkAt(0, 0);
        transientWorld.GenerateChunkAt(2, 2);
        using var transientJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var transientStreamer = new ChunkStreamer(transientWorld, transientJobs);
        transientStreamer.RequestArea(0, 0, 0);
        Check(
            "无持久化存储的临时 streamer 不静默卸载",
            transientWorld.Store.ChunkKeys.Length == 2,
            $"chunks={transientWorld.Store.ChunkKeys.Length}");

        // Section patch 同样实现 IChunkStorageWriter；流式器不能把可安全保存/卸载
        // 的能力绑死到默认 v4 region 后端，否则换后端后已探索区块会永久滞留内存。
        var patchWorld = WorldFile.Load(directory);
        using var patchStorage = new SectionPatchStorage(directory);
        using var patchJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var patchStreamer = new ChunkStreamer(patchWorld, patchJobs, patchStorage);
        patchStreamer.RequestArea(0, 0, 0);
        var patchUnloadDeadline = Stopwatch.StartNew();
        while (patchUnloadDeadline.Elapsed < TimeSpan.FromSeconds(10) && patchWorld.Store.ChunkKeys.Length > 1)
        {
            patchStreamer.Pump();
            Thread.Sleep(1);
        }

        Check(
            "所有可写区块存储都卸载视距外区块",
            patchWorld.Store.ChunkKeys.Length == 1 && patchWorld.Store.HasChunk(0, 0),
            $"chunks={patchWorld.Store.ChunkKeys.Length}");

        // 写入存储可能受防病毒扫描、慢盘或文件系统 flush 影响。流式 Pump 只能在主线程
        // 复制不可变快照并投递保存，不能直接等待磁盘 I/O 完成。
        var slowWorld = new VoxelWorld(20260808u, WorldType.Flat);
        slowWorld.GenerateChunkAt(0, 0);
        slowWorld.GenerateChunkAt(2, 0);
        var slowChanged = slowWorld.SetBlockDeferred(
            2 * Chunk.SizeX,
            Chunk.MaxYExclusive - 1,
            0,
            BlockRegistry.Stone,
            out _);
        using var slowStorage = new DelayedChunkStorage(TimeSpan.FromMilliseconds(250));
        using var slowJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var slowStreamer = new ChunkStreamer(slowWorld, slowJobs, slowStorage);
        slowStreamer.RequestArea(0, 0, 0);
        var slowPump = Stopwatch.StartNew();
        slowStreamer.Pump();
        slowPump.Stop();
        Check(
            "慢存储写入不阻塞主线程 Pump",
            slowPump.Elapsed < TimeSpan.FromMilliseconds(100),
            $"pumpMs={slowPump.Elapsed.TotalMilliseconds:F1} writeCalls={slowStorage.SaveCalls}");

        var slowUnloadDeadline = Stopwatch.StartNew();
        while (slowUnloadDeadline.Elapsed < TimeSpan.FromSeconds(5) && slowWorld.Store.HasChunk(2, 0))
        {
            slowStreamer.Pump();
            Thread.Sleep(1);
        }

        Check(
            "后台保存完成后才卸载慢存储区块",
            slowChanged && !slowWorld.Store.HasChunk(2, 0) && slowStorage.TryLoadChunk(2, 0, out var slowPersisted) &&
            slowPersisted.Chunk.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == BlockRegistry.Stone,
            $"chunks={slowWorld.Store.ChunkKeys.Length} saves={slowStorage.SaveCalls}");

        // 慢盘期间连续经过多个视距外区块时，保存任务必须有界；否则主线程虽不等待，
        // 仍会在 JobSystem 队列和持久化快照中积压整个已探索区域。
        var backpressureWorld = new VoxelWorld(20260808u, WorldType.Flat);
        backpressureWorld.GenerateChunkAt(0, 0);
        for (var chunkX = 2; chunkX <= 8; chunkX += 2)
        {
            backpressureWorld.GenerateChunkAt(chunkX, 0);
            _ = backpressureWorld.SetBlockDeferred(
                chunkX * Chunk.SizeX,
                Chunk.MaxYExclusive - 1,
                0,
                BlockRegistry.Stone,
                out _);
        }

        using var backpressureStorage = new DelayedChunkStorage(TimeSpan.FromMilliseconds(250));
        using var backpressureJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var backpressureStreamer = new ChunkStreamer(backpressureWorld, backpressureJobs, backpressureStorage);
        backpressureStreamer.RequestArea(0, 0, 0);
        for (var pump = 0; pump < 8; pump++)
        {
            backpressureStreamer.Pump();
        }

        Check(
            "慢存储卸载保存保持有界的任务背压",
            backpressureStreamer.InFlightUnloadSaveCount == 1,
            $"inFlight={backpressureStreamer.InFlightUnloadSaveCount} saves={backpressureStorage.SaveCalls}");

        var changedDuringSaveWorld = new VoxelWorld(20260808u, WorldType.Flat);
        changedDuringSaveWorld.GenerateChunkAt(0, 0);
        changedDuringSaveWorld.GenerateChunkAt(2, 0);
        _ = changedDuringSaveWorld.SetBlockDeferred(
            2 * Chunk.SizeX,
            Chunk.MaxYExclusive - 1,
            0,
            BlockRegistry.Stone,
            out _);
        using var changedDuringSaveStorage = new DelayedChunkStorage(TimeSpan.FromMilliseconds(100));
        using var changedDuringSaveJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var changedDuringSaveStreamer = new ChunkStreamer(
            changedDuringSaveWorld,
            changedDuringSaveJobs,
            changedDuringSaveStorage);
        changedDuringSaveStreamer.RequestArea(0, 0, 0);
        changedDuringSaveStreamer.Pump();
        var firstSaveStarted = changedDuringSaveStorage.WaitForSaveStart(TimeSpan.FromSeconds(1));
        var changedDuringSave = changedDuringSaveWorld.SetBlockDeferred(
            2 * Chunk.SizeX,
            Chunk.MaxYExclusive - 1,
            0,
            BlockRegistry.Dirt,
            out _);
        var changedDuringSaveDeadline = Stopwatch.StartNew();
        while (changedDuringSaveDeadline.Elapsed < TimeSpan.FromSeconds(5) && changedDuringSaveWorld.Store.HasChunk(2, 0))
        {
            changedDuringSaveStreamer.Pump();
            Thread.Sleep(1);
        }

        Check(
            "保存期间编辑会重做快照而不丢失最新方块",
            firstSaveStarted && changedDuringSave && !changedDuringSaveWorld.Store.HasChunk(2, 0) &&
            changedDuringSaveStorage.SaveCalls >= 2 &&
            changedDuringSaveStorage.TryLoadChunk(2, 0, out var changedDuringSavePersisted) &&
            changedDuringSavePersisted.Chunk.GetBlock(0, Chunk.MaxYExclusive - 1, 0) == BlockRegistry.Dirt,
            $"saves={changedDuringSaveStorage.SaveCalls} chunks={changedDuringSaveWorld.Store.ChunkKeys.Length}");

        var failingSaveWorld = new VoxelWorld(20260808u, WorldType.Flat);
        failingSaveWorld.GenerateChunkAt(0, 0);
        failingSaveWorld.GenerateChunkAt(2, 0);
        _ = failingSaveWorld.SetBlockDeferred(
            2 * Chunk.SizeX,
            Chunk.MaxYExclusive - 1,
            0,
            BlockRegistry.Stone,
            out _);
        using var failingSaveStorage = new FailOnceSavingChunkStorage();
        using var failingSaveJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var failingSaveStreamer = new ChunkStreamer(failingSaveWorld, failingSaveJobs, failingSaveStorage);
        failingSaveStreamer.RequestArea(0, 0, 0);
        var failingSaveDeadline = Stopwatch.StartNew();
        while (failingSaveDeadline.Elapsed < TimeSpan.FromSeconds(5) && failingSaveWorld.Store.HasChunk(2, 0))
        {
            failingSaveStreamer.Pump();
            Thread.Sleep(1);
        }

        Check(
            "后台保存失败保留区块并公开重试诊断",
            !failingSaveWorld.Store.HasChunk(2, 0) && failingSaveStorage.SaveCalls >= 2 &&
            failingSaveStreamer.UnloadSaveFailureCount == 1 &&
            !string.IsNullOrWhiteSpace(failingSaveStreamer.LastUnloadSaveFailure) &&
            failingSaveStreamer.CompletedUnloadSaveCount >= 1 &&
            failingSaveStreamer.CompletedUnloadCount >= 1 &&
            failingSaveStreamer.InFlightUnloadSaveCount == 0,
            $"saves={failingSaveStorage.SaveCalls} failures={failingSaveStreamer.UnloadSaveFailureCount} " +
            $"inFlight={failingSaveStreamer.InFlightUnloadSaveCount}");
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  Voxel 视距卸载异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(directory))
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "voxelunloadcheck 全部通过" : $"voxelunloadcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelTicketCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var world = new VoxelWorld(20260808u, WorldType.Flat);
    world.GenerateAround(0, 0, 2);
    var distances = new ChunkTicketDistances(renderRadius: 2, blockTickRadius: 1, entitySimulationRadius: 0);
    world.UpdateTicketLevels(0, 0, distances);
    Check(
        "ticket 分层：中心区块实体模拟",
        world.Store.GetTicketLevel(0, 0) == TicketLevel.EntitySimulation);
    Check(
        "ticket 分层：方块 tick 半径独立于渲染半径",
        world.Store.GetTicketLevel(1, 0) == TicketLevel.BlockTicks);
    Check(
        "ticket 分层：渲染范围外层只保留数据",
        world.Store.GetTicketLevel(2, 0) == TicketLevel.DataOnly);

    var invalidOrder = CaptureException(() => new ChunkTicketDistances(1, 2, 0));
    Check("ticket 半径顺序非法时拒绝", invalidOrder is ArgumentException, invalidOrder?.Message ?? "none");
    var invalidNegative = CaptureException(() => new ChunkTicketDistances(-1, 0, 0));
    Check("ticket 半径为负时拒绝", invalidNegative is ArgumentOutOfRangeException, invalidNegative?.Message ?? "none");

    Console.WriteLine(failures == 0 ? "voxelticketcheck 全部通过" : $"voxelticketcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

