static int VoxelRequestDedupCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var world = new VoxelWorld(20260808u, WorldType.Flat);
    var storage = new FailOnceChunkStorage();
    using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    using var streamer = new ChunkStreamer(world, jobs, storage);

    streamer.RequestArea(0, 0, 0);
    Exception? firstFailure = null;
    var failureDeadline = Stopwatch.StartNew();
    while (failureDeadline.Elapsed < TimeSpan.FromSeconds(5) && firstFailure is null)
    {
        try
        {
            streamer.Pump();
        }
        catch (Exception exception)
        {
            firstFailure = exception;
        }

        if (firstFailure is null)
        {
            Thread.Sleep(2);
        }
    }

    Check("生成存储异常向调用方报告", firstFailure is not null, firstFailure?.GetType().Name ?? "none");

    streamer.RequestArea(0, 0, 0);
    var retryDeadline = Stopwatch.StartNew();
    while (retryDeadline.Elapsed < TimeSpan.FromSeconds(5) && !world.Store.HasChunk(0, 0))
    {
        streamer.Pump();
        Thread.Sleep(2);
    }

    Check(
        "生成失败后同坐标请求可以重新排队",
        world.Store.HasChunk(0, 0),
        $"chunks={world.Store.ChunkKeys.Length} pending={streamer.PendingCount}");

    var generatedBeforeDuplicateRequests = streamer.GeneratedCount;
    streamer.RequestArea(0, 0, 0);
    streamer.RequestArea(0, 0, 0);
    streamer.Pump();
    Check(
        "已加载区块的重复范围请求不会重复生成",
        streamer.GeneratedCount == generatedBeforeDuplicateRequests && world.Store.ChunkKeys.Length == 1,
        $"generated={streamer.GeneratedCount}/{generatedBeforeDuplicateRequests} chunks={world.Store.ChunkKeys.Length}");

    Console.WriteLine(failures == 0 ? "voxelrequestdedupcheck 全部通过" : $"voxelrequestdedupcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelStreamPriorityCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    using var blockerStarted = new ManualResetEventSlim(false);
    using var blockerRelease = new ManualResetEventSlim(false);
    var blocker = jobs.Schedule(_ =>
    {
        blockerStarted.Set();
        blockerRelease.Wait();
    }, "voxel-stream-priority-blocker");
    if (!blockerStarted.Wait(TimeSpan.FromSeconds(5)))
    {
        Check("测试阻塞 Job 已启动", false, "worker 未进入受控等待");
        blockerRelease.Set();
        blocker.Complete();
        return failures == 0 ? 0 : 1;
    }

    var world = new VoxelWorld(20260808u, WorldType.Flat);
    var storage = new RecordingChunkStorage();
    using var streamer = new ChunkStreamer(world, jobs, storage);
    streamer.RequestArea(0, 0, 2);
    streamer.RequestArea(2, 0, 2);
    streamer.Pump();

    blockerRelease.Set();
    blocker.Complete();
    var deadline = Stopwatch.StartNew();
    while (deadline.Elapsed < TimeSpan.FromSeconds(5) && storage.Requests.Count == 0)
    {
        streamer.Pump();
        Thread.Sleep(2);
    }

    var first = storage.Requests.FirstOrDefault();
    Check(
        "快速移动后优先读取最新观察点中心区块",
        storage.Requests.Count > 0 && first == (2, 0),
        $"first=({first.X},{first.Z}) requests={storage.Requests.Count}");

    Console.WriteLine(failures == 0 ? "voxelstreamprioritycheck 全部通过" : $"voxelstreamprioritycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

