static int VoxelCompressionCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var compressedDirectory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_compressed_{Guid.NewGuid():N}");
    var legacyDirectory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_legacy_region_{Guid.NewGuid():N}");
    try
    {
        var world = new VoxelWorld(20260808u, WorldType.Flat);
        world.GenerateChunkAt(0, 0);
        // 旧 4-Section 存档的绝对 Y=0 数据：验证升级不会把它误放到负 Y。
        world.SetBlock(0, 0, 0, BlockRegistry.Stone);
        WorldFile.Save(world, compressedDirectory);
        var regionPath = WorldFile.RegionPath(compressedDirectory, 0, 0);
        var (regionVersion, encodedLength) = ReadRegionHeader(regionPath, 0);
        using var rawStream = new MemoryStream();
        using (var rawWriter = new BinaryWriter(rawStream, System.Text.Encoding.UTF8, leaveOpen: true))
        {
            WorldFile.WriteChunkPayload(
                rawWriter,
                0,
                0,
                world.Store.GetStatus(0, 0),
                world.Store.GetTicketLevel(0, 0),
                world.Store.GetChunk(0, 0)!);
        }

        Check("新 region 使用压缩版本 4（24 Section + Deflate + CRC32）", regionVersion == WorldFile.RegionVersion, $"version={regionVersion}");
        Check(
            "新 region 负载包含压缩收益",
            encodedLength < rawStream.Length + sizeof(byte) + sizeof(int),
            $"encoded={encodedLength} raw={rawStream.Length}");
        var restored = WorldFile.Load(compressedDirectory);
        Check(
            "压缩 region 完整读档一致",
            restored.Store.ChunkKeys.Length == 1 &&
            restored.GetBlock(0, 0, 0) == world.GetBlock(0, 0, 0));
        using (var storage = new WorldFileStorage(compressedDirectory))
        {
            Check("压缩 region 单区块读取一致", storage.TryLoadChunk(0, 0, out _));
        }

        var packedSection = new Section();
        packedSection.Set(0, 0, 0, BlockRegistry.Grass);
        packedSection.Set(1, 0, 0, BlockRegistry.Dirt);
        packedSection.Set(2, 0, 0, BlockRegistry.Grass);
        using var packedSectionStream = new MemoryStream();
        using (var packedWriter = new BinaryWriter(packedSectionStream, System.Text.Encoding.UTF8, leaveOpen: true))
        {
            packedSection.Save(packedWriter);
        }

        packedSectionStream.Position = 0;
        using (var packedReader = new BinaryReader(packedSectionStream, System.Text.Encoding.UTF8, leaveOpen: true))
        {
            var mode = packedReader.ReadByte();
            var paletteCount = packedReader.ReadInt32();
            for (var index = 0; index < paletteCount; index++)
            {
                _ = packedReader.ReadUInt32();
            }

            var bits = packedReader.ReadByte();
            var packedLength = packedReader.ReadInt32();
            Check(
                "Section 使用按位调色板索引",
                mode == 2 && paletteCount == 3 && bits == 2 && packedLength == 1024,
                $"mode={mode} palette={paletteCount} bits={bits} bytes={packedLength}");
        }

        packedSectionStream.Position = 0;
        using (var packedReader = new BinaryReader(packedSectionStream, System.Text.Encoding.UTF8, leaveOpen: true))
        {
            var packedRoundTrip = Section.Load(packedReader);
            Check(
                "按位调色板 Section 往返一致",
                packedRoundTrip.Get(0, 0, 0) == BlockRegistry.Grass &&
                packedRoundTrip.Get(1, 0, 0) == BlockRegistry.Dirt &&
                packedRoundTrip.Get(2, 0, 0) == BlockRegistry.Grass);
        }

        using var legacySectionStream = new MemoryStream();
        using (var legacyWriter = new BinaryWriter(legacySectionStream, System.Text.Encoding.UTF8, leaveOpen: true))
        {
            legacyWriter.Write((byte)0);
            legacyWriter.Write(3);
            legacyWriter.Write(BlockState.Air.Packed);
            legacyWriter.Write(((BlockState)BlockRegistry.Grass).Packed);
            legacyWriter.Write(((BlockState)BlockRegistry.Dirt).Packed);
            legacyWriter.Write(4096);
            var legacyIndices = new byte[4096];
            legacyIndices[0] = 1;
            legacyIndices[1] = 2;
            legacyWriter.Write(legacyIndices);
            legacyWriter.Write((byte)0);
        }

        legacySectionStream.Position = 0;
        using (var legacyReader = new BinaryReader(legacySectionStream, System.Text.Encoding.UTF8, leaveOpen: true))
        {
            var legacySection = Section.Load(legacyReader);
            Check(
                "旧 Section mode=0 仍可读取",
                legacySection.Get(0, 0, 0) == BlockRegistry.Grass &&
                legacySection.Get(1, 0, 0) == BlockRegistry.Dirt);
        }

        var widePackedSection = new Section();
        widePackedSection.Set(0, 0, 0, BlockRegistry.Grass);
        widePackedSection.Set(1, 0, 0, BlockRegistry.Dirt);
        widePackedSection.Set(2, 0, 0, BlockRegistry.Stone);
        widePackedSection.Set(3, 0, 0, BlockRegistry.Sand);
        using var widePackedStream = new MemoryStream();
        using (var wideWriter = new BinaryWriter(widePackedStream, System.Text.Encoding.UTF8, leaveOpen: true))
        {
            widePackedSection.Save(wideWriter);
        }

        widePackedStream.Position = 0;
        using (var wideReader = new BinaryReader(widePackedStream, System.Text.Encoding.UTF8, leaveOpen: true))
        {
            var wideMode = wideReader.ReadByte();
            var widePaletteCount = wideReader.ReadInt32();
            for (var index = 0; index < widePaletteCount; index++)
            {
                _ = wideReader.ReadUInt32();
            }

            var wideBits = wideReader.ReadByte();
            var wideLength = wideReader.ReadInt32();
            Check(
                "Section 按位调色板支持 3-bit 跨字节索引",
                wideMode == 2 && widePaletteCount == 5 && wideBits == 3 && wideLength == 1536,
                $"mode={wideMode} palette={widePaletteCount} bits={wideBits} bytes={wideLength}");
        }

        widePackedStream.Position = 0;
        using (var wideReader = new BinaryReader(widePackedStream, System.Text.Encoding.UTF8, leaveOpen: true))
        {
            var wideRoundTrip = Section.Load(wideReader);
            Check(
                "3-bit 调色板跨边界往返一致",
                wideRoundTrip.Get(0, 0, 0) == BlockRegistry.Grass &&
                wideRoundTrip.Get(1, 0, 0) == BlockRegistry.Dirt &&
                wideRoundTrip.Get(2, 0, 0) == BlockRegistry.Stone &&
                wideRoundTrip.Get(3, 0, 0) == BlockRegistry.Sand);
        }

        Directory.CreateDirectory(legacyDirectory);
        File.WriteAllText(
            Path.Combine(legacyDirectory, "level.json"),
            "{\"version\":3,\"seed\":20260808,\"worldType\":\"Flat\"}");
        WriteLegacyRegion(legacyDirectory, world, 0, 0);
        var legacyRestored = WorldFile.Load(legacyDirectory);
        Check(
            "旧 region v1 仍可完整读档",
            legacyRestored.Store.ChunkKeys.Length == 1 &&
            legacyRestored.GetBlock(0, 0, 0) == world.GetBlock(0, 0, 0));
        using (var legacyStorage = new WorldFileStorage(legacyDirectory))
        {
            Check("旧 region v1 仍可按区块读取", legacyStorage.TryLoadChunk(0, 0, out var legacyChunk));
            legacyChunk.Chunk.SetBlock(0, 0, 0, BlockRegistry.Grass);
            legacyStorage.SaveChunk(0, 0, legacyChunk);
            var (upgradedVersion, _) = ReadRegionHeader(WorldFile.RegionPath(legacyDirectory, 0, 0), 0);
            Check("旧 region 脏写时升级到 24 Section v4", upgradedVersion == WorldFile.RegionVersion, $"version={upgradedVersion}");
            Check(
                "升级后的旧 region 保留 Y=0 最新修改",
                legacyStorage.TryLoadChunk(0, 0, out var upgradedChunk) &&
                upgradedChunk.Chunk.GetBlock(0, 0, 0) == BlockRegistry.Grass);
        }
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  Voxel region 压缩兼容异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(compressedDirectory)) Directory.Delete(compressedDirectory, recursive: true);
        if (Directory.Exists(legacyDirectory)) Directory.Delete(legacyDirectory, recursive: true);
    }

    Console.WriteLine(failures == 0 ? "voxelcompressioncheck 全部通过" : $"voxelcompressioncheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static (int Version, int Length) ReadRegionHeader(string path, int slot)
    {
        using var stream = File.OpenRead(path);
        using var reader = new BinaryReader(stream);
        _ = reader.ReadString();
        var version = reader.ReadInt32();
        stream.Seek(WorldFile.RegionDirectoryOffset + slot * sizeof(int) * 2, SeekOrigin.Begin);
        _ = reader.ReadInt32();
        var length = reader.ReadInt32();
        return (version, length);
    }

    static void WriteLegacyRegion(string directory, VoxelWorld world, int cx, int cz)
    {
        var path = WorldFile.RegionPath(directory, 0, 0);
        using var stream = File.Create(path);
        using var writer = new BinaryWriter(stream);
        writer.Write(WorldFile.RegionMagic);
        writer.Write(WorldFile.LegacyRegionVersion);
        for (var slot = 0; slot < WorldFile.SlotsPerRegion; slot++)
        {
            writer.Write(0);
            writer.Write(0);
        }

        var offset = (int)stream.Position;
        WorldFile.WriteChunkPayload(
            writer,
            cx,
            cz,
            world.Store.GetStatus(cx, cz),
            world.Store.GetTicketLevel(cx, cz),
            world.Store.GetChunk(cx, cz)!,
            Chunk.LegacySectionCount);
        var length = (int)stream.Position - offset;
        stream.Seek(WorldFile.RegionDirectoryOffset + WorldFile.SlotIndexForStorage(0, 0, cx, cz) * sizeof(int) * 2, SeekOrigin.Begin);
        writer.Write(offset);
        writer.Write(length);
    }
}

static int VoxelCorruptionCheck()
{
    var failures = 0;
    var directory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_corruption_{Guid.NewGuid():N}");
    try
    {
        var world = new VoxelWorld(20260808u, WorldType.Flat);
        world.GenerateChunkAt(0, 0);
        WorldFile.Save(world, directory);
        var regionPath = WorldFile.RegionPath(directory, 0, 0);
        var offset = ReadRegionOffset(regionPath, 0);
        using (var stream = new FileStream(regionPath, FileMode.Open, FileAccess.ReadWrite, FileShare.None))
        {
            stream.Seek(offset + 1 + sizeof(int), SeekOrigin.Begin);
            var crcByte = stream.ReadByte();
            if (crcByte < 0)
            {
                throw new InvalidDataException("测试负载缺少 CRC32 字段");
            }

            stream.Seek(-1, SeekOrigin.Current);
            stream.WriteByte((byte)(crcByte ^ 0xFF));
            stream.Flush(flushToDisk: true);
        }

        Exception? fullLoadError = null;
        try
        {
            _ = WorldFile.Load(directory);
        }
        catch (Exception exception)
        {
            fullLoadError = exception;
        }

        Console.WriteLine($"{(fullLoadError is InvalidDataException && fullLoadError.Message.Contains("CRC32", StringComparison.Ordinal) ? "PASS" : "FAIL")}  完整读档拒绝 CRC 损坏区块  {fullLoadError?.Message ?? "none"}");
        if (fullLoadError is not InvalidDataException || !fullLoadError.Message.Contains("CRC32", StringComparison.Ordinal))
        {
            failures++;
        }

        using var storage = new WorldFileStorage(directory);
        Exception? chunkLoadError = null;
        try
        {
            _ = storage.TryLoadChunk(0, 0, out _);
        }
        catch (Exception exception)
        {
            chunkLoadError = exception;
        }

        Console.WriteLine($"{(chunkLoadError is InvalidDataException && chunkLoadError.Message.Contains("CRC32", StringComparison.Ordinal) ? "PASS" : "FAIL")}  单区块读档拒绝 CRC 损坏区块  {chunkLoadError?.Message ?? "none"}");
        if (chunkLoadError is not InvalidDataException || !chunkLoadError.Message.Contains("CRC32", StringComparison.Ordinal))
        {
            failures++;
        }
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  Voxel 损坏校验异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(directory))
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "voxelcorruptioncheck 全部通过" : $"voxelcorruptioncheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static int ReadRegionOffset(string path, int slot)
    {
        using var stream = File.OpenRead(path);
        using var reader = new BinaryReader(stream);
        _ = reader.ReadString();
        _ = reader.ReadInt32();
        stream.Seek(WorldFile.RegionDirectoryOffset + slot * sizeof(int) * 2, SeekOrigin.Begin);
        return reader.ReadInt32();
    }
}

static int VoxelRecoveryCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var directory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_recovery_{Guid.NewGuid():N}");
    try
    {
        var world = new VoxelWorld(20260808u, WorldType.Flat);
        world.GenerateChunkAt(0, 0);
        WorldFile.Save(world, directory);

        var regionPath = WorldFile.RegionPath(directory, 0, 0);
        var temporaryPath = regionPath + ".tmp";
        File.Copy(regionPath, temporaryPath, overwrite: true);
        File.Delete(regionPath);

        using (var recoveredStorage = new WorldFileStorage(directory))
        {
            var recovered = recoveredStorage.TryLoadChunk(0, 0, out var persisted);
            Check(
                "启动时从完整临时 region 恢复正式文件",
                recovered && File.Exists(regionPath) && !File.Exists(temporaryPath) &&
                persisted.Chunk.GetBlock(0, WorldGenerator.FlatLayers.Length - 1, 0) == BlockRegistry.Grass,
                $"loaded={recovered} region={File.Exists(regionPath)} temp={File.Exists(temporaryPath)}");
        }

        File.Copy(regionPath, temporaryPath, overwrite: true);
        using (var validOriginalStorage = new WorldFileStorage(directory))
        {
            Check(
                "正式 region 有效时丢弃遗留临时文件",
                validOriginalStorage.TryLoadChunk(0, 0, out _) && !File.Exists(temporaryPath));
        }

        using (var storage = new WorldFileStorage(directory))
        {
            storage.SaveChunk(
                0,
                0,
                new PersistedChunk(
                    world.Store.GetChunk(0, 0)!,
                    world.Store.GetStatus(0, 0),
                    world.Store.GetTicketLevel(0, 0)));
            Check("正常保存完成后不遗留临时 region", !File.Exists(temporaryPath));
        }
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  Voxel region 崩溃恢复异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(directory))
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "voxelrecoverycheck 全部通过" : $"voxelrecoverycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelStorageCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var directory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_storage_{Guid.NewGuid():N}");
    try
    {
        var world = new VoxelWorld(20260808u, WorldType.Flat);
        world.GenerateChunkAt(0, 0);
        world.GenerateChunkAt(-1, -1);
        world.GenerateChunkAt(40, -40);
        world.Store.SetStatus(-1, -1, ChunkStatus.Ready);
        world.Store.SetTicketLevel(-1, -1, TicketLevel.EntitySimulation);
        WorldFile.Save(world, directory);

        var metadataWorld = WorldFile.LoadMetadata(directory);
        Check(
            "通用存储打开阶段不全量载入区块",
            metadataWorld.Store.ChunkKeys.Length == 0,
            $"chunks={metadataWorld.Store.ChunkKeys.Length}");

        using (var storage = new WorldFileStorage(directory))
        {
            var loadedOrigin = storage.TryLoadChunk(0, 0, out var origin);
            var loadedNegative = storage.TryLoadChunk(-1, -1, out var negative);
            var loadedCrossRegion = storage.TryLoadChunk(40, -40, out var crossRegion);
            Check(
                "存储按坐标读取正负 region 区块",
                loadedOrigin && loadedNegative && loadedCrossRegion,
                $"origin={loadedOrigin} negative={loadedNegative} cross={loadedCrossRegion}");
            Check(
                "单区块快照保留状态和 ticket",
                negative.Status == ChunkStatus.Ready && negative.TicketLevel == TicketLevel.EntitySimulation,
                $"status={negative.Status} ticket={negative.TicketLevel}");
            Check(
                "缺失坐标返回 false 且不生成区块",
                !storage.TryLoadChunk(123, 123, out _));

            var replacement = world.Store.GetChunk(-1, -1)!;
            replacement.SetBlock(0, WorldGenerator.FlatLayers.Length - 1, 0, BlockRegistry.Stone);
            storage.SaveChunk(
                -1,
                -1,
                new PersistedChunk(replacement, ChunkStatus.Ready, TicketLevel.EntitySimulation));
            Check(
                "单区块覆盖写后立即可读最新负载",
                storage.TryLoadChunk(-1, -1, out var replaced) &&
                replaced.Chunk.GetBlock(0, WorldGenerator.FlatLayers.Length - 1, 0) == BlockRegistry.Stone);
            Check(
                "正常单区块保存不遗留临时文件",
                !File.Exists(WorldFile.RegionPath(directory, -1, -1) + ".tmp"));

            var regionPath = WorldFile.RegionPath(directory, -1, -1);
            var baselineRegionBytes = new FileInfo(regionPath).Length;
            for (var overwrite = 0; overwrite < 64; overwrite++)
            {
                storage.SaveChunk(
                    -1,
                    -1,
                    new PersistedChunk(replacement, ChunkStatus.Ready, TicketLevel.EntitySimulation));
            }

            var compactedRegionBytes = new FileInfo(regionPath).Length;
            Check(
                "重复覆盖区块后 region 文件受控增长",
                compactedRegionBytes <= baselineRegionBytes * 2,
                $"baseline={baselineRegionBytes} compacted={compactedRegionBytes}");
            Check(
                "region 压缩回收后仍可读取最新区块",
                storage.TryLoadChunk(-1, -1, out var compacted) &&
                compacted.Chunk.GetBlock(0, WorldGenerator.FlatLayers.Length - 1, 0) == BlockRegistry.Stone);

            storage.Dispose();
            var disposedError = CaptureException(() => storage.TryLoadChunk(0, 0, out _));
            Check("释放后的通用存储拒绝继续读取", disposedError is ObjectDisposedException, disposedError?.GetType().Name ?? "none");
        }

        var boundedConstructor = typeof(WorldFileStorage).GetConstructor([typeof(string), typeof(int)]);
        var cachedCountProperty = typeof(WorldFileStorage).GetProperty("CachedChunkCount");
        var boundedStorage = boundedConstructor?.Invoke([directory, 1]) as WorldFileStorage;
        try
        {
            var boundedRead = boundedStorage is not null &&
                boundedStorage.TryLoadChunk(0, 0, out _) &&
                boundedStorage.TryLoadChunk(-1, -1, out _) &&
                boundedStorage.TryLoadChunk(40, -40, out _);
            var cachedCount = cachedCountProperty?.GetValue(boundedStorage) is int value ? value : -1;
            Check(
                "通用存储负载缓存保持显式上限",
                boundedConstructor is not null && cachedCountProperty is not null && boundedRead && cachedCount <= 1,
                $"constructor={boundedConstructor is not null} property={cachedCountProperty is not null} cached={cachedCount}");

            if (boundedStorage is not null)
            {
                _ = boundedStorage.TryLoadChunk(0, 0, out _);
                var replacementOrigin = world.Store.GetChunk(0, 0)!;
                replacementOrigin.SetBlock(0, WorldGenerator.FlatLayers.Length - 1, 0, BlockRegistry.Stone);
                boundedStorage.SaveChunk(
                    0,
                    0,
                    new PersistedChunk(replacementOrigin, ChunkStatus.Ready, TicketLevel.EntitySimulation));
                Check(
                    "单区块写入会失效负载缓存",
                    boundedStorage.TryLoadChunk(0, 0, out var refreshed) &&
                    refreshed.Chunk.GetBlock(0, WorldGenerator.FlatLayers.Length - 1, 0) == BlockRegistry.Stone);
            }
        }
        finally
        {
            boundedStorage?.Dispose();
        }

        var bulkEntryType = typeof((int X, int Z, PersistedChunk Persisted));
        var bulkEntryListType = typeof(IReadOnlyList<>).MakeGenericType(bulkEntryType);
        var bulkSaveMethod = typeof(WorldFileStorage).GetMethod("SaveChunks", [bulkEntryListType]);
        Check(
            "通用存储提供按 region 批量保存入口",
            bulkSaveMethod is not null,
            bulkSaveMethod?.ToString() ?? "WorldFileStorage.SaveChunks missing");

        using (var bulkStorage = new WorldFileStorage(directory))
        {
            var bulkEntries = world.Store.ChunkKeys
                .Select(key => (
                    key.X,
                    key.Z,
                    new PersistedChunk(
                        world.Store.GetChunk(key.X, key.Z)!,
                        world.Store.GetStatus(key.X, key.Z),
                        world.Store.GetTicketLevel(key.X, key.Z))))
                .ToArray();
            bulkStorage.SaveChunks(bulkEntries);
            var restored = bulkEntries.All(entry =>
                bulkStorage.TryLoadChunk(entry.X, entry.Z, out var persisted) &&
                persisted.Chunk.GetBlock(0, WorldGenerator.FlatLayers.Length - 1, 0) ==
                entry.Item3.Chunk.GetBlock(0, WorldGenerator.FlatLayers.Length - 1, 0));
            Check(
                "批量保存跨 region 区块后全部可恢复",
                restored,
                $"chunks={bulkEntries.Length}");
        }
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  Voxel 通用存储契约异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(directory))
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "voxelstoragecheck 全部通过" : $"voxelstoragecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

