}

static int VoxelStorageBenchmarkCheck(uint seed)
{
    var failures = 0;
    var directory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_storage_benchmark_{Guid.NewGuid():N}");

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    static (int Raw, int Compressed) SectionSerializedBytes(Section section)
    {
        using var stream = new MemoryStream();
        using var writer = new BinaryWriter(stream, System.Text.Encoding.UTF8, leaveOpen: true);
        section.Save(writer);
        writer.Flush();
        var raw = stream.ToArray();
        using var compressedStream = new MemoryStream();
        using (var deflate = new DeflateStream(compressedStream, CompressionLevel.Fastest, leaveOpen: true))
        {
            deflate.Write(raw);
        }

        return (raw.Length, checked((int)compressedStream.Length));
    }

    try
    {
        var world = new VoxelWorld(seed, WorldType.Flat);
        for (var cz = -3; cz <= 3; cz++)
        {
            for (var cx = -3; cx <= 3; cx++)
            {
                world.GenerateChunkAt(cx, cz);
            }
        }

        WorldFile.Save(world, directory);
        var keys = world.Store.ChunkKeys
            .OrderBy(key => key.Z)
            .ThenBy(key => key.X)
            .ToArray();
        var initialRegionBytes = Directory.EnumerateFiles(directory, "*.cubitregion")
            .Sum(path => new FileInfo(path).Length);

        var fullPayloadBefore = 0L;
        foreach (var (cx, cz) in keys)
        {
            var chunk = world.Store.GetChunk(cx, cz)!;
            fullPayloadBefore += WorldFile.EncodeChunkPayload(
                cx,
                cz,
                world.Store.GetStatus(cx, cz),
                world.Store.GetTicketLevel(cx, cz),
                chunk,
                WorldFile.RegionVersion).LongLength;
        }

        // 固定编辑序列：每个区块只修改最高 Section 的同一局部方块，
        // 只测量存储负载，不让基准把玩法层的光照同步重复计入理论 Section 负载。
        foreach (var (cx, cz) in keys)
        {
            world.Store.GetChunk(cx, cz)!.SetBlock(0, Chunk.MaxYExclusive - 1, 0, BlockRegistry.Stone);
        }

        var fullPayloadAfter = 0L;
        var dirtySectionCount = 0;
        var dirtySectionRawBytes = 0L;
        var dirtySectionCompressedBytes = 0L;
        foreach (var (cx, cz) in keys)
        {
            var chunk = world.Store.GetChunk(cx, cz)!;
            var mask = chunk.DirtySectionMask;
            dirtySectionCount += BitOperations.PopCount(mask);
            for (var sectionIndex = 0; sectionIndex < Chunk.SectionCount; sectionIndex++)
            {
                if ((mask & (1UL << sectionIndex)) != 0)
                {
                    var sizes = SectionSerializedBytes(chunk.GetSection(sectionIndex));
                    dirtySectionRawBytes += sizes.Raw;
                    dirtySectionCompressedBytes += sizes.Compressed;
                }
            }

            fullPayloadAfter += WorldFile.EncodeChunkPayload(
                cx,
                cz,
                world.Store.GetStatus(cx, cz),
                world.Store.GetTicketLevel(cx, cz),
                chunk,
                WorldFile.RegionVersion).LongLength;
        }

        using (var storage = new WorldFileStorage(directory, maxCachedChunks: 0))
        {
            foreach (var (cx, cz) in keys)
            {
                storage.SaveChunk(
                    cx,
                    cz,
                    new PersistedChunk(
                        world.Store.GetChunk(cx, cz)!,
                        world.Store.GetStatus(cx, cz),
                        world.Store.GetTicketLevel(cx, cz)));
            }
        }

        var afterRegionBytes = Directory.EnumerateFiles(directory, "*.cubitregion")
            .Sum(path => new FileInfo(path).Length);
        var randomReadSamples = new double[32];
        using (var storage = new WorldFileStorage(directory, maxCachedChunks: 0))
        {
            for (var sample = 0; sample < randomReadSamples.Length; sample++)
            {
                var key = keys[(sample * 17) % keys.Length];
                var timer = Stopwatch.StartNew();
                var loaded = storage.TryLoadChunk(key.X, key.Z, out _);
                timer.Stop();
                Check("存储基准随机读取成功", loaded, $"coord=({key.X},{key.Z})");
                randomReadSamples[sample] = timer.Elapsed.TotalMilliseconds;
            }
        }

        var report = new
        {
            schema = "cubit.voxel-storage-benchmark/v1",
            seed,
            worldType = WorldType.Flat.ToString(),
            chunkCount = keys.Length,
            sectionCount = Chunk.SectionCount,
            initialRegionBytes,
            afterRegionBytes,
            regionDeltaBytes = afterRegionBytes - initialRegionBytes,
            fullPayloadBeforeBytes = fullPayloadBefore,
            fullPayloadAfterBytes = fullPayloadAfter,
            dirtySectionCount,
            dirtySectionSerializedBytes = dirtySectionRawBytes,
            dirtySectionIndependentCompressedBytes = dirtySectionCompressedBytes,
            dirtySectionPayloadIsTheoretical = true,
            randomReadMedianMilliseconds = Median(randomReadSamples),
        };
        Console.WriteLine(JsonSerializer.Serialize(report));
        Check(
            "存储基准覆盖 49 区块和 24 Section",
            keys.Length == 49 && Chunk.SectionCount == 24,
            $"chunks={keys.Length} sections={Chunk.SectionCount}");
        Check(
            "单区块编辑只标记最高 Section（理论细粒度写入输入）",
            dirtySectionCount == keys.Length,
            $"dirtySections={dirtySectionCount}");
        Check(
            "完整区块与 Section 理论负载均有有效数据",
            fullPayloadAfter > 0 && dirtySectionRawBytes > 0 && dirtySectionCompressedBytes > 0,
            $"full={fullPayloadAfter} rawSection={dirtySectionRawBytes} compressedSection={dirtySectionCompressedBytes}");
    }
    catch (Exception exception)
    {
        Console.WriteLine($"FAIL  体素存储基准异常  {exception}");
        failures++;
    }
    finally
    {
        if (Directory.Exists(directory))
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "voxelstoragebenchmarkcheck 全部通过" : $"voxelstoragebenchmarkcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelHeightCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var boundsType = typeof(Chunk).Assembly.GetType("Cubit.Voxel.World.VoxelVerticalBounds");
    Check(
        "体素插件提供独立垂直坐标契约",
        boundsType is not null,
        boundsType?.FullName ?? "missing");
    var configMinY = typeof(WorldConfig).GetProperty("MinY");
    var configHeight = typeof(WorldConfig).GetProperty("Height");
    Check(
        "WorldConfig 暴露项目可配置高度边界",
        configMinY is not null && configHeight is not null,
        $"minY={configMinY is not null} height={configHeight is not null}");
    var defaultConfig = new WorldConfig();
    var defaultBounds = defaultConfig.GetVerticalBounds();
    Check(
        "WorldConfig 默认值与 Chunk 布局契约一致",
        defaultBounds == Chunk.VerticalBounds &&
        defaultBounds.MinY == Chunk.MinY &&
        defaultBounds.MaxYExclusive == Chunk.MaxYExclusive &&
        defaultBounds.SectionCount == Chunk.SectionCount,
        $"min={defaultBounds.MinY} max={defaultBounds.MaxYExclusive} sections={defaultBounds.SectionCount}");
    var customBounds = new WorldConfig { MinY = -128, Height = 512 }.GetVerticalBounds();
    Check(
        "WorldConfig 接受按 Section 对齐的未来高度布局",
        customBounds.MinY == -128 && customBounds.Height == 512 &&
        customBounds.MaxYExclusive == 384 && customBounds.SectionCount == 32,
        $"min={customBounds.MinY} max={customBounds.MaxYExclusive} sections={customBounds.SectionCount}");
    var invalidBounds = CaptureException(() => new VoxelVerticalBounds(-65, 384));
    Check(
        "垂直坐标契约拒绝未对齐的最低 Y",
        invalidBounds is ArgumentOutOfRangeException,
        invalidBounds?.Message ?? "none");
    var invalidHeight = CaptureException(() => new VoxelVerticalBounds(-64, 383));
    Check(
        "垂直坐标契约拒绝非 Section 倍数高度",
        invalidHeight is ArgumentOutOfRangeException,
        invalidHeight?.Message ?? "none");
    var configRoundtrip = Resource.FromJson<WorldConfig>(new WorldConfig
    {
        MinY = -128,
        Height = 512,
    }.ToJson());
    Check(
        "WorldConfig 高度边界 JSON 往返",
        configRoundtrip.MinY == -128 && configRoundtrip.Height == 512 &&
        configRoundtrip.GetVerticalBounds().MaxYExclusive == 384,
        $"min={configRoundtrip.MinY} height={configRoundtrip.Height}");

    var minYField = typeof(Chunk).GetField("MinY", BindingFlags.Public | BindingFlags.Static);
    var maxYField = typeof(Chunk).GetField("MaxYExclusive", BindingFlags.Public | BindingFlags.Static);
    var sizeYField = typeof(Chunk).GetField("SizeY", BindingFlags.Public | BindingFlags.Static);
    Check(
        "体素插件公开原版高度契约",
        minYField is not null && maxYField is not null && sizeYField is not null,
        $"min={minYField is not null} max={maxYField is not null} size={sizeYField is not null}");

    if (minYField is not null && maxYField is not null && sizeYField is not null)
    {
        var minY = (int)(minYField.GetValue(null) ?? 0);
        var maxY = (int)(maxYField.GetValue(null) ?? 0);
        var sizeY = (int)(sizeYField.GetValue(null) ?? 0);
        Check("原版主世界高度为 -64..319", minY == -64 && maxY == 320 && sizeY == 384, $"min={minY} max={maxY} size={sizeY}");
        Check(
            "世界 Y 到 Section 索引映射连续",
            Chunk.SectionIndex(minY) == 0 && Chunk.SectionIndex(0) == 4 && Chunk.SectionIndex(maxY - 1) == 23 &&
            Chunk.SectionLocalY(minY) == 0 && Chunk.SectionLocalY(maxY - 1) == 15);

        var chunk = new Chunk();
        chunk.SetBlock(0, minY, 0, BlockRegistry.Stone);
        chunk.SetBlock(0, maxY - 1, 0, BlockRegistry.Grass);
        Check(
            "区块边界负 Y 与上边界可读写",
            chunk.GetBlock(0, minY, 0) == BlockRegistry.Stone && chunk.GetBlock(0, maxY - 1, 0) == BlockRegistry.Grass);
        chunk.SetBlock(0, minY - 1, 0, BlockRegistry.Dirt);
        chunk.SetBlock(0, maxY, 0, BlockRegistry.Dirt);
        Check(
            "区块上下边界之外拒绝写入",
            chunk.GetBlock(0, minY - 1, 0) == BlockRegistry.Air && chunk.GetBlock(0, maxY, 0) == BlockRegistry.Air);
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    var snapshotPath = repositoryRoot is null
        ? string.Empty
        : Path.Combine(repositoryRoot, "src", "Cubit.Voxel", "World", "ChunkMeshSnapshot.cs");
    var snapshotSource = File.Exists(snapshotPath) ? File.ReadAllText(snapshotPath) : string.Empty;
    Check(
        "高度网格快照不在体素循环内重复调用公共锁查询",
        snapshotSource.Length > 0 &&
        !snapshotSource.Contains("store.GetBlock(", StringComparison.Ordinal) &&
        !snapshotSource.Contains("LightingEngine.GetLight(store", StringComparison.Ordinal),
        snapshotPath);
    Check(
        "流式网格快照提供显式池化生命周期",
        typeof(ChunkMeshSnapshot).GetInterface(nameof(IDisposable)) is not null &&
        snapshotSource.Contains("ArrayPool", StringComparison.Ordinal),
        snapshotPath);

    var lightingType = typeof(LightingEngine);
    var skySeedCountField = lightingType.GetField("_lastSkySeedCount", BindingFlags.NonPublic | BindingFlags.Static);
    var seedWorld = new VoxelWorld(20260808u, WorldType.Flat);
    seedWorld.GenerateChunkAt(0, 0);
    var skySeedCount = skySeedCountField?.GetValue(null) as int? ?? -1;
    Check(
        "平坦区块天空光 BFS 只从直射/阴影边界播种",
        skySeedCountField is not null && skySeedCount >= 0 && skySeedCount <= Chunk.SizeX * Chunk.SizeZ * 4,
        $"seeds={skySeedCount}");

    var relightCountField = lightingType.GetField("_lastSkyAroundRelightCount", BindingFlags.NonPublic | BindingFlags.Static);
    var relightProbeWorld = new VoxelWorld(20260808u, WorldType.Flat);
    relightProbeWorld.GenerateChunkAt(0, 0);
    relightProbeWorld.GenerateChunkAt(1, 0);
    var relightCount = relightCountField?.GetValue(null) as int? ?? -1;
    Check(
        "新区块提交不重复重算中心天空光",
        relightCountField is not null && relightCount >= 0 && relightCount <= 2,
        $"relights={relightCount}");
    Check(
        "流式器公开生成提交阶段分配计数",
        typeof(ChunkStreamer).GetProperty("GenerationCommitAllocatedBytes", BindingFlags.Instance | BindingFlags.Public) is not null);

    Console.WriteLine(failures == 0 ? "voxelheightcheck 全部通过" : $"voxelheightcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int StreamCheck(uint seed)
{
    var failures = 0;
    const double streamWaitSeconds = 30d;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    {
        var burstWorld = new VoxelWorld(seed, WorldType.Flat);
        using (var burstJobs = new JobSystem(new JobSystemOptions { WorkerCount = Math.Max(2, Math.Min(4, Environment.ProcessorCount)) }))
        using (var burstStreamer = new ChunkStreamer(burstWorld, burstJobs))
    {
        burstStreamer.RequestArea(0, 0, 2);
        burstStreamer.Pump();
        var burstDeadline = Stopwatch.StartNew();
        while (burstStreamer.GeneratedCount < 2 && burstDeadline.Elapsed < TimeSpan.FromSeconds(2))
        {
            Thread.Sleep(10);
        }

        burstStreamer.Pump();
        Check(
            "流式器在主线程预算内批量提交相邻已完成区块",
            burstStreamer.GeneratedCount >= 2 && burstStreamer.LastGenerationCommitCount is >= 2 and <= 4,
            $"generated={burstStreamer.GeneratedCount} commits={burstStreamer.LastGenerationCommitCount} commitMs={burstStreamer.GenerationCommitMilliseconds:F3} chunks={burstWorld.Store.ChunkKeys.Length}");
    }
    }

    var world = new VoxelWorld(seed);
    using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = Math.Max(1, Math.Min(4, Environment.ProcessorCount)) });
    using var streamer = new ChunkStreamer(world, jobs);
    streamer.RequestArea(0, 0, 3);

    var consumed = new HashSet<(int, int)>();
    var maxMeshesPublishedPerPump = 0;
    var sw = Stopwatch.StartNew();
    while (sw.Elapsed < TimeSpan.FromSeconds(streamWaitSeconds))
    {
        streamer.Pump();
        var publishedThisPump = world.ConsumePendingMeshes();
        maxMeshesPublishedPerPump = Math.Max(maxMeshesPublishedPerPump, publishedThisPump.Count);
        foreach (var (key, _) in publishedThisPump) consumed.Add(key);
        if (world.Store.ChunkKeys.Length == 49 && consumed.Count == 49) break;
        Thread.Sleep(10);
    }
    foreach (var (key, _) in world.ConsumePendingMeshes()) consumed.Add(key);

    Check(
        "流式器单次 Pump 不批量发布多个已完成网格",
        maxMeshesPublishedPerPump <= 1,
        $"maxPublished={maxMeshesPublishedPerPump}");

    // 同步探针：直接网格化 (0,0)，验证 MeshIfReady 逻辑本身
    world.MeshChunk(0, 0);
    foreach (var (key, _) in world.ConsumePendingMeshes()) consumed.Add(key);
    Console.WriteLine($"[stream] 同步探针后 meshed={consumed.Count} 工作线程成功={streamer.MeshedCount}");

    Check("流式生成 49 区块", world.Store.ChunkKeys.Length == 49, $"chunks={world.Store.ChunkKeys.Length}");
    Check("流式网格 49 个（无重复）", consumed.Count == 49, $"meshed={consumed.Count}");

    // 主线程并发读安全
    var sample = world.GetBlock(24, 33, 24);
    Check("流式期间并发读安全", sample != BlockRegistry.Air, $"block={BlockRegistry.GetName(sample)}");

    // 增长：请求新区域 (4..6, 4..6) 9 块 → 总计 58
    streamer.RequestArea(5, 5, 1);
    sw.Restart();
    while (sw.Elapsed < TimeSpan.FromSeconds(streamWaitSeconds))
    {
        streamer.Pump();
        foreach (var (key, _) in world.ConsumePendingMeshes()) consumed.Add(key);
        if (consumed.Count >= 58) break;
        Thread.Sleep(10);
    }
    foreach (var (key, _) in world.ConsumePendingMeshes()) consumed.Add(key);
    Check("流式增长（新区域异步网格化）", consumed.Count == 58, $"meshed={consumed.Count}");

    var pendingDeadline = Stopwatch.StartNew();
    while (pendingDeadline.Elapsed < TimeSpan.FromSeconds(streamWaitSeconds) && streamer.PendingCount > 0)
    {
        streamer.Pump();
        foreach (var (key, _) in world.ConsumePendingMeshes()) consumed.Add(key);
        Thread.Sleep(10);
    }
    Check("请求队列已清空", streamer.PendingCount == 0, $"pending={streamer.PendingCount}");

    // 上传队列按区块合并：后到的边界修复网格必须替换同一区块尚未上传的孤立网格。
    // 否则每帧一个上传会让旧侧面在屏幕上滞留，形成 16x16 的区块网格线。
    var uploadCoalescingWorld = new VoxelWorld(seed, WorldType.Flat);
    uploadCoalescingWorld.GenerateChunkAt(0, 0);
    var firstUploadWork = uploadCoalescingWorld.CreateMeshSnapshot(0, 0);
    var oldUploadMesh = new ChunkMeshLayers(
        new ChunkMeshData([1f], [1u]),
        ChunkMeshData.Empty);
    var repairedUploadMesh = new ChunkMeshLayers(
        new ChunkMeshData([2f], [2u]),
        ChunkMeshData.Empty);
    var publishedOldUpload = firstUploadWork is { } firstUpload &&
        uploadCoalescingWorld.PublishMesh(0, 0, firstUpload.Revision, oldUploadMesh);
    var secondUploadWork = uploadCoalescingWorld.CreateMeshSnapshot(0, 0);
    var publishedRepairedUpload = secondUploadWork is { } secondUpload &&
        uploadCoalescingWorld.PublishMesh(0, 0, secondUpload.Revision, repairedUploadMesh);
    var coalescedUploads = uploadCoalescingWorld.ConsumePendingMeshes();
    Check(
        "同区块待上传网格以最新边界修复结果覆盖旧结果",
        publishedOldUpload && publishedRepairedUpload && coalescedUploads.Count == 1 &&
        coalescedUploads[0].Key == (0, 0) && coalescedUploads[0].Mesh.Opaque.Vertices.SequenceEqual(repairedUploadMesh.Opaque.Vertices),
        $"published={publishedOldUpload}/{publishedRepairedUpload} pending={coalescedUploads.Count}");

    // 平坦世界的中心区块在四邻区块都到达后，不得保留初始孤立网格产生的内部边界侧面。
    // 否则会在画面中形成与 16x16 区块完全重合的亮线。
    var settledFlatWorld = new VoxelWorld(seed, WorldType.Flat);
    using var settledFlatJobs = new JobSystem(new JobSystemOptions { WorkerCount = Math.Max(1, Math.Min(4, Environment.ProcessorCount)) });
    using var settledFlatStreamer = new ChunkStreamer(settledFlatWorld, settledFlatJobs);
    settledFlatStreamer.RequestArea(0, 0, 1);
    var settledMeshes = new Dictionary<(int X, int Z), ChunkMeshLayers>();
    var settledFlatDeadline = Stopwatch.StartNew();
    while (settledFlatDeadline.Elapsed < TimeSpan.FromSeconds(10))
    {
        settledFlatStreamer.Pump();
        foreach (var (key, mesh) in settledFlatWorld.ConsumePendingMeshes())
        {
            settledMeshes[key] = mesh;
        }

        if (settledFlatWorld.Store.ChunkKeys.Length == 9 && settledFlatStreamer.PendingCount == 0)
        {
            break;
        }

        Thread.Sleep(1);
    }

    var settledCenterFaces = settledMeshes.TryGetValue((0, 0), out var settledCenterMesh)
        ? settledCenterMesh.Opaque.Vertices.Length / (4 * 7)
        : -1;
    Check(
        "流式收敛后中心平坦区块不保留内部边界侧面",
        settledFlatWorld.Store.ChunkKeys.Length == 9 && settledFlatStreamer.PendingCount == 0 && settledCenterFaces == 2,
        $"chunks={settledFlatWorld.Store.ChunkKeys.Length} pending={settledFlatStreamer.PendingCount} centerFaces={settledCenterFaces}");

    var continuousWorld = new VoxelWorld(seed, WorldType.Flat);
    using var continuousJobs = new JobSystem(new JobSystemOptions { WorkerCount = Math.Max(2, Math.Min(4, Environment.ProcessorCount)) });
    using var continuousStreamer = new ChunkStreamer(continuousWorld, continuousJobs);
    continuousStreamer.RequestArea(0, 0, 3);
    continuousStreamer.RequestArea(10, 0, 3);
    var meshedBeforeGenerationDrained = false;
    var continuousDeadline = Stopwatch.StartNew();
    while (continuousDeadline.Elapsed < TimeSpan.FromSeconds(10))
    {
        continuousStreamer.Pump();
        _ = continuousWorld.ConsumePendingMeshes();
        if (continuousStreamer.MeshedCount > 0 && continuousWorld.Store.ChunkKeys.Length < 98)
        {
            meshedBeforeGenerationDrained = true;
            break;
        }

        Thread.Sleep(1);
    }

    Check(
        "连续流式生成期间已提交区块仍可分批网格化",
        meshedBeforeGenerationDrained,
        $"chunks={continuousWorld.Store.ChunkKeys.Length} meshed={continuousStreamer.MeshedCount} pending={continuousStreamer.PendingCount}");

    // 邻区提交后，旧区块的边界面必须优先被重建，不能被新区域的长队列拖延。
    var seamWorld = new VoxelWorld(seed, WorldType.Flat);
    using var seamJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    using var seamStreamer = new ChunkStreamer(seamWorld, seamJobs);
    seamStreamer.RequestArea(0, 0, 0);
    var initialMeshPublished = false;
    var seamDeadline = Stopwatch.StartNew();
    while (seamDeadline.Elapsed < TimeSpan.FromSeconds(10))
    {
        seamStreamer.Pump();
        foreach (var (key, _) in seamWorld.ConsumePendingMeshes())
        {
            initialMeshPublished |= key == (0, 0);
        }

        if (initialMeshPublished && seamStreamer.PendingCount == 0)
        {
            break;
        }

        Thread.Sleep(1);
    }

    Check("接缝回归：初始孤立区块网格已发布", initialMeshPublished, $"pending={seamStreamer.PendingCount}");
    var seamRepairOrder = new List<(int X, int Z)>();
    if (initialMeshPublished)
    {
        // 半径 4 保持连续生成队列非空，复现玩家移动时邻区到达的真实调度压力。
        seamStreamer.RequestArea(1, 0, 4);
        var neighbourArrived = false;
        seamDeadline.Restart();
        while (seamDeadline.Elapsed < TimeSpan.FromSeconds(10))
        {
            seamStreamer.Pump();
            neighbourArrived |= seamWorld.Store.HasChunk(1, 0);
            foreach (var (key, _) in seamWorld.ConsumePendingMeshes())
            {
                if (neighbourArrived && (key == (0, 0) || key == (1, 0)))
                {
                    seamRepairOrder.Add(key);
                }
            }

            if (seamRepairOrder.Count > 0)
            {
                break;
            }

            Thread.Sleep(1);
        }
    }

    Check(
        "接缝回归：邻区到达时优先重建旧边界网格",
        seamRepairOrder.Count > 0 && seamRepairOrder[0] == (0, 0),
        $"order={(seamRepairOrder.Count == 0 ? "none" : string.Join(",", seamRepairOrder.Select(key => $"({key.X},{key.Z})")))}");

    Console.WriteLine(failures == 0 ? "streamcheck 全部通过" : $"streamcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelBenchmarkCheck(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var streamerType = typeof(ChunkStreamer);
    var generationMilliseconds = streamerType.GetProperty("GenerationWorkerMilliseconds", BindingFlags.Instance | BindingFlags.Public);
    var generationAllocatedBytes = streamerType.GetProperty("GenerationWorkerAllocatedBytes", BindingFlags.Instance | BindingFlags.Public);
    var generationCommitAllocatedBytes = streamerType.GetProperty("GenerationCommitAllocatedBytes", BindingFlags.Instance | BindingFlags.Public);
    var snapshotMilliseconds = streamerType.GetProperty("MeshSnapshotMilliseconds", BindingFlags.Instance | BindingFlags.Public);
    var snapshotAllocatedBytes = streamerType.GetProperty("MeshSnapshotAllocatedBytes", BindingFlags.Instance | BindingFlags.Public);
    var meshingMilliseconds = streamerType.GetProperty("MeshBuildMilliseconds", BindingFlags.Instance | BindingFlags.Public);
    var meshingAllocatedBytes = streamerType.GetProperty("MeshBuildAllocatedBytes", BindingFlags.Instance | BindingFlags.Public);
    Check(
        "流式器提供三阶段累计计时",
        generationMilliseconds is not null && snapshotMilliseconds is not null && meshingMilliseconds is not null);
    Check(
        "流式器提供生成/快照/网格阶段分配计数",
        generationAllocatedBytes is not null && generationCommitAllocatedBytes is not null &&
        snapshotAllocatedBytes is not null && meshingAllocatedBytes is not null);

    if (generationMilliseconds is not null && snapshotMilliseconds is not null && meshingMilliseconds is not null)
    {
        var world = new VoxelWorld(seed, WorldType.Flat);
        using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = Math.Max(2, Math.Min(4, Environment.ProcessorCount)) });
        using var streamer = new ChunkStreamer(world, jobs);
        streamer.RequestArea(0, 0, 0);
        var deadline = Stopwatch.StartNew();
        while (deadline.Elapsed < TimeSpan.FromSeconds(10))
        {
            streamer.Pump();
            _ = world.ConsumePendingMeshes();
            if (streamer.PendingCount == 0 && world.Store.ChunkKeys.Length == 1)
            {
                break;
            }

            Thread.Sleep(1);
        }

        var generation = (double?)generationMilliseconds.GetValue(streamer) ?? 0d;
        var snapshot = (double?)snapshotMilliseconds.GetValue(streamer) ?? 0d;
        var meshing = (double?)meshingMilliseconds.GetValue(streamer) ?? 0d;
        Check(
            "三阶段累计计时反映实际流水线工作",
            world.Store.ChunkKeys.Length == 1 && streamer.PendingCount == 0 && generation > 0d && snapshot > 0d && meshing > 0d,
            $"generation={generation:F3}ms snapshot={snapshot:F3}ms meshing={meshing:F3}ms pending={streamer.PendingCount}");
    }

    const int measuredRounds = 5;
    var workerCounts = new[]
    {
        1,
        Math.Max(2, Math.Min(4, Environment.ProcessorCount)),
    }.Distinct().ToArray();
    var pipelineHeader = new VoxelPipelineBenchmarkEvidenceHeader(
        "cubit.voxel-pipeline-benchmark/v1",
        DateTimeOffset.UtcNow,
        new BenchmarkEnvironmentRecord(
            Environment.Version.ToString(),
            RuntimeInformation.FrameworkDescription,
            RuntimeInformation.OSDescription,
            RuntimeInformation.ProcessArchitecture.ToString(),
            RuntimeInformation.OSArchitecture.ToString(),
            Environment.ProcessorCount,
            Stopwatch.Frequency,
            GetToolAssemblyFingerprint()),
        seed,
        "noise",
        3,
        workerCounts,
        measuredRounds,
        "仅记录导致至少一个新网格发布的主线程 Pump 调用；不代表所有 Pump 调用的 p95");
    var pipelineHeaderJson = JsonSerializer.Serialize(pipelineHeader, new JsonSerializerOptions
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
    });
    using (var headerDocument = JsonDocument.Parse(pipelineHeaderJson))
    {
        var headerRoot = headerDocument.RootElement;
        Check(
            "流水线基准输出包含环境与构建指纹",
            headerRoot.TryGetProperty("environment", out var environment) &&
            environment.TryGetProperty("toolAssemblySha256", out var fingerprint) &&
            !string.IsNullOrWhiteSpace(fingerprint.GetString()) &&
            headerRoot.TryGetProperty("workerCounts", out var headerWorkerCounts) &&
            headerWorkerCounts.GetArrayLength() == workerCounts.Length,
            "需要运行时、平台、CPU、计时频率和 Tool SHA256");
    }
    Console.WriteLine(pipelineHeaderJson);
    var samples = new List<VoxelPipelineBenchmarkSample>(workerCounts.Length * measuredRounds);
    foreach (var workerCount in workerCounts)
    {
        _ = RunVoxelPipelineBenchmark(seed, workerCount, 0);
        for (var round = 1; round <= measuredRounds; round++)
        {
            var sample = RunVoxelPipelineBenchmark(seed, workerCount, round);
            samples.Add(sample);
            Console.WriteLine(JsonSerializer.Serialize(sample));
            Check(
                $"{workerCount} worker 第 {round} 轮流水线有效",
                sample.Chunks == 49 && sample.Meshes == 49 && sample.Pending == 0 &&
                sample.GenerationWallMilliseconds > 0d && sample.GenerationWorkerMilliseconds > 0d &&
                sample.MeshSnapshotMilliseconds > 0d && sample.MeshBuildMilliseconds > 0d &&
                sample.GenerationAllocatedBytes > 0 && sample.MeshSnapshotAllocatedBytes > 0 && sample.MeshBuildAllocatedBytes > 0 &&
                sample.GenerationCommitAllocatedBytes > 0 &&
                sample.GenerationCommitAllocatedBytes < 128_000 &&
                sample.MeshPumpP95Milliseconds >= 0d && sample.AllocatedBytes >= 0,
                $"chunks={sample.Chunks} meshes={sample.Meshes} pending={sample.Pending}");
        }
    }

    var first = samples[0];
    var hashesMatch = samples.All(sample =>
        sample.BlockHash == first.BlockHash && sample.MeshHash == first.MeshHash);
    Check(
        "五轮及单/多 worker 区块与网格哈希一致",
        hashesMatch,
        $"blocks={first.BlockHash} meshes={first.MeshHash}");

    foreach (var workerCount in workerCounts)
    {
        var group = samples.Where(sample => sample.WorkerCount == workerCount).ToArray();
        var summary = new
        {
            workerCount,
            rounds = group.Length,
            generationWallMedianMilliseconds = Median(group.Select(sample => sample.GenerationWallMilliseconds)),
            generationWallP95Milliseconds = Percentile(group.Select(sample => sample.GenerationWallMilliseconds), 0.95),
            generationWorkerMedianMilliseconds = Median(group.Select(sample => sample.GenerationWorkerMilliseconds)),
            generationWorkerP95Milliseconds = Percentile(group.Select(sample => sample.GenerationWorkerMilliseconds), 0.95),
            snapshotMedianMilliseconds = Median(group.Select(sample => sample.MeshSnapshotMilliseconds)),
            snapshotP95Milliseconds = Percentile(group.Select(sample => sample.MeshSnapshotMilliseconds), 0.95),
            meshBuildMedianMilliseconds = Median(group.Select(sample => sample.MeshBuildMilliseconds)),
            meshBuildP95Milliseconds = Percentile(group.Select(sample => sample.MeshBuildMilliseconds), 0.95),
            meshPublishingPumpP95MedianMilliseconds = Median(group.Select(sample => sample.MeshPumpP95Milliseconds)),
            meshPublishingPumpP95Milliseconds = Percentile(group.Select(sample => sample.MeshPumpP95Milliseconds), 0.95),
            allocatedBytesMedian = Median(group.Select(sample => (double)sample.AllocatedBytes)),
            allocatedBytesP95 = Percentile(group.Select(sample => (double)sample.AllocatedBytes), 0.95),
            generationAllocatedBytesMedian = Median(group.Select(sample => (double)sample.GenerationAllocatedBytes)),
            generationAllocatedBytesP95 = Percentile(group.Select(sample => (double)sample.GenerationAllocatedBytes), 0.95),
            generationCommitAllocatedBytesMedian = Median(group.Select(sample => (double)sample.GenerationCommitAllocatedBytes)),
            generationCommitAllocatedBytesP95 = Percentile(group.Select(sample => (double)sample.GenerationCommitAllocatedBytes), 0.95),
            meshSnapshotAllocatedBytesMedian = Median(group.Select(sample => (double)sample.MeshSnapshotAllocatedBytes)),
            meshSnapshotAllocatedBytesP95 = Percentile(group.Select(sample => (double)sample.MeshSnapshotAllocatedBytes), 0.95),
            meshBuildAllocatedBytesMedian = Median(group.Select(sample => (double)sample.MeshBuildAllocatedBytes)),
            meshBuildAllocatedBytesP95 = Percentile(group.Select(sample => (double)sample.MeshBuildAllocatedBytes), 0.95),
        };
        var summaryJson = JsonSerializer.Serialize(summary);
        using var summaryDocument = JsonDocument.Parse(summaryJson);
        var summaryRoot = summaryDocument.RootElement;
        Check(
            $"{workerCount} worker 流水线汇总包含各阶段 p95",
            summaryRoot.TryGetProperty("generationWorkerP95Milliseconds", out _) &&
            summaryRoot.TryGetProperty("snapshotP95Milliseconds", out _) &&
            summaryRoot.TryGetProperty("meshBuildP95Milliseconds", out _) &&
            summaryRoot.TryGetProperty("meshPublishingPumpP95Milliseconds", out _) &&
            summaryRoot.TryGetProperty("allocatedBytesP95", out _) &&
            summaryRoot.TryGetProperty("generationAllocatedBytesP95", out _) &&
            summaryRoot.TryGetProperty("generationCommitAllocatedBytesP95", out _) &&
            summaryRoot.TryGetProperty("meshSnapshotAllocatedBytesP95", out _) &&
            summaryRoot.TryGetProperty("meshBuildAllocatedBytesP95", out _),
            "需要除中位数外记录各阶段 p95");
        Console.WriteLine(summaryJson);
    }

    Console.WriteLine(failures == 0 ? "voxelbenchmarkcheck 全部通过" : $"voxelbenchmarkcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static VoxelPipelineBenchmarkSample RunVoxelPipelineBenchmark(uint seed, int workerCount, int round)
{
    const int radius = 3;
    const int expectedChunks = (radius * 2 + 1) * (radius * 2 + 1);
    GC.Collect();
    GC.WaitForPendingFinalizers();
    GC.Collect();
    var allocationStart = GC.GetTotalAllocatedBytes(true);
    var world = new VoxelWorld(seed, WorldType.Noise);
    using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = workerCount });
    using var streamer = new ChunkStreamer(world, jobs);
    streamer.RequestArea(0, 0, radius);
    var meshes = new Dictionary<(int X, int Z), ChunkMeshLayers>();
    var meshPumpSamples = new List<double>();
    var wall = Stopwatch.StartNew();
    var deadline = Stopwatch.StartNew();
    double generationWall = 0d;

    while (deadline.Elapsed < TimeSpan.FromSeconds(30))
    {
        var beforeMeshed = streamer.MeshedCount;
        var pumpStart = Stopwatch.GetTimestamp();
        streamer.Pump();
        var pumpElapsed = (Stopwatch.GetTimestamp() - pumpStart) * 1000d / Stopwatch.Frequency;
        if (streamer.MeshedCount > beforeMeshed)
        {
            meshPumpSamples.Add(pumpElapsed);
        }

        foreach (var (key, mesh) in world.ConsumePendingMeshes())
        {
            meshes[key] = mesh;
        }

        if (generationWall <= 0d && world.Store.ChunkKeys.Length == expectedChunks)
        {
            generationWall = wall.Elapsed.TotalMilliseconds;
        }

        if (world.Store.ChunkKeys.Length == expectedChunks && meshes.Count == expectedChunks && streamer.PendingCount == 0)
        {
            break;
        }

        Thread.Sleep(1);
    }

    foreach (var (key, mesh) in world.ConsumePendingMeshes())
    {
        meshes[key] = mesh;
    }

    if (generationWall <= 0d)
    {
        generationWall = wall.Elapsed.TotalMilliseconds;
    }

    var pumpP95 = meshPumpSamples.Count == 0 ? 0d : Percentile(meshPumpSamples, 0.95);
    var blockHash = HashVoxelBlocks(world);
    var meshHash = HashVoxelMeshes(meshes);
    var allocatedBytes = GC.GetTotalAllocatedBytes(true) - allocationStart;
    return new VoxelPipelineBenchmarkSample(
        seed,
        workerCount,
        round,
        world.Store.ChunkKeys.Length,
        meshes.Count,
        streamer.PendingCount,
        blockHash,
        meshHash,
        generationWall,
        streamer.GenerationWorkerMilliseconds,
        ReadStreamerLong(streamer, "GenerationWorkerAllocatedBytes"),
        ReadStreamerLong(streamer, "GenerationCommitAllocatedBytes"),
        streamer.MeshSnapshotMilliseconds,
        ReadStreamerLong(streamer, "MeshSnapshotAllocatedBytes"),
        streamer.MeshBuildMilliseconds,
        ReadStreamerLong(streamer, "MeshBuildAllocatedBytes"),
        pumpP95,
        allocatedBytes);
}

static long ReadStreamerLong(ChunkStreamer streamer, string propertyName) =>
    streamer.GetType().GetProperty(propertyName, BindingFlags.Instance | BindingFlags.Public)?.GetValue(streamer) as long? ?? 0L;

static ulong HashVoxelBlocks(VoxelWorld world)
{
    ulong hash = 1469598103934665603UL;
    static void Mix(ref ulong target, ulong value)
    {
        target ^= value;
        target *= 1099511628211UL;
    }

    foreach (var key in world.Store.ChunkKeys.OrderBy(k => k.Z).ThenBy(k => k.X))
    {
        Mix(ref hash, unchecked((ulong)key.X));
        Mix(ref hash, unchecked((ulong)key.Z));
        for (var y = Chunk.MinY; y < Chunk.MaxYExclusive; y++)
        {
            for (var z = 0; z < Chunk.SizeZ; z++)
            {
                for (var x = 0; x < Chunk.SizeX; x++)
                {
                    Mix(ref hash, world.Store.GetChunk(key.X, key.Z)!.GetBlock(x, y, z).Packed);
                }
            }
        }
    }

    return hash;
}

static ulong HashVoxelMeshes(Dictionary<(int X, int Z), ChunkMeshLayers> meshes)
{
    ulong hash = 1469598103934665603UL;
    static void Mix(ref ulong target, ulong value)
    {
        target ^= value;
        target *= 1099511628211UL;
    }

    foreach (var entry in meshes.OrderBy(kv => kv.Key.Z).ThenBy(kv => kv.Key.X))
    {
        Mix(ref hash, unchecked((ulong)entry.Key.X));
        Mix(ref hash, unchecked((ulong)entry.Key.Z));
        foreach (var layer in new[] { entry.Value.Opaque, entry.Value.Fluid })
        {
            Mix(ref hash, (ulong)layer.Vertices.Length);
            foreach (var value in layer.Vertices)
            {
                Mix(ref hash, BitConverter.SingleToUInt32Bits(value));
            }

            Mix(ref hash, (ulong)layer.Indices.Length);
            foreach (var value in layer.Indices)
            {
                Mix(ref hash, value);
            }
        }
    }

    return hash;
}

static double Median(IEnumerable<double> values)
{
    var sorted = values.OrderBy(value => value).ToArray();
    if (sorted.Length == 0)
    {
        return 0d;
    }

    var middle = sorted.Length / 2;
    return sorted.Length % 2 == 0 ? (sorted[middle - 1] + sorted[middle]) / 2d : sorted[middle];
}

static double Percentile(IEnumerable<double> values, double percentile)
{
    var sorted = values.OrderBy(value => value).ToArray();
    if (sorted.Length == 0)
    {
        return 0d;
    }

    var index = Math.Clamp((int)Math.Ceiling(sorted.Length * percentile) - 1, 0, sorted.Length - 1);
    return sorted[index];
}

static int VoxelStageCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var streamerType = typeof(ChunkStreamer);
    var meshJob = streamerType.GetNestedType("MeshJob", BindingFlags.NonPublic);
    var meshJobs = streamerType.GetField("_meshJobs", BindingFlags.Instance | BindingFlags.NonPublic);
    var completedMeshes = streamerType.GetField("_completedMeshes", BindingFlags.Instance | BindingFlags.NonPublic);
    var lastPumpThread = streamerType.GetProperty("LastPumpThreadId", BindingFlags.Instance | BindingFlags.Public);
    var lastMeshThread = streamerType.GetProperty("LastMeshThreadId", BindingFlags.Instance | BindingFlags.Public);

    Check(
        "区块流式器维护 worker 不可变网格任务",
        meshJob is not null && meshJobs is not null && completedMeshes is not null,
        $"MeshJob={meshJob is not null} jobs={meshJobs is not null} completed={completedMeshes is not null}");
    Check(
        "区块流式器提供主线程协调与 worker 网格阶段诊断",
        lastPumpThread is not null && lastMeshThread is not null);

    if (lastPumpThread is not null && lastMeshThread is not null)
    {
        var world = new VoxelWorld(20260808u, WorldType.Flat);
        using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = Math.Max(2, Math.Min(4, Environment.ProcessorCount)) });
        using var streamer = new ChunkStreamer(world, jobs);
        streamer.RequestArea(0, 0, 0);
        var meshes = 0;
        var deadline = Stopwatch.StartNew();
        var callerThread = Environment.CurrentManagedThreadId;
        while (deadline.Elapsed < TimeSpan.FromSeconds(10))
        {
            streamer.Pump();
            meshes += world.ConsumePendingMeshes().Count;
            if (meshes == 1 && streamer.PendingCount == 0)
            {
                break;
            }

            Thread.Sleep(1);
        }

        var pumpThread = (int?)lastPumpThread.GetValue(streamer) ?? 0;
        var meshThread = (int?)lastMeshThread.GetValue(streamer) ?? 0;
        Check(
            "区块网格化只读取快照并在 worker 执行",
            meshes == 1 && streamer.PendingCount == 0 && pumpThread == callerThread && meshThread != callerThread,
            $"meshes={meshes} pending={streamer.PendingCount} caller={callerThread} pump={pumpThread} mesh={meshThread}");

        var backgroundPumpRejected = false;
        try
        {
            Task.Run(streamer.Pump).GetAwaiter().GetResult();
        }
        catch (InvalidOperationException)
        {
            backgroundPumpRejected = true;
        }

        Check("流式协调器拒绝后台线程 Pump", backgroundPumpRejected);

        var streamingWorld = new VoxelWorld(20260808u, WorldType.Flat);
        using var streamingJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var streamingStreamer = new ChunkStreamer(streamingWorld, streamingJobs);
        streamingStreamer.RequestArea(0, 0, 0);
        streamingStreamer.RequestArea(1, 0, 3);
        var meshedWhileGenerating = false;
        var streamingDeadline = Stopwatch.StartNew();
        while (streamingDeadline.Elapsed < TimeSpan.FromSeconds(10))
        {
            streamingStreamer.Pump();
            var pendingMeshes = streamingWorld.ConsumePendingMeshes();
            if (pendingMeshes.Any(entry => entry.Key == (0, 0)) && streamingStreamer.PendingCount > 0)
            {
                meshedWhileGenerating = true;
                break;
            }

            Thread.Sleep(1);
        }

        Check(
            "持续流式请求期间已提交区块不会饿死网格阶段",
            meshedWhileGenerating,
            $"pending={streamingStreamer.PendingCount}");
    }

    Console.WriteLine(failures == 0 ? "voxelstagecheck 全部通过" : $"voxelstagecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelResponsivenessCheck(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var ownerThreadId = Environment.CurrentManagedThreadId;
    var world = new VoxelWorld(seed, WorldType.Noise);
    using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    using var streamer = new ChunkStreamer(world, jobs);
    streamer.RequestArea(0, 0, 0);
    var deadline = Stopwatch.StartNew();
    while (deadline.Elapsed < TimeSpan.FromSeconds(10) && streamer.MeshedCount == 0)
    {
        streamer.Pump();
        _ = world.ConsumePendingMeshes();
        Thread.Sleep(1);
    }

    Check(
        "区块网格编译不占用 Pump 主线程",
        streamer.MeshedCount == 1 && streamer.LastMeshThreadId != ownerThreadId,
        $"meshes={streamer.MeshedCount} owner={ownerThreadId} mesh={streamer.LastMeshThreadId}");

    using var startupTree = new SceneTree();
    using var startupJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    using var startupServer = new RenderingServer(new FakeRenderBackend());
    var startupWorld = new VoxelWorldNode
    {
        Seed = seed,
        GenerateRadius = 3,
        Jobs = startupJobs,
        Server = startupServer,
    };
    startupTree.Root.AddChild(startupWorld);
    Check(
        "体素世界进入场景不同步生成整个视距",
        startupWorld.World is not null && startupWorld.Streamer is not null &&
        startupWorld.World.Store.ChunkKeys.Length == 0,
        $"chunks={startupWorld.World?.Store.ChunkKeys.Length ?? -1}");

    Check(
        "新体素节点与世界配置默认提供 8 区块视距",
        new VoxelWorldNode().GenerateRadius == 8 && new WorldConfig().GenerateRadius == 8,
        $"node={new VoxelWorldNode().GenerateRadius} config={new WorldConfig().GenerateRadius}");

    var priorityWorld = new VoxelWorld(seed, WorldType.Flat);
    using var priorityJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    using var priorityStreamer = new ChunkStreamer(priorityWorld, priorityJobs);
    priorityStreamer.RequestArea(0, 0, 2);
    (int X, int Z)[] firstCommitted = [];
    var priorityDeadline = Stopwatch.StartNew();
    while (priorityDeadline.Elapsed < TimeSpan.FromSeconds(10))
    {
        priorityStreamer.Pump();
        var keys = priorityWorld.Store.ChunkKeys;
        if (keys.Length > 0)
        {
            firstCommitted = keys;
            break;
        }

        Thread.Sleep(1);
    }

    Check(
        "流式请求优先生成观察点中心区块",
        firstCommitted.Contains((0, 0)),
        $"first={string.Join(',', firstCommitted.Select(key => $"({key.X},{key.Z})"))}");

    var uploadRenderer = new FakeRenderBackend();
    using var uploadTree = new SceneTree();
    using var uploadJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    using var uploadServer = new RenderingServer(uploadRenderer);
    var uploadWorld = new VoxelWorldNode
    {
        Seed = seed,
        Jobs = uploadJobs,
        Server = uploadServer,
    };
    uploadTree.Root.AddChild(uploadWorld);
    uploadWorld.World!.GenerateAround(0, 0, 1);
    uploadTree.ProcessFrame(1d / 60d);
    Check(
        "单帧区块网格上传受预算限制",
        uploadRenderer.MeshUploadCount is > 0 and <= 2,
        $"uploads={uploadRenderer.MeshUploadCount}");

    var snapshotBudgetWorld = new VoxelWorld(seed, WorldType.Noise);
    snapshotBudgetWorld.GenerateAround(0, 0, 1);
    var snapshotBudgetTimer = Stopwatch.StartNew();
    var snapshotBudgetWork = snapshotBudgetWorld.CreateMeshSnapshot(0, 0)
        ?? throw new InvalidOperationException("无法创建网格快照预算样本");
    snapshotBudgetTimer.Stop();
    snapshotBudgetWork.Snapshot.Dispose();
    Check(
        "单个 24 Section 网格快照复制不超过 8ms",
        snapshotBudgetTimer.Elapsed.TotalMilliseconds < 8d,
        $"elapsed={snapshotBudgetTimer.Elapsed.TotalMilliseconds:F3}ms");

    var lightingWorld = new VoxelWorld(seed, WorldType.Flat);
    lightingWorld.GenerateChunkAt(0, 0);
    var placedLighting = lightingWorld.SetBlockDeferred(4, 20, 4, BlockRegistry.Wood, out _);
    var placedBlockSky = LightingEngine.GetLight(lightingWorld.Store, 4, 20, 4).Sky;
    var scatteredBelow = LightingEngine.GetLight(lightingWorld.Store, 4, 19, 4).Sky == LightingEngine.MaxLight - 1;
    var litAbove = LightingEngine.GetLight(lightingWorld.Store, 4, 21, 4).Sky == LightingEngine.MaxLight;
    var removedLighting = lightingWorld.SetBlockDeferred(4, 20, 4, BlockRegistry.Air, out _);
    var restoredBelow = LightingEngine.GetLight(lightingWorld.Store, 4, 19, 4).Sky == LightingEngine.MaxLight;
    Check(
        "普通方块改动保持散射天空光正确",
        placedLighting && removedLighting && placedBlockSky == 0 && scatteredBelow && litAbove && restoredBelow,
        $"placed={placedBlockSky} below={scatteredBelow}/{restoredBelow} above={litAbove}");

    var repositoryRoot = FindCubitRepositoryRoot();
    var voxelWorldSource = repositoryRoot is null
        ? string.Empty
        : File.ReadAllText(Path.Combine(repositoryRoot, "src", "Cubit.Voxel", "World", "VoxelWorld.cs"));
    var deferredStart = voxelWorldSource.IndexOf("public bool SetBlockDeferred", StringComparison.Ordinal);
    var deferredEnd = deferredStart < 0
        ? -1
        : voxelWorldSource.IndexOf("private void RemeshChunkLocked", deferredStart, StringComparison.Ordinal);
    var deferredSource = deferredStart < 0 || deferredEnd < 0
        ? string.Empty
        : voxelWorldSource[deferredStart..deferredEnd];
    Check(
        "普通挖放同步邻区天空光且方块光按需重算",
        deferredSource.Contains("LightingEngine.RelightSkyAround(Store, cx, cz, lx, y, lz, previous, block)", StringComparison.Ordinal) &&
        deferredSource.Contains("if (previousEmitsLight || nextEmitsLight ||", StringComparison.Ordinal) &&
        deferredSource.Contains("LightingEngine.RelightBlockLight(chunk)", StringComparison.Ordinal),
        "普通方块只同步触及的水平边界；发光体或既有方块光路径例外");

    var lightingSource = repositoryRoot is null
        ? string.Empty
        : File.ReadAllText(Path.Combine(repositoryRoot, "src", "Cubit.Voxel", "World", "LightingEngine.cs"));
    var aroundStart = lightingSource.IndexOf("public static void RelightSkyAround", StringComparison.Ordinal);
    var aroundEnd = aroundStart < 0
        ? -1
        : lightingSource.IndexOf("private static void RelightSky(", aroundStart, StringComparison.Ordinal);
    var aroundSource = aroundStart < 0 || aroundEnd < 0
        ? string.Empty
        : lightingSource[aroundStart..aroundEnd];
    Check(
        "挖放天空光同步只重算四个水平邻区",
        aroundSource.Contains("HorizontalNeighbourOffsets", StringComparison.Ordinal) &&
        !aroundSource.Contains("in NeighbourOffsets", StringComparison.Ordinal),
        "上下方向不对应独立区块，不能重复重算中心区块");

    var commitLightingWorld = new VoxelWorld(seed, WorldType.Flat);
    foreach (var (x, z) in new[] { (1, 0), (-1, 0), (0, 1), (0, -1) })
    {
        commitLightingWorld.GenerateChunkAt(x, z);
    }

    var generatedCenter = commitLightingWorld.CreateGeneratedChunk(0, 0, CancellationToken.None)
        ?? throw new InvalidOperationException("无法创建光照提交基准区块");
    var commitLightingTimer = Stopwatch.StartNew();
    var committedCenter = commitLightingWorld.CommitGeneratedChunk(0, 0, generatedCenter);
    commitLightingTimer.Stop();
    Check(
        "新区块提交的四邻区天空光同步受主线程预算约束",
        committedCenter && commitLightingTimer.Elapsed.TotalMilliseconds < 100d,
        $"elapsed={commitLightingTimer.Elapsed.TotalMilliseconds:F3}ms");

    var streamedLightingWorld = new VoxelWorld(seed, WorldType.Flat);
    foreach (var (x, z) in new[] { (1, 0), (-1, 0), (0, 1), (0, -1) })
    {
        streamedLightingWorld.GenerateChunkAt(x, z);
    }

    using var streamedLightingJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    using var streamedLightingStreamer = new ChunkStreamer(streamedLightingWorld, streamedLightingJobs);
    streamedLightingStreamer.RequestArea(0, 0, 0);
    var maxStreamPumpMilliseconds = 0d;
    var streamedLightingDeadline = Stopwatch.StartNew();
    var streamedCenterMeshed = false;
    while (streamedLightingDeadline.Elapsed < TimeSpan.FromSeconds(10))
    {
        var pumpStart = Stopwatch.GetTimestamp();
        streamedLightingStreamer.Pump();
        maxStreamPumpMilliseconds = Math.Max(
            maxStreamPumpMilliseconds,
            (Stopwatch.GetTimestamp() - pumpStart) * 1000d / Stopwatch.Frequency);
        foreach (var (key, _) in streamedLightingWorld.ConsumePendingMeshes())
        {
            streamedCenterMeshed |= key == (0, 0);
        }

        if (streamedCenterMeshed && streamedLightingStreamer.PendingCount == 0)
        {
            break;
        }

        Thread.Sleep(1);
    }

    Check(
        "流式新区块四邻区天空光同步分帧执行",
        streamedCenterMeshed && streamedLightingStreamer.PendingCount == 0 && maxStreamPumpMilliseconds < 50d,
        $"centerMeshed={streamedCenterMeshed} pending={streamedLightingStreamer.PendingCount} maxPump={maxStreamPumpMilliseconds:F3}ms");

    Console.WriteLine(failures == 0 ? "voxelresponsivenesscheck 全部通过" : $"voxelresponsivenesscheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelJobCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    // 使用反射保持测试可编译，直到生产 API 按设计落地。
    var consumer = typeof(Node).Assembly.GetType("Cubit.Core.Jobs.IJobSystemConsumer");
    var constructor = typeof(ChunkStreamer).GetConstructors()
        .SingleOrDefault(candidate =>
        {
            var parameters = candidate.GetParameters();
            return parameters.Length == 3 &&
                parameters[0].ParameterType == typeof(VoxelWorld) &&
                parameters[1].ParameterType == typeof(JobSystem) &&
                parameters[2].ParameterType == typeof(IChunkStorage) &&
                parameters[2].HasDefaultValue;
        });
    var pump = typeof(ChunkStreamer).GetMethod("Pump", Type.EmptyTypes);
    var generatedChunk = typeof(VoxelWorld).GetMethod("CreateGeneratedChunk", [typeof(int), typeof(int), typeof(CancellationToken)]);
    var commitGenerated = typeof(VoxelWorld).GetMethod("CommitGeneratedChunk", [typeof(int), typeof(int), typeof(Chunk)]);
    var snapshotType = typeof(VoxelWorld).Assembly.GetType("Cubit.Voxel.World.ChunkMeshSnapshot");
    var snapshotFactory = typeof(VoxelWorld).GetMethod("CreateMeshSnapshot", [typeof(int), typeof(int)]);
    var snapshotMesher = snapshotType is null
        ? null
        : typeof(ChunkMesher).GetMethod("Mesh", [snapshotType, typeof(CancellationToken)]);
    var repositoryRoot = FindCubitRepositoryRoot();
    var voxelWorldSource = repositoryRoot is null
        ? string.Empty
        : File.ReadAllText(Path.Combine(repositoryRoot, "src", "Cubit.Voxel", "World", "VoxelWorld.cs"));
    var generatedStart = voxelWorldSource.IndexOf("public Chunk? CreateGeneratedChunk", StringComparison.Ordinal);
    var generatedEnd = generatedStart < 0
        ? -1
        : voxelWorldSource.IndexOf("public bool CommitGeneratedChunk", generatedStart, StringComparison.Ordinal);
    var generatedMethodSource = generatedStart >= 0 && generatedEnd > generatedStart
        ? voxelWorldSource[generatedStart..generatedEnd]
        : string.Empty;

    Check("Core 提供通用 JobSystem 节点注入契约", consumer is not null);
    Check("体素流式器使用宿主 JobSystem 并由主线程 Pump", constructor is not null && pump is not null);
    Check("体素生成可在脱离 Store 的 worker 数据上运行", generatedChunk is not null && commitGenerated is not null);
    Check("worker 生成阶段不读取 ChunkStore", !string.IsNullOrEmpty(generatedMethodSource) && !generatedMethodSource.Contains("Store.", StringComparison.Ordinal));
    Check("体素网格使用不可变快照编译", snapshotType is not null && snapshotFactory is not null && snapshotMesher is not null);

    static void Mix(ref ulong hash, ulong value)
    {
        hash ^= value;
        hash *= 1099511628211UL;
    }

    static (ulong Blocks, ulong Meshes, int Chunks, int MeshCount, int Pending, int DirectMismatches, string DirectKeys, Dictionary<(int X, int Z), ChunkMeshLayers> ByChunk) RunPipeline(uint seed, int workerCount)
    {
        var world = new VoxelWorld(seed, WorldType.Flat);
        using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = workerCount });
        using var streamer = new ChunkStreamer(world, jobs);
        streamer.RequestArea(0, 0, 3);
        var meshes = new Dictionary<(int X, int Z), ChunkMeshLayers>();
        var deadline = Stopwatch.StartNew();
        while (deadline.Elapsed < TimeSpan.FromSeconds(20))
        {
            streamer.Pump();
            foreach (var (key, mesh) in world.ConsumePendingMeshes())
            {
                meshes[key] = mesh;
            }

            if (world.Store.ChunkKeys.Length == 49 && meshes.Count == 49 && streamer.PendingCount == 0)
            {
                break;
            }

            Thread.Sleep(1);
        }

        streamer.Pump();
        foreach (var (key, mesh) in world.ConsumePendingMeshes())
        {
            meshes[key] = mesh;
        }

        ulong blockHash = 1469598103934665603UL;
        foreach (var key in world.Store.ChunkKeys.OrderBy(k => k.Z).ThenBy(k => k.X))
        {
            Mix(ref blockHash, unchecked((ulong)key.X));
            Mix(ref blockHash, unchecked((ulong)key.Z));
        for (var y = Chunk.MinY; y < Chunk.MaxYExclusive; y++)
            {
                for (var z = 0; z < Chunk.SizeZ; z++)
                {
                    for (var x = 0; x < Chunk.SizeX; x++)
                    {
                        Mix(ref blockHash, world.Store.GetChunk(key.X, key.Z)!.GetBlock(x, y, z).Packed);
                    }
                }
            }
        }

        var meshHash = HashVoxelMeshes(meshes);

        var directMismatches = 0;
        var directKeys = new List<string>();
        foreach (var (key, mesh) in meshes)
        {
            var direct = ChunkMesher.Mesh(world.Store, key.X, key.Z);
            if (!MeshLayersEqual(mesh, direct))
            {
                directMismatches++;
                directKeys.Add($"({key.X},{key.Z}) {mesh.Opaque.Vertices.Length}/{direct.Opaque.Vertices.Length}");
            }
        }

        return (blockHash, meshHash, world.Store.ChunkKeys.Length, meshes.Count, streamer.PendingCount, directMismatches, string.Join(',', directKeys), meshes);
    }

    var single = RunPipeline(20260808u, 1);
    var multi = RunPipeline(20260808u, 4);
    Check("单/多 worker 生成 49 个区块并排空", single.Chunks == 49 && single.MeshCount == 49 && single.Pending == 0 &&
        multi.Chunks == 49 && multi.MeshCount == 49 && multi.Pending == 0,
        $"single={single.Chunks}/{single.MeshCount}/{single.Pending} multi={multi.Chunks}/{multi.MeshCount}/{multi.Pending}");
    var mismatch = single.ByChunk.Keys.OrderBy(k => k.Z).ThenBy(k => k.X)
        .Select(key => (Key: key, Different: !multi.ByChunk.TryGetValue(key, out var other) ||
            !MeshLayersEqual(single.ByChunk[key], other)))
        .FirstOrDefault(entry => entry.Different);
    var mismatchText = mismatch.Different ? mismatch.Key.ToString() : "none";
    Check("单/多 worker 区块与网格哈希一致", single.Blocks == multi.Blocks && single.Meshes == multi.Meshes,
        $"blocks={single.Blocks}/{multi.Blocks} meshes={single.Meshes}/{multi.Meshes} mismatch={mismatchText} direct={single.DirectMismatches}/{multi.DirectMismatches} keys={single.DirectKeys}|{multi.DirectKeys}");

    var snapshotWorld = new VoxelWorld(20260808u, WorldType.Flat);
    snapshotWorld.GenerateAround(0, 0, 1);
    var firstWork = snapshotWorld.CreateMeshSnapshot(0, 0);
    var secondWork = snapshotWorld.CreateMeshSnapshot(0, 0);
    ChunkMeshLayers firstMesh = firstWork is { } first
        ? ChunkMesher.Mesh(first.Snapshot, CancellationToken.None)
        : new ChunkMeshLayers(ChunkMeshData.Empty, ChunkMeshData.Empty);
    snapshotWorld.Store.SetBlock(0, 0, 0, BlockRegistry.Air);
    ChunkMeshLayers afterLiveEdit = firstWork is { } edited
        ? ChunkMesher.Mesh(edited.Snapshot, CancellationToken.None)
        : new ChunkMeshLayers(ChunkMeshData.Empty, ChunkMeshData.Empty);
    var staleRejected = firstWork is { } stale && secondWork is { } current &&
        !snapshotWorld.PublishMesh(0, 0, stale.Revision, firstMesh) &&
        snapshotWorld.PublishMesh(0, 0, current.Revision, afterLiveEdit);
    Check("网格快照与后续 live 编辑隔离", MeshLayersEqual(firstMesh, afterLiveEdit));
    Check("旧 revision 不能覆盖新网格", staleRejected);

    var streamerType = typeof(ChunkStreamer);
    var generationRequestType = streamerType.GetNestedType("GenerationRequest", BindingFlags.NonPublic);
    var generationJobType = streamerType.GetNestedType("GenerationJob", BindingFlags.NonPublic);
    var generationJobsField = streamerType.GetField("_generationJobs", BindingFlags.Instance | BindingFlags.NonPublic);
    var disposeFaultHandled = false;
    var disposeQueueCleared = false;
    if (generationRequestType is not null && generationJobType is not null && generationJobsField is not null)
    {
        var disposeWorld = new VoxelWorld(20260808u, WorldType.Flat);
        using var disposeJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var disposeStreamer = new ChunkStreamer(disposeWorld, disposeJobs);
        var failedHandle = disposeJobs.Schedule(_ => throw new InvalidOperationException("dispose fault"), "voxel-dispose-fault");
        _ = SpinWait.SpinUntil(() => failedHandle.IsCompleted, TimeSpan.FromSeconds(5));
        var request = Activator.CreateInstance(
            generationRequestType,
            BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
            null,
            [1L, 0, 0],
            null);
        var generationJob = request is null
            ? null
            : Activator.CreateInstance(
                generationJobType,
                BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic,
                null,
                [request, failedHandle],
                null);
        var generationJobs = generationJobsField.GetValue(disposeStreamer);
        var add = generationJobs?.GetType().GetMethod("Add", [typeof(long), generationJobType]);
        if (generationJob is not null && add is not null)
        {
            add.Invoke(generationJobs, [1L, generationJob]);
            try
            {
                disposeStreamer.Dispose();
            }
            catch (AggregateException)
            {
                disposeFaultHandled = true;
            }

            var count = (int?)generationJobs?.GetType().GetProperty("Count")?.GetValue(generationJobs) ?? -1;
            disposeQueueCleared = count == 0 && disposeStreamer.PendingCount == 0;
        }
    }

    Check(
        "流式器 Dispose 在 worker 异常后仍排空队列并重抛",
        disposeFaultHandled && disposeQueueCleared,
        $"fault={disposeFaultHandled} cleared={disposeQueueCleared}");

    Console.WriteLine(failures == 0 ? "voxeljobcheck 全部通过" : $"voxeljobcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int CompileShaders(string root)
{
    var shaderDirectory = Path.Combine(root, "assets", "shaders");
    var shaderTargets = new[]
    {
        ("world.vert", Silk.NET.Shaderc.ShaderKind.VertexShader, Path.Combine(root, "src", "Cubit.Core", "Shaders", "Spv", "world.vert.spv")),
        ("world_color.vert", Silk.NET.Shaderc.ShaderKind.VertexShader, Path.Combine(root, "src", "Cubit.Core", "Shaders", "Spv", "world_color.vert.spv")),
        ("world.frag", Silk.NET.Shaderc.ShaderKind.FragmentShader, Path.Combine(root, "src", "Cubit.Core", "Shaders", "Spv", "world.frag.spv")),
        ("world_tiled.vert", Silk.NET.Shaderc.ShaderKind.VertexShader, Path.Combine(root, "src", "Cubit.Core", "Shaders", "Spv", "world_tiled.vert.spv")),
        ("world_tiled.frag", Silk.NET.Shaderc.ShaderKind.FragmentShader, Path.Combine(root, "src", "Cubit.Core", "Shaders", "Spv", "world_tiled.frag.spv")),
        ("imgui.vert", Silk.NET.Shaderc.ShaderKind.VertexShader, Path.Combine(root, "src", "Cubit.ImGui", "Shaders", "Spv", "imgui.vert.spv")),
        ("imgui.frag", Silk.NET.Shaderc.ShaderKind.FragmentShader, Path.Combine(root, "src", "Cubit.ImGui", "Shaders", "Spv", "imgui.frag.spv")),
        ("panorama.vert", Silk.NET.Shaderc.ShaderKind.VertexShader, Path.Combine(root, "src", "Cubit.ImGui", "Shaders", "Spv", "panorama.vert.spv")),
        ("panorama.frag", Silk.NET.Shaderc.ShaderKind.FragmentShader, Path.Combine(root, "src", "Cubit.ImGui", "Shaders", "Spv", "panorama.frag.spv")),
    };

    foreach (var (fileName, kind, output) in shaderTargets)
    {
        var input = Path.Combine(shaderDirectory, fileName);
        if (!File.Exists(input))
        {
            Console.Error.WriteLine($"缺少 GLSL 源文件: {input}");
            return 1;
        }

        Directory.CreateDirectory(Path.GetDirectoryName(output)!);
        var spv = ShaderCompiler.CompileGlsl(File.ReadAllText(input), kind, fileName);
        File.WriteAllBytes(output, spv);
        Console.WriteLine($"OK  {fileName} -> {output} ({spv.Length} bytes)");
    }

    Console.WriteLine("着色器编译完成");
    return 0;
}

static string DefaultSampleScenePath() => Path.GetFullPath(Path.Combine(
    Directory.GetCurrentDirectory(),
    "..",
    "我的第一个cubit项目",
    "assets",
    "scenes",
    "demo.cscene"));

static int McpHttpTest(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    Environment.SetEnvironmentVariable("VOXEL_WORLDTYPE", "flat");
    var renderer = new FakeRenderBackend();
    using var session = CreateVoxelProjectSession(renderer, seed);
    var scene = session.Scene;
    var gameHost = new GameSceneMcpHost(scene, null, session.Input);
    var host = new McpEngineHostWithExtensions(
        gameHost,
        [ComposeProjectMcpExtensions(scene)]);

    using var server = new McpHttpServer(host);
    using var http = new HttpClient { BaseAddress = new Uri($"http://127.0.0.1:{server.Port}/") };

    // 1) GET /health
    using var health = WaitForMcpTask(http.GetAsync("/health"), gameHost);
    var healthBody = WaitForMcpTask(health.Content.ReadAsStringAsync(), gameHost);
    Check("GET /health 返回 ok", (int)health.StatusCode == 200 && healthBody == "ok", $"{healthBody}");

    // 2) POST /mcp initialize
    var initResp = PostJson(http, gameHost, "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{}}");
    Check("initialize 返回协议版本", initResp.Contains("2025-11-25") && initResp.Contains("\"id\":1"), initResp[..Math.Min(80, initResp.Length)]);

    // 3) POST /mcp tools/list
    var toolsResp = PostJson(http, gameHost, "{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/list\"}");
    Check("tools/list 返回示例已声明的体素与 Audio 工具", toolsResp.Contains("\"tools\"") && toolsResp.Contains("scene.get_tree") && toolsResp.Contains("capture.stats") && toolsResp.Contains("audio.status"), $"len={toolsResp.Length}");

    // 4) POST /mcp ping
    var pingResp = PostJson(http, gameHost, "{\"jsonrpc\":\"2.0\",\"id\":3,\"method\":\"ping\"}");
    Check("ping 返回空结果", pingResp.Contains("\"result\":{}") && pingResp.Contains("\"id\":3"), pingResp);

    // 5) 通知（无 id）：204 无响应体
    using var notif = WaitForMcpTask(http.PostAsync("/mcp", new StringContent("{\"jsonrpc\":\"2.0\",\"method\":\"notifications/initialized\"}", System.Text.Encoding.UTF8, "application/json")), gameHost);
    var notifBody = WaitForMcpTask(notif.Content.ReadAsStringAsync(), gameHost);
    Check("通知无响应体", (int)notif.StatusCode == 204 && notifBody == "", $"status={(int)notif.StatusCode} body=[{notifBody}]");

    // 6) tools/call 真实调用
    var callResp = PostJson(http, gameHost, "{\"jsonrpc\":\"2.0\",\"id\":4,\"method\":\"tools/call\",\"params\":{\"name\":\"world.get_block\",\"arguments\":{\"x\":24,\"y\":4,\"z\":24}}}");
    Check("tools/call 返回方块", callResp.Contains("草方块") || callResp.Contains("\"text\""), callResp[..Math.Min(80, callResp.Length)]);
    var audioStatus = PostJson(http, gameHost, "{\"jsonrpc\":\"2.0\",\"id\":5,\"method\":\"tools/call\",\"params\":{\"name\":\"audio.status\",\"arguments\":{}}}");
    Check("示例 HTTP MCP 可读取已注入 AudioServer", McpToolText(audioStatus).Contains("activeVoiceCount", StringComparison.Ordinal), audioStatus[..Math.Min(80, audioStatus.Length)]);

    // 并发 HTTP 客户端仍只能通过主线程队列读取同一 SceneTree。
    var parallelRequests = Enumerable.Range(0, 4)
        .Select(index => http.PostAsync(
            "/mcp",
            new StringContent(
                $"{{\"jsonrpc\":\"2.0\",\"id\":{10 + index},\"method\":\"tools/call\",\"params\":{{\"name\":\"scene.get_tree\",\"arguments\":{{}}}}}}",
                System.Text.Encoding.UTF8,
                "application/json")))
        .ToArray();
    var parallelResponses = WaitForMcpTask(Task.WhenAll(parallelRequests), gameHost);
    var parallelBodies = parallelResponses
        .Select(response =>
        {
            using (response)
            {
                return WaitForMcpTask(response.Content.ReadAsStringAsync(), gameHost);
            }
        })
        .ToArray();
    Check(
        "并发 HTTP MCP 请求经同一主线程安全完成",
        parallelBodies.Length == 4 && parallelBodies.All(body => body.Contains("Root", StringComparison.Ordinal) && !body.Contains("所有者线程", StringComparison.Ordinal)),
        $"responses={parallelBodies.Length} pending={gameHost.PumpMcpRequests()}");

    Console.WriteLine(failures == 0 ? "mcphttptest 全部通过" : $"mcphttptest 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static string PostJson(HttpClient http, GameSceneMcpHost host, string json)
{
    using var response = WaitForMcpTask(
        http.PostAsync("/mcp", new StringContent(json, System.Text.Encoding.UTF8, "application/json")),
        host);
    return WaitForMcpTask(response.Content.ReadAsStringAsync(), host);
}

static T WaitForMcpTask<T>(Task<T> task, GameSceneMcpHost host)
{
    var deadline = DateTime.UtcNow.AddSeconds(3);
    while (!task.IsCompleted)
    {
        host.PumpMcpRequests();
        if (DateTime.UtcNow >= deadline)
        {
            throw new TimeoutException("MCP HTTP 测试等待响应超时");
        }

        Thread.Sleep(1);
    }

    host.PumpMcpRequests();
    return task.GetAwaiter().GetResult();
}

static int InputCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var input = new InputServer();

    // Cancel 通过反射断言，确保门禁在 API 尚未存在时也能编译并正确 RED。
    var hasCancel = Enum.TryParse<InputAction>("Cancel", out var cancelAction);
    Check("InputAction.Cancel 存在", hasCancel);
    if (hasCancel)
    {
        input.SetAction(cancelAction, true);
    }

    var def = input.BuildSnapshot();
    var cancelField = typeof(GameInput).GetField("Cancel");
    var cancelValue = cancelField?.FieldType == typeof(bool) && (bool)(cancelField.GetValue(def) ?? false);
    Check("Cancel 进入输入快照", cancelValue);
    var voxelFields = typeof(GameInput).GetFields(BindingFlags.Instance | BindingFlags.Public)
        .Where(field => field.Name is "Break" or "Place" or "SelectedBlock")
        .Select(field => field.Name)
        .ToArray();
    Check("Core 快照无体素字段", voxelFields.Length == 0, string.Join(',', voxelFields));

    input.SetAction(InputAction.Forward, true);
    input.SetAction(InputAction.Up, true);
    var held = input.BuildSnapshot();
    Check("按键按下生效", held.Forward && held.Up && !held.Back, $"f={held.Forward} up={held.Up}");
    input.SetAction(InputAction.Forward, false);
    var released = input.BuildSnapshot();
    Check("按键抬起生效", !released.Forward && released.Up, $"f={released.Forward} up={released.Up}");

    input.AddMouseDelta(3f, -2f);
    input.AddMouseDelta(1.5f, 0.5f);
    var mouse = input.BuildSnapshot();
    Check("鼠标增量累计", MathF.Abs(mouse.MouseDeltaX - 4.5f) < 1e-4 && MathF.Abs(mouse.MouseDeltaY - (-1.5f)) < 1e-4, $"d=({mouse.MouseDeltaX},{mouse.MouseDeltaY})");
    var cleared = input.BuildSnapshot();
    Check("快照后增量清零", cleared.MouseDeltaX == 0 && cleared.MouseDeltaY == 0, $"d=({cleared.MouseDeltaX},{cleared.MouseDeltaY})");

    input.SetMoveAxis(0.8f, -0.8f);
    var stick = input.BuildSnapshot();
    Check("摇杆前推+右移", stick.Forward && stick.Right && !stick.Back && !stick.Left, $"f={stick.Forward} r={stick.Right}");
      input.SetMoveAxis(0f, 0f);
      var stickNeutral = input.BuildSnapshot();
      Check("摇杆回中清空", !stickNeutral.Forward && !stickNeutral.Right, $"f={stickNeutral.Forward} r={stickNeutral.Right}");

      var desktopHostPath = Path.GetFullPath(Path.Combine(
          Directory.GetCurrentDirectory(), "hosts", "Cubit.Sample", "Program.cs"));
      var desktopHostSource = File.ReadAllText(desktopHostPath);
       Check(
           "桌面 A/D 映射符合画面横向方向",
           desktopHostSource.Contains("Key.A => InputAction.Left", StringComparison.Ordinal)
           && desktopHostSource.Contains("Key.D => InputAction.Right", StringComparison.Ordinal));

       var strafeCamera = new FlyCamera(Vector3.Zero, yaw: 0f, pitch: 0f);
       var expectedScreenRight = Vector3.Normalize(Vector3.Cross(strafeCamera.Forward, Vector3.UnitY));
       strafeCamera.ApplyMovement(new GameInput { Right = true }, dt: 1d);
       Check(
           "右移沿相机视图右侧移动",
           Vector3.Dot(Vector3.Normalize(strafeCamera.Position), expectedScreenRight) > 0.999f,
           $"move={strafeCamera.Position} expected={expectedScreenRight}");

       input.AddMouseDelta(2f, 0f);
    input.AddLookDelta(10f, 4f);
    var look = input.BuildSnapshot();
    Check("触摸视角并入快照", MathF.Abs(look.MouseDeltaX - 12f) < 1e-4 && MathF.Abs(look.MouseDeltaY - 4f) < 1e-4, $"d=({look.MouseDeltaX},{look.MouseDeltaY})");

    // 固定模拟只能读取持续动作；视角增量属于渲染帧，不能被物理步提前消费。
    var fixedStepInput = new InputServer();
    fixedStepInput.SetAction(InputAction.Forward, true);
    fixedStepInput.SetMoveAxis(0.8f, 0f);
    fixedStepInput.AddMouseDelta(7f, -3f);
    fixedStepInput.AddLookDelta(2f, 5f);
    var simulationSnapshotMethod = typeof(InputServer).GetMethod("BuildSimulationSnapshot");
    Check(
        "固定步输入快照 API 存在",
        simulationSnapshotMethod?.ReturnType == typeof(GameInput));
    var simulationInput = simulationSnapshotMethod is null
        ? default
        : (GameInput)(simulationSnapshotMethod.Invoke(fixedStepInput, null)
            ?? throw new InvalidOperationException("固定步输入快照不能为空"));
    Check(
        "固定步快照保留持续动作且不带视角增量",
        simulationInput.Forward && simulationInput.Right
        && simulationInput.MouseDeltaX == 0f && simulationInput.MouseDeltaY == 0f,
        $"f={simulationInput.Forward} r={simulationInput.Right} d=({simulationInput.MouseDeltaX},{simulationInput.MouseDeltaY})");
    var renderInputAfterSimulation = fixedStepInput.BuildSnapshot();
    Check(
        "固定步快照不消费鼠标或触摸视角增量",
        MathF.Abs(renderInputAfterSimulation.MouseDeltaX - 9f) < 1e-4f
        && MathF.Abs(renderInputAfterSimulation.MouseDeltaY - 2f) < 1e-4f,
        $"d=({renderInputAfterSimulation.MouseDeltaX},{renderInputAfterSimulation.MouseDeltaY})");

    Console.WriteLine(failures == 0 ? "inputcheck 全部通过" : $"inputcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int TouchCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    Check(
        "触摸映射器拒绝无效视口",
        CaptureException(() => new TouchInputMapper(0, 720)) is ArgumentOutOfRangeException);

    var mapper = new TouchInputMapper(1000, 500, lookSensitivity: 0.5f);
    mapper.PointerDown(10, 100, 250);
    mapper.PointerMove(10, 250, 100);
    var diagonal = mapper.BuildSnapshot();
    Check(
        "左侧触点映射为归一化移动轴",
        diagonal.MoveX > 0.70f && diagonal.MoveY < -0.70f
            && MathF.Sqrt(diagonal.MoveX * diagonal.MoveX + diagonal.MoveY * diagonal.MoveY) <= 1.001f,
        $"move=({diagonal.MoveX:0.###},{diagonal.MoveY:0.###})");

    mapper.PointerUp(10);
    var neutral = mapper.BuildSnapshot();
    Check(
        "左侧触点抬起回中",
        neutral.MoveX == 0f && neutral.MoveY == 0f,
        $"move=({neutral.MoveX:0.###},{neutral.MoveY:0.###})");

    mapper.PointerDown(20, 800, 250);
    mapper.PointerMove(20, 840, 230);
    var look = mapper.BuildSnapshot();
    Check(
        "右侧触点累计视角增量并应用灵敏度",
        MathF.Abs(look.LookDeltaX - 20f) < 1e-4f && MathF.Abs(look.LookDeltaY - (-10f)) < 1e-4f,
        $"look=({look.LookDeltaX:0.###},{look.LookDeltaY:0.###})");

    var lookCleared = mapper.BuildSnapshot();
    Check(
        "视角增量在快照后清零",
        lookCleared.LookDeltaX == 0f && lookCleared.LookDeltaY == 0f,
        $"look=({lookCleared.LookDeltaX:0.###},{lookCleared.LookDeltaY:0.###})");

    mapper.PointerDown(30, 100, 100);
    mapper.PointerDown(31, 200, 200);
    mapper.PointerMove(31, 300, 300);
    var duplicate = mapper.BuildSnapshot();
    Check(
        "重复左侧触点不抢占活动摇杆",
        duplicate.MoveX == 0f && duplicate.MoveY == 0f && duplicate.LookDeltaX == 0f && duplicate.LookDeltaY == 0f,
        $"move=({duplicate.MoveX:0.###},{duplicate.MoveY:0.###}) look=({duplicate.LookDeltaX:0.###},{duplicate.LookDeltaY:0.###})");
    mapper.Reset();

    var input = new InputServer();
    mapper.PointerDown(40, 50, 250);
    mapper.PointerMove(40, 200, 250);
    var state = mapper.BuildSnapshot();
    input.SetMoveAxis(state.MoveX, state.MoveY);
    input.AddLookDelta(state.LookDeltaX, state.LookDeltaY);
    var gameInput = input.BuildSnapshot();
    Check(
        "触摸快照可注入通用 InputServer",
        gameInput.Right && MathF.Abs(gameInput.MouseDeltaX) < 1e-4f,
        $"right={gameInput.Right} delta=({gameInput.MouseDeltaX:0.###},{gameInput.MouseDeltaY:0.###})");

    var queued = new TouchInputEventQueue(1000, 500, lookSensitivity: 0.5f);
    var producer = new Thread(() =>
    {
        queued.EnqueuePointerDown(50, 100, 250);
        queued.EnqueuePointerMove(50, 250, 100);
        queued.EnqueuePointerDown(51, 800, 250);
        queued.EnqueuePointerMove(51, 840, 230);
    });
    producer.Start();
    producer.Join();
    var queuedSnapshot = queued.BuildSnapshot();
    Check(
        "跨线程触摸事件保留移动与视角状态",
        queuedSnapshot.MoveX > 0.70f && queuedSnapshot.MoveY < -0.70f
            && MathF.Abs(queuedSnapshot.LookDeltaX - 20f) < 1e-4f
            && MathF.Abs(queuedSnapshot.LookDeltaY - (-10f)) < 1e-4f,
        $"move=({queuedSnapshot.MoveX:0.###},{queuedSnapshot.MoveY:0.###}) look=({queuedSnapshot.LookDeltaX:0.###},{queuedSnapshot.LookDeltaY:0.###})");

    var repositoryRoot = FindCubitRepositoryRoot() ?? throw new InvalidOperationException("找不到 Cubit-Engine 仓库根目录。");
    var androidHostPath = Path.Combine(repositoryRoot, "hosts", "Cubit.Sample.Android", "MainActivity.cs");
    var androidOverlayPath = Path.Combine(repositoryRoot, "hosts", "Cubit.Sample.Android", "Platform", "MobileTouchOverlay.cs");
    var androidSurfacePath = Path.Combine(repositoryRoot, "hosts", "Cubit.Sample.Android", "Platform", "CubitTouchSurface.cs");
    var androidHostSource = File.ReadAllText(androidHostPath);
    var androidOverlaySource = File.ReadAllText(androidOverlayPath);
    var androidSurfaceSource = File.ReadAllText(androidSurfacePath);
    var androidSceneConstructor = androidHostSource.IndexOf("new GameScene(", StringComparison.Ordinal);
    var androidSharedInput = androidSceneConstructor >= 0
        && androidHostSource.IndexOf("_inputServer,", androidSceneConstructor, StringComparison.Ordinal) > androidSceneConstructor;
    Check(
        "Android 宿主通过共享输入服务驱动 Scene-First 场景",
        androidSharedInput &&
        androidHostSource.Contains("_inputServer.SetMoveAxis(touch.MoveX, touch.MoveY);", StringComparison.Ordinal) &&
        androidHostSource.Contains("_inputServer.AddLookDelta(touch.LookDeltaX, touch.LookDeltaY);", StringComparison.Ordinal) &&
        androidHostSource.Contains("_scene.ProcessFrame(delta);", StringComparison.Ordinal) &&
        !androidHostSource.Contains("_scene.ProcessFrame(delta,", StringComparison.Ordinal));
    Check(
        "Android 宿主安装可见移动端触摸覆盖层",
        File.Exists(androidOverlayPath) &&
        androidHostSource.Contains("InstallMobileTouchOverlay", StringComparison.Ordinal));
    Check(
        "Android 移动覆盖层根据手势持续显示摇杆与按钮按住状态",
        androidHostSource.Contains("BeginMoveGesture", StringComparison.Ordinal) &&
        androidHostSource.Contains("UpdateMoveGesture", StringComparison.Ordinal) &&
        androidHostSource.Contains("EndMoveGesture", StringComparison.Ordinal) &&
        androidHostSource.Contains("SetActionState", StringComparison.Ordinal) &&
        androidOverlaySource.Contains("private int _movePointerId", StringComparison.Ordinal) &&
        androidOverlaySource.Contains("internal void BeginMoveGesture", StringComparison.Ordinal) &&
        androidOverlaySource.Contains("internal void UpdateMoveGesture", StringComparison.Ordinal) &&
        androidOverlaySource.Contains("internal void EndMoveGesture", StringComparison.Ordinal) &&
        androidOverlaySource.Contains("private void DrawJoystick", StringComparison.Ordinal) &&
        androidOverlaySource.Contains("PostInvalidateOnAnimation", StringComparison.Ordinal));
    Check(
        "Android Activity 路由后继续分发 MotionEvent",
        androidHostSource.Contains("public override bool DispatchTouchEvent", StringComparison.Ordinal) &&
        androidHostSource.Contains("QueueMobileTouch(motionEvent);", StringComparison.Ordinal) &&
        androidHostSource.Contains("DrainMobileTouchEvents();", StringComparison.Ordinal) &&
        androidHostSource.Contains("ConcurrentQueue<MobileTouchEvent>", StringComparison.Ordinal) &&
        androidHostSource.Contains("return base.DispatchTouchEvent(motionEvent);", StringComparison.Ordinal) &&
        !androidSurfaceSource.Contains("public override bool DispatchTouchEvent", StringComparison.Ordinal) &&
        !androidSurfaceSource.Contains("_onMotionEvent", StringComparison.Ordinal) &&
        !androidOverlaySource.Contains("public override bool OnTouchEvent", StringComparison.Ordinal) &&
        androidOverlaySource.Contains("Clickable = false", StringComparison.Ordinal));
    Check(
        "Android 子视图不重复向通用触摸队列写入",
        !androidOverlaySource.Contains("EnqueuePointer", StringComparison.Ordinal) &&
        !androidSurfaceSource.Contains("EnqueuePointer", StringComparison.Ordinal));
    var renderResizeStart = androidHostSource.IndexOf("window.Resize +=", StringComparison.Ordinal);
    var viewLoadStart = androidHostSource.IndexOf("view.Load +=", StringComparison.Ordinal);
    var renderResizeSource = renderResizeStart >= 0 && viewLoadStart > renderResizeStart
        ? androidHostSource[renderResizeStart..viewLoadStart]
        : string.Empty;
    Check(
        "Android 触摸映射只使用覆盖层坐标尺寸",
        !renderResizeSource.Contains("PublishTouchViewport", StringComparison.Ordinal) &&
        androidOverlaySource.Contains("protected override void OnSizeChanged", StringComparison.Ordinal) &&
        androidOverlaySource.Contains("_onViewportChanged(w, h)", StringComparison.Ordinal));
    Check(
        "Android 宿主记录通用手势和输入快照诊断",
        androidHostSource.Contains("LogMobileControlTrace", StringComparison.Ordinal) &&
        androidHostSource.Contains("移动手势已路由", StringComparison.Ordinal) &&
        androidHostSource.Contains("视角手势已路由", StringComparison.Ordinal) &&
        androidHostSource.Contains("移动输入快照已进入游戏循环", StringComparison.Ordinal) &&
        androidHostSource.Contains("视角输入快照已进入游戏循环", StringComparison.Ordinal) &&
        !androidHostSource.Contains("VoxelInputState", StringComparison.Ordinal));

    Console.WriteLine(failures == 0 ? "touchcheck 全部通过" : $"touchcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int AndroidLifecycleCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    var androidSource = repositoryRoot is null
        ? string.Empty
        : File.ReadAllText(Path.Combine(repositoryRoot, "hosts", "Cubit.Sample.Android", "MainActivity.cs"));
    var engineSource = repositoryRoot is null
        ? string.Empty
        : File.ReadAllText(Path.Combine(repositoryRoot, "src", "Cubit.Core", "Engine", "Engine.cs"));

    Check(
        "Android 生命周期发布引擎关闭请求",
        androidSource.Contains("private void RequestShutdown()", StringComparison.Ordinal)
            && androidSource.Contains("engine?.RequestClose()", StringComparison.Ordinal));
    Check(
        "Android 游戏循环具备关闭请求消费与托管释放路径",
        androidSource.Contains("Volatile.Read(ref _shutdownRequested)", StringComparison.Ordinal)
            && androidSource.Contains("Shutdown();", StringComparison.Ordinal)
            && androidSource.Contains("scene?.Dispose();", StringComparison.Ordinal)
            && androidSource.Contains("ReleaseAudioFocus();", StringComparison.Ordinal),
        "游戏循环消费请求时才执行 Shutdown；不代表后台直接退出前必然执行");
    Check(
        "Android 后台与销毁路径按设计直接结束进程",
        androidSource.Contains("protected override void OnStop()", StringComparison.Ordinal)
            && androidSource.Contains("protected override void OnDestroy()", StringComparison.Ordinal)
            && androidSource.IndexOf(
                "global::Android.OS.Process.KillProcess(global::Android.OS.Process.MyPid());",
                androidSource.IndexOf("global::Android.OS.Process.KillProcess(global::Android.OS.Process.MyPid());", StringComparison.Ordinal) + 1,
                StringComparison.Ordinal) >= 0,
        "该路径不承诺等待 SceneTree、SDL 或媒体焦点的托管释放");
    Check(
        "Engine 提供跨线程关闭请求",
        engineSource.Contains("public void RequestClose()", StringComparison.Ordinal)
            && engineSource.Contains("_window.Close();", StringComparison.Ordinal));

    Console.WriteLine(failures == 0 ? "androidlifecyclecheck 全部通过" : $"androidlifecyclecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ContentCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var core = typeof(Node).Assembly;
    var severityType = core.GetType("Cubit.Core.Diagnostics.DiagnosticSeverity");
    var diagnosticType = core.GetType("Cubit.Core.Diagnostics.EngineDiagnostic");
    var bagType = core.GetType("Cubit.Core.Diagnostics.DiagnosticBag");
    Check(
        "Core 诊断 API 存在",
        severityType is not null && diagnosticType is not null && bagType is not null);

    var context = new EngineContext();
    var found = context.TryGetService<RenderingServer>(out var missingService);
    Check("TryGetService 不会创建缺失服务", !found && missingService is null);

    Check(
        "诊断代码拒绝非标准字符",
        CaptureException(() => new EngineDiagnostic(
            "Content Invalid",
            DiagnosticSeverity.Error,
            "无效代码")) is ArgumentException);

    var bag = new DiagnosticBag();
    bag.Add(new EngineDiagnostic(
        "content.source.missing",
        DiagnosticSeverity.Error,
        "找不到源文件"));
    var snapshot = bag.Snapshot();
    snapshot[0] = new EngineDiagnostic(
        "content.replaced",
        DiagnosticSeverity.Info,
        "替换快照项");
    Check(
        "诊断袋保留错误且快照隔离",
        bag.HasErrors && bag.Snapshot()[0].Code == "content.source.missing");

    var pluginDiagnostics = new DiagnosticBag();
    var contentPlugin = new CubitContentPlugin(pluginDiagnostics);
    Check(
        "Content 插件标识稳定",
        contentPlugin.Id == "cubit.content" && contentPlugin.Version == new Version(1, 0, 0));
    using (var contentPluginManager = CreateToolPluginManager([contentPlugin]))
    {
        contentPluginManager.Configure(
        [
            new CubitPluginReference
            {
                Id = contentPlugin.Id,
                Version = contentPlugin.Version.ToString(),
            },
        ]);
        Check(
            "Content 插件没有 Node 或 Resource 注册",
            contentPluginManager.Registry.Registrations.Count == 0);
    }

    contentPlugin.Start(new EngineContext());
    Check(
        "缺失内容服务写入确定诊断",
        pluginDiagnostics.Snapshot().Any(item => item.Code == "content.service.missing"));

    var contentRoot = Path.Combine(Path.GetTempPath(), $"cubit_content_check_{Guid.NewGuid():N}");
    try
    {
        Directory.CreateDirectory(contentRoot);
        File.WriteAllText(Path.Combine(contentRoot, "source.unknown"), "content check");
        var contentService = new ContentService([]);
        var missingSource = contentService.Import(new ContentImportRequest(contentRoot, "missing.cscene"));
        var invalidPath = contentService.Import(new ContentImportRequest(contentRoot, "../outside.cscene"));
        var missingImporter = contentService.Import(new ContentImportRequest(contentRoot, "source.unknown"));
        var importMethods = typeof(ContentService).GetMethods(BindingFlags.Public | BindingFlags.Instance)
            .Where(method => method.DeclaringType == typeof(ContentService))
            .ToArray();
        Check(
            "Content 服务仅提供显式 Import 入口",
            importMethods.Length == 1 &&
            importMethods[0].Name == "Import" &&
            importMethods[0].ReturnType == typeof(ContentImportResult) &&
            importMethods[0].GetParameters() is [{ ParameterType: var parameterType }] &&
            parameterType == typeof(ContentImportRequest));
        Check(
            "Content 服务不暴露后台 worker",
            typeof(ContentService).GetProperties(BindingFlags.Public | BindingFlags.Instance)
                .All(property => !property.Name.Contains("worker", StringComparison.OrdinalIgnoreCase)));
        Check("缺失源文件具有确定诊断", HasCode(missingSource, "content.source.missing"));
        Check("越界路径具有确定诊断", HasCode(invalidPath, "content.path.invalid"));
        Check("未知导入器具有确定诊断", HasCode(missingImporter, "content.importer.missing"));

        File.WriteAllText(Path.Combine(contentRoot, "scene.cscene"), "{\"name\":\"Root\"}");
        File.WriteAllText(Path.Combine(contentRoot, "damaged.cscene"), "{");
        var pngFixture = Convert.FromBase64String(
            "iVBORw0KGgoAAAANSUhEUgAAABAAAAAQBAMAAADt3eJSAAAAFVBMVEV5VTq5hVyHh4eWbEpsbGx0WERZPSk6VlZqAAAAa0lEQVR42gXBwQnDQAxFwSd+0FnLgs8+5SyjsA2kgZQgY9j+S8gMM61oM9R6W85NeBDs4BPLSpbk9bBeary02zGC02JIMIpVFCm5kkbtDUPIYt5HnaQuffNxPCuAgfiVH1bk7T5EkTPPovwPGbIOYwnMHcMAAAAASUVORK5CYII=");
        File.WriteAllBytes(Path.Combine(contentRoot, "pixel.png"), pngFixture);
        File.WriteAllBytes(Path.Combine(contentRoot, "damaged.png"), [137, 80, 78, 71]);

        var importService = new ContentService(
        [
            new SceneJsonContentImporter(),
            new PngRgba8ContentImporter(),
        ]);
        var sceneFirst = importService.Import(new ContentImportRequest(contentRoot, "scene.cscene"));
        var sceneSecond = importService.Import(new ContentImportRequest(contentRoot, "scene.cscene"));
        var damagedScene = importService.Import(new ContentImportRequest(contentRoot, "damaged.cscene"));
        ContentImportResult? importedPng = null;
        var importedPngError = CaptureException(() =>
            importedPng = importService.Import(new ContentImportRequest(contentRoot, "pixel.png")));
        ContentImportResult? damagedPng = null;
        var damagedPngError = CaptureException(() =>
            damagedPng = importService.Import(new ContentImportRequest(contentRoot, "damaged.png")));

        Check(
            "场景导入缓存未命中时成功",
            sceneFirst.Succeeded && !sceneFirst.CacheHit && sceneFirst.CacheKey is not null);
        Check(
            "场景导入缓存命中时成功",
            sceneSecond.Succeeded && sceneSecond.CacheHit && sceneSecond.CacheKey == sceneFirst.CacheKey);

        File.WriteAllText(Path.Combine(contentRoot, "same.first"), "same source bytes");
        File.WriteAllText(Path.Combine(contentRoot, "same.second"), "same source bytes");
        var extensionService = new ContentService([new ExtensionSensitiveContentImporter()]);
        var firstExtension = extensionService.Import(new ContentImportRequest(contentRoot, "same.first"));
        var secondExtension = extensionService.Import(new ContentImportRequest(contentRoot, "same.second"));
        Check(
            "同导入器的不同扩展名不能互相命中缓存",
            firstExtension.Succeeded && secondExtension.Succeeded &&
            !firstExtension.CacheHit && !secondExtension.CacheHit &&
            firstExtension.CacheKey != secondExtension.CacheKey &&
            Path.GetExtension(firstExtension.ArtifactPath) == ".first-artifact" &&
            Path.GetExtension(secondExtension.ArtifactPath) == ".second-artifact");
        Check("损坏场景报告导入失败", HasCode(damagedScene, "content.import.failed"));
        Check(
            "PNG 导入不向调用方泄漏解码异常",
            importedPngError is null && damagedPngError is null,
            $"valid={importedPngError?.GetType().FullName ?? "none"}, damaged={damagedPngError?.GetType().FullName ?? "none"}");
        Check("损坏 PNG 报告导入失败", damagedPng is not null && HasCode(damagedPng, "content.import.failed"));

        var pngMetadata = importedPng is null
            ? default
            : JsonDocument.Parse(File.ReadAllText(
                Path.Combine(Path.GetDirectoryName(importedPng.ArtifactPath!)!, "metadata.json"))).RootElement;
        var pngBytes = importedPng?.ArtifactPath is null ? [] : File.ReadAllBytes(importedPng.ArtifactPath);
        Check(
            "PNG 导入产物是精确的 RGBA8 数据",
            importedPng?.Succeeded == true &&
            pngMetadata.GetProperty("width").GetInt32() *
            pngMetadata.GetProperty("height").GetInt32() * 4 == pngBytes.Length &&
            pngMetadata.GetProperty("channels").GetInt32() == 4);

        var inaccessibleDirectory = Path.Combine(contentRoot, "directory.cscene");
        Directory.CreateDirectory(inaccessibleDirectory);
        ContentImportResult? directorySource = null;
        var directorySourceError = CaptureException(() =>
            directorySource = importService.Import(new ContentImportRequest(contentRoot, "directory.cscene")));
        Check(
            "目录源文件不会向调用方泄漏 I/O 异常",
            directorySourceError is null && directorySource is not null && HasCode(directorySource, "content.import.failed"),
            directorySourceError?.GetType().FullName ?? "none");

        var lockedSourcePath = Path.Combine(contentRoot, "locked.cscene");
        File.WriteAllText(lockedSourcePath, "{}");
        ContentImportResult? lockedSource = null;
        Exception? lockedSourceError;
        using (var sourceLock = new FileStream(lockedSourcePath, FileMode.Open, FileAccess.Read, FileShare.None))
        {
            lockedSourceError = CaptureException(() =>
                lockedSource = importService.Import(new ContentImportRequest(contentRoot, "locked.cscene")));
        }

        Check(
            "锁定源文件不会向调用方泄漏 I/O 异常",
            lockedSourceError is null && lockedSource is not null && HasCode(lockedSource, "content.import.failed"),
            lockedSourceError?.GetType().FullName ?? "none");

        File.WriteAllText(Path.Combine(contentRoot, "malformed.probe"), "probe");
        var malformedArtifact = new ContentService([new InvalidArtifactContentImporter()])
            .Import(new ContentImportRequest(contentRoot, "malformed.probe"));
        Check("非法导入工件报告导入失败", HasCode(malformedArtifact, "content.import.failed"));

        var cacheFailureRoot = Path.Combine(Path.GetTempPath(), $"cubit_content_cache_failure_{Guid.NewGuid():N}");
        try
        {
            Directory.CreateDirectory(cacheFailureRoot);
            File.WriteAllText(Path.Combine(cacheFailureRoot, "scene.cscene"), "{}");
            File.WriteAllText(Path.Combine(cacheFailureRoot, "Library"), "block cache directory");
            var cacheFailure = importService.Import(new ContentImportRequest(cacheFailureRoot, "scene.cscene"));
            Check("缓存发布失败具有确定诊断", HasCode(cacheFailure, "content.cache.write"));
        }
        finally
        {
            if (Directory.Exists(cacheFailureRoot))
            {
                Directory.Delete(cacheFailureRoot, true);
            }
        }

        var malformedIndexRoot = Path.Combine(Path.GetTempPath(), $"cubit_content_malformed_index_{Guid.NewGuid():N}");
        try
        {
            Directory.CreateDirectory(Path.Combine(malformedIndexRoot, "Library", "cubit-content"));
            File.WriteAllText(Path.Combine(malformedIndexRoot, "scene.cscene"), "{}");
            File.WriteAllText(
                Path.Combine(malformedIndexRoot, "Library", "cubit-content", "content-index.json"),
                "{\"formatVersion\":1,\"entries\":{\"bad\":null}}");
            ContentImportResult? malformedIndex = null;
            var malformedIndexError = CaptureException(() =>
                malformedIndex = importService.Import(new ContentImportRequest(malformedIndexRoot, "scene.cscene")));
            Check(
                "结构损坏的缓存索引不会向调用方泄漏异常",
                malformedIndexError is null && malformedIndex is not null && HasCode(malformedIndex, "content.cache.write"),
                malformedIndexError?.GetType().FullName ?? "none");
        }
        finally
        {
            if (Directory.Exists(malformedIndexRoot))
            {
                Directory.Delete(malformedIndexRoot, true);
            }
        }

        var forgedIndexRoot = Path.Combine(Path.GetTempPath(), $"cubit_content_forged_index_{Guid.NewGuid():N}");
        try
        {
            Directory.CreateDirectory(forgedIndexRoot);
            File.WriteAllText(Path.Combine(forgedIndexRoot, "scene.cscene"), "{\"name\":\"Forged\"}");
            var original = importService.Import(new ContentImportRequest(forgedIndexRoot, "scene.cscene"));
            File.WriteAllText(Path.Combine(forgedIndexRoot, "secret.txt"), "not a content artifact");
            File.WriteAllText(Path.Combine(forgedIndexRoot, "secret.metadata.json"), "{}");
            var forgedIndex = JsonSerializer.Serialize(
                new
                {
                    formatVersion = 1,
                    entries = new Dictionary<string, object>
                    {
                        [original.CacheKey!] = new
                        {
                            artifactPath = "secret.txt",
                            metadataPath = "secret.metadata.json",
                            importerId = "cubit.scene-json",
                            importerVersion = "1.0.0",
                        },
                    },
                });
            File.WriteAllText(
                Path.Combine(forgedIndexRoot, "Library", "cubit-content", "content-index.json"),
                forgedIndex);
            var forgedResult = importService.Import(new ContentImportRequest(forgedIndexRoot, "scene.cscene"));
            Check(
                "伪造索引不能把项目内任意文件当作缓存命中",
                forgedResult.Succeeded && !forgedResult.CacheHit &&
                !string.Equals(forgedResult.ArtifactPath, Path.Combine(forgedIndexRoot, "secret.txt"), StringComparison.OrdinalIgnoreCase));
        }
        finally
        {
            if (Directory.Exists(forgedIndexRoot))
            {
                Directory.Delete(forgedIndexRoot, true);
            }
        }

        var concurrentRoot = Path.Combine(Path.GetTempPath(), $"cubit_content_concurrent_{Guid.NewGuid():N}");
        try
        {
            Directory.CreateDirectory(concurrentRoot);
            File.WriteAllText(Path.Combine(concurrentRoot, "first.race"), "first");
            File.WriteAllText(Path.Combine(concurrentRoot, "second.race"), "second");
            using var concurrentImporter = new CoordinatedContentImporter();
            var firstConcurrentService = new ContentService([concurrentImporter]);
            var secondConcurrentService = new ContentService([concurrentImporter]);
            using var start = new ManualResetEventSlim(false);
            var firstImport = Task.Run(() =>
            {
                start.Wait();
                return firstConcurrentService.Import(new ContentImportRequest(concurrentRoot, "first.race"));
            });
            var secondImport = Task.Run(() =>
            {
                start.Wait();
                return secondConcurrentService.Import(new ContentImportRequest(concurrentRoot, "second.race"));
            });
            start.Set();
            _ = concurrentImporter.WaitForBothCalls(TimeSpan.FromMilliseconds(500));
            concurrentImporter.Release();
            Task.WaitAll(firstImport, secondImport);
            var verificationService = new ContentService([concurrentImporter]);
            var firstCached = verificationService.Import(new ContentImportRequest(concurrentRoot, "first.race"));
            var secondCached = verificationService.Import(new ContentImportRequest(concurrentRoot, "second.race"));
            Check(
                "跨服务实例并发导入保留全部索引条目",
                firstImport.Result.Succeeded && secondImport.Result.Succeeded &&
                firstCached.Succeeded && firstCached.CacheHit &&
                secondCached.Succeeded && secondCached.CacheHit);
        }
        finally
        {
            if (Directory.Exists(concurrentRoot))
            {
                Directory.Delete(concurrentRoot, true);
            }
        }

        var projectIoRoot = Path.Combine(Path.GetTempPath(), $"cubit_content_project_io_{Guid.NewGuid():N}");
        var projectIoLinkRoot = Path.Combine(Path.GetTempPath(), $"cubit_content_project_io_link_{Guid.NewGuid():N}");
        var projectIoOutside = Path.Combine(Path.GetTempPath(), $"cubit_content_project_io_outside_{Guid.NewGuid():N}");
        try
        {
            Directory.CreateDirectory(projectIoRoot);
            var validWriteError = InvokeAtomicProjectWrite(
                projectIoRoot,
                "Library/cubit-content/atomic.bin",
                new byte[] { 1, 2, 3 });
            var validWriteBytes = validWriteError is null
                ? ProjectIO.ReadProjectFileBytes(projectIoRoot, "Library/cubit-content/atomic.bin")
                : [];
            Check(
                "Core 原子项目写入可发布并回读",
                validWriteError is null && validWriteBytes.SequenceEqual(new byte[] { 1, 2, 3 }),
                validWriteError?.GetType().FullName ?? "none");

            Directory.CreateDirectory(projectIoLinkRoot);
            Directory.CreateDirectory(projectIoOutside);
            CreateDirectoryJunction(Path.Combine(projectIoLinkRoot, "Library"), projectIoOutside);
            var linkedWriteError = InvokeAtomicProjectWrite(
                projectIoLinkRoot,
                "Library/cubit-content/escaped.bin",
                new byte[] { 4 });
            Check(
                "Core 原子项目写入拒绝缓存目录 Junction",
                linkedWriteError is InvalidDataException &&
                !File.Exists(Path.Combine(projectIoOutside, "cubit-content", "escaped.bin")),
                linkedWriteError?.GetType().FullName ?? "none");
        }
        finally
        {
            DeleteDirectoryJunction(Path.Combine(projectIoLinkRoot, "Library"));
            if (Directory.Exists(projectIoRoot))
            {
                Directory.Delete(projectIoRoot, true);
            }

            if (Directory.Exists(projectIoLinkRoot))
            {
                Directory.Delete(projectIoLinkRoot, true);
            }

            if (Directory.Exists(projectIoOutside))
            {
                Directory.Delete(projectIoOutside, true);
            }
        }
    }
    finally
    {
        if (Directory.Exists(contentRoot))
        {
            Directory.Delete(contentRoot, true);
        }
    }

    return failures == 0 ? 0 : 1;

    static bool HasCode(ContentImportResult result, string code) =>
        result.Diagnostics.Any(item => item.Code == code);

    static Exception? InvokeAtomicProjectWrite(string projectDirectory, string relativePath, byte[] data)
    {
        var method = typeof(ProjectIO).GetMethod(
            "WriteProjectFileBytesAtomically",
            BindingFlags.Public | BindingFlags.Static,
            [typeof(string), typeof(string), typeof(byte[])]);
        if (method is null)
        {
            return new MissingMethodException(typeof(ProjectIO).FullName, "WriteProjectFileBytesAtomically");
        }

        try
        {
            method.Invoke(null, [projectDirectory, relativePath, data]);
            return null;
        }
        catch (TargetInvocationException exception)
        {
            return exception.InnerException ?? exception;
        }
    }
}

static int ShaderPackCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    Check("定位 Cubit 仓库根目录", repositoryRoot is not null, repositoryRoot ?? "missing");
    if (repositoryRoot is null)
    {
        return 1;
    }

    var coreProjectPath = Path.Combine(repositoryRoot, "src", "Cubit.Core", "Cubit.Core.csproj");
    var coreSourceDirectory = Path.Combine(repositoryRoot, "src", "Cubit.Core");
    var editorProjectPath = Path.Combine(repositoryRoot, "src", "Cubit.Editor", "Cubit.Editor.csproj");
    var sharedImGuiProjectPath = Path.Combine(repositoryRoot, "src", "Cubit.ImGui", "Cubit.ImGui.csproj");
    var sharedImGuiSourceDirectory = Path.Combine(repositoryRoot, "src", "Cubit.ImGui");
    var vertexSpvPath = Path.Combine(sharedImGuiSourceDirectory, "Shaders", "Spv", "imgui.vert.spv");
    var fragmentSpvPath = Path.Combine(sharedImGuiSourceDirectory, "Shaders", "Spv", "imgui.frag.spv");

    var coreProject = File.Exists(coreProjectPath) ? File.ReadAllText(coreProjectPath) : string.Empty;
    Check(
        "Core 项目不再引用 Silk.NET.Shaderc",
        !coreProject.Contains("Silk.NET.Shaderc", StringComparison.Ordinal),
        coreProjectPath);

    var coreShadercSources = Directory.Exists(coreSourceDirectory)
        ? Directory.GetFiles(coreSourceDirectory, "*.cs", SearchOption.AllDirectories)
            .Where(path => File.ReadAllText(path).Contains("Silk.NET.Shaderc", StringComparison.Ordinal) ||
                           File.ReadAllText(path).Contains("ShaderCompiler", StringComparison.Ordinal))
            .Select(Path.GetFileName)
            .ToArray()
        : [];
    Check(
        "Core 源码不保留 Shaderc 编译路径",
        coreShadercSources.Length == 0,
        string.Join(',', coreShadercSources));

    var sharedImGuiProject = File.Exists(sharedImGuiProjectPath) ? File.ReadAllText(sharedImGuiProjectPath) : string.Empty;
    Check(
        "共享 ImGui 程序集声明嵌入 SPIR-V",
        sharedImGuiProject.Contains("Shaders\\Spv\\*.spv", StringComparison.Ordinal),
        sharedImGuiProjectPath);

    var shaderResourcesValid = IsSpirvFile(vertexSpvPath) && IsSpirvFile(fragmentSpvPath);
    Check(
        "共享 ImGui SPIR-V 资源完整且有效",
        shaderResourcesValid,
        $"vert={DescribeSpirv(vertexSpvPath)} frag={DescribeSpirv(fragmentSpvPath)}");

    var sharedImGuiAssembly = typeof(Cubit.ImGui.Rendering.ImGuiRenderer).Assembly;
    var sharedImGuiResourceNames = sharedImGuiAssembly.GetManifestResourceNames();
    var sharedImGuiEmbeddedShaders = new[]
    {
        "Cubit.ImGui.Shaders.Spv.imgui.vert.spv",
        "Cubit.ImGui.Shaders.Spv.imgui.frag.spv",
    };
    Check(
        "已构建共享 ImGui 程序集嵌入 SPIR-V",
        sharedImGuiEmbeddedShaders.All(sharedImGuiResourceNames.Contains),
        string.Join(',', sharedImGuiResourceNames.Where(name => name.Contains("imgui", StringComparison.OrdinalIgnoreCase))));

    var editorAssembly = typeof(ProjectSceneSession).Assembly;
    var editorShadercReferences = editorAssembly.GetReferencedAssemblies()
        .Where(reference => string.Equals(reference.Name, "Silk.NET.Shaderc", StringComparison.Ordinal))
        .Select(reference => reference.Name)
        .ToArray();
    Check("已构建 Editor 程序集不引用 Shaderc", editorShadercReferences.Length == 0, string.Join(',', editorShadercReferences));

    var sharedImGuiShadercReferences = sharedImGuiAssembly.GetReferencedAssemblies()
        .Where(reference => string.Equals(reference.Name, "Silk.NET.Shaderc", StringComparison.Ordinal))
        .Select(reference => reference.Name)
        .ToArray();
    Check("已构建共享 ImGui 程序集不引用 Shaderc", sharedImGuiShadercReferences.Length == 0, string.Join(',', sharedImGuiShadercReferences));

    var imGuiRendererPath = Path.Combine(sharedImGuiSourceDirectory, "ImGuiRenderer.cs");
    var imGuiRenderer = File.Exists(imGuiRendererPath) ? File.ReadAllText(imGuiRendererPath) : string.Empty;
    Check(
        "共享 ImGui 运行时不再动态编译 GLSL",
        !imGuiRenderer.Contains("Silk.NET.Shaderc", StringComparison.Ordinal) &&
        !imGuiRenderer.Contains("CompileGlsl", StringComparison.Ordinal) &&
        !imGuiRenderer.Contains("ImGuiVertexShader", StringComparison.Ordinal) &&
        !imGuiRenderer.Contains("ImGuiFragmentShader", StringComparison.Ordinal),
        imGuiRendererPath);

    var apkDirectory = Path.Combine(
        repositoryRoot,
        "hosts",
        "Cubit.Sample.Android",
        "bin",
        "Debug",
        "net9.0-android",
        "android-arm64");
    var apkPaths = new[]
    {
        Path.Combine(apkDirectory, "com.cubit.sample.apk"),
        Path.Combine(apkDirectory, "com.cubit.sample-Signed.apk"),
    };
    Check(
        "Android 签名与未签名 APK 均可供 Shaderc 打包审计",
        apkPaths.All(File.Exists),
        string.Join(',', apkPaths.Where(path => !File.Exists(path))));
    foreach (var apkPath in apkPaths.Where(File.Exists))
    {
        using var apk = ZipFile.OpenRead(apkPath);
        var shadercEntries = apk.Entries
            .Where(entry => entry.FullName.Contains("shaderc", StringComparison.OrdinalIgnoreCase))
            .Select(entry => entry.FullName)
            .ToArray();
        Check(
            $"Android APK 不携带 Shaderc 原生库: {Path.GetFileName(apkPath)}",
            shadercEntries.Length == 0,
            string.Join(',', shadercEntries));
    }

    Console.WriteLine(failures == 0 ? "shaderpackcheck 全部通过" : $"shaderpackcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static bool IsSpirvFile(string path)
    {
        if (!File.Exists(path))
        {
            return false;
        }

        var bytes = File.ReadAllBytes(path);
        return bytes.Length >= sizeof(uint) && BinaryPrimitives.ReadUInt32LittleEndian(bytes) == 0x07230203;
    }

    static string DescribeSpirv(string path)
    {
        return File.Exists(path) ? $"{new FileInfo(path).Length} bytes" : "missing";
    }
}

static int AndroidPackageCheck()
{
    const string packageId = "Silk.NET.Windowing.Sdl";
    const string packageVersion = "2.23.1-cubit.3";
    const string packageFileName = "Silk.NET.Windowing.Sdl.2.23.1-cubit.3.nupkg";
    const string androidLibraryPath = "lib/net7.0-android33.0/Silk.NET.Windowing.Sdl.aar";
    const string androidBindingPath = "lib/net7.0-android33.0/Silk.NET.Windowing.Sdl.dll";
    const string provenancePath = "CUBIT-ANDROID-16KB.md";
    const string upstreamPackageHash = "FD6E4417F99E64EC6569818404C90E54E45857CD9B412F98CCA01DC97EA59E14";
    const string replacementAarHash = "BDAC2E43CBD6E13143F22C349A46B28BDB824046C946BB559C3224D097550C7E";
    const string expectedSdlVersion = "2.32.10";
    const string expectedArm64SdlHash = "FE6A6A91CFEA9E4938EE440A2FE9DCA5D51D4F7BEEC8EA5EEDEF37AAAB3F1CC9";
    const string androidTarget = "net9.0-android35.0";
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    Check("定位 Cubit 仓库根目录", repositoryRoot is not null, repositoryRoot ?? "missing");
    if (repositoryRoot is null)
    {
        return 1;
    }

    var workspaceRoot = Directory.GetParent(repositoryRoot)?.FullName;
    Check("定位工作区根目录", workspaceRoot is not null, workspaceRoot ?? "missing");
    if (workspaceRoot is null)
    {
        return 1;
    }

    var androidProjectDirectory = Path.Combine(repositoryRoot, "hosts", "Cubit.Sample.Android");
    var androidProjectPath = Path.Combine(androidProjectDirectory, "Cubit.Sample.Android.csproj");
    var lockFilePath = Path.Combine(androidProjectDirectory, "packages.lock.json");
    var assetsFilePath = Path.Combine(androidProjectDirectory, "obj", "project.assets.json");
    var packagePath = Path.Combine(androidProjectDirectory, "NativePackages", packageFileName);

    Check("定位 Android sample 项目文件", File.Exists(androidProjectPath), androidProjectPath);
    Check("定位 Android 锁定依赖文件", File.Exists(lockFilePath), lockFilePath);
    Check("定位版本化本地 SDL 包", File.Exists(packagePath), packagePath);
    var projectDocument = LoadXmlDocument(androidProjectPath, Check, "读取 Android sample 项目 XML");
    var projectRoot = projectDocument?.Root;
    var packageReferences = projectRoot is null
        ? []
        : projectRoot.Descendants("PackageReference")
            .Where(reference => string.Equals(reference.Attribute("Include")?.Value, packageId, StringComparison.OrdinalIgnoreCase))
            .ToArray();
    var directReference = packageReferences.SingleOrDefault();
    Check(
        "Android sample 仅有一个本地 SDL 直接包引用",
        packageReferences.Length == 1 && directReference is not null,
        $"count={packageReferences.Length}");
    Check(
        "Android sample 显式锁定本地 SDL 包版本",
        string.Equals(directReference?.Attribute("Version")?.Value, packageVersion, StringComparison.Ordinal),
        directReference?.Attribute("Version")?.Value ?? "missing");
    var excludedAssets = directReference?.Attribute("ExcludeAssets")?.Value ?? string.Empty;
    Check(
        "Android sample 不排除本地 SDL 包资产",
        !excludedAssets.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Any(asset => asset.Equals("all", StringComparison.OrdinalIgnoreCase) ||
                          asset.Equals("compile", StringComparison.OrdinalIgnoreCase) ||
                          asset.Equals("runtime", StringComparison.OrdinalIgnoreCase) ||
                          asset.Equals("native", StringComparison.OrdinalIgnoreCase)),
        string.IsNullOrWhiteSpace(excludedAssets) ? "none" : excludedAssets);
    var localSource = projectRoot?.Elements("PropertyGroup")
        .Elements("RestoreAdditionalProjectSources")
        .Select(element => element.Value)
        .SingleOrDefault();
    Check(
        "Android sample 仅通过项目本地源解析 SDL 包",
        !string.IsNullOrWhiteSpace(localSource) && localSource.Contains("$(MSBuildProjectDirectory)\\NativePackages", StringComparison.Ordinal),
        localSource ?? "missing");
    var manualReferences = projectRoot is null
        ? []
        : projectRoot.Descendants("Reference")
            .Where(reference => string.Equals(reference.Attribute("Include")?.Value, packageId, StringComparison.OrdinalIgnoreCase))
            .ToArray();
    Check("Android sample 不保留手工 SDL 绑定 DLL 引用", manualReferences.Length == 0, $"count={manualReferences.Length}");
    var manualLibraries = projectRoot is null
        ? []
        : projectRoot.Descendants("AndroidLibrary")
            .Where(library => library.Attributes().Any(attribute => attribute.Value.Contains("Silk.NET.Windowing.Sdl", StringComparison.OrdinalIgnoreCase)))
            .ToArray();
    Check("Android sample 不保留手工 SDL AndroidLibrary", manualLibraries.Length == 0, $"count={manualLibraries.Length}");
    var nativeDirectory = Path.Combine(androidProjectDirectory, "Native");
    var legacySdlAssets = Directory.Exists(nativeDirectory)
        ? Directory.EnumerateFiles(nativeDirectory, "*", SearchOption.AllDirectories)
            .Where(path => Path.GetFileName(path).Contains("Silk.NET.Windowing.Sdl", StringComparison.OrdinalIgnoreCase) &&
                           (path.EndsWith(".aar", StringComparison.OrdinalIgnoreCase) || path.EndsWith(".dll", StringComparison.OrdinalIgnoreCase)))
            .ToArray()
        : [];
    Check("Android sample Native 目录不保留 SDL 裸资产", legacySdlAssets.Length == 0, string.Join(';', legacySdlAssets));

    if (File.Exists(packagePath))
    {
        try
        {
            using var package = ZipFile.OpenRead(packagePath);
            var nuspec = package.Entries.SingleOrDefault(entry =>
                entry.FullName.Equals("Silk.NET.Windowing.Sdl.nuspec", StringComparison.OrdinalIgnoreCase));
            var packageEntries = package.Entries.Select(entry => entry.FullName).ToHashSet(StringComparer.OrdinalIgnoreCase);
            Check("本地 SDL 包只包含一个 Android AAR", packageEntries.Count(entry => entry.EndsWith(".aar", StringComparison.OrdinalIgnoreCase)) == 1, androidLibraryPath);
            Check("本地 SDL 包包含 Android AAR", packageEntries.Contains(androidLibraryPath), androidLibraryPath);
            Check("本地 SDL 包包含 Android 绑定 DLL", packageEntries.Contains(androidBindingPath), androidBindingPath);
            AuditSdlVersionContract(package, androidLibraryPath, expectedSdlVersion, expectedArm64SdlHash, Check);
            Check("本地 SDL 包不保留上游签名", !packageEntries.Contains(".signature.p7s"), ".signature.p7s");
            var provenance = package.Entries.SingleOrDefault(entry =>
                entry.FullName.Equals(provenancePath, StringComparison.OrdinalIgnoreCase));
            Check("本地 SDL 包包含重建来源说明", provenance is not null, provenancePath);
            if (provenance is not null)
            {
                using var reader = new StreamReader(provenance.Open());
                var provenanceText = reader.ReadToEnd();
                Check(
                    "本地 SDL 包记录正确的上游包哈希",
                    provenanceText.Contains($"Official upstream nupkg SHA-256: `{upstreamPackageHash}`", StringComparison.Ordinal),
                    upstreamPackageHash);
                Check(
                    "本地 SDL 包记录替换 AAR 哈希",
                    provenanceText.Contains($"Replacement AAR SHA-256: `{replacementAarHash}`", StringComparison.Ordinal),
                    replacementAarHash);
            }

            var coreProperties = package.Entries.SingleOrDefault(entry =>
                entry.FullName.StartsWith("package/services/metadata/core-properties/", StringComparison.OrdinalIgnoreCase) &&
                entry.FullName.EndsWith(".psmdcp", StringComparison.OrdinalIgnoreCase));
            Check("本地 SDL 包包含核心元数据", coreProperties is not null, "package/services/metadata/core-properties/*.psmdcp");
            if (coreProperties is not null)
            {
                using var reader = new StreamReader(coreProperties.Open());
                var corePropertiesDocument = XDocument.Load(reader);
                Check(
                    "本地 SDL 包核心元数据版本与锁定版本一致",
                    corePropertiesDocument.Descendants().Any(element => element.Name.LocalName == "version" && element.Value == packageVersion),
                    packageVersion);
            }

            if (nuspec is not null)
            {
                using var reader = new StreamReader(nuspec.Open());
                var nuspecDocument = XDocument.Load(reader);
                Check("本地 SDL 包保持相同 PackageId", nuspecDocument.Descendants().Any(element => element.Name.LocalName == "id" && element.Value == packageId), packageId);
                Check("本地 SDL 包使用高于上游的修订版本", nuspecDocument.Descendants().Any(element => element.Name.LocalName == "version" && element.Value == packageVersion), packageVersion);
            }
            else
            {
                Check("本地 SDL 包包含 nuspec", false, "Silk.NET.Windowing.Sdl.nuspec");
            }
        }
        catch (InvalidDataException exception)
        {
            Check("本地 SDL 包可读取", false, exception.Message);
        }
    }

    var packageSha512 = File.Exists(packagePath) ? Convert.ToBase64String(SHA512.HashData(File.ReadAllBytes(packagePath))) : string.Empty;
    if (File.Exists(lockFilePath))
    {
        try
        {
            using var lockDocument = JsonDocument.Parse(File.ReadAllText(lockFilePath));
            var lockDependencies = lockDocument.RootElement.GetProperty("dependencies");
            var targetDependencies = lockDependencies.TryGetProperty(androidTarget, out var target) ? target : default;
            var lockEntry = targetDependencies.ValueKind == JsonValueKind.Object && targetDependencies.TryGetProperty(packageId, out var entry) ? entry : default;
            Check(
                "Android 锁文件将本地 SDL 作为直接依赖",
                lockEntry.ValueKind == JsonValueKind.Object && lockEntry.TryGetProperty("type", out var type) && type.GetString() == "Direct",
                lockEntry.ValueKind == JsonValueKind.Object ? lockEntry.GetRawText() : "missing");
            Check(
                "锁定依赖解析为本地 SDL 修订版本",
                lockEntry.ValueKind == JsonValueKind.Object &&
                lockEntry.TryGetProperty("requested", out var requested) && requested.GetString() == $"[{packageVersion}, )" &&
                lockEntry.TryGetProperty("resolved", out var resolved) && resolved.GetString() == packageVersion,
                packageVersion);
            Check(
                "锁文件哈希绑定项目本地 SDL 包",
                lockEntry.ValueKind == JsonValueKind.Object &&
                lockEntry.TryGetProperty("contentHash", out var contentHash) && contentHash.GetString() == packageSha512,
                packageSha512);
        }
        catch (JsonException exception)
        {
            Check("Android 锁文件可读取", false, exception.Message);
        }
    }

    if (File.Exists(assetsFilePath))
    {
        try
        {
            using var assetsDocument = JsonDocument.Parse(File.ReadAllText(assetsFilePath));
            var targets = assetsDocument.RootElement.GetProperty("targets");
            var targetEntry = targets.TryGetProperty(androidTarget, out var target) ? target : default;
            var selectedAsset = targetEntry.ValueKind == JsonValueKind.Object &&
                targetEntry.TryGetProperty($"{packageId}/{packageVersion}", out var packageTarget) ? packageTarget : default;
            Check("Android assets 只选择本地 SDL 修订包", selectedAsset.ValueKind == JsonValueKind.Object, packageVersion);
            var compileAsset = selectedAsset.ValueKind == JsonValueKind.Object && selectedAsset.TryGetProperty("compile", out var compile)
                ? compile
                : default;
            var hasRelatedAar = compileAsset.ValueKind == JsonValueKind.Object && compileAsset.EnumerateObject().Any(asset =>
                asset.Name == androidBindingPath && asset.Value.TryGetProperty("related", out var related) &&
                related.GetString()?.Split(';').Contains(".aar", StringComparer.OrdinalIgnoreCase) == true);
            Check("Android assets 将 SDL 绑定 DLL 关联到 AAR", hasRelatedAar, androidBindingPath);
        }
        catch (JsonException exception)
        {
            Check("Android assets 文件可读取", false, exception.Message);
        }
    }

    var apkDirectory = Path.Combine(androidProjectDirectory, "bin", "Debug", "net9.0-android", "android-arm64");
    var apkPath = Directory.Exists(apkDirectory)
        ? Directory.EnumerateFiles(apkDirectory, "*.apk", SearchOption.TopDirectoryOnly)
            .OrderByDescending(File.GetLastWriteTimeUtc)
            .FirstOrDefault()
        : null;
    Check("定位 Android Debug APK", apkPath is not null, apkDirectory);
    if (apkPath is not null)
    {
        try
        {
            using var apk = ZipFile.OpenRead(apkPath);
            Check(
                "Android APK 保留 OGG/Vorbis 托管解码器",
                apk.Entries.Any(entry => entry.FullName.Equals("lib/arm64-v8a/lib_NVorbis.dll.so", StringComparison.Ordinal)),
                apkPath);
        }
        catch (InvalidDataException exception)
        {
            Check("Android Debug APK 可读取", false, exception.Message);
        }
    }

    Console.WriteLine(failures == 0 ? "androidpackagecheck 全部通过" : $"androidpackagecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static XDocument? LoadXmlDocument(string path, Action<string, bool, string> check, string name)
    {
        if (!File.Exists(path))
        {
            return null;
        }

        try
        {
            return XDocument.Load(path);
        }
        catch (Exception exception) when (exception is IOException or System.Xml.XmlException)
        {
            check(name, false, exception.Message);
            return null;
        }
    }

    static void AuditSdlVersionContract(
        ZipArchive package,
        string aarPath,
        string expectedVersion,
        string expectedArm64Hash,
        Action<string, bool, string> check)
    {
        var aarEntry = package.GetEntry(aarPath);
        if (aarEntry is null)
        {
            check("SDL AAR 可读取 Java/native 版本契约", false, aarPath);
            return;
        }

        using var aarBytes = new MemoryStream();
        using (var aarStream = aarEntry.Open())
        {
            aarStream.CopyTo(aarBytes);
        }

        aarBytes.Position = 0;
        using var aar = new ZipArchive(aarBytes, ZipArchiveMode.Read, leaveOpen: false);
        var activityEntry = aar.GetEntry("classes.jar");
        var nativeEntry = aar.GetEntry("jni/arm64-v8a/libSDL2.so");
        check("SDL AAR 包含 Java classes.jar", activityEntry is not null, "classes.jar");
        check("SDL AAR 包含 ARM64 SDL 原生库", nativeEntry is not null, "jni/arm64-v8a/libSDL2.so");
        if (activityEntry is null || nativeEntry is null)
        {
            return;
        }

        byte[] activityJarBytes;
        byte[] nativeBytes;
        using (var activityJarStream = activityEntry.Open())
        using (var activityJarBuffer = new MemoryStream())
        {
            activityJarStream.CopyTo(activityJarBuffer);
            activityJarBytes = activityJarBuffer.ToArray();
        }

        using (var nativeStream = nativeEntry.Open())
        using (var nativeBuffer = new MemoryStream())
        {
            nativeStream.CopyTo(nativeBuffer);
            nativeBytes = nativeBuffer.ToArray();
        }

        string? javaVersion = null;
        try
        {
            using var activityJar = new ZipArchive(new MemoryStream(activityJarBytes, writable: false), ZipArchiveMode.Read);
            var activityClass = activityJar.GetEntry("org/libsdl/app/SDLActivity.class");
            check("SDL Java 包含 SDLActivity", activityClass is not null, "org/libsdl/app/SDLActivity.class");
            if (activityClass is not null)
            {
                using var activityClassStream = activityClass.Open();
                using var activityClassBuffer = new MemoryStream();
                activityClassStream.CopyTo(activityClassBuffer);
                javaVersion = ReadSdlActivityVersion(activityClassBuffer.ToArray());
            }
        }
        catch (InvalidDataException exception)
        {
            check("SDL Java 版本可解析", false, exception.Message);
        }

        check("SDL Java 版本与本地修订一致", javaVersion == expectedVersion, javaVersion ?? "missing");
        var nativeHash = Convert.ToHexString(SHA256.HashData(nativeBytes));
        check("SDL ARM64 原生库为已验证版本", nativeHash == expectedArm64Hash, nativeHash);
        check(
            "SDL Java/native 版本契约一致",
            javaVersion == expectedVersion && nativeHash == expectedArm64Hash,
            $"java={javaVersion ?? "missing"}; native={expectedVersion}");
    }

    static string ReadSdlActivityVersion(byte[] classBytes)
    {
        var data = classBytes.AsSpan();
        var offset = 0;
        if (ReadUInt32(data, ref offset) != 0xCAFEBABE)
        {
            throw new InvalidDataException("SDLActivity.class 缺少 Java class magic。");
        }

        _ = ReadUInt16(data, ref offset);
        _ = ReadUInt16(data, ref offset);
        var constantPool = new object?[ReadUInt16(data, ref offset)];
        for (var index = 1; index < constantPool.Length; index++)
        {
            var tag = ReadByte(data, ref offset);
            switch (tag)
            {
                case 1:
                {
                    var length = ReadUInt16(data, ref offset);
                    EnsureAvailable(data, offset, length);
                    constantPool[index] = System.Text.Encoding.UTF8.GetString(data.Slice(offset, length));
                    offset += length;
                    break;
                }
                case 3:
                    constantPool[index] = unchecked((int)ReadUInt32(data, ref offset));
                    break;
                case 4:
                case 9:
                case 10:
                case 11:
                case 12:
                case 17:
                case 18:
                    Skip(data, ref offset, 4);
                    break;
                case 5:
                case 6:
                    Skip(data, ref offset, 8);
                    index++;
                    break;
                case 7:
                case 8:
                case 16:
                case 19:
                case 20:
                    Skip(data, ref offset, 2);
                    break;
                case 15:
                    Skip(data, ref offset, 3);
                    break;
                default:
                    throw new InvalidDataException($"SDLActivity.class 包含未知 constant-pool tag {tag}。");
            }
        }

        Skip(data, ref offset, 6);
        var interfaceCount = ReadUInt16(data, ref offset);
        Skip(data, ref offset, checked(interfaceCount * 2));
        var fieldCount = ReadUInt16(data, ref offset);
        var versions = new Dictionary<string, int>(StringComparer.Ordinal);
        for (var field = 0; field < fieldCount; field++)
        {
            Skip(data, ref offset, 2);
            var fieldNameIndex = ReadUInt16(data, ref offset);
            Skip(data, ref offset, 2);
            var attributeCount = ReadUInt16(data, ref offset);
            int? value = null;
            for (var attribute = 0; attribute < attributeCount; attribute++)
            {
                var attributeNameIndex = ReadUInt16(data, ref offset);
                var length = checked((int)ReadUInt32(data, ref offset));
                EnsureAvailable(data, offset, length);
                if (constantPool[attributeNameIndex] is string attributeName && attributeName == "ConstantValue" && length == 2)
                {
                    var valueIndex = ReadUInt16(data, ref offset);
                    value = constantPool[valueIndex] as int?;
                }
                else
                {
                    offset += length;
                }
            }

            if (constantPool[fieldNameIndex] is string fieldName && value is int constantValue &&
                (fieldName == "SDL_MAJOR_VERSION" || fieldName == "SDL_MINOR_VERSION" || fieldName == "SDL_MICRO_VERSION"))
            {
                versions[fieldName] = constantValue;
            }
        }

        return versions.TryGetValue("SDL_MAJOR_VERSION", out var major) &&
               versions.TryGetValue("SDL_MINOR_VERSION", out var minor) &&
               versions.TryGetValue("SDL_MICRO_VERSION", out var patch)
            ? $"{major}.{minor}.{patch}"
            : throw new InvalidDataException("SDLActivity.class 缺少 SDL 版本常量。");
    }

    static byte ReadByte(ReadOnlySpan<byte> data, ref int offset)
    {
        EnsureAvailable(data, offset, 1);
        return data[offset++];
    }

    static ushort ReadUInt16(ReadOnlySpan<byte> data, ref int offset)
    {
        EnsureAvailable(data, offset, 2);
        var value = BinaryPrimitives.ReadUInt16BigEndian(data.Slice(offset, 2));
        offset += 2;
        return value;
    }

    static uint ReadUInt32(ReadOnlySpan<byte> data, ref int offset)
    {
        EnsureAvailable(data, offset, 4);
        var value = BinaryPrimitives.ReadUInt32BigEndian(data.Slice(offset, 4));
        offset += 4;
        return value;
    }

    static void Skip(ReadOnlySpan<byte> data, ref int offset, int count)
    {
        EnsureAvailable(data, offset, count);
        offset += count;
    }

    static void EnsureAvailable(ReadOnlySpan<byte> data, int offset, int count)
    {
        if (offset < 0 || count < 0 || offset > data.Length - count)
        {
            throw new InvalidDataException("SDLActivity.class 截断。");
        }
    }
}

static int AndroidNativeAudit(bool requireSixteenKilobyteAlignment)
{
    const uint elfMagic = 0x464C457F;
    const ushort elf64Class = 2;
    const ushort programHeaderLoad = 1;
    const ulong requiredAlignment = 16 * 1024;
    const string packageVersion = "2.23.1-cubit.3";
    const string packageFileName = "Silk.NET.Windowing.Sdl.2.23.1-cubit.3.nupkg";
    const string packageAarPath = "lib/net7.0-android33.0/Silk.NET.Windowing.Sdl.aar";

    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    Check("定位 Cubit 仓库根目录", repositoryRoot is not null, repositoryRoot ?? "missing");
    if (repositoryRoot is null)
    {
        return 1;
    }

    var workspaceRoot = Directory.GetParent(repositoryRoot)?.FullName;
    Check("定位工作区根目录", workspaceRoot is not null, workspaceRoot ?? "missing");
    if (workspaceRoot is null)
    {
        return 1;
    }

    var apkDirectory = Path.Combine(
        repositoryRoot,
        "hosts",
        "Cubit.Sample.Android",
        "bin",
        "Debug",
        "net9.0-android",
        "android-arm64");
    var apkPaths = new[]
    {
        Path.Combine(apkDirectory, "com.cubit.sample.apk"),
        Path.Combine(apkDirectory, "com.cubit.sample-Signed.apk"),
    };
    Check(
        "Android 签名与未签名 APK 均可供原生库审计",
        apkPaths.All(File.Exists),
        string.Join(',', apkPaths.Where(path => !File.Exists(path))));
    if (!apkPaths.All(File.Exists))
    {
        return 1;
    }

    const string LinuxSdlEntry = "lib/arm64-v8a/libSDL2-2.0.so";
    var knownNativeSources = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        [LinuxSdlEntry] = "Ultz.Native.SDL 2.32.10（Linux arm64 runtime 资产）",
        ["lib/arm64-v8a/libSDL2.so"] = $"项目本地 Silk.NET.Windowing.Sdl {packageVersion} 包内 AAR",
        ["lib/arm64-v8a/libmain.so"] = $"项目本地 Silk.NET.Windowing.Sdl {packageVersion} 包内 AAR",
    };
    var requiredAndroidNativeLibraries = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        ["lib/arm64-v8a/libSDL2.so"] = $"项目本地 Silk.NET.Windowing.Sdl {packageVersion} 包内 AAR",
        ["lib/arm64-v8a/libmain.so"] = $"项目本地 Silk.NET.Windowing.Sdl {packageVersion} 包内 AAR",
    };
    var apkNativeLibraries = new Dictionary<string, NativeElfAudit>(StringComparer.Ordinal);
    foreach (var apkPath in apkPaths)
    {
        using var apk = ZipFile.OpenRead(apkPath);
        var arm64Entries = apk.Entries
            .Where(entry => entry.FullName.StartsWith("lib/arm64-v8a/", StringComparison.Ordinal) &&
                            entry.FullName.EndsWith(".so", StringComparison.Ordinal))
            .OrderBy(entry => entry.FullName, StringComparer.Ordinal)
            .ToArray();
        Check(
            $"APK 包含 ARM64 原生库: {Path.GetFileName(apkPath)}",
            arm64Entries.Length > 0,
            string.Join(',', arm64Entries.Select(entry => entry.FullName)));

        foreach (var entry in arm64Entries)
        {
            var audit = ReadElfAudit(entry.Open());
            var source = knownNativeSources.TryGetValue(entry.FullName, out var knownSource)
                ? knownSource
                : "未建立包来源映射";
            Check(
                $"APK ARM64 条目是 ELF64: {Path.GetFileName(apkPath)}:{entry.FullName}",
                audit.IsElf64,
                $"source={source}; {audit.Detail}");

            if (apkNativeLibraries.TryGetValue(entry.FullName, out var existingAudit))
            {
                Check(
                    $"签名与未签名 APK 的原生库一致: {entry.FullName}",
                    audit.IsElf64 == existingAudit.IsElf64 &&
                    string.Equals(audit.Detail, existingAudit.Detail, StringComparison.Ordinal),
                    $"unsigned={existingAudit.Detail}; signed={audit.Detail}");
            }
            else
            {
                apkNativeLibraries.Add(entry.FullName, audit);
            }
        }
    }

    foreach (var (entryName, source) in requiredAndroidNativeLibraries)
    {
        Check(
            $"APK 包含已知 SDL 原生库: {entryName}",
            apkNativeLibraries.ContainsKey(entryName),
            source);
    }
    Check(
        "APK 不携带 Ultz 的 Linux ARM64 SDL runtime",
        !apkNativeLibraries.ContainsKey(LinuxSdlEntry),
        knownNativeSources[LinuxSdlEntry]);

    var androidProjectDirectory = Path.Combine(repositoryRoot, "hosts", "Cubit.Sample.Android");
    var localPackagePath = Path.Combine(androidProjectDirectory, "NativePackages", packageFileName);
    Check("定位项目本地 SDL 修订包", File.Exists(localPackagePath), localPackagePath);
    if (File.Exists(localPackagePath))
    {
        try
        {
            using var package = ZipFile.OpenRead(localPackagePath);
            var aarEntry = package.GetEntry(packageAarPath);
            Check("本地 SDL 包包含嵌套 Android AAR", aarEntry is not null, packageAarPath);
            if (aarEntry is not null)
            {
                using var aarBuffer = new MemoryStream();
                using (var source = aarEntry.Open())
                {
                    source.CopyTo(aarBuffer);
                }

                aarBuffer.Position = 0;
                using var aar = new ZipArchive(aarBuffer, ZipArchiveMode.Read, leaveOpen: true);
                foreach (var entryName in new[]
                         {
                             "jni/arm64-v8a/libSDL2.so",
                             "jni/arm64-v8a/libmain.so",
                         })
                {
                    var entry = aar.GetEntry(entryName);
                    Check($"本地包 AAR 包含原生库: {entryName}", entry is not null, packageAarPath);
                    if (entry is null || !apkNativeLibraries.TryGetValue($"lib/arm64-v8a/{Path.GetFileName(entryName)}", out var apkAudit))
                    {
                        continue;
                    }

                    using var nativeBuffer = new MemoryStream();
                    using (var nativeStream = entry.Open())
                    {
                        nativeStream.CopyTo(nativeBuffer);
                    }

                    var nativeBytes = nativeBuffer.ToArray();
                    var expectedHash = Convert.ToHexString(SHA256.HashData(nativeBytes));
                    Check(
                        $"本地包 AAR 与 APK 原生库字节一致: {entryName}",
                        string.Equals(expectedHash, ExtractElfHash(apkAudit), StringComparison.Ordinal),
                        $"aar={expectedHash}; apk={apkAudit.Detail}");
                }
            }
        }
        catch (InvalidDataException exception)
        {
            Check("本地 SDL 包可读取嵌套 AAR", false, exception.Message);
        }
    }

    var libraryImportsCachePath = Path.Combine(
        androidProjectDirectory,
        "obj",
        "Debug",
        "net9.0-android",
        "android-arm64",
        "libraryprojectimports.cache");
    Check(
        "定位 Android AAR 打包输入记录",
        File.Exists(libraryImportsCachePath),
        libraryImportsCachePath);
    if (File.Exists(libraryImportsCachePath))
    {
        var libraryImports = File.ReadAllText(libraryImportsCachePath);
        var expectedAarRelativePath = Path.Combine(
            "silk.net.windowing.sdl",
            packageVersion,
            "lib",
            "net7.0-android33.0",
            "Silk.NET.Windowing.Sdl.aar");
        var oldAarRelativePath = Path.Combine(
            "silk.net.windowing.sdl",
            "2.23.0",
            "lib",
            "net7.0-android33.0",
            "Silk.NET.Windowing.Sdl.aar");
        Check(
            "Android 打包输入包含本地 SDL 修订 AAR",
            libraryImports.Contains(expectedAarRelativePath, StringComparison.OrdinalIgnoreCase),
            expectedAarRelativePath);
        Check(
            "Android 打包输入不包含旧 SDL AAR 或裸 AAR",
            !libraryImports.Contains(oldAarRelativePath, StringComparison.OrdinalIgnoreCase) &&
            !libraryImports.Contains(Path.Combine(androidProjectDirectory, "Native"), StringComparison.OrdinalIgnoreCase),
            oldAarRelativePath);
    }

    foreach (var (entryName, audit) in apkNativeLibraries.OrderBy(pair => pair.Key, StringComparer.Ordinal))
    {
        if (!audit.IsElf64)
        {
            continue;
        }

        var name = Path.GetFileName(entryName);
        var source = knownNativeSources.TryGetValue(entryName, out var knownSource)
            ? knownSource
            : "未建立包来源映射";
        var aligned = audit.LoadSegmentAlignments.Count > 0 &&
                      audit.LoadSegmentAlignments.All(alignment => alignment >= requiredAlignment &&
                                                         alignment % requiredAlignment == 0);
        var checkName = requireSixteenKilobyteAlignment
            ? $"发布门禁 ARM64 ELF LOAD 段至少 16 KB 对齐: {name}"
            : $"审计 ARM64 ELF LOAD 段对齐: {name}";
        Check(
            checkName,
            !requireSixteenKilobyteAlignment || aligned,
            $"source={source}; alignments={string.Join(',', audit.LoadSegmentAlignments.Select(alignment => $"0x{alignment:X}"))}");
    }

    var command = requireSixteenKilobyteAlignment ? "androidreleasecheck" : "androidnativeaudit";
    Console.WriteLine(failures == 0 ? $"{command} 全部通过" : $"{command} 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static NativeElfAudit ReadElfAudit(Stream source)
    {
        using var buffer = new MemoryStream();
        source.CopyTo(buffer);
        var bytes = buffer.ToArray();
        if (bytes.Length < 64 || BinaryPrimitives.ReadUInt32LittleEndian(bytes) != elfMagic || bytes[4] != elf64Class)
        {
            return new NativeElfAudit(false, [], Convert.ToHexString(bytes.AsSpan(0, Math.Min(16, bytes.Length))));
        }

        var programHeaderOffset = checked((int)BinaryPrimitives.ReadUInt64LittleEndian(bytes.AsSpan(32, 8)));
        var programHeaderEntrySize = BinaryPrimitives.ReadUInt16LittleEndian(bytes.AsSpan(54, 2));
        var programHeaderCount = BinaryPrimitives.ReadUInt16LittleEndian(bytes.AsSpan(56, 2));
        if (programHeaderEntrySize < 56 || programHeaderOffset < 0 ||
            programHeaderOffset > bytes.Length - checked(programHeaderEntrySize * programHeaderCount))
        {
            return new NativeElfAudit(false, [], "invalid program-header table");
        }

        var loadSegmentAlignments = new List<ulong>();
        for (var index = 0; index < programHeaderCount; index++)
        {
            var header = bytes.AsSpan(programHeaderOffset + index * programHeaderEntrySize, programHeaderEntrySize);
            if (BinaryPrimitives.ReadUInt32LittleEndian(header) == programHeaderLoad)
            {
                loadSegmentAlignments.Add(BinaryPrimitives.ReadUInt64LittleEndian(header.Slice(48, 8)));
            }
        }

        return new NativeElfAudit(
            true,
            loadSegmentAlignments,
            $"sha256={Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(bytes))}; size={bytes.Length}");
    }

    static string? ExtractElfHash(NativeElfAudit audit)
    {
        const string prefix = "sha256=";
        var offset = audit.Detail.IndexOf(prefix, StringComparison.Ordinal);
        if (offset < 0)
        {
            return null;
        }

        var start = offset + prefix.Length;
        var end = audit.Detail.IndexOf(';', start);
        return end < 0 ? audit.Detail[start..] : audit.Detail[start..end];
    }

}

static int PurityCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var engine = typeof(Node).Assembly;
    var engineTypes = engine.GetExportedTypes();

    // 1) 引擎无游戏逻辑命名空间（demo 不叫 Cubit）
    var gameNs = engineTypes.Where(t => (t.Namespace ?? "").StartsWith("Cubit.Core.Game", StringComparison.Ordinal)).ToArray();
    Check("引擎无 Cubit.Core.Game 命名空间", gameNs.Length == 0, $"n={gameNs.Length}");

    // 2) 引擎不含 demo 类型（PlayerController/GameScene 属于 Cubit.Sample）
    var demoTypes = engineTypes.Where(t => t.Name is "PlayerController" or "GameScene" or "GameSceneMcpHost").ToArray();
    Check("引擎不含 demo 类型", demoTypes.Length == 0, $"n={demoTypes.Length}");

    // 3) 引擎核心 API 齐全（只允许通用能力）
    var coreOk = engine.GetType("Cubit.Core.Scene.Node") != null
        && engine.GetType("Cubit.Core.Scene.SceneTree") != null
        && engine.GetType("Cubit.Core.Input.InputServer") != null
        && engine.GetType("Cubit.Core.Platform.DisplaySettings") != null
        && engine.GetType("Cubit.Core.Rendering.RenderingServer") != null
        && engine.GetType("Cubit.Core.Rendering.VulkanContext") != null
        && engine.GetType("Cubit.Core.Plugins.PluginManager") != null
        && engine.GetType("Cubit.Core.Ecs.EcsWorld") != null
        && engine.GetType("Cubit.Core.Jobs.JobSystem") != null;
    Check("通用引擎核心 API 齐全", coreOk, "Scene/Input/Rendering/Plugins/Ecs/Jobs");

    var forbiddenCoreTypes = engineTypes.Where(type =>
        (type.Namespace ?? "").StartsWith("Cubit.Voxel.World", StringComparison.Ordinal) ||
        type.Name.Contains("Voxel", StringComparison.Ordinal) ||
        type.Name.Contains("Chunk", StringComparison.Ordinal) ||
        type.Name is "BlockRegistry" or "TextureAtlas" or "WorldGenerator").ToArray();
    Check(
        "Core 不包含体素领域类型",
        forbiddenCoreTypes.Length == 0,
        string.Join(',', forbiddenCoreTypes.Select(type => type.FullName)));

    var forbiddenResources = engine.GetManifestResourceNames()
        .Where(name => name.EndsWith(".png", StringComparison.OrdinalIgnoreCase) ||
                       name.Contains("TextureAtlas", StringComparison.Ordinal))
        .ToArray();
    Check(
        "Core 不嵌入体素图集与方块纹理",
        forbiddenResources.Length == 0,
        string.Join(',', forbiddenResources));

    var forbiddenReferences = engine.GetReferencedAssemblies()
        .Where(reference => reference.Name is not null &&
                            (reference.Name.StartsWith("Cubit.Voxel", StringComparison.Ordinal) ||
                             reference.Name.StartsWith("Cubit.Pixel", StringComparison.Ordinal)))
        .Select(reference => reference.Name)
        .ToArray();
    Check("Core 不引用官方领域插件", forbiddenReferences.Length == 0, string.Join(',', forbiddenReferences));

    // 4) 通用渲染 API 不暴露体素语义
    var renderBackend = engine.GetType("Cubit.Core.Rendering.IRenderBackend");
    var meshData = engine.GetType("Cubit.Core.Rendering.MeshData");
    var boxMesh = engine.GetType("Cubit.Core.Scene.BoxMesh3D");
    var voxelRenderer = engine.GetType("Cubit.Core.Rendering.IVoxelRenderer");
    Check(
        "通用渲染 API 齐全",
        renderBackend is not null && meshData is not null && boxMesh is not null,
        $"IRenderBackend={renderBackend is not null} MeshData={meshData is not null} BoxMesh3D={boxMesh is not null}");
    Check("Core 不再暴露 IVoxelRenderer", voxelRenderer is null, $"present={voxelRenderer is not null}");
    var renderingServerType = typeof(RenderingServer);
    var createMesh = renderingServerType.GetMethod("CreateMesh");
    var destroyMesh = renderingServerType.GetMethod("DestroyMesh");
    var chunkMethods = renderingServerType.GetMethods()
        .Where(method => method.Name.Contains("Chunk", StringComparison.Ordinal))
        .Select(method => method.Name)
        .Distinct()
        .ToArray();
    Check(
        "RenderingServer 使用通用 RID 网格生命周期",
        createMesh is not null && destroyMesh is not null && chunkMethods.Length == 0,
        $"CreateMesh={createMesh is not null} DestroyMesh={destroyMesh is not null} chunkMethods={string.Join(',', chunkMethods)}");

    var repositoryRoot = FindCubitRepositoryRoot();
    var vulkanSource = repositoryRoot is null
        ? string.Empty
        : File.ReadAllText(Path.Combine(repositoryRoot, "src", "Cubit.Core", "Rendering", "VulkanContext.cs"));
    Check(
        "Core 渲染上下文不保留体素调试环境变量",
        !string.IsNullOrEmpty(vulkanSource) && !vulkanSource.Contains("VOXEL_", StringComparison.Ordinal),
        vulkanSource.Contains("VOXEL_", StringComparison.Ordinal) ? "发现遗留 VOXEL_ 环境变量" : "");

    var meshValidationOk = meshData is not null
        && CanCreateMeshData(meshData, new float[18], [0u, 1u, 2u], Vector3.Zero, Vector3.Zero, Vector3.One)
        && RejectsMeshData(meshData, [], [0u], Vector3.Zero, Vector3.Zero, Vector3.One)
        && RejectsMeshData(meshData, new float[5], [0u], Vector3.Zero, Vector3.Zero, Vector3.One)
        && RejectsMeshData(meshData, new float[18], [0u, 1u, 2u], new Vector3(float.NaN, 0f, 0f), Vector3.Zero, Vector3.One)
        && RejectsMeshData(meshData, new float[18], [0u, 1u, 2u], Vector3.Zero, Vector3.One, Vector3.Zero);
    Check("MeshData 拒绝无效网格与边界", meshValidationOk);

    // 5) MCP 服务齐全（Cubit.Mcp）
    var mcpTypes = typeof(McpServer).Assembly.GetExportedTypes();
    Check("MCP 服务齐全", mcpTypes.Any(t => t.Name == "McpServer") && mcpTypes.Any(t => t.Name == "McpHttpServer"), "McpServer + McpHttpServer");

    Console.WriteLine(failures == 0 ? "puritycheck 全部通过" : $"puritycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int RenderResourceCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var startupDiagnostic = VulkanFrameDiagnostics.FormatStartup(
        graphicsQueueFamily: 3,
        presentQueueFamily: 5,
        width: 2400,
        height: 1080,
        imageCount: 4,
        presentMode: Silk.NET.Vulkan.PresentModeKHR.MailboxKhr,
        compositeAlpha: Silk.NET.Vulkan.CompositeAlphaFlagsKHR.OpaqueBitKhr);
    Check(
        "Vulkan 启动诊断包含队列和交换链配置",
        startupDiagnostic.Contains("graphicsFamily=3", StringComparison.Ordinal)
            && startupDiagnostic.Contains("presentFamily=5", StringComparison.Ordinal)
            && startupDiagnostic.Contains("extent=2400x1080", StringComparison.Ordinal)
            && startupDiagnostic.Contains("images=4", StringComparison.Ordinal)
            && startupDiagnostic.Contains(
                $"presentMode={Silk.NET.Vulkan.PresentModeKHR.MailboxKhr}",
                StringComparison.Ordinal)
            && startupDiagnostic.Contains("compositeAlpha=OpaqueBitKhr", StringComparison.Ordinal),
        startupDiagnostic);
    var failedFrameDiagnostic = VulkanFrameDiagnostics.FormatFrame(
        acquire: Silk.NET.Vulkan.Result.Success,
        imageIndex: 2,
        submit: Silk.NET.Vulkan.Result.ErrorInitializationFailed,
        present: null);
    Check(
        "Vulkan 首帧诊断保留提交失败而非伪造呈现结果",
        failedFrameDiagnostic.Contains("acquire=Success", StringComparison.Ordinal)
            && failedFrameDiagnostic.Contains("image=2", StringComparison.Ordinal)
            && failedFrameDiagnostic.Contains("submit=ErrorInitializationFailed", StringComparison.Ordinal)
            && failedFrameDiagnostic.Contains("present=<not-run>", StringComparison.Ordinal),
        failedFrameDiagnostic);

    var vulkanContextSource = File.ReadAllText(Path.Combine(
        Directory.GetCurrentDirectory(),
        "src",
        "Cubit.Core",
        "Rendering",
        "VulkanContext.cs"));
    Check(
        "交换链图像在复用前等待其上一帧 fence",
        vulkanContextSource.Contains("_imageInFlightFences", StringComparison.Ordinal)
            && vulkanContextSource.Contains("WaitForAcquiredImageFence", StringComparison.Ordinal),
        "每个 acquired image 必须关联并等待最后提交它的 frame fence");
    Check(
        "呈现信号量按交换链图像而非帧槽归属",
        vulkanContextSource.Contains("var signalSemaphore = _renderFinished[imageIndex];", StringComparison.Ordinal)
            && !vulkanContextSource.Contains("var signalSemaphore = _renderFinished[_currentFrame];", StringComparison.Ordinal),
        "Godot 对每个 swapchain image 使用独立的 present semaphore，不能以 frame slot 复用");
    Check(
        "Android 默认呈现模式遵循 Godot FIFO 路径",
        vulkanContextSource.Contains("var presentMode = PresentModeKHR.FifoKhr;", StringComparison.Ordinal)
            && !vulkanContextSource.Contains("presentModes[i] == PresentModeKHR.MailboxKhr", StringComparison.Ordinal),
        "Android BufferQueue 默认走 FIFO；Mailbox 只能在显式 pacing 契约下启用");
    Check(
        "acquire 信号量按 fence 延迟归还",
        vulkanContextSource.Contains("_imageAvailableFree", StringComparison.Ordinal)
            && vulkanContextSource.Contains("ReleaseAcquireSemaphoreForFrame", StringComparison.Ordinal)
            && vulkanContextSource.Contains("_frameAcquireSemaphore", StringComparison.Ordinal),
        "模拟 Godot：acquire semaphore 成功提交后绑定 frame fence，fence 完成才回收到池");
    Check(
        "未消费 acquire 信号量失败后重建",
        vulkanContextSource.Contains("RecreateAcquireSemaphore", StringComparison.Ordinal)
            && vulkanContextSource.Contains("ErrorOutOfDateKhr", StringComparison.Ordinal),
        "OUT_OF_DATE/submit 失败不能复用仍处于 signal 状态的 acquire semaphore");
    Check(
        "复用帧槽前重置命令缓冲",
        vulkanContextSource.Contains("CommandPoolCreateFlags.ResetCommandBufferBit", StringComparison.Ordinal)
            && vulkanContextSource.Contains("ResetCommandBuffer(commandBuffer, 0)", StringComparison.Ordinal),
        "模拟 Godot：完成对应 fence 后，命令缓冲必须回到 initial 状态再重新录制");
    var retirementQueueType = typeof(RenderingServer).Assembly.GetType("Cubit.Core.Rendering.VulkanFrameRetirementQueue`1");
    var retirementFields = new[] { "_retiredMeshes", "_retiredMaterials", "_retiredTextures" }
        .Select(name => typeof(VulkanContext).GetField(name, BindingFlags.Instance | BindingFlags.NonPublic))
        .ToArray();
    Check(
        "Vulkan 的网格、材质和纹理都通过完成帧队列延迟释放",
        retirementQueueType is not null && retirementFields.All(field =>
            field?.FieldType.IsGenericType == true &&
            field.FieldType.GetGenericTypeDefinition() == retirementQueueType),
        string.Join(',', retirementFields.Select(field => field?.Name ?? "missing")));
    if (retirementQueueType is not null)
    {
        var queueType = retirementQueueType.MakeGenericType(typeof(int));
        var queue = Activator.CreateInstance(queueType, [2])
            ?? throw new InvalidOperationException("无法构造 Vulkan 帧退休队列");
        var retire = queueType.GetMethod("Retire")
            ?? throw new InvalidOperationException("Vulkan 帧退休队列缺少 Retire");
        var drain = queueType.GetMethod("DrainCompleted")
            ?? throw new InvalidOperationException("Vulkan 帧退休队列缺少 DrainCompleted");
        var collected = new List<int>();
        Action<int> collect = collected.Add;
        retire.Invoke(queue, [7, 10L]);
        drain.Invoke(queue, [11L, collect]);
        var heldAtOneFrame = collected.Count == 0;
        drain.Invoke(queue, [12L, collect]);
        Check(
            "Vulkan 帧退休队列只在两个完成帧后回收资源",
            heldAtOneFrame && collected.SequenceEqual([7]),
            string.Join(',', collected));
    }
    var core = typeof(RenderingServer).Assembly;
    var textureType = core.GetType("Cubit.Core.Rendering.TextureData");
    var filterType = core.GetType("Cubit.Core.Rendering.TextureFilter");
    var materialType = core.GetType("Cubit.Core.Rendering.MaterialData");
    Check(
        "通用 Texture/Material 数据类型存在",
        textureType is not null && filterType is not null && materialType is not null,
        $"TextureData={textureType is not null} TextureFilter={filterType is not null} MaterialData={materialType is not null}");

    var serverType = typeof(RenderingServer);
    var requiredMethods = new[]
    {
        "CreateTexture", "DestroyTexture", "CreateMaterial", "DestroyMaterial", "CreateMesh", "DestroyMesh",
    };
    var actualMethods = serverType.GetMethods().Select(method => method.Name).ToHashSet(StringComparer.Ordinal);
    Check(
        "RenderingServer 公开通用资源生命周期",
        requiredMethods.All(actualMethods.Contains),
        $"missing={string.Join(',', requiredMethods.Where(name => !actualMethods.Contains(name)))}");

    var backendMethods = typeof(IRenderBackend).GetMethods().Select(method => method.Name).ToHashSet(StringComparer.Ordinal);
    var requiredBackendMethods = new[]
    {
        "SetTexture", "RemoveTexture", "SetMaterial", "RemoveMaterial", "SetMesh", "RemoveMesh",
    };
    Check(
        "渲染后端覆盖 Texture/Material/Mesh",
        requiredBackendMethods.All(backendMethods.Contains),
        $"missing={string.Join(',', requiredBackendMethods.Where(name => !backendMethods.Contains(name)))}");

    if (textureType is not null && filterType is not null && materialType is not null &&
        requiredMethods.All(actualMethods.Contains) && requiredBackendMethods.All(backendMethods.Contains))
    {
        var nearest = Enum.Parse(filterType, "Nearest");
        var colorSpace = Enum.Parse(textureType.GetNestedType("TextureColorSpace") ?? core.GetType("Cubit.Core.Rendering.TextureColorSpace")!, "Srgb");
        var validTexture = Activator.CreateInstance(textureType, 2, 2, new byte[16], nearest, colorSpace)
            ?? throw new InvalidOperationException("无法创建 TextureData");
        Check(
            "TextureData 拒绝错误 RGBA 长度",
            RejectsConstructor(textureType, 2, 2, new byte[15], nearest, colorSpace));
        Check(
            "TextureData 拒绝非正尺寸",
            RejectsConstructor(textureType, 0, 2, Array.Empty<byte>(), nearest, colorSpace));

        var proxy = DispatchProxy.Create<IRenderBackend, CountingRenderBackendProxy>();
        var counter = (CountingRenderBackendProxy)(object)proxy;
        using var server = new RenderingServer(proxy);
        var textureRid = (RID)serverType.GetMethod("CreateTexture")!.Invoke(server, [validTexture])!;

        var badMaterial = Activator.CreateInstance(materialType, new RID(9999))!;
        Check(
            "Material 拒绝未知纹理 RID",
            RejectsInvocation(serverType.GetMethod("CreateMaterial")!, server, badMaterial));

        var material = Activator.CreateInstance(materialType, textureRid)!;
        var materialRid = (RID)serverType.GetMethod("CreateMaterial")!.Invoke(server, [material])!;
        var mesh = Activator.CreateInstance(
            typeof(MeshData),
            new float[18],
            new uint[] { 0, 1, 2 },
            Vector3.Zero,
            Vector3.Zero,
            Vector3.One,
            materialRid) as MeshData;
        Check("MeshData 接受材质 RID", mesh is not null && ReadMeshMaterial(mesh) == materialRid);

        if (mesh is not null)
        {
            var meshRid = server.CreateMesh(mesh);
            Check(
                "活跃材质阻止纹理销毁",
                RejectsInvocation(serverType.GetMethod("DestroyTexture")!, server, textureRid));
            Check(
                "活跃网格阻止材质销毁",
                RejectsInvocation(serverType.GetMethod("DestroyMaterial")!, server, materialRid));

            server.DestroyMesh(meshRid);
            var orderedRetirement = true;
            try
            {
                server.DestroyMaterial(materialRid);
                server.DestroyTexture(textureRid);
            }
            catch (InvalidOperationException)
            {
                orderedRetirement = false;
            }

            Check("退出顺序允许网格/材质/纹理同帧排队", orderedRetirement);
            server.BeginFrame();
            server.BeginFrame();
            Check(
                "两帧后各资源精确释放一次",
                counter.CallCount("RemoveMesh") == 1 &&
                counter.CallCount("RemoveMaterial") == 1 &&
                counter.CallCount("RemoveTexture") == 1,
                $"mesh={counter.CallCount("RemoveMesh")} material={counter.CallCount("RemoveMaterial")} texture={counter.CallCount("RemoveTexture")}");
        }
    }

    Console.WriteLine(failures == 0 ? "renderresourcecheck 全部通过" : $"renderresourcecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static bool RejectsConstructor(Type type, params object[] args)
{
    try
    {
        _ = Activator.CreateInstance(type, args);
        return false;
    }
    catch (TargetInvocationException ex) when (ex.InnerException is ArgumentException or ArgumentOutOfRangeException)
    {
        return true;
    }
}

static bool RejectsInvocation(MethodInfo method, object target, params object[] args)
{
    try
    {
        _ = method.Invoke(target, args);
        return false;
    }
    catch (TargetInvocationException ex) when (ex.InnerException is InvalidOperationException or ArgumentException)
    {
        return true;
    }
}

static RID ReadMeshMaterial(MeshData mesh)
{
    var property = typeof(MeshData).GetProperty("Material");
    return property?.GetValue(mesh) is RID rid ? rid : RID.None;
}

static int EditorPluginCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var editorReferences = GetEditorProjectReferences();
    var requiredOfficialModules = new[]
    {
        "Cubit.Physics",
        "Cubit.Animation",
        "Cubit.Voxel",
        "Cubit.Audio",
        "Cubit.Content",
        "Cubit.Scripting",
    };
    var missingOfficialModules = requiredOfficialModules
        .Where(module => !editorReferences.Contains(module))
        .ToArray();
    Check(
        "Editor 项目直接引用全部官方模块程序集",
        missingOfficialModules.Length == 0,
        string.Join(',', missingOfficialModules));

    var editorSampleReferences = editorReferences
        .Where(reference => reference.StartsWith("Cubit.Sample", StringComparison.Ordinal))
        .ToArray();
    Check(
        "Editor 不编译依赖 demo 项目",
        editorSampleReferences.Length == 0,
        string.Join(',', editorSampleReferences));

    var root = Path.Combine(Path.GetTempPath(), "cubit-editor-plugin-check", Guid.NewGuid().ToString("N"));
    Directory.CreateDirectory(root);
    try
    {
        var project = ProjectIO.Create(root, "EditorPluginCheck");
        File.WriteAllText(project.ManifestPath, """
{
  "formatVersion": 1,
  "name": "EditorPluginCheck",
  "mainScene": "scenes/main.cscene",
  "plugins": [{ "id": "missing.plugin", "version": "1.0.0" }]
}
""");
        var threwMissing = false;
        try
        {
            using var ignored = new ProjectSceneSession(new FakeRenderBackend(), root);
        }
        catch (InvalidOperationException)
        {
            threwMissing = true;
        }

        Check("Editor 拒绝不可用插件声明", threwMissing);

        var previewDirectory = Path.Combine(root, "preview");
        Directory.CreateDirectory(previewDirectory);
        var independentPreviewAssembly = GetIndependentPreviewAssemblyPath();
        var independentPreviewWasLoaded = IsAssemblyLoaded(independentPreviewAssembly);
        Check(
            "独立 Preview.Assembly 未被 Tool 或 Editor 预加载",
            File.Exists(independentPreviewAssembly) && !independentPreviewWasLoaded,
            $"path={independentPreviewAssembly} loaded={independentPreviewWasLoaded}");
        if (File.Exists(independentPreviewAssembly))
        {
            File.Copy(independentPreviewAssembly, Path.Combine(previewDirectory, "Cubit.Ecs.Sample.dll"));
        }
        var lifecyclePreviewDirectory = Path.Combine(root, "lifecycle-preview");
        Directory.CreateDirectory(lifecyclePreviewDirectory);
        File.Copy(typeof(EditorPreviewProbe).Assembly.Location, Path.Combine(lifecyclePreviewDirectory, "Cubit.Tool.dll"));

        File.WriteAllText(project.ManifestPath, """
{
  "formatVersion": 1,
  "name": "Editor 预览生命周期校验",
  "mainScene": "scenes/main.cscene",
  "preview": {
    "assembly": "lifecycle-preview/Cubit.Tool.dll",
    "type": "EditorPreviewProbe"
  },
  "plugins": [
    { "id": "cubit.voxel", "version": "1.0.0" },
    { "id": "cubit.audio", "version": "1.0.0" },
    { "id": "cubit.scripting", "version": "1.0.0" }
  ]
}
""");
        File.WriteAllText(project.MainScenePath, SceneIO.WithDocumentUid("""
{
  "Type": "Cubit.Core.Scene.Node",
  "Name": "Root",
  "Properties": null,
  "Children": [
    {
      "Type": "Cubit.Core.Scene.BoxMesh3D",
      "Name": "BoxMesh3D",
      "Properties": null,
      "Children": null
    },
    {
      "Type": "Cubit.Scripting.ScriptAttachmentNode",
      "Name": "ScriptAttachment",
      "Properties": {
        "Attachment": {
          "TargetPath": { "Value": "/Root/BoxMesh3D" },
          "TypeName": "ScriptingProbe",
          "PropertyOverrides": { "ExportedValue": 17 }
        }
      },
      "Children": null
    }
  ]
        }
""", project.SceneCatalog.MainScene.Uid));
        EditorPreviewProbe.Reset();
        using (var lifecycleSession = new ProjectSceneSession(new FakeRenderBackend(), root))
        {
            var lifecyclePlugins = GetEditorPluginManager(lifecycleSession);
            var lifecycleAudio = GetResolvedPlugin<CubitAudioPlugin>(lifecyclePlugins);
            var lifecycleVoxel = GetResolvedPlugin<CubitVoxelPlugin>(lifecyclePlugins);
            var lifecycleScripting = GetResolvedPlugin<CubitScriptingPlugin>(lifecyclePlugins);
            var lifecycleStartedInEditState =
                IsEditorPluginStarted(lifecyclePlugins, lifecycleAudio) ||
                IsEditorPluginStarted(lifecyclePlugins, lifecycleVoxel) ||
                IsEditorPluginStarted(lifecyclePlugins, lifecycleScripting);
            Check(
                "编辑态不启动已声明模块或执行服务",
                lifecyclePlugins is { IsStarted: false } &&
                !IsEditorPluginStarted(lifecyclePlugins, lifecycleAudio) &&
                !IsEditorPluginStarted(lifecyclePlugins, lifecycleVoxel) &&
                !IsEditorPluginStarted(lifecyclePlugins, lifecycleScripting) &&
                lifecycleAudio?.Server is null && GetScriptingRuntime(lifecycleScripting) is null &&
                GetSessionContentService(lifecycleSession) is null,
                DescribeEditorPluginState(lifecyclePlugins));

            var lifecyclePreviewError = CaptureException(lifecycleSession.StartPreview);
            lifecyclePlugins = GetEditorPluginManager(lifecycleSession);
            lifecycleAudio = GetResolvedPlugin<CubitAudioPlugin>(lifecyclePlugins);
            lifecycleVoxel = GetResolvedPlugin<CubitVoxelPlugin>(lifecyclePlugins);
            lifecycleScripting = GetResolvedPlugin<CubitScriptingPlugin>(lifecyclePlugins);
            lifecycleSession.ProcessFrame(lifecycleSession.Tree.PhysicsDelta);
            var lifecycleRuntime = GetScriptingRuntime(lifecycleScripting);
            var lifecycleScript = lifecycleRuntime?.ActiveScripts.SingleOrDefault();
            var lifecycleScriptLog = lifecycleScript?.GetType().GetProperty("Log")?.GetValue(lifecycleScript) as IReadOnlyList<string>;
            Check(
                "预览阶段才启动声明模块与执行服务",
                lifecyclePreviewError is null && !lifecycleStartedInEditState &&
                lifecycleSession.IsPreviewing && !lifecycleSession.Tree.Paused &&
                lifecyclePlugins is { IsStarted: true } &&
                IsEditorPluginStarted(lifecyclePlugins, lifecycleAudio) &&
                IsEditorPluginStarted(lifecyclePlugins, lifecycleVoxel) &&
                IsEditorPluginStarted(lifecyclePlugins, lifecycleScripting) && lifecycleAudio?.Server is not null &&
                lifecycleRuntime is { IsRunning: true } && lifecycleScriptLog is not null &&
                lifecycleScriptLog.SequenceEqual(["enter", "ready", "physics", "process"]),
                $"{DescribeEditorPluginState(lifecyclePlugins)} error={lifecyclePreviewError?.Message}");

            var lifecycleStopError = CaptureException(lifecycleSession.StopPreview);
            lifecyclePlugins = GetEditorPluginManager(lifecycleSession);
            lifecycleAudio = GetResolvedPlugin<CubitAudioPlugin>(lifecyclePlugins);
            lifecycleVoxel = GetResolvedPlugin<CubitVoxelPlugin>(lifecyclePlugins);
            lifecycleScripting = GetResolvedPlugin<CubitScriptingPlugin>(lifecyclePlugins);
            Check(
                "停止预览释放模块执行服务",
                lifecycleStopError is null && !lifecycleSession.IsPreviewing && lifecycleSession.Tree.Paused &&
                lifecyclePlugins is { IsStarted: false } &&
                !IsEditorPluginStarted(lifecyclePlugins, lifecycleAudio) &&
                !IsEditorPluginStarted(lifecyclePlugins, lifecycleVoxel) &&
                !IsEditorPluginStarted(lifecyclePlugins, lifecycleScripting) && lifecycleAudio?.Server is null &&
                GetScriptingRuntime(lifecycleScripting) is null &&
                GetSessionContentService(lifecycleSession) is null,
                $"{DescribeEditorPluginState(lifecyclePlugins)} error={lifecycleStopError?.Message}");

            var bootstrapLoadContext = GetPreviewBootstrapLoadContext(lifecycleSession);
            var bootstrapLoadContextReference = GetPreviewBootstrapLoadContextReference(lifecycleSession);
            var remainingPreviewContexts = GetPreviewLoadContextNames();
            Check(
                "停止预览释放可收集的 bootstrap 程序集上下文",
                bootstrapLoadContext is null && bootstrapLoadContextReference is not null && remainingPreviewContexts.Length == 0,
                $"active={bootstrapLoadContext is not null} reference={bootstrapLoadContextReference is not null} alive={bootstrapLoadContextReference?.IsAlive} contexts={string.Join('|', remainingPreviewContexts)}");

            var lifecycleRegistrationCount = lifecyclePlugins?.Registry.Registrations.Count ?? -1;
            var secondStartError = CaptureException(lifecycleSession.StartPreview);
            var secondStopError = CaptureException(lifecycleSession.StopPreview);
            var lifecycleFinalRegistrationCount = lifecyclePlugins?.Registry.Registrations.Count ?? -1;
            Check(
                "预览可重复 Start/Stop 且不重复注册类型",
                secondStartError is null && secondStopError is null && !lifecycleSession.IsPreviewing &&
                lifecycleSession.Tree.Paused && lifecyclePlugins is { IsStarted: false } &&
                lifecycleRegistrationCount == lifecycleFinalRegistrationCount,
                $"start={secondStartError?.Message} stop={secondStopError?.Message} registrations={lifecycleRegistrationCount}->{lifecycleFinalRegistrationCount}");
        }

        File.WriteAllText(project.ManifestPath, """
{
  "formatVersion": 1,
  "name": "Editor 官方模块编辑态校验",
  "mainScene": "scenes/main.cscene",
  "preview": {
    "assembly": "preview/Cubit.Ecs.Sample.dll",
    "type": "Cubit.Ecs.Sample.EcsPreviewBootstrap"
  },
  "plugins": [
    { "id": "cubit.physics", "version": "1.0.0" },
    { "id": "cubit.animation", "version": "1.0.0" },
    { "id": "cubit.voxel", "version": "1.0.0" },
    { "id": "cubit.audio", "version": "1.0.0" },
    { "id": "cubit.content", "version": "1.0.0" },
    { "id": "cubit.scripting", "version": "1.0.0" }
  ]
}
""");
        File.WriteAllText(project.MainScenePath, SceneIO.WithDocumentUid("""
{
  "Type": "Cubit.Core.Scene.Node",
  "Name": "Root",
  "Properties": null,
  "Children": [
    {
      "Type": "Cubit.Physics.Scene.PhysicsWorld3D",
      "Name": "Physics",
      "Properties": null,
      "Children": null
    },
    {
      "Type": "Cubit.Animation.AnimationPlayer",
      "Name": "Animation",
      "Properties": null,
      "Children": null
    },
    {
      "Type": "Cubit.Core.Scene.EcsNode",
      "Name": "PreviewEcs",
      "Properties": null,
      "Children": null
    },
    {
      "Type": "Cubit.Core.Scene.Node",
      "Name": "Presentation",
      "Properties": null,
      "Children": [
        {
          "Type": "Cubit.Core.Scene.Camera3D",
          "Name": "PreviewCamera",
          "Properties": null,
          "Children": null
        },
        {
          "Type": "Cubit.Core.Scene.BoxMesh3D",
          "Name": "EcsPreviewAnchor",
          "Properties": null,
          "Children": null
        }
      ]
    },
    {
      "Type": "Cubit.Voxel.World.VoxelWorldNode",
      "Name": "World",
      "Properties": { "Seed": 20260808, "WorldType": 1, "GenerateRadius": 1 },
      "Children": null
    }
  ]
        }
""", project.SceneCatalog.MainScene.Uid));

        var fullPreviewAssemblyPath = Path.GetFullPath(Path.Combine(root, "preview", "Cubit.Ecs.Sample.dll"));
        var loadedBeforeOpen = IsAssemblyLoaded(fullPreviewAssemblyPath);
        ProjectSceneSession? session = null;
        Exception? openError = null;
        try
        {
            session = new ProjectSceneSession(new FakeRenderBackend(), root);
        }
        catch (Exception exception)
        {
            openError = exception;
        }

        try
        {
            Check(
                "Editor 可打开包含全部官方模块声明的项目",
                session is not null,
                openError?.Message ?? "");
            var loadedAfterOpen = IsAssemblyLoaded(fullPreviewAssemblyPath);
            Check(
                "打开完整项目不加载独立 Preview.Assembly",
                !loadedBeforeOpen && !loadedAfterOpen,
                $"before={loadedBeforeOpen} after={loadedAfterOpen}");

            var requiredNodeTypes = new[]
            {
                "PhysicsWorld3D",
                "AnimationPlayer",
                "VoxelWorldNode",
                "AudioPlayer",
                "ScriptAttachmentNode",
            };
            var requiredResourceTypes = new[] { "BoxShape3D", "AnimationClip", "ScriptAttachment" };
            var knownNodeTypes = session?.SceneRegistry.KnownNodeTypes ?? [];
            var unresolvedNodeTypes = requiredNodeTypes
                .Where(type => !knownNodeTypes.Contains(type, StringComparer.Ordinal))
                .ToArray();
            var knownResourceTypes = session?.SceneRegistry.KnownResourceTypes ?? [];
            var unresolvedResourceTypes = requiredResourceTypes
                .Where(type => !knownResourceTypes.Contains(type, StringComparer.Ordinal))
                .ToArray();
            Check(
                "打开项目后官方模块节点进入会话 registry、资源保留元数据注册",
                session is not null && unresolvedNodeTypes.Length == 0 && unresolvedResourceTypes.Length == 0,
                $"nodes={string.Join(',', unresolvedNodeTypes)} resources={string.Join(',', unresolvedResourceTypes)}");

            var pluginManager = GetEditorPluginManager(session);
            var resolvedOfficialPlugins = pluginManager?.ResolvedPlugins ?? [];
            var editPhysics = GetResolvedPlugin<CubitPhysicsPlugin>(pluginManager);
            var editAnimation = GetResolvedPlugin<CubitAnimationPlugin>(pluginManager);
            var editAudio = GetResolvedPlugin<CubitAudioPlugin>(pluginManager);
            var editContent = GetResolvedPlugin<CubitContentPlugin>(pluginManager);
            var editScripting = GetResolvedPlugin<CubitScriptingPlugin>(pluginManager);
            var editVoxel = GetResolvedPlugin<CubitVoxelPlugin>(pluginManager);
            Check(
                "完整清单编辑态逐个保持 Physics 未启动",
                session is not null && !IsEditorPluginStarted(pluginManager, editPhysics),
                DescribeEditorPluginState(pluginManager));
            Check(
                "完整清单编辑态逐个保持 Animation 未启动",
                session is not null && !IsEditorPluginStarted(pluginManager, editAnimation),
                DescribeEditorPluginState(pluginManager));
            Check(
                "完整清单编辑态逐个保持 Audio 未启动且无 Server",
                session is not null && !IsEditorPluginStarted(pluginManager, editAudio) && editAudio?.Server is null,
                DescribeEditorPluginState(pluginManager));
            Check(
                "完整清单编辑态逐个保持 Content 未启动且无服务",
                session is not null && !IsEditorPluginStarted(pluginManager, editContent) &&
                GetSessionContentService(session) is null,
                DescribeEditorPluginState(pluginManager));
            Check(
                "完整清单编辑态逐个保持 Scripting 未启动且无 Runtime",
                session is not null && !IsEditorPluginStarted(pluginManager, editScripting) &&
                GetScriptingRuntime(editScripting) is null,
                DescribeEditorPluginState(pluginManager));
            Check(
                "完整清单编辑态逐个保持 Voxel 未启动",
                session is not null && !IsEditorPluginStarted(pluginManager, editVoxel),
                DescribeEditorPluginState(pluginManager));
            Check(
                "完整清单逐个解析全部官方插件宿主",
                session is not null && resolvedOfficialPlugins.OfType<CubitPhysicsPlugin>().Count() == 1 &&
                resolvedOfficialPlugins.OfType<CubitAnimationPlugin>().Count() == 1 &&
                resolvedOfficialPlugins.OfType<CubitVoxelPlugin>().Count() == 1 &&
                resolvedOfficialPlugins.OfType<CubitAudioPlugin>().Count() == 1 &&
                resolvedOfficialPlugins.OfType<CubitContentPlugin>().Count() == 1 &&
                resolvedOfficialPlugins.OfType<CubitScriptingPlugin>().Count() == 1,
                string.Join(',', resolvedOfficialPlugins.Select(plugin => plugin.GetType().Name)));

            if (session is not null)
            {
                var registrationCount = pluginManager?.Registry.Registrations.Count ?? -1;
                var previewError = CaptureException(session.StartPreview);
                pluginManager = GetEditorPluginManager(session);
                var physics = GetResolvedPlugin<CubitPhysicsPlugin>(pluginManager);
                var animation = GetResolvedPlugin<CubitAnimationPlugin>(pluginManager);
                var audio = GetResolvedPlugin<CubitAudioPlugin>(pluginManager);
                var content = GetResolvedPlugin<CubitContentPlugin>(pluginManager);
                var scripting = GetResolvedPlugin<CubitScriptingPlugin>(pluginManager);
                var voxel = GetResolvedPlugin<CubitVoxelPlugin>(pluginManager);
                Check(
                    "显式预览才启动全部声明模块与执行服务",
                    previewError is null && session.IsPreviewing && !session.Tree.Paused && pluginManager is { IsStarted: true } &&
                    physics?.IsStarted == true && animation?.IsStarted == true && audio?.IsStarted == true &&
                    audio.Server is not null && content is not null && scripting?.IsStarted == true &&
                    voxel is not null && GetContentPluginDiagnostics(content).All(item => item.Code != "content.service.missing") &&
                    IsEditorPluginStarted(pluginManager, physics) &&
                    IsEditorPluginStarted(pluginManager, animation) &&
                    IsEditorPluginStarted(pluginManager, audio) &&
                    IsEditorPluginStarted(pluginManager, content) &&
                    IsEditorPluginStarted(pluginManager, scripting) &&
                    IsEditorPluginStarted(pluginManager, voxel) &&
                    GetSessionContentService(session) is not null,
                    $"{DescribeEditorPluginState(pluginManager)} error={previewError?.Message} contentDiagnostics={string.Join(',', GetContentPluginDiagnostics(content).Select(item => item.Code))}");

                var stopError = CaptureException(session.StopPreview);
                pluginManager = GetEditorPluginManager(session);
                audio = GetResolvedPlugin<CubitAudioPlugin>(pluginManager);
                scripting = GetResolvedPlugin<CubitScriptingPlugin>(pluginManager);
                Check(
                    "停止预览释放执行服务并恢复作者场景",
                    stopError is null && !session.IsPreviewing && session.Tree.Paused && pluginManager is { IsStarted: false } &&
                    audio?.Server is null && GetScriptingRuntime(scripting) is null &&
                    GetSessionContentService(session) is null &&
                    session.Tree.GetNode("/Root/Physics")?.GetType().FullName == "Cubit.Physics.Scene.PhysicsWorld3D",
                    $"{DescribeEditorPluginState(pluginManager)} error={stopError?.Message}");

                var secondStartError = CaptureException(session.StartPreview);
                var secondStopError = CaptureException(session.StopPreview);
                var finalRegistrationCount = GetEditorPluginManager(session)?.Registry.Registrations.Count ?? -1;
                scripting = GetResolvedPlugin<CubitScriptingPlugin>(GetEditorPluginManager(session));
                Check(
                    "完整项目预览可重复启停且不重复 ClassDB 注册",
                    secondStartError is null && secondStopError is null && registrationCount == finalRegistrationCount &&
                    GetScriptingRuntime(scripting) is null,
                    $"start={secondStartError?.Message} stop={secondStopError?.Message} registrations={registrationCount}->{finalRegistrationCount} runtime={GetScriptingRuntime(scripting) is not null}");
            }
        }
        finally
        {
            session?.Dispose();
        }
    }
    finally
    {
        if (Directory.Exists(root))
        {
            Directory.Delete(root, true);
        }
    }

    Console.WriteLine(failures == 0 ? "editorplugincheck 全部通过" : $"editorplugincheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static HashSet<string> GetEditorProjectReferences()
{
    var repositoryRoot = FindCubitRepositoryRoot();
    if (repositoryRoot is null)
    {
        return [];
    }

    var projectPath = Path.Combine(repositoryRoot, "src", "Cubit.Editor", "Cubit.Editor.csproj");
    if (!File.Exists(projectPath))
    {
        return [];
    }

    return XDocument.Load(projectPath)
        .Descendants()
        .Where(element => element.Name.LocalName == "ProjectReference")
        .Select(element => element.Attribute("Include")?.Value)
        .Where(include => !string.IsNullOrWhiteSpace(include))
        .Select(include => Path.GetFileNameWithoutExtension(include!.Replace('\\', '/')))
        .ToHashSet(StringComparer.Ordinal);
}

static PluginManager? GetEditorPluginManager(ProjectSceneSession? session) =>
    session is null
        ? null
        : typeof(ProjectSceneSession)
            .GetField("_pluginManager", BindingFlags.Instance | BindingFlags.NonPublic)
            ?.GetValue(session) as PluginManager;

static TPlugin? GetResolvedPlugin<TPlugin>(PluginManager? manager) where TPlugin : class, IEnginePlugin =>
    manager?.ResolvedPlugins.OfType<TPlugin>().SingleOrDefault();

static IReadOnlyList<EngineDiagnostic> GetContentPluginDiagnostics(CubitContentPlugin? plugin) =>
    plugin is null
        ? []
        : typeof(CubitContentPlugin)
            .GetField("_diagnostics", BindingFlags.Instance | BindingFlags.NonPublic)
            ?.GetValue(plugin) is DiagnosticBag diagnostics
                ? diagnostics.Snapshot()
                : [];

static ScriptRuntime? GetScriptingRuntime(CubitScriptingPlugin? plugin) =>
    plugin is null
        ? null
        : typeof(CubitScriptingPlugin)
            .GetField("_runtime", BindingFlags.Instance | BindingFlags.NonPublic)
            ?.GetValue(plugin) as ScriptRuntime;

static ContentService? GetSessionContentService(ProjectSceneSession? session) =>
    session is null
        ? null
        : typeof(ProjectSceneSession)
            .GetField("_previewContentService", BindingFlags.Instance | BindingFlags.NonPublic)
            ?.GetValue(session) as ContentService;

static WeakReference? GetPreviewBootstrapLoadContextReference(ProjectSceneSession? session) =>
    session is null
        ? null
        : typeof(ProjectSceneSession)
            .GetField("_previewBootstrapLoadContextReference", BindingFlags.Instance | BindingFlags.NonPublic)
            ?.GetValue(session) as WeakReference;

static AssemblyLoadContext? GetPreviewBootstrapLoadContext(ProjectSceneSession? session) =>
    session is null
        ? null
        : typeof(ProjectSceneSession)
            .GetField("_previewBootstrapLoadContext", BindingFlags.Instance | BindingFlags.NonPublic)
            ?.GetValue(session) as AssemblyLoadContext;

static string[] GetPreviewLoadContextNames() =>
    AssemblyLoadContext.All
        .Select(context => context.Name)
        .Where(name => name?.StartsWith("CubitPreview:", StringComparison.Ordinal) == true)
        .Cast<string>()
        .ToArray();

static bool IsEditorPluginStarted<TPlugin>(PluginManager? manager, TPlugin? plugin) where TPlugin : class, IEnginePlugin
{
    if (manager is null || plugin is null || !manager.IsStarted)
    {
        return false;
    }

    return plugin switch
    {
        CubitPhysicsPlugin physics => physics.IsStarted,
        CubitAnimationPlugin animation => animation.IsStarted,
        CubitAudioPlugin audio => audio.IsStarted,
        CubitScriptingPlugin scripting => scripting.IsStarted,
        CubitContentPlugin => true,
        CubitVoxelPlugin => true,
        _ => false,
    };
}

static string GetIndependentPreviewAssemblyPath()
{
    var repositoryRoot = FindCubitRepositoryRoot()
        ?? throw new InvalidOperationException("找不到 Cubit 仓库根目录");
    var workspaceRoot = Directory.GetParent(repositoryRoot)?.FullName
        ?? throw new InvalidOperationException("找不到 Cubit 工作区根目录");
    return Path.Combine(
        workspaceRoot,
        "通用3D-ECS示例项目",
        "src",
        "Cubit.Ecs.Sample",
        "bin",
        "Debug",
        "net9.0",
        "Cubit.Ecs.Sample.dll");
}

static bool IsAssemblyLoaded(string path)
{
    var fullPath = Path.GetFullPath(path);
    return AppDomain.CurrentDomain.GetAssemblies().Any(assembly =>
    {
        try
        {
            return string.Equals(assembly.Location, fullPath, StringComparison.OrdinalIgnoreCase);
        }
        catch (NotSupportedException)
        {
            return false;
        }
    });
}

static string DescribeEditorPluginState(PluginManager? manager)
{
    if (manager is null)
    {
        return "manager=missing";
    }

    return string.Join(
        ',',
        manager.ResolvedPlugins.Select(plugin => plugin switch
        {
            CubitPhysicsPlugin physics => $"{physics.Id}:started={physics.IsStarted}",
            CubitAnimationPlugin animation => $"{animation.Id}:started={animation.IsStarted}",
            CubitAudioPlugin audio => $"{audio.Id}:started={audio.IsStarted};server={audio.Server is not null}",
            CubitScriptingPlugin scripting => $"{scripting.Id}:started={scripting.IsStarted}",
            _ => $"{plugin.Id}:started=unknown",
        }));
}

static int BenchmarkCheck(uint seed, string? jsonOutputPath)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    const int radius = 3;
    const int measuredFrames = 240;
    const int measuredRounds = 5;
    var workerCounts = new[] { 1, new JobSystemOptions().WorkerCount }.Distinct().ToArray();
    var runs = new List<BenchmarkEvidenceRun>(workerCounts.Length * measuredRounds);
    foreach (var workerCount in workerCounts)
    {
        _ = RunBenchmarkSample(seed, radius, measuredFrames, workerCount, 0);
        for (var round = 1; round <= measuredRounds; round++)
        {
            runs.Add(RunBenchmarkSample(seed, radius, measuredFrames, workerCount, round));
        }
    }

    var measuredRuns = runs.ToArray();
    var first = measuredRuns[0];
    var hashesMatch = measuredRuns.All(run => run.BlockHash == first.BlockHash && run.MeshHash == first.MeshHash);
    Check("单 worker 与默认 worker 各五轮均生成 49 区块和网格", measuredRuns.All(run => run.Chunks == 49 && run.Meshes == 49),
        string.Join(';', measuredRuns.Select(run => $"w{run.WorkerCount}/r{run.Round}:chunks={run.Chunks},meshes={run.Meshes}")));
    Check("单 worker 与默认 worker 测量前流式阶段均已排空", measuredRuns.All(run => run.PendingBeforeMeasurement == 0),
        string.Join(',', measuredRuns.Select(run => $"w{run.WorkerCount}:{run.PendingBeforeMeasurement}")));
    Check("单/多 worker 区块与网格哈希一致", hashesMatch, $"blocks={first.BlockHash} meshes={first.MeshHash}");
    Check(
        "单 worker 与默认 worker 请求均被运行时实际采用",
        measuredRuns.All(run => run.WorkerCount == run.RequestedWorkerCount),
        string.Join(',', measuredRuns.Select(run => $"requested={run.RequestedWorkerCount},actual={run.WorkerCount}")));
    Check("单 worker 与默认 worker 计时与分配有效", measuredRuns.All(run =>
        run.GenerationMilliseconds > 0d && run.MeshMilliseconds > 0d &&
        run.FrameP95Milliseconds >= 0d && run.FrameP95Milliseconds < 100d &&
        run.GenerationAllocatedBytes >= 0 && run.MeshingAllocatedBytes >= 0 && run.FrameAllocatedBytes >= 0),
        $"p95={Percentile(measuredRuns.Select(run => run.FrameP95Milliseconds), 0.95):F3}ms");

    var report = new BenchmarkEvidenceRecord(
        "cubit.benchmark-evidence/v2",
        DateTimeOffset.UtcNow,
        new BenchmarkEnvironmentRecord(
            Environment.Version.ToString(),
            RuntimeInformation.FrameworkDescription,
            RuntimeInformation.OSDescription,
            RuntimeInformation.ProcessArchitecture.ToString(),
            RuntimeInformation.OSArchitecture.ToString(),
            Environment.ProcessorCount,
            Stopwatch.Frequency,
            GetToolAssemblyFingerprint()),
        new BenchmarkScenarioRecord(seed, "noise", radius, measuredFrames, measuredRounds, workerCounts, 1.0 / 60.0),
        measuredRuns,
        new BenchmarkEvidenceSummary(
            Median(measuredRuns.Select(run => run.GenerationMilliseconds)),
            Median(measuredRuns.Select(run => run.MeshMilliseconds)),
            Percentile(measuredRuns.SelectMany(run => run.FrameMilliseconds), 0.95),
            Median(measuredRuns.Select(run => (double)run.GenerationAllocatedBytes)),
            Median(measuredRuns.Select(run => (double)run.MeshingAllocatedBytes)),
            Median(measuredRuns.Select(run => (double)run.FrameAllocatedBytes))),
        new BenchmarkBaselineComparison(
            "unavailable",
            "迁移前没有保存同机器、同场景、同命令的 p95 原始样本；本记录不得推算 10% 回退结论"));
    var reportJson = JsonSerializer.Serialize(report, new JsonSerializerOptions
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        WriteIndented = true,
    });
    using (var reportDocument = JsonDocument.Parse(reportJson))
    {
        var root = reportDocument.RootElement;
        var hasActualWorkerEvidence = root.TryGetProperty("runs", out var workerEvidenceRuns) &&
            workerEvidenceRuns.EnumerateArray().All(run =>
                run.TryGetProperty("workerCount", out var actualWorkerCount) &&
                run.TryGetProperty("requestedWorkerCount", out var requestedWorkerCount) &&
                actualWorkerCount.ValueKind == JsonValueKind.Number &&
                requestedWorkerCount.ValueKind == JsonValueKind.Number &&
                actualWorkerCount.GetInt32() == requestedWorkerCount.GetInt32());
        Check(
            "基准输出保留可追溯证据",
            root.TryGetProperty("schema", out _) &&
            root.TryGetProperty("recordedAtUtc", out _) &&
            root.TryGetProperty("environment", out _) &&
             root.TryGetProperty("scenario", out var scenario) &&
             scenario.TryGetProperty("workerCounts", out var scenarioWorkers) && scenarioWorkers.GetArrayLength() == workerCounts.Length &&
             root.TryGetProperty("runs", out var runArray) && runArray.GetArrayLength() == measuredRounds * workerCounts.Length &&
            runArray.EnumerateArray().All(run =>
                run.TryGetProperty("workerCount", out _) &&
                run.TryGetProperty("frameMilliseconds", out var frames) && frames.GetArrayLength() == measuredFrames) &&
            root.TryGetProperty("baselineComparison", out var comparison) &&
            comparison.TryGetProperty("status", out var status) && status.GetString() == "unavailable",
            "需要版本、环境、场景、五轮原始样本和历史对照状态");
        Check(
            "基准证据同时记录并核对请求与实际 worker 数",
            hasActualWorkerEvidence,
            "每轮必须包含 workerCount 与 requestedWorkerCount，且二者相等");
    }

    if (!string.IsNullOrWhiteSpace(jsonOutputPath))
    {
        var outputPath = Path.GetFullPath(jsonOutputPath);
        var outputDirectory = Path.GetDirectoryName(outputPath);
        if (string.IsNullOrEmpty(outputDirectory))
        {
            throw new InvalidOperationException($"证据输出路径没有父目录: {jsonOutputPath}");
        }

        Directory.CreateDirectory(outputDirectory);
        File.WriteAllText(outputPath, reportJson + Environment.NewLine);
        Console.WriteLine($"基准证据已写入 {outputPath}");
    }

    Console.WriteLine(reportJson);
    Console.WriteLine(failures == 0 ? "benchmarkcheck 全部通过" : $"benchmarkcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static BenchmarkEvidenceRun RunBenchmarkSample(uint seed, int radius, int measuredFrames, int workerCount, int round)
{
    var expectedChunks = (radius * 2 + 1) * (radius * 2 + 1);
    GC.Collect();
    GC.WaitForPendingFinalizers();
    GC.Collect();
    var world = new VoxelWorld(seed, WorldType.Noise);
    var generationAllocationStart = GC.GetTotalAllocatedBytes(true);
    var timer = Stopwatch.StartNew();
    for (var z = -radius; z <= radius; z++)
    {
        for (var x = -radius; x <= radius; x++)
        {
            world.GenerateChunkAt(x, z);
        }
    }

    timer.Stop();
    var generationMs = timer.Elapsed.TotalMilliseconds;
    var generationAllocations = GC.GetTotalAllocatedBytes(true) - generationAllocationStart;
    var meshingAllocationStart = GC.GetTotalAllocatedBytes(true);
    timer.Restart();
    for (var z = -radius; z <= radius; z++)
    {
        for (var x = -radius; x <= radius; x++)
        {
            world.MeshChunk(x, z);
        }
    }

    timer.Stop();
    var meshingMs = timer.Elapsed.TotalMilliseconds;
    var meshingAllocations = GC.GetTotalAllocatedBytes(true) - meshingAllocationStart;
    var meshes = world.ConsumePendingMeshes();
    var blockHash = HashVoxelBlocks(world);
    var meshHash = HashVoxelMeshes(meshes.ToDictionary(entry => entry.Key, entry => entry.Mesh));

    var originalFixedCamera = Environment.GetEnvironmentVariable("VOXEL_FIXEDCAM");
    var originalWorldType = Environment.GetEnvironmentVariable("VOXEL_WORLDTYPE");
    var frameSamples = new double[measuredFrames];
    var frameAllocations = 0L;
    var pendingBeforeMeasurement = -1;
    var actualWorkerCount = -1;
    try
    {
        Environment.SetEnvironmentVariable("VOXEL_FIXEDCAM", "1");
        Environment.SetEnvironmentVariable("VOXEL_WORLDTYPE", "noise");
        using var session = CreateVoxelProjectSession(new FakeRenderBackend(), seed, workerCount: workerCount);
        var scene = session.Scene;
        var worldNode = RequireVoxelWorld(scene);
        actualWorkerCount = scene.Runtime.Jobs.WorkerCount;
        for (var i = 0; i < 30; i++)
        {
            scene.ProcessFrame(1.0 / 60.0);
        }

        var warmupDeadline = Stopwatch.StartNew();
        while (worldNode.Streamer?.PendingCount > 0 && warmupDeadline.Elapsed < TimeSpan.FromSeconds(30))
        {
            scene.ProcessFrame(1.0 / 60.0);
            Thread.Sleep(1);
        }

        pendingBeforeMeasurement = worldNode.Streamer?.PendingCount ?? -1;
        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();
        var frameAllocationStart = GC.GetTotalAllocatedBytes(true);
        for (var i = 0; i < frameSamples.Length; i++)
        {
            var start = Stopwatch.GetTimestamp();
            scene.ProcessFrame(1.0 / 60.0);
            frameSamples[i] = (Stopwatch.GetTimestamp() - start) * 1000.0 / Stopwatch.Frequency;
        }

        frameAllocations = GC.GetTotalAllocatedBytes(true) - frameAllocationStart;
    }
    finally
    {
        Environment.SetEnvironmentVariable("VOXEL_FIXEDCAM", originalFixedCamera);
        Environment.SetEnvironmentVariable("VOXEL_WORLDTYPE", originalWorldType);
    }

    return new BenchmarkEvidenceRun(
        actualWorkerCount,
        workerCount,
        round,
        expectedChunks,
        world.Store.ChunkKeys.Length,
        meshes.Count,
        pendingBeforeMeasurement,
        blockHash,
        meshHash,
        generationMs,
        meshingMs,
        generationAllocations,
        meshingAllocations,
        Percentile(frameSamples, 0.95),
        frameAllocations,
        frameSamples);
}

static string GetToolAssemblyFingerprint()
{
    var assemblyPath = Assembly.GetExecutingAssembly().Location;
    if (string.IsNullOrEmpty(assemblyPath) || !File.Exists(assemblyPath))
    {
        return "unavailable";
    }

    using var stream = File.OpenRead(assemblyPath);
    return Convert.ToHexString(SHA256.HashData(stream)).ToLowerInvariant();
}

static int VoxelCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var root = FindCubitRepositoryRoot();
    var projectPath = root is null ? null : Path.Combine(root, "src", "Cubit.Voxel", "Cubit.Voxel.csproj");
    Check(
        "Cubit.Voxel 项目存在",
        projectPath is not null && File.Exists(projectPath),
        projectPath ?? "未找到 Cubit 仓库根目录");

    Assembly? assembly = null;
    if (projectPath is not null && File.Exists(projectPath))
    {
        var projectDirectory = Path.GetDirectoryName(projectPath)!;
        var candidates = new[]
        {
            Path.Combine(AppContext.BaseDirectory, "Cubit.Voxel.dll"),
            Path.Combine(projectDirectory, "bin", "Debug", "net9.0", "Cubit.Voxel.dll"),
            Path.Combine(projectDirectory, "bin", "Release", "net9.0", "Cubit.Voxel.dll"),
        };
        var assemblyPath = candidates.FirstOrDefault(File.Exists);
        Check("Cubit.Voxel 可独立构建", assemblyPath is not null, string.Join(" | ", candidates));
        if (assemblyPath is not null)
        {
            try
            {
                assembly = Assembly.LoadFrom(assemblyPath);
            }
            catch (Exception ex)
            {
                Check("Cubit.Voxel 程序集可加载", false, ex.Message);
            }
        }
    }

    if (assembly is not null)
    {
        Check("Cubit.Voxel 独立程序集", assembly != typeof(Node).Assembly, assembly.FullName ?? "");
        var pluginType = assembly.GetType("Cubit.Voxel.CubitVoxelPlugin");
        Check("CubitVoxelPlugin 类型存在", pluginType is not null, pluginType?.FullName ?? "missing");
        if (pluginType is not null)
        {
            try
            {
                var plugin = (IEnginePlugin)(Activator.CreateInstance(pluginType)
                    ?? throw new InvalidOperationException("无法创建 CubitVoxelPlugin"));
                Check(
                    "插件标识与版本",
                    plugin.Id == "cubit.voxel" && plugin.Version == new Version(1, 0, 0),
                    $"id={plugin.Id} version={plugin.Version}");

                using var manager = CreateToolPluginManager([plugin]);
                manager.Configure([new CubitPluginReference { Id = "cubit.voxel", Version = "1.0.0" }]);
                var names = manager.Registry.Registrations.Select(item => item.Name).ToHashSet(StringComparer.Ordinal);
                Check(
                    "插件注册 VoxelWorldNode、VoxelTerrainBody3D 与 WorldConfig",
                    names.SetEquals(["VoxelWorldNode", "VoxelTerrainBody3D", "WorldConfig"]),
                    string.Join(',', names.OrderBy(name => name, StringComparer.Ordinal)));
            }
            catch (Exception ex)
            {
                Check("CubitVoxelPlugin 可注册", false, ex.Message);
            }
        }
    }

    Check(
        "Core 不再解析旧体素类型",
        Cubit.Core.ObjectSystem.ClassDB.ResolveType("Cubit.Core.World.VoxelWorldNode") is null,
        "Cubit.Core.World.VoxelWorldNode");

    Console.WriteLine(failures == 0 ? "voxelcheck 全部通过" : $"voxelcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelGenerationCacheCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var evaluateCount = 0;
    var terrain = new ToolTerrainPass(
        "tool.counting-terrain",
        (in VoxelTerrainColumnContext _, in VoxelTerrainColumn column) =>
        {
            evaluateCount++;
            return column;
        });
    var feature = new ToolRepeatedTerrainQueryFeaturePass(64, 3, 5);
    var world = new VoxelWorld(
        20260808u,
        WorldType.Noise,
        terrainPasses: [terrain],
        featurePasses: [feature]);

    _ = world.CreateGeneratedChunkData(0, 0, CancellationToken.None);
    Check(
        "同一生成区块的特征列查询不重复执行地形通道",
        evaluateCount <= Chunk.SizeX * Chunk.SizeZ,
        $"terrainEvaluations={evaluateCount} expectedMax={Chunk.SizeX * Chunk.SizeZ}");

    evaluateCount = 0;
    var remoteFeature = new ToolRepeatedTerrainQueryFeaturePass(64, Chunk.SizeX, 5);
    var remoteWorld = new VoxelWorld(
        20260808u,
        WorldType.Noise,
        terrainPasses: [terrain],
        featurePasses: [remoteFeature]);
    _ = remoteWorld.CreateGeneratedChunkData(0, 0, CancellationToken.None);
    Check(
        "跨区块特征列查询复用地形通道缓存",
        evaluateCount <= Chunk.SizeX * Chunk.SizeZ + 1,
        $"terrainEvaluations={evaluateCount} expectedMax={Chunk.SizeX * Chunk.SizeZ + 1}");

    Console.WriteLine(failures == 0 ? "voxelgenerationcachecheck 全部通过" : $"voxelgenerationcachecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static bool MeshLayersEqual(ChunkMeshLayers left, ChunkMeshLayers right) =>
    left.Opaque.Vertices.SequenceEqual(right.Opaque.Vertices) &&
    left.Opaque.Indices.SequenceEqual(right.Opaque.Indices) &&
    left.Fluid.Vertices.SequenceEqual(right.Fluid.Vertices) &&
    left.Fluid.Indices.SequenceEqual(right.Fluid.Indices);

static int ProjectFluidDynamicCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    const ushort waterId = 651;
    if (!BlockRegistry.IsRegistered(waterId))
    {
        BlockRegistry.Register(new BlockDef
        {
            Id = waterId,
            Key = "tool.fluid:dynamic_water",
            Name = "Dynamic Fluid Test Water",
            TopTexture = "dirt",
            SideTexture = "dirt",
            RenderShape = BlockRenderShape.Fluid,
            Solid = false,
            Opaque = false,
            LightAttenuation = 1,
        });
    }

    var water = VoxelFluidState.Source(waterId);
    var staticWorld = new VoxelWorld(20260905, WorldType.Flat);
    staticWorld.GenerateChunkAt(0, 0);
    _ = staticWorld.SetBlockDeferred(0, 20, 0, water, out _);
    Check(
        "默认 VoxelWorld 不启用动态流体",
        staticWorld.ScheduledTickCount == 0,
        $"scheduled={staticWorld.ScheduledTickCount}");

    var world = new VoxelWorld(
        20260905,
        WorldType.Flat,
        fluidOptions: new VoxelFluidSimulationOptions { Enabled = true, FluidTickDelay = 5 });
    world.GenerateChunkAt(0, 0);
    var placed = world.SetBlockDeferred(0, 20, 0, water, out _);
    Check(
        "动态流体源水登记计划刻",
        placed && world.ScheduledTickCount == 1,
        $"placed={placed} scheduled={world.ScheduledTickCount}");
    for (var i = 0; i < 5; i++)
    {
        world.Tick();
    }

    var below = world.GetBlock(0, 19, 0);
    Check(
        "五 tick 后生成下落流体",
        VoxelFluidState.TryDecode(below, out var state) &&
        state.Level == VoxelFluidState.SourceLevel && state.Falling,
        below.ToString());

    var blockedWorld = new VoxelWorld(
        20260905,
        WorldType.Flat,
        fluidOptions: new VoxelFluidSimulationOptions { Enabled = true, FluidTickDelay = 5 });
    blockedWorld.GenerateChunkAt(0, 0);
    _ = blockedWorld.SetBlockDeferred(0, 19, 0, BlockRegistry.Stone, out _);
    _ = blockedWorld.SetBlockDeferred(0, 20, 0, water, out _);
    for (var i = 0; i < 5; i++)
    {
        blockedWorld.Tick();
    }

    var side = blockedWorld.GetBlock(1, 20, 0);
    Check(
        "下方受阻时横向生成衰减流体",
        VoxelFluidState.TryDecode(side, out var sideState) &&
        sideState.Level == VoxelFluidState.SourceLevel - 1 && !sideState.Falling,
        side.ToString());

    var persistenceDirectory = Path.Combine(
        Path.GetTempPath(),
        $"cubit-fluid-check-{Guid.NewGuid():N}");
    try
    {
        Directory.CreateDirectory(persistenceDirectory);
        world.Save(persistenceDirectory);
        var restored = WorldFile.Load(
            persistenceDirectory,
            fluidOptions: new VoxelFluidSimulationOptions { Enabled = true, FluidTickDelay = 5 });
    var restoredCoordinates = string.Join(
            ";",
            restored.FluidActivationCoordinates.Select(coordinate =>
                $"{coordinate.X},{coordinate.Y},{coordinate.Z}"));
        Check(
            "动态流体激活坐标保存并重载",
            restored.FluidActivationCoordinates.Count >= 2 &&
            VoxelFluidState.TryDecode(restored.GetBlock(0, 19, 0), out var restoredBelow) &&
            restoredBelow.Falling,
            $"activations={restored.FluidActivationCoordinates.Count} scheduled={restored.ScheduledTickCount} coords={restoredCoordinates}");
    }
    finally
    {
        if (Directory.Exists(persistenceDirectory))
        {
            Directory.Delete(persistenceDirectory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0
        ? "projectfluiddynamiccheck 全部通过"
        : $"projectfluiddynamiccheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int FluidCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    bool Throws<TException>(Action action)
        where TException : Exception
    {
        try
        {
            action();
            return false;
        }
        catch (TException)
        {
            return true;
        }
    }

    static int UploadLayerCount(ChunkMeshLayers layers)
    {
        var renderer = new FakeRenderBackend();
        using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var server = new RenderingServer(renderer);
        using var tree = new SceneTree();
        var node = new VoxelWorldNode { Jobs = jobs, Server = server };
        tree.Root.AddChild(node);

        var world = new VoxelWorld(20260826, WorldType.Flat);
        world.GenerateChunkAt(0, 0);
        var work = world.CreateMeshSnapshot(0, 0)
            ?? throw new InvalidOperationException("测试世界未创建网格快照");
        work.Snapshot.Dispose();
        if (!world.PublishMesh(0, 0, work.Revision, layers))
        {
            throw new InvalidOperationException("测试世界未接受待上传网格");
        }

        node.ReplaceWorld(world);
        tree.ProcessFrame(1d / 60d);
        return renderer.MeshUploadCount;
    }

    const ushort waterLikeId = 500;
    var initialContentHash = BlockRegistry.ContentHash;
    BlockRegistry.Register(new BlockDef
    {
        Id = waterLikeId,
        Key = "tool.fluid:source",
        Name = "Test Fluid",
        TopTexture = "dirt",
        SideTexture = "dirt",
        RenderShape = BlockRenderShape.Fluid,
        Solid = false,
        Opaque = false,
        LightAttenuation = 1,
    });

    var source = VoxelFluidState.Source(waterLikeId);
    var raycastWorld = new VoxelWorld(20260826, WorldType.Flat);
    var raycastChunk = new Chunk();
    raycastChunk.SetBlock(1, 32, 1, source);
    raycastChunk.SetBlock(2, 32, 1, BlockRegistry.Stone);
    raycastWorld.Store.AddChunk(0, 0, raycastChunk);
    var raycastOrigin = new Vector3(0.5f, 32.5f, 1.5f);
    var raycastNone = raycastWorld.Raycast(
        raycastOrigin,
        Vector3.UnitX,
        4f,
        VoxelRaycastFluidMode.None);
    var raycastSourceOnly = raycastWorld.Raycast(
        raycastOrigin,
        Vector3.UnitX,
        4f,
        VoxelRaycastFluidMode.SourceOnly);
    var raycastAny = raycastWorld.Raycast(
        raycastOrigin,
        Vector3.UnitX,
        4f,
        VoxelRaycastFluidMode.Any);
    var defaultRaycast = raycastWorld.Raycast(raycastOrigin, Vector3.UnitX, 4f);
    Check(
        "Raycast None 忽略流体并命中后方石头",
        raycastNone is { Hit: { X: 2, Y: 32, Z: 1 } });
    Check(
        "Raycast SourceOnly 命中静态源流体",
        raycastSourceOnly is { Hit: { X: 1, Y: 32, Z: 1 } });
    Check(
        "Raycast Any 命中静态源流体",
        raycastAny is { Hit: { X: 1, Y: 32, Z: 1 } });
    Check(
        "默认 Raycast 保持命中静态源流体",
        defaultRaycast is { Hit: { X: 1, Y: 32, Z: 1 } });

    raycastChunk.SetBlock(1, 32, 1, VoxelFluidState.FromLevel(waterLikeId, 7, falling: true));
    var flowingSourceOnly = raycastWorld.Raycast(
        raycastOrigin,
        Vector3.UnitX,
        4f,
        VoxelRaycastFluidMode.SourceOnly);
    var flowingAny = raycastWorld.Raycast(
        raycastOrigin,
        Vector3.UnitX,
        4f,
        VoxelRaycastFluidMode.Any);
    Check(
        "Raycast SourceOnly 忽略流动流体并命中后方石头",
        flowingSourceOnly is { Hit: { X: 2, Y: 32, Z: 1 } });
    Check(
        "Raycast Any 命中流动流体",
        flowingAny is { Hit: { X: 1, Y: 32, Z: 1 } });

    raycastChunk.SetBlock(1, 32, 1, new BlockState(waterLikeId, 0));
    Check(
        "Raycast Any 拒绝无效流体编码",
        Throws<InvalidDataException>(() => raycastWorld.Raycast(
            raycastOrigin,
            Vector3.UnitX,
            4f,
            VoxelRaycastFluidMode.Any)));
    Check(
        "Raycast 拒绝未知流体模式",
        Throws<ArgumentOutOfRangeException>(() => raycastWorld.Raycast(
            raycastOrigin,
            Vector3.UnitX,
            4f,
            (VoxelRaycastFluidMode)99)));
    Check("静态源流体编码为 level=8", source.Data == VoxelFluidState.SourceLevel);
    Check(
        "静态源流体可被解码",
        VoxelFluidState.TryDecode(source, out var decoded) &&
        decoded.Level == VoxelFluidState.SourceLevel && !decoded.Falling);
    Check(
        "流体状态拒绝非流体方块",
        Throws<InvalidDataException>(() => VoxelFluidState.FromLevel(BlockRegistry.Stone, VoxelFluidState.SourceLevel)));
    Check(
        "流体状态拒绝未知编码位",
        !VoxelFluidState.TryDecode(new BlockState(waterLikeId, 0x0028), out _));
    Check(
        "流体定义参与内容哈希",
        !string.Equals(initialContentHash, BlockRegistry.ContentHash, StringComparison.Ordinal));
    Check(
        "流体必须透光且有衰减",
        Throws<InvalidDataException>(() => BlockRegistry.Register(new BlockDef
        {
            Id = waterLikeId + 1,
            Key = "tool.fluid:invalid",
            Name = "Invalid Fluid",
            TopTexture = "dirt",
            SideTexture = "dirt",
            RenderShape = BlockRenderShape.Fluid,
            Solid = false,
            Opaque = false,
            LightAttenuation = 0,
        })));

    var store = new ChunkStore();
    var chunk = new Chunk();
    chunk.SetBlock(8, 32, 8, source);
    store.AddChunk(0, 0, chunk);
    LightingEngine.RelightChunk(store, 0, 0);
    var layers = ChunkMesher.Mesh(store, 0, 0);
    Check("流体不进入普通网格", layers.Opaque.Indices.Length == 0);
    Check("满格静态流体生成顶面和四侧面", layers.Fluid.Indices.Length == 30, $"indices={layers.Fluid.Indices.Length}");
    chunk.SetBlock(9, 32, 8, source);
    layers = ChunkMesher.Mesh(store, 0, 0);
    Check("同类流体相邻面被剔除", layers.Fluid.Indices.Length == 48, $"indices={layers.Fluid.Indices.Length}");

    var renderSource = File.ReadAllText(Path.Combine(
        FindCubitRepositoryRoot()!, "src", "Cubit.Core", "Rendering", "VulkanContext.cs"));
    Check(
        "AlphaBlend 按相机距离由远到近",
        renderSource.Contains("blendMode == MaterialBlendMode.AlphaBlend", StringComparison.Ordinal) &&
        renderSource.Contains("OrderByDescending", StringComparison.Ordinal));

    var waterLight = LightingEngine.GetLight(store, 8, 32, 8);
    var airLight = LightingEngine.GetLight(store, 8, 33, 8);
    Check(
        "流体衰减但不遮蔽天空光",
        waterLight.Sky < airLight.Sky && waterLight.Sky > 0,
        $"water={waterLight.Sky} air={airLight.Sky}");

    var triangle = new ChunkMeshData(
        [
            0f, 0f, 0f, 0f, 0f, 1f, 0f,
            1f, 0f, 0f, 1f, 0f, 1f, 0f,
            0f, 1f, 0f, 0f, 1f, 1f, 0f,
        ],
        [0u, 1u, 2u]);
    Check(
        "含流体层的区块创建两个 GPU 网格",
        UploadLayerCount(new ChunkMeshLayers(triangle, triangle)) == 2);
    Check(
        "空流体层不创建 GPU 网格",
        UploadLayerCount(new ChunkMeshLayers(triangle, ChunkMeshData.Empty)) == 1);

    // 地形列通道只决定当前绝对坐标列的基础地表和静态流体，不能读取区块存储。
    var terrainPass = new ToolTerrainPass(
        "tool.terrain:lower",
        static (in VoxelTerrainColumnContext context, in VoxelTerrainColumn column) =>
            context.X == 8 && context.Z == 8
                ? column with
                {
                    SurfaceY = column.SurfaceY - 4,
                    StaticFluid = VoxelFluidState.Source(waterLikeId),
                    FluidSurfaceY = column.SurfaceY,
                }
                : column);
    var forward = new VoxelWorld(20260826, WorldType.Noise, terrainPasses: [terrainPass]);
    forward.GenerateAround(0, 0, 1);
    var reverse = new VoxelWorld(20260826, WorldType.Noise, terrainPasses: [terrainPass]);
    foreach (var (chunkX, chunkZ) in EnumerateChunkSquare(0, 0, 1).Reverse())
    {
        reverse.GenerateChunkAt(chunkX, chunkZ);
    }

    var baseHeight = Math.Clamp(
        WorldGenerator.GetHeight(8, 8, 20260826),
        Chunk.MinY + 1,
        Chunk.MaxYExclusive - 2);
    Check(
        "terrain pass 在地表上方填入静态流体",
        Enumerable.Range(baseHeight - 3, 4)
            .All(y => forward.GetBlock(8, y, 8) == source),
        $"base={baseHeight}");
    Check(
        "terrain pass 只影响所属列",
        forward.GetBlock(7, baseHeight, 8).Id != waterLikeId &&
        forward.GetBlock(8, baseHeight - 4, 8).Id != waterLikeId,
        $"left={forward.GetBlock(7, baseHeight, 8)} bed={forward.GetBlock(8, baseHeight - 4, 8)}");
    Check(
        "terrain pass 不依赖区块生成顺序",
        ComputeVoxelHash(forward) == ComputeVoxelHash(reverse));
    Check(
        "出生高度读取最终流体列",
        forward.GetSpawnHeight(8, 8) == baseHeight + 1,
        $"spawn={forward.GetSpawnHeight(8, 8)} expected={baseHeight + 1}");
    var remoteTerrainPass = new ToolTerrainPass(
        "tool.terrain:remote-lower",
        static (in VoxelTerrainColumnContext context, in VoxelTerrainColumn column) =>
            context.X == 16 && context.Z == 8
                ? column with
                {
                    SurfaceY = column.SurfaceY - 4,
                    StaticFluid = VoxelFluidState.Source(waterLikeId),
                    FluidSurfaceY = column.SurfaceY,
                }
                : column);
    var remoteProbe = new ToolTerrainProbeFeaturePass(16, 8);
    var remoteQueryWorld = new VoxelWorld(
        20260826,
        WorldType.Noise,
        terrainPasses: [remoteTerrainPass],
        featurePasses: [remoteProbe]);
    remoteQueryWorld.GenerateChunkAt(0, 0);
    var remoteBaseHeight = Math.Clamp(
        WorldGenerator.GetHeight(16, 8, 20260826),
        Chunk.MinY + 1,
        Chunk.MaxYExclusive - 2);
    Check(
        "跨区块特征查询读取最终流体列",
        remoteProbe.ObservedSurfaceY == remoteBaseHeight + 1 &&
        remoteProbe.ObservedBlock == source,
        $"surface={remoteProbe.ObservedSurfaceY} block={remoteProbe.ObservedBlock}");
    var flatTerrain = new VoxelWorld(20260826, WorldType.Flat, terrainPasses: [terrainPass]);
    flatTerrain.GenerateChunkAt(0, 0);
    Check(
        "平坦世界不执行 terrain pass",
        flatTerrain.GetBlock(8, WorldGenerator.FlatLayers.Length, 8).IsAir);

    Console.WriteLine(failures == 0 ? "fluidcheck 全部通过" : $"fluidcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static IEnumerable<(int X, int Z)> EnumerateChunkSquare(int centerX, int centerZ, int radius)
    {
        for (var z = centerZ - radius; z <= centerZ + radius; z++)
        {
            for (var x = centerX - radius; x <= centerX + radius; x++)
            {
                yield return (x, z);
            }
        }
    }

    static ulong ComputeVoxelHash(VoxelWorld world)
    {
        var hash = 14695981039346656037UL;
        foreach (var (chunkX, chunkZ) in world.Store.ChunkKeys.OrderBy(key => key.Z).ThenBy(key => key.X))
        {
            for (var y = Chunk.MinY; y < Chunk.MaxYExclusive; y++)
            {
                for (var z = 0; z < Chunk.SizeZ; z++)
                {
                    for (var x = 0; x < Chunk.SizeX; x++)
                    {
                        hash ^= world.GetBlock(chunkX * Chunk.SizeX + x, y, chunkZ * Chunk.SizeZ + z).Packed;
                        hash *= 1099511628211UL;
                    }
                }
            }
        }

        return hash;
    }
}

static string? FindCubitRepositoryRoot()
{
    var current = new DirectoryInfo(Directory.GetCurrentDirectory());
    while (current is not null)
    {
        if (File.Exists(Path.Combine(current.FullName, "src", "Cubit.Core", "Cubit.Core.csproj")))
        {
            return current.FullName;
        }

        current = current.Parent;
    }

    return null;
}

/// <summary>
/// 为旧的体素验收项准备真实 project.cubit.json 与 mainScene，而非由测试代码拼接运行节点。
/// 仅复制清单和主场景，并在场景 JSON 中覆盖测试需要的世界种子。
/// </summary>
static VoxelWorldNode RequireVoxelWorld(GameScene scene) =>
    scene.Tree.GetNode("/Root/World") as VoxelWorldNode
        ?? throw new InvalidOperationException("项目主场景缺少 VoxelWorldNode: /Root/World");

static Camera3D RequireCamera(GameScene scene) =>
    scene.Tree.GetNode("/Root/Camera") as Camera3D
        ?? throw new InvalidOperationException("项目主场景缺少 Camera3D: /Root/Camera");

/// <summary>主场景直接子节点的稳定签名，用于验证加载与重置不丢失作者节点。</summary>
static string[] CaptureRootChildSignatures(Node root) =>
    root.Children
        .Select(node => $"{node.Name}:{node.GetType().FullName ?? node.GetType().Name}")
        .ToArray();

static bool HasRootChildSignatures(Node root, IReadOnlyList<string> expected) =>
    CaptureRootChildSignatures(root).SequenceEqual(expected, StringComparer.Ordinal);

static bool TryReadSceneSummaryChildCount(string? summary, out int childCount)
{
    childCount = -1;
    if (string.IsNullOrWhiteSpace(summary))
    {
        return false;
    }

    try
    {
        using var document = JsonDocument.Parse(summary);
        return document.RootElement.TryGetProperty("children", out var children) &&
            children.TryGetInt32(out childCount);
    }
    catch (JsonException)
    {
        return false;
    }
}

static PluginManager CreateToolPluginManager(IEnumerable<IEnginePlugin> availablePlugins) =>
    new(availablePlugins, new SceneRegistry());

static PluginManager CreateToolPluginManagerWithRegistry(
    IEnumerable<IEnginePlugin> availablePlugins,
    SceneRegistry sceneRegistry) =>
    new(availablePlugins, sceneRegistry);

static VoxelProjectTestSession CreateVoxelProjectSession(
    IRenderBackend renderer,
    uint seed,
    IAudioOutputBackend? audioBackend = null,
    int? workerCount = null,
    WorldType? worldType = null,
    string? projectRootOverride = null)
{
    var repositoryRoot = FindCubitRepositoryRoot()
        ?? throw new InvalidOperationException("找不到 Cubit 仓库根目录");
    var workspaceRoot = Directory.GetParent(repositoryRoot)?.FullName
        ?? throw new InvalidOperationException("找不到 Cubit 工作区根目录");
    var sourceProjectRoot = projectRootOverride ?? Path.Combine(workspaceRoot, "我的第一个cubit项目");
    var sourceManifestPath = Path.Combine(sourceProjectRoot, ProjectIO.ManifestFileName);
    var sourceScenePath = Path.Combine(sourceProjectRoot, "scenes", "gameplay.cscene");
    if (!File.Exists(sourceManifestPath) || !File.Exists(sourceScenePath))
    {
        throw new FileNotFoundException("找不到官方体素项目的清单或主场景", sourceProjectRoot);
    }

    var projectRoot = Path.Combine(Path.GetTempPath(), $"cubit_tool_project_{Guid.NewGuid():N}");
    try
    {
        Directory.CreateDirectory(Path.Combine(projectRoot, "scenes"));
        var manifestText = File.ReadAllText(sourceManifestPath)
            .Replace("\"mainScene\": \"scenes/boot.cscene\"", "\"mainScene\": \"scenes/gameplay.cscene\"", StringComparison.Ordinal);
        File.WriteAllText(Path.Combine(projectRoot, ProjectIO.ManifestFileName), manifestText);

        var sceneDocument = JsonNode.Parse(File.ReadAllText(sourceScenePath)) as JsonObject
            ?? throw new InvalidDataException("官方体素主场景不是 JSON 对象");
        var world = sceneDocument["Children"]?.AsArray()
            .Select(node => node as JsonObject)
            .FirstOrDefault(node => node?["Name"]?.GetValue<string>() == "World")
            ?? throw new InvalidDataException("官方体素主场景缺少 World 节点");
        var properties = world["Properties"] as JsonObject
            ?? throw new InvalidDataException("官方体素 World 节点缺少导出属性");
        properties["Seed"] = seed;
        properties["WorldType"] = (int)(worldType ?? WorldType.Flat);
        File.WriteAllText(
            Path.Combine(projectRoot, "scenes", "gameplay.cscene"),
            sceneDocument.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));
        var sourceScenesRoot = Path.Combine(sourceProjectRoot, "scenes");
        foreach (var sourceScene in Directory.EnumerateFiles(sourceScenesRoot, "*.cscene", SearchOption.AllDirectories))
        {
            var relativeScene = Path.GetRelativePath(sourceScenesRoot, sourceScene);
            var targetScene = Path.Combine(projectRoot, "scenes", relativeScene);
            if (!string.Equals(Path.GetFullPath(sourceScene), Path.GetFullPath(sourceScenePath), StringComparison.OrdinalIgnoreCase))
            {
                Directory.CreateDirectory(Path.GetDirectoryName(targetScene)!);
                File.Copy(sourceScene, targetScene, overwrite: true);
            }
        }

        var sourceAssetsRoot = Path.Combine(sourceProjectRoot, "assets");
        if (Directory.Exists(sourceAssetsRoot))
        {
            foreach (var sourceFile in Directory.EnumerateFiles(sourceAssetsRoot, "*", SearchOption.AllDirectories))
            {
                var relative = Path.GetRelativePath(sourceProjectRoot, sourceFile);
                var targetFile = Path.Combine(projectRoot, relative);
                Directory.CreateDirectory(Path.GetDirectoryName(targetFile)!);
                File.Copy(sourceFile, targetFile, overwrite: true);
            }
        }

        var sourceSavesRoot = Path.Combine(sourceProjectRoot, "saves");
        if (Directory.Exists(sourceSavesRoot))
        {
            foreach (var sourceFile in Directory.EnumerateFiles(sourceSavesRoot, "*", SearchOption.AllDirectories))
            {
                var relative = Path.GetRelativePath(sourceProjectRoot, sourceFile);
                var targetFile = Path.Combine(projectRoot, relative);
                Directory.CreateDirectory(Path.GetDirectoryName(targetFile)!);
                File.Copy(sourceFile, targetFile);
            }
        }

        var input = new InputServer();
        var jobSystemOptions = workerCount is { } count
            ? new JobSystemOptions { WorkerCount = count }
            : null;
        var scene = new GameScene(renderer, ProjectIO.Load(projectRoot), input, audioBackend, jobSystemOptions);
        var voxelInput = scene.Runtime.Context.GetRequiredService<VoxelInputState>();
        return new VoxelProjectTestSession(projectRoot, scene, input, voxelInput);
    }
    catch
    {
        if (Directory.Exists(projectRoot))
        {
            Directory.Delete(projectRoot, recursive: true);
        }

        throw;
    }
}

static int ModuleCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var modules = new List<CubitProjectModuleReference>
    {
        new() { Id = "project.player", Version = "1.0.0", Kind = "feature" },
        new() { Id = "project.combat", Version = "1.0.0", Kind = "feature", Dependencies = ["project.player"] },
        new() { Id = "project.desktop", Version = "1.0.0", Kind = "presentation", Dependencies = ["project.player"] },
    };
    var order = ProjectModuleCatalog.ResolveLoadOrder(modules);
    Check(
        "项目模块按依赖顺序解析",
        order.Select(module => module.Id).SequenceEqual(["project.player", "project.combat", "project.desktop"]),
        string.Join(',', order.Select(module => module.Id)));

    var duplicate = CaptureException(() => ProjectModuleCatalog.ResolveLoadOrder(
        [new CubitProjectModuleReference { Id = "project.player", Version = "1.0.0" },
         new CubitProjectModuleReference { Id = "PROJECT.PLAYER", Version = "1.0.0" }]));
    Check("项目模块拒绝重复 ID", duplicate is InvalidDataException, duplicate?.Message ?? "none");

    var cycle = CaptureException(() => ProjectModuleCatalog.ResolveLoadOrder(
        [new CubitProjectModuleReference { Id = "a", Version = "1.0.0", Dependencies = ["b"] },
         new CubitProjectModuleReference { Id = "b", Version = "1.0.0", Dependencies = ["a"] }]));
    Check("项目模块拒绝循环依赖", cycle is InvalidDataException, cycle?.Message ?? "none");

    var missingDependency = CaptureException(() => ProjectModuleCatalog.ResolveLoadOrder(
        [new CubitProjectModuleReference { Id = "project.combat", Version = "1.0.0", Dependencies = ["project.player"] }]));
    Check("项目模块拒绝缺失依赖", missingDependency is InvalidDataException, missingDependency?.Message ?? "none");

    var conflict = CaptureException(() => ProjectModuleCatalog.ResolveLoadOrder(
        [new CubitProjectModuleReference { Id = "project.a", Version = "1.0.0", Conflicts = ["project.b"] },
         new CubitProjectModuleReference { Id = "project.b", Version = "1.0.0" }]));
    Check("项目模块拒绝显式冲突", conflict is InvalidDataException, conflict?.Message ?? "none");

    try
    {
        var repositoryRoot = FindCubitRepositoryRoot();
        var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
        var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
        var project = projectRoot is null ? null : ProjectIO.Load(projectRoot);
        Check(
            "正式体素项目清单声明模块并通过 ProjectIO",
            project is not null && project.Manifest.Modules.Count == 5 &&
            project.Manifest.Modules.Any(module => module.Id == "project.combat"),
            project is null ? "missing" : string.Join(',', project.Manifest.Modules.Select(module => module.Id)));
        Check(
            "正式体素项目场景声明分类",
            project is not null && project.SceneCatalog.GetById("boot").Category == "flow" &&
            project.SceneCatalog.GetById("gameplay").Category == "gameplay",
            project is null ? "missing" : string.Join(',', project.SceneCatalog.Entries.Select(entry => $"{entry.Id}:{entry.Category}")));
    }
    catch (Exception exception)
    {
        Check("正式体素项目模块清单加载", false, exception.Message);
    }

    Console.WriteLine(failures == 0 ? "modulecheck 全部通过" : $"modulecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int SkeletonCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var tree = new SceneTree();
    var skeleton = new Skeleton3D();
    var rootBone = new Bone3D { Name = "root" };
    var headBone = new Bone3D { Name = "head" };
    skeleton.AddBone(rootBone);
    skeleton.AddBone(headBone, rootBone);
    tree.Root.AddChild(skeleton);

    Check("Skeleton 保存根骨骼和子骨骼", skeleton.Bones.Count == 2 && headBone.Parent == rootBone);
    var duplicate = CaptureException(() => skeleton.AddBone(new Bone3D { Name = "head" }, rootBone));
    Check("Skeleton 拒绝重复骨骼名称", duplicate is InvalidOperationException, duplicate?.Message ?? "none");
    var cycle = CaptureException(() => skeleton.AddBone(rootBone, headBone));
    Check("Skeleton 拒绝循环层级", cycle is InvalidOperationException, cycle?.Message ?? "none");

    Exception? workerMutation = null;
    var worker = new Thread(() =>
    {
        try
        {
            headBone.Rotation = Quaternion.CreateFromAxisAngle(Vector3.UnitY, 0.5f);
        }
        catch (Exception exception)
        {
            workerMutation = exception;
        }
    });
    worker.Start();
    worker.Join();
    Check("Skeleton 变换拒绝 worker 线程访问", workerMutation is InvalidOperationException, workerMutation?.Message ?? "none");

    tree.Dispose();
    Check("Skeleton 退出树后清理骨骼索引", skeleton.Bones.Count == 0 && rootBone.Tree is null && headBone.Tree is null);

    Console.WriteLine(failures == 0 ? "skeletoncheck 全部通过" : $"skeletoncheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int MeshInstanceCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var backend = new FakeRenderBackend();
    using var server = new RenderingServer(backend);
    using var tree = new SceneTree();
    var mesh = new MeshData(
        new float[18],
        [0u, 1u, 2u],
        Vector3.Zero,
        Vector3.Zero,
        Vector3.One);
    var node = new MeshInstance3D { Name = "Part", Server = server, Mesh = mesh };
    tree.Root.AddChild(node);
    Check("MeshInstance3D 入树提交网格", backend.MeshUploadCount == 1 && backend.ActiveMeshCount == 1);

    node.Mesh = new MeshData(
        new float[18],
        [0u, 1u, 2u],
        Vector3.Zero,
        Vector3.Zero,
        Vector3.One);
    Check("MeshInstance3D 替换网格延迟回收旧 RID", backend.MeshUploadCount == 2 && backend.ActiveMeshCount == 2);
    server.BeginFrame();
    server.BeginFrame();
    Check("MeshInstance3D 两帧后只保留新 RID", backend.ActiveMeshCount == 1);

    node.Dispose();
    server.BeginFrame();
    server.BeginFrame();
    Check("MeshInstance3D 退出树释放网格", backend.ActiveMeshCount == 0 && backend.MeshRemovalCount == 2);

    Console.WriteLine(failures == 0 ? "meshinstancecheck 全部通过" : $"meshinstancecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectEntitySceneCatalogCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    try
    {
        var repositoryRoot = FindCubitRepositoryRoot();
        var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
        var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
        if (projectRoot is null)
        {
            Check("首个项目根目录可定位", false, "missing");
