                playerJson.Contains("MyFirstCubitProject.PlayerEcsBridgeNode", StringComparison.Ordinal) &&
                playerJson.Contains("MyFirstCubitProject.PlayerController", StringComparison.Ordinal) &&
                playerJson.Contains("Cubit.Animation.Skeleton3D", StringComparison.Ordinal) &&
                playerJson.Contains("Cubit.Animation.AnimationPlayer", StringComparison.Ordinal),
                playerScenePath ?? "missing");
        }
    }
    catch (Exception exception)
