        Check("玩家实体场景目录检查执行", false, exception.Message);
    }

    Console.WriteLine(failures == 0
        ? "projectentityscenecatalogcheck 全部通过"
        : $"projectentityscenecatalogcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int MeshTransformCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var backend = new FakeRenderBackend();
    using var server = new RenderingServer(backend);
    using var tree = new SceneTree();
    var parent = new Node3D { Name = "Parent", Position = new Vector3(2f, 0f, 0f) };
    var child = new MeshInstance3D
    {
        Name = "Child",
        Server = server,
        Mesh = new MeshData(
            new float[18],
            [0u, 1u, 2u],
            Vector3.Zero,
            new Vector3(-0.5f),
            new Vector3(0.5f)),
    };
    parent.AddChild(child);
    tree.Root.AddChild(parent);
    Check("MeshInstance3D 首次提交层级模型矩阵", backend.MeshTransformUpdateCount == 1,
        $"updates={backend.MeshTransformUpdateCount}");
    var first = backend.LastMeshTransform;
    parent.Position = new Vector3(4f, 1f, -2f);
    parent.Rotation = Quaternion.CreateFromAxisAngle(Vector3.UnitY, MathF.PI * 0.5f);
    parent.Scale = 2f;
    tree.ProcessFrame(1d / 60d);
    Check(
        "父节点变换在渲染网格上更新",
        backend.MeshTransformUpdateCount == 2 && backend.LastMeshTransform != first,
        $"updates={backend.MeshTransformUpdateCount} first={first} current={backend.LastMeshTransform}");
    Check(
        "层级模型矩阵包含父节点平移",
        MathF.Abs(backend.LastMeshTransform.M41 - 4f) < 0.0001f &&
        MathF.Abs(backend.LastMeshTransform.M42 - 1f) < 0.0001f &&
        MathF.Abs(backend.LastMeshTransform.M43 + 2f) < 0.0001f,
        backend.LastMeshTransform.ToString());

    Console.WriteLine(failures == 0 ? "meshtransformcheck 全部通过" : $"meshtransformcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int PlayerModelCheck()
{
