                "HumanoidModel.createMesh: hat = 8x8x8 + CubeDeformation.extend(0.5)");
            var playerSceneRoot = JsonNode.Parse(playerScene) as JsonObject;
            var skinProperties = playerSceneRoot?["Children"]?.AsArray()
                .Select(node => node as JsonObject)
                .FirstOrDefault(node => node?["Name"]?.GetValue<string>() == "PlayerModel")?["Properties"] as JsonObject;
            var slimSkin = new MyFirstCubitProject.PlayerModelNode { SkinPath = "assets/skins/custom.png", SkinLayout = "slim" };
            var slimArm = slimSkin.ResolvePartGeometry(
                "right_arm",
                new Vector3(4f, 12f, 4f),
                new Vector3(-1f, -4f, 0f));
            var slimSleeve = slimSkin.ResolvePartGeometry(
                "right_sleeve",
