                slimSkin.SkinPath == "assets/skins/custom.png" && slimSkin.IsSlimSkin &&
                slimArm.SizePixels.X == 3f && slimArm.CenterOffsetPixels.X == -0.5f && slimArm.TextureArmWidth == 3 &&
                slimSleeve.SizePixels.X == 3.5f && slimSleeve.TextureArmWidth == 3,
                $"base={skinProperties?["SkinPath"]?.GetValue<string>()}/{skinProperties?["SkinLayout"]?.GetValue<string>()} arm={slimArm} sleeve={slimSleeve}");
            Check("项目拥有玩家皮肤资产",
                File.Exists(Path.Combine(projectRoot, "assets", "minecraft", "textures", "entity", "player", "steve.png")) &&
                File.Exists(Path.Combine(projectRoot, "assets", "minecraft", "textures", "entity", "player", "alex.png")),
                Path.Combine(projectRoot, "assets", "minecraft", "textures", "entity", "player"));
            Check("玩家场景声明原版部件表现节点",
                playerScene.Contains("PlayerModelPartNode", StringComparison.Ordinal) &&
                playerScene.Contains("MeshInstance3D", StringComparison.Ordinal), playerScenePath);
            Check("玩家场景声明原版躯干和腿部枢轴",
                playerScene.Contains("\"Name\": \"body\"", StringComparison.Ordinal) &&
                playerScene.Contains("\"Y\": 1.5", StringComparison.Ordinal) &&
                playerScene.Contains("\"Name\": \"left_leg\"", StringComparison.Ordinal) &&
                playerScene.Contains("\"Y\": 0.75", StringComparison.Ordinal), playerScenePath);
            Check("玩家部件声明相对骨骼的局部盒体偏移",
                playerScene.Contains("CenterOffsetPixels", StringComparison.Ordinal) &&
                playerScene.Contains("\"Y\": -6", StringComparison.Ordinal) &&
                playerScene.Contains("\"Y\": 4", StringComparison.Ordinal), playerScenePath);
            var part = new MyFirstCubitProject.PlayerModelPartNode
            {
                PartId = "head",
                SizePixels = new Vector3(8f, 8f, 8f),
                CenterOffsetPixels = new Vector3(0f, 4f, 0f),
            };
            var buildMesh = typeof(MyFirstCubitProject.PlayerModelPartNode).GetMethod(
                "BuildMesh",
                BindingFlags.Instance | BindingFlags.NonPublic);
            var headMesh = buildMesh?.Invoke(part, [RID.None]) as MeshData;
            var faceUvOrigins = headMesh is null
                ? []
                : Enumerable.Range(0, 6)
                    .Select(face => (U: headMesh.Vertices[face * 24 + 3], V: headMesh.Vertices[face * 24 + 4]))
                    .ToArray();
            Check(
                "玩家头部六面使用原版皮肤展开 UV",
                faceUvOrigins.Length == 6 &&
                MathF.Abs(faceUvOrigins[0].U - 16f / 64f) < 0.0001f && MathF.Abs(faceUvOrigins[0].V) < 0.0001f &&
                MathF.Abs(faceUvOrigins[1].U - 24f / 64f) < 0.0001f && MathF.Abs(faceUvOrigins[1].V - 8f / 64f) < 0.0001f &&
                MathF.Abs(faceUvOrigins[2].U - 8f / 64f) < 0.0001f && MathF.Abs(faceUvOrigins[2].V - 8f / 64f) < 0.0001f &&
                MathF.Abs(faceUvOrigins[3].U - 16f / 64f) < 0.0001f && MathF.Abs(faceUvOrigins[3].V - 8f / 64f) < 0.0001f &&
                MathF.Abs(faceUvOrigins[4].U - 24f / 64f) < 0.0001f && MathF.Abs(faceUvOrigins[4].V - 8f / 64f) < 0.0001f &&
                MathF.Abs(faceUvOrigins[5].U - 32f / 64f) < 0.0001f && MathF.Abs(faceUvOrigins[5].V - 8f / 64f) < 0.0001f,
                string.Join(',', faceUvOrigins));
            var topFaceUvs = headMesh is null
                ? []
                : Enumerable.Range(0, 4)
                    .Select(index => (
                        U: headMesh.Vertices[index * 6 + 3],
                        V: headMesh.Vertices[index * 6 + 4]))
                    .ToArray();
            Check(
                "玩家 Cube 顶面严格复刻 ModelPart.Cube 的 DOWN 顶点和 UV 顺序",
                topFaceUvs.Length == 4 &&
                MathF.Abs(topFaceUvs[0].U - 16f / 64f) < 0.0001f && MathF.Abs(topFaceUvs[0].V) < 0.0001f &&
                MathF.Abs(topFaceUvs[1].U - 8f / 64f) < 0.0001f && MathF.Abs(topFaceUvs[1].V) < 0.0001f &&
                MathF.Abs(topFaceUvs[2].U - 8f / 64f) < 0.0001f && MathF.Abs(topFaceUvs[2].V - 8f / 64f) < 0.0001f &&
                MathF.Abs(topFaceUvs[3].U - 16f / 64f) < 0.0001f && MathF.Abs(topFaceUvs[3].V - 8f / 64f) < 0.0001f,
                string.Join(',', topFaceUvs));
        }
    }
    catch (Exception exception)
    {
        Check("玩家模型检查执行", false, exception.Message);
    }

    Console.WriteLine(failures == 0 ? "playermodelcheck 全部通过" : $"playermodelcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int BlockModuleCheck()
{
    var failures = 0;
    var tempRoot = Path.Combine(Path.GetTempPath(), $"cubit_block_module_{Guid.NewGuid():N}");
    Directory.CreateDirectory(tempRoot);
    try
    {
        Check("内置方块使用稳定命名空间 ID",
            BlockRegistry.GetKey(BlockRegistry.Stone) == "cubit.voxel:stone");
        Check("稳定 ID 可解析回内置数字 ID",
            BlockRegistry.GetId("cubit.voxel:stone") == BlockRegistry.Stone);

        var pack = tempRoot;
        var blocks = Path.Combine(pack, "blocks");
        Directory.CreateDirectory(blocks);
        File.WriteAllText(Path.Combine(blocks, "granite.json"), "{\"key\":\"demo:granite\",\"name\":\"花岗岩\",\"topTexture\":\"dirt\",\"sideTexture\":\"dirt\",\"bottomTexture\":\"dirt\"}");
        File.WriteAllText(Path.Combine(blocks, "glass.json"), "{\"key\":\"demo:glass\",\"name\":\"玻璃\",\"topTexture\":\"dirt\",\"sideTexture\":\"dirt\",\"bottomTexture\":\"dirt\",\"opaque\":false}");

        var beforeHash = BlockRegistry.ContentHash;
        var loaded = BlockRegistry.LoadContentPack(pack);
        Check("内容包按确定顺序加载两个方块", loaded.SequenceEqual(["demo:glass", "demo:granite"]));
        var graniteId = BlockRegistry.GetId("demo:granite");
        Check("内容包方块获得稳定运行时 ID", graniteId >= 8 && BlockRegistry.GetKey(graniteId) == "demo:granite");
        Check("图集按内容包方块定义动态纳入纹理", TextureAtlas.GetTile(graniteId, 0) == TextureAtlas.GetTile(BlockRegistry.Dirt, 0));
        Check("内容哈希反映内容包变化", !string.Equals(beforeHash, BlockRegistry.ContentHash, StringComparison.Ordinal));

        var hashBeforeDuplicatePath = BlockRegistry.ContentHash;
        var duplicatePack = Path.Combine(tempRoot, "duplicate");
        var duplicateBlocks = Path.Combine(duplicatePack, "blocks");
        Directory.CreateDirectory(duplicateBlocks);
        File.Copy(Path.Combine(blocks, "granite.json"), Path.Combine(duplicateBlocks, "granite.json"));
        File.Copy(Path.Combine(blocks, "glass.json"), Path.Combine(duplicateBlocks, "glass.json"));
        _ = BlockRegistry.LoadContentPack(duplicatePack);
        Check(
            "相同内容包位于不同目录不会改变内容哈希",
            string.Equals(hashBeforeDuplicatePath, BlockRegistry.ContentHash, StringComparison.Ordinal));

        var worldDirectory = Path.Combine(tempRoot, "world");
        var world = new VoxelWorld(1234, WorldType.Flat);
        world.GenerateChunkAt(0, 0);
        WorldFile.Save(world, worldDirectory);
        Check("level.json 保存内容哈希", File.ReadAllText(Path.Combine(worldDirectory, "level.json")).Contains(BlockRegistry.ContentHash, StringComparison.Ordinal));
        _ = WorldFile.LoadMetadata(worldDirectory);

        BlockRegistry.RegisterAuto(new BlockDef { Key = "demo:later", Name = "后置方块", TopTexture = "dirt", SideTexture = "dirt" });
        CheckThrows<InvalidDataException>("内容变化后拒绝加载旧存档", () => WorldFile.LoadMetadata(worldDirectory));

        using var unknownSection = new MemoryStream();
        using (var writer = new BinaryWriter(unknownSection, System.Text.Encoding.UTF8, leaveOpen: true))
        {
            writer.Write((byte)1);
            for (var i = 0; i < 4096; i++)
            {
                writer.Write(i == 0 ? 65535u : 0u);
            }

            writer.Write((byte)0);
        }

        unknownSection.Position = 0;
        CheckThrows<InvalidDataException>("区块调色板拒绝未知方块", () => Section.Load(new BinaryReader(unknownSection, System.Text.Encoding.UTF8, leaveOpen: true)));
    }
    finally
    {
        if (Directory.Exists(tempRoot))
        {
            Directory.Delete(tempRoot, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "blockmodulecheck 全部通过" : $"blockmodulecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    void Check(string name, bool condition)
    {
        if (condition)
        {
            Console.WriteLine($"  [通过] {name}");
        }
        else
        {
            failures++;
            Console.WriteLine($"  [失败] {name}");
        }
    }

    void CheckThrows<TException>(string name, Action action) where TException : Exception
    {
        try
        {
            action();
            Check(name, false);
        }
        catch (TException)
        {
            Check(name, true);
        }
    }
}

static int PluginCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var core = typeof(Node).Assembly;
    var pluginInterface = core.GetType("Cubit.Core.Plugins.IEnginePlugin");
    var pluginRegistry = core.GetType("Cubit.Core.Plugins.PluginRegistry");
    var pluginManager = core.GetType("Cubit.Core.Plugins.PluginManager");
    var engineContext = core.GetType("Cubit.Core.Plugins.EngineContext");
    var pluginReference = core.GetType("Cubit.Core.Project.CubitPluginReference");

    Check(
        "Core 插件 API 类型齐全",
        pluginInterface is not null && pluginRegistry is not null && pluginManager is not null &&
        engineContext is not null && pluginReference is not null,
        $"interface={pluginInterface is not null} registry={pluginRegistry is not null} " +
        $"manager={pluginManager is not null} context={engineContext is not null} reference={pluginReference is not null}");

    var expectedMembers = new[] { "Id", "Version", "Register", "Start", "Stop" };
    var actualMembers = pluginInterface?.GetMembers().Select(member => member.Name).ToHashSet(StringComparer.Ordinal) ?? [];
    Check(
        "IEnginePlugin 生命周期契约齐全",
        expectedMembers.All(actualMembers.Contains),
        $"missing={string.Join(',', expectedMembers.Where(member => !actualMembers.Contains(member)))}");

    var managerMembers = new[] { "Configure", "Start", "Stop", "ResolvedPlugins", "Registry", "IsStarted" };
    var actualManagerMembers = pluginManager?.GetMembers().Select(member => member.Name).ToHashSet(StringComparer.Ordinal) ?? [];
    Check(
        "PluginManager 公开确定性生命周期入口",
        managerMembers.All(actualManagerMembers.Contains),
        $"missing={string.Join(',', managerMembers.Where(member => !actualManagerMembers.Contains(member)))}");

    var registryMembers = new[]
    {
        "RegisterNode", "RegisterResource", "RegisterComponent", "RegisterSystem",
        "RegisterEditorDock", "RegisterInspectorProvider", "RegisterViewportTool", "Registrations",
    };
    var actualRegistryMembers = pluginRegistry?.GetMembers().Select(member => member.Name).ToHashSet(StringComparer.Ordinal) ?? [];
    Check(
        "PluginRegistry 覆盖插件扩展种类",
        registryMembers.All(actualRegistryMembers.Contains),
        $"missing={string.Join(',', registryMembers.Where(member => !actualRegistryMembers.Contains(member)))}");

    var editorKindNames = Enum.GetNames(typeof(Cubit.Core.Plugins.PluginRegistrationKind));
    Check(
        "PluginRegistry 公开编辑器扩展注册种类",
        editorKindNames.Contains("EditorDock", StringComparer.Ordinal) &&
        editorKindNames.Contains("InspectorProvider", StringComparer.Ordinal) &&
        editorKindNames.Contains("ViewportTool", StringComparer.Ordinal),
        string.Join(',', editorKindNames));

    var contextMembers = new[] { "AddService", "GetRequiredService", "IsMainThread" };
    var actualContextMembers = engineContext?.GetMembers().Select(member => member.Name).ToHashSet(StringComparer.Ordinal) ?? [];
    Check(
        "EngineContext 提供主线程与类型化服务边界",
        contextMembers.All(actualContextMembers.Contains),
        $"missing={string.Join(',', contextMembers.Where(member => !actualContextMembers.Contains(member)))}");

    var pluginsProperty = typeof(CubitProjectManifest).GetProperty("Plugins");
    Check("项目清单公开插件声明", pluginsProperty is not null, $"present={pluginsProperty is not null}");

    var projectDirectory = Path.Combine(Path.GetTempPath(), $"cubit_plugin_project_{Guid.NewGuid():N}");
    try
    {
        var project = ProjectIO.Create(projectDirectory, "插件清单测试");
        using var document = JsonDocument.Parse(File.ReadAllText(project.ManifestPath));
        var hasPlugins = document.RootElement.TryGetProperty("plugins", out var plugins) &&
            plugins.ValueKind == JsonValueKind.Array && plugins.GetArrayLength() == 0;
        Check("新项目显式写入空插件数组", hasPlugins);
    }
    finally
    {
        if (Directory.Exists(projectDirectory)) Directory.Delete(projectDirectory, true);
    }

    var context = new EngineContext();
    var service = new PluginProbeService("core-service");
    var contextException = CaptureException(() => context.AddService(service));
    PluginProbeService? resolvedService = null;
    var resolveException = CaptureException(() => resolvedService = context.GetRequiredService<PluginProbeService>());
    var mainThreadException = CaptureException(() => _ = context.IsMainThread);
    Check(
        "EngineContext 类型化服务与主线程识别",
        contextException is null && resolveException is null && mainThreadException is null &&
        ReferenceEquals(service, resolvedService) && context.IsMainThread,
        $"add={contextException?.Message} get={resolveException?.Message} main={mainThreadException?.Message}");

    var lifecycleTrace = new List<string>();
    var pluginA = new PluginProbe(
        "plugin.a",
        new Version(1, 0, 0),
        lifecycleTrace,
        registry => registry.RegisterNode<PluginProbeNodeA>(typeName: nameof(PluginProbeNodeA)));
    var pluginB = new PluginProbe(
        "plugin.b",
        new Version(2, 1, 0),
        lifecycleTrace,
        registry => registry.RegisterResource<PluginProbeResource>(typeName: nameof(PluginProbeResource)));
    using var manager = CreateToolPluginManager([pluginA, pluginB]);
    var configureException = CaptureException(() => manager.Configure([
        new CubitPluginReference { Id = "plugin.b", Version = "2.1.0" },
        new CubitPluginReference { Id = "plugin.a", Version = "1.0.0" },
    ]));
    var startException = CaptureException(() => manager.Start(context));
    var stopException = CaptureException(manager.Stop);
    Check(
        "插件按项目顺序注册启动并逆序停止",
        configureException is null && startException is null && stopException is null &&
        lifecycleTrace.SequenceEqual([
            "register:plugin.b", "register:plugin.a",
            "start:plugin.b", "start:plugin.a",
            "stop:plugin.a", "stop:plugin.b",
        ]) && !manager.IsStarted,
        $"trace={string.Join('|', lifecycleTrace)} configure={configureException?.Message} " +
        $"start={startException?.Message} stop={stopException?.Message}");

    var editorExtensionsManager = CreateToolPluginManager([
        new PluginProbe(
            "plugin.editor.extensions",
            new Version(1, 0),
            [],
            registry =>
            {
                registry.RegisterEditorDock<PluginProbeService>("world-tools", "世界工具", 20, () => new PluginProbeService("dock"));
                registry.RegisterInspectorProvider<PluginProbeService>(
                    "physics-inspector",
                    "物理属性",
                    "Cubit.Physics.Scene.PhysicsWorld3D",
                    10,
                    () => new PluginProbeService("inspector"));
                registry.RegisterViewportTool<PluginProbeService>("select-tool", "选择工具", 0, () => new PluginProbeService("viewport"));
            }),
    ]);
    var editorExtensionsConfigureError = CaptureException(() => editorExtensionsManager.Configure([
        new CubitPluginReference { Id = "plugin.editor.extensions", Version = "1.0" },
    ]));
    var editorExtensions = editorExtensionsManager.Registry.EditorExtensions;
    var selectedInspector = editorExtensionsManager.Registry.FindInspectorProvider(
        typeof(Cubit.Physics.Scene.PhysicsWorld3D));
    var editorDock = CaptureException(() => editorExtensionsManager.Registry.CreateEditorExtension(
        Cubit.Core.Plugins.PluginRegistrationKind.EditorDock,
        "world-tools"));
    Check(
        "插件可登记 Dock/Inspector/视口工具并在会话 registry 枚举",
        editorExtensionsConfigureError is null &&
        editorExtensions.Count == 3 &&
        editorExtensions.Any(item => item.Kind == Cubit.Core.Plugins.PluginRegistrationKind.EditorDock && item.Id == "world-tools" && item.Title == "世界工具") &&
        editorExtensions.Any(item => item.Kind == Cubit.Core.Plugins.PluginRegistrationKind.InspectorProvider && item.TargetTypeName == "Cubit.Physics.Scene.PhysicsWorld3D") &&
        selectedInspector?.Id == "physics-inspector" &&
        editorDock is null,
        $"configure={editorExtensionsConfigureError?.Message} count={editorExtensions.Count} create={editorDock?.Message}");
    editorExtensionsManager.Dispose();

    var duplicateEditorManager = CreateToolPluginManager([
        new PluginProbe("plugin.editor.a", new Version(1, 0), [], registry => registry.RegisterEditorDock<PluginProbeService>("same-dock", factory: () => new PluginProbeService("a"))),
        new PluginProbe("plugin.editor.b", new Version(1, 0), [], registry => registry.RegisterEditorDock<PluginProbeService>("same-dock", factory: () => new PluginProbeService("b"))),
    ]);
    var duplicateEditorError = CaptureException(() => duplicateEditorManager.Configure([
        new CubitPluginReference { Id = "plugin.editor.a", Version = "1.0" },
        new CubitPluginReference { Id = "plugin.editor.b", Version = "1.0" },
    ]));
    Check(
        "编辑器扩展 ID 冲突被拒绝",
        duplicateEditorError is InvalidOperationException && duplicateEditorError.Message.Contains("same-dock", StringComparison.Ordinal),
        duplicateEditorError?.Message ?? "none");
    duplicateEditorManager.Dispose();

    var offThreadConfigureManager = CreateToolPluginManager([
        new PluginProbe("plugin.thread.configure", new Version(1, 0), []),
    ]);
    Exception? offThreadConfigureError = null;
    var offThreadConfigure = new Thread(() =>
        offThreadConfigureError = CaptureException(() => offThreadConfigureManager.Configure([
            new CubitPluginReference { Id = "plugin.thread.configure", Version = "1.0" },
        ])));
    offThreadConfigure.Start();
    offThreadConfigure.Join();
    Check(
        "插件 Configure 拒绝非所有者线程",
        offThreadConfigureError is InvalidOperationException && !offThreadConfigureManager.ResolvedPlugins.Any(),
        offThreadConfigureError?.GetType().Name ?? "none");
    offThreadConfigureManager.Dispose();

    var offThreadStopManager = CreateToolPluginManager([
        new PluginProbe("plugin.thread.stop", new Version(1, 0), []),
    ]);
    offThreadStopManager.Configure([
        new CubitPluginReference { Id = "plugin.thread.stop", Version = "1.0" },
    ]);
    Exception? offThreadStopError = null;
    var offThreadStop = new Thread(() => offThreadStopError = CaptureException(offThreadStopManager.Stop));
    offThreadStop.Start();
    offThreadStop.Join();
    Check(
        "插件 Stop 拒绝非所有者线程",
        offThreadStopError is InvalidOperationException && !offThreadStopManager.IsStarted,
        offThreadStopError?.GetType().Name ?? "none");
    offThreadStopManager.Dispose();

    Check(
        "插件注册表提交 Node/Resource 到当前会话 registry",
        manager.Registry.Registrations.Count == 2 &&
        manager.SceneRegistry.InstantiateNode(nameof(PluginProbeNodeA)) is PluginProbeNodeA &&
        manager.SceneRegistry.InstantiateResource(nameof(PluginProbeResource)) is PluginProbeResource,
        $"registrations={manager.Registry.Registrations.Count}");

    var retryRegistrationAttempt = 0;
    using var retryManager = CreateToolPluginManager([
        new PluginProbe(
            "plugin.configure.retry",
            new Version(1, 0),
            [],
            registry =>
            {
                if (retryRegistrationAttempt++ == 0)
                {
                    registry.RegisterNode<PluginProbeNodeA>(typeName: "PluginRetryDiscardedNode");
                    throw new InvalidOperationException("simulated register failure");
                }

                registry.RegisterNode<PluginProbeNodeB>(typeName: "PluginRetryCommittedNode");
            }),
    ]);
    var firstRetryError = CaptureException(() => retryManager.Configure([
        new CubitPluginReference { Id = "plugin.configure.retry", Version = "1.0" },
    ]));
    var retryStateWasCleared = retryManager.ResolvedPlugins.Count == 0 && retryManager.Registry.Registrations.Count == 0;
    var secondRetryError = CaptureException(() => retryManager.Configure([
        new CubitPluginReference { Id = "plugin.configure.retry", Version = "1.0" },
    ]));
    Check(
        "插件注册失败后清理暂存状态并允许重试",
        ContainsDiagnostic(firstRetryError, "plugin.configure.retry") && retryStateWasCleared && secondRetryError is null &&
        retryManager.Registry.Registrations.Count == 1 &&
        retryManager.Registry.Registrations[0].Name == "PluginRetryCommittedNode" &&
        retryManager.SceneRegistry.InstantiateNode("PluginRetryDiscardedNode") is null &&
        retryManager.SceneRegistry.InstantiateNode("PluginRetryCommittedNode") is PluginProbeNodeB,
        $"first={firstRetryError?.Message} cleared={retryStateWasCleared} second={secondRetryError?.Message} " +
        $"registrations={retryManager.Registry.Registrations.Count}");

    static Exception? ConfigureError(
        IEnumerable<IEnginePlugin> available,
        IReadOnlyList<CubitPluginReference> declarations)
    {
        try
        {
            using var candidate = CreateToolPluginManager(available);
            candidate.Configure(declarations);
            return null;
        }
        catch (Exception ex)
        {
            return ex;
        }
    }

    var missingError = ConfigureError(
        [],
        [new CubitPluginReference { Id = "plugin.missing", Version = "1.0.0" }]);
    Check("缺失插件返回含 ID 的诊断", ContainsDiagnostic(missingError, "plugin.missing"), missingError?.Message ?? "null");

    var duplicateAvailableError = CaptureException(() =>
    {
        using var _ = CreateToolPluginManager([
            new PluginProbe("plugin.duplicate", new Version(1, 0), []),
            new PluginProbe("PLUGIN.DUPLICATE", new Version(1, 0), []),
        ]);
    });
    Check("可用插件重复 ID 被拒绝", ContainsDiagnostic(duplicateAvailableError, "plugin.duplicate"), duplicateAvailableError?.Message ?? "null");

    var duplicateDeclarationError = ConfigureError(
        [new PluginProbe("plugin.one", new Version(1, 0), [])],
        [
            new CubitPluginReference { Id = "plugin.one", Version = "1.0" },
            new CubitPluginReference { Id = "PLUGIN.ONE", Version = "1.0" },
        ]);
    Check("项目重复声明被拒绝", ContainsDiagnostic(duplicateDeclarationError, "plugin.one"), duplicateDeclarationError?.Message ?? "null");

    var invalidVersionError = ConfigureError(
        [new PluginProbe("plugin.version", new Version(1, 0), [])],
        [new CubitPluginReference { Id = "plugin.version", Version = "latest" }]);
    Check("无效插件版本被拒绝", ContainsDiagnostic(invalidVersionError, "plugin.version"), invalidVersionError?.Message ?? "null");

    var mismatchError = ConfigureError(
        [new PluginProbe("plugin.version", new Version(1, 2, 0), [])],
        [new CubitPluginReference { Id = "plugin.version", Version = "2.0.0" }]);
    Check("插件精确版本不匹配被拒绝", ContainsDiagnostic(mismatchError, "plugin.version"), mismatchError?.Message ?? "null");

    var collisionError = ConfigureError(
        [
            new PluginProbe("plugin.node.a", new Version(1, 0), [], r => r.RegisterNode<PluginProbeNodeA>(typeName: "SharedNode")),
            new PluginProbe("plugin.node.b", new Version(1, 0), [], r => r.RegisterNode<PluginProbeNodeB>(typeName: "SharedNode")),
        ],
        [
            new CubitPluginReference { Id = "plugin.node.a", Version = "1.0" },
            new CubitPluginReference { Id = "plugin.node.b", Version = "1.0" },
        ]);
    Check(
        "插件类型别名冲突被拒绝且包含双方 ID",
        ContainsDiagnostic(collisionError, "plugin.node.a") && ContainsDiagnostic(collisionError, "plugin.node.b"),
        collisionError?.Message ?? "null");

    var invalidSystemError = ConfigureError(
        [new PluginProbe(
            "plugin.invalid-system",
            new Version(1, 0),
            [],
            registry => registry.RegisterSystem<PluginProbeService>())],
        [new CubitPluginReference { Id = "plugin.invalid-system", Version = "1.0" }]);
    Check(
        "插件拒绝把普通类注册为 ECS System",
        ContainsDiagnostic(invalidSystemError, "plugin.invalid-system"),
        invalidSystemError?.Message ?? "null");

    var rollbackTrace = new List<string>();
    using var rollbackManager = CreateToolPluginManager([
        new PluginProbe("plugin.good", new Version(1, 0), rollbackTrace),
        new PluginProbe("plugin.bad", new Version(1, 0), rollbackTrace, failStart: true),
    ]);
    var rollbackConfigureError = CaptureException(() => rollbackManager.Configure([
        new CubitPluginReference { Id = "plugin.good", Version = "1.0" },
        new CubitPluginReference { Id = "plugin.bad", Version = "1.0" },
    ]));
    var rollbackStartError = CaptureException(() => rollbackManager.Start(new EngineContext()));
    Check(
        "启动失败回滚已启动插件",
        rollbackConfigureError is null && ContainsDiagnostic(rollbackStartError, "plugin.bad") &&
        rollbackTrace.SequenceEqual([
            "register:plugin.good", "register:plugin.bad",
            "start:plugin.good", "start:plugin.bad", "stop:plugin.good",
        ]) && !rollbackManager.IsStarted,
        $"trace={string.Join('|', rollbackTrace)} error={rollbackStartError?.Message}");

    Console.WriteLine(failures == 0 ? "plugincheck 全部通过" : $"plugincheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int JobCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var core = typeof(Node).Assembly;
    var jobSystem = core.GetType("Cubit.Core.Jobs.JobSystem");
    var jobHandle = core.GetType("Cubit.Core.Jobs.JobHandle");
    var options = core.GetType("Cubit.Core.Jobs.JobSystemOptions");
    var executionException = core.GetType("Cubit.Core.Jobs.JobExecutionException");
    Check(
        "Core Jobs API 类型齐全",
        jobSystem is not null && jobHandle is not null && options is not null && executionException is not null,
        $"system={jobSystem is not null} handle={jobHandle is not null} " +
        $"options={options is not null} exception={executionException is not null}");

    var expectedMembers = new[] { "WorkerCount", "Schedule", "ScheduleBatch", "ParallelFor", "Dispose" };
    var actualMembers = jobSystem?.GetMembers().Select(member => member.Name).ToHashSet(StringComparer.Ordinal) ?? [];
    Check(
        "JobSystem 调度与关闭入口齐全",
        expectedMembers.All(actualMembers.Contains),
        $"missing={string.Join(',', expectedMembers.Where(member => !actualMembers.Contains(member)))}");

    var expectedDefaultWorkers = Math.Max(1, Environment.ProcessorCount - 1);
    using (var defaultJobs = new JobSystem())
    {
        Check(
            "默认 worker 数保留主线程",
            defaultJobs.WorkerCount == expectedDefaultWorkers,
            $"workers={defaultJobs.WorkerCount} processors={Environment.ProcessorCount}");
    }

    var mainThreadId = Environment.CurrentManagedThreadId;
    var executions = new int[64];
    var workerThreads = new System.Collections.Concurrent.ConcurrentDictionary<int, byte>();
    Exception? batchError;
    bool batchCompleted;
    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 2 }))
    {
        JobHandle? batchHandle = null;
        batchError = CaptureException(() =>
        {
            batchHandle = jobs.ScheduleBatch(
                Enumerable.Range(0, executions.Length).Select(index => (Action<CancellationToken>)(_ =>
                {
                    Interlocked.Increment(ref executions[index]);
                    workerThreads.TryAdd(Environment.CurrentManagedThreadId, 0);
                })),
                "exact-once");
            batchHandle.Complete();
        });
        batchCompleted = batchHandle?.IsCompleted == true;

        var coverage = new int[1000];
        JobHandle? parallelHandle = null;
        var parallelError = CaptureException(() =>
        {
            parallelHandle = jobs.ParallelFor(0, coverage.Length, 37, (start, end, _) =>
            {
                for (var i = start; i < end; i++)
                {
                    Interlocked.Increment(ref coverage[i]);
                }
            }, "coverage");
            parallelHandle.Complete();
        });
        Check(
            "ParallelFor 确定性分片完整覆盖",
            parallelError is null && parallelHandle?.IsCompleted == true && coverage.All(value => value == 1),
            parallelError?.Message ?? $"covered={coverage.Count(value => value == 1)}");

        JobHandle? faultHandle = null;
        var fault = CaptureException(() =>
        {
            faultHandle = jobs.Schedule(_ => throw new InvalidOperationException("boom"), "explode");
            faultHandle.Complete();
        });
        Check(
            "worker 异常携带 Job 名称回传",
            ContainsDiagnostic(fault, "explode") && faultHandle?.IsCompleted == true,
            fault?.Message ?? "null");

        using var cancelled = new CancellationTokenSource();
        cancelled.Cancel();
        JobHandle? cancelledHandle = null;
        var cancellation = CaptureException(() =>
        {
            cancelledHandle = jobs.Schedule(_ => { }, "cancelled", cancelled.Token);
            cancelledHandle.Complete();
        });
        Check(
            "预取消 Job 不执行并回传取消",
            cancellation is OperationCanceledException && cancelledHandle?.IsCompleted == true,
            cancellation?.GetType().Name ?? "null");
    }

    Check(
        "批任务精确一次且只在 worker 执行",
        batchError is null && batchCompleted && executions.All(value => value == 1) &&
        workerThreads.Count > 0 && !workerThreads.ContainsKey(mainThreadId),
        $"error={batchError?.Message} completed={batchCompleted} once={executions.Count(value => value == 1)} " +
        $"threads={string.Join(',', workerThreads.Keys)} main={mainThreadId}");

    var drained = 0;
    var disposableJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    JobHandle? drainHandle = null;
    var drainScheduleError = CaptureException(() => drainHandle = disposableJobs.Schedule(_ =>
    {
        Thread.Sleep(10);
        Interlocked.Increment(ref drained);
    }, "drain"));
    var disposeError = CaptureException(disposableJobs.Dispose);
    var rejected = CaptureException(() => disposableJobs.Schedule(_ => { }, "late"));
    Check(
        "Dispose 排空任务并拒绝新提交",
        drainScheduleError is null && disposeError is null && drainHandle?.IsCompleted == true &&
        drained == 1 && rejected is ObjectDisposedException,
        $"schedule={drainScheduleError?.Message} dispose={disposeError?.Message} " +
        $"drained={drained} rejected={rejected?.GetType().Name}");

    Console.WriteLine(failures == 0 ? "jobcheck 全部通过" : $"jobcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int EcsCheck()
{
    var failures = 0;
    var ecsMainThreadId = Environment.CurrentManagedThreadId;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var core = typeof(Node).Assembly;
    var expectedTypes = new[]
    {
        "Cubit.Core.Ecs.EntityId",
        "Cubit.Core.Ecs.EcsWorld",
        "Cubit.Core.Ecs.CommandBuffer",
        "Cubit.Core.Ecs.IEcsSystem",
        "Cubit.Core.Ecs.EcsSystemDescriptor",
        "Cubit.Core.Ecs.EcsSystemContext",
        "Cubit.Core.Ecs.EcsSystemPhase",
        "Cubit.Core.Ecs.EcsScheduler",
        "Cubit.Core.Scene.EcsNode",
    };
    var missingTypes = expectedTypes.Where(name => core.GetType(name) is null).ToArray();
    Check("Core ECS API 类型齐全", missingTypes.Length == 0, $"missing={string.Join(',', missingTypes)}");

    var world = core.GetType("Cubit.Core.Ecs.EcsWorld");
    var worldMembers = new[]
    {
        "CreateEntity", "DestroyEntity", "IsAlive", "AddComponent", "RemoveComponent",
        "HasComponent", "GetComponent", "Query",
    };
    var actualWorldMembers = world?.GetMembers().Select(member => member.Name).ToHashSet(StringComparer.Ordinal) ?? [];
    Check(
        "EcsWorld 实体组件查询入口齐全",
        worldMembers.All(actualWorldMembers.Contains),
        $"missing={string.Join(',', worldMembers.Where(member => !actualWorldMembers.Contains(member)))}");

    var ecsNode = core.GetType("Cubit.Core.Scene.EcsNode");
    var ecsNodeMembers = new[] { "World", "Scheduler", "WorkerCount", "IsInitialized", "AddSystem" };
    var actualEcsNodeMembers = ecsNode?.GetMembers().Select(member => member.Name).ToHashSet(StringComparer.Ordinal) ?? [];
    Check(
        "EcsNode 桥接场景树与 ECS/Jobs",
        ecsNodeMembers.All(actualEcsNodeMembers.Contains),
        $"missing={string.Join(',', ecsNodeMembers.Where(member => !actualEcsNodeMembers.Contains(member)))}");

    var ecs = new EcsWorld();
    EntityId first = default;
    EntityId second = default;
    EntityId third = default;
    var setupError = CaptureException(() =>
    {
        first = ecs.CreateEntity();
        second = ecs.CreateEntity();
        third = ecs.CreateEntity();
        ecs.AddComponent(first, new EcsProbePosition { X = 1 });
        ecs.AddComponent(first, new EcsProbeVelocity { X = 10 });
        ecs.AddComponent(second, new EcsProbePosition { X = 2 });
        ecs.AddComponent(third, new EcsProbePosition { X = 3 });
        ecs.AddComponent(third, new EcsProbeVelocity { X = 30 });
    });
    Check(
        "generation 实体创建并存活",
        setupError is null && ecs.EntityCount == 3 && first.IsValid && second.IsValid && third.IsValid &&
        ecs.IsAlive(first) && ecs.IsAlive(second) && ecs.IsAlive(third),
        setupError?.Message ?? $"count={ecs.EntityCount}");

    var singleQueryCount = 0;
    var singleQueryError = CaptureException(() =>
    {
        var query = ecs.Query<EcsProbePosition>();
        singleQueryCount = query.Count;
        foreach (var item in query)
        {
            ref var position = ref item.Component;
            position.X += 1;
        }
    });
    Check(
        "单组件查询无分配遍历并原地修改",
        singleQueryError is null && singleQueryCount == 3 &&
        ecs.GetComponent<EcsProbePosition>(first).X == 2 &&
        ecs.GetComponent<EcsProbePosition>(second).X == 3 &&
        ecs.GetComponent<EcsProbePosition>(third).X == 4,
        singleQueryError?.Message ?? $"count={singleQueryCount}");

    var pairQueryCount = 0;
    var pairQueryError = CaptureException(() =>
    {
        var query = ecs.Query<EcsProbePosition, EcsProbeVelocity>();
        pairQueryCount = query.Count;
        foreach (var item in query)
        {
            ref var position = ref item.Component1;
            ref var velocity = ref item.Component2;
            position.X += velocity.X;
        }
    });
    Check(
        "双组件查询只返回交集并原地修改",
        pairQueryError is null && pairQueryCount == 2 &&
        ecs.GetComponent<EcsProbePosition>(first).X == 12 &&
        ecs.GetComponent<EcsProbePosition>(second).X == 3 &&
        ecs.GetComponent<EcsProbePosition>(third).X == 34,
        pairQueryError?.Message ?? $"count={pairQueryCount}");

    var duplicateAdd = CaptureException(() => ecs.AddComponent(first, new EcsProbePosition()));
    Check("同实体重复组件被拒绝", duplicateAdd is InvalidOperationException, duplicateAdd?.Message ?? "null");

    var removeError = CaptureException(() =>
    {
        if (!ecs.RemoveComponent<EcsProbePosition>(second))
        {
            throw new InvalidOperationException("RemoveComponent 返回 false");
        }
    });
    Check(
        "组件 swap-remove 保持剩余稠密存储完整",
        removeError is null && !ecs.HasComponent<EcsProbePosition>(second) &&
        ecs.Query<EcsProbePosition>().Count == 2 && ecs.HasComponent<EcsProbePosition>(third),
        removeError?.Message ?? "");

    EntityId reused = default;
    var lifecycleError = CaptureException(() =>
    {
        ecs.DestroyEntity(first);
        reused = ecs.CreateEntity();
    });
    var staleAccess = CaptureException(() => _ = ecs.GetComponent<EcsProbeVelocity>(first));
    Check(
        "销毁清理组件且复用索引递增 generation",
        lifecycleError is null && reused.Index == first.Index && reused.Generation == first.Generation + 1 &&
        !ecs.IsAlive(first) && ecs.IsAlive(reused) && !ecs.HasComponent<EcsProbeVelocity>(reused) &&
        staleAccess is InvalidOperationException,
        lifecycleError?.Message ?? $"first={first} reused={reused} stale={staleAccess?.GetType().Name}");

    Exception? workerStructuralError = null;
    var worker = new Thread(() => workerStructuralError = CaptureException(() => ecs.CreateEntity()));
    worker.Start();
    worker.Join();
    Check(
        "后台线程直接结构变更被拒绝",
        workerStructuralError is InvalidOperationException,
        workerStructuralError?.Message ?? "null");

    var beforePlaybackCount = ecs.EntityCount;
    var commands = new Cubit.Core.Ecs.CommandBuffer();
    EntityTarget deferred = default;
    var recordError = CaptureException(() =>
    {
        deferred = commands.CreateEntity();
        commands.AddComponent(deferred, new EcsProbePosition { X = 99 });
        commands.RemoveComponent<EcsProbeVelocity>(EntityTarget.Existing(third));
        commands.DestroyEntity(EntityTarget.Existing(second));
    });
    Check(
        "CommandBuffer 记录期间不改变世界",
        recordError is null && commands.Count == 4 && ecs.EntityCount == beforePlaybackCount &&
        ecs.IsAlive(second) && ecs.HasComponent<EcsProbeVelocity>(third) && deferred.IsDeferred,
        recordError?.Message ?? $"commands={commands.Count} entities={ecs.EntityCount}");

    var playbackError = CaptureException(() => commands.Playback(ecs));
    var createdPositions = 0;
    foreach (var item in ecs.Query<EcsProbePosition>())
    {
        if (item.Component.X == 99)
        {
            createdPositions++;
        }
    }
    Check(
        "CommandBuffer 主线程按序提交并在成功后清空",
        playbackError is null && commands.Count == 0 && ecs.EntityCount == beforePlaybackCount &&
        !ecs.IsAlive(second) && !ecs.HasComponent<EcsProbeVelocity>(third) && createdPositions == 1,
        playbackError?.Message ?? $"entities={ecs.EntityCount} created={createdPositions}");

    var staleCommands = new Cubit.Core.Ecs.CommandBuffer();
    var staleRecordError = CaptureException(() => staleCommands.DestroyEntity(EntityTarget.Existing(first)));
    var staleCommandError = CaptureException(() => staleCommands.Playback(ecs));
    Check(
        "CommandBuffer 拒绝失效实体且保留未提交命令",
        staleRecordError is null && staleCommandError is InvalidOperationException && staleCommands.Count == 1,
        staleRecordError?.Message ?? staleCommandError?.Message ?? "null");

    var invalidDeferredCommands = new Cubit.Core.Ecs.CommandBuffer();
    var invalidDeferredRecordError = CaptureException(() =>
        invalidDeferredCommands.AddComponent(new EntityTarget(default, 42), new EcsProbePosition()));
    var invalidDeferredError = CaptureException(() => invalidDeferredCommands.Playback(ecs));
    Check(
        "CommandBuffer 拒绝未知延迟实体",
        invalidDeferredRecordError is null && invalidDeferredError is InvalidOperationException,
        invalidDeferredRecordError?.Message ?? invalidDeferredError?.Message ?? "null");

    var workerCommands = new Cubit.Core.Ecs.CommandBuffer();
    var workerRecordError = CaptureException(() => workerCommands.CreateEntity());
    Exception? workerPlaybackError = null;
    var playbackWorker = new Thread(() => workerPlaybackError = CaptureException(() => workerCommands.Playback(ecs)));
    playbackWorker.Start();
    playbackWorker.Join();
    Check(
        "CommandBuffer 只能在世界主线程 Playback",
        workerRecordError is null && workerPlaybackError is InvalidOperationException && workerCommands.Count == 1,
        workerRecordError?.Message ?? workerPlaybackError?.Message ?? "null");

    static HashSet<Type> Types(params Type[] types) => [.. types];

    var mutableReads = Types(typeof(EcsProbePosition));
    var mutableWrites = Types(typeof(EcsProbeVelocity));
    var frozenDescriptor = new EcsSystemDescriptor(
        "frozen",
        EcsSystemPhase.Update,
        mutableReads,
        mutableWrites);
    mutableReads.Clear();
    mutableWrites.Clear();
    Check(
        "System 描述在构造时冻结读写集合",
        frozenDescriptor.Reads.Contains(typeof(EcsProbePosition)) &&
        frozenDescriptor.Writes.Contains(typeof(EcsProbeVelocity)));

    var scheduleWorld = new EcsWorld();
    using var scheduleJobs = new JobSystem(new JobSystemOptions { WorkerCount = 2 });
    var scheduler = new EcsScheduler(scheduleWorld, scheduleJobs);
    var systemA = new EcsProbeSystem(
        new EcsSystemDescriptor("A", EcsSystemPhase.FixedUpdate, Types(), Types(typeof(EcsProbePosition)), Order: 0),
        _ => { });
    var systemB = new EcsProbeSystem(
        new EcsSystemDescriptor("B", EcsSystemPhase.FixedUpdate, Types(typeof(EcsProbePosition)), Types(), Order: 1),
        _ => { });
    var systemC = new EcsProbeSystem(
        new EcsSystemDescriptor("C", EcsSystemPhase.FixedUpdate, Types(), Types(typeof(EcsProbeVelocity)), Order: 2),
        _ => { });
    var systemD = new EcsProbeSystem(
        new EcsSystemDescriptor("D", EcsSystemPhase.FixedUpdate, Types(), Types(), Order: 3, RequiresMainThread: true),
        _ => { });
    IReadOnlyList<IReadOnlyList<IEcsSystem>>? batches = null;
    var batchBuildError = CaptureException(() =>
    {
        scheduler.Register(systemA);
        scheduler.Register(systemB);
        scheduler.Register(systemC);
        scheduler.Register(systemD);
        batches = scheduler.BuildBatches(EcsSystemPhase.FixedUpdate);
    });
    Check(
        "System 冲突依赖分批且主线程 System 独占屏障",
        batchBuildError is null && batches is { Count: 3 } &&
        batches[0].Select(system => system.Descriptor.Id).SequenceEqual(["A", "C"]) &&
        batches[1].Select(system => system.Descriptor.Id).SequenceEqual(["B"]) &&
        batches[2].Select(system => system.Descriptor.Id).SequenceEqual(["D"]),
        batchBuildError?.Message ?? (batches is null
            ? "null"
            : string.Join(" | ", batches.Select(batch => string.Join(',', batch.Select(system => system.Descriptor.Id))))));

    var duplicateSystemError = CaptureException(() => scheduler.Register(new EcsProbeSystem(
        new EcsSystemDescriptor("a", EcsSystemPhase.FixedUpdate, Types(), Types()),
        _ => { })));
    Check("System ID 大小写不敏感且拒绝重复", duplicateSystemError is InvalidOperationException, duplicateSystemError?.Message ?? "null");

    var guardedWorld = new EcsWorld();
    var guardedEntity = guardedWorld.CreateEntity();
    guardedWorld.AddComponent(guardedEntity, new EcsProbePosition { X = 7 });
    using var guardedJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    var guardedScheduler = new EcsScheduler(guardedWorld, guardedJobs);
    var guardedSetupError = CaptureException(() => guardedScheduler.Register(new EcsProbeSystem(
        new EcsSystemDescriptor("undeclared", EcsSystemPhase.Update, Types(), Types()),
        context => context.World.GetComponent<EcsProbePosition>(guardedEntity).X++)));
    var undeclaredError = guardedSetupError ??
        CaptureException(() => guardedScheduler.ExecutePhase(EcsSystemPhase.Update, 1.0 / 60.0));
    Check(
        "System 未声明组件访问被拒绝且不修改状态",
        ContainsDiagnostic(undeclaredError, "undeclared") && guardedWorld.GetComponent<EcsProbePosition>(guardedEntity).X == 7,
        undeclaredError?.Message ?? "null");

    var executionWorld = new EcsWorld();
    var executionEntity = executionWorld.CreateEntity();
    executionWorld.AddComponent(executionEntity, new EcsProbePosition { X = 1 });
    executionWorld.AddComponent(executionEntity, new EcsProbeVelocity { X = 2 });
    using var executionJobs = new JobSystem(new JobSystemOptions { WorkerCount = 2 });
    var executionScheduler = new EcsScheduler(executionWorld, executionJobs);
    var executionThreads = new System.Collections.Concurrent.ConcurrentDictionary<string, int>();
    var executionError = CaptureException(() =>
    {
        executionScheduler.Register(new EcsProbeSystem(
            new EcsSystemDescriptor("worker.position", EcsSystemPhase.FixedUpdate, Types(typeof(EcsProbePosition)), Types(typeof(EcsProbePosition)), Order: 0),
            context =>
            {
                executionThreads["position"] = Environment.CurrentManagedThreadId;
                foreach (var item in context.World.Query<EcsProbePosition>()) item.Component.X += 10;
                var target = context.Commands.CreateEntity();
                context.Commands.AddComponent(target, new EcsProbePosition { X = 100 });
            }));
        executionScheduler.Register(new EcsProbeSystem(
            new EcsSystemDescriptor("worker.velocity", EcsSystemPhase.FixedUpdate, Types(typeof(EcsProbeVelocity)), Types(typeof(EcsProbeVelocity)), Order: 1),
            context =>
            {
                executionThreads["velocity"] = Environment.CurrentManagedThreadId;
                foreach (var item in context.World.Query<EcsProbeVelocity>()) item.Component.X += 20;
            }));
        executionScheduler.Register(new EcsProbeSystem(
            new EcsSystemDescriptor("main", EcsSystemPhase.FixedUpdate, Types(), Types(), Order: 2, RequiresMainThread: true),
            _ => executionThreads["main"] = Environment.CurrentManagedThreadId));
        executionScheduler.ExecutePhase(EcsSystemPhase.FixedUpdate, 0.05);
    });
    Check(
        "无冲突 System 多核执行、主线程 System 固定并确定性提交命令",
        executionError is null && executionThreads["position"] != ecsMainThreadId &&
        executionThreads["velocity"] != ecsMainThreadId && executionThreads["main"] == ecsMainThreadId &&
        executionWorld.EntityCount == 2 && executionWorld.Query<EcsProbePosition>().Count == 2 &&
        executionWorld.GetComponent<EcsProbePosition>(executionEntity).X == 11 &&
        executionWorld.GetComponent<EcsProbeVelocity>(executionEntity).X == 22,
        executionError?.Message ?? string.Join(',', executionThreads.Select(pair => $"{pair.Key}={pair.Value}")));

    var failedWorld = new EcsWorld();
    using var failedJobs = new JobSystem(new JobSystemOptions { WorkerCount = 2 });
    var failedScheduler = new EcsScheduler(failedWorld, failedJobs);
    var failedPhaseError = CaptureException(() =>
    {
        failedScheduler.Register(new EcsProbeSystem(
            new EcsSystemDescriptor("fault", EcsSystemPhase.Update, Types(), Types(), Order: 0, StructuralChanges: true),
            context =>
            {
                context.Commands.CreateEntity();
                throw new InvalidOperationException("system boom");
            }));
        failedScheduler.Register(new EcsProbeSystem(
            new EcsSystemDescriptor("peer", EcsSystemPhase.Update, Types(), Types(), Order: 1, StructuralChanges: true),
            context => context.Commands.CreateEntity()));
        failedScheduler.ExecutePhase(EcsSystemPhase.Update, 0.016);
    });
    Check(
        "失败批次取消并丢弃全部结构命令",
        ContainsDiagnostic(failedPhaseError, "fault") && failedWorld.EntityCount == 0,
        failedPhaseError?.Message ?? "null");

    static long RunDeterministicEcs(int workerCount)
    {
        var world = new EcsWorld();
        for (var i = 0; i < 256; i++)
        {
            var entity = world.CreateEntity();
            world.AddComponent(entity, new EcsProbePosition { X = i });
            world.AddComponent(entity, new EcsProbeVelocity { X = i % 7 - 3 });
            world.AddComponent(entity, new EcsProbeCounter { Value = i * 2 });
        }

        using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = workerCount });
        var scheduler = new EcsScheduler(world, jobs);
        scheduler.Register(new EcsProbeSystem(
            new EcsSystemDescriptor(
                "integrate",
                EcsSystemPhase.FixedUpdate,
                Types(typeof(EcsProbePosition), typeof(EcsProbeVelocity)),
                Types(typeof(EcsProbePosition))),
            context =>
            {
                foreach (var item in context.World.Query<EcsProbePosition, EcsProbeVelocity>())
                {
                    item.Component1.X += item.Component2.X;
                }
            }));
        scheduler.Register(new EcsProbeSystem(
            new EcsSystemDescriptor(
                "counter",
                EcsSystemPhase.FixedUpdate,
                Types(typeof(EcsProbeCounter)),
                Types(typeof(EcsProbeCounter))),
            context =>
            {
                foreach (var item in context.World.Query<EcsProbeCounter>()) item.Component.Value += 3;
            }));

        for (var tick = 0; tick < 1000; tick++)
        {
            scheduler.ExecutePhase(EcsSystemPhase.FixedUpdate, 0.05);
        }

        var hash = 1469598103934665603L;
        foreach (var item in world.Query<EcsProbePosition>()) hash = unchecked((hash ^ item.Component.X) * 1099511628211L);
        foreach (var item in world.Query<EcsProbeCounter>()) hash = unchecked((hash ^ item.Component.Value) * 1099511628211L);
        return hash;
    }

    long singleWorkerHash = 0;
    long multiWorkerHash = 0;
    var deterministicError = CaptureException(() =>
    {
        singleWorkerHash = RunDeterministicEcs(1);
        multiWorkerHash = RunDeterministicEcs(Math.Max(2, Math.Min(4, Environment.ProcessorCount)));
    });
    Check(
        "单 worker 与多 worker 运行 1000 tick 状态哈希一致",
        deterministicError is null && singleWorkerHash == multiWorkerHash,
        deterministicError?.Message ?? $"single={singleWorkerHash} multi={multiWorkerHash}");

    var fixedRuns = 0;
    var updateRuns = 0;
    var renderPrepareRuns = 0;
    var bridgeNode = new EcsNode { Name = "ECS", WorkerCount = 2 };
    using var bridgeTree = new SceneTree();
    var bridgeError = CaptureException(() =>
    {
        bridgeNode.AddSystem(new EcsProbeSystem(
            new EcsSystemDescriptor("bridge.fixed", EcsSystemPhase.FixedUpdate, Types(), Types()),
            _ => Interlocked.Increment(ref fixedRuns)));
        bridgeNode.AddSystem(new EcsProbeSystem(
            new EcsSystemDescriptor("bridge.update", EcsSystemPhase.Update, Types(), Types()),
            _ => Interlocked.Increment(ref updateRuns)));
        bridgeNode.AddSystem(new EcsProbeSystem(
            new EcsSystemDescriptor("bridge.render", EcsSystemPhase.RenderPrepare, Types(), Types()),
            _ => Interlocked.Increment(ref renderPrepareRuns)));
        bridgeTree.Root.AddChild(bridgeNode);
        bridgeTree.ProcessFrame(0.05);
    });
    var initializedBeforeExit = CaptureException(() =>
    {
        if (!bridgeNode.IsInitialized || bridgeNode.Scheduler is null)
        {
            throw new InvalidOperationException("EcsNode 未初始化");
        }
    }) is null;
    bridgeTree.Root.RemoveChild(bridgeNode);
    Check(
        "EcsNode 生命周期驱动三个 phase 并在 ExitTree 关闭",
        bridgeError is null && initializedBeforeExit && !bridgeNode.IsInitialized &&
        fixedRuns == 1 && updateRuns == 1 && renderPrepareRuns == 1,
        bridgeError?.Message ?? $"initialized={initializedBeforeExit} fixed={fixedRuns} update={updateRuns} render={renderPrepareRuns}");
    Check(
        "ClassDB 注册 EcsNode 供场景与编辑器创建",
        Cubit.Core.ObjectSystem.ClassDB.Instantiate("EcsNode") is EcsNode);

    Console.WriteLine(failures == 0 ? "ecscheck 全部通过" : $"ecscheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int EcsProductionCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var cubitRoot = FindCubitRepositoryRoot();
    var workspaceRoot = cubitRoot is null ? null : Directory.GetParent(cubitRoot)?.FullName;
    var projectRoot = workspaceRoot is null
        ? null
        : Path.Combine(workspaceRoot, "通用3D-ECS示例项目");
    var manifestPath = projectRoot is null ? null : Path.Combine(projectRoot, ProjectIO.ManifestFileName);
    var scenePath = projectRoot is null ? null : Path.Combine(projectRoot, "scenes", "main.cscene");
    var csprojPath = projectRoot is null
        ? null
        : Path.Combine(projectRoot, "src", "Cubit.Ecs.Sample", "Cubit.Ecs.Sample.csproj");

    Check("Core-only ECS 正式项目存在", projectRoot is not null && Directory.Exists(projectRoot), projectRoot ?? "未找到工作区根目录");
    Check("ECS 正式项目清单存在", manifestPath is not null && File.Exists(manifestPath), manifestPath ?? "路径不可用");
    Check("ECS 正式项目场景存在", scenePath is not null && File.Exists(scenePath), scenePath ?? "路径不可用");
    Check("ECS 正式项目 C# 工程存在", csprojPath is not null && File.Exists(csprojPath), csprojPath ?? "路径不可用");

    if (projectRoot is not null && manifestPath is not null && File.Exists(manifestPath))
    {
        var manifestError = CaptureException(() =>
        {
            var project = ProjectIO.Load(projectRoot);
            if (project.Manifest.Plugins.Count != 0)
            {
                throw new InvalidOperationException($"插件数={project.Manifest.Plugins.Count}");
            }
        });
        Check("ECS 正式项目清单不声明官方插件", manifestError is null, manifestError?.Message ?? "");

        var previewError = CaptureException(() =>
        {
            var preview = ProjectIO.Load(projectRoot).Manifest.Preview;
            if (preview is not
                {
                    Assembly: "src/Cubit.Ecs.Sample/bin/Debug/net9.0/Cubit.Ecs.Sample.dll",
                    Type: "Cubit.Ecs.Sample.EcsPreviewBootstrap",
                })
            {
                throw new InvalidOperationException("ECS 正式项目缺少精确预览入口声明");
            }
        });
        Check("ECS 正式项目声明 Core-only 预览入口", previewError is null, previewError?.Message ?? "");
    }

    if (projectRoot is not null && scenePath is not null && File.Exists(scenePath))
    {
        var sceneError = CaptureException(() =>
        {
            var root = ProjectIO.LoadMainScene(ProjectIO.Load(projectRoot), new SceneRegistry());
            if (FindNodes<EcsNode>(root).Count != 1)
            {
                throw new InvalidOperationException("主场景必须包含一个 EcsNode");
            }
        });
        Check("ECS 正式项目主场景包含 EcsNode", sceneError is null, sceneError?.Message ?? "");
    }

    if (csprojPath is not null && File.Exists(csprojPath))
    {
        var projectText = File.ReadAllText(csprojPath);
        var coreOnly = projectText.Contains("Cubit.Core\\Cubit.Core.csproj", StringComparison.OrdinalIgnoreCase) &&
            !projectText.Contains("Cubit.Voxel", StringComparison.OrdinalIgnoreCase) &&
            !projectText.Contains("Cubit.Pixel", StringComparison.OrdinalIgnoreCase) &&
            !projectText.Contains("Cubit.Sample", StringComparison.OrdinalIgnoreCase);
        Check("ECS 正式项目只引用 Cubit.Core", coreOnly, csprojPath);
    }

    var assemblyCandidates = projectRoot is null ? [] : new[]
    {
        Path.Combine(projectRoot, "src", "Cubit.Ecs.Sample", "bin", "Debug", "net9.0", "Cubit.Ecs.Sample.dll"),
        Path.Combine(projectRoot, "src", "Cubit.Ecs.Sample", "bin", "Release", "net9.0", "Cubit.Ecs.Sample.dll"),
    };
    var assemblyPath = assemblyCandidates.FirstOrDefault(File.Exists);
    Check("ECS 正式项目已构建", assemblyPath is not null, string.Join(" | ", assemblyCandidates));

    Assembly? assembly = null;
    if (assemblyPath is not null)
    {
        var loadError = CaptureException(() => assembly = Assembly.LoadFrom(assemblyPath));
        Check("ECS 正式项目程序集可加载", loadError is null && assembly is not null, loadError?.Message ?? assemblyPath);
    }

    if (assembly is not null && projectRoot is not null)
    {
        var scenarioType = assembly.GetType("Cubit.Ecs.Sample.EcsProductionScenario");
        var previewBootstrapType = assembly.GetType("Cubit.Ecs.Sample.EcsPreviewBootstrap");
        Check(
            "ECS 正式项目提供公开预览引导器",
            previewBootstrapType is { IsPublic: true, IsAbstract: false } &&
            typeof(IProjectPreviewBootstrap).IsAssignableFrom(previewBootstrapType),
            previewBootstrapType?.FullName ?? "missing");
        var run = scenarioType?.GetMethod(
            "Run",
            BindingFlags.Public | BindingFlags.Static,
            [typeof(string), typeof(int), typeof(int), typeof(int)]);
        Check("ECS 正式项目公开运行场景 API", run is not null, scenarioType?.FullName ?? "missing");
        if (run is not null)
        {
            object? oneWorkerReport = null;
            object? multiWorkerReport = null;
            var runError = CaptureException(() =>
            {
                oneWorkerReport = run.Invoke(null, [projectRoot, 1, 4096, 120]);
                multiWorkerReport = run.Invoke(null, [projectRoot, 4, 4096, 120]);
            });
            var runDetail = runError?.ToString() ??
                (oneWorkerReport is not null && multiWorkerReport is not null ? "" : "null report");
            Check("ECS 正式项目可运行", runError is null && oneWorkerReport is not null && multiWorkerReport is not null, runDetail);

            if (runError is null && oneWorkerReport is not null && multiWorkerReport is not null)
            {
                int ReadInt(object report, string property) => (int)(report.GetType().GetProperty(property)?.GetValue(report)
                    ?? throw new InvalidOperationException($"缺少报告属性: {property}"));
                long ReadLong(object report, string property) => (long)(report.GetType().GetProperty(property)?.GetValue(report)
                    ?? throw new InvalidOperationException($"缺少报告属性: {property}"));
                bool ReadBool(object report, string property) => (bool)(report.GetType().GetProperty(property)?.GetValue(report)
                    ?? throw new InvalidOperationException($"缺少报告属性: {property}"));

                var reportError = CaptureException(() =>
                {
                    var singleHash = ReadLong(oneWorkerReport, "StateHash");
                    var multiHash = ReadLong(multiWorkerReport, "StateHash");
                    Check(
                        "ECS 正式项目单 worker 与多 worker 状态一致",
                        singleHash == multiHash,
                        $"single={singleHash} multi={multiHash}");
                    Check(
                        "ECS 正式项目复用宿主共享 JobSystem",
                        ReadBool(multiWorkerReport, "UsesSharedJobSystem"),
                        ReadBool(multiWorkerReport, "UsesSharedJobSystem").ToString());
                    Check(
                        "ECS 正式项目驱动高数量同构实体",
                        ReadInt(multiWorkerReport, "EntityCount") == 4096,
                        $"entities={ReadInt(multiWorkerReport, "EntityCount")}");
                    Check(
                        "EcsNode 通过 SceneTree 驱动固定与渲染准备阶段",
                        ReadInt(multiWorkerReport, "FixedStepCount") == 120 &&
                        ReadInt(multiWorkerReport, "RenderPrepareCount") == 120,
                        $"fixed={ReadInt(multiWorkerReport, "FixedStepCount")} render={ReadInt(multiWorkerReport, "RenderPrepareCount")}");
                    Check(
                        "无冲突 ECS System 在 worker 执行且渲染准备保留主线程",
                        ReadInt(multiWorkerReport, "IntegrateWorkerThreadId") != ReadInt(multiWorkerReport, "MainThreadId") &&
                        ReadInt(multiWorkerReport, "PhaseWorkerThreadId") != ReadInt(multiWorkerReport, "MainThreadId") &&
                        ReadInt(multiWorkerReport, "RenderPrepareThreadId") == ReadInt(multiWorkerReport, "MainThreadId"),
                        $"integrate={ReadInt(multiWorkerReport, "IntegrateWorkerThreadId")} phase={ReadInt(multiWorkerReport, "PhaseWorkerThreadId")} main={ReadInt(multiWorkerReport, "MainThreadId")} render={ReadInt(multiWorkerReport, "RenderPrepareThreadId")}");
                    Check(
                        "ECS 正式项目主线程每帧分配受控",
                        ReadLong(multiWorkerReport, "MainThreadAllocatedBytesPerFrame") >= 0 &&
                        ReadLong(multiWorkerReport, "MainThreadAllocatedBytesPerFrame") < 65536,
                        $"bytes/frame={ReadLong(multiWorkerReport, "MainThreadAllocatedBytesPerFrame")}");
                });
                if (reportError is not null)
                {
                    Check("ECS 正式项目报告字段完整", false, reportError.Message);
                }
            }
        }
    }

    Console.WriteLine(failures == 0 ? "ecsproductioncheck 全部通过" : $"ecsproductioncheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static List<T> FindNodes<T>(Node root) where T : Node
{
    var result = new List<T>();
    Visit(root);
    return result;

    void Visit(Node node)
    {
        if (node is T typed)
        {
            result.Add(typed);
        }

        foreach (var child in node.Children)
        {
            Visit(child);
        }
    }
}

static Exception? CaptureException(Action action)
{
    try
    {
        action();
        return null;
    }
    catch (Exception ex)
    {
        return ex;
    }
}

static bool ContainsDiagnostic(Exception? exception, string expected)
{
    if (exception is null)
    {
        return false;
    }

    if (exception.Message.Contains(expected, StringComparison.OrdinalIgnoreCase))
    {
        return true;
    }

    return exception is AggregateException aggregate &&
        aggregate.InnerExceptions.Any(inner => ContainsDiagnostic(inner, expected));
}

static bool CanCreateMeshData(
    Type meshDataType,
    float[] vertices,
    uint[] indices,
    Vector3 translation,
    Vector3 boundsMin,
    Vector3 boundsMax)
{
    try
    {
        return Activator.CreateInstance(
            meshDataType,
            [vertices, indices, translation, boundsMin, boundsMax]) is not null;
    }
    catch
    {
        return false;
    }
}

static bool RejectsMeshData(
    Type meshDataType,
    float[] vertices,
    uint[] indices,
    Vector3 translation,
    Vector3 boundsMin,
    Vector3 boundsMax)
{
    try
    {
        _ = Activator.CreateInstance(
            meshDataType,
            [vertices, indices, translation, boundsMin, boundsMax]);
        return false;
    }
    catch (System.Reflection.TargetInvocationException exception)
    {
        return exception.InnerException is ArgumentException;
    }
}

static int WorldGenCheck(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    // 1) 同种子跨实例逐方块一致（生成确定性，含光照后数据）
    var a = new VoxelWorld(seed, WorldType.Noise);
    a.GenerateAround(0, 0, 2);
    var b = new VoxelWorld(seed, WorldType.Noise);
    b.GenerateAround(0, 0, 2);
    var mismatches = 0;
    var compared = 0;
    foreach (var key in a.Store.ChunkKeys)
    {
        for (var y = Chunk.MinY; y < Chunk.MaxYExclusive; y++)
        {
            for (var z = 0; z < Chunk.SizeZ; z++)
            {
                for (var x = 0; x < Chunk.SizeX; x++)
                {
                    var wx = key.X * Chunk.SizeX + x;
                    var wz = key.Z * Chunk.SizeZ + z;
                    compared++;
                    if (a.GetBlock(wx, y, wz) != b.GetBlock(wx, y, wz)) mismatches++;
                }
            }
        }
    }
    Check("同种子逐方块一致", mismatches == 0 && compared > 0, $"compared={compared} mismatches={mismatches}");
    Check("生成区块数一致", a.Store.ChunkKeys.Length == b.Store.ChunkKeys.Length, $"chunks={a.Store.ChunkKeys.Length}");
    Check("出生高度一致", a.GetSpawnHeight(24, 24) == b.GetSpawnHeight(24, 24), $"h={a.GetSpawnHeight(24, 24)}");
    Check(
        "噪声世界生成覆盖负 Y 并在最低层放置基岩",
        a.GetBlock(24, Chunk.MinY, 24) == BlockRegistry.Bedrock &&
        a.GetBlock(24, -1, 24) != BlockState.Air,
        $"min={BlockRegistry.GetName(a.GetBlock(24, Chunk.MinY, 24).Id)} y-1={BlockRegistry.GetName(a.GetBlock(24, -1, 24).Id)}");

    // 2) 异种子必须不同（至少一处）
    var c = new VoxelWorld(seed + 1, WorldType.Noise);
    c.GenerateAround(0, 0, 2);
    var differs = false;
    foreach (var key in a.Store.ChunkKeys)
    {
        for (var y = Chunk.MinY; y < Chunk.MaxYExclusive && !differs; y++)
        {
            for (var z = 0; z < Chunk.SizeZ && !differs; z++)
            {
                for (var x = 0; x < Chunk.SizeX && !differs; x++)
                {
                    var wx = key.X * Chunk.SizeX + x;
                    var wz = key.Z * Chunk.SizeZ + z;
                    if (a.GetBlock(wx, y, wz) != c.GetBlock(wx, y, wz)) differs = true;
                }
            }
        }
    }
    Check("异种子数据不同", differs, "seed+1 至少一处方块不同");

    Console.WriteLine(failures == 0 ? "worldgencheck 全部通过" : $"worldgencheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int MesherCheck(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var mesherRepositoryRoot = FindCubitRepositoryRoot();
    var mesherSource = mesherRepositoryRoot is null
        ? string.Empty
        : File.ReadAllText(Path.Combine(mesherRepositoryRoot, "src", "Cubit.Voxel", "World", "ChunkMesher.cs"));
    Check(
        "网格编译使用精确数组而非热路径 List 扩容",
        mesherSource.Contains("CountMeshQuads", StringComparison.Ordinal) &&
        mesherSource.Contains("CollectGreedyCubeQuads", StringComparison.Ordinal) &&
        mesherSource.Contains("ArrayPool<GreedyCubeQuad>.Shared.Rent", StringComparison.Ordinal) &&
        mesherSource.Contains("block.IsAir", StringComparison.Ordinal) &&
        mesherSource.Contains("new float[checked(quadCount * 4 * 7)]", StringComparison.Ordinal) &&
        mesherSource.Contains("new uint[checked(quadCount * 6)]", StringComparison.Ordinal) &&
        !mesherSource.Contains("new List<float>", StringComparison.Ordinal) &&
        !mesherSource.Contains("new List<uint>", StringComparison.Ordinal),
        "体素网格应先统计合并后的四边形数，并一次性写入位置/局部 UV/明暗/瓦片 ID 顶点数组");

    // 1) 实心 3x3 石头的中心区块：所有面被邻居遮挡 → 空网格（面剔除不变量）
    var solid = new VoxelWorld(seed, WorldType.Noise);
    solid.GenerateAround(0, 0, 1);
    for (var cx = -1; cx <= 1; cx++)
    {
        for (var cz = -1; cz <= 1; cz++)
        {
        for (var y = Chunk.MinY; y < Chunk.MaxYExclusive; y++)
            {
                for (var z = 0; z < Chunk.SizeZ; z++)
                {
                    for (var x = 0; x < Chunk.SizeX; x++)
                    {
                        solid.Store.SetBlock(cx * Chunk.SizeX + x, y, cz * Chunk.SizeZ + z, BlockRegistry.Stone);
                    }
                }
            }
        }
    }
    var solidMesh = ChunkMesher.Mesh(solid.Store, 0, 0).Opaque;
    Check(
        "实心中心区块将连续顶/底面合并为两个四边形",
        solidMesh.Vertices.Length == 2 * 4 * 7 && solidMesh.Indices.Length == 2 * 6,
        $"v={solidMesh.Vertices.Length} i={solidMesh.Indices.Length}");
    var single = new VoxelWorld(seed, WorldType.Noise);
    single.GenerateAround(0, 0, 0);
        for (var y = Chunk.MinY; y < Chunk.MaxYExclusive; y++)
    {
        for (var z = 0; z < Chunk.SizeZ; z++)
        {
            for (var x = 0; x < Chunk.SizeX; x++)
            {
                single.Store.SetBlock(x, y, z, BlockRegistry.Stone);
            }
        }
    }
    var singleMesh = ChunkMesher.Mesh(single.Store, 0, 0).Opaque;
    Check(
        "未知邻区不当作空气生成临时侧面",
        singleMesh.Vertices.Length == solidMesh.Vertices.Length && singleMesh.Indices.Length == solidMesh.Indices.Length,
        $"single={singleMesh.Vertices.Length / 24} surrounded={solidMesh.Vertices.Length / 24}");

    // 2) 噪声世界中心区块：顶点/索引结构合法
    var world = new VoxelWorld(seed, WorldType.Noise);
    world.GenerateAround(0, 0, 2);
    var mesh = ChunkMesher.Mesh(world.Store, 0, 0).Opaque;
    var vertexCount = mesh.Vertices.Length / 7;
    Check("网格非空且顶点为 7 元组", mesh.Vertices.Length > 0 && mesh.Vertices.Length % 7 == 0, $"v={mesh.Vertices.Length}");
    Check("索引为三角形且不越界", mesh.Indices.Length > 0 && mesh.Indices.Length % 3 == 0 && mesh.Indices.Max() < vertexCount, $"i={mesh.Indices.Length} max={mesh.Indices.Max()} vc={vertexCount}");
    var boundsOk = true;
    var uvOk = true;
    var shadeOk = true;
    var tileOk = true;
    for (var i = 0; i < mesh.Vertices.Length; i += 7)
    {
        var x = mesh.Vertices[i];
        var y = mesh.Vertices[i + 1];
        var z = mesh.Vertices[i + 2];
        var u = mesh.Vertices[i + 3];
        var v = mesh.Vertices[i + 4];
        var shade = mesh.Vertices[i + 5];
        var tile = mesh.Vertices[i + 6];
        if (x < 0 || x > Chunk.SizeX || y < Chunk.MinY || y > Chunk.MaxYExclusive || z < 0 || z > Chunk.SizeZ) boundsOk = false;
        if (u < 0 || u > Chunk.SizeX || v < 0 || v > Chunk.SizeZ) uvOk = false;
        if (shade < 0 || shade > 1) shadeOk = false;
        if (!float.IsFinite(tile) || tile < 0) tileOk = false;
    }
    Check("顶点坐标在区块内", boundsOk, $"v={mesh.Vertices.Length / 7}");
    Check("局部重复 UV 在区块跨度内", uvOk);
    Check("AO 明暗在 [0,1]", shadeOk);
    Check("顶点携带非负图集瓦片 ID", tileOk);

    // 3) 平坦世界中心区块：顶面和底面各合并为一个四边形；邻居同高时侧面仍被剔除。
    var flat = new VoxelWorld(seed, WorldType.Flat);
    flat.GenerateAround(0, 0, 1);
    var flatMesh = ChunkMesher.Mesh(flat.Store, 0, 0).Opaque;
    var expectedFaces = (WorldGenerator.FlatLayers.Length < Chunk.SizeY ? 1 : 0) + 1;
    var expectedVertices = expectedFaces * 4 * 7;
    var expectedIndices = expectedFaces * 6;
    Check("平坦中心区块合并面数精确", flatMesh.Vertices.Length == expectedVertices && flatMesh.Indices.Length == expectedIndices, $"faces={flatMesh.Vertices.Length / (4 * 7)} 期望 {expectedFaces}");

    // 连续平坦地表的顶面法线方向没有方块，顶面不能被同层相邻方块错误压暗。
    // 区块边缘也必须与内部一致，避免 AO 把边界外数据误当成空气或实体。
    var flatTopShades = new List<float>();
    for (var i = 0; i < flatMesh.Vertices.Length; i += 7)
    {
        if (MathF.Abs(flatMesh.Vertices[i + 1] - WorldGenerator.FlatLayers.Length) < 0.0001f)
        {
            flatTopShades.Add(flatMesh.Vertices[i + 5]);
        }
    }

    var flatTopShadeMin = flatTopShades.Count == 0 ? float.NegativeInfinity : flatTopShades.Min();
    var flatTopShadeMax = flatTopShades.Count == 0 ? float.PositiveInfinity : flatTopShades.Max();
    Check(
        "平坦地表顶面 AO 只采样面外侧且不产生区块边界亮线",
        flatTopShades.Count == 4 &&
        flatTopShadeMin >= 0.999f &&
        flatTopShadeMax <= 1.001f,
        $"vertices={flatTopShades.Count} min={flatTopShadeMin:F3} max={flatTopShadeMax:F3}");

    static int CountHorizontalQuadsInArea(
        float[] vertices,
        float height,
        float minX,
        float maxX,
        float minZ,
        float maxZ)
    {
        var count = 0;
        for (var quadOffset = 0; quadOffset < vertices.Length; quadOffset += 4 * 7)
        {
            var matches = true;
            for (var corner = 0; corner < 4; corner++)
            {
                var offset = quadOffset + corner * 7;
                if (MathF.Abs(vertices[offset + 1] - height) >= 0.0001f ||
                    vertices[offset] < minX || vertices[offset] > maxX ||
                    vertices[offset + 2] < minZ || vertices[offset + 2] > maxZ)
                {
                    matches = false;
                    break;
                }
            }

            if (matches)
            {
                count++;
            }
        }

        return count;
    }

    // 同一平面上相邻但材质不同的顶面不能共用图集瓦片。
    var materialBoundaryStore = new ChunkStore();
    var materialBoundaryChunk = new Chunk();
    materialBoundaryChunk.SetBlock(8, 0, 8, BlockRegistry.GetState(BlockRegistry.Grass));
    materialBoundaryChunk.SetBlock(9, 0, 8, BlockRegistry.GetState(BlockRegistry.Stone));
    materialBoundaryStore.AddChunk(0, 0, materialBoundaryChunk);
    var materialBoundaryMesh = ChunkMesher.Mesh(materialBoundaryStore, 0, 0).Opaque;
    var materialBoundaryTopQuadCount = CountHorizontalQuadsInArea(materialBoundaryMesh.Vertices, 1f, 8f, 10f, 8f, 9f);
    Check(
        "相邻异材质顶面不会被贪心合并",
        materialBoundaryTopQuadCount == 2,
        $"topQuads={materialBoundaryTopQuadCount}");

    // 顶面左侧面外的遮挡体只影响左方块角落 AO；两顶面必须保留为独立四边形。
    var aoBoundaryStore = new ChunkStore();
    var aoBoundaryChunk = new Chunk();
    aoBoundaryChunk.SetBlock(8, 1, 8, BlockRegistry.GetState(BlockRegistry.Grass));
    aoBoundaryChunk.SetBlock(9, 1, 8, BlockRegistry.GetState(BlockRegistry.Grass));
    aoBoundaryChunk.SetBlock(7, 2, 8, BlockRegistry.GetState(BlockRegistry.Grass));
    aoBoundaryStore.AddChunk(0, 0, aoBoundaryChunk);
    var aoBoundaryMesh = ChunkMesher.Mesh(aoBoundaryStore, 0, 0).Opaque;
    var aoBoundaryTopQuadCount = CountHorizontalQuadsInArea(aoBoundaryMesh.Vertices, 2f, 8f, 10f, 8f, 9f);
    Check(
        "相邻不同 AO 顶面不会被贪心合并",
        aoBoundaryTopQuadCount == 2,
        $"topQuads={aoBoundaryTopQuadCount}");

    // 无天空光、无方块光的封闭空腔不能因环境光下限看起来像发光体。
    var enclosedStore = new ChunkStore();
    var enclosedChunk = new Chunk();
        for (var y = Chunk.MinY; y < Chunk.MaxYExclusive; y++)
    {
        for (var z = 0; z < Chunk.SizeZ; z++)
        {
            for (var x = 0; x < Chunk.SizeX; x++)
            {
                enclosedChunk.SetBlock(x, y, z, BlockRegistry.GetState(BlockRegistry.Stone));
            }
        }
    }

    enclosedChunk.SetBlock(8, 8, 8, BlockState.Air);
    enclosedStore.AddChunk(0, 0, enclosedChunk);
    LightingEngine.RelightChunk(enclosedStore, 0, 0);
    var enclosedMesh = ChunkMesher.Mesh(enclosedStore, 0, 0).Opaque;
    var enclosedPocketShades = new List<float>();
    for (var i = 0; i < enclosedMesh.Vertices.Length; i += 7)
    {
        var x = enclosedMesh.Vertices[i];
        var y = enclosedMesh.Vertices[i + 1];
        var z = enclosedMesh.Vertices[i + 2];
        if (x >= 8f && x <= 9f && y >= 8f && y <= 9f && z >= 8f && z <= 9f)
        {
            enclosedPocketShades.Add(enclosedMesh.Vertices[i + 5]);
        }
    }

    var enclosedMaxShade = enclosedPocketShades.Count == 0 ? float.PositiveInfinity : enclosedPocketShades.Max();
    Check(
        "封闭无光空腔不呈现自发光亮度",
        enclosedPocketShades.Count == 24 && enclosedMaxShade <= 0.1001f,
        $"vertices={enclosedPocketShades.Count} maxShade={enclosedMaxShade:F3}");

    Console.WriteLine(failures == 0 ? "meshercheck 全部通过" : $"meshercheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int WorldCheck(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var h1 = WorldGenerator.GetHeight(3, 5, seed);
    var h2 = WorldGenerator.GetHeight(3, 5, seed);
    Check("世界生成确定性（同种子同高度）", h1 == h2, $"h={h1}");

    var world = new VoxelWorld(seed);
    world.GenerateAround(0, 0, VoxelWorld.GenerateRadius);
    var chunkCount = world.Store.ChunkKeys.Count();
    var expectedChunkCount = (VoxelWorld.GenerateRadius * 2 + 1) * (VoxelWorld.GenerateRadius * 2 + 1);
    Check("区块生成（默认视距范围）", chunkCount == expectedChunkCount, $"chunks={chunkCount} expected={expectedChunkCount}");

    var nonEmpty = 0;
    foreach (var key in world.Store.ChunkKeys)
    {
        var mesh = ChunkMesher.Mesh(world.Store, key.X, key.Z).Opaque;
        if (mesh.Vertices.Length > 0 && mesh.Indices.Length > 0) nonEmpty++;
    }
    Check("所有区块网格非空", nonEmpty == chunkCount, $"{nonEmpty}/{chunkCount}");

    var groundY = WorldGenerator.GetHeight(24, 24, seed);
    var camera = new FlyCamera(new Vector3(24f, groundY + 3f, 24f), 0f, -MathF.PI / 2f);
    var hit = world.Raycast(camera.Position, camera.Forward);
    Check("DDA 射线命中地形", hit is { }, hit is { } r ? $"hit=({r.Hit.X},{r.Hit.Y},{r.Hit.Z}) block={BlockRegistry.GetName(world.GetBlock(r.Hit.X, r.Hit.Y, r.Hit.Z))}" : "未命中");
    if (hit is { } r0)
    {
        Check("命中位置正确（正下方地表）", r0.Hit.X == 24 && r0.Hit.Z == 24 && r0.Hit.Y == groundY, $"实际 ({r0.Hit.X},{r0.Hit.Y},{r0.Hit.Z}) 期望 (24,{groundY},24)");
    }

    if (hit is { } target)
    {
        var before = world.GetBlock(target.Hit.X, target.Hit.Y, target.Hit.Z);
        world.SetBlock(target.Hit.X, target.Hit.Y, target.Hit.Z, BlockRegistry.Air);
        var after = world.GetBlock(target.Hit.X, target.Hit.Y, target.Hit.Z);
        var pending = world.ConsumePendingMeshes().Count;
        Check("挖方块生效", before != BlockRegistry.Air && after == BlockRegistry.Air, $"{BlockRegistry.GetName(before)} -> 空气, 待重建网格={pending}");
        Check("挖方块触发区块重建", pending > 0, $"pending={pending}");
    }
    else
    {
        Check("挖方块测试", false, "射线未命中，跳过");
    }

    if (hit is { } t2)
    {
        var before = world.GetBlock(t2.Place.X, t2.Place.Y, t2.Place.Z);
        world.SetBlock(t2.Place.X, t2.Place.Y, t2.Place.Z, BlockRegistry.Wood);
        var after = world.GetBlock(t2.Place.X, t2.Place.Y, t2.Place.Z);
        Check("放方块生效", after == BlockRegistry.Wood && before != BlockRegistry.Wood, $"({t2.Place.X},{t2.Place.Y},{t2.Place.Z}) {BlockRegistry.GetName(before)} -> 木头");
    }

    if (hit is { } t3)
    {
        var (cx, cz) = ChunkStore.WorldToChunk(t3.Hit.X, t3.Hit.Z);
        var meshBefore = ChunkMesher.Mesh(world.Store, cx, cz).Opaque;
        world.SetBlock(t3.Hit.X, t3.Hit.Y, t3.Hit.Z, BlockRegistry.Grass);
        var meshAfter = ChunkMesher.Mesh(world.Store, cx, cz).Opaque;
        Check("网格随方块变化", meshBefore.Vertices.Length != meshAfter.Vertices.Length, $"挖后={meshBefore.Vertices.Length} 放回={meshAfter.Vertices.Length}");
    }

    // 8) 平坦世界（原版超平坦思路）
    var flat = new VoxelWorld(seed, WorldType.Flat);
    flat.GenerateAround(0, 0, VoxelWorld.GenerateRadius);
    var flatTop = flat.GetSpawnHeight(24, 24);
    Check("平坦世界地表高度", flatTop == WorldGenerator.FlatLayers.Length, $"top={flatTop}");

    var uniform = true;
    foreach (var (dx, dz) in new[] { (0, 0), (3, 5), (-7, 2), (9, -4) })
    {
        if (flat.GetSpawnHeight(24 + dx * 4, 24 + dz * 4) != flatTop) uniform = false;
    }
    Check("平坦世界各处高度一致", uniform);

    var layered = flat.GetBlock(24, 0, 24) == BlockRegistry.Bedrock
        && flat.GetBlock(24, 1, 24) == BlockRegistry.Stone
        && flat.GetBlock(24, 3, 24) == BlockRegistry.Dirt
        && flat.GetBlock(24, 4, 24) == BlockRegistry.Grass
        && flat.GetBlock(24, 5, 24) == BlockRegistry.Air;
    Check("平坦世界层叠正确（基岩/石/石/泥土/草/空气）", layered);

    var flatMesh = ChunkMesher.Mesh(flat.Store, 1, 1).Opaque;
    Check("平坦区块网格非空", flatMesh.Vertices.Length > 0 && flatMesh.Indices.Length > 0, $"verts={flatMesh.Vertices.Length} idx={flatMesh.Indices.Length}");
    if (flatMesh.Vertices.Length >= 12)
    {
        Console.WriteLine($"平坦网格顶点样本: {string.Join(",", flatMesh.Vertices.Take(12).Select(v => v.ToString("F2")))}");
    }
    var flatCam = new FlyCamera(new Vector3(24f, flatTop + 2f, 24f), 0f, -MathF.PI / 2f);
    var flatHit = flat.Raycast(flatCam.Position, flatCam.Forward);
    Check("平坦世界射线命中草地", flatHit is { } fh && fh.Hit.Y == flatTop - 1 && flat.GetBlock(fh.Hit.X, fh.Hit.Y, fh.Hit.Z) == BlockRegistry.Grass,
        flatHit is { } fh2 ? $"hit=({fh2.Hit.X},{fh2.Hit.Y},{fh2.Hit.Z})" : "未命中");


    // 8.5) M2 世界存储：Section 调色板 / 区块状态机 / 存档往返
    var section = new Section();
    section.Set(0, 0, 0, BlockRegistry.Grass);
    section.Set(1, 0, 0, BlockRegistry.Dirt);
    section.Set(2, 0, 0, BlockRegistry.Grass);
    Check("Section 调色板去重（Air+草+泥土=3，草复用）", section.PaletteCount == 3, $"palette={section.PaletteCount}");
    Check("Section 读写", section.Get(0, 0, 0) == BlockRegistry.Grass && section.Get(1, 0, 0) == BlockRegistry.Dirt && section.Get(2, 0, 0) == BlockRegistry.Grass);
    Check("Section 全空气零分配", new Section().PaletteCount == 0);

    Check("区块状态机（生成→网格→就绪）",
        world.Store.GetStatus(0, 0) == ChunkStatus.Ready,
        $"status={world.Store.GetStatus(0, 0)}");

    var saveDir = Path.Combine(Path.GetTempPath(), $"cubit_worldcheck_{Guid.NewGuid():N}");
    world.Save(saveDir);
    var loaded = VoxelWorld.LoadFile(saveDir);
    Directory.Delete(saveDir, true);
    var roundTrip = loaded.Seed == seed && loaded.WorldType == WorldType.Noise && loaded.Store.ChunkKeys.Length == world.Store.ChunkKeys.Length;
    if (roundTrip)
    {
        foreach (var key in world.Store.ChunkKeys)
        {
        for (var y = Chunk.MinY; y < Chunk.MaxYExclusive; y++)
            {
                for (var z = 0; z < Chunk.SizeZ; z++)
                {
                    for (var x = 0; x < Chunk.SizeX; x++)
                    {
                        var wx = key.X * Chunk.SizeX + x;
                        var wz = key.Z * Chunk.SizeZ + z;
                        if (loaded.GetBlock(wx, y, wz) != world.GetBlock(wx, y, wz) || LightingEngine.GetLight(loaded.Store, wx, y, wz) != LightingEngine.GetLight(world.Store, wx, y, wz))
                        {
                            roundTrip = false;
                            break;
                        }
                    }

                    if (!roundTrip) break;
                }

                if (!roundTrip) break;
            }

            if (!roundTrip) break;
        }
    }
    Check("世界存档往返（种子/类型/逐方块/状态）", roundTrip, $"chunks={loaded.Store.ChunkKeys.Length} status={loaded.Store.GetStatus(0, 0)}");


    // 9.5) M4 AO：有邻块的角更暗（环境光遮蔽）
    var aoStore = new ChunkStore();
    var aoChunk = new Chunk();
    aoChunk.SetBlock(8, 1, 8, BlockRegistry.Grass);
    aoStore.AddChunk(0, 0, aoChunk);
    aoStore.SetStatus(0, 0, ChunkStatus.Ready);
    var aoMeshBefore = ChunkMesher.Mesh(aoStore, 0, 0).Opaque;
    // 顶面 AO 的遮挡体必须处于面外侧（Y+1）且沿切向偏移一格，
    // 同层相邻方块不应压暗开放的顶面。
    aoChunk.SetBlock(7, 2, 8, BlockRegistry.Grass);
    var aoMeshAfter = ChunkMesher.Mesh(aoStore, 0, 0).Opaque;
    static bool HasOccludedShade(float[] verts)
    {
        for (var i = 0; i < verts.Length; i += 7)
        {
            var s = verts[i + 5];
            if (s is > 0.07f and < 0.08f) return true; // 0.10 × (1-0.25) = 0.075
        }
        return false;
    }
    Check("AO 角遮蔽（面外侧邻块使角更暗）", !HasOccludedShade(aoMeshBefore.Vertices) && HasOccludedShade(aoMeshAfter.Vertices),
        $"before={HasOccludedShade(aoMeshBefore.Vertices)} after={HasOccludedShade(aoMeshAfter.Vertices)}");


    // 9) 逐个方块注册完整性（一个方块一条定义）
    foreach (var id in new ushort[] { BlockRegistry.Grass, BlockRegistry.Dirt, BlockRegistry.Stone, BlockRegistry.Sand, BlockRegistry.Wood, BlockRegistry.Leaves, BlockRegistry.Bedrock })
    {
        var def = BlockRegistry.Get(id);
        var ok = def.Name.Length > 0;
        for (var f = 0; f < 6; f++)
        {
            var tile = TextureAtlas.GetTile(id, f);
            if (tile < 0 || tile >= TextureAtlas.Columns) ok = false;
        }
        Check($"方块「{def.Name}」(ID {id}) 定义与六面纹理完整", ok);
    }
    Console.WriteLine(failures == 0 ? "worldcheck 全部通过" : $"worldcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int SimCheck(uint seed)
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var persistedReadyWorld = new VoxelWorld(seed, WorldType.Flat);
    var persistedReadyCommit = persistedReadyWorld.CommitLoadedChunk(
        0,
        0,
        new PersistedChunk(new Chunk(), ChunkStatus.Ready, TicketLevel.EntitySimulation));
    Check(
        "恢复 Ready 存档必须降级等待当前会话重新网格化",
        persistedReadyCommit && persistedReadyWorld.Store.GetStatus(0, 0) == ChunkStatus.Lighted,
        $"committed={persistedReadyCommit} status={persistedReadyWorld.Store.GetStatus(0, 0)}");

    var renderer = new FakeRenderBackend();
    using var session = CreateVoxelProjectSession(renderer, seed, worldType: WorldType.Flat);
    var scene = session.Scene;
    var worldNode = RequireVoxelWorld(scene);
    var cameraNode = RequireCamera(scene);
    var playerNode = scene.Tree.GetNode("/Root/Physics/Player") as MyFirstCubitProject.PlayerController;
    var playerBridge = scene.Tree.GetNode("/Root/Physics/PlayerEcs") as MyFirstCubitProject.PlayerEcsBridgeNode;
    var terrainNode = scene.Tree.GetNode("/Root/Physics/Terrain") as VoxelTerrainBody3D;
    var singleplayerMenu = scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
    scene.Tree.Root.AddChild(new Node { Name = "Probe" });

    // 1) 节点树就绪：世界/相机/玩家都是节点
    Check("场景节点树就绪",
        scene.Tree.GetNode("/Root/World") == worldNode &&
        scene.Tree.GetNode("/Root/Camera") == cameraNode &&
        playerNode is not null && terrainNode is not null && singleplayerMenu is not null,
        "World/Camera/Physics/Player/Terrain/SingleplayerMenu 均为树节点");

    // 单人项目启动应停在标题页。物理回归通过临时项目中的真实“创建世界”路径进入游戏，
    // 避免退回旧 demo 的启动即游玩前置条件。
    var openedTemporaryWorld = singleplayerMenu?.CreateWorld("Sim Check World", seed.ToString(), WorldType.Flat) == true;
    scene.ProcessFrame(0d);
    var openingProgress = singleplayerMenu?.OpeningProgress;
    Check(
        "进入世界先产生可观察 OpeningWorld 进度",
        openedTemporaryWorld && openingProgress is not null &&
        openingProgress.Stage is MyFirstCubitProject.WorldOpeningStage.OpenMetadata or
            MyFirstCubitProject.WorldOpeningStage.RequestSpawnArea or
            MyFirstCubitProject.WorldOpeningStage.WaitSpawnChunks or
            MyFirstCubitProject.WorldOpeningStage.WaitCollision or
            MyFirstCubitProject.WorldOpeningStage.RestorePlayer or
            MyFirstCubitProject.WorldOpeningStage.Complete,
        $"opened={openedTemporaryWorld} stage={openingProgress?.Stage.ToString() ?? "missing"}");
    var previousOpeningCompleted = openingProgress?.CompletedTasks ?? 0;
    for (var openingFrame = 0; openingFrame < 8; openingFrame++)
    {
        scene.ProcessFrame(1d / 60d);
        openingProgress = singleplayerMenu?.OpeningProgress;
        Check(
            "世界加载进度单调且范围有效",
            openingProgress is not null &&
            openingProgress.TotalTasks > 0 &&
            openingProgress.CompletedTasks >= previousOpeningCompleted &&
            openingProgress.CompletedTasks <= openingProgress.TotalTasks,
            $"frame={openingFrame} completed={openingProgress?.CompletedTasks} total={openingProgress?.TotalTasks}");
        previousOpeningCompleted = openingProgress?.CompletedTasks ?? previousOpeningCompleted;
    }
    var openingDeadline = Stopwatch.StartNew();
    while (singleplayerMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.OpeningWorld &&
           openingDeadline.Elapsed < TimeSpan.FromSeconds(10))
    {
        scene.ProcessFrame(1d / 60d);
        Thread.Sleep(1);
    }
    Check(
        "单人菜单经真实创建世界路径解除暂停并启用玩家控制",
        openedTemporaryWorld && singleplayerMenu?.State.IsGameplayActive == true && !scene.Tree.Paused && playerNode?.GameplayActive == true,
        $"opened={openedTemporaryWorld} screen={singleplayerMenu?.State.Screen.ToString() ?? "missing"} paused={scene.Tree.Paused} player={playerNode?.GameplayActive.ToString() ?? "missing"} openingMs={openingDeadline.Elapsed.TotalMilliseconds:F1}");

    if (playerNode is not null && playerBridge is not null)
    {
        playerNode.Position += Vector3.UnitX;
        var movedMotion = playerBridge.ReadMotionState();
        movedMotion.Position = playerNode.Position;
        playerBridge.SetMotionState(movedMotion);
    }

    scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.Cancel, true));
    scene.ProcessFrame(0d);
    scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.Cancel, false));
    Check(
        "项目 Cancel 输入切入暂停并禁用玩家控制",
        singleplayerMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.Pause && scene.Tree.Paused && playerNode?.GameplayActive == false,
        $"screen={singleplayerMenu?.State.Screen.ToString() ?? "missing"} paused={scene.Tree.Paused} player={playerNode?.GameplayActive.ToString() ?? "missing"}");
    var positionBeforeResume = playerNode?.GlobalPosition ?? default;
    scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.Cancel, true));
    scene.ProcessFrame(0d);
    scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.Cancel, false));
    Check(
        "项目 Cancel 输入从暂停返回游戏",
        singleplayerMenu?.State.IsGameplayActive == true && !scene.Tree.Paused && playerNode?.GameplayActive == true &&
        playerNode.GlobalPosition == positionBeforeResume,
        $"screen={singleplayerMenu?.State.Screen.ToString() ?? "missing"} paused={scene.Tree.Paused} player={playerNode?.GameplayActive.ToString() ?? "missing"} " +
        $"before={positionBeforeResume} after={playerNode?.GlobalPosition}");

    Check(
        "玩家就绪时立即请求出生点流式范围",
        worldNode.Streamer is { PendingCount: > 0 },
        $"pending={worldNode.Streamer?.PendingCount ?? -1}");

    var expectedSpawnY = worldNode.World!.GetSpawnHeight(24, 24) + 0.901f;
    scene.ProcessFrame(scene.Tree.PhysicsDelta);
    Check(
        "首个固定步不会让未加载出生区块中的玩家坠落",
        playerNode is not null && MathF.Abs(playerNode.GlobalPosition.Y - expectedSpawnY) <= 0.02f,
        $"expectedY={expectedSpawnY:F3} actual={playerNode?.GlobalPosition.Y:F3} pending={worldNode.Streamer?.PendingCount ?? -1}");

    for (var frame = 0; frame < 60; frame++)
    {
        scene.ProcessFrame(1d / 60d);
    }

    Check(
        "首批区块仍在流式时玩家保持在出生点而非落入虚空",
        playerNode is not null && MathF.Abs(playerNode.GlobalPosition.Y - expectedSpawnY) <= 0.02f,
        $"expectedY={expectedSpawnY:F3} actual={playerNode?.GlobalPosition.Y:F3} pending={worldNode.Streamer?.PendingCount ?? -1}");

    // 2) 前进 1 秒（固定物理步 60 帧）：平坦地表上位移应接近 8
    var readyDeadline = Stopwatch.StartNew();
    while ((terrainNode?.UsesConservativeFallback == true || worldNode.World!.GetBlock(24, 4, 24) == BlockRegistry.Air) &&
           readyDeadline.Elapsed < TimeSpan.FromSeconds(10))
    {
        scene.ProcessFrame(1d / 60d);
        Thread.Sleep(1);
    }
    Check(
        "玩家附近地形碰撞窗口完成加载",
        terrainNode is { UsesConservativeFallback: false } && worldNode.World!.GetBlock(24, 4, 24) != BlockRegistry.Air,
        $"fallback={terrainNode?.UsesConservativeFallback} elapsed={readyDeadline.Elapsed.TotalMilliseconds:F1}ms");

    Check(
        "场景作者化玩家在首批地形完成后站在出生地表",
        playerNode is not null &&
        MathF.Abs(playerNode.GlobalPosition.Y - expectedSpawnY) <= 0.02f &&
        playerNode.IsOnFloor,
        $"expectedY={expectedSpawnY:F3} actual={playerNode?.GlobalPosition.Y:F3} floor={playerNode?.IsOnFloor}");

    var start = cameraNode.Camera.Position;
    session.Input.SetAction(InputAction.Forward, true);
    for (var i = 0; i < 60; i++)
    {
        scene.ProcessFrame(1.0 / 60.0);
    }
    var walkingAction = playerBridge?.ReadActionState() ?? default;
    var walkingBaseEyeY = (playerNode?.GlobalPosition.Y ?? 0f) + (playerNode?.EyeHeight ?? 0f);
    Check(
        "真实前行固定步持续推进原版步态和第一人称向下 bob",
        walkingAction.WalkAnimation.Position > 0f && walkingAction.CameraBob.Bob > 0f &&
        cameraNode.Camera.Position.Y < walkingBaseEyeY,
        $"phase={walkingAction.WalkAnimation.Position:F3} bob={walkingAction.CameraBob.Bob:F3} " +
        $"cameraY={cameraNode.Camera.Position.Y:F3} eyeY={walkingBaseEyeY:F3}");
    session.Input.SetAction(InputAction.Forward, false);
    var moved = Vector3.Distance(start, cameraNode.Camera.Position);
    Check("按 W 前进位移约 8 格", moved is > 7f and < 8.5f, $"位移={moved:F2}");

    // 正式项目路径回归：输入、玩家控制器、体素碰撞桥和 PhysicsWorld3D 必须共同
    // 保证一格台阶前进起跳时不会退化为每 tick 仅 skin 宽度的水平位移。
    if (playerNode is not null && terrainNode is not null)
    {
        const int stepX = 25;
        const int stepY = 5;
        const int stepZ = 24;
        var stepCreated = worldNode.TrySetBlock(stepX, stepY, stepZ, BlockRegistry.Stone);
        playerBridge?.SetMotionState(new MyFirstCubitProject.PlayerMotionState
        {
            Position = new Vector3(24.55f, 5.901f, 24.5f),
            Velocity = new Vector3(0f, -1f, 0f),
            IsOnFloor = false,
        });
        cameraNode.Camera.Position = playerNode.GlobalPosition + Vector3.UnitY * 0.6f;
        cameraNode.Camera.Yaw = MathF.PI * 0.5f;
        cameraNode.Camera.Pitch = 0f;
        scene.ProcessFrame(scene.Tree.PhysicsDelta);
        scene.ProcessFrame(scene.Tree.PhysicsDelta);

        var stepStartX = playerNode.GlobalPosition.X;
        var minimumAirborneHorizontalStep = float.MaxValue;
        var slowStepTrace = new List<string>();
        session.Input.SetAction(InputAction.Forward, true);
        session.Input.SetAction(InputAction.Up, true);
        for (var tick = 0; tick < 20; tick++)
        {
            var previousX = playerNode.GlobalPosition.X;
            scene.ProcessFrame(scene.Tree.PhysicsDelta);
            var horizontalStep = MathF.Abs(playerNode.GlobalPosition.X - previousX);
            if (!playerNode.IsOnFloor && horizontalStep > 1e-5f)
            {
                minimumAirborneHorizontalStep = MathF.Min(minimumAirborneHorizontalStep, horizontalStep);
            }

            if (horizontalStep < 0.25f)
            {
                var normals = string.Join(';', Enumerable.Range(0, playerNode.LastSlideCount)
                    .Select(index => playerNode.GetSlideCollision(index).Normal.ToString()));
                slowStepTrace.Add(
                    $"{tick}:dx={horizontalStep:F4} pos={playerNode.GlobalPosition} vel={playerNode.Velocity} " +
                    $"floor={playerNode.IsOnFloor} slides={playerNode.LastSlideCount} normals={normals}");
            }
        }

        session.Input.SetAction(InputAction.Forward, false);
        session.Input.SetAction(InputAction.Up, false);
        Check(
            "正式项目玩家贴边起跳不会陷入近零水平位移",
            stepCreated && terrainNode.UsesConservativeFallback is false &&
            playerNode.GlobalPosition.X > stepStartX + 1f && minimumAirborneHorizontalStep >= 0.25f,
            $"created={stepCreated} x={stepStartX:F3}->{playerNode.GlobalPosition.X:F3} " +
            $"minimumHorizontalStep={minimumAirborneHorizontalStep:F4} floor={playerNode.IsOnFloor} " +
            $"slides={playerNode.LastSlideCount} trace={string.Join('|', slowStepTrace)}");
    }

    // 3) 鼠标视角：每帧 Process 应用一次
    var pitchBefore = cameraNode.Camera.Pitch;
    session.Input.AddMouseDelta(0f, -200f);
    scene.ProcessFrame(1.0 / 60.0);
    var pitchAfter = cameraNode.Camera.Pitch;
    Check("鼠标控制俯仰角", MathF.Abs(pitchAfter - pitchBefore) > 0.1f, $"Δ={pitchAfter - pitchBefore:F3}");

    // 4) 贴近地面垂直向下挖：正下方地表应变为空气
    var groundY = worldNode.World!.GetSpawnHeight(24, 24) - 1;
    if (playerNode is not null)
    {
        playerBridge?.SetMotionState(new MyFirstCubitProject.PlayerMotionState
        {
            Position = new Vector3(24.5f, groundY + 0.901f, 24.5f),
            Velocity = Vector3.Zero,
            IsOnFloor = true,
        });
    }
    cameraNode.Camera.Position = new Vector3(24.5f, groundY + 1.501f, 24.5f);
    cameraNode.Camera.Yaw = 0f;
    cameraNode.Camera.Pitch = -MathF.PI / 2f;
    var groundReadyDeadline = Stopwatch.StartNew();
    while (worldNode.World!.GetBlock(24, groundY, 24) == BlockRegistry.Air &&
           groundReadyDeadline.Elapsed < TimeSpan.FromSeconds(10))
    {
        scene.ProcessFrame(1d / 60d);
        Thread.Sleep(1);
    }
    var originalGround = worldNode.World!.GetBlock(24, groundY, 24);
    Check(
        "挖掘测试目标来自噪声地表而非空气",
        originalGround != BlockRegistry.Air,
        $"(24,{groundY},24) = {BlockRegistry.GetName(originalGround)}, elapsed={groundReadyDeadline.Elapsed.TotalMilliseconds:F1}ms");
    scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.PrimaryPointer, true));
    var breakInputBeforeStep = session.Scene.Runtime.Context.GetRequiredService<VoxelInputState>().BuildSnapshot();
    Check(
        "项目输入路由保留挖掘状态",
        breakInputBeforeStep.Break,
        $"break={breakInputBeforeStep.Break} place={breakInputBeforeStep.Place}");
    Check("玩家仍处于 ECS 游戏控制状态", playerNode?.GameplayActive == true, $"active={playerNode?.GameplayActive}");
    scene.ProcessFrame(1.0 / 20.0);
    var blockBelowBreakTarget = worldNode.World!.GetBlock(24, groundY - 1, 24);
    // 持续按住跨过 0.1 秒挖掘节流后，向下射线应继续作用于下一格。
    for (var i = 0; i < 6; i++)
    {
        scene.ProcessFrame(1.0 / 20.0);
    }
    var blockBelowAfterHeldBreak = worldNode.World!.GetBlock(24, groundY - 1, 24);
    scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.PrimaryPointer, false));
    var broken = worldNode.World!.GetBlock(24, groundY, 24);
    Check(
        "左键持续按住越过节流后继续挖掘下一方块",
        broken == BlockRegistry.Air && blockBelowBreakTarget != BlockRegistry.Air && blockBelowAfterHeldBreak == BlockRegistry.Air,
        $"target={BlockRegistry.GetName(broken)} below={BlockRegistry.GetName(blockBelowBreakTarget)}->{BlockRegistry.GetName(blockBelowAfterHeldBreak)}");

    // 5) 右键放方块：被挖位置应放回项目 Oak 原木
    scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.Digit5, true));
    var placeRay = worldNode.World!.Raycast(
        playerNode!.GlobalPosition + Vector3.UnitY * playerNode.EyeHeight,
        cameraNode.Camera.Forward);
    Check(
        "连续挖掘后右键仍能找到当前表面放置格",
        placeRay is not null,
        placeRay?.ToString() ?? "missing");
    scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.SecondaryPointer, true));
    scene.ProcessFrame(1.0 / 20.0);
    // 右键首击后需等约 4 个固定步；保持按下则应向上继续放置。
    for (var i = 0; i < 6; i++)
    {
        scene.ProcessFrame(1.0 / 20.0);
    }
    var initialPlace = placeRay?.Place ?? default;
    var blockAtInitialPlace = worldNode.World!.GetBlock(initialPlace.X, initialPlace.Y, initialPlace.Z);
    var blockAboveAfterHeldPlace = worldNode.World!.GetBlock(initialPlace.X, initialPlace.Y + 1, initialPlace.Z);
    scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.SecondaryPointer, false));
    Check(
        "右键持续按住越过节流后继续向上放置",
        placeRay is not null &&
        blockAtInitialPlace == BlockRegistry.GetId("my_first:oak_log") &&
        blockAboveAfterHeldPlace == BlockRegistry.GetId("my_first:oak_log"),
        $"target=({initialPlace.X},{initialPlace.Y},{initialPlace.Z}) " +
        $"{BlockRegistry.GetName(blockAtInitialPlace)}/{BlockRegistry.GetName(blockAboveAfterHeldPlace)}");

    // 6) 渲染服务收到网格上传与相机更新
    Check("渲染服务收到区块网格上传", renderer.MeshUploadCount > 0, $"上传 {renderer.MeshUploadCount} 次");
    Check("渲染服务收到相机更新", renderer.CameraUpdateCount > 0, $"更新 {renderer.CameraUpdateCount} 次");

    // 7) 模拟 tick 20Hz：1 秒 = 20 tick（60 帧 × 1/60）
    var tickProbe = new PhysNode();
    scene.Tree.Root.AddChild(tickProbe);
    for (var i = 0; i < 60; i++)
    {
        scene.ProcessFrame(1.0 / 60.0);
    }
    Check("模拟 tick 20Hz（1 秒 = 20 tick）", tickProbe.PhysicsCount == 20, $"tick={tickProbe.PhysicsCount}");

    // 8) 渲染插值 alpha ∈ [0,1)
    scene.ProcessFrame(1.0 / 120.0);
    Check("渲染插值 alpha ∈ [0,1)", scene.Tree.PhysicsInterpolationAlpha is >= 0 and < 1, $"alpha={scene.Tree.PhysicsInterpolationAlpha:F3}");

    // 9) RenderingServer RID 生命周期（2 帧安全期延迟销毁）。流式世界可在
    // 同一帧回收其他区块的过期 RID，因此必须观测本测试创建的目标 RID。
    var server = scene.RenderingServer;
    var rid = server.CreateMesh(new MeshData(
        new float[18],
        [0u, 1u, 2u],
        Vector3.Zero,
        Vector3.Zero,
        Vector3.One));
    server.DestroyMesh(rid);
    Check("RID 有效且已注册", rid.IsValid && renderer.IsMeshActive(rid), $"valid={rid.IsValid} active={renderer.IsMeshActive(rid)}");
    server.BeginFrame();
    Check("1 帧安全期内未销毁", renderer.IsMeshActive(rid), $"active={renderer.IsMeshActive(rid)}");
    server.BeginFrame();
    Check("2 帧后延迟销毁", !renderer.IsMeshActive(rid), $"active={renderer.IsMeshActive(rid)}");
    singleplayerMenu?.ReturnToTitle();
    scene.ProcessFrame(0d);
    Check(
        "返回标题后保存世界并停止后台流式",
        singleplayerMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.Title && scene.Tree.Paused &&
        playerNode?.GameplayActive == false && worldNode.Streamer is null,
        $"screen={singleplayerMenu?.State.Screen.ToString() ?? "missing"} paused={scene.Tree.Paused} player={playerNode?.GameplayActive.ToString() ?? "missing"} streamer={(worldNode.Streamer is null ? "null" : "active")}");
    var meshesBeforeDispose = server.MeshCount;
    session.Dispose();
    Check(
        "demo 会话释放时立即清退服务器与后端网格",
        meshesBeforeDispose > 0 && server.MeshCount == 0 && renderer.ActiveMeshCount == 0,
        $"before={meshesBeforeDispose} server={server.MeshCount} backend={renderer.ActiveMeshCount}");
    Console.WriteLine(failures == 0 ? "simcheck 全部通过" : $"simcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int PlayerAnimationCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    static Transform3D BuildVanillaRightHandReference(float attackTime, float inverseArmHeight)
    {
        attackTime = Math.Clamp(attackTime, 0f, 1f);
        inverseArmHeight = Math.Clamp(inverseArmHeight, 0f, 1f);
        var root = MathF.Sqrt(attackTime);
        var xSwing = -0.3f * MathF.Sin(root * MathF.PI);
        var ySwing = 0.4f * MathF.Sin(root * 2f * MathF.PI);
        var zSwing = -0.4f * MathF.Sin(attackTime * MathF.PI);
        var ySwingRotation = MathF.Sin(root * MathF.PI);
        var zSwingRotation = MathF.Sin(attackTime * attackTime * MathF.PI);
        var pose = Matrix4x4.Identity;

        static void Push(ref Matrix4x4 current, Matrix4x4 operation) => current = operation * current;

        // JOML 使用列向量右乘；转到 System.Numerics 的行向量后，后续操作前乘。
        Push(ref pose, Matrix4x4.CreateTranslation(xSwing + 0.64000005f, ySwing - 0.6f - inverseArmHeight * 0.6f, zSwing - 0.71999997f));
        Push(ref pose, Matrix4x4.CreateRotationY(MathF.PI * 0.25f));
        Push(ref pose, Matrix4x4.CreateRotationY(ySwingRotation * 70f * MathF.PI / 180f));
        Push(ref pose, Matrix4x4.CreateRotationZ(zSwingRotation * -20f * MathF.PI / 180f));
        Push(ref pose, Matrix4x4.CreateTranslation(-1f, 3.6f, 3.5f));
        Push(ref pose, Matrix4x4.CreateRotationZ(120f * MathF.PI / 180f));
        Push(ref pose, Matrix4x4.CreateRotationX(200f * MathF.PI / 180f));
        Push(ref pose, Matrix4x4.CreateRotationY(-135f * MathF.PI / 180f));
        Push(ref pose, Matrix4x4.CreateTranslation(5.6f, 0f, 0f));
        Push(ref pose, Matrix4x4.CreateTranslation(-5f / 16f, 2f / 16f, 0f));
        Push(ref pose, Matrix4x4.CreateRotationZ(0.1f));

        if (!Matrix4x4.Decompose(pose, out var scale, out var rotation, out var position) ||
            MathF.Abs(scale.X - scale.Y) > 1e-5f || MathF.Abs(scale.X - scale.Z) > 1e-5f)
        {
            throw new InvalidOperationException("原版第一人称手臂姿势未能分解为 Cubit 的刚体变换");
        }

        return new Transform3D(position, rotation, scale.X);
    }

    static bool TransformNearlyEquals(in Transform3D actual, in Transform3D expected)
    {
        var left = actual.Matrix;
        var right = expected.Matrix;
        return new[]
        {
            left.M11 - right.M11, left.M12 - right.M12, left.M13 - right.M13, left.M14 - right.M14,
            left.M21 - right.M21, left.M22 - right.M22, left.M23 - right.M23, left.M24 - right.M24,
            left.M31 - right.M31, left.M32 - right.M32, left.M33 - right.M33, left.M34 - right.M34,
            left.M41 - right.M41, left.M42 - right.M42, left.M43 - right.M43, left.M44 - right.M44,
        }.All(delta => MathF.Abs(delta) < 1e-5f);
    }

    var gait = new MyFirstCubitProject.PlayerWalkAnimationState();
    gait.Update(0.25f);
    gait.Update(0f);
    Check(
        "玩家步态按原版 0.4 因子平滑速度并持续累加相位",
        MathF.Abs(gait.SpeedOld - 0.4f) < 0.0001f &&
        MathF.Abs(gait.Speed - 0.24f) < 0.0001f &&
        MathF.Abs(gait.Position - 0.64f) < 0.0001f,
        $"old={gait.SpeedOld:F3} speed={gait.Speed:F3} position={gait.Position:F3}");
    Check(
        "玩家步态在停止或起跳后仍能按 partial tick 连续采样",
        MathF.Abs(gait.SampleSpeed(0.5f) - 0.32f) < 0.0001f &&
        MathF.Abs(gait.SamplePosition(0.5f) - 0.52f) < 0.0001f,
        $"speed={gait.SampleSpeed(0.5f):F3} position={gait.SamplePosition(0.5f):F3}");

    var cameraBob = new MyFirstCubitProject.PlayerCameraBobState();
    cameraBob.Update(0.25f, isOnFloor: true);
    var cameraBobOffset = cameraBob.SampleTranslation(0.5f);
    Check(
        "玩家相机 bob 按原版 walkDistance*0.6、bob 上限 0.1 和向下余弦公式计算",
        MathF.Abs(cameraBob.WalkDistance - 0.15f) < 0.0001f &&
        MathF.Abs(cameraBob.Bob - 0.04f) < 0.0001f && cameraBobOffset.Y < 0f,
        $"walk={cameraBob.WalkDistance:F3} bob={cameraBob.Bob:F3} offset={cameraBobOffset}");

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
    var animationPath = projectRoot is null ? null : Path.Combine(projectRoot, "assets", "player", "animations.json");
    Check("项目拥有独立玩家动画资产", animationPath is not null && File.Exists(animationPath), animationPath ?? "missing");

    JsonDocument? animationDocument = null;
    try
    {
        if (animationPath is not null && File.Exists(animationPath))
        {
            animationDocument = JsonDocument.Parse(File.ReadAllText(animationPath));
            var clips = animationDocument.RootElement.GetProperty("clips");
            var required = new[] { "Attack" };
            Check(
                "玩家动画资产只保留离散攻击时间轴，正常步态不使用固定剪辑",
                required.All(name => clips.TryGetProperty(name, out _)) && clips.EnumerateObject().All(clip => clip.Name == "Attack"),
                string.Join(',', required));
            Check(
                "玩家动画资产使用骨骼 Quaternion 轨道",
                clips.EnumerateObject().SelectMany(clip => clip.Value.GetProperty("Tracks").EnumerateArray())
                    .Any(track => track.GetProperty("Kind").ValueKind == JsonValueKind.Number &&
                                 track.GetProperty("Kind").GetInt32() == (int)AnimationValueKind.Quaternion),
                $"Kind={(int)AnimationValueKind.Quaternion}=Quaternion");
            Check(
                "攻击时间轴仍使用骨骼 Quaternion 轨道",
                clips.GetProperty("Attack").GetProperty("Tracks").EnumerateArray().Any(track =>
                    track.GetProperty("Kind").GetInt32() == (int)AnimationValueKind.Quaternion),
                "Attack.Quaternion");
        }
    }
    catch (Exception exception)
    {
        Check("玩家动画资产 JSON 可解析", false, exception.Message);
    }
    finally
    {
        animationDocument?.Dispose();
    }

    var modelType = typeof(MyFirstCubitProject.PlayerModelNode);
    var currentAnimationProperty = modelType.GetProperty("CurrentAnimationName", BindingFlags.Public | BindingFlags.Instance);
    var applyActionMethod = modelType.GetMethod("ApplyActionState", BindingFlags.Public | BindingFlags.Instance);
    Check(
        "PlayerModelNode 提供 ECS 动作到动画的显式桥接",
        currentAnimationProperty is not null && applyActionMethod is not null,
        $"current={currentAnimationProperty is not null} apply={applyActionMethod is not null}");

    var vanillaRightHandPose = typeof(MyFirstCubitProject.FirstPersonArmNode).GetMethod(
        "BuildVanillaRightHandCameraLocalPose",
        BindingFlags.NonPublic | BindingFlags.Static);
    foreach (var (attackTime, inverseArmHeight) in new[] { (0f, 0f), (0.36f, 0.4f) })
    {
        var expectedPose = BuildVanillaRightHandReference(attackTime, inverseArmHeight);
        var actualPose = vanillaRightHandPose?.Invoke(null, [attackTime, inverseArmHeight]);
        Check(
            $"第一人称右臂遵守原版空手姿势公式 attack={attackTime:F2} height={inverseArmHeight:F2}",
            actualPose is Transform3D pose && TransformNearlyEquals(pose, expectedPose),
            actualPose?.ToString() ?? "missing");
    }
    var emptyHandPose = vanillaRightHandPose?.Invoke(null, [0f, 0f]);
    Check(
        "第一人称右臂的原版空手姿势位于相机 -Z 可见前方",
        emptyHandPose is Transform3D visiblePose && visiblePose.Position.Z < -0.01f,
        emptyHandPose?.ToString() ?? "missing");
    var rawArmMeshBuilder = typeof(MyFirstCubitProject.PlayerModelPartNode).GetMethod(
        "BuildMinecraftModelPartMesh",
        BindingFlags.NonPublic | BindingFlags.Static);
    var rawArmMesh = rawArmMeshBuilder?.Invoke(null,
        ["right_arm", new Vector3(4f, 12f, 4f), new Vector3(-1f, 4f, 0f), RID.None, 4]) as MeshData;
    Check(
        "第一人称右臂使用未翻转的原版 ModelPart 盒体坐标",
        rawArmMesh is not null &&
        MathF.Abs(rawArmMesh.BoundsMin.Y + 2f / 16f) < 0.0001f &&
        MathF.Abs(rawArmMesh.BoundsMax.Y - 10f / 16f) < 0.0001f,
        rawArmMesh is null ? "missing" : $"min={rawArmMesh.BoundsMin} max={rawArmMesh.BoundsMax}");

    var vanillaThirdPersonHitDistance = typeof(MyFirstCubitProject.PlayerController).GetMethod(
        "ResolveVanillaThirdPersonHitDistance",
        BindingFlags.NonPublic | BindingFlags.Static);
    var thirdPersonHitDistance = vanillaThirdPersonHitDistance?.Invoke(
        null,
        [Vector3.Zero, new Vector3(0.1f, 0.1f, 0.1f), Vector3.UnitX, (3, 0, 0), 4f]);
    var expectedThirdPersonHitDistance = MathF.Sqrt(3f * 3f + 0.1f * 0.1f + 0.1f * 0.1f);
    Check(
        "第三人称回缩距离以原版相机眼睛中心而非抖动射线起点计算",
        thirdPersonHitDistance is float distance && MathF.Abs(distance - expectedThirdPersonHitDistance) < 1e-5f,
        thirdPersonHitDistance?.ToString() ?? "missing");

    var cameraFrame = typeof(MyFirstCubitProject.FirstPersonArmNode).GetMethod(
        "BuildCameraToWorld",
        BindingFlags.NonPublic | BindingFlags.Static)?.Invoke(null, [Vector3.Zero, Vector3.UnitZ]);
    var cameraScreenRight = cameraFrame is Matrix4x4 matrix
        ? Vector3.Transform(Vector3.UnitX, matrix)
        : Vector3.Zero;
    Check(
        "第一人称右臂的相机局部正 X 投影到屏幕右侧",
        cameraFrame is Matrix4x4 && Vector3.Distance(cameraScreenRight, -Vector3.UnitX) < 1e-5f,
        cameraFrame is null ? "missing" : cameraScreenRight.ToString());

    if (projectRoot is not null && Directory.Exists(projectRoot))
    {
        try
        {
            using var session = CreateVoxelProjectSession(new FakeRenderBackend(), 20260808u, workerCount: 1, worldType: WorldType.Flat);
            var model = session.Scene.Tree.GetNode("/Root/Physics/PlayerModel") as MyFirstCubitProject.PlayerModelNode;
            var firstPersonArm = session.Scene.Tree.GetNode("/Root/Physics/FirstPersonArm") as MyFirstCubitProject.FirstPersonArmNode;
            var animationPlayer = model?.AnimationPlayer;
            var required = new[] { "Attack" };
            var poseNode = session.Scene.Tree.GetNode("/Root/Physics/PlayerModel/HumanoidPose") as MyFirstCubitProject.PlayerHumanoidPoseNode;
            Check(
                "玩家模型运行时挂载 AnimationPlayer",
                model is not null && animationPlayer is not null,
                $"model={model is not null} player={animationPlayer is not null}");
            Check(
                "玩家场景作者化第一人称主手臂节点",
                firstPersonArm is not null);
            Check(
                "玩家模型默认第一人称隐藏",
                model is { IsModelVisible: false });
            Check(
                "玩家模型运行时只注册离散攻击时间轴",
                animationPlayer is not null && required.All(name => animationPlayer.ClipNames.Contains(name)),
                animationPlayer is null ? "missing" : string.Join(',', animationPlayer.ClipNames));
            Check(
                "玩家场景作者化程序姿势节点并在网格提交前运行",
                poseNode is not null && poseNode.ProcessPriority < 0,
                poseNode?.ProcessPriority.ToString() ?? "missing");

            var bridge = session.Scene.Tree.GetNode("/Root/Physics/PlayerEcs") as MyFirstCubitProject.PlayerEcsBridgeNode;
            var ecsNode = bridge?.Children.OfType<EcsNode>().SingleOrDefault();
            if (bridge is not null && ecsNode is not null && model is not null && currentAnimationProperty is not null)
            {
                session.Scene.ProcessFrame(1d / 60d);
                var rootOffset = bridge.ReadMotionState().Position - Vector3.UnitY * model.CharacterRootOffset;
                Check(
                    "玩家模型原点与作者化脚底位置对齐",
                    Vector3.Distance(model.Position, rootOffset) < 0.0001f,
                    $"model={model.Position} expected={rootOffset}");
                ref var action = ref ecsNode.World.GetComponent<MyFirstCubitProject.PlayerActionState>(bridge.PlayerEntity);
                var expected = new[]
                {
                    MyFirstCubitProject.PlayerLocomotionMode.Idle,
                    MyFirstCubitProject.PlayerLocomotionMode.Walk,
                    MyFirstCubitProject.PlayerLocomotionMode.Run,
                    MyFirstCubitProject.PlayerLocomotionMode.Sneak,
                    MyFirstCubitProject.PlayerLocomotionMode.Jump,
                    MyFirstCubitProject.PlayerLocomotionMode.Fall,
                };
                foreach (var mode in expected)
                {
                    action.Locomotion = mode;
                    action.Flags = MyFirstCubitProject.PlayerActionFlags.None;
                    action.ActionSequence++;
                    session.Scene.ProcessFrame(1d / 60d);
                    Check($"ECS locomotion {mode} 保持程序步态而不重置固定剪辑", string.Equals(
                        currentAnimationProperty.GetValue(model) as string, "ProceduralLocomotion", StringComparison.Ordinal),
                        currentAnimationProperty.GetValue(model) as string ?? "null");
                }

                var skeleton = model.Skeleton;
                var authoredBones = skeleton?.Bones.ToDictionary(bone => bone.Name, bone => bone.Transform,
                    StringComparer.Ordinal);
                action.WalkAnimation.Position = 3.5f;
                action.WalkAnimation.SpeedOld = 0.4f;
                action.WalkAnimation.Speed = 0.4f;
                action.Flags = MyFirstCubitProject.PlayerActionFlags.None;
                action.Locomotion = MyFirstCubitProject.PlayerLocomotionMode.Walk;
                action.ActionSequence++;
                session.Scene.ProcessFrame(1d / 60d);
                var gaitLeftLegRotation = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "left_leg")?.Rotation;
                var gaitRightLegRotation = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "right_leg")?.Rotation;
                action.Flags = MyFirstCubitProject.PlayerActionFlags.Crouch;
                action.Locomotion = MyFirstCubitProject.PlayerLocomotionMode.Sneak;
                action.ActionSequence++;
                session.Scene.ProcessFrame(1d / 60d);
                var crouchedHead = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "head");
                var crouchedBody = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "body");
                var crouchedLeftLeg = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "left_leg");
                var crouchedRightLeg = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "right_leg");
                var crouchedBodySeam = crouchedBody is null
                    ? Vector3.Zero
                    : crouchedBody.Position + Vector3.Transform(
                        new Vector3(0f, -12f / 16f, 0f),
                        crouchedBody.Rotation);
                Check(
                    "原版潜行在 Y 翻转模型中让躯干下缘朝前移双腿保持连续",
                    crouchedHead is not null && crouchedBody is not null && crouchedLeftLeg is not null && crouchedRightLeg is not null &&
                    gaitLeftLegRotation is Quaternion leftGait && gaitRightLegRotation is Quaternion rightGait && authoredBones is not null &&
                    crouchedHead.Position.Y < authoredBones["head"].Position.Y &&
                    MathF.Abs(Quaternion.Dot(
                        crouchedBody.Rotation,
                        Quaternion.CreateFromAxisAngle(Vector3.UnitX, -0.5f))) > 0.999f &&
                    MathF.Abs(Quaternion.Dot(crouchedLeftLeg.Rotation, leftGait)) > 0.999f &&
                    MathF.Abs(Quaternion.Dot(crouchedRightLeg.Rotation, rightGait)) > 0.999f &&
                    MathF.Abs(crouchedLeftLeg.Position.X - authoredBones["left_leg"].Position.X) < 0.0001f &&
                    MathF.Abs(crouchedRightLeg.Position.X - authoredBones["right_leg"].Position.X) < 0.0001f &&
                    MathF.Abs(crouchedLeftLeg.Position.Y - authoredBones["left_leg"].Position.Y) < 0.0001f &&
                    MathF.Abs(crouchedRightLeg.Position.Y - authoredBones["right_leg"].Position.Y) < 0.0001f &&
                    MathF.Abs(crouchedLeftLeg.Position.Z - (authoredBones["left_leg"].Position.Z + 0.25f)) < 0.0001f &&
                    MathF.Abs(crouchedRightLeg.Position.Z - (authoredBones["right_leg"].Position.Z + 0.25f)) < 0.0001f &&
                    crouchedBodySeam.Z > 0f &&
                    Vector3.Distance(crouchedBodySeam, crouchedLeftLeg.Position) < 0.22f &&
                    Vector3.Distance(crouchedBodySeam, crouchedRightLeg.Position) < 0.22f,
                    $"head={crouchedHead?.Position} body={crouchedBody?.Rotation} " +
                    $"seam={crouchedBodySeam} legs={crouchedLeftLeg?.Position}/{crouchedRightLeg?.Position}");

                var gaitPhaseBeforeJump = action.WalkAnimation.Position;
                action.Flags = MyFirstCubitProject.PlayerActionFlags.None;
                action.Locomotion = MyFirstCubitProject.PlayerLocomotionMode.Jump;
                action.ActionSequence++;
                session.Scene.ProcessFrame(1d / 60d);
                var restoredHead = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "head");
                var restoredBody = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "body");
                var restoredLeftArm = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "left_arm");
                var restoredRightArm = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "right_arm");
                var restoredLeftLeg = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "left_leg");
                var restoredRightLeg = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "right_leg");
                Check(
                    "解除潜行后所有身体部件恢复作者化位置，Jump 不切入静态姿势",
                    authoredBones is not null && restoredHead is not null && restoredBody is not null &&
                    restoredLeftArm is not null && restoredRightArm is not null && restoredLeftLeg is not null && restoredRightLeg is not null &&
                    Vector3.Distance(restoredHead.Position, authoredBones["head"].Position) < 0.0001f &&
                    Vector3.Distance(restoredBody.Position, authoredBones["body"].Position) < 0.0001f &&
                    Vector3.Distance(restoredLeftArm.Position, authoredBones["left_arm"].Position) < 0.0001f &&
                    Vector3.Distance(restoredRightArm.Position, authoredBones["right_arm"].Position) < 0.0001f &&
                    Vector3.Distance(restoredLeftLeg.Position, authoredBones["left_leg"].Position) < 0.0001f &&
                    Vector3.Distance(restoredRightLeg.Position, authoredBones["right_leg"].Position) < 0.0001f &&
                    MathF.Abs(restoredBody.Rotation.X - 0.5f) > 0.1f &&
                    MathF.Abs(bridge.ReadActionState().WalkAnimation.Position - gaitPhaseBeforeJump) < 0.0001f,
                    $"head={restoredHead?.Position} body={restoredBody?.Position}/{restoredBody?.Rotation} phase={bridge.ReadActionState().WalkAnimation.Position:F3}");

                action.Locomotion = MyFirstCubitProject.PlayerLocomotionMode.Idle;
                action.Flags = MyFirstCubitProject.PlayerActionFlags.Attack;
                action.ActionSequence++;
                session.Scene.ProcessFrame(1d / 60d);
                Check(
                    "ECS Attack 标志优先选择攻击动画",
                    string.Equals(currentAnimationProperty.GetValue(model) as string, "Attack", StringComparison.Ordinal),
                    currentAnimationProperty.GetValue(model) as string ?? "null");

                action.HeadYaw = 0.35f;
                action.HeadPitch = -0.2f;
                action.ActionSequence++;
                session.Scene.ProcessFrame(1d / 60d);
                var head = skeleton?.Bones.FirstOrDefault(bone => bone.Name == "head");
                Check(
                    "头部旋转只由 PlayerActionState 驱动",
                    head is not null && MathF.Abs(head.Rotation.Y) > 0.01f && MathF.Abs(head.Rotation.X) > 0.01f,
                    head?.Rotation.ToString() ?? "missing");

                var playerController = session.Scene.Tree.GetNode("/Root/Physics/Player") as MyFirstCubitProject.PlayerController;
                var camera = session.Scene.Tree.GetNode("/Root/Camera") as Camera3D;
                if (playerController is null || camera is null)
                {
                    throw new InvalidOperationException("玩家动画回归缺少 PlayerController 或 Camera3D");
                }

                playerController.SetGameplayActive(true);
                playerController.SetViewAnglesForTesting(0.75f, -0.3f);
                session.Scene.ProcessFrame(1d / 60d);
                var cameraAction = bridge.ReadActionState();
                Check(
                    "玩家控制器将相机朝向写入项目动作状态",
                    MathF.Abs(cameraAction.BodyYaw - (0.75f + MathF.PI)) < 0.0001f &&
                    MathF.Abs(cameraAction.HeadPitch + 0.3f) < 0.0001f,
                    $"body={cameraAction.BodyYaw} headPitch={cameraAction.HeadPitch}");
                Check(
                    "模型根节点只根据动作状态旋转身体",
                    MathF.Abs(model.Rotation.Y) > 0.1f,
                    model.Rotation.ToString());
                var modelForward = Vector3.Normalize(Vector3.Transform(-Vector3.UnitZ, model.Rotation));
                var cameraForward = camera.Camera.Forward;
                cameraForward.Y = 0f;
                cameraForward = Vector3.Normalize(cameraForward);
                Check(
                    "模型皮肤正面与相机前向保持一致",
                    Vector3.Dot(modelForward, cameraForward) > 0.99f,
                    $"dot={Vector3.Dot(modelForward, cameraForward):F4}");

                action = bridge.ReadActionState();
                action.CameraBob = cameraBob;
                action.CameraBob.BobOld = action.CameraBob.Bob;
                action.Flags &= ~MyFirstCubitProject.PlayerActionFlags.Crouch;
                bridge.SetActionState(action);
                playerController.SetViewAnglesForTesting(0.75f, -0.3f);
                var cameraEyeY = bridge.ReadInterpolatedMotionState((float)session.Scene.Tree.PhysicsInterpolationAlpha).Position.Y +
                    playerController.EyeHeight;
                Check(
                    "第一人称前行相机应用原版向下 bob 而非固定高度",
                    camera.Camera.Position.Y < cameraEyeY,
                    $"cameraY={camera.Camera.Position.Y:F4} eyeY={cameraEyeY:F4}");

                playerController?.SetGameplayActive(false);
                session.Scene.Tree.Paused = false;
                bridge.SetMotionState(new MyFirstCubitProject.PlayerMotionState
                {
                    Position = Vector3.Zero,
                    Velocity = Vector3.Zero,
                    IsOnFloor = true,
                    LastSlideCount = 0,
                });
                session.Scene.ProcessFrame(1d / 20d);
                bridge.SetMotionState(new MyFirstCubitProject.PlayerMotionState
                {
                    Position = new Vector3(4f, 0f, 0f),
                    Velocity = Vector3.Zero,
                    IsOnFloor = true,
                    LastSlideCount = 0,
                });
                var directInterpolated = bridge.ReadInterpolatedMotionState(0.5f);
                Check(
                    "玩家 ECS 桥接保留前一固定步运动快照",
                    MathF.Abs(directInterpolated.Position.X - 2f) < 0.0001f,
                    $"position={directInterpolated.Position}");
                session.Scene.Tree.Paused = false;
                session.Scene.ProcessFrame(1d / 20d);
                session.Scene.Tree.Paused = false;
                session.Scene.ProcessFrame(1d / 40d);
                Check(
                    "玩家模型在渲染半步使用固定步位置插值",
                    MathF.Abs(model.Position.X - 2f) < 0.0001f,
                    $"position={model.Position} alpha={session.Scene.Tree.PhysicsInterpolationAlpha:F3}");

                // 相机与第三人称模型必须使用同一个渲染插值位置；物理节点
                // 仍保持最新固定步位置，避免边缘落差时两套表现不同步。
                // 明确构造前后两个固定步，避免测试依赖会话此前的累计状态。
                var interpolatedStart = bridge.ReadMotionState();
                interpolatedStart.Position = Vector3.Zero;
                interpolatedStart.Velocity = Vector3.Zero;
                interpolatedStart.IsOnFloor = true;
                bridge.SetMotionState(interpolatedStart);
                var cameraActionState = bridge.ReadActionState();
                cameraActionState.CameraBob = default;
                bridge.SetActionState(cameraActionState);
                var interpolationMenu = session.Scene.Runtime.Context.GetRequiredService<MyFirstCubitProject.SingleplayerMenuState>();
                interpolationMenu.ShowWorldSelection();
                interpolationMenu.BeginOpeningWorld();
                interpolationMenu.BeginPlaying();
                playerController!.SetGameplayActive(true);
                playerController.Position = interpolatedStart.Position;
                session.Scene.Tree.Paused = true;
                session.Scene.ProcessFrame(0d);
                // 这里显式推进相机的固定步边界：生产路径由 PlayerController
                // 在 PhysicsProcess 开始时调用，同步测试用同一语义建立起点。
                camera!.Camera.BeginPhysicsStep();
                var interpolatedEnd = interpolatedStart;
                interpolatedEnd.Position = new Vector3(4f, 0f, 0f);
                bridge.SetMotionState(interpolatedEnd);
                cameraActionState = bridge.ReadActionState();
                cameraActionState.CameraBob = default;
                bridge.SetActionState(cameraActionState);
                playerController!.Position = interpolatedEnd.Position;
                session.Scene.ProcessFrame(0d);
                var visualAlpha = (float)session.Scene.Tree.PhysicsInterpolationAlpha;
                var visualMotion = bridge.ReadInterpolatedMotionState(visualAlpha);
                var renderedCameraPosition = camera.Camera.InterpolatedPosition(visualAlpha);
                Check(
                    "玩家相机与模型共享固定步渲染插值位置",
                    MathF.Abs(renderedCameraPosition.X - visualMotion.Position.X) < 0.0001f &&
                    MathF.Abs(renderedCameraPosition.Y - (visualMotion.Position.Y + playerController.EyeHeight)) < 0.0001f &&
                    MathF.Abs(model.Position.X - (visualMotion.Position.X)) < 0.0001f,
                    $"camera={renderedCameraPosition} model={model.Position} expectedPlayer={visualMotion.Position} " +
                    $"physicalPlayer={playerController.Position} cameraCurrent={camera.Camera.Position} " +
                    $"cameraPrevious={camera.Camera.PreviousPosition} mode={session.Scene.Runtime.Context.GetRequiredService<MyFirstCubitProject.PlayerViewState>().Mode} alpha={visualAlpha:F3}");
                Check(
                    "玩家物理节点保留当前固定步位置而不被渲染插值回写",
                    MathF.Abs(playerController.Position.X - interpolatedEnd.Position.X) < 0.0001f,
                    $"physicalX={playerController.Position.X:F4} currentX={interpolatedEnd.Position.X:F4}");
                session.Scene.Tree.Paused = false;

                var viewMenu = session.Scene.Runtime.Context.GetRequiredService<MyFirstCubitProject.SingleplayerMenuState>();
                viewMenu.ShowWorldSelection();
                viewMenu.BeginOpeningWorld();
                viewMenu.BeginPlaying();
                playerController?.SetGameplayActive(true);
                var viewState = session.Scene.Runtime.Context.GetRequiredService<MyFirstCubitProject.PlayerViewState>();
                session.Scene.ProcessFrame(1d / 60d);
                Check(
                    "第一人称只显示主手臂而不显示完整实体",
                    viewState.Mode == MyFirstCubitProject.PlayerCameraMode.FirstPerson &&
                    model.IsModelVisible == false && firstPersonArm?.IsArmVisible == true,
                    $"mode={viewState.Mode} model={model.IsModelVisible} arm={firstPersonArm?.IsArmVisible}");

                var baseForward = camera.Camera.Forward;
                session.Scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.ToggleView, true));
                session.Scene.ProcessFrame(1d / 60d);
                Check(
                    "F5 从第一人称切换第三人称后视",
                    viewState.Mode == MyFirstCubitProject.PlayerCameraMode.ThirdPersonBack &&
                    model.IsModelVisible && firstPersonArm?.IsArmVisible == false,
                    $"mode={viewState.Mode} model={model.IsModelVisible} arm={firstPersonArm?.IsArmVisible}");
                session.Scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.ToggleView, false));
                session.Scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.ToggleView, true));
                session.Scene.ProcessFrame(1d / 60d);
                Check(
                    "F5 再次切换第三人称前视并反向看向玩家",
                    viewState.Mode == MyFirstCubitProject.PlayerCameraMode.ThirdPersonFront &&
                    Vector3.Dot(Vector3.Normalize(camera.Camera.Forward), Vector3.Normalize(baseForward)) < -0.99f,
                    $"mode={viewState.Mode} dot={Vector3.Dot(Vector3.Normalize(camera.Camera.Forward), Vector3.Normalize(baseForward)):F4}");
                session.Scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.ToggleView, false));
                session.Scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.ToggleView, true));
                session.Scene.ProcessFrame(1d / 60d);
                Check(
                    "F5 第三次返回第一人称",
                    viewState.Mode == MyFirstCubitProject.PlayerCameraMode.FirstPerson &&
                    model.IsModelVisible == false && firstPersonArm?.IsArmVisible == true,
                    $"mode={viewState.Mode} model={model.IsModelVisible} arm={firstPersonArm?.IsArmVisible}");
                session.Scene.RouteProjectInput(new ProjectInputEvent(ProjectInputControl.ToggleView, false));
            }
        }
        catch (Exception exception)
        {
            Check("玩家动画运行时场景桥接", false, exception.ToString());
        }
    }

    Console.WriteLine(failures == 0 ? "playeranimationcheck 全部通过" : $"playeranimationcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int BlockTintCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    try
    {
        Check(
            "草方块只对顶面应用草色调",
            BlockRegistry.Get(BlockRegistry.Grass).TintFaces == BlockTintFaces.Top,
            BlockRegistry.Get(BlockRegistry.Grass).TintFaces.ToString());

        const ushort topOnlyId = 300;
        const ushort allFacesId = 301;
        BlockRegistry.Register(new BlockDef
        {
            Id = topOnlyId,
            Key = "tool.tint:top_only",
            Name = "Top Only Tint",
            TopTexture = "dirt",
            SideTexture = "dirt",
            BottomTexture = "dirt",
            Tint = "#00ff00",
            TintFaces = BlockTintFaces.Top,
        });
        BlockRegistry.Register(new BlockDef
        {
            Id = allFacesId,
            Key = "tool.tint:all_faces",
            Name = "All Faces Tint",
            TopTexture = "dirt",
            SideTexture = "dirt",
            BottomTexture = "dirt",
            Tint = "#00ff00",
            TintFaces = BlockTintFaces.All,
        });

        var topOnlyTop = TextureAtlas.GetTile(topOnlyId, 0);
        var topOnlySide = TextureAtlas.GetTile(topOnlyId, 2);
        var topOnlyBottom = TextureAtlas.GetTile(topOnlyId, 1);
        var allFacesTop = TextureAtlas.GetTile(allFacesId, 0);
        var allFacesSide = TextureAtlas.GetTile(allFacesId, 2);
        Check(
            "面级色调不污染未声明的侧面和底面",
            topOnlyTop != topOnlySide && topOnlySide == topOnlyBottom,
            $"top={topOnlyTop} side={topOnlySide} bottom={topOnlyBottom}");
        Check(
            "全方块色调仍复用同一着色瓦片",
            allFacesTop == allFacesSide,
            $"top={allFacesTop} side={allFacesSide}");
    }
    catch (Exception exception)
    {
        Check("方块面级色调契约", false, exception.ToString());
    }

    Console.WriteLine(failures == 0 ? "blocktintcheck 全部通过" : $"blocktintcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ProjectBlockIdCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var cubitRoot = FindCubitRepositoryRoot();
    var workspaceRoot = cubitRoot is null ? null : Directory.GetParent(cubitRoot)?.FullName;
    var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
    if (projectRoot is null || !Directory.Exists(projectRoot))
    {
        Check("定位首个项目方块编号表", false, projectRoot ?? "missing");
        Console.WriteLine($"projectblockidcheck 失败 {failures} 项");
        return 1;
    }

    try
    {
        var idMap = MyFirstCubitProject.ProjectBlockIdMap.Load(projectRoot);
        Check(
            "项目方块编号表保留既有 Oak 语义",
            idMap.GetId("my_first:granite") == 8 &&
            idMap.GetId("my_first:oak_leaves") == 9 &&
            idMap.GetId("my_first:oak_log") == 10,
            $"granite={idMap.GetId("my_first:granite")} leaves={idMap.GetId("my_first:oak_leaves")} log={idMap.GetId("my_first:oak_log")}");
        Check(
            "普通平原植被只使用既有项目编号后的追加区间",
            new[]
            {
                "my_first:short_grass", "my_first:dandelion", "my_first:orange_tulip", "my_first:red_tulip",
                "my_first:pink_tulip", "my_first:white_tulip", "my_first:poppy", "my_first:azure_bluet",
                "my_first:oxeye_daisy", "my_first:cornflower",
            }.All(key => idMap.GetId(key) >= 11));
        Check(
            "项目方块编号表不占用插件内置区间",
            idMap.Entries.All(entry => entry.Id >= 8));

        BlockRegistry.LoadContentPack(Path.Combine(projectRoot, "assets", "voxel"), idMap.Assignments);
        Check(
            "按项目编号表注册后 Oak 保持原持久 ID",
            BlockRegistry.GetId("my_first:oak_leaves") == 9 &&
            BlockRegistry.GetId("my_first:oak_log") == 10 &&
            BlockRegistry.GetKey(9) == "my_first:oak_leaves" &&
            BlockRegistry.GetKey(10) == "my_first:oak_log",
            $"id9={BlockRegistry.GetKey(9)} id10={BlockRegistry.GetKey(10)}");

        var worldDirectory = Path.Combine(projectRoot, "saves", "world-e1eea58b35a04ac9b480365d962dfb69");
        var repository = new MyFirstCubitProject.WorldRepository(projectRoot);
        var oldSummary = repository.List().Single(summary =>
            string.Equals(summary.Id, "world-e1eea58b35a04ac9b480365d962dfb69", StringComparison.Ordinal));
        var oldWorld = repository.Load(oldSummary);
        var oldOakLeaves = CountBlock(oldWorld, 9);
        var oldOakLogs = CountBlock(oldWorld, 10);
        Check(
            "旧 Region 中编号 9/10 仍解码为 Oak 树叶和原木",
            oldOakLeaves > 0 && oldOakLogs > 0 &&
            BlockRegistry.GetKey(9) == "my_first:oak_leaves" &&
            BlockRegistry.GetKey(10) == "my_first:oak_log",
            $"leaves={oldOakLeaves} logs={oldOakLogs}");

        var legacyMapMismatchRejected = !MyFirstCubitProject.ProjectWorldContentCompatibility.IsCompatible(
            "551ab04ac08d6f18fb7db72c275d6a3dd9bf97a18a82f6885ee27f2133d8aadc",
            id => id switch
            {
                8 => "my_first:granite",
                9 => "my_first:oak_log",
                10 => "my_first:oak_leaves",
                _ => null,
            });
        Check("旧内容摘要在数字 ID 语义漂移时拒绝加载", legacyMapMismatchRejected);

        var temporaryPack = Path.Combine(Path.GetTempPath(), $"cubit_explicit_block_ids_{Guid.NewGuid():N}");
        try
        {
            var blocksDirectory = Path.Combine(temporaryPack, "blocks");
            Directory.CreateDirectory(blocksDirectory);
            File.WriteAllText(
                Path.Combine(blocksDirectory, "a-first.json"),
                "{\"key\":\"tool.explicit:alpha\",\"name\":\"Alpha\",\"topTexture\":\"dirt\",\"sideTexture\":\"dirt\"}");
            File.WriteAllText(
                Path.Combine(blocksDirectory, "z-last.json"),
                "{\"key\":\"tool.explicit:zulu\",\"name\":\"Zulu\",\"topTexture\":\"dirt\",\"sideTexture\":\"dirt\"}");
            var explicitIds = new Dictionary<string, ushort>(StringComparer.Ordinal)
            {
                ["tool.explicit:alpha"] = 301,
                ["tool.explicit:zulu"] = 300,
            };
            _ = BlockRegistry.LoadContentPack(temporaryPack, explicitIds);
            Check(
                "显式编号不受内容文件排序影响",
                BlockRegistry.GetId("tool.explicit:alpha") == 301 &&
                BlockRegistry.GetId("tool.explicit:zulu") == 300);
            var changedMapRejected = false;
            try
            {
                _ = BlockRegistry.LoadContentPack(
                    temporaryPack,
                    new Dictionary<string, ushort>(StringComparer.Ordinal)
                    {
                        ["tool.explicit:alpha"] = 300,
                        ["tool.explicit:zulu"] = 301,
                    });
            }
            catch (InvalidOperationException)
            {
                changedMapRejected = true;
            }

            Check("同一内容包不能在会话中更换持久编号表", changedMapRejected);
        }
        finally
        {
            if (Directory.Exists(temporaryPack))
            {
                Directory.Delete(temporaryPack, recursive: true);
            }
        }
    }
    catch (Exception exception)
    {
        Check("项目统一方块编号契约", false, exception.ToString());
    }

    Console.WriteLine(failures == 0 ? "projectblockidcheck 全部通过" : $"projectblockidcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static int CountBlock(VoxelWorld world, ushort id)
    {
        var count = 0;
        foreach (var (chunkX, chunkZ) in world.Store.ChunkKeys)
        {
            var chunk = world.Store.GetChunk(chunkX, chunkZ)!;
            for (var y = Chunk.MinY; y < Chunk.MaxYExclusive; y++)
            {
                for (var z = 0; z < Chunk.SizeZ; z++)
                {
                    for (var x = 0; x < Chunk.SizeX; x++)
                    {
                        if (chunk.GetBlock(x, y, z).Id == id)
                        {
                            count++;
                        }
                    }
                }
            }
        }

        return count;
    }
}

static int ProjectWaterStreamCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var diagnosticLayers = new ChunkMeshLayers(
        new ChunkMeshData(new float[28], new uint[6]),
        new ChunkMeshData(new float[56], new uint[12]));
    Check(
        "网格诊断区分不透明与流体顶点和索引数",
        diagnosticLayers.Geometry == new ChunkMeshGeometry(
            OpaqueVertexCount: 4,
            OpaqueIndexCount: 6,
            FluidVertexCount: 8,
            FluidIndexCount: 12),
        diagnosticLayers.Geometry.ToString());

    var stages = Enum.GetValues<ChunkStreamingStage>();
    Check(
        "流式诊断覆盖 ticket、读取、生成、光照、网格和上传",
        stages.ToHashSet().IsSupersetOf(
        [
            ChunkStreamingStage.TicketWait,
            ChunkStreamingStage.StorageRead,
            ChunkStreamingStage.Generation,
            ChunkStreamingStage.InitialLighting,
            ChunkStreamingStage.BoundaryLighting,
            ChunkStreamingStage.MeshSnapshot,
            ChunkStreamingStage.MeshBuild,
            ChunkStreamingStage.MeshPublish,
            ChunkStreamingStage.MeshUpload,
        ]));

    var stageSink = new CollectingChunkStreamingDiagnosticsSink();
    var stageWorld = new VoxelWorld(20260826, WorldType.Flat);
    using (var stageJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var stageStreamer = new ChunkStreamer(stageWorld, stageJobs, diagnostics: stageSink))
    {
        stageStreamer.RequestArea(0, 0, 0);
        var deadline = Stopwatch.StartNew();
        while (deadline.Elapsed < TimeSpan.FromSeconds(10))
        {
            stageStreamer.Pump();
            _ = stageWorld.ConsumePendingMeshes();
            if (stageStreamer.PendingCount == 0 && stageStreamer.MeshedCount >= 1)
            {
                break;
            }

            Thread.Sleep(1);
        }
    }

    var requiredStages = new[]
    {
        ChunkStreamingStage.TicketWait,
        ChunkStreamingStage.Generation,
        ChunkStreamingStage.InitialLighting,
        ChunkStreamingStage.GenerationCommit,
        ChunkStreamingStage.BoundaryLighting,
        ChunkStreamingStage.MeshSnapshot,
        ChunkStreamingStage.MeshBuild,
        ChunkStreamingStage.MeshPublish,
    };
    var samples = stageSink.Samples;
    Check(
        "单区块流式输出各阶段样本",
        requiredStages.All(stage => samples.Any(sample =>
            sample.Stage == stage && sample.ChunkX == 0 && sample.ChunkZ == 0 && sample.ElapsedTicks >= 0)),
        $"stages={string.Join(',', samples.Select(sample => sample.Stage).Distinct())}");

    var uploadSink = new CollectingChunkStreamingDiagnosticsSink();
    var uploadBackend = new FakeRenderBackend();
    using (var uploadJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var uploadServer = new RenderingServer(uploadBackend))
    using (var uploadTree = new SceneTree())
    {
        var uploadNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            GenerateRadius = 0,
            Jobs = uploadJobs,
            Server = uploadServer,
            DiagnosticsSink = uploadSink,
        };
        uploadTree.Root.AddChild(uploadNode);
        uploadNode.EnsureAround(0, 0);
        var uploadDeadline = Stopwatch.StartNew();
        while (uploadDeadline.Elapsed < TimeSpan.FromSeconds(10) &&
               !uploadSink.Samples.Any(sample => sample.Stage == ChunkStreamingStage.MeshUpload))
        {
            uploadTree.ProcessFrame(1d / 60d);
            Thread.Sleep(1);
        }

        var uploadSamples = uploadSink.Samples;
        Check(
            "节点真实上传输出 MeshUpload 样本",
            uploadSamples.Any(sample => sample.Stage == ChunkStreamingStage.MeshUpload &&
                sample.ChunkX == 0 && sample.ChunkZ == 0 && sample.ElapsedTicks >= 0) &&
            uploadBackend.MeshUploadCount > 0 && uploadNode.LastMeshUploadMilliseconds >= 0d,
            $"uploads={uploadBackend.MeshUploadCount} stages={string.Join(',', uploadSamples.Select(sample => sample.Stage).Distinct())}");
    }

    try
    {
        var absentStageSummaries = CreateProjectWaterStreamingStageSummaries([]);
        Check(
            "未执行的已存档阶段仍输出零样本汇总",
            absentStageSummaries.Count == Enum.GetValues<ChunkStreamingStage>().Length &&
            absentStageSummaries.All(summary =>
                summary.SampleCount == 0 && summary.P95Milliseconds == 0d && summary.P95AllocatedBytes == 0),
            $"stages={absentStageSummaries.Count}");
    }
    catch (Exception exception)
    {
        Check("未执行的已存档阶段仍输出零样本汇总", false, exception.Message);
    }

    if (failures != 0)
    {
        Console.WriteLine($"projectwaterstreamcheck 失败 {failures} 项");
        return 1;
    }

    var evidence = RunProjectWaterStreamingEvidence();
    const int expectedRounds = 3;
    Check(
        "水域 MeshBuild 证据为两种路线与两种 worker 的三轮暖态新建会话",
        evidence.Schema == "cubit.project-water-mesh-build/v2" &&
        evidence.Scenario.StorageMode == "fresh-without-storage" &&
        evidence.Scenario.WarmupTrajectoriesPerRoute == 1 &&
        evidence.Scenario.MeasurementRounds == expectedRounds &&
        evidence.Runs.Count == 2 * 2 * expectedRounds &&
        evidence.Runs.All(run => run.Segments.Count == 4 && run.Segments.All(segment => segment.PendingCount == 0)) &&
        File.Exists(evidence.OutputPath),
        $"schema={evidence.Schema} runs={evidence.Runs.Count}");
    Check(
        "水域最终发布网格含流体，对照最终发布网格不含流体",
        evidence.Runs.Where(run => run.RouteKind == "water").All(run =>
            run.Segments.All(segment =>
                segment.StaticFluidColumnCount > 0 &&
                segment.FinalPublishedGeometry.FluidVertexCount > 0 &&
                segment.FinalPublishedGeometry.FluidIndexCount > 0)) &&
        evidence.Runs.Where(run => run.RouteKind == "control").All(run =>
            run.Segments.All(segment =>
                segment.StaticFluidColumnCount == 0 &&
                segment.FinalPublishedGeometry.FluidVertexCount == 0 &&
                segment.FinalPublishedGeometry.FluidIndexCount == 0)));
    Check(
        "同路线重复暖态与一四 worker 的方块哈希和最终网格几何完全一致",
        HasStableProjectWaterMeshBuildResults(evidence.Runs),
        DescribeProjectWaterMeshBuildInstability(evidence.Runs));

    Console.WriteLine(failures == 0
        ? "projectwaterstreamcheck 全部通过"
        : $"projectwaterstreamcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static ProjectWaterMeshBuildEvidence RunProjectWaterStreamingEvidence()
{
    const uint seed = 20260826;
    const int renderRadius = 1;
    const int readyQueryRadius = 0;
    const int segmentsPerRoute = 4;
    const int warmupTrajectoriesPerRoute = 1;
    const int measurementRounds = 3;
    const double frameDeltaSeconds = 1d / 60d;
    var cubitRoot = FindCubitRepositoryRoot()
        ?? throw new InvalidOperationException("未找到 Cubit 仓库根目录，不能运行项目水域流式证据");
    var workspaceRoot = Directory.GetParent(cubitRoot)?.FullName
        ?? throw new InvalidOperationException("未找到 Cubit 工作区根目录");
    var projectRoot = Path.Combine(workspaceRoot, "我的第一个cubit项目");
    if (!Directory.Exists(projectRoot))
    {
        throw new DirectoryNotFoundException($"未找到首个项目: {projectRoot}");
    }

    var blockIds = MyFirstCubitProject.ProjectBlockIdMap.Load(projectRoot);
    BlockRegistry.LoadContentPack(Path.Combine(projectRoot, "assets", "voxel"), blockIds.Assignments);
    TextureAtlas.ConfigureProjectTextureDirectory(
        Path.Combine(projectRoot, "assets", "minecraft", "textures", "block"));
    var terrainPasses = new IVoxelTerrainPass[]
    {
        new MyFirstCubitProject.RiverBasinTerrainPass(),
    };
    var featurePasses = new IVoxelFeaturePass[]
    {
        new MyFirstCubitProject.OakWorldgenPass(projectRoot),
        new MyFirstCubitProject.PlainsVegetationPass(projectRoot),
    };
    var routes = SelectProjectWaterStreamingRoutes(seed, terrainPasses, segmentsPerRoute, renderRadius * 2 + 1);
    var environment = new BenchmarkEnvironmentRecord(
        Environment.Version.ToString(),
        RuntimeInformation.FrameworkDescription,
        RuntimeInformation.OSDescription,
        RuntimeInformation.ProcessArchitecture.ToString(),
        RuntimeInformation.OSArchitecture.ToString(),
        Environment.ProcessorCount,
        Stopwatch.Frequency,
        GetToolAssemblyFingerprint());
    var runs = new List<ProjectWaterStreamingRun>(2 * 2 * measurementRounds);
    foreach (var workerCount in new[] { 1, 4 })
    {
        foreach (var route in routes)
        {
            for (var warmup = 0; warmup < warmupTrajectoriesPerRoute; warmup++)
            {
                _ = RunProjectWaterStreamingRoute(
                    seed,
                    route,
                    workerCount,
                    round: -1,
                    renderRadius,
                    readyQueryRadius,
                    frameDeltaSeconds,
                    terrainPasses,
                    featurePasses);
            }

            for (var round = 1; round <= measurementRounds; round++)
            {
                runs.Add(RunProjectWaterStreamingRoute(
                    seed,
                    route,
                    workerCount,
                    round,
                    renderRadius,
                    readyQueryRadius,
                    frameDeltaSeconds,
                    terrainPasses,
                    featurePasses));
            }
        }
    }

    var evidenceDirectory = Path.Combine(cubitRoot, "docs", "benchmarks");
    var outputPath = Path.Combine(evidenceDirectory, "project-water-streaming-evidence.json");
    var evidence = new ProjectWaterMeshBuildEvidence(
        "cubit.project-water-mesh-build/v2",
        DateTimeOffset.UtcNow,
        environment,
        new ProjectWaterMeshBuildScenario(
            seed,
            "noise",
            "fresh-without-storage",
            renderRadius,
            readyQueryRadius,
            frameDeltaSeconds,
            warmupTrajectoriesPerRoute,
            measurementRounds,
            "river-v3 + project Oak + Plains feature passes",
            "p95 uses nearest-rank samples after ascending sort; allocations are per executing managed thread.",
            "FinalPublishedGeometry is the exact accepted target mesh per-layer vertex/index count; MeshBuild stage totals cover completed build samples observed in that segment.",
            "MeshUpload measures CPU-side RenderingServer scheduling through FakeRenderBackend; it excludes Vulkan driver and GPU execution."),
        runs,
        outputPath);
    var json = JsonSerializer.Serialize(evidence, new JsonSerializerOptions
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        WriteIndented = true,
    });
    Directory.CreateDirectory(evidenceDirectory);
    File.WriteAllText(outputPath, json + Environment.NewLine);
    Console.WriteLine($"项目水域流式证据已写入 {outputPath}");
    return evidence;
}

static IReadOnlyList<ProjectWaterStreamingRoute> SelectProjectWaterStreamingRoutes(
    uint seed,
    IReadOnlyList<IVoxelTerrainPass> terrainPasses,
    int segmentsPerRoute,
    int minimumRouteSpacing)
{
    var water = new List<ProjectWaterStreamingRouteSegment>(segmentsPerRoute);
    var control = new List<ProjectWaterStreamingRouteSegment>(segmentsPerRoute);
    const int scanRadiusChunks = 24;
    for (var chunkZ = -scanRadiusChunks;
         chunkZ <= scanRadiusChunks && (water.Count < segmentsPerRoute || control.Count < segmentsPerRoute);
         chunkZ++)
    {
        for (var chunkX = -scanRadiusChunks;
             chunkX <= scanRadiusChunks && (water.Count < segmentsPerRoute || control.Count < segmentsPerRoute);
             chunkX++)
        {
            var staticFluidColumns = CountStaticFluidColumns(chunkX, chunkZ, seed, terrainPasses);
            if (staticFluidColumns > 0 && water.Count < segmentsPerRoute &&
                IsProjectWaterStreamingSegmentSeparated(water, chunkX, chunkZ, minimumRouteSpacing))
            {
                water.Add(new ProjectWaterStreamingRouteSegment(chunkX, chunkZ, staticFluidColumns));
            }
            else if (staticFluidColumns == 0 && control.Count < segmentsPerRoute &&
                     IsProjectWaterStreamingSegmentSeparated(control, chunkX, chunkZ, minimumRouteSpacing))
            {
                control.Add(new ProjectWaterStreamingRouteSegment(chunkX, chunkZ, staticFluidColumns));
            }
        }
    }

    if (water.Count != segmentsPerRoute || control.Count != segmentsPerRoute)
    {
        throw new InvalidOperationException(
            $"固定范围无法选出水域和干燥轨迹: water={water.Count} control={control.Count}");
    }

    Console.WriteLine(
        $"水域轨迹: {string.Join(" -> ", water.Select(segment => $"({segment.ChunkX},{segment.ChunkZ}) water={segment.StaticFluidColumnCount}"))}");
    Console.WriteLine(
        $"对照轨迹: {string.Join(" -> ", control.Select(segment => $"({segment.ChunkX},{segment.ChunkZ}) water={segment.StaticFluidColumnCount}"))}");
    return
    [
        new ProjectWaterStreamingRoute("water", water),
        new ProjectWaterStreamingRoute("control", control),
    ];
}

static bool IsProjectWaterStreamingSegmentSeparated(
    IReadOnlyList<ProjectWaterStreamingRouteSegment> selected,
    int chunkX,
    int chunkZ,
    int minimumRouteSpacing) => selected.All(segment =>
    Math.Max(Math.Abs(segment.ChunkX - chunkX), Math.Abs(segment.ChunkZ - chunkZ)) >= minimumRouteSpacing);

static int CountStaticFluidColumns(
    int chunkX,
    int chunkZ,
    uint seed,
    IReadOnlyList<IVoxelTerrainPass> terrainPasses)
{
    var count = 0;
    for (var localZ = 0; localZ < Chunk.SizeZ; localZ++)
    {
        for (var localX = 0; localX < Chunk.SizeX; localX++)
        {
            var column = WorldGenerator.GetTerrainColumn(
                chunkX * Chunk.SizeX + localX,
                chunkZ * Chunk.SizeZ + localZ,
                seed,
                WorldType.Noise,
                terrainPasses);
            if (column.HasStaticFluid)
            {
                count++;
            }
        }
    }

    return count;
}

static ProjectWaterStreamingRun RunProjectWaterStreamingRoute(
    uint seed,
    ProjectWaterStreamingRoute route,
    int workerCount,
    int round,
    int renderRadius,
    int readyQueryRadius,
    double frameDeltaSeconds,
    IReadOnlyList<IVoxelTerrainPass> terrainPasses,
    IReadOnlyList<IVoxelFeaturePass> featurePasses)
{
    var diagnostics = new CollectingChunkStreamingDiagnosticsSink();
    var segments = new List<ProjectWaterStreamingSegment>(route.Segments.Count);
    using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = workerCount });
    using var server = new RenderingServer(new FakeRenderBackend());
    using var tree = new SceneTree();
    var node = new VoxelWorldNode
    {
        Name = "World",
        Seed = seed,
        WorldType = WorldType.Noise,
        GenerateRadius = renderRadius,
        BlockTickRadius = renderRadius,
        EntitySimulationRadius = renderRadius,
        Jobs = jobs,
        Server = server,
        TerrainPasses = terrainPasses,
        FeaturePasses = featurePasses,
        DiagnosticsSink = diagnostics,
    };
    tree.Root.AddChild(node);
    node.ReplaceWorld(
        new VoxelWorld(seed, WorldType.Noise, terrainPasses: terrainPasses, featurePasses: featurePasses),
        storage: null);

    foreach (var routeSegment in route.Segments)
    {
        var sampleOffset = diagnostics.Samples.Count;
        var frameMilliseconds = new List<double>();
        var frameAllocatedBytes = new List<long>();
        node.EnsureAround(routeSegment.ChunkX, routeSegment.ChunkZ);
        var deadline = Stopwatch.StartNew();
        while (deadline.Elapsed < TimeSpan.FromSeconds(60))
        {
            var allocationStarted = GC.GetAllocatedBytesForCurrentThread();
            var frameStarted = Stopwatch.GetTimestamp();
            tree.ProcessFrame(frameDeltaSeconds);
            frameMilliseconds.Add((Stopwatch.GetTimestamp() - frameStarted) * 1000d / Stopwatch.Frequency);
            frameAllocatedBytes.Add(GC.GetAllocatedBytesForCurrentThread() - allocationStarted);
            var streamer = node.Streamer
                ?? throw new InvalidOperationException("水域轨迹期间 VoxelWorldNode 丢失 ChunkStreamer");
            if (streamer.GetAreaProgress(routeSegment.ChunkX, routeSegment.ChunkZ, readyQueryRadius).IsReady &&
                streamer.PendingCount == 0)
            {
                break;
            }

            Thread.Sleep(1);
        }

        var activeStreamer = node.Streamer
            ?? throw new InvalidOperationException("水域轨迹结束时 VoxelWorldNode 丢失 ChunkStreamer");
        var progress = activeStreamer.GetAreaProgress(routeSegment.ChunkX, routeSegment.ChunkZ, readyQueryRadius);
        if (!progress.IsReady || activeStreamer.PendingCount != 0)
        {
            var status = node.World?.Store.GetStatus(routeSegment.ChunkX, routeSegment.ChunkZ);
            var stageNames = diagnostics.Samples
                .Skip(sampleOffset)
                .Where(sample => sample.ChunkX == routeSegment.ChunkX && sample.ChunkZ == routeSegment.ChunkZ)
                .Select(sample => sample.Stage)
                .Distinct()
                .ToArray();
            throw new TimeoutException(
                $"水域轨迹段未就绪: fresh/{route.Kind}/w{workerCount}/round{round} " +
                $"({routeSegment.ChunkX},{routeSegment.ChunkZ}) readyRadius={readyQueryRadius} progress={progress} status={status} " +
                $"pending={activeStreamer.PendingCount} stages={string.Join(',', stageNames)}");
        }

        var stageSamples = diagnostics.Samples
            .Skip(sampleOffset)
            .Where(sample => sample.ChunkX == routeSegment.ChunkX && sample.ChunkZ == routeSegment.ChunkZ)
            .ToArray();
        var world = node.World
            ?? throw new InvalidOperationException("水域轨迹结束时 VoxelWorldNode 丢失 VoxelWorld");
        var chunk = world.Store.GetChunk(routeSegment.ChunkX, routeSegment.ChunkZ)
            ?? throw new InvalidOperationException("水域轨迹段就绪但目标区块缺失");
        var finalPublishedGeometry = stageSamples
            .Where(sample => sample.Stage == ChunkStreamingStage.MeshPublish)
            .OrderBy(sample => sample.Sequence)
            .Select(sample => sample.Geometry)
            .LastOrDefault();
        if (finalPublishedGeometry == default)
        {
            throw new InvalidOperationException(
                $"水域轨迹段缺少最终发布网格: ({routeSegment.ChunkX},{routeSegment.ChunkZ})");
        }

        segments.Add(new ProjectWaterStreamingSegment(
            routeSegment.ChunkX,
            routeSegment.ChunkZ,
            routeSegment.StaticFluidColumnCount,
            activeStreamer.PendingCount,
            ComputeChunkBlockHash(chunk),
            finalPublishedGeometry,
            CreateProjectWaterStreamingStageSummaries(stageSamples),
            frameMilliseconds.Count,
            Percentile(frameMilliseconds, 0.95),
            (long)Percentile(frameAllocatedBytes.Select(value => (double)value), 0.95),
            frameAllocatedBytes.Sum()));
    }

    return new ProjectWaterStreamingRun(route.Kind, workerCount, round, route.Segments, segments);
}

static IReadOnlyList<ProjectWaterStreamingStageSummary> CreateProjectWaterStreamingStageSummaries(
    IReadOnlyList<ChunkStreamingDiagnosticSample> samples)
{
    var stages = new List<ProjectWaterStreamingStageSummary>(Enum.GetValues<ChunkStreamingStage>().Length);
    foreach (var stage in Enum.GetValues<ChunkStreamingStage>())
    {
        var stageSamples = samples.Where(sample => sample.Stage == stage).ToArray();
        if (stageSamples.Length == 0)
        {
            stages.Add(new ProjectWaterStreamingStageSummary(
                stage,
                SampleCount: 0,
                MedianMilliseconds: 0d,
                P95Milliseconds: 0d,
                TotalMilliseconds: 0d,
                MedianAllocatedBytes: 0d,
                P95AllocatedBytes: 0,
                TotalAllocatedBytes: 0,
                LoadedFromStorageSampleCount: 0,
                TotalOpaqueVertexCount: 0,
                TotalOpaqueIndexCount: 0,
                TotalFluidVertexCount: 0,
                TotalFluidIndexCount: 0));
            continue;
        }

        var milliseconds = stageSamples
            .Select(sample => sample.ElapsedTicks * 1000d / Stopwatch.Frequency)
            .ToArray();
        var allocations = stageSamples.Select(sample => sample.AllocatedBytes).ToArray();
        var totalOpaqueVertexCount = stageSamples.Sum(sample => (long)sample.Geometry.OpaqueVertexCount);
        var totalOpaqueIndexCount = stageSamples.Sum(sample => (long)sample.Geometry.OpaqueIndexCount);
        var totalFluidVertexCount = stageSamples.Sum(sample => (long)sample.Geometry.FluidVertexCount);
        var totalFluidIndexCount = stageSamples.Sum(sample => (long)sample.Geometry.FluidIndexCount);
        stages.Add(new ProjectWaterStreamingStageSummary(
            stage,
            stageSamples.Length,
            Median(milliseconds),
            Percentile(milliseconds, 0.95),
            milliseconds.Sum(),
            Median(allocations.Select(value => (double)value)),
            (long)Percentile(allocations.Select(value => (double)value), 0.95),
            allocations.Sum(),
            stageSamples.Count(sample => sample.LoadedFromStorage),
            totalOpaqueVertexCount,
            totalOpaqueIndexCount,
            totalFluidVertexCount,
            totalFluidIndexCount));
    }

    return stages;
}

static bool HasStableProjectWaterMeshBuildResults(IReadOnlyList<ProjectWaterStreamingRun> runs) =>
    runs.GroupBy(run => run.RouteKind, StringComparer.Ordinal)
        .All(group =>
        {
            var orderedRuns = group
                .OrderBy(run => run.WorkerCount)
                .ThenBy(run => run.Round)
                .ToArray();
            var expected = CreateProjectWaterMeshBuildSegmentStates(orderedRuns[0]);
            return orderedRuns.All(run =>
                expected.SequenceEqual(CreateProjectWaterMeshBuildSegmentStates(run)));
        });

static string DescribeProjectWaterMeshBuildInstability(IReadOnlyList<ProjectWaterStreamingRun> runs)
{
    var divergentRuns = new List<string>();
    foreach (var group in runs.GroupBy(run => run.RouteKind, StringComparer.Ordinal))
    {
        var orderedRuns = group
            .OrderBy(run => run.WorkerCount)
            .ThenBy(run => run.Round)
            .ToArray();
        var expected = CreateProjectWaterMeshBuildSegmentStates(orderedRuns[0]);
        foreach (var run in orderedRuns.Skip(1))
        {
            if (!expected.SequenceEqual(CreateProjectWaterMeshBuildSegmentStates(run)))
            {
                divergentRuns.Add($"{run.RouteKind}/w{run.WorkerCount}/round{run.Round}");
            }
        }
    }

    return divergentRuns.Count == 0 ? "stable" : string.Join(", ", divergentRuns);
}

static ProjectWaterMeshBuildSegmentState[] CreateProjectWaterMeshBuildSegmentStates(
    ProjectWaterStreamingRun run) =>
    run.Segments
        .Select(segment => new ProjectWaterMeshBuildSegmentState(
            segment.ChunkX,
            segment.ChunkZ,
            segment.BlockHash,
            segment.FinalPublishedGeometry))
        .ToArray();

static ulong ComputeChunkBlockHash(Chunk chunk)
{
    var hash = 14695981039346656037UL;
    for (var y = Chunk.MinY; y < Chunk.MaxYExclusive; y++)
    {
        for (var z = 0; z < Chunk.SizeZ; z++)
        {
            for (var x = 0; x < Chunk.SizeX; x++)
            {
                hash ^= chunk.GetBlock(x, y, z).Packed;
                hash *= 1099511628211UL;
            }
        }
    }

    return hash;
}

static int ProjectWaterCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var cubitRoot = FindCubitRepositoryRoot();
    var workspaceRoot = cubitRoot is null ? null : Directory.GetParent(cubitRoot)?.FullName;
    var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
    if (projectRoot is null || !Directory.Exists(projectRoot))
    {
        Check("定位首个项目水资源", false, projectRoot ?? "missing");
        Console.WriteLine($"projectwatercheck 失败 {failures} 项");
        return 1;
    }

    var playerControllerPath = Path.Combine(projectRoot, "src", "PlayerController.cs");
    var resolvedCubitRoot = cubitRoot ?? throw new InvalidOperationException("未找到 Cubit 仓库根目录");
    var resolvedWorkspaceRoot = workspaceRoot ?? throw new InvalidOperationException("未找到工作区根目录");

    try
    {
        var playerControllerSource = File.ReadAllText(playerControllerPath);
        var idMap = MyFirstCubitProject.ProjectBlockIdMap.Load(projectRoot);
        Check(
            "水只追加为项目 ID 21",
            idMap.GetId("my_first:water") == 21 && idMap.NextId == 22,
            $"id={idMap.GetId("my_first:water")} next={idMap.NextId}");

        var textureDirectory = Path.Combine(projectRoot, "assets", "minecraft", "textures", "block");
        var stillPath = Path.Combine(textureDirectory, "water_still.png");
        var flowPath = Path.Combine(textureDirectory, "water_flow.png");
        Check(
            "水纹理仅由项目 assets 管理",
            File.Exists(stillPath) && File.Exists(flowPath),
            $"still={File.Exists(stillPath)} flow={File.Exists(flowPath)}");

        var hydrology = new MyFirstCubitProject.OverworldHydrology(20260826);
        var repeated = hydrology.Sample(15, 0);
        Check(
            "相邻区块边界的流域采样稳定",
            repeated == new MyFirstCubitProject.OverworldHydrology(20260826).Sample(15, 0),
            $"sample={repeated}");
        Check(
            "不同种子产生不同流域",
            !new MyFirstCubitProject.OverworldHydrology(1).Sample(320, -192).Equals(
                new MyFirstCubitProject.OverworldHydrology(2).Sample(320, -192)));

        var sourceTextureDirectory = Path.Combine(
            resolvedWorkspaceRoot, "mc26.1.2", "26.1.2.jar.src", "assets", "minecraft", "textures", "block");
        var copiesOutsideProject = new[] { "water_still.png", "water_flow.png" }.Any(fileName =>
        {
            var hash = File.Exists(Path.Combine(textureDirectory, fileName))
                ? SHA256.HashData(File.ReadAllBytes(Path.Combine(textureDirectory, fileName)))
                : Array.Empty<byte>();
            return hash.Length > 0 && new[]
            {
                Path.Combine(resolvedCubitRoot, "src"),
                Path.Combine(resolvedCubitRoot, "hosts"),
                Path.Combine(resolvedWorkspaceRoot, ".codex", "visualizations"),
            }
            .Where(Directory.Exists)
            .SelectMany(directory => Directory.EnumerateFiles(directory, "*.png", SearchOption.AllDirectories))
            .Any(path => SHA256.HashData(File.ReadAllBytes(path)).SequenceEqual(hash));
        });
        Check("水纹理不复制到插件、宿主或预览目录", !copiesOutsideProject, sourceTextureDirectory);

        BlockRegistry.LoadContentPack(Path.Combine(projectRoot, "assets", "voxel"), idMap.Assignments);
        var waterId = BlockRegistry.GetId("my_first:water");
        var waterDefinition = BlockRegistry.Get(waterId);
        Check(
            "水使用 Fluid、无碰撞、半透明定义",
            waterDefinition.RenderShape == BlockRenderShape.Fluid &&
            !waterDefinition.Solid && !waterDefinition.Opaque &&
            waterDefinition.LightAttenuation == 1 &&
            waterDefinition.TopTexture == "water_still" &&
            waterDefinition.SideTexture == "water_flow",
            $"shape={waterDefinition.RenderShape} solid={waterDefinition.Solid} opaque={waterDefinition.Opaque}");
        Check(
            "灰阶原版水纹理应用平原水色调",
            string.Equals(waterDefinition.Tint, "#3f76e4", StringComparison.OrdinalIgnoreCase) &&
            waterDefinition.TintFaces == BlockTintFaces.All,
            $"tint={waterDefinition.Tint} faces={waterDefinition.TintFaces}");
        var ignoredFluidRaycastCount = playerControllerSource
            .Split("VoxelRaycastFluidMode.None", StringSplitOptions.None)
            .Length - 1;
        Check(
            "普通挖放和第三人称相机显式忽略流体",
            ignoredFluidRaycastCount == 2,
            $"count={ignoredFluidRaycastCount}");

        var waterInput = new VoxelInputState();
        var waterInputRouter = new MyFirstCubitProject.VoxelProjectInputRouter(
            waterInput,
            new MyFirstCubitProject.VoxelDebugOverlayState());
        waterInputRouter.Handle(new ProjectInputEvent(ProjectInputControl.Digit7, true));
        Check(
            "项目第七快捷栏槽位选择静态水方块",
            waterInput.BuildSnapshot().SelectedBlock == waterId,
            $"selected={waterInput.BuildSnapshot().SelectedBlock}");

        var editWorld = new VoxelWorld(20260826, WorldType.Flat);
        editWorld.Store.AddChunk(0, 0, new Chunk());
        editWorld.Store.AddChunk(1, 0, new Chunk());
        var sourceWater = VoxelFluidState.Source(waterId);
        var interiorEdited = editWorld.SetBlockDeferred(8, 32, 8, sourceWater, out var interiorAffected);
        Check(
            "内部水编辑只标记中心区块网格",
            interiorEdited && interiorAffected.SequenceEqual([(0, 0)]) &&
            editWorld.GetBlock(8, 32, 8) == sourceWater,
            $"affected={string.Join(',', interiorAffected.Select(key => $"({key.X},{key.Z})"))}");

        var boundaryEdited = editWorld.SetBlockDeferred(15, 32, 8, sourceWater, out var boundaryAffected);
        Check(
            "边界水编辑只标记相邻两区块网格",
            boundaryEdited && boundaryAffected.SequenceEqual([(0, 0), (1, 0)]),
            $"affected={string.Join(',', boundaryAffected.Select(key => $"({key.X},{key.Z})"))}");
        Check(
            "W1 水编辑不会登记计划刻",
            editWorld.ScheduledTickCount == 0,
            $"scheduled={editWorld.ScheduledTickCount}");
        Check(
            "体素世界公开网格、透明网格和待上传统计",
            editWorld.MeshedChunkCount >= 0 &&
            editWorld.FluidMeshChunkCount >= 0 &&
            editWorld.PendingMeshUploadCount >= 0,
            $"meshed={editWorld.MeshedChunkCount} fluid={editWorld.FluidMeshChunkCount} pending={editWorld.PendingMeshUploadCount}");

        TextureAtlas.ConfigureProjectTextureDirectory(textureDirectory);
        var stillTile = TextureAtlas.GetTile(waterId, 0);
        var (stillU0, stillV0, stillU1, stillV1) = TextureAtlas.GetUv(stillTile);
        var waterAtlas = TextureAtlas.AtlasData;
        var waterAtlasWidth = TextureAtlas.AtlasWidth;
        var waterAtlasHeight = TextureAtlas.AtlasHeight;
        long waterRed = 0;
        long waterGreen = 0;
        long waterBlue = 0;
        var waterPixelCount = 0;
        for (var y = (int)(stillV0 * waterAtlasHeight); y < (int)(stillV1 * waterAtlasHeight); y++)
        {
            for (var x = (int)(stillU0 * waterAtlasWidth); x < (int)(stillU1 * waterAtlasWidth); x++)
            {
                var offset = (y * waterAtlasWidth + x) * 4;
                if (waterAtlas[offset + 3] == 0)
                {
                    continue;
                }

                waterRed += waterAtlas[offset];
                waterGreen += waterAtlas[offset + 1];
                waterBlue += waterAtlas[offset + 2];
                waterPixelCount++;
            }
        }
        Check(
            "水图集保留原版灰阶细节并呈蓝色",
            waterPixelCount > 0 && waterBlue > waterGreen && waterGreen > waterRed,
            $"pixels={waterPixelCount} rgb={waterRed}/{waterGreen}/{waterBlue}");
        using (var editJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
        using (var editServer = new RenderingServer(new FakeRenderBackend()))
        using (var editTree = new SceneTree())
        {
            var worldNode = new VoxelWorldNode
            {
                Name = "World",
                WorldType = WorldType.Flat,
                Jobs = editJobs,
                Server = editServer,
            };
            editTree.Root.AddChild(worldNode);
            worldNode.ReplaceWorld(editWorld);

            var placedSource = worldNode.TrySetBlock(9, 32, 8, sourceWater);
            Check(
                "节点 BlockState 放置保留静态源水编码",
                placedSource && editWorld.GetBlock(9, 32, 8) == sourceWater,
                $"state={editWorld.GetBlock(9, 32, 8)}");

            var overlay = new MyFirstCubitProject.VoxelDebugOverlayState();
            overlay.Attach(editTree.Root);
            overlay.Toggle();
            var overlaySnapshot = overlay.CaptureSnapshot();
            Check(
                "F3 显示水体网格与计划刻诊断",
                overlaySnapshot.RightLines.Any(line => line.StartsWith("Voxel Mesh:", StringComparison.Ordinal)),
                string.Join(" | ", overlaySnapshot.RightLines));
        }

        var waterColumn = Enumerable.Range(-512, 1025)
            .SelectMany(z => Enumerable.Range(-512, 1025)
                .Where(x => x % Chunk.SizeX == Chunk.SizeX - 1)
                .Select(x => (X: x, Z: z, Column: hydrology.Sample(x, z))))
            .FirstOrDefault(entry => entry.Column.HasWater && hydrology.Sample(entry.X + 1, entry.Z).HasWater);
        Check(
            "河槽跨区块边界连续",
            waterColumn.Column.HasWater && hydrology.Sample(waterColumn.X + 1, waterColumn.Z).HasWater,
            $"x={waterColumn.X} z={waterColumn.Z} sample={waterColumn.Column}");

        if (waterColumn.Column.HasWater)
        {
            var pass = new MyFirstCubitProject.RiverBasinTerrainPass();
            var context = new VoxelTerrainColumnContext(
                waterColumn.X,
                waterColumn.Z,
                20260826,
                WorldType.Noise,
                waterColumn.Column.WaterY + 8);
            var initial = VoxelTerrainColumn.CreateBase(context.BaseSurfaceY);
            var result = pass.Evaluate(in context, in initial);
            Check(
                "项目流域通道只通过通用列契约填入静态水",
                result.StaticFluid == VoxelFluidState.Source(waterId) &&
                result.SurfaceY <= waterColumn.Column.BedY &&
                result.FluidSurfaceY == waterColumn.Column.WaterY,
                $"surface={result.SurfaceY} fluid={result.FluidSurfaceY}");
        }

        var riverPass = new MyFirstCubitProject.RiverBasinTerrainPass();
        Check(
            "当前流域通道标识 river-v3",
            string.Equals(riverPass.Id, "project.my_first.river_basin.v3", StringComparison.Ordinal),
            $"pass={riverPass.Id}");
        var greatestRiverBankStep = 0;
        (int X, int Z, VoxelTerrainColumn Column, MyFirstCubitProject.HydrologyColumn Hydrology)? unfilledLowland = null;
        (int X, int Z, VoxelTerrainColumn Water, VoxelTerrainColumn Neighbor)? unsupportedWaterEdge = null;
        for (var z = -256; z <= 256; z++)
        {
            for (var x = -256; x < 256; x++)
            {
                var current = WorldGenerator.GetTerrainColumn(
                    x,
                    z,
                    20260826,
                    WorldType.Noise,
                    [riverPass]);
                var east = WorldGenerator.GetTerrainColumn(
                    x + 1,
                    z,
                    20260826,
                    WorldType.Noise,
                    [riverPass]);
                var south = WorldGenerator.GetTerrainColumn(
                    x,
                    z + 1,
                    20260826,
                    WorldType.Noise,
                    [riverPass]);
                greatestRiverBankStep = Math.Max(greatestRiverBankStep, Math.Abs(current.SurfaceY - east.SurfaceY));
                greatestRiverBankStep = Math.Max(greatestRiverBankStep, Math.Abs(current.SurfaceY - south.SurfaceY));

                var currentHydrology = hydrology.Sample(x, z);
                if (unfilledLowland is null &&
                    current.SurfaceY < currentHydrology.WaterY &&
                    (!current.HasStaticFluid || current.FluidSurfaceY != currentHydrology.WaterY))
                {
                    unfilledLowland = (x, z, current, currentHydrology);
                }

                if (unsupportedWaterEdge is null && current.HasStaticFluid)
                {
                    var dryEastBelowWater = !east.HasStaticFluid && east.SurfaceY < current.FluidSurfaceY;
                    var drySouthBelowWater = !south.HasStaticFluid && south.SurfaceY < current.FluidSurfaceY;
                    if (dryEastBelowWater)
                    {
                        unsupportedWaterEdge = (x, z, current, east);
                    }
                    else if (drySouthBelowWater)
                    {
                        unsupportedWaterEdge = (x, z, current, south);
                    }
                }
            }
        }

        Check(
            "流域岸线保持连续坡度而非峡谷断崖",
            greatestRiverBankStep <= 2,
            $"maxStep={greatestRiverBankStep}");
        Check(
            "低于水位的最终地表列必须填满静态水",
            unfilledLowland is null,
            unfilledLowland is { } lowland
                ? $"x={lowland.X} z={lowland.Z} surface={lowland.Column.SurfaceY} fluid={lowland.Column.FluidSurfaceY} hydrology={lowland.Hydrology}"
                : string.Empty);
        Check(
            "水体边缘必须由同水面或不低于水位的岸承接",
            unsupportedWaterEdge is null,
            unsupportedWaterEdge is { } edge
                ? $"x={edge.X} z={edge.Z} waterSurface={edge.Water.FluidSurfaceY} neighborSurface={edge.Neighbor.SurfaceY}"
                : string.Empty);

        var repository = new MyFirstCubitProject.WorldRepository(projectRoot);
        var temporaryWorlds = new List<MyFirstCubitProject.WorldSummary>();
        try
        {
            var terrainPasses = new IVoxelTerrainPass[]
            {
                new MyFirstCubitProject.RiverBasinTerrainPass(),
            };
            var created = repository.Create("水体 profile 检查", 20260826, WorldType.Noise);
            temporaryWorlds.Add(created);
            var createdMetadataPath = Path.Combine(projectRoot, "saves", created.Id, "world.cubit.json");
            var createdMetadata = JsonNode.Parse(File.ReadAllText(createdMetadataPath))!.AsObject();
            Check(
                "新 Noise 世界写入 river-v3 profile",
                string.Equals(createdMetadata["worldGenerationProfile"]?.GetValue<string>(), "river-v3", StringComparison.Ordinal));
            using (var createdSession = repository.Open(created, terrainPasses: terrainPasses))
            {
                Check(
                    "river-v3 世界注入项目地形通道",
                    createdSession.WorldGenerationProfile == "river-v3" &&
                    createdSession.World.TerrainPasses.Count == 1,
                    $"profile={createdSession.WorldGenerationProfile} passes={createdSession.World.TerrainPasses.Count}");
            }

            var legacyPassType = typeof(MyFirstCubitProject.RiverBasinTerrainPass).Assembly.GetType(
                "MyFirstCubitProject.LegacyRiverBasinTerrainPass");
            var legacyPass = legacyPassType?.GetConstructor(Type.EmptyTypes)?.Invoke(null) as IVoxelTerrainPass;
            var versionedTerrainPasses = legacyPass is null
                ? terrainPasses
                : terrainPasses.Concat([legacyPass]).ToArray();
            createdMetadata["worldGenerationProfile"] = "river-v1";
            File.WriteAllText(createdMetadataPath, createdMetadata.ToJsonString());
            using (var riverV1Session = repository.Open(created, terrainPasses: versionedTerrainPasses))
            {
                Check(
                    "river-v1 世界继续使用已归档的流域通道",
                    riverV1Session.WorldGenerationProfile == "river-v1" &&
                    riverV1Session.World.TerrainPasses.Count == 1 &&
                    string.Equals(riverV1Session.World.TerrainPasses[0].Id, "project.my_first.river_basin.v1", StringComparison.Ordinal),
                    $"profile={riverV1Session.WorldGenerationProfile} pass={riverV1Session.World.TerrainPasses.FirstOrDefault()?.Id ?? "none"}");
            }
            var riverV2PassType = typeof(MyFirstCubitProject.RiverBasinTerrainPass).Assembly.GetType(
                "MyFirstCubitProject.RiverBasinTerrainPassV2");
            var riverV2Pass = riverV2PassType?.GetConstructor(Type.EmptyTypes)?.Invoke(null) as IVoxelTerrainPass;
            var fullyVersionedTerrainPasses = riverV2Pass is null
                ? versionedTerrainPasses
                : versionedTerrainPasses.Concat([riverV2Pass]).ToArray();
            createdMetadata["worldGenerationProfile"] = "river-v2";
            File.WriteAllText(createdMetadataPath, createdMetadata.ToJsonString());
            using (var riverV2Session = repository.Open(created, terrainPasses: fullyVersionedTerrainPasses))
            {
                Check(
                    "river-v2 世界继续使用已归档的流域通道",
                    riverV2Pass is not null &&
                    riverV2Session.WorldGenerationProfile == "river-v2" &&
                    riverV2Session.World.TerrainPasses.Count == 1 &&
                    string.Equals(riverV2Session.World.TerrainPasses[0].Id, "project.my_first.river_basin.v2", StringComparison.Ordinal),
                    $"profile={riverV2Session.WorldGenerationProfile} pass={riverV2Session.World.TerrainPasses.FirstOrDefault()?.Id ?? "none"}");
            }
            createdMetadata["worldGenerationProfile"] = "river-v3";
            File.WriteAllText(createdMetadataPath, createdMetadata.ToJsonString());

            var legacy = repository.Create("旧世界 profile 检查", 20260826, WorldType.Noise);
            temporaryWorlds.Add(legacy);
            var legacyMetadataPath = Path.Combine(projectRoot, "saves", legacy.Id, "world.cubit.json");
            var legacyMetadata = JsonNode.Parse(File.ReadAllText(legacyMetadataPath))!.AsObject();
            legacyMetadata["FormatVersion"] = 1;
            legacyMetadata.Remove("worldGenerationProfile");
            File.WriteAllText(legacyMetadataPath, legacyMetadata.ToJsonString());
            using (var legacySession = repository.Open(legacy, terrainPasses: terrainPasses))
            {
                Check(
                    "缺 profile 的历史世界保持 legacy-v0",
                    legacySession.WorldGenerationProfile == "legacy-v0" &&
                    legacySession.World.TerrainPasses.Count == 0,
                    $"profile={legacySession.WorldGenerationProfile} passes={legacySession.World.TerrainPasses.Count}");
            }

            var unknown = repository.Create("未知 profile 检查", 20260826, WorldType.Noise);
            temporaryWorlds.Add(unknown);
            var unknownMetadataPath = Path.Combine(projectRoot, "saves", unknown.Id, "world.cubit.json");
            var unknownMetadata = JsonNode.Parse(File.ReadAllText(unknownMetadataPath))!.AsObject();
            unknownMetadata["worldGenerationProfile"] = "unknown-v999";
            File.WriteAllText(unknownMetadataPath, unknownMetadata.ToJsonString());
            var unknownError = CaptureException(() => repository.Open(unknown, terrainPasses: terrainPasses));
            Check("未知世界生成 profile 被拒绝", unknownError is InvalidDataException, unknownError?.Message ?? "none");
            unknownMetadata["worldGenerationProfile"] = "river-v1";
            File.WriteAllText(unknownMetadataPath, unknownMetadata.ToJsonString());
        }
        finally
        {
            foreach (var summary in temporaryWorlds)
            {
                var directory = Path.Combine(projectRoot, "saves", summary.Id);
                if (Directory.Exists(directory))
                {
                    repository.Delete(summary);
                }
            }
        }
    }
    catch (Exception exception)
    {
        Check("项目水资源与流域契约", false, exception.ToString());
    }

    Console.WriteLine(failures == 0 ? "projectwatercheck 全部通过" : $"projectwatercheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int PlainsVegetationCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    try
    {
        const ushort crossId = 250;
        BlockRegistry.Register(new BlockDef
        {
            Id = crossId,
            Key = "tool:cross",
            Name = "Cross",
            TopTexture = "grass_block_top",
            SideTexture = "grass_block_top",
            BottomTexture = "grass_block_top",
            Solid = false,
            Opaque = false,
            RenderShape = BlockRenderShape.Cross,
        });

        var singleCross = new ChunkStore();
        var singleCrossChunk = new Chunk();
        singleCrossChunk.SetBlock(8, 64, 8, BlockRegistry.GetState(crossId));
        singleCross.AddChunk(0, 0, singleCrossChunk);
        var crossMesh = ChunkMesher.Mesh(singleCross, 0, 0).Opaque;
        Check(
            "Cross 方块网格化而不成为实体",
            BlockRegistry.IsRenderable(crossId) &&
            !BlockRegistry.IsSolid(crossId) &&
            !BlockRegistry.IsOpaque(crossId) &&
            crossMesh.Vertices.Length == 16 * 7 &&
            crossMesh.Indices.Length == 24,
            $"vertices={crossMesh.Vertices.Length} indices={crossMesh.Indices.Length}");
        var crossTile = TextureAtlas.GetTile(crossId, 0);
        var bottomUvs = new List<float>();
        var topUvs = new List<float>();
        var crossTiles = new List<float>();
        for (var index = 0; index < crossMesh.Vertices.Length; index += 7)
        {
            var vertexY = crossMesh.Vertices[index + 1];
            crossTiles.Add(crossMesh.Vertices[index + 6]);
            if (MathF.Abs(vertexY - 64f) < 0.0001f)
            {
                bottomUvs.Add(crossMesh.Vertices[index + 4]);
            }
            else if (MathF.Abs(vertexY - 65f) < 0.0001f)
            {
                topUvs.Add(crossMesh.Vertices[index + 4]);
            }
        }

        Check(
            "Cross 双面均保持纹理朝上，背面不生成倒置植物",
            bottomUvs.Count == 8 && topUvs.Count == 8 &&
            bottomUvs.All(value => MathF.Abs(value - 1f) < 0.0001f) &&
            topUvs.All(value => MathF.Abs(value) < 0.0001f) &&
            crossTiles.All(value => MathF.Abs(value - crossTile) < 0.0001f),
            $"bottom={string.Join(',', bottomUvs.Select(value => value.ToString("F3")))} " +
            $"top={string.Join(',', topUvs.Select(value => value.ToString("F3")))}");

        var grassAndCross = new ChunkStore();
        var grassAndCrossChunk = new Chunk();
        grassAndCrossChunk.SetBlock(8, 63, 8, BlockRegistry.GetState(BlockRegistry.Grass));
        grassAndCrossChunk.SetBlock(8, 64, 8, BlockRegistry.GetState(crossId));
        grassAndCross.AddChunk(0, 0, grassAndCrossChunk);
        var grassAndCrossMesh = ChunkMesher.Mesh(grassAndCross, 0, 0).Opaque;
        Check(
            "Cross 方块不遮挡草方块顶面",
            grassAndCrossMesh.Vertices.Length == (6 * 4 + 16) * 7 &&
            grassAndCrossMesh.Indices.Length == (6 * 6 + 24),
            $"vertices={grassAndCrossMesh.Vertices.Length} indices={grassAndCrossMesh.Indices.Length}");

        var onlyAir = new ChunkStore();
        onlyAir.AddChunk(0, 0, new Chunk());
        var airMesh = ChunkMesher.Mesh(onlyAir, 0, 0).Opaque;
        Check(
            "空气不会因为通用可渲染契约被网格化",
            airMesh.Vertices.Length == 0 && airMesh.Indices.Length == 0,
            $"vertices={airMesh.Vertices.Length} indices={airMesh.Indices.Length}");

        var cubitRoot = FindCubitRepositoryRoot();
        var workspaceRoot = cubitRoot is null ? null : Directory.GetParent(cubitRoot)?.FullName;
        var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
        var textureDirectory = projectRoot is null
            ? null
            : Path.Combine(projectRoot, "assets", "minecraft", "textures", "block");
        var blockDirectory = projectRoot is null
            ? null
            : Path.Combine(projectRoot, "assets", "voxel", "blocks", "my_first");
        var sourceTextureDirectory = workspaceRoot is null
            ? null
            : Path.Combine(workspaceRoot, "mc26.1.2", "26.1.2.jar.src", "assets", "minecraft", "textures", "block");
        var plants = new (string Key, string Texture, string Tint)[]
        {
            ("my_first:short_grass", "short_grass", "#48b518"),
            ("my_first:dandelion", "dandelion", "#ffffff"),
            ("my_first:orange_tulip", "orange_tulip", "#ffffff"),
            ("my_first:red_tulip", "red_tulip", "#ffffff"),
            ("my_first:pink_tulip", "pink_tulip", "#ffffff"),
            ("my_first:white_tulip", "white_tulip", "#ffffff"),
            ("my_first:poppy", "poppy", "#ffffff"),
            ("my_first:azure_bluet", "azure_bluet", "#ffffff"),
            ("my_first:oxeye_daisy", "oxeye_daisy", "#ffffff"),
            ("my_first:cornflower", "cornflower", "#ffffff"),
        };
        var filesPresent = textureDirectory is not null && sourceTextureDirectory is not null &&
            plants.All(plant =>
                File.Exists(Path.Combine(textureDirectory, plant.Texture + ".png")) &&
                File.Exists(Path.Combine(sourceTextureDirectory, plant.Texture + ".png")) &&
                string.Equals(
                    Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(Path.Combine(textureDirectory, plant.Texture + ".png")))),
                    Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(Path.Combine(sourceTextureDirectory, plant.Texture + ".png")))),
                    StringComparison.Ordinal));
        Check("项目拥有原版矮草与普通平原小花纹理副本", filesPresent, textureDirectory ?? "missing");

        var definitionsPresent = blockDirectory is not null &&
            plants.All(plant => File.Exists(Path.Combine(blockDirectory, plant.Texture + ".json")));
        Check("项目拥有矮草与普通平原小花方块定义", definitionsPresent, blockDirectory ?? "missing");
        Check(
            "项目不包含本切片未实现的高草内容",
            blockDirectory is not null && !File.Exists(Path.Combine(blockDirectory, "tall_grass.json")) &&
            (textureDirectory is null || !File.Exists(Path.Combine(textureDirectory, "tall_grass.png"))),
            blockDirectory ?? "missing");

        if (projectRoot is not null && Directory.Exists(projectRoot))
        {
            var blockIds = MyFirstCubitProject.ProjectBlockIdMap.Load(projectRoot);
            BlockRegistry.LoadContentPack(Path.Combine(projectRoot, "assets", "voxel"), blockIds.Assignments);
            var registeredPlants = plants.All(plant => BlockRegistry.FindId(plant.Key) is { } id &&
                BlockRegistry.Get(id) is
                {
                    RenderShape: BlockRenderShape.Cross,
                    Solid: false,
                    Opaque: false,
                } definition &&
                string.Equals(definition.TopTexture, plant.Texture, StringComparison.Ordinal) &&
                string.Equals(definition.SideTexture, plant.Texture, StringComparison.Ordinal) &&
                string.Equals(definition.BottomTexture, plant.Texture, StringComparison.Ordinal) &&
                string.Equals(definition.Tint, plant.Tint, StringComparison.Ordinal));
            Check("平原植被使用项目稳定 Key 和无碰撞 Cross 定义", registeredPlants);

            var pass = new MyFirstCubitProject.PlainsVegetationPass(projectRoot);
            var flatContext = CreatePlainsContext(0, 0, WorldType.Flat);
            Check(
                "Flat 世界不生成普通平原植被",
                pass.Generate(in flatContext, 8, 64, 8, 20260825u).IsEmpty);

            var noiseContext = CreatePlainsContext(4, -3, WorldType.Noise);
            var first = pass.Generate(in noiseContext, 72, 64, -40, 20260825u);
            var second = pass.Generate(in noiseContext, 72, 64, -40, 20260825u);
            Check(
                "普通平原植被同种子保持确定性",
                first.Placements.SequenceEqual(second.Placements),
                $"first={first.Placements.Count} second={second.Placements.Count}");
            Check(
                "普通平原植被只写在草方块上方空气格",
                first.Placements.All(placement => placement.Y == 64 &&
                    plants.Any(plant => plant.Key == placement.BlockKey)),
                $"placements={first.Placements.Count}");
            Check(
                "普通平原植被不生成高草",
                first.Placements.All(placement => placement.BlockKey != "my_first:tall_grass"));

            var observedPlants = new HashSet<string>(StringComparer.Ordinal);
            var sampledChunks = Enumerable.Range(-8, 17)
                .SelectMany(chunkZ => Enumerable.Range(-8, 17).Select(chunkX => (X: chunkX, Z: chunkZ)))
                // FLOWER_PLAIN 的 NormalNoise < -0.8 区域，锁住原版郁金香状态分支；
                // 需要区域而非单格，避免原版 RarityFilter(1/32) 恰好滤掉唯一候选。
                .Concat(Enumerable.Range(33, 17)
                    .SelectMany(chunkZ => Enumerable.Range(-81, 17).Select(chunkX => (X: chunkX, Z: chunkZ))));
            foreach (var (chunkX, chunkZ) in sampledChunks)
            {
                var context = CreatePlainsContext(chunkX, chunkZ, WorldType.Noise);
                var generated = pass.Generate(
                    in context,
                    chunkX * Chunk.SizeX + Chunk.SizeX / 2,
                    64,
                    chunkZ * Chunk.SizeZ + Chunk.SizeZ / 2,
                    20260825u);
                foreach (var placement in generated.Placements)
                {
                    observedPlants.Add(placement.BlockKey);
                }
            }

            Check(
                "普通平原采样覆盖矮草、郁金香、普通花与蒲公英分支",
                observedPlants.Contains("my_first:short_grass") &&
                new[] { "my_first:orange_tulip", "my_first:red_tulip", "my_first:pink_tulip", "my_first:white_tulip" }
                    .Any(observedPlants.Contains) &&
                new[] { "my_first:poppy", "my_first:azure_bluet", "my_first:oxeye_daisy", "my_first:cornflower" }
                    .Any(observedPlants.Contains) &&
                observedPlants.Contains("my_first:dandelion"),
                string.Join(',', observedPlants.OrderBy(key => key, StringComparer.Ordinal)));

            using var projectSession = CreateVoxelProjectSession(
                new FakeRenderBackend(),
                20260825u,
                workerCount: 1,
                worldType: WorldType.Noise);
            var projectWorld = RequireVoxelWorld(projectSession.Scene);
            Check(
                "项目场景按原版普通平原顺序注册 Oak、花、矮草",
                projectWorld.World?.FeaturePasses.Select(feature => feature.Id).SequenceEqual(
                    ["project.my_first.oak", "project.my_first.plains_vegetation"]) == true,
                string.Join(',', projectWorld.World?.FeaturePasses.Select(feature => feature.Id) ?? []));

            // 真实 Region 的 ID 语义和内容摘要兼容由 projectblockidcheck 单独进程验证；
            // 本检查先注册 tool:cross，不能让该临时定义参与项目存档摘要比较。
        }
    }
    catch (Exception exception)
    {
        Check("Cross 方块渲染契约", false, exception.ToString());
    }

    Console.WriteLine(failures == 0 ? "plainsvegetationcheck 全部通过" : $"plainsvegetationcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static ChunkGenerationContext CreatePlainsContext(int chunkX, int chunkZ, WorldType worldType) => new(
        chunkX,
        chunkZ,
        20260825u,
        static (_, _, _) => true,
        worldType,
        static (_, _) => 64,
        static (_, y, _) => y == 63
            ? BlockRegistry.GetState(BlockRegistry.Grass)
            : BlockState.Air);
}

static int OverworldCelestialCloudCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var backend = new FakeRenderBackend();
    using var server = new RenderingServer(backend);
    var texture = server.CreateTexture(new TextureData(1, 1, [255, 255, 255, 255]));
    var opaque = new MaterialData(texture);
    var overlay = new MaterialData(texture, MaterialBlendMode.Overlay);
    var alpha = new MaterialData(texture, MaterialBlendMode.AlphaBlend);
    Check("材质默认保持不透明", opaque.BlendMode == MaterialBlendMode.Opaque);
    Check(
        "渲染层声明通用背景阶段",
        Enum.GetNames<MaterialBlendMode>().Contains("Background", StringComparer.Ordinal));
    Check(
        "材质声明通用叠加、背景 alpha 与 alpha 混合",
        overlay.BlendMode == MaterialBlendMode.Overlay &&
        alpha.BlendMode == MaterialBlendMode.AlphaBlend &&
        Enum.GetNames<MaterialBlendMode>().Contains("BackgroundAlphaBlend", StringComparer.Ordinal));

    var material = server.CreateMaterial(overlay);
    var mesh = server.CreateMesh(new MeshData(
        [
            0f, 0f, 0f, 0f, 0f, 1f,
            1f, 0f, 0f, 1f, 0f, 1f,
            0f, 1f, 0f, 0f, 1f, 1f,
        ],
        [0, 1, 2],
        Vector3.Zero,
        Vector3.Zero,
        Vector3.One,
        material,
        new Vector4(0.5f, 0.5f, 0.5f, 0.8f)));
    Check(
        "网格保存通用颜色调制",
        backend.IsMeshActive(mesh) && backend.LastMeshModulation == new Vector4(0.5f, 0.5f, 0.5f, 0.8f));
    server.UpdateMeshModulation(mesh, Vector4.One);
    Check("网格调制可原位更新", backend.LastMeshModulation == Vector4.One);

    var day = new MyFirstCubitProject.OverworldSkyState(6_000);
    var night = new MyFirstCubitProject.OverworldSkyState(18_000);
    var lateNight = new MyFirstCubitProject.OverworldSkyState(21_000);
    var preDawn = new MyFirstCubitProject.OverworldSkyState(23_000);
    Check("星图在夜晚比白天更亮", night.StarBrightness > day.StarBrightness);
    Check(
        "星图角度随游戏时间变化",
        MathF.Abs(day.StarAngleRadians - night.StarAngleRadians) > 0.01f);
    Check(
        "项目 F3 时间使用 24 小时制",
        MyFirstCubitProject.VoxelDebugOverlayState.Format24HourTime(0) == "06:00" &&
        MyFirstCubitProject.VoxelDebugOverlayState.Format24HourTime(6_000) == "12:00" &&
        MyFirstCubitProject.VoxelDebugOverlayState.Format24HourTime(18_000) == "00:00");
    var sevenOClock = new MyFirstCubitProject.OverworldSkyState(1_000);
    var elevenOClock = new MyFirstCubitProject.OverworldSkyState(5_000);
    Check(
        "太阳仰角与 24 小时制时间保持 MC 时间线同步",
        MyFirstCubitProject.VoxelDebugOverlayState.Format24HourTime(sevenOClock.DayTime) == "07:00" &&
        MyFirstCubitProject.VoxelDebugOverlayState.Format24HourTime(elevenOClock.DayTime) == "11:00" &&
        MathF.Abs(sevenOClock.SunAltitudeDegrees - 27.55f) < 0.15f &&
        MathF.Abs(elevenOClock.SunAltitudeDegrees - 79.49f) < 0.15f,
        $"07:00 altitude={sevenOClock.SunAltitudeDegrees:F2} 11:00 altitude={elevenOClock.SunAltitudeDegrees:F2}");
    Check(
        "太阳方位诊断可用于区分轨道与投影观感",
        float.IsFinite(sevenOClock.SunAzimuthDegrees) &&
        float.IsFinite(elevenOClock.SunAzimuthDegrees));
    Check(
        "原版时间轨道在凌晨三点保持夜间",
        lateNight.SkyColorFactor < 0.001f && lateNight.SkyLightFactor <= 0.24f,
        $"sky={lateNight.SkyColorFactor:F3} light={lateNight.SkyLightFactor:F3}");
    Check(
        "原版时间轨道在日出前不提前达到白天亮度",
        preDawn.SkyColorFactor < 0.5f && preDawn.SkyLightFactor < 0.5f,
        $"sky={preDawn.SkyColorFactor:F3} light={preDawn.SkyLightFactor:F3}");
    var sunriseColorProperty = typeof(MyFirstCubitProject.OverworldSkyState).GetProperty(
        "SunriseSunsetColor",
        BindingFlags.Public | BindingFlags.Instance);
    var sunriseColor = sunriseColorProperty?.GetValue(new MyFirstCubitProject.OverworldSkyState(0));
    var noonSunriseColor = sunriseColorProperty?.GetValue(new MyFirstCubitProject.OverworldSkyState(6_000));
    Check(
        "项目时间线在日出日落提供颜色且午间透明",
        sunriseColor is Vector4 dawn && dawn.W > 0.001f &&
        noonSunriseColor is Vector4 noonColor && noonColor.W <= 0.001f);
    var menuState = new MyFirstCubitProject.SingleplayerMenuState();
    menuState.ShowWorldSelection();
    menuState.BeginOpeningWorld();
    menuState.BeginPlaying();
    menuState.TogglePause();
    Check("暂停时保留世界视图状态", menuState.IsWorldViewVisible && !menuState.IsGameplayActive);
    var noonCelestial = MyFirstCubitProject.OverworldSkyNode.CreateCelestialTransform(
        Vector3.Zero,
        0f,
        30f,
        100f);
    Check(
        "正午太阳方向平行世界上方向时天体矩阵仍保持有限",
        IsFiniteMatrix(noonCelestial),
        noonCelestial.ToString());

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var skyNodePath = workspaceRoot is null
        ? string.Empty
        : Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "OverworldSkyNode.cs");
    var vulkanContextPath = repositoryRoot is null
        ? string.Empty
        : Path.Combine(repositoryRoot, "src", "Cubit.Core", "Rendering", "VulkanContext.cs");
    var skySource = File.Exists(skyNodePath) ? File.ReadAllText(skyNodePath) : string.Empty;
    var vulkanSource = File.Exists(vulkanContextPath) ? File.ReadAllText(vulkanContextPath) : string.Empty;
    Check(
        "背景阶段在不测试和不写入深度时先于地形提交",
        vulkanSource.Contains("MaterialBlendMode.Background => _backgroundPipeline", StringComparison.Ordinal) &&
        vulkanSource.Contains("MaterialBlendMode.BackgroundAlphaBlend => _backgroundAlphaBlendPipeline", StringComparison.Ordinal) &&
        vulkanSource.Contains("MaterialBlendMode.Background,\n                     MaterialBlendMode.BackgroundAlphaBlend,\n                     MaterialBlendMode.Opaque", StringComparison.Ordinal) &&
        vulkanSource.Contains("DepthTestEnable = blendMode is not (MaterialBlendMode.Background or MaterialBlendMode.BackgroundAlphaBlend)", StringComparison.Ordinal) &&
        vulkanSource.Contains("DepthWriteEnable = blendMode == MaterialBlendMode.Opaque", StringComparison.Ordinal),
        vulkanContextPath);
    Check(
        "项目天体使用背景材质并在地形前提交",
        skySource.Contains("MaterialBlendMode.Background", StringComparison.Ordinal) &&
        !skySource.Contains("IsCelestialAboveHorizon", StringComparison.Ordinal),
        skyNodePath);
    Check(
        "项目天空以原版单一逐顶点透明扇面表现朝晚霞",
        skySource.Contains("CreateSunriseSunsetFanMesh", StringComparison.Ordinal) &&
        skySource.Contains("SunriseSunsetColor", StringComparison.Ordinal),
        skyNodePath);
    Check(
        "项目朝晚霞在地形之前使用标准 alpha 混合",
        skySource.Contains(
            "var sunriseSunsetMaterial = Server.CreateMaterial(new MaterialData(effectTexture, MaterialBlendMode.BackgroundAlphaBlend));",
            StringComparison.Ordinal),
        skyNodePath);
    var sunriseFanMeshFactory = typeof(MyFirstCubitProject.OverworldSkyNode).GetMethod(
        "CreateSunriseSunsetFanMesh",
        BindingFlags.NonPublic | BindingFlags.Static);
    var sunriseFanMesh = sunriseFanMeshFactory?.Invoke(null, [RID.None]) as MeshData;
    var sunriseFanStride = typeof(MeshData).GetProperty("VertexStride", BindingFlags.Public | BindingFlags.Instance)
        ?.GetValue(sunriseFanMesh);
    Check(
        "朝晚霞是地形之前的单个顶点透明背景扇面",
        Enum.GetNames<MaterialBlendMode>().Contains("BackgroundAlphaBlend", StringComparer.Ordinal) &&
        skySource.Contains("MaterialBlendMode.BackgroundAlphaBlend", StringComparison.Ordinal) &&
        sunriseFanMesh is { Vertices.Length: 180, Indices.Length: 48 } &&
        sunriseFanStride is 10 &&
        MathF.Abs(sunriseFanMesh.Vertices[9] - 1f) < 0.0001f &&
        MathF.Abs(sunriseFanMesh.Vertices[19]) < 0.0001f,
        $"mesh={sunriseFanMesh?.Vertices.Length}/{sunriseFanMesh?.Indices.Length} stride={sunriseFanStride}");
    Check(
        "项目天体网格沿用原版 XZ 平面与月相 UV",
        skySource.Contains("-1f, 0f, -1f", StringComparison.Ordinal) &&
        skySource.Contains("CreateQuadMesh(material, moonUv: true)", StringComparison.Ordinal) &&
        skySource.Contains("Matrix4x4.CreateScale(size)", StringComparison.Ordinal),
        skyNodePath);
    Check(
        "项目天体使用 MC 固定天空姿态而非相机 billboard",
        skySource.Contains("CreateCelestialTransform", StringComparison.Ordinal) &&
        !skySource.Contains("CreateStableBillboardTransform", StringComparison.Ordinal) &&
        skySource.Contains("CreateRotationY(-MathF.PI * 0.5f)", StringComparison.Ordinal),
        skyNodePath);
    var celestialTransformMethod = typeof(MyFirstCubitProject.OverworldSkyNode).GetMethod(
        "CreateCelestialTransform",
        BindingFlags.Public | BindingFlags.Static);
    var quarterOrbitTransform = celestialTransformMethod?.Invoke(
        null,
        [Vector3.Zero, MathF.PI * 0.5f, 30f, 100f]);
    var quarterOrbitPosition = quarterOrbitTransform is Matrix4x4 quarterOrbitMatrix
        ? Vector3.Transform(Vector3.Zero, quarterOrbitMatrix)
        : new Vector3(float.NaN);
    Check(
        "天体四分之一轨道沿水平面移动",
        quarterOrbitTransform is Matrix4x4 &&
        MathF.Abs(quarterOrbitPosition.X) > 90f &&
        MathF.Abs(quarterOrbitPosition.Y) < 1f &&
        MathF.Abs(quarterOrbitPosition.Z) < 1f,
        $"position={quarterOrbitPosition}");
    var quarterOrbitBasis = quarterOrbitTransform is Matrix4x4 quarterMatrix
        ? (Vector3.TransformNormal(Vector3.UnitX, quarterMatrix),
            Vector3.TransformNormal(Vector3.UnitZ, quarterMatrix))
        : (new Vector3(float.NaN), new Vector3(float.NaN));
    Check(
        "天体四边形保持 MC 正方形比例",
        MathF.Abs(quarterOrbitBasis.Item1.Length() - 30f) < 0.001f &&
        MathF.Abs(quarterOrbitBasis.Item2.Length() - 30f) < 0.001f &&
        MathF.Abs(Vector3.Dot(quarterOrbitBasis.Item1, quarterOrbitBasis.Item2)) < 0.001f,
        $"x={quarterOrbitBasis.Item1} z={quarterOrbitBasis.Item2}");
    var sunriseHorizonState = new MyFirstCubitProject.OverworldSkyState(101);
    var sunriseFanTransformMethod = typeof(MyFirstCubitProject.OverworldSkyNode).GetMethod(
        "CreateSunriseSunsetTransform",
        BindingFlags.NonPublic | BindingFlags.Static);
    var sunriseFanTransform = sunriseFanTransformMethod?.Invoke(
        null,
        [Vector3.Zero, sunriseHorizonState.SunAngleRadians, sunriseHorizonState.SunriseSunsetColor.W]);
    var sunriseFanCenter = sunriseFanTransform is Matrix4x4 sunriseMatrix
        ? Vector3.Transform(new Vector3(0f, 100f, 0f), sunriseMatrix)
        : new Vector3(float.NaN);
    var sunriseCenter = Vector3.Transform(
        Vector3.Zero,
        MyFirstCubitProject.OverworldSkyNode.CreateCelestialTransform(
            Vector3.Zero,
            sunriseHorizonState.SunAngleRadians,
            1f,
            100f));
    var sunriseFanHorizontal = Vector2.Normalize(new Vector2(sunriseFanCenter.X, sunriseFanCenter.Z));
    var sunriseHorizontal = Vector2.Normalize(new Vector2(sunriseCenter.X, sunriseCenter.Z));
    var sunriseAlignment = Vector2.Dot(sunriseFanHorizontal, sunriseHorizontal);
    Check(
        "日出时朝晚霞扇面中心与太阳保持同一水平朝向",
        float.IsFinite(sunriseAlignment) && sunriseAlignment > 0.99f,
        $"fan={sunriseFanCenter} sun={sunriseCenter} dot={sunriseAlignment:F4}");

    var cloudPixels = new byte[3 * 3 * 4];
    cloudPixels[(1 * 3 + 1) * 4 + 3] = 255;
    cloudPixels[(1 * 3 + 0) * 4 + 3] = 9;
    var cloudMap = MyFirstCubitProject.OverworldCloudMap.FromRgba8(3, 3, cloudPixels);
    Check(
        "云图按原版 alpha<10 识别空格并重复",
        cloudMap.IsFilledWrapped(1, 1) && !cloudMap.IsFilledWrapped(0, 1) && cloudMap.IsFilledWrapped(4, 1));
    var fancyCloud = MyFirstCubitProject.OverworldCloudMesh.Build(
        cloudMap,
        1,
        1,
        1,
        MyFirstCubitProject.CloudRelativeCameraPos.Below,
        fancy: true);
    var flatCloud = MyFirstCubitProject.OverworldCloudMesh.Build(
        cloudMap,
        1,
        1,
        1,
        MyFirstCubitProject.CloudRelativeCameraPos.Below,
        fancy: false);
    Check(
        "精美云生成顶底和暴露侧面",
        fancyCloud.QuadCount > flatCloud.QuadCount && fancyCloud.Indices.Length > flatCloud.Indices.Length,
        $"fancy={fancyCloud.QuadCount} flat={flatCloud.QuadCount}");
    Check("平面云只生成底面", flatCloud.QuadCount == 1, $"quads={flatCloud.QuadCount}");
    Check(
        "云单元保持原版 12 格宽和 4 格厚",
        MathF.Abs(fancyCloud.BoundsMax.Y - fancyCloud.BoundsMin.Y - MyFirstCubitProject.OverworldCloudMap.Thickness) < 0.0001f &&
        MathF.Abs(flatCloud.BoundsMax.X - flatCloud.BoundsMin.X - MyFirstCubitProject.OverworldCloudMap.CellSize) < 0.0001f,
        $"fancyBounds={fancyCloud.BoundsMin}/{fancyCloud.BoundsMax} flatBounds={flatCloud.BoundsMin}/{flatCloud.BoundsMax}");

    var projectRoot = workspaceRoot is null ? string.Empty : Path.Combine(workspaceRoot, "我的第一个cubit项目");
    var cloudPath = Path.Combine(projectRoot, "assets", "minecraft", "textures", "environment", "clouds.png");
    var sourceCloudPath = workspaceRoot is null
        ? string.Empty
        : Path.Combine(workspaceRoot, "mc26.1.2", "26.1.2.jar.src", "assets", "minecraft", "textures", "environment", "clouds.png");
    var gameplayPath = Path.Combine(projectRoot, "scenes", "gameplay.cscene");
    var gameplaySource = File.Exists(gameplayPath) ? File.ReadAllText(gameplayPath) : string.Empty;
    Check(
        "项目天体采用原版距离与尺寸比例",
        gameplaySource.Contains("\"CelestialDistance\": 100", StringComparison.Ordinal) &&
        gameplaySource.Contains("\"SunSize\": 30", StringComparison.Ordinal) &&
        gameplaySource.Contains("\"MoonSize\": 20", StringComparison.Ordinal) &&
        skySource.Contains("axisX * size", StringComparison.Ordinal) &&
        !skySource.Contains("size * 5f", StringComparison.Ordinal),
        gameplayPath);
    Check(
        "项目拥有原版云格资产",
        IsPngWithDimensions(cloudPath, 256, 256) &&
        Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(cloudPath))) ==
            Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(sourceCloudPath))),
        cloudPath);
    Check(
        "项目 gameplay 作者化云节点",
        gameplaySource.Contains("MyFirstCubitProject.OverworldCloudNode", StringComparison.Ordinal),
        gameplayPath);
    Check(
        "项目程序集包含 OverworldCloudNode",
        typeof(MyFirstCubitProject.OverworldCloudNode).IsSubclassOf(typeof(Node)));

    Console.WriteLine(failures == 0
        ? "overworldcelestialcloudcheck 全部通过"
        : $"overworldcelestialcloudcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static bool IsFiniteMatrix(Matrix4x4 value) =>
    float.IsFinite(value.M11) && float.IsFinite(value.M12) && float.IsFinite(value.M13) && float.IsFinite(value.M14) &&
    float.IsFinite(value.M21) && float.IsFinite(value.M22) && float.IsFinite(value.M23) && float.IsFinite(value.M24) &&
    float.IsFinite(value.M31) && float.IsFinite(value.M32) && float.IsFinite(value.M33) && float.IsFinite(value.M34) &&
    float.IsFinite(value.M41) && float.IsFinite(value.M42) && float.IsFinite(value.M43) && float.IsFinite(value.M44);

static int OverworldSkyCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var sunrise = new MyFirstCubitProject.OverworldSkyState(0);
    var noon = new MyFirstCubitProject.OverworldSkyState(6_000);
    var midnight = new MyFirstCubitProject.OverworldSkyState(18_000);
    var twilight = new MyFirstCubitProject.OverworldSkyState(12_000);
    var nextMoon = new MyFirstCubitProject.OverworldSkyState(
        MyFirstCubitProject.OverworldSkyState.DayLengthTicks);

    Check(
        "主世界天空使用原版 24000 tick 昼夜周期",
        MyFirstCubitProject.OverworldSkyState.DayLengthTicks == 24_000 &&
        sunrise.DayTime == 0 && noon.DayTime == 6_000 && midnight.DayTime == 18_000);
    Check(
        "天空时钟在完整世界日后推进月相而不改变日内时间",
        nextMoon.DayTime == sunrise.DayTime && nextMoon.MoonPhase == 1);
    Check(
        "天空状态二进制往返保持游戏 tick",
        MyFirstCubitProject.OverworldSkyState.Decode(sunrise.Encode()) == sunrise &&
        MyFirstCubitProject.OverworldSkyState.Decode(midnight.Encode()) == midnight);
    Check(
        "正午比午夜更明亮且过渡时段保持可见",
        noon.SkyColor.LengthSquared() > midnight.SkyColor.LengthSquared() &&
        twilight.SkyColor.LengthSquared() > midnight.SkyColor.LengthSquared(),
        $"noon={noon.SkyColor} midnight={midnight.SkyColor} twilight={twilight.SkyColor} " +
        $"twilightAngle={twilight.SunAngleRadians:F4} twilightDirection={twilight.SunDirection}");

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
    var gameplayScene = projectRoot is null ? string.Empty : Path.Combine(projectRoot, "scenes", "gameplay.cscene");
    var skyAssetDirectory = projectRoot is null
        ? string.Empty
        : Path.Combine(projectRoot, "assets", "minecraft", "textures", "environment", "celestial");
    var sourceAssetDirectory = workspaceRoot is null
        ? string.Empty
        : Path.Combine(workspaceRoot, "mc26.1.2", "26.1.2.jar.src", "assets", "minecraft", "textures", "environment", "celestial");
    var requiredMoonFiles = new[]
    {
        "new_moon.png", "waxing_crescent.png", "first_quarter.png", "waxing_gibbous.png",
        "full_moon.png", "waning_gibbous.png", "third_quarter.png", "waning_crescent.png",
    };
    Check(
        "gameplay 场景作者化 OverworldSky 节点",
        File.Exists(gameplayScene) && File.ReadAllText(gameplayScene).Contains("MyFirstCubitProject.OverworldSkyNode", StringComparison.Ordinal),
        gameplayScene);
    Check(
        "太阳与八个月相仅由项目 assets 管理",
        File.Exists(Path.Combine(skyAssetDirectory, "sun.png")) &&
        requiredMoonFiles.All(file => File.Exists(Path.Combine(skyAssetDirectory, "moon", file))) &&
        !Directory.Exists(Path.Combine(repositoryRoot ?? string.Empty, "src", "Cubit.Voxel", "Textures", "environment")) &&
        File.Exists(Path.Combine(sourceAssetDirectory, "sun.png")),
        skyAssetDirectory);

    try
    {
        using var session = CreateVoxelProjectSession(
            new FakeRenderBackend(),
            20260825u,
            workerCount: 1,
            worldType: WorldType.Flat);
        var repository = new MyFirstCubitProject.WorldRepository(session.Scene.Runtime.Project.RootDirectory);
        var summary = repository.Create("天空时钟验收", 20260825u, WorldType.Flat);
        var expected = new MyFirstCubitProject.OverworldSkyState(3L * MyFirstCubitProject.OverworldSkyState.DayLengthTicks + 12_345L);
        repository.SaveSkyState(summary, expected);
        using var opened = repository.Open(summary);
        Check(
            "项目级 sky.cubit.bin 在重新打开世界后恢复游戏时间和月相",
            opened.SkyState == expected && opened.SkyState.MoonPhase == 3,
            $"time={opened.SkyState.GameTime} phase={opened.SkyState.MoonPhase}");
    }
    catch (Exception exception)
    {
        Check("项目级 sky.cubit.bin 在重新打开世界后恢复游戏时间和月相", false, exception.Message);
    }

    Console.WriteLine(failures == 0 ? "overworldskycheck 全部通过" : $"overworldskycheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int OakFeatureCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    Assembly? voxelAssembly = null;
    try
    {
        voxelAssembly = Assembly.Load("Cubit.Voxel");
        Check("Cubit.Voxel assembly loadable", true, voxelAssembly.FullName ?? "");
    }
    catch (Exception exception)
    {
        Check("Cubit.Voxel assembly loadable", false, exception.Message);
    }

    var requiredTypes = new[]
    {
        "Cubit.Voxel.World.ChunkGenerationContext",
        "Cubit.Voxel.World.FeaturePlacementBuffer",
        "Cubit.Voxel.World.TreeFeatureRecipe",
        "Cubit.Voxel.World.TrunkPlacer",
        "Cubit.Voxel.World.FoliagePlacer",
        "Cubit.Voxel.World.StraightTrunkPlacer",
        "Cubit.Voxel.World.BlobFoliagePlacer",
        "Cubit.Voxel.World.IVoxelFeaturePass",
    };
    foreach (var typeName in requiredTypes)
    {
        Check($"TreeFeature 通用类型存在: {typeName}", voxelAssembly?.GetType(typeName) is not null);
    }

    Check(
        "TreeFeature 通用类型不引用首个项目程序集",
        voxelAssembly?.GetReferencedAssemblies().All(reference =>
            !string.Equals(reference.Name, "MyFirstCubitProject", StringComparison.Ordinal)) == true,
        string.Join(',', voxelAssembly?.GetReferencedAssemblies().Select(reference => reference.Name) ?? []));

    try
    {
        var recipe = new TreeFeatureRecipe(
            BlockRegistry.GetKey(BlockRegistry.Wood),
            BlockRegistry.GetKey(BlockRegistry.Leaves),
            new StraightTrunkPlacer(4, 2, 0),
            new BlobFoliagePlacer(2, 0, 3),
            featureWidth: 5,
            featureHeight: 8,
            featureDepth: 5);
        var context = new ChunkGenerationContext(0, 0, 20260824u);
        var first = TreeFeaturePlacement.Place(recipe, in context, 3, 20, 5, 20260824u);
        Check(
            "TreeFeature 生成不可变放置缓冲",
            !first.IsEmpty && first.Placements.All(placement =>
                placement.BlockKey is "cubit.voxel:wood" or "cubit.voxel:leaves"),
            $"placements={first.Placements.Count}");
        Check(
            "TreeFeature 放置结果按世界坐标稳定排序",
            first.Placements.SequenceEqual(first.Placements.OrderBy(p => p.X).ThenBy(p => p.Y).ThenBy(p => p.Z)
                .ThenBy(p => p.BlockKey, StringComparer.Ordinal)),
            first.Placements.Count == 0 ? "empty" : $"first={first.Placements[0]}");

        var second = TreeFeaturePlacement.Place(recipe, in context, 3, 20, 5, 20260824u);
        Check("TreeFeature 相同种子和原点保持确定性", first.Placements.SequenceEqual(second.Placements));

        var trunkPlacements = first.Placements
            .Where(placement => placement.BlockKey == BlockRegistry.GetKey(BlockRegistry.Wood))
            .ToArray();
        var foliagePlacements = first.Placements
            .Where(placement => placement.BlockKey == BlockRegistry.GetKey(BlockRegistry.Leaves))
            .ToArray();
        var highestTrunkY = trunkPlacements.Length == 0 ? int.MinValue : trunkPlacements.Max(placement => placement.Y);
        Check(
            "StraightTrunkPlacer 的树叶附着点位于原版最后一段树干上方",
            foliagePlacements.Length > 0 && foliagePlacements.Max(placement => placement.Y) == highestTrunkY + 1,
            $"trunkTop={highestTrunkY} leafTop={(foliagePlacements.Length == 0 ? int.MinValue : foliagePlacements.Max(placement => placement.Y))}");
        Check(
            "BlobFoliagePlacer 按原版 height=3 生成四层叶冠",
            foliagePlacements.Select(placement => placement.Y).Distinct().Count() == 4,
            string.Join(',', foliagePlacements.Select(placement => placement.Y).Distinct().OrderBy(y => y)));

        var blockedContext = new ChunkGenerationContext(0, 0, 20260824u, static (_, _, _) => false);
        var blocked = TreeFeaturePlacement.Place(recipe, in blockedContext, 3, 20, 5, 20260824u);
        Check("TreeFeature 空间不足时整棵树原子放弃", blocked.IsEmpty);

        var builder = FeaturePlacementBuffer.CreateBuilder(context);
        Exception? workerError = null;
        var worker = new Thread(() => workerError = CaptureException(() => builder.Add(0, 0, 0, "cubit.voxel:wood")));
        worker.Start();
        worker.Join();
        Check("FeaturePlacementBuffer 拒绝跨线程写入", workerError is InvalidOperationException);
        _ = builder.Build();
    }
    catch (Exception exception)
    {
        Check("TreeFeature 生成契约运行时自检", false, exception.ToString());
    }

    var projectRoot = FindCubitRepositoryRoot() is { } root
        ? Path.Combine(Directory.GetParent(root)?.FullName ?? string.Empty, "我的第一个cubit项目")
        : null;
    var workspaceRoot = projectRoot is null ? null : Directory.GetParent(projectRoot)?.FullName;
    var oakRecipePath = projectRoot is null ? null : Path.Combine(projectRoot, "assets", "worldgen", "features", "oak.json");
    var oakBlockDirectory = projectRoot is null ? null : Path.Combine(projectRoot, "assets", "voxel", "blocks", "my_first");
    var oakTextureDirectory = projectRoot is null ? null : Path.Combine(projectRoot, "assets", "minecraft", "textures", "block");
    Check("项目拥有 Oak 世界生成配方资产", oakRecipePath is not null && File.Exists(oakRecipePath), oakRecipePath ?? "missing");
    Check(
        "项目拥有 Oak 方块定义资产",
        oakBlockDirectory is not null &&
        File.Exists(Path.Combine(oakBlockDirectory, "oak_log.json")) &&
        File.Exists(Path.Combine(oakBlockDirectory, "oak_leaves.json")),
        oakBlockDirectory ?? "missing");
    Check(
        "项目拥有 Oak 纹理资产",
        oakTextureDirectory is not null &&
        File.Exists(Path.Combine(oakTextureDirectory, "oak_log.png")) &&
        File.Exists(Path.Combine(oakTextureDirectory, "oak_log_top.png")) &&
        File.Exists(Path.Combine(oakTextureDirectory, "oak_leaves.png")),
        oakTextureDirectory ?? "missing");
    var originalOakLeavesPath = workspaceRoot is null
        ? null
        : Path.Combine(workspaceRoot, "mc26.1.2", "26.1.2.jar.src", "assets", "minecraft", "textures", "block", "oak_leaves.png");
    var paleOakLeavesPath = workspaceRoot is null
        ? null
        : Path.Combine(workspaceRoot, "mc26.1.2", "26.1.2.jar.src", "assets", "minecraft", "textures", "block", "pale_oak_leaves.png");
    var projectOakLeavesPath = oakTextureDirectory is null ? null : Path.Combine(oakTextureDirectory, "oak_leaves.png");
    var projectOakLeavesHash = projectOakLeavesPath is not null && File.Exists(projectOakLeavesPath)
        ? Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(projectOakLeavesPath)))
        : string.Empty;
    var originalOakLeavesHash = originalOakLeavesPath is not null && File.Exists(originalOakLeavesPath)
        ? Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(originalOakLeavesPath)))
        : string.Empty;
    var paleOakLeavesHash = paleOakLeavesPath is not null && File.Exists(paleOakLeavesPath)
        ? Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(paleOakLeavesPath)))
        : string.Empty;
    Check(
        "项目 oak_leaves 资产等于原版普通橡树叶且不等于苍白橡树叶",
        projectOakLeavesHash.Length > 0 &&
        string.Equals(projectOakLeavesHash, originalOakLeavesHash, StringComparison.Ordinal) &&
        !string.Equals(projectOakLeavesHash, paleOakLeavesHash, StringComparison.Ordinal),
        $"project={projectOakLeavesHash} oak={originalOakLeavesHash} pale={paleOakLeavesHash}");
    var projectSource = projectRoot is null || !Directory.Exists(Path.Combine(projectRoot, "src"))
        ? string.Empty
        : string.Join("\n", Directory.GetFiles(Path.Combine(projectRoot, "src"), "*.cs", SearchOption.AllDirectories)
            .Select(File.ReadAllText));
    Check(
        "项目提供 OakTreeFeature 和 OakWorldgenPass",
        projectSource.Contains("class OakTreeFeature", StringComparison.Ordinal) &&
        projectSource.Contains("class OakWorldgenPass", StringComparison.Ordinal),
        projectRoot ?? "missing");

    if (projectRoot is not null && Directory.Exists(projectRoot))
    {
        try
        {
            var blockIds = MyFirstCubitProject.ProjectBlockIdMap.Load(projectRoot);
            BlockRegistry.LoadContentPack(Path.Combine(projectRoot, "assets", "voxel"), blockIds.Assignments);
            var oakFeature = MyFirstCubitProject.OakTreeFeature.Load(projectRoot);
            var oakLeavesId = BlockRegistry.GetId("my_first:oak_leaves");
            var oakLeaves = BlockRegistry.Get(oakLeavesId);
            var tintProperty = typeof(BlockDef).GetProperty("Tint");
            var oakTint = tintProperty?.GetValue(oakLeaves) as string;
            Check(
                "项目普通橡树叶作者化原版默认 foliage 色 #48B518",
                string.Equals(oakTint, "#48b518", StringComparison.OrdinalIgnoreCase),
                oakTint ?? "missing");
            TextureAtlas.ConfigureProjectTextureDirectory(Path.Combine(projectRoot, "assets", "minecraft", "textures", "block"));
            var oakTile = TextureAtlas.GetTile(oakLeavesId, 0);
            var (oakU0, oakV0, oakU1, oakV1) = TextureAtlas.GetUv(oakTile);
            var oakAtlas = TextureAtlas.AtlasData;
            var oakAtlasWidth = TextureAtlas.AtlasWidth;
            var oakAtlasHeight = TextureAtlas.AtlasHeight;
            long oakRed = 0;
            long oakGreen = 0;
            long oakBlue = 0;
            var oakPixels = 0;
            for (var y = (int)(oakV0 * oakAtlasHeight); y < (int)(oakV1 * oakAtlasHeight); y++)
            {
                for (var x = (int)(oakU0 * oakAtlasWidth); x < (int)(oakU1 * oakAtlasWidth); x++)
                {
                    var offset = (y * oakAtlasWidth + x) * 4;
                    if (oakAtlas[offset + 3] == 0)
                    {
                        continue;
                    }

                    oakRed += oakAtlas[offset];
                    oakGreen += oakAtlas[offset + 1];
                    oakBlue += oakAtlas[offset + 2];
                    oakPixels++;
                }
            }

            var oakMeanRed = oakPixels == 0 ? 0d : oakRed / (double)oakPixels;
            var oakMeanGreen = oakPixels == 0 ? 0d : oakGreen / (double)oakPixels;
            var oakMeanBlue = oakPixels == 0 ? 0d : oakBlue / (double)oakPixels;
            Check(
                "普通橡树叶图集实际应用 foliage 色调而非灰度苍白纹理",
                oakPixels > 0 && oakMeanGreen > oakMeanRed * 2d && oakMeanGreen > oakMeanBlue * 4d,
                $"tile={oakTile} rgb={oakMeanRed:F1}/{oakMeanGreen:F1}/{oakMeanBlue:F1}");
            Check(
                "Oak 平原放置参数对齐原版 countExtra(0, 0.05, 1)",
                oakFeature.Placement.BaseCount == 0 &&
                MathF.Abs(oakFeature.Placement.ExtraChance - 0.05f) <= 0.00001f &&
                oakFeature.Placement.ExtraCount == 1,
                $"base={oakFeature.Placement.BaseCount} chance={oakFeature.Placement.ExtraChance:F3} extra={oakFeature.Placement.ExtraCount}");
            var oakPass = new MyFirstCubitProject.OakWorldgenPass(projectRoot);
            var generatedOaks = new List<(int ChunkX, int ChunkZ, FeaturePlacementBuffer Buffer)>();
            for (var chunkZ = -16; chunkZ <= 16; chunkZ++)
            {
                for (var chunkX = -16; chunkX <= 16; chunkX++)
                {
                    var context = new ChunkGenerationContext(
                        chunkX,
                        chunkZ,
                        20260824u,
                        static (_, _, _) => true,
                        WorldType.Noise,
                        static (_, _) => 64,
                        static (_, _, _) => BlockRegistry.GetState(BlockRegistry.Grass));
                    var buffer = oakPass.Generate(
                        in context,
                        chunkX * Chunk.SizeX + Chunk.SizeX / 2,
                        32,
                        chunkZ * Chunk.SizeZ + Chunk.SizeZ / 2,
                        20260824u);
                    if (!buffer.IsEmpty)
                    {
                        generatedOaks.Add((chunkX, chunkZ, buffer));
                    }
                }
            }

            var oakTrunks = generatedOaks
                .SelectMany(entry => entry.Buffer.Placements
                    .Where(placement => placement.BlockKey == "my_first:oak_log")
                    .Select(placement => (entry.ChunkX, entry.ChunkZ, Placement: placement)))
                .ToArray();
            Check(
                "OakWorldgenPass 使用高度图提供的落点而非区块中心高度",
                oakTrunks.Length > 0 && oakTrunks.All(entry => entry.Placement.Y >= 64),
                $"trees={generatedOaks.Count} minY={(oakTrunks.Length == 0 ? "missing" : oakTrunks.Min(entry => entry.Placement.Y))}");
            Check(
                "OakWorldgenPass 在区块内随机散布而非固定中心",
                oakTrunks.Any(entry => entry.Placement.X != entry.ChunkX * Chunk.SizeX + Chunk.SizeX / 2 ||
                                       entry.Placement.Z != entry.ChunkZ * Chunk.SizeZ + Chunk.SizeZ / 2),
                $"trees={generatedOaks.Count} trunks={oakTrunks.Length}");

            var noiseWorld = new VoxelWorld(20260824u, WorldType.Noise, featurePasses: [oakPass]);
            var sampleOakChunk = generatedOaks.FirstOrDefault();
            if (!sampleOakChunk.Buffer.IsEmpty)
            {
                noiseWorld.GenerateChunkAt(sampleOakChunk.ChunkX, sampleOakChunk.ChunkZ);
            }

            var generatedChunk = sampleOakChunk.Buffer.IsEmpty
                ? null
                : noiseWorld.Store.GetChunk(sampleOakChunk.ChunkX, sampleOakChunk.ChunkZ);
            Check(
                "OakWorldgenPass 接入 Noise 世界生成流水线",
                generatedChunk is not null && CountBlock(generatedChunk, BlockRegistry.GetId("my_first:oak_log")) > 0,
                generatedChunk is null ? "no candidate chunk" : $"logs={CountBlock(generatedChunk, BlockRegistry.GetId("my_first:oak_log"))}");

            var flatWorld = new VoxelWorld(20260824u, WorldType.Flat, featurePasses: [oakPass]);
            flatWorld.GenerateChunkAt(0, 0);
            var flatChunk = flatWorld.Store.GetChunk(0, 0);
            Check(
                "OakWorldgenPass 在 Flat 世界不写入 Oak",
                flatChunk is not null && CountBlock(flatChunk, BlockRegistry.GetId("my_first:oak_log")) == 0,
                flatChunk is null ? "missing" : "logs=0");

            using var projectSession = CreateVoxelProjectSession(
                new FakeRenderBackend(),
                20260824u,
                workerCount: 1,
                worldType: WorldType.Noise);
            var projectMenu = projectSession.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
            var projectWorld = RequireVoxelWorld(projectSession.Scene);
            var createdProjectWorld = projectMenu?.CreateWorld("Oak Runtime Check", "20260824", WorldType.Noise) == true;
            var openingDeadline = Stopwatch.StartNew();
            while (projectMenu?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.OpeningWorld &&
                   openingDeadline.Elapsed < TimeSpan.FromSeconds(10))
            {
                projectSession.Scene.ProcessFrame(1d / 60d);
                Thread.Sleep(1);
            }

            Check(
                "项目实际打开存档后仍注入 OakWorldgenPass",
                createdProjectWorld &&
                projectMenu?.State.IsGameplayActive == true &&
                projectWorld.World?.FeaturePasses.Count >= 1 &&
                projectWorld.World.FeaturePasses[0] is MyFirstCubitProject.OakWorldgenPass,
                $"created={createdProjectWorld} screen={projectMenu?.State.Screen} " +
                $"passes={projectWorld.World?.FeaturePasses.Count ?? 0}");
        }
        catch (Exception exception)
        {
            Check("OakWorldgenPass 接入 VoxelWorld 生成流水线", false, exception.ToString());
        }
    }

    Console.WriteLine(failures == 0 ? "oakfeaturecheck 全部通过" : $"oakfeaturecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static int CountBlock(Chunk chunk, ushort blockId)
    {
        var count = 0;
        for (var x = 0; x < Chunk.SizeX; x++)
        {
            for (var z = 0; z < Chunk.SizeZ; z++)
            {
                for (var y = Chunk.MinY; y < Chunk.MaxYExclusive; y++)
                {
                    if (chunk.GetBlock(x, y, z).Id == blockId)
                    {
                        count++;
                    }
                }
            }
        }

        return count;
    }

}

static int OakCrossChunkCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    try
    {
        var pass = new ToolCrossChunkFeaturePass();
        var world = new VoxelWorld(20260824u, WorldType.Noise, featurePasses: [pass]);
        world.GenerateChunkAt(0, 0);
        var beforeTarget = world.Store.GetChunk(1, 0);
        Check("跨区块 Oak 生成不提前创建目标区块", beforeTarget is null);
        world.GenerateChunkAt(1, 0);
        var target = world.Store.GetChunk(1, 0);
        var oak = BlockRegistry.GetState(BlockRegistry.Wood);
        var applied = target is not null && target.GetBlock(0, 300, 8) == oak;
        Check("目标区块加载后应用跨区块树干写入", applied, target is null ? "missing" : target.GetBlock(0, 300, 8).ToString());
        var dirty = world.ConsumeFeatureMeshDirtyChunkKeys();
        Check(
            "跨区块写入只使树干触及的区块网格失效",
            dirty.OrderBy(key => key.X).ThenBy(key => key.Z).SequenceEqual([(0, 0), (1, 0)]),
            string.Join(',', dirty.Select(key => $"({key.X},{key.Z})")));
        world.GenerateChunkAt(1, 0);
        Check("重复生成请求不会重复创建目标区块", world.Store.ChunkKeys.Count(key => key == (1, 0)) == 1);
    }
    catch (Exception exception)
    {
        Check("跨区块 Oak 提交流程", false, exception.ToString());
    }

    Console.WriteLine(failures == 0 ? "oakcrosschunkcheck 全部通过" : $"oakcrosschunkcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int OakFeatureBatchCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    try
    {
        var world = new VoxelWorld(
            20260825u,
            WorldType.Noise,
            featurePasses: [new ToolCrossChunkFeatureBurstPass()]);
        // 先让树叶目标区块存在；随后源区块提交时会走主线程跨区块 feature 写入路径。
        world.GenerateChunkAt(1, 0);
        _ = world.ConsumeFeatureMeshDirtyChunkKeys();
        var elapsed = Stopwatch.StartNew();
        world.GenerateChunkAt(0, 0);
        elapsed.Stop();

        var target = world.Store.GetChunk(1, 0);
        var placedLeaves = target is null
            ? 0
            : Enumerable.Range(0, ToolCrossChunkFeatureBurstPass.PlacementCount)
                .Count(offset => target.GetBlock(0, 200 + offset, 8).Id == BlockRegistry.Leaves);
        var statistics = typeof(VoxelWorld).GetProperty("LastFeaturePlacementCommitStatistics")?.GetValue(world);
        var writes = statistics?.GetType().GetProperty("BlockWrites")?.GetValue(statistics) as int?;
        var targets = statistics?.GetType().GetProperty("TargetChunks")?.GetValue(statistics) as int?;
        var skyRelights = statistics?.GetType().GetProperty("SkyRelightPasses")?.GetValue(statistics) as int?;
        Check(
            "跨区块树叶按目标区块批量写入并只做一次光照同步",
            placedLeaves == ToolCrossChunkFeatureBurstPass.PlacementCount &&
            writes == ToolCrossChunkFeatureBurstPass.PlacementCount &&
            targets == 1 && skyRelights == 1,
            $"leaves={placedLeaves} writes={writes} targets={targets} sky={skyRelights} elapsed={elapsed.Elapsed.TotalMilliseconds:F3}ms");

        var deferredWorld = new VoxelWorld(
            20260825u,
            WorldType.Noise,
            featurePasses: [new ToolCrossChunkFeatureBurstPass()]);
        deferredWorld.GenerateChunkAt(1, 0);
        _ = deferredWorld.ConsumeFeatureMeshDirtyChunkKeys();
        var generated = deferredWorld.CreateGeneratedChunkData(0, 0, CancellationToken.None);
        var deferredCommit = typeof(VoxelWorld).GetMethods(BindingFlags.Instance | BindingFlags.NonPublic)
            .SingleOrDefault(method => method.Name == "CommitGeneratedChunkDeferredLighting" &&
                method.GetParameters().Length == 4);
        var deferredCommitted = deferredCommit?.Invoke(
            deferredWorld,
            [0, 0, generated.Chunk, generated.FeatureBatches]) as bool?;
        var deferredStatistics = typeof(VoxelWorld).GetProperty("LastFeaturePlacementCommitStatistics")?.GetValue(deferredWorld);
        var deferredSkyRelights = deferredStatistics?.GetType().GetProperty("SkyRelightPasses")?.GetValue(deferredStatistics) as int?;
        var deferredTargets = deferredStatistics?.GetType().GetProperty("DeferredSkyRelightTargets")?.GetValue(deferredStatistics) as int?;
        var consumeDeferredLighting = typeof(VoxelWorld).GetMethod(
            "ConsumeFeatureLightingDirtyChunkKeys",
            BindingFlags.Instance | BindingFlags.NonPublic);
        var deferredLightingKeys = consumeDeferredLighting?.Invoke(deferredWorld, null) as ValueTuple<int, int>[];
        var deferredMeshKeys = deferredWorld.ConsumeFeatureMeshDirtyChunkKeys();
        Check(
            "流式树叶提交延后光照和网格到分帧队列",
            deferredCommitted == true && deferredSkyRelights == 0 && deferredTargets == 1 &&
            deferredLightingKeys is { Length: 1 } && deferredLightingKeys[0] == (1, 0) &&
            deferredMeshKeys.Length == 0,
            $"committed={deferredCommitted} sky={deferredSkyRelights} deferred={deferredTargets} " +
            $"lights={(deferredLightingKeys is null ? "missing" : string.Join(',', deferredLightingKeys))} " +
            $"meshes={string.Join(',', deferredMeshKeys)}");
    }
    catch (Exception exception)
    {
        Check("跨区块树叶批量提交执行", false, exception.ToString());
    }

    Console.WriteLine(failures == 0 ? "oakfeaturebatchcheck 全部通过" : $"oakfeaturebatchcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int OakDeterminismCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    try
    {
        var forward = new VoxelWorld(20260824u, WorldType.Noise, featurePasses: [new ToolCrossChunkFeaturePass()]);
        forward.GenerateChunkAt(0, 0);
        forward.GenerateChunkAt(1, 0);
        var reverse = new VoxelWorld(20260824u, WorldType.Noise, featurePasses: [new ToolCrossChunkFeaturePass()]);
        reverse.GenerateChunkAt(1, 0);
        reverse.GenerateChunkAt(0, 0);
        var forwardBlocks = CaptureChunkBlocks(forward, [(0, 0), (1, 0)]);
        var reverseBlocks = CaptureChunkBlocks(reverse, [(0, 0), (1, 0)]);
        Check(
            "不同区块完成顺序保持 Oak 写入确定性",
            forwardBlocks.SequenceEqual(reverseBlocks),
            $"forward={forwardBlocks.Length} reverse={reverseBlocks.Length}");
    }
    catch (Exception exception)
    {
        Check("Oak 跨区块确定性流程", false, exception.ToString());
    }

    Console.WriteLine(failures == 0 ? "oakdeterminismcheck 全部通过" : $"oakdeterminismcheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static string[] CaptureChunkBlocks(VoxelWorld world, params (int X, int Z)[] keys) =>
        keys.SelectMany(key =>
                Enumerable.Range(0, Chunk.SizeX).SelectMany(x =>
                    Enumerable.Range(Chunk.MinY, Chunk.SizeY).SelectMany(y =>
                        Enumerable.Range(0, Chunk.SizeZ)
                            .Select(z => (X: key.X * Chunk.SizeX + x, Y: y, Z: key.Z * Chunk.SizeZ + z, Block: world.GetBlock(key.X * Chunk.SizeX + x, y, key.Z * Chunk.SizeZ + z).Id)))))
            .Where(block => block.Block != BlockRegistry.Air)
            .Select(block => $"{block.X},{block.Y},{block.Z},{block.Block}")
            .ToArray();
}

static int AnimationCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    Assembly? animationAssembly = null;
    try
    {
        animationAssembly = Assembly.Load("Cubit.Animation");
        Check("Cubit.Animation assembly loadable", true, animationAssembly.FullName ?? "");
    }
    catch (Exception ex)
    {
        Check("Cubit.Animation assembly loadable", false, ex.Message);
    }

    var requiredTypes = new[]
    {
        "Cubit.Animation.CubitAnimationPlugin",
        "Cubit.Animation.AnimationClip",
        "Cubit.Animation.AnimationTrack",
        "Cubit.Animation.AnimationPlayer",
        "Cubit.Animation.Tween",
    };
    foreach (var typeName in requiredTypes)
    {
        Check($"Animation type exists: {typeName}", animationAssembly?.GetType(typeName) is not null);
    }

    var plugin = new CubitAnimationPlugin();
    Check("CubitAnimationPlugin reports stable identity", plugin.Id == "cubit.animation" && plugin.Version == new Version(1, 0, 0));
    var animationReferences = typeof(CubitAnimationPlugin).Assembly.GetReferencedAssemblies()
        .Select(reference => reference.Name)
        .Where(name => name is not null && name.StartsWith("Cubit.", StringComparison.Ordinal))
        .ToArray();
    Check("Cubit.Animation references only Cubit.Core", animationReferences.SequenceEqual(["Cubit.Core"]), string.Join(',', animationReferences));
    using (var manager = CreateToolPluginManager([plugin]))
    {
        manager.Configure([
            new CubitPluginReference { Id = "cubit.animation", Version = "1.0.0" },
        ]);
        Check(
            "CubitAnimationPlugin registers only the public animation types",
            manager.Registry.Registrations.Count == 4 &&
            manager.SceneRegistry.ResolveResourceType(nameof(AnimationClip)) == typeof(AnimationClip) &&
            manager.SceneRegistry.ResolveNodeType(nameof(AnimationPlayer)) == typeof(AnimationPlayer));
        var context = new EngineContext();
        plugin.Start(context);
        var duplicateStart = CaptureException(() => plugin.Start(context));
        Check("CubitAnimationPlugin gates duplicate start", plugin.IsStarted && duplicateStart is InvalidOperationException);
        plugin.Stop();
        plugin.Stop();
        Check("CubitAnimationPlugin Stop is idempotent", !plugin.IsStarted);
        var offThreadContext = new EngineContext();
        Exception? offThreadStart = null;
        var offThread = new Thread(() => offThreadStart = CaptureException(() => plugin.Start(offThreadContext)));
        offThread.Start();
        offThread.Join();
        Check("CubitAnimationPlugin rejects off-main-thread start", offThreadStart is InvalidOperationException && !plugin.IsStarted);
    }

    var invalidQuaternion = new AnimationTrack
    {
        TargetPath = "/Root/Probe",
        PropertyName = nameof(AnimationProbeNode.Orientation),
    };
    Check(
        "AnimationTrack rejects a zero quaternion",
        CaptureException(() => invalidQuaternion.AddQuaternionKey(0d, Quaternion.Zero)) is ArgumentException);
    var invalidFloat = new AnimationTrack
    {
        TargetPath = "/Root/Probe",
        PropertyName = nameof(AnimationProbeNode.Weight),
    };
    Check(
        "AnimationTrack rejects a non-finite float",
        CaptureException(() => invalidFloat.AddFloatKey(0d, float.NaN)) is ArgumentException);
    var invalidVector = new AnimationTrack
    {
        TargetPath = "/Root/Probe",
        PropertyName = nameof(AnimationProbeNode.Offset),
    };
    Check(
        "AnimationTrack rejects a non-finite Vector3",
        CaptureException(() => invalidVector.AddVector3Key(0d, new Vector3(float.PositiveInfinity, 0f, 0f))) is ArgumentException);
    var scaledQuaternion = new AnimationTrack
    {
        TargetPath = "/Root/Probe",
        PropertyName = nameof(AnimationProbeNode.Orientation),
    };
    scaledQuaternion.AddQuaternionKey(0d, new Quaternion(0f, 0f, 0f, 2f));
    Check("AnimationTrack normalizes finite quaternions", MathF.Abs(((Quaternion)scaledQuaternion.Keys[0].Value!).Length() - 1f) < 0.0001f);

    var clip = BuildAnimationClip(loop: false);
    var serialized = clip.ToJson();
    var roundTrip = AnimationClip.FromJson(serialized);
    Check(
        "AnimationClip sorts keys and round-trips through stable JSON",
        roundTrip.Tracks.Count == 4 && roundTrip.Tracks[0].Keys[0].Time == 0d &&
        roundTrip.Events.Count == 2 && roundTrip.Length == 1d);

    var discreteRoundTripClip = new AnimationClip { Length = 1d };
    var boolTrack = new AnimationTrack { TargetPath = "/Root/Probe", PropertyName = "BoolState" };
    boolTrack.AddDiscreteKey(0d, false);
    discreteRoundTripClip.AddTrack(boolTrack);
    var intTrack = new AnimationTrack { TargetPath = "/Root/Probe", PropertyName = "IntState" };
    intTrack.AddDiscreteKey(0d, 42);
    discreteRoundTripClip.AddTrack(intTrack);
    var longTrack = new AnimationTrack { TargetPath = "/Root/Probe", PropertyName = "LongState" };
    longTrack.AddDiscreteKey(0d, 9_007_199_254_740_991L);
    discreteRoundTripClip.AddTrack(longTrack);
    var enumTrack = new AnimationTrack { TargetPath = "/Root/Probe", PropertyName = "EnumState" };
    enumTrack.AddDiscreteKey(0d, AnimationProbeState.Active);
    discreteRoundTripClip.AddTrack(enumTrack);
    var discreteRoundTrip = AnimationClip.FromJson(discreteRoundTripClip.ToJson());
    Check(
        "AnimationClip preserves discrete value types during JSON round-trip",
        discreteRoundTrip.Tracks[0].Keys[0].Value is bool boolValue && !boolValue &&
        discreteRoundTrip.Tracks[1].Keys[0].Value is int intValue && intValue == 42 &&
        discreteRoundTrip.Tracks[2].Keys[0].Value is long longValue && longValue == 9_007_199_254_740_991L &&
        discreteRoundTrip.Tracks[3].Keys[0].Value is AnimationProbeState enumValue && enumValue == AnimationProbeState.Active);

    using (var tree = new SceneTree())
    {
        var probe = new AnimationProbeNode { Name = "Probe" };
        var player = new AnimationPlayer { Name = "Player" };
        tree.Root.AddChild(probe);
        tree.Root.AddChild(player);
        player.AddClip("walk", clip);
        var events = new List<string>();
        var finished = 0;
        player.EventTriggered += events.Add;
        player.PlaybackFinished += _ => finished++;
        player.Play("walk");
        var registeredClipNames = player.ClipNames;
        player.AddClip("clip-names-late", clip);
        Check(
            "AnimationPlayer ClipNames returns a stable registration snapshot",
            registeredClipNames.Contains("walk") && !registeredClipNames.Contains("clip-names-late") &&
            player.ClipNames.Contains("clip-names-late"));
        tree.ProcessFrame(0.5);
        Check(
            "AnimationPlayer interpolates float/vector/quaternion/discrete tracks",
            MathF.Abs(probe.Weight - 0.5f) < 0.0001f &&
            Vector3.Distance(probe.Offset, new Vector3(0f, 1f, 0f)) < 0.0001f &&
            MathF.Abs(probe.Orientation.Length() - 1f) < 0.0001f &&
            probe.State == "middle");
        Check("AnimationPlayer dispatches forward event at key boundary", events.SequenceEqual(["quarter"]));
        tree.ProcessFrame(0.5);
        Check("AnimationPlayer finishes a non-looping clip", finished == 1 && !player.IsPlaying && events.SequenceEqual(["quarter", "threequarter"]));

        events.Clear();
        player.SpeedScale = -1d;
        player.Play("walk");
        tree.ProcessFrame(0.25);
        Check("AnimationPlayer supports reverse playback event ordering", events.SequenceEqual(["threequarter"]));

        events.Clear();
        player.Play("walk");
        tree.ProcessFrame(1d);
        Check(
            "AnimationPlayer dispatches reverse multi-event playback in travel order",
            events.SequenceEqual(["threequarter", "quarter"]));

        var loopClip = BuildAnimationClip(loop: true);
        player.AddClip("loop", loopClip);
        events.Clear();
        player.SpeedScale = 1d;
        player.Play("loop");
        tree.ProcessFrame(1.25);
        Check("AnimationPlayer wraps a loop across the clip boundary", player.IsPlaying && player.CurrentTime > 0.24 && player.CurrentTime < 0.26);

        var nonFiniteSpeedError = CaptureException(() => player.SpeedScale = double.NaN);
        Check(
            "AnimationPlayer rejects a non-finite speed scale at assignment",
            nonFiniteSpeedError is ArgumentOutOfRangeException,
            nonFiniteSpeedError?.GetType().Name ?? "none");
        player.SpeedScale = 1d;

        Exception? offThreadSpeedError = null;
        var speedWorker = new Thread(() => offThreadSpeedError = CaptureException(() => player.SpeedScale = 2d));
        speedWorker.Start();
        speedWorker.Join();
        Check(
            "AnimationPlayer rejects off-thread speed scale writes",
            offThreadSpeedError is InvalidOperationException && player.SpeedScale == 1d,
            $"error={offThreadSpeedError?.GetType().Name} speed={player.SpeedScale}");

        player.SpeedScale = double.MaxValue;
        player.Play("loop");
        var overflowAdvanceError = CaptureException(() => tree.ProcessFrame(2d));
        Check(
            "AnimationPlayer rejects a finite speed and delta product that overflows",
            overflowAdvanceError is ArgumentOutOfRangeException && player.IsPlaying && player.CurrentTime == 0d,
            $"error={overflowAdvanceError?.GetType().Name} time={player.CurrentTime}");
        player.Stop();
        player.SpeedScale = 1d;

        Exception? offThreadClipNamesRead = null;
        Exception? offThreadCurrentClipRead = null;
        Exception? offThreadCurrentTimeRead = null;
        Exception? offThreadSpeedRead = null;
        Exception? offThreadPlayingRead = null;
        Exception? offThreadEventSubscription = null;
        Exception? offThreadFinishedSubscription = null;
        Action<string> offThreadEventHandler = _ => { };
        Action<string> offThreadFinishedHandler = _ => { };
        var stateWorker = new Thread(() =>
        {
            offThreadClipNamesRead = CaptureException(() => { _ = player.ClipNames.Count; });
            offThreadCurrentClipRead = CaptureException(() => { _ = player.CurrentClipName; });
            offThreadCurrentTimeRead = CaptureException(() => { _ = player.CurrentTime; });
            offThreadSpeedRead = CaptureException(() => { _ = player.SpeedScale; });
            offThreadPlayingRead = CaptureException(() => { _ = player.IsPlaying; });
            offThreadEventSubscription = CaptureException(() => player.EventTriggered += offThreadEventHandler);
            offThreadFinishedSubscription = CaptureException(() => player.PlaybackFinished += offThreadFinishedHandler);
        });
        stateWorker.Start();
        stateWorker.Join();
        player.EventTriggered -= offThreadEventHandler;
        player.PlaybackFinished -= offThreadFinishedHandler;
        Check(
            "AnimationPlayer rejects worker state reads and event subscriptions",
            offThreadClipNamesRead is InvalidOperationException &&
            offThreadCurrentClipRead is InvalidOperationException &&
            offThreadCurrentTimeRead is InvalidOperationException &&
            offThreadSpeedRead is InvalidOperationException &&
            offThreadPlayingRead is InvalidOperationException &&
            offThreadEventSubscription is InvalidOperationException &&
            offThreadFinishedSubscription is InvalidOperationException,
            $"names={offThreadClipNamesRead?.GetType().Name} clip={offThreadCurrentClipRead?.GetType().Name} " +
            $"time={offThreadCurrentTimeRead?.GetType().Name} speed={offThreadSpeedRead?.GetType().Name} " +
            $"playing={offThreadPlayingRead?.GetType().Name} event={offThreadEventSubscription?.GetType().Name} " +
            $"finished={offThreadFinishedSubscription?.GetType().Name}");

        var fadeClip = new AnimationClip { Length = 1d };
        var fadeTrack = new AnimationTrack { TargetPath = "/Root/Probe", PropertyName = nameof(AnimationProbeNode.Weight) };
        fadeTrack.AddFloatKey(0d, 10f);
        fadeTrack.AddFloatKey(1d, 20f);
        fadeClip.AddTrack(fadeTrack);
        player.AddClip("fade", fadeClip);
        player.CrossFade("fade", 1d);
        tree.ProcessFrame(0.5);
        Check("AnimationPlayer crossfades matching properties", probe.Weight > 5f && probe.Weight < 16f);

        player.Stop();
        var idleWeight = probe.Weight;
        GC.Collect();
        var allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        for (var frame = 0; frame < 120; frame++)
        {
        tree.ProcessFrame(1d / 60d);
        }

        var allocated = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
        Check("AnimationPlayer idle frames do not update or allocate", probe.Weight == idleWeight && allocated == 0, $"bytes={allocated}");

        player.EventTriggered -= events.Add;
        player.Play("loop");
        for (var frame = 0; frame < 30; frame++)
        {
            tree.ProcessFrame(1d / 60d);
        }

        GC.Collect();
        allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        for (var frame = 0; frame < 120; frame++)
        {
            tree.ProcessFrame(1d / 60d);
        }

        allocated = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
        Check("AnimationPlayer active frames do not allocate", allocated == 0, $"bytes={allocated}");

        var missingClip = new AnimationClip { Length = 1d };
        var missingTrack = new AnimationTrack { TargetPath = "/Root/Missing", PropertyName = nameof(AnimationProbeNode.Weight) };
        missingTrack.AddFloatKey(0d, 0f);
        missingClip.AddTrack(missingTrack);
        player.AddClip("missing", missingClip);
        Check("AnimationPlayer rejects a missing target at play start", CaptureException(() => player.Play("missing")) is InvalidOperationException);

        var incompatibleDiscreteClip = new AnimationClip { Length = 1d };
        var incompatibleDiscreteTrack = new AnimationTrack { TargetPath = "/Root/Probe", PropertyName = nameof(AnimationProbeNode.State) };
        incompatibleDiscreteTrack.AddDiscreteKey(0d, true);
        incompatibleDiscreteClip.AddTrack(incompatibleDiscreteTrack);
        player.AddClip("incompatible-discrete", incompatibleDiscreteClip);
        Check(
            "AnimationPlayer rejects an incompatible discrete binding at play start",
            CaptureException(() => player.Play("incompatible-discrete")) is InvalidOperationException);

        var snapshotTrack = new AnimationTrack { TargetPath = "/Root/Probe", PropertyName = nameof(AnimationProbeNode.Weight) };
        snapshotTrack.AddFloatKey(0d, 1f);
        var snapshotClip = new AnimationClip { Length = 1d };
        snapshotClip.AddTrack(snapshotTrack);
        snapshotTrack.AddFloatKey(1d, 99f);
        Check("AnimationClip stores an immutable track snapshot", snapshotClip.Tracks[0].Keys.Count == 1);

        var playbackSnapshotClip = new AnimationClip { Length = 1d };
        var playbackSnapshotTrack = new AnimationTrack
        {
            TargetPath = "/Root/Probe",
            PropertyName = nameof(AnimationProbeNode.Weight),
        };
        playbackSnapshotTrack.AddFloatKey(0d, 0f);
        playbackSnapshotTrack.AddFloatKey(1d, 1f);
        playbackSnapshotClip.AddTrack(playbackSnapshotTrack);
        player.AddClip("playback-snapshot", playbackSnapshotClip);
        player.Play("playback-snapshot");
        Exception? clipMutationError = null;
        var clipMutationWorker = new Thread(() => clipMutationError = CaptureException(() => playbackSnapshotClip.Length = double.NaN));
        clipMutationWorker.Start();
        clipMutationWorker.Join();
        tree.ProcessFrame(0.5d);
        Check(
            "AnimationPlayer isolates an active clip from external worker mutation",
            clipMutationError is null && Math.Abs(player.CurrentTime - 0.5d) < 0.0001d &&
            MathF.Abs(probe.Weight - 0.5f) < 0.0001f,
            $"error={clipMutationError?.GetType().Name ?? "none"} time={player.CurrentTime} weight={probe.Weight}");

        var playbackSnapshotConfigClip = new AnimationClip { Length = 1d, Loop = true };
        playbackSnapshotConfigClip.AddEvent(0.25d, "authored");
        player.AddClip("playback-snapshot-config", playbackSnapshotConfigClip);
        var playbackSnapshotEvents = new List<string>();
        player.EventTriggered += playbackSnapshotEvents.Add;
        Exception? configMutationError = null;
        var configMutationWorker = new Thread(() => configMutationError = CaptureException(() =>
        {
            playbackSnapshotConfigClip.Loop = false;
            playbackSnapshotConfigClip.AddEvent(0.5d, "late");
        }));
        configMutationWorker.Start();
        configMutationWorker.Join();
        player.Play("playback-snapshot-config");
        tree.ProcessFrame(1.25d);
        player.EventTriggered -= playbackSnapshotEvents.Add;
        Check(
            "AnimationPlayer freezes loop and event metadata at clip registration",
            configMutationError is null && player.IsPlaying && Math.Abs(player.CurrentTime - 0.25d) < 0.0001d &&
            playbackSnapshotEvents.SequenceEqual(["authored", "authored"]),
            $"error={configMutationError?.GetType().Name ?? "none"} playing={player.IsPlaying} " +
            $"time={player.CurrentTime} events={string.Join(',', playbackSnapshotEvents)}");

        player.Stop();
        var tween = new Tween { Name = "Tween" };
        tree.Root.AddChild(tween);
        Check(
            "Tween rejects repeat counts below -1",
            CaptureException(() => tween.RepeatCount = -2) is ArgumentOutOfRangeException);
        tween.Ease = TweenEase.EaseOut;
        tween.RepeatCount = 1;
        Exception? offThreadEaseError = null;
        Exception? offThreadRepeatError = null;
        var tweenWorker = new Thread(() =>
        {
            offThreadEaseError = CaptureException(() => tween.Ease = TweenEase.Linear);
            offThreadRepeatError = CaptureException(() => tween.RepeatCount = 2);
        });
        tweenWorker.Start();
        tweenWorker.Join();
        var invalidEaseError = CaptureException(() => tween.Ease = (TweenEase)999);
        Check(
            "Tween rejects off-thread and undefined easing state without changing playback configuration",
            offThreadEaseError is InvalidOperationException &&
            offThreadRepeatError is InvalidOperationException &&
            invalidEaseError is ArgumentOutOfRangeException &&
            tween.Ease == TweenEase.EaseOut && tween.RepeatCount == 1,
            $"ease={offThreadEaseError?.GetType().Name ?? "none"} repeat={offThreadRepeatError?.GetType().Name ?? "none"} " +
            $"invalid={invalidEaseError?.GetType().Name ?? "none"} state={tween.Ease}/{tween.RepeatCount}");
        tween.Ease = TweenEase.Linear;
        tween.RepeatCount = 0;
        var invalidValueTween = new Tween { Name = "InvalidValueTween" };
        tree.Root.AddChild(invalidValueTween);
        Check(
            "Tween rejects non-finite endpoints",
            CaptureException(() => invalidValueTween.StartFloat("/Root/Probe", nameof(AnimationProbeNode.Weight), float.NaN, 1f, 1d)) is ArgumentException);
        var canceled = 0;
        var completed = 0;
        tween.Canceled += () => canceled++;
        tween.Completed += () => completed++;
        tween.StartFloat("/Root/Probe", nameof(AnimationProbeNode.Weight), 0f, 10f, 1d);
        tree.ProcessFrame(0.5);
        Check("Tween interpolates a property", MathF.Abs(probe.Weight - 5f) < 0.0001f);
        tween.Cancel();
        tree.ProcessFrame(0.5);
        Check("Tween cancellation freezes the property", canceled == 1 && MathF.Abs(probe.Weight - 5f) < 0.0001f);
        tween.StartFloat("/Root/Probe", nameof(AnimationProbeNode.Weight), 0f, 10f, 1d);
        tree.ProcessFrame(1d);
        Check("Tween completion fires once", completed == 1 && MathF.Abs(probe.Weight - 10f) < 0.0001f && !tween.IsPlaying);
    }

    Console.WriteLine(failures == 0 ? "animationcheck passed" : $"animationcheck failed {failures}");
    return failures == 0 ? 0 : 1;

    static AnimationClip BuildAnimationClip(bool loop)
    {
        var clip = new AnimationClip { Length = 1d, Loop = loop };
        var weight = new AnimationTrack { TargetPath = "/Root/Probe", PropertyName = nameof(AnimationProbeNode.Weight) };
        weight.AddFloatKey(1d, 1f);
        weight.AddFloatKey(0d, 0f);
        clip.AddTrack(weight);
        var offset = new AnimationTrack { TargetPath = "/Root/Probe", PropertyName = nameof(AnimationProbeNode.Offset) };
        offset.AddVector3Key(0d, Vector3.Zero);
        offset.AddVector3Key(1d, Vector3.UnitY * 2f);
        clip.AddTrack(offset);
        var orientation = new AnimationTrack { TargetPath = "/Root/Probe", PropertyName = nameof(AnimationProbeNode.Orientation) };
        orientation.AddQuaternionKey(0d, Quaternion.Identity);
        orientation.AddQuaternionKey(1d, Quaternion.CreateFromAxisAngle(Vector3.UnitY, MathF.PI));
        clip.AddTrack(orientation);
        var state = new AnimationTrack { TargetPath = "/Root/Probe", PropertyName = nameof(AnimationProbeNode.State) };
        state.AddDiscreteKey(0d, "idle");
        state.AddDiscreteKey(0.5d, "middle");
        state.AddDiscreteKey(1d, "end");
        clip.AddTrack(state);
        clip.AddEvent(0.25d, "quarter");
        clip.AddEvent(0.75d, "threequarter");
        return clip;
    }
}

static int ScriptingCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    Assembly? scriptingAssembly = null;
    try
    {
        scriptingAssembly = Assembly.Load("Cubit.Scripting");
        Check("Cubit.Scripting assembly loadable", true, scriptingAssembly.FullName ?? "");
    }
    catch (Exception exception)
    {
        Check("Cubit.Scripting assembly loadable", false, exception.Message);
    }

    foreach (var typeName in new[]
    {
        "Cubit.Scripting.CubitScriptingPlugin",
        "Cubit.Scripting.CubitScript",
        "Cubit.Scripting.ScriptAttachment",
        "Cubit.Scripting.ScriptRuntime",
        "Cubit.Scripting.ScriptRuntimeException",
    })
    {
        Check($"Scripting type exists: {typeName}", scriptingAssembly?.GetType(typeName) is not null);
    }

    var scriptingReferences = typeof(CubitScriptingPlugin).Assembly.GetReferencedAssemblies()
        .Select(reference => reference.Name)
        .Where(name => name is not null && name.StartsWith("Cubit.", StringComparison.Ordinal))
        .ToArray();
    Check("Cubit.Scripting references only Cubit.Core", scriptingReferences.SequenceEqual(["Cubit.Core"]), string.Join(',', scriptingReferences));

    var plugin = new CubitScriptingPlugin();
    Check("CubitScriptingPlugin reports stable identity", plugin.Id == "cubit.scripting" && plugin.Version == new Version(1, 0, 0));
    using var manager = CreateToolPluginManager([plugin]);
    manager.Configure([new CubitPluginReference { Id = "cubit.scripting", Version = "1.0.0" }]);
    Check(
        "CubitScriptingPlugin registers script attachment resource and data-only node",
        manager.Registry.Registrations.Count == 2 &&
        manager.SceneRegistry.ResolveResourceType(nameof(ScriptAttachment)) == typeof(ScriptAttachment) &&
        manager.SceneRegistry.ResolveNodeType(nameof(ScriptAttachmentNode)) == typeof(ScriptAttachmentNode));

    var overrides = new Dictionary<string, object?> { ["ExportedValue"] = 7 };
    var serializedAttachment = new ScriptAttachment("/Root/ScriptNode", "ScriptingProbe", overrides);
    overrides["ExportedValue"] = 99;
    var serializedAttachmentNode = new ScriptAttachmentNode
    {
        Name = "ScriptAttachment",
        Attachment = serializedAttachment,
    };
    var serializedAttachmentScene = SceneIO.SerializeToJson(serializedAttachmentNode);
    var restoredAttachmentNode = SceneIO.DeserializeFromJson(
        serializedAttachmentScene,
        type => type == typeof(ScriptAttachmentNode).FullName
            ? new ScriptAttachmentNode()
            : throw new InvalidOperationException($"Unexpected scene type: {type}")) as ScriptAttachmentNode;
    Check(
        "ScriptAttachmentNode scene JSON preserves attachment data with an immutable override snapshot",
        serializedAttachment.PropertyOverrides["ExportedValue"] is 7 &&
        restoredAttachmentNode?.Attachment is { } restoredAttachment &&
        restoredAttachment.TargetPath.Value == "/Root/ScriptNode" &&
        restoredAttachment.TypeName == "ScriptingProbe" &&
        restoredAttachment.PropertyOverrides["ExportedValue"] is JsonElement { ValueKind: JsonValueKind.Number } element &&
        element.GetInt32() == 7);

    using (var attachmentTree = new SceneTree())
    {
        var authoringAttachment = new ScriptAttachment("/Root/ScriptNode", "ScriptingProbe");
        var authoringNode = new ScriptAttachmentNode
        {
            Name = "AuthoringAttachment",
            Attachment = authoringAttachment,
        };
        attachmentTree.Root.AddChild(authoringNode);
        var replacementAttachment = new ScriptAttachment("/Root/OtherNode", "OtherProbe");
        Exception? offThreadNodeWrite = null;
        Exception? offThreadResourceWrite = null;
        var attachmentWorker = new Thread(() =>
        {
            offThreadNodeWrite = CaptureException(() => authoringNode.Attachment = replacementAttachment);
            offThreadResourceWrite = CaptureException(() => authoringAttachment.TypeName = "MutatedProbe");
        });
        attachmentWorker.Start();
        attachmentWorker.Join();
        Check(
            "ScriptAttachmentNode rejects worker replacement after entering the scene tree",
            offThreadNodeWrite is InvalidOperationException && ReferenceEquals(authoringNode.Attachment, authoringAttachment),
            $"error={offThreadNodeWrite?.GetType().Name}");
        Check(
            "ScriptAttachment rejects worker mutation after its node enters the scene tree",
            offThreadResourceWrite is InvalidOperationException && authoringAttachment.TypeName == "ScriptingProbe",
            $"error={offThreadResourceWrite?.GetType().Name} type={authoringAttachment.TypeName}");
    }

    var root = Path.Combine(Path.GetTempPath(), $"cubit_scripting_{Guid.NewGuid():N}");
    WeakReference? unloadReference = null;
    try
    {
        Directory.CreateDirectory(Path.Combine(root, "bin"));
        var toolDirectory = Path.GetDirectoryName(typeof(ScriptingProbe).Assembly.Location)
            ?? throw new InvalidOperationException("未找到 Cubit.Tool 程序集目录");
        foreach (var dependency in Directory.EnumerateFiles(toolDirectory, "Cubit*.dll"))
        {
            File.Copy(dependency, Path.Combine(root, "bin", Path.GetFileName(dependency)));
        }

        plugin.Start(new EngineContext());
        RunScriptingRuntimeAssertions(root, plugin, Check);
        unloadReference = RunScriptingUnloadProbe(root, plugin);
    }
    finally
    {
        plugin.Stop();
        GC.Collect();
        GC.WaitForPendingFinalizers();
        GC.Collect();
        Check("ScriptRuntime releases the collectible AssemblyLoadContext", unloadReference is not null && !unloadReference.IsAlive);
        if (Directory.Exists(root))
        {
            try
            {
                Directory.Delete(root, true);
                Check("ScriptRuntime unloads the collectible project assembly", true);
            }
            catch (Exception exception) when (exception is IOException or UnauthorizedAccessException)
            {
                Check("ScriptRuntime unloads the collectible project assembly", false, exception.Message);
            }
        }
    }

    Console.WriteLine(failures == 0 ? "scriptingcheck passed" : $"scriptingcheck failed {failures}");
    return failures == 0 ? 0 : 1;
}

[MethodImpl(MethodImplOptions.NoInlining)]
static WeakReference RunScriptingUnloadProbe(string root, CubitScriptingPlugin plugin)
{
    using var tree = new SceneTree();
    tree.Root.AddChild(new Node { Name = "ScriptNode" });
    using var runtime = plugin.CreateRuntime(tree, root, new DiagnosticBag());
    runtime.LoadAssembly("bin/Cubit.Tool.dll");
    var reference = runtime.LoadContextReference ?? throw new InvalidOperationException("缺少脚本加载上下文引用");
    plugin.Stop();
    return reference;
}

[MethodImpl(MethodImplOptions.NoInlining)]
static void RunScriptingRuntimeAssertions(
    string root,
    CubitScriptingPlugin plugin,
    Action<string, bool, string> check)
{
    using var tree = new SceneTree();
    var target = new Node { Name = "ScriptNode" };
    tree.Root.AddChild(target);
    var diagnostics = new DiagnosticBag();
    using var runtime = plugin.CreateRuntime(tree, root, diagnostics);
    check("Creating ScriptRuntime does not load or execute project code", runtime.LoadedAssembly is null && runtime.ActiveScripts.Count == 0, "");

    runtime.LoadAssembly("bin/Cubit.Tool.dll");
    check("ScriptRuntime loads only an explicit project-relative assembly", runtime.LoadedAssembly is not null, "");
    var traversalError = CaptureException(() => runtime.LoadAssembly("../Cubit.Tool.dll"));
    check("ScriptRuntime rejects project path traversal", traversalError is ScriptRuntimeException, traversalError?.GetType().Name ?? "");
    var attachment = new ScriptAttachment(
        "/Root/ScriptNode",
        "ScriptingProbe",
        new Dictionary<string, object?> { ["ExportedValue"] = 7, ["ExportedField"] = 11 });
    runtime.Start([attachment]);
    Exception? offThreadAssemblyRead = null;
    Exception? offThreadRunningRead = null;
    Exception? offThreadScriptsRead = null;
    var runtimeStateWorker = new Thread(() =>
    {
        offThreadAssemblyRead = CaptureException(() => { _ = runtime.LoadedAssembly; });
        offThreadRunningRead = CaptureException(() => { _ = runtime.IsRunning; });
        offThreadScriptsRead = CaptureException(() => { _ = runtime.ActiveScripts.Count; });
    });
    runtimeStateWorker.Start();
    runtimeStateWorker.Join();
    check(
        "ScriptRuntime rejects worker reads of lifecycle state",
        offThreadAssemblyRead is InvalidOperationException &&
        offThreadRunningRead is InvalidOperationException &&
        offThreadScriptsRead is InvalidOperationException,
        $"assembly={offThreadAssemblyRead?.GetType().Name} running={offThreadRunningRead?.GetType().Name} " +
        $"scripts={offThreadScriptsRead?.GetType().Name}");
    var script = runtime.ActiveScripts.Single();
    var scriptType = script.GetType();
    var exportedValue = scriptType.GetProperty("ExportedValue")?.GetValue(script);
    var exportedField = scriptType.GetField("ExportedField")?.GetValue(script);
    check("ScriptRuntime binds a public parameterless CubitScript to NodePath", ReferenceEquals(script.TargetNode, target), "");
    check("ScriptRuntime applies only exported attachment overrides", exportedValue is 7, "");
    check("ScriptRuntime applies exported field overrides", exportedField is 11, exportedField?.ToString() ?? "null");

    runtime.PhysicsProcess(0.05);
    runtime.Process(0.016);
    var log = scriptType.GetProperty("Log")?.GetValue(script) as IReadOnlyList<string>;
    check("ScriptRuntime runs deterministic lifecycle order on the main thread", log is not null && log.SequenceEqual(["enter", "ready", "physics", "process"]), string.Join(',', log ?? []));

    runtime.Stop();
    log = scriptType.GetProperty("Log")?.GetValue(script) as IReadOnlyList<string>;
    check("ScriptRuntime invokes OnExitTree in a controlled stop", log is not null && log.SequenceEqual(["enter", "ready", "physics", "process", "exit"]), string.Join(',', log ?? []));

    var aliasedAttachment = new ScriptAttachment(
        "/Root/ScriptNode",
        "ScriptingProbe",
        new Dictionary<string, object?> { ["ThrowOnProcess"] = true });
    runtime.Start([aliasedAttachment]);
    var bindingsField = typeof(ScriptRuntime).GetField("_bindings", BindingFlags.Instance | BindingFlags.NonPublic);
    var bindingObject = (bindingsField?.GetValue(runtime) as System.Collections.IEnumerable)?.Cast<object>().SingleOrDefault();
    var bindingAttachment = bindingObject?.GetType().GetProperty("Attachment")?.GetValue(bindingObject);
    aliasedAttachment.TargetPath = "/Root/MutatedAfterStart";
    aliasedAttachment.TypeName = "MutatedAfterStart";
    var aliasedLifecycleError = CaptureException(() => runtime.Process(0.016));
    check(
        "ScriptRuntime snapshots attachment identity before running user code",
        bindingAttachment is ScriptAttachment snapshot &&
            !ReferenceEquals(snapshot, aliasedAttachment) &&
            snapshot.TargetPath.Value == "/Root/ScriptNode" &&
            snapshot.TypeName == "ScriptingProbe" &&
            aliasedLifecycleError is ScriptRuntimeException aliasedFailure &&
            aliasedFailure.ScriptType == "ScriptingProbe" &&
            aliasedFailure.NodePath == "/Root/ScriptNode" &&
            aliasedFailure.Phase == "process",
        aliasedLifecycleError?.GetType().Name ?? "");
    runtime.Stop();

    runtime.Start([attachment]);
    var nonFinitePhysicsDeltaError = CaptureException(() => runtime.PhysicsProcess(double.NaN));
    check(
        "ScriptRuntime rejects a non-finite physics delta before invoking scripts",
        nonFinitePhysicsDeltaError is ArgumentOutOfRangeException,
        nonFinitePhysicsDeltaError?.GetType().Name ?? "");
    var negativeProcessDeltaError = CaptureException(() => runtime.Process(-0.001));
    check(
        "ScriptRuntime rejects a negative process delta before invoking scripts",
        negativeProcessDeltaError is ArgumentOutOfRangeException,
        negativeProcessDeltaError?.GetType().Name ?? "");
    runtime.Stop();

    var nonExportedError = CaptureException(() => runtime.Start([
        new ScriptAttachment(
            "/Root/ScriptNode",
            "ScriptingProbe",
            new Dictionary<string, object?> { ["NonExportedValue"] = 9 })
    ]));
    check("ScriptRuntime rejects overrides for non-exported properties", nonExportedError is ScriptRuntimeException, nonExportedError?.GetType().Name ?? "");

    var nonScriptError = CaptureException(() => runtime.Start([
        new ScriptAttachment("/Root/ScriptNode", "NonScriptProbe")
    ]));
    check("ScriptRuntime rejects types that are not CubitScript", nonScriptError is ScriptRuntimeException, nonScriptError?.GetType().Name ?? "");

    runtime.Start([attachment]);
    var offThreadError = CaptureException(() =>
        Task.Run(() => runtime.Process(0.016)).GetAwaiter().GetResult());
    check("ScriptRuntime rejects lifecycle calls from worker threads", offThreadError is InvalidOperationException, offThreadError?.GetType().Name ?? "");
    runtime.Stop();

    runtime.Start([new ScriptAttachment(
        "/Root/ScriptNode",
        "ScriptingProbe",
        new Dictionary<string, object?> { ["ThrowOnProcess"] = true })]);
    var lifecycleError = CaptureException(() => runtime.Process(0.016));
    check(
        "ScriptRuntime reports lifecycle failures with type, path, and phase",
        lifecycleError is ScriptRuntimeException scriptError &&
            scriptError.ScriptType == "ScriptingProbe" &&
            scriptError.NodePath == "/Root/ScriptNode" &&
            scriptError.Phase == "process",
        lifecycleError?.GetType().Name ?? "");
    runtime.Stop();
    check("ScriptRuntime clears bindings after a lifecycle failure", runtime.ActiveScripts.Count == 0, runtime.ActiveScripts.Count.ToString());

    var emptyAttachmentError = CaptureException(() => runtime.Start([new ScriptAttachment()]));
    check(
        "ScriptRuntime rejects empty attachment target and type with a stable bind diagnostic",
        emptyAttachmentError is ScriptRuntimeException emptyAttachmentFailure &&
        emptyAttachmentFailure.Phase == "bind" &&
        emptyAttachmentFailure.ScriptType == "" &&
        emptyAttachmentFailure.NodePath == "" &&
        runtime.ActiveScripts.Count == 0,
        emptyAttachmentError?.Message ?? "");

    var duplicateAttachmentError = CaptureException(() => runtime.Start([
        new ScriptAttachment("/Root/ScriptNode", "ScriptingProbe"),
        new ScriptAttachment("/Root/ScriptNode", "ScriptingProbe"),
    ]));
    check(
        "ScriptRuntime rejects duplicate target and type attachments before creating scripts",
        duplicateAttachmentError is ScriptRuntimeException duplicateAttachmentFailure &&
        duplicateAttachmentFailure.Phase == "bind" &&
        duplicateAttachmentFailure.ScriptType == "ScriptingProbe" &&
        duplicateAttachmentFailure.NodePath == "/Root/ScriptNode" &&
        runtime.ActiveScripts.Count == 0,
        duplicateAttachmentError?.Message ?? "");

    runtime.Start([new ScriptAttachment(
        "/Root/ScriptNode",
        "ScriptingProbe",
        new Dictionary<string, object?> { ["ThrowScriptRuntimeException"] = true })]);
    var userRuntimeError = CaptureException(() => runtime.Process(0.016));
    check(
        "ScriptRuntime wraps user-thrown ScriptRuntimeException with host context",
        userRuntimeError is ScriptRuntimeException userScriptError &&
            userScriptError.ScriptType == "ScriptingProbe" &&
            userScriptError.NodePath == "/Root/ScriptNode" &&
            userScriptError.Phase == "process",
        userRuntimeError?.GetType().Name ?? "");
    runtime.Stop();

    var setterError = CaptureException(() => runtime.Start([new ScriptAttachment(
        "/Root/ScriptNode",
        "ScriptingProbe",
        new Dictionary<string, object?> { ["ThrowingValue"] = 13 })]));
    check("ScriptRuntime reports exported setter failures with stable context", setterError is ScriptRuntimeException, setterError?.GetType().Name ?? "");

    var constructorError = CaptureException(() => runtime.Start([
        new ScriptAttachment("/Root/ScriptNode", "ConstructorFailureProbe")
    ]));
    check("ScriptRuntime reports constructor failures with stable context", constructorError is ScriptRuntimeException, constructorError?.GetType().Name ?? "");

    var invalidError = CaptureException(() => runtime.Start([
        new ScriptAttachment("/Root/ScriptNode", "MissingScriptType")
    ]));
    check("ScriptRuntime rejects unknown script types with a stable diagnostic exception", invalidError is ScriptRuntimeException, invalidError?.GetType().Name ?? "");

    runtime.Dispose();
    var disposedStopError = CaptureException(runtime.Stop);
    check(
        "ScriptRuntime rejects Stop after dispose",
        disposedStopError is ObjectDisposedException,
        disposedStopError?.GetType().Name ?? "");
}

static void WritePersistentProjectFixture(string projectRoot)
{
    var voxelRoot = Path.Combine(projectRoot, "assets", "voxel");
    var blocksRoot = Path.Combine(voxelRoot, "blocks", "tool_fixture");
    Directory.CreateDirectory(blocksRoot);
    var reservedIds = string.Join(',', Enumerable.Range(8, 92));
    File.WriteAllText(
        Path.Combine(voxelRoot, "block-ids.json"),
        "{\"formatVersion\":1,\"firstProjectBlockId\":8,\"nextId\":101," +
        "\"blocks\":[{\"key\":\"tool.fixture:probe\",\"id\":100}]," +
        $"\"reservedIds\":[{reservedIds}]}}");
    File.WriteAllText(
        Path.Combine(blocksRoot, "probe.json"),
        "{\"key\":\"tool.fixture:probe\",\"name\":\"Fixture Probe\",\"topTexture\":\"dirt\",\"sideTexture\":\"dirt\",\"bottomTexture\":\"dirt\"}");
}

static int SingleplayerCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    Check("定位单人模式工作区", workspaceRoot is not null, workspaceRoot ?? "missing");
    if (workspaceRoot is null)
    {
        return 1;
    }

    Assembly? projectAssembly = null;
    try
    {
        projectAssembly = Assembly.Load("MyFirstCubitProject");
        Check("单人模式项目程序集可由反射加载", true, projectAssembly.FullName ?? "");
    }
    catch (Exception exception)
    {
        Check("单人模式项目程序集可由反射加载", false, exception.Message);
    }

    var menuStateType = projectAssembly?.GetType("MyFirstCubitProject.SingleplayerMenuState");
    var repositoryType = projectAssembly?.GetType("MyFirstCubitProject.WorldRepository");
    var summaryType = projectAssembly?.GetType("MyFirstCubitProject.WorldSummary");
    var controllerType = projectAssembly?.GetType("MyFirstCubitProject.SingleplayerMenuController");
    var respawnPointType = projectAssembly?.GetType("MyFirstCubitProject.ProjectRespawnPoint");
    var respawnCatalogType = projectAssembly?.GetType("MyFirstCubitProject.ProjectRespawnPointCatalog");
    var respawnResolverType = projectAssembly?.GetType("MyFirstCubitProject.IProjectPlayerRespawnPointResolver");
    var voxelRespawnResolverType = projectAssembly?.GetType("MyFirstCubitProject.ProjectVoxelPlayerRespawnPointResolver");
    Check("项目程序集包含单人菜单状态", menuStateType is not null, "MyFirstCubitProject.SingleplayerMenuState");
    Check("项目程序集包含世界存档目录", repositoryType is not null, "MyFirstCubitProject.WorldRepository");
    Check("项目程序集包含世界摘要", summaryType is not null, "MyFirstCubitProject.WorldSummary");
    Check("项目程序集包含单人菜单作者节点", controllerType is not null, "MyFirstCubitProject.SingleplayerMenuController");
    Check("项目提供可配置重生点数据类型", respawnPointType is not null, respawnPointType?.FullName ?? "missing");
    Check("项目提供重生点目录加载器", respawnCatalogType is not null, respawnCatalogType?.FullName ?? "missing");
    Check("项目提供重生点解析契约", respawnResolverType is not null, respawnResolverType?.FullName ?? "missing");
    Check("项目提供 Voxel 重生点解析器", voxelRespawnResolverType is not null, voxelRespawnResolverType?.FullName ?? "missing");
    Check("单人菜单控制器提供显式重生入口",
        controllerType?.GetMethod("RespawnPlayer", BindingFlags.Public | BindingFlags.Instance) is not null,
        "RespawnPlayer");
    Check(
        "单人菜单控制器提供删除确认动作",
        controllerType?.GetMethod("RequestDeleteSelectedWorld", BindingFlags.Public | BindingFlags.Instance) is not null &&
        controllerType?.GetMethod("CancelDelete", BindingFlags.Public | BindingFlags.Instance) is not null &&
        controllerType?.GetMethod("ConfirmDelete", BindingFlags.Public | BindingFlags.Instance) is not null,
        "RequestDeleteSelectedWorld/CancelDelete/ConfirmDelete");
    Check(
        "单人菜单控制器提供加载失败返回选档动作",
        controllerType?.GetMethod("ReturnToWorldSelection", BindingFlags.Public | BindingFlags.Instance) is not null,
        "ReturnToWorldSelection");
    var respawnAssetPath = Path.Combine(workspaceRoot, "我的第一个cubit项目", "assets", "gameplay", "respawn-points.json");
    Check("项目资产包含重生点候选目录", File.Exists(respawnAssetPath), respawnAssetPath);
    var playerControllerPath = Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "PlayerController.cs");
    var playerControllerSource = File.Exists(playerControllerPath) ? File.ReadAllText(playerControllerPath) : string.Empty;
    Check("PlayerController 不硬编码单一重生坐标",
        !playerControllerSource.Contains("GetSpawnHeight(24, 24)", StringComparison.Ordinal) &&
        !playerControllerSource.Contains("new Vector3(24f", StringComparison.Ordinal),
        playerControllerPath);
    try
    {
        var respawnCatalog = MyFirstCubitProject.ProjectRespawnPointCatalog.Load(
            Path.Combine(workspaceRoot, "我的第一个cubit项目"));
        Check("重生点目录按作者顺序加载多个候选", respawnCatalog.Points.Count == 2 &&
            respawnCatalog.Points[0] == new MyFirstCubitProject.ProjectRespawnPoint(24, 24) &&
            respawnCatalog.Points[1] == new MyFirstCubitProject.ProjectRespawnPoint(0, 0),
            $"count={respawnCatalog.Points.Count}");
        var respawnWorld = new VoxelWorld(20260808u, WorldType.Flat);
        respawnWorld.GenerateChunkAt(0, 0);
        var respawnResolver = new MyFirstCubitProject.ProjectVoxelPlayerRespawnPointResolver(respawnCatalog);
        var resolved = respawnResolver.TryResolve(respawnWorld, out var resolvedPosition);
        Check("重生解析器跳过未加载首候选并选择已加载候选", resolved &&
            resolvedPosition == new Vector3(0.5f, 5f, 0.5f),
            $"resolved={resolved} position={resolvedPosition}");
    }
    catch (Exception exception)
    {
        Check("重生点目录和体素解析器行为不抛出异常", false, exception.ToString());
    }

    if (menuStateType is not null)
    {
        try
        {
            var state = Activator.CreateInstance(menuStateType);
            var screen = menuStateType.GetProperty("Screen");
            var showWorldSelection = menuStateType.GetMethod("ShowWorldSelection");
            var showCreateWorld = menuStateType.GetMethod("ShowCreateWorld");
            var showDeleteConfirm = menuStateType.GetMethod("ShowDeleteConfirm");
            var cancelDelete = menuStateType.GetMethod("CancelDelete");
            var beginOpeningWorld = menuStateType.GetMethod("BeginOpeningWorld");
            var beginPlaying = menuStateType.GetMethod("BeginPlaying");
            var showDeath = menuStateType.GetMethod("ShowDeath");
            var respawn = menuStateType.GetMethod("Respawn");
            var togglePause = menuStateType.GetMethod("TogglePause");
            var returnToTitle = menuStateType.GetMethod("ReturnToTitle");
            Check(
                "单人菜单状态公开标题、选档、创建、游戏、暂停与死亡转换",
                state is not null && screen is not null && showWorldSelection is not null && showCreateWorld is not null &&
                showDeleteConfirm is not null && cancelDelete is not null && beginOpeningWorld is not null &&
                beginPlaying is not null && showDeath is not null && respawn is not null &&
                togglePause is not null && returnToTitle is not null,
                $"screen={screen is not null} select={showWorldSelection is not null} create={showCreateWorld is not null} delete={showDeleteConfirm is not null} cancel={cancelDelete is not null} opening={beginOpeningWorld is not null} play={beginPlaying is not null} death={showDeath is not null} respawn={respawn is not null} pause={togglePause is not null} title={returnToTitle is not null}");

            if (state is not null && screen is not null && showWorldSelection is not null && showCreateWorld is not null &&
                showDeleteConfirm is not null && cancelDelete is not null && beginOpeningWorld is not null &&
                beginPlaying is not null && showDeath is not null && respawn is not null &&
                togglePause is not null && returnToTitle is not null)
            {
                Check("单人菜单初始停在标题界面", string.Equals(screen.GetValue(state)?.ToString(), "Title", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                beginPlaying.Invoke(state, null);
                Check("标题界面不能直接进入游戏", string.Equals(screen.GetValue(state)?.ToString(), "Title", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                showCreateWorld.Invoke(state, null);
                Check("标题界面不能直接进入创建世界", string.Equals(screen.GetValue(state)?.ToString(), "Title", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                showDeleteConfirm.Invoke(state, null);
                Check("标题界面不能直接进入删除确认", string.Equals(screen.GetValue(state)?.ToString(), "Title", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                cancelDelete.Invoke(state, null);
                beginOpeningWorld.Invoke(state, null);
                Check("标题界面不能取消或开始非法加载", string.Equals(screen.GetValue(state)?.ToString(), "Title", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                showDeath.Invoke(state, null);
                Check("标题界面不能直接进入死亡界面", string.Equals(screen.GetValue(state)?.ToString(), "Title", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                respawn.Invoke(state, null);
                Check("标题界面不能直接重生进入游戏", string.Equals(screen.GetValue(state)?.ToString(), "Title", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                showWorldSelection.Invoke(state, null);
                Check("标题界面可进入世界选择", string.Equals(screen.GetValue(state)?.ToString(), "WorldSelection", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                showCreateWorld.Invoke(state, null);
                Check("世界选择可进入创建世界", string.Equals(screen.GetValue(state)?.ToString(), "CreateWorld", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                beginOpeningWorld.Invoke(state, null);
                Check("创建世界可进入加载状态", string.Equals(screen.GetValue(state)?.ToString(), "OpeningWorld", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                beginPlaying.Invoke(state, null);
                Check("创建或加载完成后进入游戏", string.Equals(screen.GetValue(state)?.ToString(), "Playing", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                togglePause.Invoke(state, null);
                Check("Esc 能从游戏切到暂停", string.Equals(screen.GetValue(state)?.ToString(), "Pause", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                togglePause.Invoke(state, null);
                Check("Esc 能从暂停返回游戏", string.Equals(screen.GetValue(state)?.ToString(), "Playing", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                showDeath.Invoke(state, null);
                Check("玩家死亡事件可切换到死亡界面", string.Equals(screen.GetValue(state)?.ToString(), "Death", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                respawn.Invoke(state, null);
                Check("死亡界面可返回游戏状态", string.Equals(screen.GetValue(state)?.ToString(), "Playing", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
                returnToTitle.Invoke(state, null);
                Check("暂停菜单可返回标题", string.Equals(screen.GetValue(state)?.ToString(), "Title", StringComparison.Ordinal), screen.GetValue(state)?.ToString() ?? "null");
            }
        }
        catch (Exception exception)
        {
            Check("单人菜单状态转换不抛出反射异常", false, exception.GetType().Name + ": " + exception.Message);
        }
    }

    if (repositoryType is not null && summaryType is not null)
    {
        var temporaryRoot = Path.Combine(Path.GetTempPath(), "Cubit.SingleplayerCheck", Guid.NewGuid().ToString("N"));
        try
        {
            var constructor = repositoryType.GetConstructor([typeof(string)]);
            var create = repositoryType.GetMethod("Create");
            var list = repositoryType.GetMethod("List");
            var load = repositoryType.GetMethod("Load");
            Check(
                "世界存档目录公开创建、列举与加载接口",
                constructor is not null && create is not null && list is not null && load is not null,
                $"ctor={constructor is not null} create={create is not null} list={list is not null} load={load is not null}");

            if (constructor is not null && create is not null && list is not null && load is not null)
            {
                WritePersistentProjectFixture(temporaryRoot);
                var repository = constructor.Invoke([temporaryRoot]);
                // 此处验证的是旧式直接 Load 的 region 持久化；Noise 新世界为 river-v1，
                // 必须通过项目 Open 注入地形通道，其行为由 projectwatercheck 单独覆盖。
                var created = create.Invoke(repository, ["First World", 123456u, WorldType.Flat]);
                var identifier = summaryType.GetProperty("Id")?.GetValue(created)?.ToString();
                var displayName = summaryType.GetProperty("DisplayName")?.GetValue(created)?.ToString();
                Check(
                    "创建世界生成与显示名称分离的安全目录标识",
                    !string.IsNullOrWhiteSpace(identifier) && identifier.All(character => char.IsAsciiLetterOrDigit(character) || character == '-') &&
                    string.Equals(displayName, "First World", StringComparison.Ordinal),
                    $"id={identifier ?? "null"} name={displayName ?? "null"}");

                var listed = ((list.Invoke(repository, null) as System.Collections.IEnumerable)?.Cast<object>().ToArray()) ?? [];
                Check("重启前世界目录可列出新建世界", listed.Length == 1 && Equals(summaryType.GetProperty("Id")?.GetValue(listed[0]), identifier), $"count={listed.Length}");

                var reopened = constructor.Invoke([temporaryRoot]);
                var reloadedList = ((list.Invoke(reopened, null) as System.Collections.IEnumerable)?.Cast<object>().ToArray()) ?? [];
                Check("重新打开项目后世界元数据仍可列出", reloadedList.Length == 1, $"count={reloadedList.Length}");
                var world = reloadedList.Length == 1 ? load.Invoke(reopened, [reloadedList[0]]) : null;
                Check("列出的 legacy 世界可从 region 存档恢复", world is VoxelWorld restored && restored.Seed == 123456u && restored.WorldType == WorldType.Flat, world?.GetType().Name ?? "null");

                var reparseRoot = Path.Combine(Path.GetTempPath(), "Cubit.SingleplayerCheck", Guid.NewGuid().ToString("N"));
                var reparseOutside = Path.Combine(Path.GetTempPath(), "Cubit.SingleplayerCheck", Guid.NewGuid().ToString("N"));
                var reparseSaves = Path.Combine(reparseRoot, "saves");
                try
                {
                    Directory.CreateDirectory(reparseRoot);
                    WritePersistentProjectFixture(reparseRoot);
                    Directory.CreateDirectory(reparseOutside);
                    CreateDirectoryJunction(reparseSaves, reparseOutside);
                    var reparseRepository = constructor.Invoke([reparseRoot]);
                    var reparseException = CaptureException(() => create.Invoke(reparseRepository, ["Unsafe", 1u, WorldType.Noise]));
                    Check(
                        "世界存档拒绝项目外 saves 目录 Junction",
                        reparseException is TargetInvocationException { InnerException: IOException },
                        reparseException?.GetType().Name ?? "none");
                }
                finally
                {
                    if (Directory.Exists(reparseSaves))
                    {
                        DeleteDirectoryJunction(reparseSaves);
                    }

                    if (Directory.Exists(reparseRoot))
                    {
                        Directory.Delete(reparseRoot, recursive: true);
                    }

                    if (Directory.Exists(reparseOutside))
                    {
                        Directory.Delete(reparseOutside, recursive: true);
                    }
                }
            }
        }
        catch (Exception exception)
        {
            Check("世界存档目录行为检查未出现异常", false, exception.ToString());
        }
        finally
        {
            if (Directory.Exists(temporaryRoot))
            {
                Directory.Delete(temporaryRoot, recursive: true);
            }
        }
    }

    try
    {
        var existingProjectRoot = Path.Combine(workspaceRoot, "我的第一个cubit项目");
        var repository = Activator.CreateInstance(repositoryType!, existingProjectRoot);
        var existingWorlds = ((repositoryType!.GetMethod("List")!.Invoke(repository, null) as System.Collections.IEnumerable)?.Cast<object>().ToArray()) ?? [];
        Check("真实项目旧存档仍可列出", existingWorlds.Length > 0, $"count={existingWorlds.Length}");
        foreach (var existingWorld in existingWorlds)
        {
            try
            {
                var loaded = repositoryType.GetMethod("Load")!.Invoke(repository, [existingWorld]);
                Check("真实项目旧存档可读取", loaded is VoxelWorld, summaryType?.GetProperty("Id")?.GetValue(existingWorld)?.ToString() ?? "unknown");
            }
            catch (TargetInvocationException exception)
            {
                Check("真实项目旧存档可读取", false, exception.InnerException?.ToString() ?? exception.ToString());
            }
        }
    }
    catch (Exception exception)
    {
        Check("真实项目旧存档检查未出现异常", false, exception.ToString());
    }

    try
    {
        var existingProjectRoot = Path.Combine(workspaceRoot, "我的第一个cubit项目");
        using var existingSession = CreateVoxelProjectSession(
            new FakeRenderBackend(),
            20260808u,
            workerCount: 1,
            worldType: WorldType.Flat,
            projectRootOverride: existingProjectRoot);
        var menuNode = existingSession.Scene.Tree.GetNode(new NodePath("/Root/SingleplayerMenu"))
            as MyFirstCubitProject.SingleplayerMenuController;
        var existingSummary = menuNode?.Worlds.FirstOrDefault();
        Check("真实项目运行时可读取旧世界列表", menuNode is not null && existingSummary is not null, $"worlds={menuNode?.Worlds.Count ?? 0}");
        if (menuNode is not null && existingSummary is not null)
        {
            menuNode.SelectWorld(existingSummary);
            var opened = menuNode.OpenSelectedWorld();
            menuNode = existingSession.Scene.Tree.GetNode("/Root/SingleplayerMenu") as MyFirstCubitProject.SingleplayerMenuController;
            for (var frame = 0; opened && menuNode?.State.Screen == MyFirstCubitProject.SingleplayerMenuScreen.OpeningWorld && frame < 900; frame++)
            {
                existingSession.Scene.ProcessFrame(1d / 60d);
                Thread.Sleep(1);
            }
            Check(
                "真实项目运行时可打开旧世界并进入游戏",
                opened && menuNode?.State.IsGameplayActive == true && menuNode.CurrentWorld?.Id == existingSummary.Id,
                $"opened={opened} screen={menuNode?.State.Screen} current={menuNode?.CurrentWorld?.Id ?? "null"} " +
                $"stage={menuNode?.OpeningProgress?.Stage} error={menuNode?.LastError ?? "none"}");
        }
    }
    catch (Exception exception)
    {
        Check("真实项目运行时旧世界切换未出现异常", false, exception.ToString());
    }

    var runtimeBootstrapPath = Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "RuntimeBootstrap.cs");
    var mainScenePath = Path.Combine(workspaceRoot, "我的第一个cubit项目", "scenes", "gameplay.cscene");
    var runtimeBootstrapSource = File.Exists(runtimeBootstrapPath) ? File.ReadAllText(runtimeBootstrapPath) : string.Empty;
    Check(
        "运行时引导器注册单人菜单作者节点类型",
        runtimeBootstrapSource.Contains("registry.RegisterNode(() => new SingleplayerMenuController())", StringComparison.Ordinal),
        runtimeBootstrapPath);

    var menuDeclarations = 0;
    try
    {
        var sceneRoot = JsonNode.Parse(File.ReadAllText(mainScenePath));
        menuDeclarations = sceneRoot?["Children"]?.AsArray()
            .Count(child => string.Equals(child?["Type"]?.GetValue<string>(), "MyFirstCubitProject.SingleplayerMenuController", StringComparison.Ordinal)) ?? 0;
    }
    catch (Exception exception)
    {
        Check("主场景可以读取单人菜单作者节点声明", false, exception.Message);
    }

    Check("主场景在 Root 直接声明一个单人菜单节点", menuDeclarations == 1, $"count={menuDeclarations} path={mainScenePath}");
    Console.WriteLine(failures == 0 ? "singleplayercheck 全部通过" : $"singleplayercheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int ColorSpaceCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    Check("定位颜色空间渲染源码", repositoryRoot is not null, repositoryRoot ?? "missing");
    if (repositoryRoot is null)
    {
        return 1;
    }

    var coreRendererPath = Path.Combine(repositoryRoot, "src", "Cubit.Core", "Rendering", "VulkanContext.cs");
    var textureDataPath = Path.Combine(repositoryRoot, "src", "Cubit.Core", "Rendering", "TextureData.cs");
    var imGuiRendererPath = Path.Combine(repositoryRoot, "src", "Cubit.ImGui", "ImGuiRenderer.cs");
    var worldShaderPath = Path.Combine(repositoryRoot, "assets", "shaders", "world.frag");
    var imGuiShaderPath = Path.Combine(repositoryRoot, "assets", "shaders", "imgui.frag");
    var coreRenderer = File.ReadAllText(coreRendererPath);
    var textureData = File.ReadAllText(textureDataPath);
    var imGuiRenderer = File.ReadAllText(imGuiRendererPath);
    var worldShader = File.ReadAllText(worldShaderPath);
    var imGuiShader = File.ReadAllText(imGuiShaderPath);

    Check(
        "世界纹理上传根据颜色空间选择 Vulkan 格式",
        coreRenderer.Contains("TextureColorSpace.Srgb => Format.R8G8B8A8Srgb", StringComparison.Ordinal),
        coreRendererPath);
    Check(
        "ImGui 静态纹理使用 sRGB 格式采样",
        imGuiRenderer.Contains("Format.R8G8B8A8Srgb", StringComparison.Ordinal),
        imGuiRendererPath);
    Check(
        "世界着色器继续在线性空间乘以光照强度",
        worldShader.Contains("texture(atlas, fragUv)", StringComparison.Ordinal) &&
        worldShader.Contains("vec3(fragShade)", StringComparison.Ordinal),
        worldShaderPath);
    Check(
        "世界着色器丢弃透明皮肤覆盖层，避免透明像素写成黑色",
        worldShader.Contains("sampled.a < 0.5", StringComparison.Ordinal) &&
        worldShader.Contains("discard", StringComparison.Ordinal),
        worldShaderPath);
    Check(
        "ImGui 将作者颜色从 sRGB 转换为线性空间",
        imGuiShader.Contains("srgbToLinear", StringComparison.Ordinal),
        imGuiShaderPath);
    Check(
        "颜色纹理默认按 sRGB 采样，并允许声明线性数据纹理",
        textureData.Contains("TextureColorSpace colorSpace = TextureColorSpace.Srgb", StringComparison.Ordinal) &&
        textureData.Contains("TextureColorSpace ColorSpace", StringComparison.Ordinal),
        textureDataPath);

    Console.WriteLine(failures == 0 ? "colorspacecheck 全部通过" : $"colorspacecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int DesktopUiCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    Check("定位桌面原版 UI 工作区", workspaceRoot is not null, workspaceRoot ?? "missing");
    if (workspaceRoot is null)
    {
        return 1;
    }

    var projectRoot = Path.Combine(workspaceRoot, "我的第一个cubit项目");
    var vanillaClientJarPath = Path.Combine(workspaceRoot, "mc26.1.2", "versions", "26.1.2", "26.1.2.jar");
    Check("定位原版客户端资源 JAR", File.Exists(vanillaClientJarPath), vanillaClientJarPath);
    var expectedAssets = new[]
    {
        "minecraft/textures/font/ascii.png",
        "minecraft/textures/gui/title/minecraft.png",
        "minecraft/textures/gui/menu_background.png",
        "minecraft/textures/gui/menu_list_background.png",
        "minecraft/textures/gui/header_separator.png",
        "minecraft/textures/gui/footer_separator.png",
        "minecraft/textures/gui/tab_header_background.png",
        "minecraft/textures/gui/inworld_menu_background.png",
        "minecraft/textures/gui/sprites/widget/button.png",
        "minecraft/textures/gui/sprites/widget/button_highlighted.png",
        "minecraft/textures/gui/sprites/widget/button_disabled.png",
        "minecraft/textures/gui/sprites/widget/text_field.png",
        "minecraft/textures/gui/sprites/widget/text_field_highlighted.png",
        "minecraft/textures/gui/sprites/widget/tab.png",
        "minecraft/textures/gui/sprites/widget/tab_selected.png",
        "minecraft/textures/gui/sprites/widget/tab_highlighted.png",
        "minecraft/textures/gui/sprites/widget/tab_selected_highlighted.png",
    };

    if (File.Exists(vanillaClientJarPath))
    {
        using var vanillaClientJar = ZipFile.OpenRead(vanillaClientJarPath);
        foreach (var relativeAssetPath in expectedAssets)
        {
            var entry = vanillaClientJar.GetEntry("assets/" + relativeAssetPath);
            var projectPath = Path.Combine(projectRoot, "assets", relativeAssetPath.Replace('/', Path.DirectorySeparatorChar));
            var identical = false;
            if (entry is not null && File.Exists(projectPath))
            {
                using var stream = entry.Open();
                identical = SHA256.HashData(stream).SequenceEqual(SHA256.HashData(File.ReadAllBytes(projectPath)));
            }

            Check($"项目资产与原版客户端 JAR 一致: {relativeAssetPath}", identical, projectPath);
        }
    }

    // 当前客户端 JAR 中的全景图是 1 x 1 占位项；项目保留了可实际呈现的六张大图，不能用该占位项覆盖。
    foreach (var index in Enumerable.Range(0, 6))
    {
        var relativeAssetPath = $"minecraft/textures/gui/title/background/panorama_{index}.png";
        var projectPath = Path.Combine(projectRoot, "assets", relativeAssetPath.Replace('/', Path.DirectorySeparatorChar));
        var valid = TryReadPngDimensions(projectPath, out var width, out var height) && width >= 16 && height >= 16;
        Check($"项目保留可呈现的原版全景面: {relativeAssetPath}", valid, $"{width}x{height} {projectPath}");
    }

    var overlayPath = Path.Combine(projectRoot, "assets", "minecraft", "textures", "gui", "title", "background", "panorama_overlay.png");
    var validOverlay = TryReadPngDimensions(overlayPath, out var overlayWidth, out var overlayHeight) && overlayWidth == 1 && overlayHeight == 1;
    Check("项目保留有效的原版全景覆盖层", validOverlay, $"{overlayWidth}x{overlayHeight} {overlayPath}");

    var menuRendererPath = Path.Combine(projectRoot, "src", "MyFirstCubitProject.Desktop", "SingleplayerMenuRenderer.cs");
    var menuRendererSource = ReadWorkspaceText(menuRendererPath);
    var subtitlePath = Path.Combine(projectRoot, "assets", "minecraft", "textures", "gui", "title", "cubit_subtitle.png");
    var subtitleDimensionsValid = TryReadPngDimensions(subtitlePath, out var subtitleWidth, out var subtitleHeight) &&
        subtitleWidth == 2171 && subtitleHeight == 274;
    Check(
        "项目拥有 Cubit 副标题 GUI 资产",
        subtitleDimensionsValid,
        $"{subtitleWidth}x{subtitleHeight} {subtitlePath}");
    Check(
        "标题页加载并绘制 Cubit 副标题纹理",
        menuRendererSource.Contains("cubit_subtitle.png", StringComparison.Ordinal) &&
        menuRendererSource.Contains("_textures.Subtitle", StringComparison.Ordinal) &&
        menuRendererSource.Contains("title.subtitle", StringComparison.Ordinal),
        menuRendererPath);
    Check(
        "标题页选项文字使用放大比例而其他菜单保持默认比例",
        menuRendererSource.Contains("textScale: 1.5f", StringComparison.Ordinal) &&
        menuRendererSource.Contains("float textScale = 1f", StringComparison.Ordinal),
        menuRendererPath);
    Check(
        "选择世界和创建世界使用项目菜单背景纹理",
        menuRendererSource.Contains("private void RenderWorldSelection", StringComparison.Ordinal) &&
        menuRendererSource.Contains("private void RenderCreateWorld", StringComparison.Ordinal) &&
        menuRendererSource.Contains("DrawMenuBackground(drawList, viewport)", StringComparison.Ordinal) &&
        menuRendererSource.Contains("assets/minecraft/textures/gui/menu_background.png", StringComparison.Ordinal),
        menuRendererPath);
    Check(
        "死亡界面由项目桌面呈现层绘制并提供重生/标题动作",
        menuRendererSource.Contains("case SingleplayerMenuScreen.Death", StringComparison.Ordinal) &&
        menuRendererSource.Contains("private void RenderDeath", StringComparison.Ordinal) &&
        menuRendererSource.Contains("RespawnPlayer", StringComparison.Ordinal) &&
        menuRendererSource.Contains("death.return-to-title", StringComparison.Ordinal),
        menuRendererPath);
    Check(
        "删除确认由项目桌面呈现层绘制并连接项目控制器",
        menuRendererSource.Contains("RenderDeleteConfirm", StringComparison.Ordinal) &&
        menuRendererSource.Contains("RequestDeleteSelectedWorld", StringComparison.Ordinal) &&
        menuRendererSource.Contains("ConfirmDelete", StringComparison.Ordinal) &&
        menuRendererSource.Contains("0xA8000000u", StringComparison.Ordinal),
        menuRendererPath);
    var panoramaStart = menuRendererSource.IndexOf("var panoramaVisible", StringComparison.Ordinal);
    var panoramaEnd = menuRendererSource.IndexOf("_textures.SetPanorama", panoramaStart, StringComparison.Ordinal);
    var panoramaBlock = panoramaStart >= 0 && panoramaEnd > panoramaStart
        ? menuRendererSource[panoramaStart..panoramaEnd]
        : string.Empty;
    Check(
        "删除确认继续显示全景环绕背景",
        panoramaBlock.Contains("SingleplayerMenuScreen.DeleteConfirm", StringComparison.Ordinal),
        "DeleteConfirm panorama visibility");
    Check(
        "进入世界加载使用旋转全景和黑色遮罩",
        panoramaBlock.Contains("SingleplayerMenuScreen.OpeningWorld", StringComparison.Ordinal) &&
        menuRendererSource.Contains("private void DrawOpeningBackground", StringComparison.Ordinal) &&
        menuRendererSource.Contains("0xA0000000u", StringComparison.Ordinal) &&
        !menuRendererSource.Contains("Tile(drawList, _textures.Dirt", StringComparison.Ordinal),
        "OpeningWorld panorama loading background");
    var loadingDirtPath = Path.Combine(projectRoot, "assets", "minecraft", "textures", "block", "dirt.png");
    Check(
        "项目保留加载备用泥土资产",
        File.Exists(loadingDirtPath) &&
        menuRendererSource.Contains("Loading terrain", StringComparison.Ordinal),
        loadingDirtPath);
    Check(
        "加载错误态提供返回选档动作",
        menuRendererSource.Contains("OpeningProgress", StringComparison.Ordinal) &&
        menuRendererSource.Contains("WorldOpeningStage.Failed", StringComparison.Ordinal) &&
        menuRendererSource.Contains("World could not be loaded", StringComparison.Ordinal) &&
        menuRendererSource.Contains("ReturnToWorldSelection", StringComparison.Ordinal),
        menuRendererPath);

    Assembly? desktopPresentationAssembly = null;
    try
    {
        desktopPresentationAssembly = Assembly.Load(new AssemblyName("MyFirstCubitProject.Desktop"));
    }
    catch (Exception exception)
    {
        Check("项目桌面呈现程序集可加载", false, exception.Message);
    }

    var layoutType = desktopPresentationAssembly?.GetType("MyFirstCubitProject.Desktop.VanillaSingleplayerUiLayout");
    Check("桌面版提供原版逻辑像素布局契约", layoutType is not null, layoutType?.FullName ?? "missing");
    if (layoutType is not null)
    {
        var fit = layoutType.GetMethod("Fit", BindingFlags.Public | BindingFlags.Static, [typeof(Vector2)]);
        var getElementBounds = layoutType.GetMethod("GetElementBounds", BindingFlags.Public | BindingFlags.Static, [typeof(string)]);
        var getTextureSourceUv = layoutType.GetMethod("GetTextureSourceUv", BindingFlags.Public | BindingFlags.Static, [typeof(string)]);
        Check("布局契约公开视口适配、元素边界和纹理裁切接口", fit is not null && getElementBounds is not null && getTextureSourceUv is not null);

        if (fit is not null)
        {
            var viewport = fit.Invoke(null, [new Vector2(1280f, 720f)]);
            var scale = viewport?.GetType().GetProperty("Scale")?.GetValue(viewport);
            var origin = viewport?.GetType().GetProperty("Origin")?.GetValue(viewport);
            Check(
                "1280x720 以 2 倍整数比例承载 640x360 原版 UI",
                scale is float fitScale && Math.Abs(fitScale - 2f) < 0.0001f && origin is Vector2 point && point == Vector2.Zero,
                $"scale={scale} origin={origin}");
        }

        var expectedBounds = new Dictionary<string, Vector4>(StringComparer.Ordinal)
        {
            ["title.logo"] = new(160f, 18f, 320f, 55f),
            ["title.subtitle"] = new(210f, 78f, 220f, 28f),
            ["title.singleplayer"] = new(200f, 138f, 240f, 24f),
            ["title.multiplayer"] = new(200f, 166f, 240f, 24f),
            ["title.realms"] = new(200f, 194f, 240f, 24f),
            ["title.quit"] = new(320f, 230f, 120f, 24f),
            ["select.search"] = new(220f, 22f, 200f, 20f),
            ["select.world-row"] = new(185f, 53f, 270f, 36f),
            ["select.delete"] = new(245f, 332f, 71f, 20f),
            ["delete.confirm"] = new(218f, 214f, 96f, 20f),
            ["delete.cancel"] = new(326f, 214f, 96f, 20f),
            ["create.game-tab"] = new(190f, 0f, 130f, 24f),
            ["create.world-name"] = new(215f, 70f, 210f, 20f),
            ["create.seed"] = new(215f, 118f, 210f, 20f),
            ["pause.return-to-game"] = new(218f, 112f, 204f, 20f),
            ["death.respawn"] = new(218f, 150f, 204f, 20f),
            ["death.return-to-title"] = new(218f, 174f, 204f, 20f),
            ["opening.return-to-selection"] = new(218f, 230f, 204f, 20f),
        };

        foreach (var (elementId, expected) in expectedBounds)
        {
            var actual = getElementBounds?.Invoke(null, [elementId]);
            var vector = actual?.GetType().GetMethod("ToVector4", BindingFlags.Public | BindingFlags.Instance)?.Invoke(actual, null);
            Check(
                $"原版逻辑像素边界: {elementId}",
                vector is Vector4 boundsValue && Vector4.Distance(boundsValue, expected) < 0.0001f,
                $"expected={expected} actual={vector}");
        }

        var logoUv = getTextureSourceUv?.Invoke(null, ["title.logo"]);
        Check(
            "标题只使用 minecraft.png 顶部 176 像素，移除 Java Edition 区域",
            logoUv is Vector4 logoValue && Vector4.Distance(logoValue, new Vector4(0f, 0f, 1f, 176f / 256f)) < 0.0001f,
            $"actual={logoUv}");
    }

    var panoramaProjectionType = desktopPresentationAssembly?.GetType("MyFirstCubitProject.Desktop.VanillaPanoramaProjection");
    Check("桌面版提供原版六面全景投影", panoramaProjectionType is not null, panoramaProjectionType?.FullName ?? "missing");
    if (panoramaProjectionType is not null)
    {
        var faceOrder = panoramaProjectionType.GetProperty("CubeFaceOrder", BindingFlags.Public | BindingFlags.Static)?.GetValue(null) as IReadOnlyList<int>;
        var fullSourceUv = panoramaProjectionType.GetProperty("FullSourceUv", BindingFlags.Public | BindingFlags.Static)?.GetValue(null);
        Check(
            "全景图采用 Minecraft CubeMapTexture 面顺序 _1, _3, _5, _4, _0, _2",
            faceOrder is not null && faceOrder.SequenceEqual([1, 3, 5, 4, 0, 2]),
            faceOrder is null ? "missing" : string.Join(',', faceOrder));
        Check(
            "全景投影不裁切任一源图",
            fullSourceUv is Vector4 panoramaUv && Vector4.Distance(panoramaUv, new Vector4(0f, 0f, 1f, 1f)) < 0.0001f,
            $"actual={fullSourceUv}");
    }

    Console.WriteLine(failures == 0 ? "desktopuicheck 全部通过" : $"desktopuicheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static bool TryReadPngDimensions(string path, out int width, out int height)
{
    width = 0;
    height = 0;
    if (!File.Exists(path))
    {
        return false;
    }

    var bytes = File.ReadAllBytes(path);
    if (bytes.Length < 24 ||
        bytes[0] != 137 || bytes[1] != 80 || bytes[2] != 78 || bytes[3] != 71 ||
        bytes[12] != 73 || bytes[13] != 72 || bytes[14] != 68 || bytes[15] != 82)
    {
        return false;
    }

    width = (bytes[16] << 24) | (bytes[17] << 16) | (bytes[18] << 8) | bytes[19];
    height = (bytes[20] << 24) | (bytes[21] << 16) | (bytes[22] << 8) | bytes[23];
    return width > 0 && height > 0;
}

