static int MenuMusicCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    Check("定位菜单音乐工作区", workspaceRoot is not null, workspaceRoot ?? "missing");
    if (workspaceRoot is null)
    {
        return 1;
    }

    var menuDirectory = Path.Combine(workspaceRoot, "我的第一个cubit项目", "assets", "audio", "minecraft", "menu");
    var assets = new[]
    {
        (FileName: "below_and_above.ogg", Volume: 0.4f, Hash: "29617ea7a07d4c3ed1b98b752b5740b8ca2e7cbf"),
        (FileName: "broken_clocks.ogg", Volume: 0.4f, Hash: "6095be3382a6b9897a7d0caf93131436e5cea4d6"),
        (FileName: "fireflies.ogg", Volume: 0.4f, Hash: "154255dcccfcde8af7e3727a0ccaaa72ea359ff5"),
        (FileName: "lilypad.ogg", Volume: 0.4f, Hash: "b023b1ddac5e027086ef04a9da7234e73a4502a6"),
        (FileName: "os_piano.ogg", Volume: 0.4f, Hash: "a32d22b74e0a451083c99b68a0119b501652ccd8"),
        (FileName: "beginning_2.ogg", Volume: 1f, Hash: "fe440be99066e6efcdb809c00d706bc62a500184"),
        (FileName: "floating_trees.ogg", Volume: 1f, Hash: "3cf507fd0a0288688962bd265839e4a706f5d24b"),
        (FileName: "moog_city_2.ogg", Volume: 1f, Hash: "215583bfda553bb04b5b15ef27d643abfe5fa2f1"),
        (FileName: "mutation.ogg", Volume: 1f, Hash: "f5d6381c34a8154bfd3fdbb67fa87d9fca6794f0"),
    };

    var actualFileNames = Directory.Exists(menuDirectory)
        ? Directory.EnumerateFiles(menuDirectory, "*.ogg", SearchOption.TopDirectoryOnly)
            .Select(Path.GetFileName)
            .OrderBy(fileName => fileName, StringComparer.Ordinal)
            .ToArray()
        : [];
    var expectedFileNames = assets
        .Select(asset => asset.FileName)
        .OrderBy(fileName => fileName, StringComparer.Ordinal)
        .ToArray();
    Check(
        "菜单音乐目录仅包含声明的 OGG 资源",
        actualFileNames.SequenceEqual(expectedFileNames, StringComparer.Ordinal),
        $"expected={string.Join(',', expectedFileNames)} actual={string.Join(',', actualFileNames)}");

    foreach (var asset in assets)
    {
        var path = Path.Combine(menuDirectory, asset.FileName);
        if (!File.Exists(path))
        {
            Check($"菜单音乐资源存在: {asset.FileName}", false, path);
            continue;
        }

        try
        {
            var hash = Convert.ToHexString(SHA1.HashData(File.ReadAllBytes(path))).ToLowerInvariant();
            Check(
                $"菜单音乐资源 SHA1: {asset.FileName}",
                hash == asset.Hash,
                $"volume={asset.Volume} expected={asset.Hash} actual={hash}");
        }
        catch (Exception exception)
        {
            Check($"菜单音乐资源 SHA1: {asset.FileName}", false, exception.Message);
        }
    }

    Assembly? projectAssembly = null;
    try
    {
        projectAssembly = Assembly.Load("MyFirstCubitProject");
        Check("项目程序集可由反射加载", true, projectAssembly.FullName ?? "");
    }
    catch (Exception exception)
    {
        Check("项目程序集可由反射加载", false, exception.Message);
    }

    var catalogType = projectAssembly?.GetType("MyFirstCubitProject.MenuMusicCatalog");
    var controllerType = projectAssembly?.GetType("MyFirstCubitProject.MenuMusicController");
    Check("项目程序集包含菜单音乐类型: MyFirstCubitProject.MenuMusicCatalog", catalogType is not null, "MyFirstCubitProject.MenuMusicCatalog");
    Check("项目程序集包含菜单音乐类型: MyFirstCubitProject.MenuMusicController", controllerType is not null, "MyFirstCubitProject.MenuMusicController");

    if (catalogType is not null && controllerType is not null)
    {
        try
        {
            var catalogConstructor = catalogType.GetConstructor([typeof(string)]);
            var tracksProperty = catalogType.GetProperty("Tracks");
            var tryLoadMethod = catalogType.GetMethod("TryLoad");
            Check(
                "菜单音乐目录公开项目根目录构造与按需加载接口",
                catalogConstructor is not null && tracksProperty is not null && tryLoadMethod is not null,
                $"ctor={catalogConstructor is not null} tracks={tracksProperty is not null} load={tryLoadMethod is not null}");

            if (catalogConstructor is not null && tracksProperty is not null && tryLoadMethod is not null)
            {
                var catalog = catalogConstructor.Invoke([Path.Combine(workspaceRoot, "我的第一个cubit项目")]);
                var tracks = ((tracksProperty.GetValue(catalog) as System.Collections.IEnumerable)?.Cast<object>().ToArray()) ?? [];
                var sourceVolumes = tracks
                    .Select(track => track.GetType().GetProperty("SourceVolume")?.GetValue(track))
                    .OfType<float>()
                    .ToArray();
                Check(
                    "菜单音乐目录保持原版九首曲目与源音量",
                    tracks.Length == 9 && sourceVolumes.Count(volume => Math.Abs(volume - 0.4f) < 0.0001f) == 5 &&
                    sourceVolumes.Count(volume => Math.Abs(volume - 1f) < 0.0001f) == 4,
                    $"tracks={tracks.Length} volumes={string.Join(',', sourceVolumes)}");

                var temporaryRoot = Path.Combine(Path.GetTempPath(), "Cubit.MenuMusicCheck", Guid.NewGuid().ToString("N"));
                try
                {
                    Directory.CreateDirectory(temporaryRoot);
                    var emptyCatalog = catalogConstructor.Invoke([temporaryRoot]);
                    var emptyTracks = ((tracksProperty.GetValue(emptyCatalog) as System.Collections.IEnumerable)?.Cast<object>().ToArray()) ?? [];
                    var loadArguments = new object?[] { emptyTracks.FirstOrDefault(), null, null };
                    var loaded = emptyTracks.Length > 0 && (bool)(tryLoadMethod.Invoke(emptyCatalog, loadArguments) ?? false);
                    Check(
                        "缺失菜单音乐资源返回可诊断失败",
                        !loaded && loadArguments[2] is string { Length: > 0 },
                        loadArguments[2]?.ToString() ?? "missing diagnostic");
                }
                finally
                {
                    if (Directory.Exists(temporaryRoot))
                    {
                        Directory.Delete(temporaryRoot, recursive: true);
                    }
                }

                var reparseRoot = Path.Combine(Path.GetTempPath(), "Cubit.MenuMusicCheck", Guid.NewGuid().ToString("N"));
                var reparseOutside = Path.Combine(Path.GetTempPath(), "Cubit.MenuMusicCheck", Guid.NewGuid().ToString("N"));
                var reparseLink = Path.Combine(reparseRoot, "assets", "audio", "minecraft", "menu");
                try
                {
                    Directory.CreateDirectory(reparseOutside);
                    File.Copy(
                        Path.Combine(menuDirectory, "below_and_above.ogg"),
                        Path.Combine(reparseOutside, "below_and_above.ogg"));
                    Directory.CreateDirectory(Path.GetDirectoryName(reparseLink)!);
                    CreateDirectoryJunction(reparseLink, reparseOutside);
                    var reparseCatalog = catalogConstructor.Invoke([reparseRoot]);
                    var reparseTrack = tracks.FirstOrDefault();
                    var reparseArguments = new object?[] { reparseTrack, null, null };
                    var reparseLoaded = reparseTrack is not null &&
                        (bool)(tryLoadMethod.Invoke(reparseCatalog, reparseArguments) ?? false);
                    Check(
                        "菜单音乐拒绝项目外 Junction 资源",
                        !reparseLoaded && reparseArguments[2] is string { Length: > 0 },
                        reparseArguments[2]?.ToString() ?? "missing diagnostic");
                }
                finally
                {
                    if (Directory.Exists(reparseLink))
                    {
                        DeleteDirectoryJunction(reparseLink);
                    }

                    if (Directory.Exists(reparseRoot))
                    {
                        Directory.Delete(reparseRoot, recursive: true);
                    }

                    if (Directory.Exists(reparseOutside))
                    {
                        Directory.Delete(reparseOutside, recursive: true);
                    }
                }

                var controller = Activator.CreateInstance(controllerType);
                var currentVoiceProperty = controllerType.GetProperty("CurrentVoice");
                var remainingDelayProperty = controllerType.GetProperty("RemainingDelaySeconds");
                var activeProperty = controllerType.GetProperty("Active");
                var controllerConsumer = controller as IEngineContextConsumer;
                Check(
                    "菜单音乐控制器接收引擎上下文并公开调度状态",
                    controller is Node && controllerConsumer is not null && currentVoiceProperty is not null &&
                    remainingDelayProperty is not null && activeProperty?.CanWrite == true,
                    $"node={controller is Node} consumer={controllerConsumer is not null} voice={currentVoiceProperty is not null} remaining={remainingDelayProperty is not null} active={activeProperty?.CanWrite == true}");

                if (controller is Node controllerNode && controllerConsumer is not null && currentVoiceProperty is not null &&
                    remainingDelayProperty is not null && activeProperty?.CanWrite == true)
                {
                    var audioServer = new AudioServer(null, new DiagnosticBag());
                    var context = new EngineContext().AddService(audioServer);
                    var addService = typeof(EngineContext).GetMethods(BindingFlags.Public | BindingFlags.Instance)
                        .Single(method => method.Name == nameof(EngineContext.AddService) && method.IsGenericMethodDefinition)
                        .MakeGenericMethod(catalogType);
                    _ = addService.Invoke(context, [catalog]);
                    controllerConsumer.SetEngineContext(context);

                    using var tree = new SceneTree();
                    tree.Root.AddChild(controllerNode);
                    tree.ProcessFrame(4.99d);
                    Check("菜单音乐首曲在 4.99 秒前不播放", audioServer.Status.ActiveVoiceCount == 0, $"voices={audioServer.Status.ActiveVoiceCount}");

                    tree.ProcessFrame(0.02d);
                    var firstVoice = (AudioPlaybackHandle)(currentVoiceProperty.GetValue(controller) ?? default(AudioPlaybackHandle));
                    Check(
                        "菜单音乐首曲在五秒后创建单个非循环语音",
                        firstVoice.IsValid && audioServer.Status.ActiveVoiceCount == 1,
                        $"voice={firstVoice.Id} voices={audioServer.Status.ActiveVoiceCount}");

                    audioServer.Stop(firstVoice);
                    tree.ProcessFrame(0.01d);
                    var repeatDelay = Convert.ToDouble(remainingDelayProperty.GetValue(controller));
                    Check(
                        "已停止菜单音乐会随机调度一至三十秒重试",
                        repeatDelay >= 1d && repeatDelay <= 30d,
                        $"delay={repeatDelay:F3}");

                    tree.ProcessFrame(repeatDelay + 0.01d);
                    var nextVoice = (AudioPlaybackHandle)(currentVoiceProperty.GetValue(controller) ?? default(AudioPlaybackHandle));
                    Check(
                        "等待重试间隔后创建下一首单曲语音",
                        nextVoice.IsValid && audioServer.Status.ActiveVoiceCount == 1,
                        $"voice={nextVoice.Id} voices={audioServer.Status.ActiveVoiceCount}");

                    activeProperty.SetValue(controller, false);
                    tree.ProcessFrame(0d);
                    Check(
                        "停用菜单音乐会停止当前语音",
                        audioServer.Status.ActiveVoiceCount == 0,
                        $"voices={audioServer.Status.ActiveVoiceCount}");
                }
            }
        }
        catch (Exception exception)
        {
            Check("菜单音乐目录与控制器行为检查未出现反射异常", false, exception.GetType().Name + ": " + exception.Message);
        }
    }
    else
    {
        Console.WriteLine("SKIP  菜单音乐目录与控制器行为检查  项目类型尚未实现");
    }

    var runtimeBootstrapPath = Path.Combine(workspaceRoot, "我的第一个cubit项目", "src", "RuntimeBootstrap.cs");
    var mainScenePath = Path.Combine(workspaceRoot, "我的第一个cubit项目", "scenes", "gameplay.cscene");
    var runtimeBootstrapSource = File.Exists(runtimeBootstrapPath) ? File.ReadAllText(runtimeBootstrapPath) : string.Empty;
    var registrationBody = GetMethodBody(runtimeBootstrapSource, "RegisterProjectTypes");
    var configureRuntimeBody = GetMethodBody(runtimeBootstrapSource, "ConfigureRuntime");
    var configureLoadedSceneBody = GetMethodBody(runtimeBootstrapSource, "ConfigureLoadedScene");
    Check(
        "运行时引导器注册菜单音乐作者节点类型",
        registrationBody.Contains("registry.RegisterNode(() => new MenuMusicController())", StringComparison.Ordinal),
        runtimeBootstrapPath);
    Check(
        "运行时引导器以项目根目录注册菜单音乐目录服务",
        runtimeBootstrapSource.Contains("_projectRoot = project.RootDirectory", StringComparison.Ordinal) &&
        configureRuntimeBody.Contains("context.AddService(new MenuMusicCatalog(_projectRoot", StringComparison.Ordinal),
        runtimeBootstrapPath);
    Check(
        "Scene-First 门禁拒绝在运行时配置中 AddChild 作者节点",
        HasForbiddenMenuMusicAuthorship("root.AddChild(menuMusic);"),
        "root.AddChild(menuMusic);");
    Check(
        "运行时配置不直接创建菜单音乐作者节点",
        !HasForbiddenMenuMusicAuthorship(configureRuntimeBody) &&
        !HasForbiddenMenuMusicAuthorship(configureLoadedSceneBody),
        runtimeBootstrapPath);

    var menuDeclarations = 0;
    try
    {
        var sceneRoot = JsonNode.Parse(File.ReadAllText(mainScenePath));
        menuDeclarations = sceneRoot?["Children"]?.AsArray()
            .Count(child => string.Equals(child?["Type"]?.GetValue<string>(), "MyFirstCubitProject.MenuMusicController", StringComparison.Ordinal)) ?? 0;
    }
    catch (Exception exception)
    {
        Check("主场景可以读取菜单音乐作者节点声明", false, exception.Message);
    }

    Check(
        "主场景在 Root 直接声明一个菜单音乐节点",
        menuDeclarations == 1,
        $"count={menuDeclarations} path={mainScenePath}");

    Console.WriteLine(failures == 0 ? "menumusiccheck 全部通过" : $"menumusiccheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;

    static string GetMethodBody(string source, string methodName)
    {
        var methodStart = source.IndexOf($" {methodName}(", StringComparison.Ordinal);
        if (methodStart < 0)
        {
            return string.Empty;
        }

        var bodyStart = source.IndexOf('{', methodStart);
        if (bodyStart < 0)
        {
            return string.Empty;
        }

        var depth = 0;
        for (var index = bodyStart; index < source.Length; index++)
        {
            if (source[index] == '{')
            {
                depth++;
            }
            else if (source[index] == '}' && --depth == 0)
            {
                return source.Substring(bodyStart, index - bodyStart + 1);
            }
        }

        return string.Empty;
    }

    static bool HasForbiddenMenuMusicAuthorship(string methodBody) =>
        methodBody.Contains("new MenuMusicController", StringComparison.Ordinal) ||
        methodBody.Contains("AddChild(", StringComparison.Ordinal);
}

static int AudioCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    Assembly? audioAssembly = null;
    try
    {
        audioAssembly = Assembly.Load("Cubit.Audio");
        Check("Cubit.Audio assembly loadable", true, audioAssembly.FullName ?? "");
    }
    catch (Exception exception)
    {
        Check("Cubit.Audio assembly loadable", false, exception.Message);
    }

    foreach (var typeName in new[]
    {
        "Cubit.Audio.CubitAudioPlugin",
        "Cubit.Audio.AudioClip",
        "Cubit.Audio.AudioServer",
        "Cubit.Audio.AudioBus",
        "Cubit.Audio.AudioPlayer",
        "Cubit.Audio.AudioPlayer3D",
        "Cubit.Audio.IAudioOutputBackend",
    })
    {
        Check($"Audio type exists: {typeName}", audioAssembly?.GetType(typeName) is not null);
    }

    var audioReferences = typeof(CubitAudioPlugin).Assembly.GetReferencedAssemblies()
        .Select(reference => reference.Name)
        .Where(name => name is not null && name.StartsWith("Cubit.", StringComparison.Ordinal))
        .ToArray();
    Check("Cubit.Audio references only Cubit.Core", audioReferences.SequenceEqual(["Cubit.Core"]), string.Join(',', audioReferences));
    Check("AudioPlayer3D inherits Node3D", typeof(AudioPlayer3D).IsSubclassOf(typeof(Node3D)));

    var plugin = new CubitAudioPlugin();
    Check("CubitAudioPlugin reports stable identity", plugin.Id == "cubit.audio" && plugin.Version == new Version(1, 0, 0));
    using (var manager = CreateToolPluginManager([plugin]))
    {
        manager.Configure([new CubitPluginReference { Id = "cubit.audio", Version = "1.0.0" }]);
        Check("CubitAudioPlugin registers clip and player node types", manager.Registry.Registrations.Count == 3);
        var context = new EngineContext();
        plugin.Start(context);
        var missingBackend = plugin.Diagnostics.Snapshot();
        Check(
            "CubitAudioPlugin reports a missing output backend without creating a thread",
            plugin.Server is not null && missingBackend.Length == 1 && missingBackend[0].Code == "audio.backend.missing");
        Check("CubitAudioPlugin rejects duplicate start", CaptureException(() => plugin.Start(context)) is InvalidOperationException);

        var source = new[] { 0.25f, -0.5f };
        var clip = new AudioClip(source);
        source[0] = 99f;
        Check("AudioClip snapshots finite stereo PCM", clip.FrameCount == 1 && clip.Samples[0] is 0.25f);
        Check("AudioClip rejects non-finite samples", CaptureException(() => new AudioClip([float.NaN, 0f])) is ArgumentException);
        Check("AudioClip rejects non-stereo format", CaptureException(() => new AudioClip([0f, 0f], 44_100, 2)) is ArgumentException);

        var wavFactory = typeof(AudioClip).GetMethod(
            "FromWav",
            BindingFlags.Public | BindingFlags.Static,
            binder: null,
            types: [typeof(byte[])],
            modifiers: null);
        var wavClip = wavFactory?.Invoke(null, [BuildPcm16Wav([short.MinValue, short.MaxValue])]) as AudioClip;
        Check(
            "AudioClip imports 48 kHz stereo PCM16 WAV without a hidden conversion stage",
            wavClip is { SampleRate: AudioFormat.SampleRate, Channels: AudioFormat.Channels, FrameCount: 1 } &&
            MathF.Abs(wavClip.Samples[0] + 1f) < 0.0001f &&
            MathF.Abs(wavClip.Samples[1] - (short.MaxValue / 32768f)) < 0.0001f);
        var incompatibleWavError = wavFactory is null
            ? null
            : CaptureException(() => wavFactory.Invoke(null, [BuildPcm16Wav([0, 0], sampleRate: 44_100)]));
        Check(
            "AudioClip rejects WAV that would require implicit resampling",
            incompatibleWavError is TargetInvocationException { InnerException: ArgumentException });
        var truncatedWavError = wavFactory is null
            ? null
            : CaptureException(() => wavFactory.Invoke(null, [BuildPcm16Wav([0, 0])[..20]]));
        Check(
            "AudioClip rejects truncated WAV headers and chunks",
            truncatedWavError is TargetInvocationException { InnerException: ArgumentException });

        // 使用反射保持自检可编译，直到 OGG/Vorbis 导入 API 按契约落地。
        var oggFactory = typeof(AudioClip).GetMethod(
            "FromOggVorbis",
            BindingFlags.Public | BindingFlags.Static,
            binder: null,
            types: [typeof(byte[])],
            modifiers: null);
        Check(
            "AudioClip exposes an explicit OGG/Vorbis import API",
            oggFactory is not null);
        var invalidOggError = oggFactory is null
            ? null
            : CaptureException(() => oggFactory.Invoke(null, new object?[] { new byte[] { 0x4F, 0x67, 0x67, 0x53 } }));
        Check(
            "AudioClip rejects invalid OGG/Vorbis data deterministically",
            invalidOggError is TargetInvocationException { InnerException: ArgumentException },
            invalidOggError?.GetBaseException().GetType().Name ?? "");

        var localMinecraftMusicPath = FindLocalMinecraftMusicOgg();
        if (localMinecraftMusicPath is null)
        {
            Console.WriteLine("SKIP  AudioClip imports local Minecraft OGG/Vorbis fixture  local fixture unavailable");
        }
        else
        {
            var localMinecraftMusic = File.ReadAllBytes(localMinecraftMusicPath);
            var sourceSampleRate = ReadVorbisIdentificationSampleRate(localMinecraftMusic);
            AudioClip? oggClip = null;
            var oggClipError = oggFactory is null
                ? null
                : CaptureException(() => oggClip = oggFactory.Invoke(null, [localMinecraftMusic]) as AudioClip);
            Check(
                "AudioClip imports local Minecraft OGG/Vorbis into canonical PCM",
                oggClipError is null && sourceSampleRate == 44_100 &&
                oggClip is { SampleRate: AudioFormat.SampleRate, Channels: AudioFormat.Channels } &&
                oggClip.FrameCount > 0 &&
                oggClip.Samples.Any(sample => float.IsFinite(sample) && MathF.Abs(sample) > 0.001f),
                $"error={oggClipError?.GetBaseException().GetType().Name} source={sourceSampleRate} output={oggClip?.SampleRate} frames={oggClip?.FrameCount}");
        }

        var restoredClip = Resource.FromJson<AudioClip>(clip.ToJson());
        Check(
            "AudioClip resource JSON preserves PCM samples",
            restoredClip.FrameCount == clip.FrameCount && restoredClip.Samples.SequenceEqual(clip.Samples));
        var serializedAudioPlayer = new AudioPlayer { Name = "SerializedAudio", Clip = clip };
        var serializedScene = SceneIO.SerializeToJson(serializedAudioPlayer);
        var restoredAudioPlayer = SceneIO.DeserializeFromJson(
            serializedScene,
            type => type == typeof(AudioPlayer).FullName
                ? new AudioPlayer()
                : throw new InvalidOperationException($"Unexpected scene type: {type}")) as AudioPlayer;
        Check(
            "AudioPlayer scene JSON preserves its AudioClip",
            restoredAudioPlayer?.Clip is { } restoredSceneClip && restoredSceneClip.Samples.SequenceEqual(clip.Samples));

        Check(
            "AudioPlayer rejects non-finite and out-of-range configuration at assignment",
            CaptureException(() => serializedAudioPlayer.Volume = float.NaN) is ArgumentOutOfRangeException &&
            CaptureException(() => serializedAudioPlayer.Volume = -0.1f) is ArgumentOutOfRangeException &&
            CaptureException(() => serializedAudioPlayer.Pan = float.PositiveInfinity) is ArgumentOutOfRangeException &&
            CaptureException(() => serializedAudioPlayer.Pan = 1.1f) is ArgumentOutOfRangeException);

        Check(
            "AudioPlayer3D rejects non-finite and invalid distance configuration at assignment",
            CaptureException(() =>
            {
                var invalidPlayer = new AudioPlayer3D();
                invalidPlayer.Volume = float.PositiveInfinity;
            }) is ArgumentOutOfRangeException &&
            CaptureException(() =>
            {
                var invalidPlayer = new AudioPlayer3D();
                invalidPlayer.MinDistance = -1f;
            }) is ArgumentOutOfRangeException &&
            CaptureException(() =>
            {
                var invalidPlayer = new AudioPlayer3D();
                invalidPlayer.MaxDistance = 0f;
            }) is ArgumentOutOfRangeException &&
            CaptureException(() =>
            {
                var invalidPlayer = new AudioPlayer3D { MaxDistance = 5f };
                invalidPlayer.MinDistance = 5f;
            }) is ArgumentOutOfRangeException);

        using (var configurationTree = new SceneTree())
        {
            var configuredPlayer = new AudioPlayer { Name = "ConfigurationThreadGuard", Clip = clip };
            var configuredPlayer3D = new AudioPlayer3D { Name = "Configuration3DThreadGuard", Clip = clip };
            configurationTree.Root.AddChild(configuredPlayer);
            configurationTree.Root.AddChild(configuredPlayer3D);

            Exception? offThreadPlayerConfiguration = null;
            Exception? offThreadPlayer3DConfiguration = null;
            var configurationWorker = new Thread(() =>
            {
                offThreadPlayerConfiguration = CaptureException(() => configuredPlayer.Volume = 0.5f);
                offThreadPlayer3DConfiguration = CaptureException(() => configuredPlayer3D.MinDistance = 2f);
            });
            configurationWorker.Start();
            configurationWorker.Join();
            Check(
                "AudioPlayer configuration rejects worker writes after entering the scene tree",
                offThreadPlayerConfiguration is InvalidOperationException && configuredPlayer.Volume == 1f,
                $"error={offThreadPlayerConfiguration?.GetType().Name} volume={configuredPlayer.Volume}");
            Check(
                "AudioPlayer3D configuration rejects worker writes after entering the scene tree",
                offThreadPlayer3DConfiguration is InvalidOperationException && configuredPlayer3D.MinDistance == 1f,
                $"error={offThreadPlayer3DConfiguration?.GetType().Name} min={configuredPlayer3D.MinDistance}");

            configuredPlayer3D.AttachServer(plugin.Server!);
            configuredPlayer3D.Play();
            Exception?[]? offThreadAudioReads = null;
            var readWorker = new Thread(() =>
            {
                offThreadAudioReads =
                [
                    CaptureException(() => { _ = configuredPlayer.Clip; }),
                    CaptureException(() => { _ = configuredPlayer.BusName; }),
                    CaptureException(() => { _ = configuredPlayer.Volume; }),
                    CaptureException(() => { _ = configuredPlayer.Pan; }),
                    CaptureException(() => { _ = configuredPlayer.Loop; }),
                    CaptureException(() => { _ = configuredPlayer.Autoplay; }),
                    CaptureException(() => { _ = configuredPlayer.IsPlaying; }),
                    CaptureException(() => { _ = configuredPlayer3D.Clip; }),
                    CaptureException(() => { _ = configuredPlayer3D.BusName; }),
                    CaptureException(() => { _ = configuredPlayer3D.Volume; }),
                    CaptureException(() => { _ = configuredPlayer3D.Loop; }),
                    CaptureException(() => { _ = configuredPlayer3D.Autoplay; }),
                    CaptureException(() => { _ = configuredPlayer3D.MinDistance; }),
                    CaptureException(() => { _ = configuredPlayer3D.MaxDistance; }),
                    CaptureException(() => { _ = configuredPlayer3D.IsPlaying; }),
                    CaptureException(() => { _ = plugin.Server!.IsClosed; }),
                ];
            });
            readWorker.Start();
            readWorker.Join();
            Check(
                "Audio runtime public reads reject worker access after entering the scene tree",
                offThreadAudioReads is { Length: 16 } && offThreadAudioReads.All(error => error is InvalidOperationException),
                string.Join(',', offThreadAudioReads?.Select(error => error?.GetType().Name ?? "none") ?? []));
        }

        var handle = plugin.Server!.Play(clip);
        var output = new float[2];
        plugin.Server.Mix(output);
        Check("AudioServer mixes a clip into a stereo buffer", output.SequenceEqual([0.25f, -0.5f]));
        plugin.Server.Mix(output);
        Check("AudioServer marks a non-looping voice complete", !plugin.Server.IsPlaying(handle) && output.SequenceEqual([0f, 0f]));

        var voicesField = typeof(AudioServer).GetField("_voices", BindingFlags.Instance | BindingFlags.NonPublic);
        var voicesBeforePrune = (voicesField?.GetValue(plugin.Server) as System.Collections.IDictionary)?.Count;
        var finishedVoice = (voicesField?.GetValue(plugin.Server) as System.Collections.IDictionary)?.Values
            .Cast<object>()
            .SingleOrDefault();
        var finishedClip = finishedVoice?.GetType().GetProperty("Clip")?.GetValue(finishedVoice);
        Check(
            "AudioServer releases completed one-shot sample ownership on the callback thread",
            finishedClip is null,
            finishedClip?.GetType().Name ?? "null");
        _ = plugin.Server.Status;
        var voicesAfterPrune = (voicesField?.GetValue(plugin.Server) as System.Collections.IDictionary)?.Count;
        Check(
            "AudioServer prunes completed one-shot voices at a main-thread status boundary",
            voicesBeforePrune == 1 && voicesAfterPrune == 0,
            $"before={voicesBeforePrune} after={voicesAfterPrune}");

        var lifecycleServer = new AudioServer(null, new DiagnosticBag());
        using (var lifecycleTree = new SceneTree())
        {
            var lifecyclePlayer = new AudioPlayer { Name = "OneShot", Clip = clip };
            lifecyclePlayer.AttachServer(lifecycleServer);
            lifecycleTree.Root.AddChild(lifecyclePlayer);
            lifecyclePlayer.Play();
            lifecycleServer.Mix(output);
            lifecycleTree.ProcessFrame(1d / 60d);
            var retainedVoiceCount = (voicesField?.GetValue(lifecycleServer) as System.Collections.IDictionary)?.Count;
            Check(
                "AudioPlayer reclaims a naturally completed voice during its next process frame",
                !lifecyclePlayer.IsPlaying && retainedVoiceCount == 0,
                $"voices={retainedVoiceCount}");
        }

        var maintenanceServer = new AudioServer(null, new DiagnosticBag());
        maintenanceServer.Play(clip);
        maintenanceServer.Mix(output);
        Check(
            "AudioServer exposes an explicit main-thread voice maintenance point",
            maintenanceServer.Maintain() &&
            (voicesField?.GetValue(maintenanceServer) as System.Collections.IDictionary)?.Count == 0);

        var firstServer = new AudioServer(null, new DiagnosticBag());
        var secondServer = new AudioServer(null, new DiagnosticBag());
        using (var attachTree = new SceneTree())
        {
            var attachedPlayer = new AudioPlayer { Name = "Reattached", Clip = clip, Loop = true };
            attachedPlayer.AttachServer(firstServer);
            attachTree.Root.AddChild(attachedPlayer);
            attachedPlayer.Play();
            attachedPlayer.AttachServer(secondServer);
            var firstVoiceCount = (voicesField?.GetValue(firstServer) as System.Collections.IDictionary)?.Count;
            attachedPlayer.Stop();
            Check(
                "AudioPlayer detaches the old server voice before reattachment",
                firstVoiceCount == 0 && (voicesField?.GetValue(secondServer) as System.Collections.IDictionary)?.Count == 0,
                $"old={firstVoiceCount} new={(voicesField?.GetValue(secondServer) as System.Collections.IDictionary)?.Count}");
        }

        var loopHandle = plugin.Server.Play(new AudioClip([0.25f, 0.5f, 0.75f, 1f]), loop: true);
        var loopOutput = new float[6];
        plugin.Server.Mix(loopOutput);
        Check("AudioServer wraps looping voices deterministically", loopOutput.SequenceEqual([0.25f, 0.5f, 0.75f, 1f, 0.25f, 0.5f]));
        plugin.Server.Stop(loopHandle);

        plugin.Server.CreateBus("Effects", volume: 0.5f);
        plugin.Server.Play(new AudioClip([0.5f, 1f]), busName: "Effects");
        plugin.Server.Mix(output);
        Check("AudioServer mixes a named bus with its published gain", output.SequenceEqual([0.25f, 0.5f]));
        plugin.Server.SetBusMuted("Effects", true);
        plugin.Server.Play(new AudioClip([0.5f, 1f]), busName: "Effects");
        plugin.Server.Mix(output);
        Check("AudioServer publishes muted bus silence without callback branching state", output.SequenceEqual([0f, 0f]));

        using (var audioTree = new SceneTree())
        {
            var player = new AudioPlayer { Name = "Music", Clip = clip };
            player.AttachServer(plugin.Server);
            audioTree.Root.AddChild(player);
            player.Play();
            plugin.Server.Mix(output);
            Check("AudioPlayer plays through an explicitly attached server", output.SequenceEqual([0.25f, -0.5f]));

            plugin.Server.SetListenerPosition(Vector3.Zero);
            var player3D = new AudioPlayer3D
            {
                Name = "Emitter",
                Position = new Vector3(10f, 0f, 0f),
                Clip = clip,
                MaxDistance = 20f,
            };
            player3D.AttachServer(plugin.Server);
            audioTree.Root.AddChild(player3D);
            player3D.Play();
            plugin.Server.Mix(output);
            Check(
                "AudioPlayer3D applies distance attenuation and right pan",
                MathF.Abs(output[0]) < 0.0001f && output[1] < -0.25f && output[1] > -0.27f,
                $"left={output[0]} right={output[1]}");
        }

        var oneShot3DServer = new AudioServer(null, new DiagnosticBag());
        using (var oneShot3DTree = new SceneTree())
        {
            var oneShot3D = new AudioPlayer3D { Name = "OneShot3D", Clip = clip };
            oneShot3D.AttachServer(oneShot3DServer);
            oneShot3DTree.Root.AddChild(oneShot3D);
            oneShot3D.Play();
            oneShot3DServer.Mix(output);
            oneShot3DTree.ProcessFrame(1d / 60d);
            var retainedVoiceCount = (voicesField?.GetValue(oneShot3DServer) as System.Collections.IDictionary)?.Count;
            Check(
                "AudioPlayer3D reclaims a naturally completed voice during its next process frame",
                !oneShot3D.IsPlaying && retainedVoiceCount == 0,
                $"voices={retainedVoiceCount}");
        }

        var overflowServer = new AudioServer(null, new DiagnosticBag());
        overflowServer.CreateBus("Overflow", float.MaxValue);
        Check(
            "AudioServer rejects a volume and bus gain combination that would overflow the mixer",
            CaptureException(() => overflowServer.Play(clip, float.MaxValue, busName: "Overflow")) is ArgumentOutOfRangeException);

        using (var staticAudioTree = new SceneTree())
        {
            var snapshotField = typeof(AudioServer).GetField(
                "_snapshot",
                BindingFlags.Instance | BindingFlags.NonPublic);
            Check("AudioServer exposes a private published snapshot for regression observation", snapshotField is not null);
            var staticPlayer = new AudioPlayer
            {
                Name = "StaticLoop",
                Clip = clip,
                Loop = true,
            };
            staticPlayer.AttachServer(plugin.Server);
            staticAudioTree.Root.AddChild(staticPlayer);
            staticPlayer.Play();
            staticAudioTree.ProcessFrame(1d / 60d);
            var staticSnapshotBefore = snapshotField?.GetValue(plugin.Server);
            for (var frame = 0; frame < 120; frame++)
            {
                staticAudioTree.ProcessFrame(1d / 60d);
            }

            var staticSnapshotAfter = snapshotField?.GetValue(plugin.Server);
            Check(
                "AudioPlayer 静止循环帧不重复提交参数或重建快照",
                staticSnapshotBefore is not null && ReferenceEquals(staticSnapshotBefore, staticSnapshotAfter));

            staticPlayer.Stop();
            staticPlayer.Volume = 0.5f;
            staticPlayer.Play();
            plugin.Server.Mix(output);
            Check(
                "AudioPlayer Stop/Play resets cached parameters",
                MathF.Abs(output[0] - 0.125f) < 0.0001f && MathF.Abs(output[1] + 0.25f) < 0.0001f);
        }

        GC.Collect();
        var allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        for (var frame = 0; frame < 120; frame++)
        {
            plugin.Server.Mix(output);
        }

        var allocated = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
        Check("AudioServer mix callback performs no managed allocations", allocated == 0, $"bytes={allocated}");

        var mixGateField = typeof(AudioServer).GetField("_mixInProgress", BindingFlags.Instance | BindingFlags.NonPublic);
        var concurrentServer = new AudioServer(null, new DiagnosticBag());
        concurrentServer.Play(new AudioClip(new float[2]), loop: true);
        var longOutput = new float[2 * 2_000_000];
        Exception? concurrentMixError = null;
        var concurrentWorker = new Thread(() =>
        {
            try
            {
                concurrentServer.Mix(longOutput);
            }
            catch (Exception exception)
            {
                concurrentMixError = exception;
            }
        });
        concurrentWorker.Start();
        var enteredMix = SpinWait.SpinUntil(
            () => mixGateField?.GetValue(concurrentServer) is int value && value == 1,
            TimeSpan.FromSeconds(1));
        var overlappingMixError = enteredMix ? CaptureException(() => concurrentServer.Mix(output)) : null;
        concurrentWorker.Join();
        Check(
            "AudioServer rejects concurrent device callbacks instead of racing voice cursors",
            enteredMix && overlappingMixError is InvalidOperationException && concurrentMixError is null,
            $"entered={enteredMix} overlap={overlappingMixError?.GetType().Name} worker={concurrentMixError?.GetType().Name}");

        Exception? offThread = null;
        var worker = new Thread(() => offThread = CaptureException(() => plugin.Server.Play(clip)));
        worker.Start();
        worker.Join();
        Check("AudioServer rejects off-thread playback commands", offThread is InvalidOperationException);
        plugin.Stop();
        plugin.Stop();
        Check("CubitAudioPlugin Stop is idempotent", !plugin.IsStarted && plugin.Server is null);
    }

    var backendPlugin = new CubitAudioPlugin();
    using (var backendManager = CreateToolPluginManager([backendPlugin]))
    {
        backendManager.Configure([new CubitPluginReference { Id = "cubit.audio", Version = "1.0.0" }]);
        var backendContext = new EngineContext();
        var backend = new AudioProbeBackend();
        backendContext.AddService<IAudioOutputBackend>(backend);
        backendPlugin.Start(backendContext);
        var retainedServer = backendPlugin.Server!;
        var activeServiceRegistered = backendContext.TryGetService<AudioServer>(out var activeAudioService) &&
            ReferenceEquals(activeAudioService, retainedServer);
        var backendClip = new AudioClip([0.25f, -0.5f]);
        using var retainedTree = new SceneTree();
        var retainedPlayer = new AudioPlayer { Name = "RetainedAfterStop", Clip = backendClip, Loop = true };
        retainedPlayer.AttachServer(retainedServer);
        retainedTree.Root.AddChild(retainedPlayer);
        retainedPlayer.Play();
        retainedServer.Render(new float[2]);
        Check("AudioServer submits rendered PCM to the explicit backend", backend.SubmitCount == 1);
        backendPlugin.Stop();
        var closedPlay = CaptureException(() => retainedPlayer.Play());
        var releasedService = !backendContext.TryGetService<AudioServer>(out _);
        var releasedBackend = !backendContext.TryGetService<IAudioOutputBackend>(out _);
        Check(
            "CubitAudioPlugin Stop closes the server and releases both owned services",
            activeServiceRegistered && backend.DisposeCount == 1 && retainedServer.IsClosed &&
            closedPlay is InvalidOperationException && releasedService && releasedBackend,
            $"registered={activeServiceRegistered} dispose={backend.DisposeCount} closed={retainedServer.IsClosed} serverReleased={releasedService} backendReleased={releasedBackend} error={closedPlay?.GetType().Name}");

        if (releasedBackend)
        {
            var replacementBackend = new AudioProbeBackend();
            backendContext.AddService<IAudioOutputBackend>(replacementBackend);
            backendPlugin.Start(backendContext);
            backendPlugin.Server!.Render(new float[2]);
            Check(
                "CubitAudioPlugin 可在替换输出后重启",
                replacementBackend.SubmitCount == 1,
                $"submits={replacementBackend.SubmitCount}");
            backendPlugin.Stop();
        }
        else
        {
            Check("CubitAudioPlugin 可在替换输出后重启", false, "停止后仍保留已关闭的 IAudioOutputBackend");
        }
    }

    var offThreadStopPlugin = new CubitAudioPlugin();
    var offThreadStopContext = new EngineContext();
    var offThreadStopBackend = new AudioProbeBackend();
    offThreadStopContext.AddService<IAudioOutputBackend>(offThreadStopBackend);
    offThreadStopPlugin.Start(offThreadStopContext);
    var offThreadStopServer = offThreadStopPlugin.Server;
    Exception? offThreadStopError = null;
    var stopWorker = new Thread(() => offThreadStopError = CaptureException(offThreadStopPlugin.Stop));
    stopWorker.Start();
    stopWorker.Join();
    var stopStateIntact = offThreadStopServer is not null &&
        ReferenceEquals(offThreadStopPlugin.Server, offThreadStopServer) &&
        offThreadStopPlugin.IsStarted &&
        offThreadStopContext.TryGetService<AudioServer>(out var registeredAfterRejectedStop) &&
        ReferenceEquals(registeredAfterRejectedStop, offThreadStopServer);
    Check(
        "CubitAudioPlugin 拒绝后台 Stop 时保持服务状态完整",
        offThreadStopError is InvalidOperationException && stopStateIntact,
        $"error={offThreadStopError?.GetType().Name} started={offThreadStopPlugin.IsStarted} server={offThreadStopPlugin.Server is not null}");
    if (stopStateIntact)
    {
        offThreadStopPlugin.Stop();
    }
    else
    {
        if (offThreadStopContext.TryGetService<AudioServer>(out var strandedServer) && strandedServer is not null)
        {
            offThreadStopContext.RemoveService(strandedServer);
            strandedServer.Dispose();
        }

        if (offThreadStopContext.TryGetService<IAudioOutputBackend>(out var strandedBackend) && strandedBackend is not null)
        {
            offThreadStopContext.RemoveService(strandedBackend);
        }
    }

    var duplicateBackend = new AudioProbeBackend();
    var duplicateExistingServer = new AudioServer(duplicateBackend, new DiagnosticBag());
    var duplicateContext = new EngineContext()
        .AddService<IAudioOutputBackend>(duplicateBackend)
        .AddService(duplicateExistingServer);
    var duplicatePlugin = new CubitAudioPlugin();
    var duplicateStartError = CaptureException(() => duplicatePlugin.Start(duplicateContext));
    Check(
        "CubitAudioPlugin 重复注册不会关闭宿主已有音频服务",
        duplicateStartError is InvalidOperationException &&
        !duplicateExistingServer.IsClosed &&
        duplicateBackend.DisposeCount == 0,
        $"error={duplicateStartError?.GetType().Name} closed={duplicateExistingServer.IsClosed} dispose={duplicateBackend.DisposeCount}");
    duplicateExistingServer.Dispose();

    var orientationServer = new AudioServer(null, new DiagnosticBag());
    var orientationClip = new AudioClip([0.25f, -0.5f]);
    var orientationOutput = new float[2];
    var orientationMethod = typeof(AudioServer).GetMethod("SetListenerOrientation", [typeof(Vector3), typeof(Vector3)]);
    var orientationError = orientationMethod is null
        ? null
        : CaptureException(() => orientationMethod.Invoke(orientationServer, [Vector3.UnitZ, Vector3.UnitY]));
    using (var orientationTree = new SceneTree())
    {
        var orientedPlayer = new AudioPlayer3D
        {
            Name = "OrientedEmitter",
            Position = new Vector3(10f, 0f, 0f),
            Clip = orientationClip,
            MaxDistance = 20f,
        };
        orientedPlayer.AttachServer(orientationServer);
        orientationTree.Root.AddChild(orientedPlayer);
        var orientedPlayError = CaptureException(orientedPlayer.Play);
        orientationServer.Mix(orientationOutput);
        Check(
            "AudioPlayer3D applies listener orientation to panning",
            orientationMethod is not null && orientationError is null && orientedPlayError is null && orientationOutput[0] > 0.12f && MathF.Abs(orientationOutput[1]) < 0.0001f,
            $"method={orientationMethod is not null} setup={orientationError?.GetType().Name} play={orientedPlayError?.GetType().Name} left={orientationOutput[0]} right={orientationOutput[1]}");
    }

    var overflowDiagnostics = new DiagnosticBag();
    var overflowMixServer = new AudioServer(null, overflowDiagnostics);
    overflowMixServer.Play(new AudioClip([float.MaxValue, float.MaxValue]), loop: true);
    var overflowOutput = new float[2];
    var overflowMixError = CaptureException(() => overflowMixServer.Mix(overflowOutput));
    Check(
        "AudioServer keeps mixed PCM finite and normalized",
        overflowMixError is null && overflowOutput.All(sample => float.IsFinite(sample) && sample is >= -1f and <= 1f),
        $"error={overflowMixError?.GetType().Name} output={string.Join(',', overflowOutput)}");

    var failingBackendDiagnostics = new DiagnosticBag();
    var failingBackendServer = new AudioServer(new ThrowingAudioBackend(), failingBackendDiagnostics);
    failingBackendServer.Play(orientationClip);
    var backendSubmitError = CaptureException(() => failingBackendServer.Render(new float[2]));
    Check(
        "AudioServer converts backend submit failures into diagnostics",
        backendSubmitError is null && failingBackendDiagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.submit-failed"),
        $"error={backendSubmitError?.GetType().Name}:{backendSubmitError?.Message} diagnostics={string.Join(',', failingBackendDiagnostics.Snapshot().Select(diagnostic => diagnostic.Code))}");

    var renderThreadBackend = new AudioProbeBackend();
    var renderThreadServer = new AudioServer(renderThreadBackend, new DiagnosticBag());
    Exception? offThreadRenderError = null;
    var renderWorker = new Thread(() =>
        offThreadRenderError = CaptureException(() => renderThreadServer.Render(new float[2])));
    renderWorker.Start();
    renderWorker.Join();
    Check(
        "AudioServer rejects off-thread Render before submitting to the backend",
        offThreadRenderError is InvalidOperationException && renderThreadBackend.SubmitCount == 0,
        $"error={offThreadRenderError?.GetType().Name} submits={renderThreadBackend.SubmitCount}");

    var framePumpThreadBackend = new AudioProbeBackend();
    var framePumpThreadServer = new AudioServer(framePumpThreadBackend, new DiagnosticBag());
    var framePumpThreadGuard = new AudioFramePump(framePumpThreadServer);
    Exception? offThreadFramePumpError = null;
    var framePumpWorker = new Thread(() =>
        offThreadFramePumpError = CaptureException(() => framePumpThreadGuard.RenderFrame(1d / AudioFormat.SampleRate)));
    framePumpWorker.Start();
    framePumpWorker.Join();
    Check(
        "AudioFramePump rejects off-thread frame submission without advancing output",
        offThreadFramePumpError is InvalidOperationException && framePumpThreadBackend.SubmitCount == 0,
        $"error={offThreadFramePumpError?.GetType().Name} submits={framePumpThreadBackend.SubmitCount}");
    framePumpThreadGuard.RenderFrame(1d / AudioFormat.SampleRate);
    Check(
        "AudioFramePump remains usable from its owning thread after a rejected worker call",
        framePumpThreadBackend.SubmitCount == 1,
        $"submits={framePumpThreadBackend.SubmitCount}");

    var sceneBindingType = typeof(CubitAudioPlugin).Assembly.GetType("Cubit.Audio.AudioSceneBinding");
    var framePumpType = typeof(CubitAudioPlugin).Assembly.GetType("Cubit.Audio.AudioFramePump");
    Check(
        "Audio exposes explicit scene binding and frame pump contracts",
        sceneBindingType is not null && framePumpType is not null,
        $"binding={sceneBindingType is not null} pump={framePumpType is not null}");
    if (sceneBindingType is not null && framePumpType is not null)
    {
        var hostBackend = new AudioProbeBackend();
        var hostPlugin = new CubitAudioPlugin();
        using var hostManager = CreateToolPluginManager([hostPlugin]);
        hostManager.Configure([new CubitPluginReference { Id = "cubit.audio", Version = "1.0.0" }]);
        var hostContext = new EngineContext().AddService<IAudioOutputBackend>(hostBackend);
        hostManager.Start(hostContext);
        using var hostTree = new SceneTree();
        var container = new Node { Name = "AudioContainer" };
        var hostPlayer = new AudioPlayer { Name = "HostPlayer", Clip = new AudioClip([0.4f, -0.4f]) };
        container.AddChild(hostPlayer);
        hostTree.Root.AddChild(container);
        var bindMethod = sceneBindingType.GetMethod("Attach", BindingFlags.Public | BindingFlags.Static);
        var bindError = bindMethod is null ? null : CaptureException(() => bindMethod.Invoke(null, [hostTree.Root, hostPlugin.Server!]));
        var hostPlayError = CaptureException(hostPlayer.Play);
        var pump = Activator.CreateInstance(framePumpType, hostPlugin.Server!, 1024);
        var pumpMethod = framePumpType.GetMethod("RenderFrame", BindingFlags.Public | BindingFlags.Instance);
        var halfFrameError = pumpMethod is null || pump is null
            ? null
            : CaptureException(() => pumpMethod.Invoke(pump, [1d / (AudioFormat.SampleRate * 2)]));
        var fullFrameError = pumpMethod is null || pump is null
            ? null
            : CaptureException(() => pumpMethod.Invoke(pump, [1d / (AudioFormat.SampleRate * 2)]));
    Check(
        "Audio scene binding recursively attaches players and frame pump accumulates PCM frames",
            bindMethod is not null && bindError is null && hostPlayError is null &&
            pumpMethod is not null && halfFrameError is null && fullFrameError is null &&
            hostBackend.SubmitCount == 1 && hostBackend.LastSamples.SequenceEqual([0.4f, -0.4f]),
            $"bind={bindError?.GetType().Name} play={hostPlayError?.GetType().Name} render={halfFrameError?.GetType().Name}/{fullFrameError?.GetType().Name} submits={hostBackend.SubmitCount}");
    }

    var gameSceneConstructor = typeof(GameScene).GetConstructor([
        typeof(IRenderBackend),
        typeof(CubitProject),
        typeof(InputServer),
        typeof(IAudioOutputBackend),
        typeof(JobSystemOptions),
        typeof(VulkanContext),
    ]);
    var legacyGameSceneConstructor = typeof(GameScene).GetConstructor([
        typeof(IRenderBackend),
        typeof(CubitProject),
        typeof(InputServer),
        typeof(VoxelInputState),
        typeof(IAudioOutputBackend),
        typeof(JobSystemOptions),
    ]);
    Check(
        "平台会话接受显式音频后端和可选 Job 配置而不接收体素输入服务",
        gameSceneConstructor is not null &&
        gameSceneConstructor.GetParameters()[3].IsOptional &&
        gameSceneConstructor.GetParameters()[4].IsOptional &&
        gameSceneConstructor.GetParameters()[5].IsOptional &&
        legacyGameSceneConstructor is null,
        gameSceneConstructor?.ToString() ?? "missing");
    if (gameSceneConstructor is not null)
    {
        var sampleBackend = new AudioProbeBackend();
        using var sampleSession = CreateVoxelProjectSession(new FakeRenderBackend(), 20260808u, sampleBackend);
        var sampleScene = sampleSession.Scene;
        var samplePlayer = new AudioPlayer { Name = "SampleAudio", Clip = new AudioClip([0.2f, -0.2f]) };
        sampleScene.Tree.Root.AddChild(samplePlayer);
        sampleScene.ProcessFrame(1d / AudioFormat.SampleRate);
        var samplePlayError = CaptureException(samplePlayer.Play);
        sampleScene.ProcessFrame(1d / AudioFormat.SampleRate);
        Check(
            "Declared audio plugin receives host backend, binds scene players at a frame boundary, and renders each game frame",
            samplePlayError is null && sampleBackend.SubmitCount == 2 && sampleBackend.LastSamples.SequenceEqual([0.2f, -0.2f]),
            $"play={samplePlayError?.GetType().Name} submits={sampleBackend.SubmitCount}");

        var sampleAutoplayPlayer = new AudioPlayer
        {
            Name = "SampleAutoplayAudio",
            Clip = new AudioClip([0.3f, -0.3f]),
            Autoplay = true,
            Loop = true,
        };
        var sampleAutoplayAddError = CaptureException(() => sampleScene.Tree.Root.AddChild(sampleAutoplayPlayer));
        sampleScene.ProcessFrame(1d / AudioFormat.SampleRate);
        Check(
            "Autoplay 作者音频节点等待下一帧服务绑定后开始播放",
            sampleAutoplayAddError is null && sampleAutoplayPlayer.IsPlaying &&
            sampleBackend.LastSamples.SequenceEqual([0.3f, -0.3f]),
            $"add={sampleAutoplayAddError?.GetType().Name} playing={sampleAutoplayPlayer.IsPlaying} " +
            $"samples={string.Join(',', sampleBackend.LastSamples)}");
    }

    var repositoryRoot = FindCubitRepositoryRoot() ?? throw new InvalidOperationException("找不到 Cubit-Engine 仓库根目录。");
    var desktopHostSource = File.ReadAllText(Path.Combine(repositoryRoot, "hosts", "Cubit.Sample", "Program.cs"));
    var androidHostSource = File.ReadAllText(Path.Combine(repositoryRoot, "hosts", "Cubit.Sample.Android", "MainActivity.cs"));
    static bool ClosesSceneBeforeEngine(string source)
    {
        var sceneDisposeIndex = source.IndexOf("scene?.Dispose();", StringComparison.Ordinal);
        var engineDisposeIndex = source.IndexOf("engine.Dispose();", StringComparison.Ordinal);
        if (engineDisposeIndex < 0)
        {
            engineDisposeIndex = source.IndexOf("engine?.Dispose();", StringComparison.Ordinal);
        }

        return sceneDisposeIndex >= 0 && engineDisposeIndex > sceneDisposeIndex;
    }

    Check(
        "Desktop and Android hosts dispose GameScene before Engine so declared audio backends close",
        ClosesSceneBeforeEngine(desktopHostSource) && ClosesSceneBeforeEngine(androidHostSource),
        $"desktop={ClosesSceneBeforeEngine(desktopHostSource)} android={ClosesSceneBeforeEngine(androidHostSource)}");

    var smokeSignalType = typeof(GameScene).Assembly.GetType("Cubit.Sample.AudioSmokeSignal");
    var smokeFactory = smokeSignalType?.GetMethod("CreateClip", BindingFlags.Public | BindingFlags.Static);
    var intentExtraField = smokeSignalType?.GetField("AndroidIntentExtra", BindingFlags.Public | BindingFlags.Static);
    var smokeClip = smokeFactory?.Invoke(null, null) as AudioClip;
    var smokeSamples = smokeClip?.Samples ?? Array.Empty<float>();
    var smokeStereo = smokeSamples.Count % AudioFormat.Channels == 0;
    for (var index = 0; smokeStereo && index < smokeSamples.Count; index += AudioFormat.Channels)
    {
        smokeStereo = smokeSamples[index] == smokeSamples[index + 1];
    }

    var smokePeak = smokeSamples.Count > 0 ? smokeSamples.Max(MathF.Abs) : float.NaN;
    Check(
        "Sample exposes an opt-in finite stereo audio smoke signal for Android device validation",
        intentExtraField?.GetValue(null) as string == "cubit.audio.smoke" &&
        smokeClip is not null &&
        smokeClip.SampleRate == AudioFormat.SampleRate &&
        smokeClip.Channels == AudioFormat.Channels &&
        smokeClip.FrameCount == AudioFormat.SampleRate / 4 &&
        smokeSamples.All(float.IsFinite) &&
        smokeStereo &&
        smokePeak is > 0.1f and <= 0.2f &&
        smokeSamples.Any(sample => sample > 0.1f) &&
        smokeSamples.Any(sample => sample < -0.1f) &&
        androidHostSource.Contains("GetBooleanExtra(AudioSmokeSignal.AndroidIntentExtra, false)", StringComparison.Ordinal) &&
        androidHostSource.Contains("var audioServer = _scene.Runtime.Context.GetRequiredService<Cubit.Audio.AudioServer>();", StringComparison.Ordinal) &&
        androidHostSource.Contains("audioServer.Play(AudioSmokeSignal.CreateClip(), volume: 0.65f, loop: true)", StringComparison.Ordinal) &&
        !androidHostSource.Contains("new AudioPlayer", StringComparison.Ordinal) &&
        !androidHostSource.Contains("_scene.Tree.Root.AddChild", StringComparison.Ordinal) &&
        androidHostSource.Contains("_touchInput.BuildSnapshot()", StringComparison.Ordinal) &&
        androidHostSource.Contains("_inputServer.SetMoveAxis(touch.MoveX, touch.MoveY);", StringComparison.Ordinal) &&
        androidHostSource.Contains("_inputServer.AddLookDelta(touch.LookDeltaX, touch.LookDeltaY);", StringComparison.Ordinal) &&
        androidHostSource.IndexOf("audioServer.Play(AudioSmokeSignal.CreateClip(), volume: 0.65f, loop: true)", StringComparison.Ordinal) <
        androidHostSource.IndexOf("_scene.ProcessFrame(delta);", StringComparison.Ordinal) &&
        !androidHostSource.Contains("_scene.ProcessFrame(delta,", StringComparison.Ordinal),
        $"type={smokeSignalType is not null} factory={smokeFactory is not null} frames={smokeClip?.FrameCount} peak={smokePeak}");

    Console.WriteLine(failures == 0 ? "audiocheck passed" : $"audiocheck failed {failures}");
    return failures == 0 ? 0 : 1;

    static byte[] BuildPcm16Wav(short[] samples, int sampleRate = AudioFormat.SampleRate)
    {
        var dataLength = checked(samples.Length * sizeof(short));
        var wav = new byte[44 + dataLength];
        "RIFF"u8.CopyTo(wav);
        BinaryPrimitives.WriteInt32LittleEndian(wav.AsSpan(4), 36 + dataLength);
        "WAVEfmt "u8.CopyTo(wav.AsSpan(8));
        BinaryPrimitives.WriteInt32LittleEndian(wav.AsSpan(16), 16);
        BinaryPrimitives.WriteInt16LittleEndian(wav.AsSpan(20), 1);
        BinaryPrimitives.WriteInt16LittleEndian(wav.AsSpan(22), AudioFormat.Channels);
        BinaryPrimitives.WriteInt32LittleEndian(wav.AsSpan(24), sampleRate);
        BinaryPrimitives.WriteInt32LittleEndian(wav.AsSpan(28), sampleRate * AudioFormat.Channels * sizeof(short));
        BinaryPrimitives.WriteInt16LittleEndian(wav.AsSpan(32), AudioFormat.Channels * sizeof(short));
        BinaryPrimitives.WriteInt16LittleEndian(wav.AsSpan(34), 16);
        "data"u8.CopyTo(wav.AsSpan(36));
        BinaryPrimitives.WriteInt32LittleEndian(wav.AsSpan(40), dataLength);
        for (var index = 0; index < samples.Length; index++)
        {
            BinaryPrimitives.WriteInt16LittleEndian(wav.AsSpan(44 + index * sizeof(short)), samples[index]);
        }

        return wav;
    }

    static string? FindLocalMinecraftMusicOgg()
    {
        var repositoryRoot = FindCubitRepositoryRoot();
        var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
        if (workspaceRoot is null)
        {
            return null;
        }

        var path = Path.Combine(
            workspaceRoot,
            "mc26.1.2",
            "assets",
            "objects",
            "7f",
            "7f7777e5d5b163c5d64201fd53e5682599548a49");
        return File.Exists(path) ? path : null;
    }

    static int ReadVorbisIdentificationSampleRate(ReadOnlySpan<byte> oggData)
    {
        for (var index = 0; index <= oggData.Length - 16; index++)
        {
            if (oggData[index] == 1 && oggData.Slice(index + 1, 6).SequenceEqual("vorbis"u8))
            {
                return BinaryPrimitives.ReadInt32LittleEndian(oggData.Slice(index + 12, sizeof(int)));
            }
        }

        return 0;
    }
}

static int DesktopAudioSmokeCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var programPath = repositoryRoot is null
        ? null
        : Path.Combine(repositoryRoot, "hosts", "Cubit.Sample", "Program.cs");
    var source = programPath is not null && File.Exists(programPath)
        ? File.ReadAllText(programPath)
        : string.Empty;

    Check("桌面样例入口可定位", !string.IsNullOrEmpty(source), programPath ?? "missing");
    Check(
        "桌面 OGG 冒烟测试必须显式 opt-in",
        source.Contains("--audio-smoke-ogg", StringComparison.Ordinal),
        "expected --audio-smoke-ogg");
    Check(
        "桌面 OGG 冒烟测试只从调用方路径导入",
        source.Contains("AudioClip.FromOggVorbis(File.ReadAllBytes(audioSmokeRequest.FilePath))", StringComparison.Ordinal) &&
        !source.Contains("mc26.1.2", StringComparison.Ordinal),
        "expected explicit request path without local fixture path");
    Check(
        "桌面 OGG 冒烟测试要求已打开的 SDL 输出设备",
        source.Contains("audioBackend is not SdlAudioOutputBackend", StringComparison.Ordinal),
        "expected SDL backend guard");
    Check(
        "桌面 OGG 冒烟测试不创建作者 AudioPlayer 节点",
        !source.Contains("new AudioPlayer", StringComparison.Ordinal) &&
        !source.Contains("AddChild(audio", StringComparison.Ordinal),
        "scene-first boundary");
    Check(
        "桌面 OGG 冒烟测试会在限定时长后关闭窗口",
        source.Contains("window.Close();", StringComparison.Ordinal),
        "expected bounded close");

    Console.WriteLine(failures == 0 ? "desktopaudiosmokecheck passed" : $"desktopaudiosmokecheck failed {failures}");
    return failures == 0 ? 0 : 1;
}

static int DesktopOggAudioDeviceCheck(string oggPath)
{
    const double playbackSeconds = 8d;
    const int framesPerBlock = 1_024;
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    if (string.IsNullOrWhiteSpace(oggPath))
    {
        Console.Error.WriteLine("用法: Cubit.Tool desktopoggaudiocheck <本地 OGG/Vorbis 文件路径>");
        return 1;
    }

    var fullPath = Path.GetFullPath(oggPath);
    if (!File.Exists(fullPath))
    {
        Console.Error.WriteLine($"找不到 OGG/Vorbis 文件: {fullPath}");
        return 1;
    }

    AudioClip clip;
    try
    {
        clip = AudioClip.FromOggVorbis(File.ReadAllBytes(fullPath));
    }
    catch (ArgumentException exception)
    {
        Console.Error.WriteLine($"无法导入 OGG/Vorbis 文件: {exception.Message}");
        return 1;
    }

    var playbackClip = CreateLoudestExcerpt(clip, (int)(playbackSeconds * AudioFormat.SampleRate), out var sourceStartFrame, out var sourceRms);

    var deviceDiagnostics = new SdlAudioDiagnostics();
    var serverDiagnostics = new DiagnosticBag();
    SdlAudioOutputBackend? backend = null;
    AudioServer? server = null;
    try
    {
        backend = new SdlAudioOutputBackend(deviceDiagnostics);
        server = new AudioServer(backend, serverDiagnostics);
        var playback = server.Play(playbackClip, volume: 0.32f);
        var buffer = new float[framesPerBlock * AudioFormat.Channels];
        var stopwatch = Stopwatch.StartNew();
        var submissions = 0;
        var maximumQueuedBytes = 0;
        var peakSample = 0f;
        var nonSilentBlocks = 0;

        Console.WriteLine(
            $"桌面 OGG 实播开始: sourceFrames={clip.FrameCount} " +
            $"sourceStart={sourceStartFrame / (double)AudioFormat.SampleRate:F2}s rms={sourceRms:F5} " +
            $"device={backend.DeviceId} format={backend.DeviceFormat.SampleRate}Hz/" +
            $"{backend.DeviceFormat.Channels}ch duration={playbackSeconds:F1}s");

        while (stopwatch.Elapsed.TotalSeconds < playbackSeconds)
        {
            server.Render(buffer);
            server.Maintain();
            submissions++;
            maximumQueuedBytes = Math.Max(maximumQueuedBytes, backend.QueuedBytes);
            var blockPeak = 0f;
            foreach (var sample in buffer)
            {
                blockPeak = Math.Max(blockPeak, MathF.Abs(sample));
            }

            peakSample = Math.Max(peakSample, blockPeak);
            if (blockPeak >= 0.001f)
            {
                nonSilentBlocks++;
            }

            var expectedElapsed = TimeSpan.FromSeconds(
                submissions * (double)framesPerBlock / AudioFormat.SampleRate);
            var remaining = expectedElapsed - stopwatch.Elapsed;
            if (remaining > TimeSpan.Zero)
            {
                Thread.Sleep(Math.Clamp((int)Math.Ceiling(remaining.TotalMilliseconds), 1, 100));
            }
        }

        var wasPlayingBeforeStop = server.IsPlaying(playback);
        server.Stop(playback);
        server.Maintain();
        var backendFaults = deviceDiagnostics.Snapshot();
        var serverFaults = serverDiagnostics.Snapshot();

        Check(
            "桌面 OGG 实播使用固定 SDL 设备格式",
            backend.DeviceId != 0 && backend.DeviceFormat == SdlAudioDeviceFormat.Fixed,
            $"id={backend.DeviceId} format={backend.DeviceFormat}");
        Check(
            "桌面 OGG 实播向设备持续提交 PCM",
            submissions >= 300 && nonSilentBlocks * 10 >= submissions * 9 && maximumQueuedBytes > 0,
            $"playing={wasPlayingBeforeStop} submissions={submissions} nonSilentBlocks={nonSilentBlocks} maxQueued={maximumQueuedBytes}");
        Check(
            "桌面 OGG 实播混音缓冲达到可听性冒烟阈值",
            peakSample >= 0.02f && nonSilentBlocks > 0,
            $"peak={peakSample:F5} nonSilentBlocks={nonSilentBlocks}");
        Check(
            "桌面 OGG 实播没有后端提交诊断",
            !backendFaults.Any(diagnostic => diagnostic.Code is "audio.backend.queue_failed" or "audio.backend.queue_full") &&
            !serverFaults.Any(diagnostic => diagnostic.Code == "audio.backend.submit-failed"),
            $"backend={string.Join(',', backendFaults.Select(diagnostic => diagnostic.Code))} " +
            $"server={string.Join(',', serverFaults.Select(diagnostic => diagnostic.Code))}");
    }
    catch (AudioBackendException exception)
    {
        Check("桌面 OGG 实播可以打开默认 SDL 设备", false, exception.DiagnosticCode);
    }
    catch (Exception exception)
    {
        Check("桌面 OGG 实播未出现未处理异常", false, exception.GetType().Name);
    }
    finally
    {
        server?.Dispose();
        backend?.Dispose();
    }

    Console.WriteLine(failures == 0 ? "desktopoggaudiocheck passed" : $"desktopoggaudiocheck failed {failures}");
    return failures == 0 ? 0 : 1;

    static AudioClip CreateLoudestExcerpt(AudioClip source, int targetFrameCount, out int sourceStartFrame, out float sourceRms)
    {
        ArgumentNullException.ThrowIfNull(source);
        if (targetFrameCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(targetFrameCount));
        }

        var sourceFrames = source.FrameCount;
        var samples = source.Samples;
        var framesPerExcerpt = Math.Min(targetFrameCount, sourceFrames);
        var bestEnergy = double.NegativeInfinity;
        sourceStartFrame = 0;

        for (var startFrame = 0; startFrame < sourceFrames; startFrame += framesPerExcerpt)
        {
            var frameCount = Math.Min(framesPerExcerpt, sourceFrames - startFrame);
            var sumSquares = 0d;
            for (var frame = 0; frame < frameCount; frame++)
            {
                var index = (startFrame + frame) * AudioFormat.Channels;
                var left = samples[index];
                var right = samples[index + 1];
                sumSquares += left * left + right * right;
            }

            var meanSquare = sumSquares / (frameCount * AudioFormat.Channels);
            if (meanSquare > bestEnergy)
            {
                bestEnergy = meanSquare;
                sourceStartFrame = startFrame;
            }
        }

        var actualFrameCount = Math.Min(framesPerExcerpt, sourceFrames - sourceStartFrame);
        var excerptSamples = new float[actualFrameCount * AudioFormat.Channels];
        for (var frame = 0; frame < actualFrameCount; frame++)
        {
            var sourceIndex = (sourceStartFrame + frame) * AudioFormat.Channels;
            var targetIndex = frame * AudioFormat.Channels;
            excerptSamples[targetIndex] = samples[sourceIndex];
            excerptSamples[targetIndex + 1] = samples[sourceIndex + 1];
        }

        sourceRms = (float)Math.Sqrt(Math.Max(0d, bestEnergy));
        return new AudioClip(excerptSamples);
    }
}

static int AudioBackendCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var repositoryRoot = FindCubitRepositoryRoot() ?? throw new InvalidOperationException("找不到 Cubit-Engine 仓库根目录。");
    var androidHostPath = Path.Combine(repositoryRoot, "hosts", "Cubit.Sample.Android", "MainActivity.cs");
    var androidHostSource = File.ReadAllText(androidHostPath);
    Check(
        "Android 音频 smoke 通过项目 AudioServer 播放且不创建作者节点",
        androidHostSource.Contains("var audioServer = _scene.Runtime.Context.GetRequiredService<Cubit.Audio.AudioServer>();", StringComparison.Ordinal) &&
        androidHostSource.Contains("audioServer.Play(", StringComparison.Ordinal) &&
        !androidHostSource.Contains("new AudioPlayer", StringComparison.Ordinal) &&
        !androidHostSource.Contains("_scene.Tree.Root.AddChild", StringComparison.Ordinal));
    Check(
        "Android 音频 smoke 以可辨识电平循环播放",
        androidHostSource.Contains("audioServer.Play(AudioSmokeSignal.CreateClip(), volume: 0.65f, loop: true)", StringComparison.Ordinal));
    var androidAudioBackendStart = androidHostSource.IndexOf("new SdlAudioOutputBackend", StringComparison.Ordinal);
    var androidAudioFocusAcquire = androidHostSource.IndexOf("if (AcquireAudioFocus())", StringComparison.Ordinal);
    var androidShutdown = androidHostSource.IndexOf("private void Shutdown()", StringComparison.Ordinal);
    Check(
        "Android 宿主在打开 SDL 设备前取得并在关闭时释放媒体焦点",
        androidAudioFocusAcquire >= 0 &&
        androidAudioBackendStart > androidAudioFocusAcquire &&
        androidShutdown >= 0 &&
        androidHostSource.IndexOf("ReleaseAudioFocus();", androidShutdown, StringComparison.Ordinal) > androidShutdown);
    Check(
        "Android 宿主以 API 26+ AudioFocusRequest 获得焦点后才打开 SDL 设备",
        androidHostSource.Contains("private global::Android.Media.AudioFocusRequestClass? _audioFocusRequest", StringComparison.Ordinal) &&
        androidHostSource.Contains("new global::Android.Media.AudioFocusRequestClass.Builder", StringComparison.Ordinal) &&
        androidHostSource.Contains("RequestAudioFocus(audioFocusRequest)", StringComparison.Ordinal) &&
        androidHostSource.Contains("AbandonAudioFocusRequest(audioFocusRequest)", StringComparison.Ordinal) &&
        androidHostSource.Contains("if (result != global::Android.Media.AudioFocusRequest.Granted)", StringComparison.Ordinal) &&
        androidHostSource.Contains("if (AcquireAudioFocus())", StringComparison.Ordinal) &&
        androidHostSource.Contains("OperatingSystem.IsAndroidVersionAtLeast(26)", StringComparison.Ordinal) &&
        androidHostSource.Contains("audioManager.RequestAudioFocus(", StringComparison.Ordinal) &&
        androidHostSource.Contains("global::Android.Media.Stream.Music", StringComparison.Ordinal) &&
        androidHostSource.Contains("AbandonAudioFocus(_audioFocusListener)", StringComparison.Ordinal));

    foreach (var assemblyName in new[] { "Cubit.Audio.Windows", "Cubit.Audio.Android" })
    {
        try
        {
            var assembly = Assembly.Load(assemblyName);
            Check($"{assemblyName} assembly loadable", true, assembly.FullName ?? "");
            var references = assembly.GetReferencedAssemblies()
                .Select(reference => reference.Name)
                .Where(name => name is not null && name.StartsWith("Cubit.", StringComparison.Ordinal))
                .ToArray();
            Check(
                $"{assemblyName} only references Cubit.Audio in engine assemblies",
                references.SequenceEqual(["Cubit.Audio"]),
                string.Join(',', references));
        }
        catch (Exception exception)
        {
            Check($"{assemblyName} assembly loadable", false, exception.GetType().Name);
        }
    }

    var requestedFormatAdapter = new ToolSdlAudioAdapter(SdlAudioDeviceFormat.Fixed);
    var requestedFormatDiagnostics = new SdlAudioDiagnostics();
    using (var requestedFormatBackend = new SdlAudioOutputBackend(
        requestedFormatAdapter,
        requestedFormatDiagnostics,
        maximumQueuedBytes: 32))
    {
        Check(
            "Windows backend requests fixed 48kHz stereo float32 format",
            requestedFormatAdapter.RequestedFormat == SdlAudioDeviceFormat.Fixed &&
            requestedFormatAdapter.OpenCount == 1,
            requestedFormatAdapter.RequestedFormat.ToString());

        requestedFormatBackend.Submit([0.25f, -0.25f]);
        Check(
            "Windows backend synchronously queues submitted PCM",
            requestedFormatAdapter.LastQueuedSamples.SequenceEqual([0.25f, -0.25f]),
            string.Join(',', requestedFormatAdapter.LastQueuedSamples));
    }

    var mismatchAdapter = new ToolSdlAudioAdapter(new SdlAudioDeviceFormat(44_100, 2, 32));
    var mismatchDiagnostics = new SdlAudioDiagnostics();
    var mismatchException = CaptureException(() => new SdlAudioOutputBackend(mismatchAdapter, mismatchDiagnostics));
    Check(
        "Windows backend rejects a device format mismatch",
        mismatchException is AudioBackendException &&
        mismatchDiagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.format_mismatch"),
        mismatchException?.GetType().Name ?? "none");

    var openFailureAdapter = new ToolSdlAudioAdapter(SdlAudioDeviceFormat.Fixed) { DeviceId = 0 };
    var openFailureDiagnostics = new SdlAudioDiagnostics();
    var openFailureException = CaptureException(() => new SdlAudioOutputBackend(openFailureAdapter, openFailureDiagnostics));
    Check(
        "Windows backend reports an underscored device-open diagnostic",
        openFailureException is AudioBackendException { DiagnosticCode: "audio.backend.open_failed" } &&
        openFailureDiagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.open_failed"),
        openFailureException is AudioBackendException backendException ? backendException.DiagnosticCode : openFailureException?.GetType().Name ?? "none");

    var queueAdapter = new ToolSdlAudioAdapter(SdlAudioDeviceFormat.Fixed);
    var queueDiagnostics = new SdlAudioDiagnostics();
    using (var queueBackend = new SdlAudioOutputBackend(queueAdapter, queueDiagnostics, maximumQueuedBytes: 32))
    {
        queueAdapter.QueuedBytes = 24;
        queueBackend.Submit([0.1f, -0.1f, 0.2f, -0.2f]);
        Check(
            "Windows backend drops a block that exceeds the bounded queue",
            queueAdapter.QueueCount == 0 &&
            queueDiagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.queue_full"),
            $"queued={queueAdapter.QueuedBytes}");
    }

    var queueFailureAdapter = new ToolSdlAudioAdapter(SdlAudioDeviceFormat.Fixed) { QueueSucceeds = false };
    var queueFailureDiagnostics = new SdlAudioDiagnostics();
    using (var queueFailureBackend = new SdlAudioOutputBackend(queueFailureAdapter, queueFailureDiagnostics))
    {
        queueFailureBackend.Submit([0.1f, -0.1f]);
        Check(
            "Windows backend reports an underscored queue-submit diagnostic",
            queueFailureDiagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.queue_failed"),
            string.Join(',', queueFailureDiagnostics.Snapshot().Select(diagnostic => diagnostic.Code)));
    }

    var closeAdapter = new ToolSdlAudioAdapter(SdlAudioDeviceFormat.Fixed);
    var closeDiagnostics = new SdlAudioDiagnostics();
    var closeBackend = new SdlAudioOutputBackend(closeAdapter, closeDiagnostics);
    closeBackend.Dispose();
    closeBackend.Dispose();
    closeBackend.Submit([0f, 0f]);
    Check(
        "Windows backend close is idempotent and rejects subsequent submits",
        closeAdapter.PauseCount == 2 &&
        closeAdapter.ClearCount == 2 &&
        closeAdapter.CloseCount == 1 &&
        closeAdapter.QueueCount == 0 &&
        closeDiagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.closed"),
        $"pause={closeAdapter.PauseCount} clear={closeAdapter.ClearCount} close={closeAdapter.CloseCount}");

    var androidAdapter = new ToolAndroidSdlAudioAdapter(AndroidAudio.SdlAudioDeviceFormat.Fixed);
    var androidDiagnostics = new AndroidAudio.SdlAudioDiagnostics();
    using (var androidBackend = new AndroidAudio.SdlAudioOutputBackend(
        androidAdapter,
        androidDiagnostics,
        maximumQueuedBytes: 32))
    {
        Check(
            "Android backend requests fixed 48kHz stereo float32 format",
            androidAdapter.RequestedFormat == AndroidAudio.SdlAudioDeviceFormat.Fixed &&
            androidAdapter.OpenCount == 1,
            androidAdapter.RequestedFormat.ToString());

        androidBackend.Submit([0.5f, -0.5f]);
        Check(
            "Android backend synchronously queues submitted PCM",
            androidAdapter.LastQueuedSamples.SequenceEqual([0.5f, -0.5f]),
            string.Join(',', androidAdapter.LastQueuedSamples));

        var androidDeviceIdProperty = typeof(AndroidAudio.SdlAudioOutputBackend)
            .GetProperty("DeviceId", BindingFlags.Public | BindingFlags.Instance);
        var androidDeviceFormatProperty = typeof(AndroidAudio.SdlAudioOutputBackend)
            .GetProperty("DeviceFormat", BindingFlags.Public | BindingFlags.Instance);
        var androidQueuedBytesProperty = typeof(AndroidAudio.SdlAudioOutputBackend)
            .GetProperty("QueuedBytes", BindingFlags.Public | BindingFlags.Instance);
        var androidSubmittedBytesProperty = typeof(AndroidAudio.SdlAudioOutputBackend)
            .GetProperty("SubmittedBytes", BindingFlags.Public | BindingFlags.Instance);
        Check(
            "Android backend exposes opened-device telemetry for real-device evidence",
            androidDeviceIdProperty?.PropertyType == typeof(uint) &&
            androidDeviceFormatProperty?.PropertyType == typeof(AndroidAudio.SdlAudioDeviceFormat) &&
            androidQueuedBytesProperty?.PropertyType == typeof(int) &&
            androidSubmittedBytesProperty?.PropertyType == typeof(long) &&
            (uint)androidDeviceIdProperty.GetValue(androidBackend)! == androidAdapter.DeviceId &&
            (AndroidAudio.SdlAudioDeviceFormat)androidDeviceFormatProperty.GetValue(androidBackend)! == AndroidAudio.SdlAudioDeviceFormat.Fixed &&
            (int)androidQueuedBytesProperty.GetValue(androidBackend)! == androidAdapter.QueuedBytes &&
            (long)androidSubmittedBytesProperty.GetValue(androidBackend)! == sizeof(float) * AudioFormat.Channels,
            $"id={androidDeviceIdProperty?.PropertyType.Name} format={androidDeviceFormatProperty?.PropertyType.Name} queued={androidQueuedBytesProperty?.PropertyType.Name} submitted={androidSubmittedBytesProperty?.PropertyType.Name}");

        androidAdapter.QueuedBytes = 24;
        androidBackend.Submit([0.1f, -0.1f, 0.2f, -0.2f]);
        Check(
            "Android backend drops a block that exceeds the bounded queue",
            androidAdapter.QueueCount == 1 &&
            androidDiagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.queue_full"),
            $"queued={androidAdapter.QueuedBytes}");
    }

    var androidMismatchAdapter = new ToolAndroidSdlAudioAdapter(new AndroidAudio.SdlAudioDeviceFormat(44_100, 2, 32));
    var androidMismatchDiagnostics = new AndroidAudio.SdlAudioDiagnostics();
    var androidMismatchException = CaptureException(() => new AndroidAudio.SdlAudioOutputBackend(
        androidMismatchAdapter,
        androidMismatchDiagnostics));
    Check(
        "Android backend rejects a device format mismatch",
        androidMismatchException is AndroidAudio.AudioBackendException &&
        androidMismatchDiagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.format_mismatch"),
        androidMismatchException?.GetType().Name ?? "none");

    var androidOpenFailureAdapter = new ToolAndroidSdlAudioAdapter(AndroidAudio.SdlAudioDeviceFormat.Fixed) { DeviceId = 0 };
    var androidOpenFailureDiagnostics = new AndroidAudio.SdlAudioDiagnostics();
    var androidOpenFailureException = CaptureException(() => new AndroidAudio.SdlAudioOutputBackend(
        androidOpenFailureAdapter,
        androidOpenFailureDiagnostics));
    Check(
        "Android backend reports an underscored device-open diagnostic",
        androidOpenFailureException is AndroidAudio.AudioBackendException { DiagnosticCode: "audio.backend.open_failed" } &&
        androidOpenFailureDiagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.open_failed"),
        androidOpenFailureException is AndroidAudio.AudioBackendException androidBackendException ? androidBackendException.DiagnosticCode : androidOpenFailureException?.GetType().Name ?? "none");

    var androidQueueFailureAdapter = new ToolAndroidSdlAudioAdapter(AndroidAudio.SdlAudioDeviceFormat.Fixed) { QueueSucceeds = false };
    var androidQueueFailureDiagnostics = new AndroidAudio.SdlAudioDiagnostics();
    using (var androidQueueFailureBackend = new AndroidAudio.SdlAudioOutputBackend(
        androidQueueFailureAdapter,
        androidQueueFailureDiagnostics))
    {
        androidQueueFailureBackend.Submit([0.1f, -0.1f]);
        Check(
            "Android backend reports an underscored queue-submit diagnostic",
            androidQueueFailureDiagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.queue_failed"),
            string.Join(',', androidQueueFailureDiagnostics.Snapshot().Select(diagnostic => diagnostic.Code)));
    }

    var androidCloseAdapter = new ToolAndroidSdlAudioAdapter(AndroidAudio.SdlAudioDeviceFormat.Fixed);
    var androidCloseDiagnostics = new AndroidAudio.SdlAudioDiagnostics();
    var androidCloseBackend = new AndroidAudio.SdlAudioOutputBackend(androidCloseAdapter, androidCloseDiagnostics);
    androidCloseBackend.Dispose();
    androidCloseBackend.Dispose();
    androidCloseBackend.Submit([0f, 0f]);
    Check(
        "Android backend close is idempotent and rejects subsequent submits",
        androidCloseAdapter.PauseCount == 2 &&
        androidCloseAdapter.ClearCount == 2 &&
        androidCloseAdapter.CloseCount == 1 &&
        androidCloseDiagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.closed"),
        $"pause={androidCloseAdapter.PauseCount} clear={androidCloseAdapter.ClearCount} close={androidCloseAdapter.CloseCount}");
    Check(
        "Android backend reports zero queued bytes after close",
        typeof(AndroidAudio.SdlAudioOutputBackend)
            .GetProperty("QueuedBytes", BindingFlags.Public | BindingFlags.Instance)?
            .GetValue(androidCloseBackend) is int { } closedQueuedBytes && closedQueuedBytes == 0,
        "queued telemetry unavailable or nonzero");

    Console.WriteLine(failures == 0 ? "audiobackendcheck passed" : $"audiobackendcheck failed {failures}");
    return failures == 0 ? 0 : 1;
}

static int AudioDeviceCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    var backendType = typeof(SdlAudioOutputBackend);
    var deviceIdProperty = backendType.GetProperty("DeviceId", BindingFlags.Public | BindingFlags.Instance);
    var deviceFormatProperty = backendType.GetProperty("DeviceFormat", BindingFlags.Public | BindingFlags.Instance);
    var queuedBytesProperty = backendType.GetProperty("QueuedBytes", BindingFlags.Public | BindingFlags.Instance);
    Check(
        "Windows SDL backend exposes device smoke-test telemetry",
        deviceIdProperty?.PropertyType == typeof(uint) &&
        deviceFormatProperty?.PropertyType == typeof(SdlAudioDeviceFormat) &&
        queuedBytesProperty?.PropertyType == typeof(int),
        $"id={deviceIdProperty?.PropertyType.Name} format={deviceFormatProperty?.PropertyType.Name} queued={queuedBytesProperty?.PropertyType.Name}");
    if (failures != 0)
    {
        Console.WriteLine($"audiodevicecheck failed {failures}");
        return 1;
    }

    var diagnostics = new SdlAudioDiagnostics();
    try
    {
        using var backend = new SdlAudioOutputBackend(diagnostics);
        backend.Submit(new float[AudioFormat.Channels * 1_024]);
        var deviceId = (uint)deviceIdProperty!.GetValue(backend)!;
        var deviceFormat = (SdlAudioDeviceFormat)deviceFormatProperty!.GetValue(backend)!;
        var queuedAfterSubmit = (int)queuedBytesProperty!.GetValue(backend)!;
        Thread.Sleep(50);
        var queuedAfterWait = (int)queuedBytesProperty.GetValue(backend)!;
        Check(
            "Windows SDL default device opens and accepts bounded silent PCM",
            deviceId != 0 && deviceFormat == SdlAudioDeviceFormat.Fixed &&
            queuedAfterSubmit is >= 0 && queuedAfterSubmit <= backend.MaximumQueuedBytes &&
            queuedAfterWait is >= 0 && queuedAfterWait <= queuedAfterSubmit,
            $"id={deviceId} format={deviceFormat} queued={queuedAfterSubmit}->{queuedAfterWait}");
    }
    catch (AudioBackendException exception)
    {
        Check(
            "Windows SDL default device unavailability reports a stable diagnostic",
            exception.DiagnosticCode == "audio.backend.open_failed" &&
            diagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "audio.backend.open_failed"),
            exception.DiagnosticCode);
    }
    catch (Exception exception)
    {
        Check("Windows SDL default device does not leak an unmanaged initialization exception", false, exception.GetType().Name);
    }

    Console.WriteLine(failures == 0 ? "audiodevicecheck passed" : $"audiodevicecheck failed {failures}");
    return failures == 0 ? 0 : 1;
}

static int VoxelCollisionReplaceCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    using var tree = new SceneTree();
    using var renderer = new RenderingServer(new FakeRenderBackend());
    var worldNode = new VoxelWorldNode
    {
        Name = "World",
        Seed = 20260808,
        WorldType = WorldType.Noise,
        Jobs = jobs,
        Server = renderer,
    };
    tree.Root.AddChild(worldNode);
    var initialWorld = worldNode.World ?? throw new InvalidOperationException("初始体素世界没有创建");
    initialWorld.GenerateAround(0, 0, 1);

    var physics = new PhysicsWorld3D { Name = "Physics", Gravity = Vector3.Zero };
    var terrain = new VoxelTerrainBody3D
    {
        Name = "Terrain",
        WorldPath = "/Root/World",
        FocusPath = "/Root/Physics/Player",
        CollisionRadius = 1,
    };
    var player = new CharacterBody3D { Name = "Player", Position = new Vector3(8f, 70f, 8f) };
    player.AddChild(new CollisionShape3D
    {
        Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
    });
    physics.AddChild(terrain);
    physics.AddChild(player);
    tree.Root.AddChild(physics);
    tree.ProcessFrame(tree.PhysicsDelta);

    var rebuildBeforeReplace = terrain.RebuildCount;
    var oldGeneratedShape = terrain.Children.OfType<CollisionShape3D>().FirstOrDefault();
    var replacement = new VoxelWorld(999999u, WorldType.Noise);
    replacement.GenerateAround(0, 0, 1);
    worldNode.ReplaceWorld(replacement);
    tree.ProcessFrame(tree.PhysicsDelta);

    Check(
        "替换世界实例后碰撞窗口强制重建",
        terrain.RebuildCount > rebuildBeforeReplace,
        $"before={rebuildBeforeReplace} after={terrain.RebuildCount} colliders={terrain.GeneratedColliderCount}");
    Check(
        "替换世界实例后释放旧碰撞派生节点",
        oldGeneratedShape is not null && !terrain.Children.Contains(oldGeneratedShape),
        $"oldShapeWasChild={oldGeneratedShape is not null && terrain.Children.Contains(oldGeneratedShape)}");

    var directory = Path.Combine(Path.GetTempPath(), $"cubit_voxel_collision_unload_{Guid.NewGuid():N}");
    try
    {
        var source = new VoxelWorld(20260808u, WorldType.Flat);
        source.GenerateAround(0, 0, 1);
        WorldFile.Save(source, directory);
        var loaded = WorldFile.Load(directory);

        using var unloadJobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
        using var unloadTree = new SceneTree();
        using var unloadRenderer = new RenderingServer(new FakeRenderBackend());
        var unloadWorldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            Jobs = unloadJobs,
            Server = unloadRenderer,
        };
        unloadTree.Root.AddChild(unloadWorldNode);
        unloadWorldNode.ReplaceWorld(loaded);
        var unloadPhysics = new PhysicsWorld3D { Name = "Physics", Gravity = Vector3.Zero };
        var unloadTerrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var unloadPlayer = new CharacterBody3D { Name = "Player", Position = new Vector3(8f, 70f, 8f) };
        unloadPlayer.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        unloadPhysics.AddChild(unloadTerrain);
        unloadPhysics.AddChild(unloadPlayer);
        unloadTree.Root.AddChild(unloadPhysics);
        unloadTree.ProcessFrame(unloadTree.PhysicsDelta);

        var unloadRebuildBefore = unloadTerrain.RebuildCount;
        var unloadOldShape = unloadTerrain.Children.OfType<CollisionShape3D>().FirstOrDefault();
        var unloadRevisionBefore = loaded.GetTerrainWindowRevision(0, 0, 1);
        var unloadedKeys = loaded.UnloadChunksOutside(0, 0, 0);
        var unloadRevisionAfter = loaded.GetTerrainWindowRevision(0, 0, 1);
        unloadTree.ProcessFrame(unloadTree.PhysicsDelta);
        unloadTree.ProcessFrame(unloadTree.PhysicsDelta);
        Check(
            "视距卸载触发碰撞窗口重建",
            unloadedKeys.Length == 8 && unloadRevisionAfter != unloadRevisionBefore && unloadTerrain.RebuildCount > unloadRebuildBefore,
            $"unloaded={unloadedKeys.Length} revision={unloadRevisionBefore}->{unloadRevisionAfter} before={unloadRebuildBefore} after={unloadTerrain.RebuildCount}");
        Check(
            "视距卸载释放旧碰撞派生节点",
            unloadOldShape is not null && !unloadTerrain.Children.Contains(unloadOldShape),
            $"oldShapeWasChild={unloadOldShape is not null && unloadTerrain.Children.Contains(unloadOldShape)}");
    }
    finally
    {
        if (Directory.Exists(directory))
        {
            Directory.Delete(directory, recursive: true);
        }
    }

    Console.WriteLine(failures == 0 ? "voxelcollisionreplacecheck 全部通过" : $"voxelcollisionreplacecheck 失败 {failures} 项");
    return failures == 0 ? 0 : 1;
}

static int VoxelPhysicsCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok)
        {
            failures++;
        }
    }

    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(0, 0, 1);

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = new Vector3(0f, -24f, 0f) };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8f, 5.901f, 8f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1.1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        character.Velocity = new Vector3(0f, -1f, 0f);
        character.MoveAndSlide();
        tree.ProcessFrame(tree.PhysicsDelta);
        var maximumFootY = character.GlobalPosition.Y - 0.9f;
        for (var tick = 0; tick < 40; tick++)
        {
            var vertical = tick == 0 ? 7f : character.Velocity.Y - 24f * (float)tree.PhysicsDelta;
            character.Velocity = new Vector3(0f, vertical, 0f);
            character.MoveAndSlide();
            tree.ProcessFrame(tree.PhysicsDelta);
            maximumFootY = MathF.Max(maximumFootY, character.GlobalPosition.Y - 0.9f);
        }

        Check(
            "正式体素项目当前跳跃高度必须收敛到单格范围",
            maximumFootY >= 6.15f && maximumFootY <= 6.25f,
            $"maximumFootY={maximumFootY:F3}");
    }

    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(0, 0, 1);

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = Vector3.Zero };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8f, 12f, 8f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        var before = terrain.GeneratedColliderCount;
        Check("体素地形基线碰撞体已生成", before > 0, $"colliders={before}");
        Check("写入三层连续体素柱", voxelWorld.SetBlock(12, 8, 8, BlockRegistry.Stone) &&
            voxelWorld.SetBlock(12, 9, 8, BlockRegistry.Stone) &&
            voxelWorld.SetBlock(12, 10, 8, BlockRegistry.Stone));
        tree.ProcessFrame(tree.PhysicsDelta);
        tree.ProcessFrame(tree.PhysicsDelta);
        var added = terrain.GeneratedColliderCount - before;
        Check(
            "连续体素柱合并为单个垂直碰撞体",
            added == 1,
            $"before={before} after={terrain.GeneratedColliderCount} added={added} " +
            $"column={string.Join(';', terrain.Children.OfType<CollisionShape3D>()
                .Where(shape => MathF.Abs(shape.Position.X - 12.5f) < 0.01f && MathF.Abs(shape.Position.Z - 8.5f) < 0.01f)
                .Select(shape => $"p={shape.Position}/s={((BoxShape3D)shape.Shape!).Size}"))}");
    }

    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(0, 0, 1);
        voxelWorld.SetBlock(9, 5, 8, BlockRegistry.Stone);
        voxelWorld.SetBlock(9, 6, 8, BlockRegistry.Stone);

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = new Vector3(0f, -24f, 0f) };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8f, 5.901f, 8f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1.1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        character.Velocity = new Vector3(0f, -1f, 0f);
        character.MoveAndSlide();
        tree.ProcessFrame(tree.PhysicsDelta);
        for (var tick = 0; tick < 45; tick++)
        {
            var vertical = tick == 0 ? 7f : character.Velocity.Y - 24f * (float)tree.PhysicsDelta;
            character.Velocity = new Vector3(8f, vertical, 0f);
            character.MoveAndSlide();
            tree.ProcessFrame(tree.PhysicsDelta);
        }

        Check(
            "正式体素项目跳跃不能越过两格实体墙",
            character.GlobalPosition.X <= 8.65f,
            $"position={character.GlobalPosition} slides={character.LastSlideCount}");
