        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = Vector3.Zero };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8.6f, 5.901f, 8f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1.1f },
