            $"position={character.GlobalPosition} velocity={character.Velocity} floor={character.IsOnFloor} " +
            $"slides={character.LastSlideCount} normals={string.Join(';', Enumerable.Range(0, character.LastSlideCount).Select(i => character.GetSlideCollision(i).Normal.ToString()))} " +
            $"trace={string.Join(',', collisionTrace)}");
        Check(
            "贴边跳跃的水平速度不会被圆角接触削成极小值",
            minimumHorizontalSpeed >= 4f,
            $"minimumHorizontalSpeed={minimumHorizontalSpeed:F3}");
    }

    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
