        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(0, 0, 1);
        voxelWorld.SetBlock(9, 5, 9, BlockRegistry.Stone);

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = new Vector3(0f, -24f, 0f) };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8.65f, 5.901f, 8.65f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1.1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        character.Velocity = new Vector3(0f, -1f, 0f);
        character.MoveAndSlide();
        tree.ProcessFrame(tree.PhysicsDelta);
        var diagonalDirection = Vector3.Normalize(new Vector3(1f, 0f, 1f));
        var minimumDiagonalStep = float.MaxValue;
        var previousPosition = character.GlobalPosition;
        for (var tick = 0; tick < 45; tick++)
        {
            var vertical = tick == 0 ? 8f : character.Velocity.Y - 24f * (float)tree.PhysicsDelta;
            var horizontal = tick == 0 ? diagonalDirection * 8f : new Vector3(character.Velocity.X, 0f, character.Velocity.Z);
            character.Velocity = horizontal + Vector3.UnitY * vertical;
            character.MoveAndSlide();
            tree.ProcessFrame(tree.PhysicsDelta);
            var step = Vector3.Distance(character.GlobalPosition, previousPosition);
            if (!character.IsOnFloor && step > 1e-5f)
            {
                minimumDiagonalStep = MathF.Min(minimumDiagonalStep, step);
            }

            previousPosition = character.GlobalPosition;
        }

        Check(
            "斜向贴边跳跃不会陷入近零实际位移",
            character.GlobalPosition.X > 9.2f && character.GlobalPosition.Z > 9.2f && minimumDiagonalStep >= 0.04f,
            $"position={character.GlobalPosition} velocity={character.Velocity} minimumStep={minimumDiagonalStep:F4}");
    }

    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = Vector3.Zero };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 0,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8f, 350f, 8f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.4f, CylinderHeight = 1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);
        for (var tick = 0; tick < 30 && !character.IsOnFloor; tick++)
        {
            character.Velocity = new Vector3(0f, -200f, 0f);
            character.MoveAndSlide();
            tree.ProcessFrame(tree.PhysicsDelta);
        }

        Check(
            "未加载区块使用保守碰撞而非可穿透空气",
            terrain.UsesConservativeFallback && character.GlobalPosition.Y >= Chunk.MaxYExclusive - 0.11f && character.IsOnFloor,
            $"position={character.GlobalPosition} fallback={terrain.UsesConservativeFallback}");
    }

    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Noise,
            Seed = 20260808,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(1, 1, 1);

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = new Vector3(0f, -24f, 0f) };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
            MaxColliderCount = 2048,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(24f, voxelWorld.GetSpawnHeight(24, 24) + 0.901f, 24f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1.1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        Check(
            "噪声地形碰撞窗口不因默认预算退化为整区块墙",
            !terrain.UsesConservativeFallback,
            $"colliders={terrain.GeneratedColliderCount} fallback={terrain.UsesConservativeFallback}");
    }

    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Noise,
            Seed = 20260808,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(1, 1, 1);

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = new Vector3(0f, -24f, 0f) };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
            MaxColliderCount = 2048,
        };
        var character = new CharacterBody3D { Name = "Player" };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1.1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        var foundStep = false;
        var failedStep = (X: 0, Z: 0, From: 0, To: 0);
        var minimumStep = float.MaxValue;
        for (var z = 17; z < 31 && !foundStep; z++)
        {
            for (var x = 17; x < 30 && !foundStep; x++)
            {
                var from = voxelWorld.GetSpawnHeight(x, z);
                var to = voxelWorld.GetSpawnHeight(x + 1, z);
                if (to != from + 1)
                {
                    continue;
                }

                foundStep = true;
                character.Position = new Vector3(x + 0.5f, from + 0.901f, z + 0.5f);
                character.Velocity = new Vector3(0f, -1f, 0f);
                character.MoveAndSlide();
                tree.ProcessFrame(tree.PhysicsDelta);
                var start = character.GlobalPosition;
                var previous = start;
                var localMinimumStep = float.MaxValue;
                for (var tick = 0; tick < 45; tick++)
                {
                    var vertical = tick == 0 ? 8f : character.Velocity.Y - 24f * (float)tree.PhysicsDelta;
                    var horizontal = tick == 0 ? 8f : character.Velocity.X;
                    character.Velocity = new Vector3(horizontal, vertical, 0f);
                    character.MoveAndSlide();
                    tree.ProcessFrame(tree.PhysicsDelta);
                    var step = Vector3.Distance(character.GlobalPosition, previous);
                    if (!character.IsOnFloor && step > 1e-5f)
                    {
                        localMinimumStep = MathF.Min(localMinimumStep, step);
                    }

                    previous = character.GlobalPosition;
                }

                minimumStep = localMinimumStep;
                if (character.GlobalPosition.X < x + 1.25f || localMinimumStep < 0.04f)
                {
                    failedStep = (x, z, from, to);
                }

                _ = start;
            }
        }

        Check(
            "随机地形一格上台阶跳跃不会出现近零实际位移",
            foundStep && failedStep == (0, 0, 0, 0),
            $"found={foundStep} failed=({failedStep.X},{failedStep.Z}) height={failedStep.From}->{failedStep.To} minimumStep={minimumStep:F4} position={character.GlobalPosition}");
    }

    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(0, 0, 1);

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = new Vector3(0f, -24f, 0f) };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8.5f, 5.901f, 8.5f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.4f, CylinderHeight = 1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        character.Velocity = new Vector3(0f, -1f, 0f);
        character.MoveAndSlide();
        tree.ProcessFrame(tree.PhysicsDelta);
        Check("挖空前角色已建立地面状态", character.IsOnFloor, $"floor={character.IsOnFloor}");

        Check("脚下方块可被挖空", voxelWorld.SetBlock(8, 4, 8, BlockRegistry.Air));
        character.Velocity = Vector3.Zero;
        character.MoveAndSlide();
        tree.ProcessFrame(tree.PhysicsDelta);
        Check(
            "挖空脚下方块后零位移移动不会保留旧地面状态",
            !character.IsOnFloor,
            $"position={character.GlobalPosition} floor={character.IsOnFloor} rebuilds={terrain.RebuildCount} colliders={terrain.GeneratedColliderCount}");

        for (var tick = 0; tick < 8; tick++)
        {
            var vertical = character.IsOnFloor ? 0f : character.Velocity.Y - 24f * (float)tree.PhysicsDelta;
            character.Velocity = new Vector3(0f, vertical, 0f);
            character.MoveAndSlide();
            tree.ProcessFrame(tree.PhysicsDelta);
        }

        Check(
            "挖空脚下方块后角色重新受到重力",
            character.GlobalPosition.Y < 5.7f,
            $"position={character.GlobalPosition} floor={character.IsOnFloor} rebuilds={terrain.RebuildCount} colliders={terrain.GeneratedColliderCount}");
    }

    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(0, 0, 1);
        for (var x = 9; x <= 13; x++)
        {
            for (var z = 7; z <= 9; z++)
            {
                for (var y = 1; y <= 4; y++)
                {
                    voxelWorld.SetBlock(x, y, z, BlockRegistry.Air);
                }
            }
        }

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = Vector3.Zero };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8.2f, 5.901f, 8f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.4f, CylinderHeight = 1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        character.Velocity = new Vector3(0f, -1f, 0f);
        character.MoveAndSlide();
        tree.ProcessFrame(tree.PhysicsDelta);
        var leftFloorTick = -1;
        var firstGravityTick = -1;
        var previousY = character.GlobalPosition.Y;
        var monotonicFall = true;
        var lowestY = previousY;
        var farthestX = character.GlobalPosition.X;
        var landedAtBottom = false;
        var fallTrace = new List<string>();
        for (var tick = 0; tick < 30; tick++)
        {
            var wasOnFloor = character.IsOnFloor;
            var vertical = wasOnFloor ? 0f : character.Velocity.Y - 24f * (float)tree.PhysicsDelta;
            character.Velocity = new Vector3(8f, vertical, 0f);
            character.MoveAndSlide();
            tree.ProcessFrame(tree.PhysicsDelta);

            if (wasOnFloor && !character.IsOnFloor && leftFloorTick < 0)
            {
                leftFloorTick = tick;
            }

            if (!character.IsOnFloor && character.Velocity.Y < -1e-4f && firstGravityTick < 0)
            {
                firstGravityTick = tick;
            }

            if (firstGravityTick >= 0 && !character.IsOnFloor && character.GlobalPosition.Y > previousY + 1e-4f)
            {
                monotonicFall = false;
            }

            lowestY = MathF.Min(lowestY, character.GlobalPosition.Y);
            farthestX = MathF.Max(farthestX, character.GlobalPosition.X);
            landedAtBottom |= character.IsOnFloor && character.GlobalPosition.Y <= 1.92f;
            if (tick < 8 || (tick & 3) == 3)
            {
                var normals = string.Join(';', Enumerable.Range(0, character.LastSlideCount)
                    .Select(index => character.GetSlideCollision(index).Normal.ToString()));
                fallTrace.Add(
                    $"{tick}:pos={character.GlobalPosition} vel={character.Velocity} floor={character.IsOnFloor} " +
                    $"slides={character.LastSlideCount} normals={normals}");
            }

            previousY = character.GlobalPosition.Y;
        }

        Check(
            "角色持续前进离开空洞后下一固定步开始连续下落而非被边缘卡住",
            terrain.UsesConservativeFallback is false && leftFloorTick >= 0 &&
            firstGravityTick == leftFloorTick + 1 && monotonicFall && lowestY <= 1.92f &&
            farthestX > 9.6f && landedAtBottom,
            $"leftFloor={leftFloorTick} firstGravity={firstGravityTick} lowestY={lowestY:F3} farthestX={farthestX:F3} " +
            $"landed={landedAtBottom} position={character.GlobalPosition} velocity={character.Velocity} floor={character.IsOnFloor} " +
            $"rebuilds={terrain.RebuildCount} trace={string.Join('|', fallTrace)}");
    }

    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(0, 0, 1);
        voxelWorld.SetBlock(10, 5, 8, BlockRegistry.Stone);
        voxelWorld.SetBlock(10, 6, 8, BlockRegistry.Stone);

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = Vector3.Zero };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8f, 5.901f, 8f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.4f, CylinderHeight = 1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        Check("前方实体方块可被挖空", voxelWorld.SetBlock(10, 5, 8, BlockRegistry.Air) && voxelWorld.SetBlock(10, 6, 8, BlockRegistry.Air));
        for (var tick = 0; tick < 10; tick++)
        {
            character.Velocity = new Vector3(8f, 0f, 0f);
            character.MoveAndSlide();
            tree.ProcessFrame(tree.PhysicsDelta);
        }

        Check(
            "挖空前方方块后角色可以通过空位",
            character.GlobalPosition.X > 11f,
            $"position={character.GlobalPosition} slides={character.LastSlideCount}");
    }

    // 单个方块修改只应更新所属区块的碰撞节点；窗口内其他区块的节点必须保留。
    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(0, 0, 1);

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = Vector3.Zero };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8f, 7f, 8f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        var oldShapes = terrain.Children.OfType<CollisionShape3D>().ToArray();
        var editTimer = Stopwatch.StartNew();
        var changed = voxelWorld.SetBlockDeferred(8, 10, 8, BlockRegistry.Stone, out var changedAffected);
        editTimer.Stop();
        tree.ProcessFrame(tree.PhysicsDelta);
        var noOpAffected = Array.Empty<(int X, int Z)>();
        var noOp = voxelWorld.SetBlockDeferred(
            8,
            10,
            8,
            BlockRegistry.Stone,
            out noOpAffected);
        Check(
            "单方块修改保留未受影响区块碰撞节点",
            changed && oldShapes.Any(terrain.Children.Contains),
            $"changed={changed} old={oldShapes.Length} retained={oldShapes.Count(terrain.Children.Contains)} rebuilds={terrain.RebuildCount} editMs={editTimer.Elapsed.TotalMilliseconds:F3}");
        Check(
            "区块内部方块修改只返回中心网格区块",
            changedAffected.Length == 1 && changedAffected[0] == (0, 0),
            $"affected={string.Join(',', changedAffected.Select(key => $"({key.X},{key.Z})"))}");
        Check(
            "重复写入相同方块不触发体素更新",
            !noOp && noOpAffected.Length == 0,
            $"changed={noOp} affected={noOpAffected.Length}");
    }

    // 连续编辑必须在完整场景帧内保持有界，不应因每次编辑都重建完整窗口而形成尖峰。
    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(0, 0, 1);

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = Vector3.Zero };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8f, 7f, 8f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        var maximumFrameMilliseconds = 0d;
        var maximumTerrainSynchronizationMilliseconds = 0d;
        var maximumPumpMilliseconds = 0d;
        var maximumMeshUploadMilliseconds = 0d;
        var maximumReconcileMilliseconds = 0d;
        var maximumStaticBvhMilliseconds = 0d;
        var maximumFrameTerrainMilliseconds = 0d;
        var maximumFramePumpMilliseconds = 0d;
        var maximumFrameUploadMilliseconds = 0d;
        var maximumFrameReconcileMilliseconds = 0d;
        var maximumFrameAllocatedBytes = 0L;
        var maximumFrameGen0Collections = 0;
        var maximumFrameWorkerMeshAllocatedBytes = 0L;
        var burstWorkerMeshStart = worldNode.Streamer?.MeshBuildAllocatedBytes ?? 0L;
        var previousWorkerMeshAllocatedBytes = burstWorkerMeshStart;
        for (var edit = 0; edit < 12; edit++)
        {
            var block = edit < 6 ? BlockRegistry.Stone : BlockRegistry.Air;
            var localX = 2 + (edit % 6);
            var frameAllocatedBefore = GC.GetAllocatedBytesForCurrentThread();
            var frameGen0Before = GC.CollectionCount(0);
            var timer = Stopwatch.StartNew();
            worldNode.TrySetBlock(localX, 10, 8, block);
            tree.ProcessFrame(tree.PhysicsDelta);
            timer.Stop();
            var frameAllocated = GC.GetAllocatedBytesForCurrentThread() - frameAllocatedBefore;
            var frameGen0 = GC.CollectionCount(0) - frameGen0Before;
            var currentWorkerMeshAllocatedBytes = worldNode.Streamer?.MeshBuildAllocatedBytes ?? previousWorkerMeshAllocatedBytes;
            var workerMeshAllocated = Math.Max(0L, currentWorkerMeshAllocatedBytes - previousWorkerMeshAllocatedBytes);
            previousWorkerMeshAllocatedBytes = currentWorkerMeshAllocatedBytes;
            maximumFrameMilliseconds = Math.Max(maximumFrameMilliseconds, timer.Elapsed.TotalMilliseconds);
            if (timer.Elapsed.TotalMilliseconds >= maximumFrameMilliseconds)
            {
                maximumFrameTerrainMilliseconds = terrain.LastSynchronizationMilliseconds;
                maximumFramePumpMilliseconds = worldNode.Streamer?.LastPumpMilliseconds ?? 0d;
                maximumFrameUploadMilliseconds = worldNode.LastMeshUploadMilliseconds;
                maximumFrameReconcileMilliseconds = physics.LastReconcileMilliseconds;
                maximumFrameAllocatedBytes = frameAllocated;
                maximumFrameGen0Collections = frameGen0;
                maximumFrameWorkerMeshAllocatedBytes = workerMeshAllocated;
            }
            maximumTerrainSynchronizationMilliseconds = Math.Max(
                maximumTerrainSynchronizationMilliseconds,
                terrain.LastSynchronizationMilliseconds);
            maximumPumpMilliseconds = Math.Max(
                maximumPumpMilliseconds,
                worldNode.Streamer?.LastPumpMilliseconds ?? 0d);
            maximumMeshUploadMilliseconds = Math.Max(
                maximumMeshUploadMilliseconds,
                worldNode.LastMeshUploadMilliseconds);
            maximumReconcileMilliseconds = Math.Max(
                maximumReconcileMilliseconds,
                physics.LastReconcileMilliseconds);
            maximumStaticBvhMilliseconds = Math.Max(
                maximumStaticBvhMilliseconds,
                physics.LastStaticBvhBuildMilliseconds);
        }

        var pendingAfterBurst = worldNode.Streamer?.PendingCount ?? -1;
        var workerMeshAllocatedAfterBurst = (worldNode.Streamer?.MeshBuildAllocatedBytes ?? burstWorkerMeshStart) - burstWorkerMeshStart;
        for (var idleFrame = 0; idleFrame < 60 && (worldNode.Streamer?.PendingCount ?? 0) > 0; idleFrame++)
        {
            tree.ProcessFrame(tree.PhysicsDelta);
            Thread.Sleep(1);
        }

        Check(
            "连续编辑期间不启动新的网格编译",
            workerMeshAllocatedAfterBurst == 0,
            $"workerMeshAllocated={workerMeshAllocatedAfterBurst} pendingAfterBurst={pendingAfterBurst}");
        Check(
            "连续编辑结束后网格最终收敛",
            (worldNode.Streamer?.PendingCount ?? -1) == 0,
            $"pending={worldNode.Streamer?.PendingCount ?? -1}");
        Check(
            "连续编辑场景帧尖峰低于 60ms",
            maximumFrameMilliseconds < 60d,
            $"maxFrameMs={maximumFrameMilliseconds:F3} terrainMs={maximumTerrainSynchronizationMilliseconds:F3} " +
            $"pumpMs={maximumPumpMilliseconds:F3} uploadMs={maximumMeshUploadMilliseconds:F3} " +
            $"reconcileMs={maximumReconcileMilliseconds:F3} bvhMs={maximumStaticBvhMilliseconds:F3} " +
            $"atMax=terrain:{maximumFrameTerrainMilliseconds:F3}/pump:{maximumFramePumpMilliseconds:F3}/upload:{maximumFrameUploadMilliseconds:F3}/reconcile:{maximumFrameReconcileMilliseconds:F3} " +
            $"alloc={maximumFrameAllocatedBytes} workerMeshAlloc={maximumFrameWorkerMeshAllocatedBytes} gen0={maximumFrameGen0Collections} " +
            $"pending={worldNode.Streamer?.PendingCount ?? -1} terrainRebuilds={terrain.RebuildCount}");
    }

    // 玩家跨越区块边界时，碰撞窗口应平移并保留重叠区块节点，而不是清空整个窗口。
    using (var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 }))
    using (var tree = new SceneTree())
    {
        var renderer = new RenderingServer(new FakeRenderBackend());
        var worldNode = new VoxelWorldNode
        {
            Name = "World",
            WorldType = WorldType.Flat,
            Jobs = jobs,
            Server = renderer,
        };
        tree.Root.AddChild(worldNode);
        var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
        voxelWorld.GenerateAround(0, 0, 1);

        var physics = new PhysicsWorld3D { Name = "Physics", Gravity = Vector3.Zero };
        var terrain = new VoxelTerrainBody3D
        {
            Name = "Terrain",
            WorldPath = "/Root/World",
            FocusPath = "/Root/Physics/Player",
            CollisionRadius = 1,
        };
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(15.5f, 7f, 8f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        physics.AddChild(terrain);
        physics.AddChild(character);
        tree.Root.AddChild(physics);
        tree.ProcessFrame(tree.PhysicsDelta);

        var oldShapes = terrain.Children.OfType<CollisionShape3D>().ToArray();
        character.Position = new Vector3(16.5f, 7f, 8f);
        tree.ProcessFrame(tree.PhysicsDelta);
        Check(
            "跨区块移动保留重叠地形碰撞节点",
            oldShapes.Any(terrain.Children.Contains) && terrain.RebuildCount == 2,
            $"retained={oldShapes.Count(terrain.Children.Contains)} rebuilds={terrain.RebuildCount} colliders={terrain.GeneratedColliderCount}");
    }

    var firstHash = SimulateVoxelTerrainCharacterHash();
    var secondHash = SimulateVoxelTerrainCharacterHash();
    Check(
        "体素地形角色 1000 tick 状态保持确定性",
        firstHash == secondHash,
        $"first={firstHash:X16} second={secondHash:X16}");

    var repositoryRoot = FindCubitRepositoryRoot();
    var workspaceRoot = repositoryRoot is null ? null : Directory.GetParent(repositoryRoot)?.FullName;
    var projectRoot = workspaceRoot is null ? null : Path.Combine(workspaceRoot, "我的第一个cubit项目");
    if (projectRoot is null || !Directory.Exists(projectRoot))
    {
        Check("官方体素项目存在", false, projectRoot ?? "找不到工作区根目录");
    }
    else
    {
        using var authoredSession = CreateVoxelProjectSession(new FakeRenderBackend(), 20260808u);
        var project = authoredSession.Scene.Runtime.Project;
        var authoredRoot = authoredSession.Scene.Tree.Root;
        var authoredPhysics = authoredRoot.Children.OfType<PhysicsWorld3D>().SingleOrDefault();
        var authoredTerrain = authoredPhysics?.Children.OfType<VoxelTerrainBody3D>().SingleOrDefault();
        var authoredPlayer = authoredPhysics?.Children.OfType<MyFirstCubitProject.PlayerController>().SingleOrDefault();
        var authoredCapsule = authoredPlayer?.Children.OfType<CollisionShape3D>().SingleOrDefault();
        Check(
            "官方体素场景作者化 Physics/地形桥/胶囊角色",
            project.Manifest.Plugins.Any(plugin => string.Equals(plugin.Id, "cubit.physics", StringComparison.OrdinalIgnoreCase)) &&
            authoredPhysics is not null && authoredTerrain is not null && authoredPlayer is not null &&
            authoredCapsule is { ShapeKind: CollisionShapeKind.Capsule } &&
            typeof(MyFirstCubitProject.PlayerController).IsSubclassOf(typeof(CharacterBody3D)),
            $"physics={authoredPhysics is not null} terrain={authoredTerrain is not null} player={authoredPlayer is not null} capsule={authoredCapsule?.ShapeKind.ToString() ?? "none"}");
    }

    Console.WriteLine(failures == 0 ? "voxelphysicscheck passed" : $"voxelphysicscheck failed {failures}");
    return failures == 0 ? 0 : 1;
}

static ulong SimulateVoxelTerrainCharacterHash()
{
    using var jobs = new JobSystem(new JobSystemOptions { WorkerCount = 1 });
    using var tree = new SceneTree();
    var renderer = new RenderingServer(new FakeRenderBackend());
    var worldNode = new VoxelWorldNode
    {
        Name = "World",
        WorldType = WorldType.Flat,
        Jobs = jobs,
        Server = renderer,
    };
    tree.Root.AddChild(worldNode);
    var voxelWorld = worldNode.World ?? throw new InvalidOperationException("体素世界没有在 Ready 创建");
    voxelWorld.GenerateAround(0, 0, 1);
    voxelWorld.SetBlock(10, 5, 8, BlockRegistry.Stone);
    voxelWorld.SetBlock(10, 6, 8, BlockRegistry.Stone);

    var physics = new PhysicsWorld3D { Name = "Physics", Gravity = Vector3.Zero };
    physics.AddChild(new VoxelTerrainBody3D
    {
        Name = "Terrain",
        WorldPath = "/Root/World",
        FocusPath = "/Root/Physics/Player",
        CollisionRadius = 1,
    });
    var character = new CharacterBody3D { Name = "Player", Position = new Vector3(8f, 5.901f, 8f) };
    character.AddChild(new CollisionShape3D
    {
        Shape = new CapsuleShape3D { Radius = 0.4f, CylinderHeight = 1f },
    });
    physics.AddChild(character);
    tree.Root.AddChild(physics);
    tree.ProcessFrame(tree.PhysicsDelta);
    tree.ProcessFrame(tree.PhysicsDelta);

    var hash = 14695981039346656037UL;
    for (var tick = 0; tick < 1_000; tick++)
    {
        character.Velocity = new Vector3(8f, -20f, (tick & 15) < 8 ? 2f : -2f);
        character.MoveAndSlide();
        tree.ProcessFrame(tree.PhysicsDelta);
        hash = MixCharacterHash(hash, character.GlobalPosition.X);
        hash = MixCharacterHash(hash, character.GlobalPosition.Y);
        hash = MixCharacterHash(hash, character.GlobalPosition.Z);
        hash ^= character.IsOnFloor ? 1UL : 0UL;
        hash *= 1099511628211UL;
        hash ^= (uint)character.LastSlideCount;
        hash *= 1099511628211UL;
    }

    return hash;
}

static int PhysicsCheck()
{
    var failures = 0;

    void Check(string name, bool ok, string detail = "")
    {
        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {name}  {detail}");
        if (!ok) failures++;
    }

    var parent = new Node3D { Position = new Vector3(10f, 0f, 0f) };
    var child = new Node3D { Position = Vector3.UnitX };
    parent.AddChild(child);
    Check(
        "Node3D composes parent position",
        child.GlobalPosition == new Vector3(11f, 0f, 0f));
    Check(
        "Node3D composes parent rotation and scale",
        Vector3.Distance(
            Transform3D.Combine(
                new Transform3D(Vector3.UnitX, Quaternion.Identity, 1f),
                new Transform3D(Vector3.Zero, Quaternion.CreateFromAxisAngle(Vector3.UnitY, MathF.PI * 0.5f), 2f)).Position,
            new Vector3(0f, 0f, -2f)) < 0.0001f);
    Check(
        "Transform3D rejects non-finite scale",
        CaptureException(() => new Transform3D(Vector3.Zero, Quaternion.Identity, float.NaN)) is ArgumentException);
    Check(
        "Transform3D rejects zero scale",
        CaptureException(() => new Transform3D(Vector3.Zero, Quaternion.Identity, 0f)) is ArgumentException);
    Check(
        "Transform3D identifies default value as invalid",
        !Transform3D.IsValid(default) && Transform3D.IsValid(Transform3D.Identity));
    Check(
        "Transform3D rejects overflowing rotation length",
        CaptureException(() => new Transform3D(
            Vector3.Zero,
            new Quaternion(float.MaxValue, 0f, 0f, 1f),
            1f)) is ArgumentException);
    Check("BoxMesh3D inherits Node3D", new BoxMesh3D() is Node3D);
    Check(
        "ClassDB registers Node3D",
        Cubit.Core.ObjectSystem.ClassDB.ResolveType(nameof(Node3D)) == typeof(Node3D));

    var box = new BoxShape3D { Size = new Vector3(2f, 4f, 6f) };
    var boxBounds = box.GetLocalBounds();
    Check(
        "BoxShape3D reports centered bounds",
        boxBounds.Min == new Vector3(-1f, -2f, -3f) &&
        boxBounds.Max == new Vector3(1f, 2f, 3f));
    Check(
        "SphereShape3D rejects zero radius",
        CaptureException(() => new SphereShape3D { Radius = 0f }.GetLocalBounds()) is InvalidOperationException);
    Check(
        "CapsuleShape3D reports cylinder plus cap bounds",
        new CapsuleShape3D { Radius = 0.5f, CylinderHeight = 2f }.GetLocalBounds().Max == new Vector3(0.5f, 1.5f, 0.5f));

    var authoredShape = SceneIO.DeserializeFromJson(
        """
        {
          "Type": "Cubit.Physics.Scene.CollisionShape3D",
          "Name": "AuthoredCapsule",
          "Properties": {
            "ShapeKind": 2,
            "CapsuleRadius": 0.35,
            "CapsuleCylinderHeight": 1.1
          }
        }
        """,
        type => type == typeof(CollisionShape3D).FullName
            ? new CollisionShape3D()
            : throw new InvalidOperationException($"Unexpected shape node type: {type}")) as CollisionShape3D
        ?? throw new InvalidOperationException("作者化碰撞形状没有反序列化为 CollisionShape3D");
    using (var authoredShapeTree = new SceneTree())
    {
        var authoredWorld = new PhysicsWorld3D { Name = "AuthoredPhysics" };
        var authoredBody = new StaticBody3D { Name = "AuthoredBody" };
        authoredBody.AddChild(authoredShape);
        authoredWorld.AddChild(authoredBody);
        authoredShapeTree.Root.AddChild(authoredWorld);
        authoredShapeTree.ProcessFrame(authoredShapeTree.PhysicsDelta);
        Check(
            "CollisionShape3D 从场景导出的胶囊配置创建形状",
            authoredShape.ShapeKind == CollisionShapeKind.Capsule &&
            authoredShape.Shape is CapsuleShape3D { Radius: 0.35f, CylinderHeight: 1.1f } &&
            authoredWorld.ColliderCount == 1,
            $"kind={authoredShape.ShapeKind} shape={authoredShape.Shape?.GetType().Name ?? "none"} colliders={authoredWorld.ColliderCount}");
        var colliderIdProperty = typeof(CollisionShape3D).GetProperty("ColliderId");
        var colliderIdValue = colliderIdProperty?.GetValue(authoredShape);
        Check(
            "CollisionShape3D 公开稳定 ColliderId 读取契约",
            colliderIdProperty?.PropertyType == typeof(long) && colliderIdProperty.CanRead &&
            colliderIdValue is long id && id > 0,
            colliderIdValue?.ToString() ?? "missing");
    }

    var physicsPlugin = new CubitPhysicsPlugin();
    Check(
        "CubitPhysicsPlugin reports stable identity",
        physicsPlugin.Id == "cubit.physics" && physicsPlugin.Version == new Version(1, 0, 0));
    using (var physicsPlugins = CreateToolPluginManager([physicsPlugin]))
    {
        physicsPlugins.Configure([
            new CubitPluginReference { Id = "cubit.physics", Version = "1.0.0" },
        ]);
        Check(
            "CubitPhysicsPlugin registers public collision types",
            physicsPlugins.SceneRegistry.ResolveResourceType(nameof(BoxShape3D)) == typeof(BoxShape3D) &&
            physicsPlugins.SceneRegistry.ResolveNodeType(nameof(Area3D)) == typeof(Area3D) &&
            physicsPlugins.SceneRegistry.ResolveNodeType(nameof(StaticBody3D)) == typeof(StaticBody3D) &&
            physicsPlugins.SceneRegistry.ResolveNodeType(nameof(CharacterBody3D)) == typeof(CharacterBody3D) &&
            physicsPlugins.SceneRegistry.ResolveNodeType(nameof(PhysicsWorld3D)) == typeof(PhysicsWorld3D));

        var physicsContext = new EngineContext();
        physicsPlugin.Start(physicsContext);
        var duplicateStart = CaptureException(() => physicsPlugin.Start(physicsContext));
        Check(
            "CubitPhysicsPlugin gates duplicate start without creating a global world service",
            physicsPlugin.IsStarted && duplicateStart is InvalidOperationException &&
            !physicsContext.TryGetService<PhysicsWorld3D>(out _),
            $"started={physicsPlugin.IsStarted} duplicate={duplicateStart?.GetType().Name ?? "none"}");
        physicsPlugin.Stop();
        physicsPlugin.Stop();
        Check("CubitPhysicsPlugin Stop is idempotent", !physicsPlugin.IsStarted);

        var offThreadContext = new EngineContext();
        Exception? offThreadStart = null;
        var offThread = new Thread(() => offThreadStart = CaptureException(() => physicsPlugin.Start(offThreadContext)));
        offThread.Start();
        offThread.Join();
        Check(
            "CubitPhysicsPlugin rejects off-main-thread start",
            offThreadStart is InvalidOperationException && !physicsPlugin.IsStarted,
            $"error={offThreadStart?.GetType().Name ?? "none"}");
    }

    var staticBody = new StaticBody3D();
    staticBody.AddChild(new CollisionShape3D { Shape = box });
    Check(
        "CollisionShape3D can be attached below collision body",
        staticBody.Children.Single() is CollisionShape3D { Shape: BoxShape3D });

    using (var physicsTree = new SceneTree())
    {
        var world = new PhysicsWorld3D { Name = "Physics" };
        var wall = new StaticBody3D
        {
            Name = "Wall",
            CollisionLayer = 0b0010,
            CollisionMask = 0b0001,
        };
        wall.AddChild(new CollisionShape3D
        {
            Name = "WallShape",
            Shape = new BoxShape3D { Size = Vector3.One },
        });
        world.AddChild(wall);
        physicsTree.Root.AddChild(world);
        physicsTree.ProcessFrame(physicsTree.PhysicsDelta);
        Check("PhysicsWorld3D registers shape child", world.ColliderCount == 1);
        Check(
            "PhysicsWorld3D requires both collision masks",
            !world.CanCollide(0b0100, 0b0001, 0b0010, 0b0001));
    }

    using (var threadBoundaryPhysicsTree = new SceneTree())
    {
        var threadBoundaryWorld = new PhysicsWorld3D { Name = "ThreadBoundaryPhysics", Gravity = Vector3.Zero };
        var rigidBody = new RigidBody3D
        {
            Name = "ThreadBoundaryRigidBody",
            Mass = 2f,
            LinearVelocity = new Vector3(1f, 2f, 3f),
        };
        rigidBody.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        var character = new CharacterBody3D
        {
            Name = "ThreadBoundaryCharacter",
            Velocity = new Vector3(4f, 5f, 6f),
            UpDirection = Vector3.UnitY,
            FloorMaxAngleCosine = 0.5f,
        };
        character.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        threadBoundaryWorld.AddChild(rigidBody);
        threadBoundaryWorld.AddChild(character);
        threadBoundaryPhysicsTree.Root.AddChild(threadBoundaryWorld);
        threadBoundaryPhysicsTree.ProcessFrame(threadBoundaryPhysicsTree.PhysicsDelta);

        var originalGravity = threadBoundaryWorld.Gravity;
        var originalMass = rigidBody.Mass;
        var originalLinearVelocity = rigidBody.LinearVelocity;
        var originalVelocity = character.Velocity;
        var originalUpDirection = character.UpDirection;
        var originalFloorMaxAngleCosine = character.FloorMaxAngleCosine;
        Exception? gravityError = null;
        Exception? massError = null;
        Exception? linearVelocityError = null;
        Exception? velocityError = null;
        Exception? upDirectionError = null;
        Exception? floorMaxAngleError = null;
        var worker = new Thread(() =>
        {
            gravityError = CaptureException(() => threadBoundaryWorld.Gravity = Vector3.UnitY);
            massError = CaptureException(() => rigidBody.Mass = 3f);
            linearVelocityError = CaptureException(() => rigidBody.LinearVelocity = Vector3.UnitX);
            velocityError = CaptureException(() => character.Velocity = Vector3.UnitX);
            upDirectionError = CaptureException(() => character.UpDirection = Vector3.UnitZ);
            floorMaxAngleError = CaptureException(() => character.FloorMaxAngleCosine = 0.25f);
        });
        worker.Start();
        worker.Join();
        Check(
            "Physics nodes reject off-thread mutable state after entering a world",
            gravityError is InvalidOperationException &&
            massError is InvalidOperationException &&
            linearVelocityError is InvalidOperationException &&
            velocityError is InvalidOperationException &&
            upDirectionError is InvalidOperationException &&
            floorMaxAngleError is InvalidOperationException &&
            threadBoundaryWorld.Gravity == originalGravity &&
            rigidBody.Mass == originalMass &&
            rigidBody.LinearVelocity == originalLinearVelocity &&
            character.Velocity == originalVelocity &&
            character.UpDirection == originalUpDirection &&
            character.FloorMaxAngleCosine == originalFloorMaxAngleCosine,
            $"gravity={gravityError?.GetType().Name ?? "none"} mass={massError?.GetType().Name ?? "none"} " +
            $"linear={linearVelocityError?.GetType().Name ?? "none"} velocity={velocityError?.GetType().Name ?? "none"} " +
            $"up={upDirectionError?.GetType().Name ?? "none"} floor={floorMaxAngleError?.GetType().Name ?? "none"}");
    }

    using (var warmPhysicsTree = new SceneTree())
    {
        var warmWorld = new PhysicsWorld3D();
        var warmWall = new StaticBody3D();
        warmWall.AddChild(new CollisionShape3D { Shape = new BoxShape3D() });
        warmWorld.AddChild(warmWall);
        warmPhysicsTree.Root.AddChild(warmWorld);
        warmPhysicsTree.ProcessFrame(warmPhysicsTree.PhysicsDelta);
        var allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        for (var tick = 0; tick < 100; tick++)
        {
            warmPhysicsTree.ProcessFrame(warmPhysicsTree.PhysicsDelta);
        }

        var allocated = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
        Check("PhysicsWorld3D warm static step has no allocations", allocated == 0, $"bytes={allocated}");
    }

    using (var diagnosticsPhysicsTree = new SceneTree())
    {
        var outerWorld = new PhysicsWorld3D { Name = "OuterPhysics" };
        outerWorld.AddChild(new CollisionShape3D { Name = "OrphanShape", Shape = new BoxShape3D() });
        var nestedWorld = new PhysicsWorld3D { Name = "NestedPhysics" };
        var nestedWall = new StaticBody3D();
        nestedWall.AddChild(new CollisionShape3D { Shape = new BoxShape3D() });
        nestedWorld.AddChild(nestedWall);
        outerWorld.AddChild(nestedWorld);
        diagnosticsPhysicsTree.Root.AddChild(outerWorld);
        diagnosticsPhysicsTree.ProcessFrame(diagnosticsPhysicsTree.PhysicsDelta);
        var diagnosticCodes = outerWorld.Diagnostics.Snapshot().Select(diagnostic => diagnostic.Code).ToHashSet();
        Check(
            "PhysicsWorld3D reports missing and nested hierarchy",
            diagnosticCodes.Contains("physics.world.missing") && diagnosticCodes.Contains("physics.world.nested") &&
            outerWorld.ColliderCount == 0 && nestedWorld.ColliderCount == 0);
    }

    using (var staticPhysicsTree = new SceneTree())
    {
        var staticWorld = new PhysicsWorld3D();
        var immutableWall = new StaticBody3D();
        immutableWall.AddChild(new CollisionShape3D { Shape = new BoxShape3D() });
        staticWorld.AddChild(immutableWall);
        staticPhysicsTree.Root.AddChild(staticWorld);
        staticPhysicsTree.ProcessFrame(staticPhysicsTree.PhysicsDelta);
        immutableWall.Position = Vector3.UnitX;
        staticPhysicsTree.ProcessFrame(staticPhysicsTree.PhysicsDelta);
        Check(
            "PhysicsWorld3D reports static transform mutation",
            staticWorld.Diagnostics.Snapshot().Any(diagnostic => diagnostic.Code == "physics.static.transform"));
        var staticSnapshotHits = new List<PhysicsRayHit3D>();
        var staticSnapshotHitCount = staticWorld.Raycast(
            new Vector3(-4f, 0f, 0f),
            Vector3.UnitX,
            4f,
            default,
            staticSnapshotHits);
        Check(
            "PhysicsWorld3D keeps static narrow-phase at its registered transform",
            staticSnapshotHitCount == 1 && MathF.Abs(staticSnapshotHits[0].Distance - 3.5f) < 0.0001f,
            staticSnapshotHitCount == 1 ? $"distance={staticSnapshotHits[0].Distance}" : $"count={staticSnapshotHitCount}");
    }

    using (var queryPhysicsTree = new SceneTree())
    {
        var queryWorld = new PhysicsWorld3D();
        var wall = new StaticBody3D { Name = "QueryWall", Position = new Vector3(5f, 0f, 0f), CollisionLayer = 0b0010 };
        wall.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = Vector3.One } });
        var area = new Area3D { Name = "QueryArea", Position = new Vector3(10f, 0f, 0f), CollisionLayer = 0b0010 };
        area.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        queryWorld.AddChild(wall);
        queryWorld.AddChild(area);
        queryPhysicsTree.Root.AddChild(queryWorld);
        queryPhysicsTree.ProcessFrame(queryPhysicsTree.PhysicsDelta);

        var hits = new List<PhysicsRayHit3D>();
        var hitCount = queryWorld.Raycast(
            Vector3.Zero,
            Vector3.UnitX,
            20f,
            new PhysicsQueryFilter(collisionMask: 0b0010),
            hits);
        Check(
            "PhysicsWorld3D raycast returns nearest exact hit",
            hitCount == 2 && hits[0].Collider == wall && MathF.Abs(hits[0].Distance - 4.5f) < 0.0001f);
        Check("PhysicsWorld3D raycast appends to caller buffer", hits.Count == 2);
        var bufferedHits = new List<PhysicsRayHit3D> { hits[1] };
        var bufferedHitCount = queryWorld.Raycast(
            Vector3.Zero,
            Vector3.UnitX,
            20f,
            new PhysicsQueryFilter(collisionMask: 0b0010),
            bufferedHits);
        Check(
            "PhysicsWorld3D raycast preserves caller buffer prefix",
            bufferedHitCount == 2 && bufferedHits.Count == 3 && bufferedHits[0] == hits[1] &&
            bufferedHits[1].Collider == wall && bufferedHits[2].Collider == area);
        var invalidRayOrigin = CaptureException(() => queryWorld.Raycast(
            new Vector3(float.NaN, 0f, 0f),
            Vector3.UnitX,
            1f,
            new PhysicsQueryFilter(),
            new List<PhysicsRayHit3D>()));
        var invalidRayDirection = CaptureException(() => queryWorld.Raycast(
            Vector3.Zero,
            Vector3.Zero,
            1f,
            new PhysicsQueryFilter(),
            new List<PhysicsRayHit3D>()));
        var invalidRayDistance = CaptureException(() => queryWorld.Raycast(
            Vector3.Zero,
            Vector3.UnitX,
            float.PositiveInfinity,
            new PhysicsQueryFilter(),
            new List<PhysicsRayHit3D>()));
        Check(
            "PhysicsWorld3D raycast rejects non-finite origin, zero direction, and invalid distance",
            invalidRayOrigin is ArgumentException && invalidRayDirection is ArgumentException &&
            invalidRayDistance is ArgumentOutOfRangeException);

        var filteredHits = new List<PhysicsRayHit3D>();
        var filteredCount = queryWorld.Raycast(
            Vector3.Zero,
            Vector3.UnitX,
            20f,
            new PhysicsQueryFilter(collisionMask: 0b0010, exclude: wall),
            filteredHits);
        Check(
            "PhysicsWorld3D raycast honors exclusion and dynamic proxy",
            filteredCount == 1 && filteredHits[0].Collider == area && MathF.Abs(filteredHits[0].Distance - 9.5f) < 0.0001f);

        var reverseBoxHits = new List<PhysicsRayHit3D>();
        var reverseBoxHitCount = queryWorld.Raycast(
            new Vector3(8f, 0f, 0f),
            -Vector3.UnitX,
            20f,
            new PhysicsQueryFilter(collisionMask: 0b0010),
            reverseBoxHits);
        Check(
            "PhysicsWorld3D raycast returns outward normal for reverse box ray",
            reverseBoxHitCount == 1 && reverseBoxHits[0].Collider == wall &&
            Vector3.Distance(reverseBoxHits[0].Normal, Vector3.UnitX) < 0.0001f,
            reverseBoxHits.Count == 1 ? $"normal={reverseBoxHits[0].Normal}" : $"count={reverseBoxHits.Count}");

        var overlapHits = new List<PhysicsOverlapHit3D>();
        var overlapCount = queryWorld.Overlap(
            new SphereShape3D { Radius = 1f },
            new Transform3D(new Vector3(5.75f, 0f, 0f), Quaternion.Identity, 1f),
            new PhysicsQueryFilter(collisionMask: 0b0010),
            overlapHits);
        Check(
            "PhysicsWorld3D overlap reports exact primitive pair",
            overlapCount == 1 && overlapHits[0].Collider == wall && overlapHits.Count == 1);
        var invalidOverlapTransform = CaptureException(() => queryWorld.Overlap(
            new SphereShape3D { Radius = 1f },
            default,
            new PhysicsQueryFilter(collisionMask: 0b0010),
            new List<PhysicsOverlapHit3D>()));
        Check(
            "PhysicsWorld3D overlap rejects default transform",
            invalidOverlapTransform is ArgumentException,
            invalidOverlapTransform?.Message ?? "未抛出异常");
    }

    using (var capsulePhysicsTree = new SceneTree())
    {
        var capsuleWorld = new PhysicsWorld3D();
        var capsuleBody = new StaticBody3D { Position = new Vector3(5f, 0f, 0f), CollisionLayer = 0b0100 };
        capsuleBody.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.5f, CylinderHeight = 2f },
        });
        capsuleWorld.AddChild(capsuleBody);
        capsulePhysicsTree.Root.AddChild(capsuleWorld);
        capsulePhysicsTree.ProcessFrame(capsulePhysicsTree.PhysicsDelta);
        var capsuleHits = new List<PhysicsRayHit3D>();
        var capsuleHitCount = capsuleWorld.Raycast(
            Vector3.Zero,
            Vector3.UnitX,
            20f,
            new PhysicsQueryFilter(collisionMask: 0b0100),
            capsuleHits);
        Check(
            "PhysicsWorld3D raycast hits exact capsule",
            capsuleHitCount == 1 && MathF.Abs(capsuleHits[0].Distance - 4.5f) < 0.0001f);
        var capsuleBoundaryHits = new List<PhysicsRayHit3D>();
        var capsuleBoundaryHitCount = capsuleWorld.Raycast(
            Vector3.Zero,
            Vector3.UnitX,
            4.5f,
            new PhysicsQueryFilter(collisionMask: 0b0100),
            capsuleBoundaryHits);
        Check(
            "PhysicsWorld3D raycast includes capsule hit at max distance",
            capsuleBoundaryHitCount == 1 && capsuleBoundaryHits.Count == 1 &&
            MathF.Abs(capsuleBoundaryHits[0].Distance - 4.5f) < 0.0001f,
            capsuleBoundaryHits.Count == 1 ? $"distance={capsuleBoundaryHits[0].Distance}" : $"count={capsuleBoundaryHits.Count}");
        var capsuleAxisHits = new List<PhysicsRayHit3D>();
        var capsuleAxisHitCount = capsuleWorld.Raycast(
            new Vector3(5f, 0f, 0f),
            Vector3.UnitY,
            20f,
            new PhysicsQueryFilter(collisionMask: 0b0100),
            capsuleAxisHits);
        Check(
            "PhysicsWorld3D raycast limits capsule cap to its outward hemisphere",
            capsuleAxisHitCount == 1 && capsuleAxisHits.Count == 1 &&
            MathF.Abs(capsuleAxisHits[0].Distance - 1.5f) < 0.0001f &&
            Vector3.Distance(capsuleAxisHits[0].Normal, Vector3.UnitY) < 0.0001f,
            capsuleAxisHits.Count == 1
                ? $"distance={capsuleAxisHits[0].Distance} normal={capsuleAxisHits[0].Normal}"
                : $"count={capsuleAxisHits.Count}");
        var capsuleOverlapHits = new List<PhysicsOverlapHit3D>();
        var capsuleOverlapCount = capsuleWorld.Overlap(
            new SphereShape3D { Radius = 0.5f },
            new Transform3D(new Vector3(5.9f, 0f, 0f), Quaternion.Identity, 1f),
            new PhysicsQueryFilter(collisionMask: 0b0100),
            capsuleOverlapHits);
        Check(
            "PhysicsWorld3D overlap handles sphere and capsule",
            capsuleOverlapCount == 1 && capsuleOverlapHits[0].Collider == capsuleBody);
    }

    using (var tiePhysicsTree = new SceneTree())
    {
        var tieWorld = new PhysicsWorld3D { Name = "TieWorld" };
        var tieB = new StaticBody3D { Name = "B", Position = new Vector3(5f, 0f, 0f) };
        tieB.AddChild(new CollisionShape3D { Shape = new BoxShape3D() });
        var tieA = new StaticBody3D { Name = "A", Position = new Vector3(5f, 0f, 0f) };
        tieA.AddChild(new CollisionShape3D { Shape = new BoxShape3D() });
        tieWorld.AddChild(tieB);
        tieWorld.AddChild(tieA);
        tiePhysicsTree.Root.AddChild(tieWorld);
        tiePhysicsTree.ProcessFrame(tiePhysicsTree.PhysicsDelta);
        var tieHits = new List<PhysicsRayHit3D>();
        var defaultFilterHitCount = tieWorld.Raycast(
            Vector3.Zero,
            Vector3.UnitX,
            20f,
            new PhysicsQueryFilter(),
            tieHits);
        Check(
            "PhysicsQueryFilter default constructor accepts all collision layers",
            defaultFilterHitCount == 2 && tieHits.Count == 2,
            string.Join(",", tieHits.Select(hit => $"{hit.Collider.Name}:{hit.ColliderId}:{hit.Distance}")));
        var defaultValueHits = new List<PhysicsRayHit3D>();
        var defaultValueHitCount = tieWorld.Raycast(
            Vector3.Zero,
            Vector3.UnitX,
            20f,
            default,
            defaultValueHits);
        Check(
            "PhysicsQueryFilter default value accepts all collision layers",
            defaultValueHitCount == 2 && defaultValueHits.Count == 2,
            string.Join(",", defaultValueHits.Select(hit => $"{hit.Collider.Name}:{hit.ColliderId}:{hit.Distance}")));
        Check(
            "PhysicsWorld3D raycast tie breaks by collider id",
            tieHits.Count == 2 && tieHits[0].Collider == tieA && tieHits[0].ColliderId < tieHits[1].ColliderId,
            string.Join(",", tieHits.Select(hit => $"{hit.Collider.Name}:{hit.ColliderId}:{hit.Distance}")));
    }

    using (var obbPhysicsTree = new SceneTree())
