    using (var largeCapsulePhysicsTree = new SceneTree())
    {
        var largeCapsuleWorld = new PhysicsWorld3D();
        var largeCapsule = new StaticBody3D { Scale = 2_000_000f };
        largeCapsule.AddChild(new CollisionShape3D { Shape = new CapsuleShape3D() });
        largeCapsuleWorld.AddChild(largeCapsule);
        largeCapsulePhysicsTree.Root.AddChild(largeCapsuleWorld);
        largeCapsulePhysicsTree.ProcessFrame(largeCapsulePhysicsTree.PhysicsDelta);
        var largeCapsuleHits = new List<PhysicsRayHit3D>();
        var largeCapsuleHitCount = largeCapsuleWorld.Raycast(
            new Vector3(-3_000_000f, 0f, 0f),
            Vector3.UnitX,
            2_000_000f,
            new PhysicsQueryFilter(),
            largeCapsuleHits);
        Check(
            "PhysicsWorld3D raycast handles valid large uniform capsule scale",
            largeCapsuleHitCount == 1 && largeCapsuleHits.Count == 1 &&
            MathF.Abs(largeCapsuleHits[0].Distance - 2_000_000f) < 0.25f,
            largeCapsuleHits.Count == 1 ? $"distance={largeCapsuleHits[0].Distance}" : $"count={largeCapsuleHits.Count}");
    }

    using (var areaPhysicsTree = new SceneTree())
    {
        var areaWorld = new PhysicsWorld3D();
        var area = new Area3D { Name = "Trigger" };
        area.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 1f } });
        var body = new StaticBody3D { Name = "Body", Position = new Vector3(0.5f, 0f, 0f) };
        body.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        var deferredBody = new StaticBody3D { Name = "DeferredBody", Position = new Vector3(-0.5f, 0f, 0f) };
        deferredBody.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        var areaEvents = new List<PhysicsAreaEvent>();
        var callbackAddedBody = false;
        area.BodyEntered += other =>
        {
            areaEvents.Add(new PhysicsAreaEvent(area, other, true, 0, 0));
            if (ReferenceEquals(other, body) && !callbackAddedBody)
            {
                callbackAddedBody = true;
                areaWorld.AddChild(deferredBody);
            }
        };
        area.BodyExited += other => areaEvents.Add(new PhysicsAreaEvent(area, other, false, 0, 0));
        areaWorld.AddChild(area);
        areaWorld.AddChild(body);
        areaPhysicsTree.Root.AddChild(areaWorld);
        areaPhysicsTree.ProcessFrame(areaPhysicsTree.PhysicsDelta);
        Check(
            "Area3D emits one ordered enter and queues callback mutation",
            callbackAddedBody && areaEvents is [{ Entered: true, Other: var enteredBody }] && ReferenceEquals(enteredBody, body));
        Check(
            "Area3D callback keeps added node detached until next fixed step",
            deferredBody.Parent is null,
            deferredBody.Parent?.GetPath().Value ?? "detached");
        areaPhysicsTree.ProcessFrame(areaPhysicsTree.PhysicsDelta);
        Check(
            "Area3D callback addition applies before the next fixed detection",
            ReferenceEquals(deferredBody.Parent, areaWorld) && areaEvents.Count == 2 &&
            areaEvents[1] is { Entered: true, Other: var enteredDeferred } && ReferenceEquals(enteredDeferred, deferredBody));
        areaWorld.RemoveChild(body);
        areaPhysicsTree.ProcessFrame(areaPhysicsTree.PhysicsDelta);
        Check(
            "Area3D removal emits one exit without stay duplicates",
            areaEvents.Count == 3 && areaEvents[2] is { Entered: false, Other: var exitedBody } &&
            ReferenceEquals(exitedBody, body));
        areaPhysicsTree.ProcessFrame(areaPhysicsTree.PhysicsDelta);
        Check("Area3D stay does not emit duplicate event", areaEvents.Count == 3);
    }

    using (var callbackRemovalPhysicsTree = new SceneTree())
    {
        var areaWorld = new PhysicsWorld3D();
        var area = new Area3D { Name = "RemovalTrigger" };
        area.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 1f } });
        var body = new StaticBody3D { Name = "RemovalBody", Position = new Vector3(0.5f, 0f, 0f) };
        body.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        var removalRequested = false;
        var exitCount = 0;
        area.BodyEntered += other =>
        {
            if (ReferenceEquals(other, body) && !removalRequested)
            {
                removalRequested = true;
                areaWorld.RemoveChild(body);
            }
        };
        area.BodyExited += other =>
        {
            if (ReferenceEquals(other, body))
            {
                exitCount++;
            }
        };
        areaWorld.AddChild(area);
        areaWorld.AddChild(body);
        callbackRemovalPhysicsTree.Root.AddChild(areaWorld);
        callbackRemovalPhysicsTree.ProcessFrame(callbackRemovalPhysicsTree.PhysicsDelta);
        Check(
            "Area3D callback keeps removed node attached until next fixed step",
            removalRequested && ReferenceEquals(body.Parent, areaWorld) && exitCount == 0,
            body.Parent?.GetPath().Value ?? "detached");
        callbackRemovalPhysicsTree.ProcessFrame(callbackRemovalPhysicsTree.PhysicsDelta);
        Check(
            "Area3D callback removal applies before the next fixed detection",
            body.Parent is null && exitCount == 1,
            $"parent={body.Parent?.GetPath().Value ?? "detached"} exits={exitCount}");
        callbackRemovalPhysicsTree.ProcessFrame(callbackRemovalPhysicsTree.PhysicsDelta);
        Check("Area3D callback removal has no duplicate exit", exitCount == 1, $"exits={exitCount}");
    }

    using (var callbackConflictPhysicsTree = new SceneTree())
    {
        var areaWorld = new PhysicsWorld3D();
        var area = new Area3D { Name = "ConflictTrigger" };
        area.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 1f } });
        var body = new StaticBody3D { Name = "ConflictBody", Position = new Vector3(0.5f, 0f, 0f) };
        body.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        var queuedBody = new StaticBody3D { Name = "QueuedConflictBody" };
        Exception? conflict = null;
        area.BodyEntered += other =>
        {
            if (ReferenceEquals(other, body))
            {
                areaWorld.AddChild(queuedBody);
                conflict = CaptureException(() => areaWorld.RemoveChild(queuedBody));
            }
        };
        areaWorld.AddChild(area);
        areaWorld.AddChild(body);
        callbackConflictPhysicsTree.Root.AddChild(areaWorld);
        callbackConflictPhysicsTree.ProcessFrame(callbackConflictPhysicsTree.PhysicsDelta);
        Check(
            "Area3D callback rejects conflicting add then remove for one node",
            conflict is InvalidOperationException && queuedBody.Parent is null,
            conflict?.Message ?? "no exception");
    }

    using (var callbackBoundaryPhysicsTree = new SceneTree())
    {
        var areaWorld = new PhysicsWorld3D();
        var area = new Area3D { Name = "BoundaryTrigger" };
        area.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 1f } });
        var body = new StaticBody3D { Name = "BoundaryBody", Position = new Vector3(0.5f, 0f, 0f) };
        body.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        var queuedBody = new StaticBody3D { Name = "QueuedBoundaryBody" };
        var processProbe = new DeferredStructureMutationNode();
        Exception? processAddError = null;
        Exception? processRemoveError = null;
        area.BodyEntered += other =>
        {
            if (ReferenceEquals(other, body))
            {
                areaWorld.AddChild(queuedBody);
            }
        };
        processProbe.ProcessAction = () =>
        {
            processAddError = CaptureException(() => areaWorld.AddChild(queuedBody));
            processRemoveError = CaptureException(() => areaWorld.RemoveChild(queuedBody));
            processProbe.ProcessAction = null;
        };
        areaWorld.AddChild(area);
        areaWorld.AddChild(body);
        callbackBoundaryPhysicsTree.Root.AddChild(areaWorld);
        callbackBoundaryPhysicsTree.Root.AddChild(processProbe);
        callbackBoundaryPhysicsTree.ProcessFrame(callbackBoundaryPhysicsTree.PhysicsDelta);
        Check(
            "Area3D pending mutation rejects ordinary Process add and remove before next fixed step",
            processAddError is InvalidOperationException && processRemoveError is InvalidOperationException &&
            queuedBody.Parent is null,
            $"add={processAddError?.GetType().Name ?? "none"} remove={processRemoveError?.GetType().Name ?? "none"}");
        callbackBoundaryPhysicsTree.ProcessFrame(callbackBoundaryPhysicsTree.PhysicsDelta);
        Check(
            "Area3D pending mutation applies once at the following fixed-step boundary",
            ReferenceEquals(queuedBody.Parent, areaWorld),
            queuedBody.Parent?.GetPath().Value ?? "detached");
    }

    using (var warmAreaPhysicsTree = new SceneTree())
    {
        var areaWorld = new PhysicsWorld3D();
        var area = new Area3D { Name = "WarmTrigger" };
        area.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 1f } });
        var body = new StaticBody3D { Name = "WarmBody", Position = new Vector3(0.5f, 0f, 0f) };
        body.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        areaWorld.AddChild(area);
        areaWorld.AddChild(body);
        warmAreaPhysicsTree.Root.AddChild(areaWorld);
        warmAreaPhysicsTree.ProcessFrame(warmAreaPhysicsTree.PhysicsDelta);
        var allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        for (var tick = 0; tick < 100; tick++)
        {
            warmAreaPhysicsTree.ProcessFrame(warmAreaPhysicsTree.PhysicsDelta);
        }

        var allocated = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
        Check("Area3D warm stable overlap has no event-path allocations", allocated == 0, $"bytes={allocated}");
    }

    using (var orderedAreasPhysicsTree = new SceneTree())
    {
        var areaWorld = new PhysicsWorld3D { Name = "OrderedWorld" };
        var beta = new Area3D { Name = "Beta" };
        beta.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 1f } });
        var alpha = new Area3D { Name = "Alpha" };
        alpha.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 1f } });
        var body = new StaticBody3D { Name = "OrderedBody", Position = new Vector3(0.5f, 0f, 0f) };
        body.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        var enterOrder = new List<string>();
        alpha.BodyEntered += _ => enterOrder.Add(alpha.Name);
        beta.BodyEntered += _ => enterOrder.Add(beta.Name);
        areaWorld.AddChild(beta);
        areaWorld.AddChild(alpha);
        areaWorld.AddChild(body);
        orderedAreasPhysicsTree.Root.AddChild(areaWorld);
        orderedAreasPhysicsTree.ProcessFrame(orderedAreasPhysicsTree.PhysicsDelta);
        Check(
            "Area3D dispatches simultaneous enters by stable area collider order",
            enterOrder.SequenceEqual(["Alpha", "Beta"]),
            string.Join(",", enterOrder));
    }

    using (var areaRemovalPhysicsTree = new SceneTree())
    {
        var areaWorld = new PhysicsWorld3D();
        var area = new Area3D { Name = "RemovedArea" };
        area.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 1f } });
        var body = new StaticBody3D { Name = "AreaRemovalBody", Position = new Vector3(0.5f, 0f, 0f) };
        body.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        var entered = 0;
        var exited = 0;
        area.BodyEntered += other =>
        {
            if (ReferenceEquals(other, body))
            {
                entered++;
            }
        };
        area.BodyExited += other =>
        {
            if (ReferenceEquals(other, body))
            {
                exited++;
            }
        };
        areaWorld.AddChild(area);
        areaWorld.AddChild(body);
        areaRemovalPhysicsTree.Root.AddChild(areaWorld);
        areaRemovalPhysicsTree.ProcessFrame(areaRemovalPhysicsTree.PhysicsDelta);
        areaWorld.RemoveChild(area);
        areaRemovalPhysicsTree.ProcessFrame(areaRemovalPhysicsTree.PhysicsDelta);
        areaRemovalPhysicsTree.ProcessFrame(areaRemovalPhysicsTree.PhysicsDelta);
        Check(
            "Area3D removal emits one exit for its previous pair",
            entered == 1 && exited == 1,
            $"entered={entered} exited={exited}");
    }

    using (var shapeRemovalPhysicsTree = new SceneTree())
    {
        var areaWorld = new PhysicsWorld3D();
        var area = new Area3D { Name = "ShapeRemovalTrigger" };
        area.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 1f } });
        var body = new StaticBody3D { Name = "ShapeRemovalBody", Position = new Vector3(0.5f, 0f, 0f) };
        var firstShape = new CollisionShape3D { Name = "FirstShape", Shape = new SphereShape3D { Radius = 0.5f } };
        var secondShape = new CollisionShape3D { Name = "SecondShape", Shape = new SphereShape3D { Radius = 0.5f } };
        body.AddChild(firstShape);
        body.AddChild(secondShape);
        var entered = 0;
        var exited = 0;
        area.BodyEntered += other =>
        {
            if (ReferenceEquals(other, body))
            {
                entered++;
            }
        };
        area.BodyExited += other =>
        {
            if (ReferenceEquals(other, body))
            {
                exited++;
            }
        };
        areaWorld.AddChild(area);
        areaWorld.AddChild(body);
        shapeRemovalPhysicsTree.Root.AddChild(areaWorld);
        shapeRemovalPhysicsTree.ProcessFrame(shapeRemovalPhysicsTree.PhysicsDelta);
        body.RemoveChild(firstShape);
        shapeRemovalPhysicsTree.ProcessFrame(shapeRemovalPhysicsTree.PhysicsDelta);
        shapeRemovalPhysicsTree.ProcessFrame(shapeRemovalPhysicsTree.PhysicsDelta);
        Check(
            "Area3D shape removal emits one exit for only the removed collider pair",
            entered == 2 && exited == 1,
            $"entered={entered} exited={exited}");
        body.RemoveChild(secondShape);
        shapeRemovalPhysicsTree.ProcessFrame(shapeRemovalPhysicsTree.PhysicsDelta);
        shapeRemovalPhysicsTree.ProcessFrame(shapeRemovalPhysicsTree.PhysicsDelta);
        Check(
            "Area3D every removed collider pair exits exactly once",
            exited == 2,
            $"exited={exited}");
    }

    using (var characterPhysicsTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "CharacterWorld" };
        var floor = new StaticBody3D { Name = "Floor", Position = new Vector3(0f, -0.5f, 0f) };
        floor.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(16f, 1f, 256f) } });
        var wall = new StaticBody3D { Name = "Wall", Position = new Vector3(2f, 1.5f, 0f) };
        wall.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(1f, 3f, 256f) } });
        var character = new CharacterBody3D { Name = "Player", Position = new Vector3(0f, 1.5f, 0f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.5f, CylinderHeight = 1f },
        });
        characterWorld.AddChild(floor);
        characterWorld.AddChild(wall);
        characterWorld.AddChild(character);
        characterPhysicsTree.Root.AddChild(characterWorld);
        characterPhysicsTree.ProcessFrame(characterPhysicsTree.PhysicsDelta);

        character.Velocity = new Vector3(12f, -20f, 3f);
        character.MoveAndSlide();
        Check("CharacterBody3D queues movement until the next world step", character.LastSlideCount == 0);
        characterPhysicsTree.ProcessFrame(characterPhysicsTree.PhysicsDelta);
        Check(
            "CharacterBody3D classifies floor contact and records its slide",
            character.IsOnFloor && character.GlobalPosition.Y >= 0f && character.LastSlideCount > 0,
            $"floor={character.IsOnFloor} y={character.GlobalPosition.Y} slides={character.LastSlideCount}");

        character.Velocity = Vector3.Zero;
        character.MoveAndSlide();
        characterPhysicsTree.ProcessFrame(characterPhysicsTree.PhysicsDelta);
        Check(
            "CharacterBody3D preserves floor state and clears slides for a zero-velocity move",
            character.IsOnFloor && character.LastSlideCount == 0,
            $"floor={character.IsOnFloor} slides={character.LastSlideCount}");

        for (var tick = 0; tick < 8; tick++)
        {
            character.Velocity = new Vector3(12f, -20f, 3f);
            character.MoveAndSlide();
            characterPhysicsTree.ProcessFrame(characterPhysicsTree.PhysicsDelta);
        }

        var allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        for (var tick = 0; tick < 100; tick++)
        {
            character.Velocity = new Vector3(12f, -20f, 3f);
            character.MoveAndSlide();
            characterPhysicsTree.ProcessFrame(characterPhysicsTree.PhysicsDelta);
        }

        var allocated = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
        Check("CharacterBody3D warm movement loop has no managed allocations", allocated == 0, $"bytes={allocated}");
        CharacterSlideCollision lastSlide = character.GetSlideCollision(character.LastSlideCount - 1);
        Check(
            "CharacterBody3D slides along a wall without penetrating it",
            character.GlobalPosition.X <= 1.001f && character.GlobalPosition.Z > 0.1f &&
            lastSlide.Collider == wall,
            $"position={character.GlobalPosition} collider={lastSlide.Collider.Name}");
    }

    using (var platformEdgePhysicsTree = new SceneTree())
    {
        var platformWorld = new PhysicsWorld3D { Name = "PlatformEdgeWorld", Gravity = new Vector3(0f, -24f, 0f) };
        var platform = new StaticBody3D { Name = "OneBlockPlatform", Position = new Vector3(0f, -0.5f, 0f) };
        platform.AddChild(new CollisionShape3D
        {
            Shape = new BoxShape3D { Size = new Vector3(1f, 1f, 4f) },
        });
        var lowerPlatform = new StaticBody3D { Name = "LowerOneBlockPlatform", Position = new Vector3(16.5f, -1.5f, 0f) };
        lowerPlatform.AddChild(new CollisionShape3D
        {
            Shape = new BoxShape3D { Size = new Vector3(32f, 1f, 4f) },
        });
        var platformCharacter = new CharacterBody3D
        {
            Name = "PlatformEdgePlayer",
            Position = new Vector3(-0.25f, 0.905f, 0f),
            MaxStepHeight = 0.65f,
        };
        platformCharacter.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1.1f },
        });
        platformWorld.AddChild(platform);
        platformWorld.AddChild(lowerPlatform);
        platformWorld.AddChild(platformCharacter);
        platformEdgePhysicsTree.Root.AddChild(platformWorld);
        platformEdgePhysicsTree.ProcessFrame(platformEdgePhysicsTree.PhysicsDelta);

        var edgeTrace = new List<string>();
        for (var tick = 0; tick < 60; tick++)
        {
            var vertical = tick == 0
                ? -1f
                : platformCharacter.IsOnFloor
                    ? 0f
                    : platformCharacter.Velocity.Y - 24f * (float)platformEdgePhysicsTree.PhysicsDelta;
            platformCharacter.Velocity = new Vector3(8f, vertical, 0f);
            platformCharacter.MoveAndSlide();
            platformEdgePhysicsTree.ProcessFrame(platformEdgePhysicsTree.PhysicsDelta);
            var normals = string.Join(';', Enumerable.Range(0, platformCharacter.LastSlideCount)
                .Select(i => platformCharacter.GetSlideCollision(i).Normal.ToString()));
            edgeTrace.Add($"{tick}:pos={platformCharacter.GlobalPosition} vel={platformCharacter.Velocity} floor={platformCharacter.IsOnFloor} slides={platformCharacter.LastSlideCount} normals={normals}");
        }

        Check(
            "角色走下一格落差后应落到低台而不是沿方块边缘缓降",
            platformCharacter.GlobalPosition.X > 1.5f && platformCharacter.GlobalPosition.Y > -0.12f &&
            platformCharacter.GlobalPosition.Y < -0.06f && platformCharacter.IsOnFloor,
            $"position={platformCharacter.GlobalPosition} velocity={platformCharacter.Velocity} floor={platformCharacter.IsOnFloor} " +
            $"slides={platformCharacter.LastSlideCount} trace={string.Join('|', edgeTrace)}");
    }

    using (var cornerPhysicsTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "CornerWorld", Gravity = Vector3.Zero };
        var floor = new StaticBody3D { Name = "CornerFloor", Position = new Vector3(0f, -0.5f, 0f) };
        floor.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(8f, 1f, 8f) } });
        var eastBlock = new StaticBody3D { Name = "EastBlock", Position = new Vector3(1.5f, 0.5f, 0f) };
        eastBlock.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(1f, 1f, 2f) } });
        var northBlock = new StaticBody3D { Name = "NorthBlock", Position = new Vector3(0f, 0.5f, 1.5f) };
        northBlock.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(2f, 1f, 1f) } });
        var character = new CharacterBody3D { Name = "CornerPlayer", Position = new Vector3(0.4f, 1.5f, 1.36f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        characterWorld.AddChild(floor);
        characterWorld.AddChild(eastBlock);
        characterWorld.AddChild(northBlock);
        characterWorld.AddChild(character);
        cornerPhysicsTree.Root.AddChild(characterWorld);
        cornerPhysicsTree.ProcessFrame(cornerPhysicsTree.PhysicsDelta);

        var start = character.GlobalPosition;
        for (var tick = 0; tick < 20; tick++)
        {
            character.Velocity = new Vector3(8f, 0f, 0.35f);
            character.MoveAndSlide();
            cornerPhysicsTree.ProcessFrame(cornerPhysicsTree.PhysicsDelta);
        }

        Check(
            "胶囊擦过两个方块公共棱角仍能连续前进",
            character.GlobalPosition.X - start.X > 0.5f,
            $"start={start} end={character.GlobalPosition} slides={character.LastSlideCount}");
    }

    // 一格空位边缘：角色不应被相邻方块的圆角接触托住并缓降，
    // 而应完整越过空位后落到下一块低一格的地面。
    using (var oneBlockGapPhysicsTree = new SceneTree())
    {
        var gapWorld = new PhysicsWorld3D { Name = "OneBlockGapWorld", Gravity = new Vector3(0f, -24f, 0f) };
        var highPlatform = new StaticBody3D { Name = "GapHighPlatform", Position = new Vector3(-3.5f, -0.5f, 0f) };
        highPlatform.AddChild(new CollisionShape3D
        {
            Shape = new BoxShape3D { Size = new Vector3(6f, 1f, 4f) },
        });
        var lowPlatform = new StaticBody3D { Name = "GapLowPlatform", Position = new Vector3(2.5f, -1.5f, 0f) };
        lowPlatform.AddChild(new CollisionShape3D
        {
            Shape = new BoxShape3D { Size = new Vector3(3f, 1f, 4f) },
        });
        var gapCharacter = new CharacterBody3D
        {
            Name = "OneBlockGapPlayer",
            Position = new Vector3(-0.25f, 0.905f, 0f),
            MaxStepHeight = 0.65f,
        };
        gapCharacter.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1.1f },
        });
        gapWorld.AddChild(highPlatform);
        gapWorld.AddChild(lowPlatform);
        gapWorld.AddChild(gapCharacter);
        oneBlockGapPhysicsTree.Root.AddChild(gapWorld);
        oneBlockGapPhysicsTree.ProcessFrame(oneBlockGapPhysicsTree.PhysicsDelta);

        var gapTrace = new List<string>();
        var lowestGapY = gapCharacter.GlobalPosition.Y;
        var firstGapGravityTick = -1;
        for (var tick = 0; tick < 13; tick++)
        {
            var vertical = gapCharacter.IsOnFloor
                ? 0f
                : gapCharacter.Velocity.Y - 24f * (float)oneBlockGapPhysicsTree.PhysicsDelta;
            gapCharacter.Velocity = new Vector3(8f, vertical, 0f);
            gapCharacter.MoveAndSlide();
            oneBlockGapPhysicsTree.ProcessFrame(oneBlockGapPhysicsTree.PhysicsDelta);
            if (!gapCharacter.IsOnFloor && gapCharacter.Velocity.Y < -1e-4f && firstGapGravityTick < 0)
            {
                firstGapGravityTick = tick;
            }

            lowestGapY = MathF.Min(lowestGapY, gapCharacter.GlobalPosition.Y);
            var normals = string.Join(';', Enumerable.Range(0, gapCharacter.LastSlideCount)
                .Select(i => gapCharacter.GetSlideCollision(i).Normal.ToString()));
            gapTrace.Add($"{tick}:pos={gapCharacter.GlobalPosition} vel={gapCharacter.Velocity} floor={gapCharacter.IsOnFloor} slides={gapCharacter.LastSlideCount} normals={normals}");
        }

        Check(
            "角色离开低台边缘后不应被圆角接触重新判定为地面",
            firstGapGravityTick >= 0 && gapCharacter.GlobalPosition.X > 4.5f &&
            gapCharacter.GlobalPosition.Y < -0.12f && gapCharacter.Velocity.Y < -0.5f &&
            !gapCharacter.IsOnFloor && lowestGapY < -0.12f,
            $"position={gapCharacter.GlobalPosition} velocity={gapCharacter.Velocity} floor={gapCharacter.IsOnFloor} " +
            $"firstGravityTick={firstGapGravityTick} lowestY={lowestGapY:F3} trace={string.Join('|', gapTrace)}");
    }

    // 方块外棱回归：离开顶面后，纯竖直下落不能被胶囊圆角的斜法线
    // 截断成一次极小的缓降，否则表现为角色悬空/落地状态来回切换。
    using (var edgeDescentPhysicsTree = new SceneTree())
    {
        var edgeWorld = new PhysicsWorld3D { Name = "EdgeDescentWorld", Gravity = new Vector3(0f, -24f, 0f) };
        var edgePlatform = new StaticBody3D { Name = "EdgePlatform", Position = new Vector3(0f, -0.5f, 0f) };
        edgePlatform.AddChild(new CollisionShape3D
        {
            Shape = new BoxShape3D { Size = new Vector3(2f, 1f, 4f) },
        });
        var edgeCharacter = new CharacterBody3D
        {
            Name = "EdgeDescentPlayer",
            Position = new Vector3(0.65f, 0.905f, 0f),
            MaxStepHeight = 0.65f,
        };
        edgeCharacter.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1.1f },
        });
        edgeWorld.AddChild(edgePlatform);
        edgeWorld.AddChild(edgeCharacter);
        edgeDescentPhysicsTree.Root.AddChild(edgeWorld);
        edgeDescentPhysicsTree.ProcessFrame(edgeDescentPhysicsTree.PhysicsDelta);

        edgeCharacter.Velocity = new Vector3(8f, 0f, 0f);
        edgeCharacter.MoveAndSlide();
        edgeDescentPhysicsTree.ProcessFrame(edgeDescentPhysicsTree.PhysicsDelta);
        var edgeYBeforeDescent = edgeCharacter.GlobalPosition.Y;

        edgeCharacter.Velocity = new Vector3(8f, -1.2f, 0f);
        edgeCharacter.MoveAndSlide();
        edgeDescentPhysicsTree.ProcessFrame(edgeDescentPhysicsTree.PhysicsDelta);
        var edgeYAfterDescent = edgeCharacter.GlobalPosition.Y;
        var edgeDeltaY = edgeYAfterDescent - edgeYBeforeDescent;

        Check(
            "离开方块顶面时不会被胶囊外棱碰撞造成缓降",
            edgeDeltaY >= -0.0001f,
            $"before={edgeYBeforeDescent:F6} after={edgeYAfterDescent:F6} deltaY={edgeDeltaY:F6} " +
            $"position={edgeCharacter.GlobalPosition} velocity={edgeCharacter.Velocity} floor={edgeCharacter.IsOnFloor} " +
            $"normals={string.Join(';', Enumerable.Range(0, edgeCharacter.LastSlideCount).Select(i => edgeCharacter.GetSlideCollision(i).Normal.ToString()))}");
    }

    using (var airborneStepTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "AirborneStepWorld", Gravity = Vector3.Zero };
        var block = new StaticBody3D { Name = "AirborneStepBlock", Position = new Vector3(1.5f, 0.5f, 0f) };
        block.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(1f, 1f, 2f) } });
        var character = new CharacterBody3D
        {
            Name = "AirborneStepPlayer",
