            MaxStepHeight = 0.65f,
        };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1.1f },
        });
        characterWorld.AddChild(block);
        characterWorld.AddChild(character);
        airborneStepTree.Root.AddChild(characterWorld);
        airborneStepTree.ProcessFrame(airborneStepTree.PhysicsDelta);

        var startY = character.GlobalPosition.Y;
        for (var tick = 0; tick < 4; tick++)
        {
            character.Velocity = new Vector3(8f, -2f, 0f);
            character.MoveAndSlide();
            airborneStepTree.ProcessFrame(airborneStepTree.PhysicsDelta);
        }

        Check(
            "空中下落时撞到一格方块不能自动跨步",
            character.GlobalPosition.X < 0.8f && character.GlobalPosition.Y < startY && !character.IsOnFloor,
            $"startY={startY} end={character.GlobalPosition} velocity={character.Velocity} floor={character.IsOnFloor} slides={character.LastSlideCount}");
    }

    using (var diagonalCornerPhysicsTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "DiagonalCornerWorld", Gravity = Vector3.Zero };
        var northBlock = new StaticBody3D { Name = "NorthBlock", Position = new Vector3(0f, 0.5f, 1.5f) };
        northBlock.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(2f, 1f, 1f) } });
        var character = new CharacterBody3D { Name = "DiagonalCornerPlayer", Position = new Vector3(0.4f, 1.5f, 1.34f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        characterWorld.AddChild(northBlock);
        characterWorld.AddChild(character);
        diagonalCornerPhysicsTree.Root.AddChild(characterWorld);
        diagonalCornerPhysicsTree.ProcessFrame(diagonalCornerPhysicsTree.PhysicsDelta);

        var start = character.GlobalPosition;
        character.Velocity = new Vector3(8f, 0f, 8f);
        character.MoveAndSlide();
        diagonalCornerPhysicsTree.ProcessFrame(diagonalCornerPhysicsTree.PhysicsDelta);

        Check(
            "胶囊从方块棱角向外斜走不吞掉水平轴",
            character.GlobalPosition.X - start.X > 0.2f && character.GlobalPosition.Z - start.Z > 0.2f,
            $"start={start} end={character.GlobalPosition} slides={character.LastSlideCount} " +
            $"normals={string.Join(';', Enumerable.Range(0, character.LastSlideCount).Select(i => character.GetSlideCollision(i).Normal.ToString()))}");
    }

    using (var axisCornerPhysicsTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "AxisCornerWorld", Gravity = Vector3.Zero };
        var cornerBlock = new StaticBody3D { Name = "CornerBlock", Position = new Vector3(0.5f, 0.5f, 0.5f) };
        cornerBlock.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = Vector3.One } });
        var character = new CharacterBody3D { Name = "AxisCornerPlayer", Position = new Vector3(-0.6f, 1.5f, -0.2f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        characterWorld.AddChild(cornerBlock);
        characterWorld.AddChild(character);
        axisCornerPhysicsTree.Root.AddChild(characterWorld);
        axisCornerPhysicsTree.ProcessFrame(axisCornerPhysicsTree.PhysicsDelta);

        var start = character.GlobalPosition;
        character.Velocity = new Vector3(8f, 0f, 0f);
        character.MoveAndSlide();
        axisCornerPhysicsTree.ProcessFrame(axisCornerPhysicsTree.PhysicsDelta);

        Check(
            "单轴扫掠遇圆角不生成垂直水平位移",
            MathF.Abs(character.GlobalPosition.Z - start.Z) <= 1e-5f,
            $"start={start} end={character.GlobalPosition} slides={character.LastSlideCount} " +
            $"normals={string.Join(';', Enumerable.Range(0, character.LastSlideCount).Select(i => character.GetSlideCollision(i).Normal.ToString()))}");
    }

    using (var closeCornerEscapeTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "CloseCornerEscapeWorld", Gravity = Vector3.Zero };
        var eastBlock = new StaticBody3D { Name = "EastBlock", Position = new Vector3(1.5f, 0.5f, 0f) };
        eastBlock.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(1f, 1f, 2f) } });
        var northBlock = new StaticBody3D { Name = "NorthBlock", Position = new Vector3(0f, 0.5f, 1.5f) };
        northBlock.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(2f, 1f, 1f) } });
        var character = new CharacterBody3D { Name = "CloseCornerPlayer", Position = new Vector3(0.64f, 1.5f, 1.36f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        characterWorld.AddChild(eastBlock);
        characterWorld.AddChild(northBlock);
        characterWorld.AddChild(character);
        closeCornerEscapeTree.Root.AddChild(characterWorld);
        closeCornerEscapeTree.ProcessFrame(closeCornerEscapeTree.PhysicsDelta);

        var start = character.GlobalPosition;
        for (var tick = 0; tick < 4; tick++)
        {
            character.Velocity = new Vector3(-8f, 0f, -8f);
            character.MoveAndSlide();
            closeCornerEscapeTree.ProcessFrame(closeCornerEscapeTree.PhysicsDelta);
        }

        Check(
            "贴近两个方块公共棱角向外移动不会被水平恢复锁死",
            start.X - character.GlobalPosition.X > 0.2f && start.Z - character.GlobalPosition.Z > 0.2f,
            $"start={start} end={character.GlobalPosition} slides={character.LastSlideCount} " +
            $"normals={string.Join(';', Enumerable.Range(0, character.LastSlideCount).Select(i => character.GetSlideCollision(i).Normal.ToString()))}");
    }

    using (var closeCornerAxisTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "CloseCornerAxisWorld", Gravity = Vector3.Zero };
        var eastBlock = new StaticBody3D { Name = "EastBlock", Position = new Vector3(1.5f, 0.5f, 0f) };
        eastBlock.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(1f, 1f, 2f) } });
        var northBlock = new StaticBody3D { Name = "NorthBlock", Position = new Vector3(0f, 0.5f, 1.5f) };
        northBlock.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(2f, 1f, 1f) } });
        var character = new CharacterBody3D { Name = "CloseCornerAxisPlayer", Position = new Vector3(0.66f, 1.5f, 1.34f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        characterWorld.AddChild(eastBlock);
        characterWorld.AddChild(northBlock);
        characterWorld.AddChild(character);
        closeCornerAxisTree.Root.AddChild(characterWorld);
        closeCornerAxisTree.ProcessFrame(closeCornerAxisTree.PhysicsDelta);

        var start = character.GlobalPosition;
        for (var tick = 0; tick < 4; tick++)
        {
            character.Velocity = new Vector3(-8f, 0f, 0f);
            character.MoveAndSlide();
            closeCornerAxisTree.ProcessFrame(closeCornerAxisTree.PhysicsDelta);
        }

        Check(
            "贴近两个方块公共棱角沿单轴向外移动不会被另一接触锁死",
            start.X - character.GlobalPosition.X > 0.2f,
            $"start={start} end={character.GlobalPosition} slides={character.LastSlideCount} " +
            $"normals={string.Join(';', Enumerable.Range(0, character.LastSlideCount).Select(i => character.GetSlideCollision(i).Normal.ToString()))}");
    }

    using (var narrowCorridorTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "NarrowCorridorWorld", Gravity = Vector3.Zero };
        var westWall = new StaticBody3D { Name = "WestWall", Position = new Vector3(-0.62f, 1.5f, 1f) };
        westWall.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(0.5f, 3f, 2f) } });
        var eastWall = new StaticBody3D { Name = "EastWall", Position = new Vector3(0.62f, 1.5f, 1f) };
        eastWall.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(0.5f, 3f, 2f) } });
        var character = new CharacterBody3D { Name = "NarrowCorridorPlayer", Position = new Vector3(0.02f, 1.5f, -0.25f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        characterWorld.AddChild(westWall);
        characterWorld.AddChild(eastWall);
        characterWorld.AddChild(character);
        narrowCorridorTree.Root.AddChild(characterWorld);
        narrowCorridorTree.ProcessFrame(narrowCorridorTree.PhysicsDelta);

        var start = character.GlobalPosition;
        for (var tick = 0; tick < 8; tick++)
        {
            character.Velocity = new Vector3(0f, 0f, 8f);
            character.MoveAndSlide();
            narrowCorridorTree.ProcessFrame(narrowCorridorTree.PhysicsDelta);
        }

        Check(
            "略宽于胶囊直径的两方块通道不会在墙端棱角卡死",
            character.GlobalPosition.Z - start.Z > 1f,
            $"start={start} end={character.GlobalPosition} slides={character.LastSlideCount} " +
            $"normals={string.Join(';', Enumerable.Range(0, character.LastSlideCount).Select(i => character.GetSlideCollision(i).Normal.ToString()))}");
    }

    // 跨步只用于消除胶囊擦过低台阶上棱时的零分数循环，绝不能将角色
    // 抬入低顶棚。此处刻意同时施加跳跃和水平速度，覆盖正式项目的分轴路径。
    using (var lowCeilingStepTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "LowCeilingStepWorld", Gravity = Vector3.Zero };
        var floor = new StaticBody3D { Name = "Floor", Position = new Vector3(0f, -0.5f, 0f) };
        floor.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(16f, 1f, 4f) } });
        var step = new StaticBody3D { Name = "OneBlockStep", Position = new Vector3(1.5f, 0.5f, 0f) };
        step.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(1f, 1f, 2f) } });
        var ceiling = new StaticBody3D { Name = "LowCeiling", Position = new Vector3(1.5f, 3.1f, 0f) };
        var ceilingShape = new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(3f, 0.3f, 2f) } };
        ceiling.AddChild(ceilingShape);
        var character = new CharacterBody3D
        {
            Name = "LowCeilingPlayer",
            Position = new Vector3(0f, 1.5f, 0f),
            MaxStepHeight = 0.65f,
        };
        var characterShape = new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.5f, CylinderHeight = 1f },
        };
        character.AddChild(characterShape);
        characterWorld.AddChild(floor);
        characterWorld.AddChild(step);
        characterWorld.AddChild(ceiling);
        characterWorld.AddChild(character);
        lowCeilingStepTree.Root.AddChild(characterWorld);
        lowCeilingStepTree.ProcessFrame(lowCeilingStepTree.PhysicsDelta);

        for (var tick = 0; tick < 8; tick++)
        {
            character.Velocity = new Vector3(8f, 8f, 0f);
            character.MoveAndSlide();
            lowCeilingStepTree.ProcessFrame(lowCeilingStepTree.PhysicsDelta);
        }

        var overlaps = new List<PhysicsOverlapHit3D>();
        characterWorld.Overlap(
            characterShape.Shape ?? throw new InvalidOperationException("低顶棚角色缺少碰撞形状"),
            characterShape.GlobalTransform,
            new PhysicsQueryFilter(exclude: character),
            overlaps);
        var hasCeilingContact = ShapeGeometry.TryGetContact(
            characterShape.Shape ?? throw new InvalidOperationException("低顶棚角色缺少碰撞形状"),
            characterShape.GlobalTransform,
            ceilingShape.Shape ?? throw new InvalidOperationException("低顶棚缺少碰撞形状"),
            ceilingShape.GlobalTransform,
            out var ceilingContact);
        Check(
            "CharacterBody3D 跨步不会穿过低顶棚或越过受阻台阶",
            character.GlobalPosition.X < 1f && character.GlobalPosition.Y <= 1.96f &&
            overlaps.Count == 0 && !hasCeilingContact,
            $"position={character.GlobalPosition} overlaps={string.Join(',', overlaps.Select(hit => hit.Collider.Name))} " +
            $"ceilingContact={hasCeilingContact}:{ceilingContact.Penetration:F6} slides={character.LastSlideCount}");
    }

    using (var automaticStepTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "AutomaticStepWorld", Gravity = Vector3.Zero };
        var floor = new StaticBody3D { Name = "AutomaticStepFloor", Position = new Vector3(0f, -0.5f, 0f) };
        floor.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(16f, 1f, 4f) } });
        var step = new StaticBody3D { Name = "AutomaticStep", Position = new Vector3(1.5f, 0.25f, 0f) };
        step.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(1f, 0.5f, 2f) } });
        var character = new CharacterBody3D
        {
            Name = "AutomaticStepPlayer",
            Position = new Vector3(0f, 1f, 0f),
            MaxStepHeight = 0.65f,
        };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.5f, CylinderHeight = 1f },
        });
        characterWorld.AddChild(floor);
        characterWorld.AddChild(step);
        characterWorld.AddChild(character);
        automaticStepTree.Root.AddChild(characterWorld);
        automaticStepTree.ProcessFrame(automaticStepTree.PhysicsDelta);

        var start = character.GlobalPosition;
        for (var tick = 0; tick < 8; tick++)
        {
            character.Velocity = new Vector3(8f, 0f, 0f);
            character.MoveAndSlide();
            automaticStepTree.ProcessFrame(automaticStepTree.PhysicsDelta);
        }

        Check(
            "纯水平输入自动跨过一格方块",
            character.GlobalPosition.X > 2f && character.GlobalPosition.Y > start.Y + 0.2f,
            $"start={start} end={character.GlobalPosition} floor={character.IsOnFloor} slides={character.LastSlideCount}");
    }

    // 体素地形碰撞按 Y 层生成相邻盒体。高墙不能触发跨步，角色应沿
    // 墙面滑到墙端，再从墙端继续前进；层间接缝不得把切向位移锁死。
    using (var stackedWallSlideTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "StackedWallSlideWorld", Gravity = Vector3.Zero };
        for (var layer = 0; layer < 3; layer++)
        {
            var wallLayer = new StaticBody3D
            {
                Name = $"WallLayer{layer}",
                Position = new Vector3(1.5f, 0.5f + layer, 1.5f),
            };
            wallLayer.AddChild(new CollisionShape3D
            {
                Shape = new BoxShape3D { Size = new Vector3(1f, 1f, 4f) },
            });
            characterWorld.AddChild(wallLayer);
        }

        var character = new CharacterBody3D
        {
            Name = "StackedWallSlidePlayer",
            Position = new Vector3(0f, 1.5f, -2f),
            MaxStepHeight = 0.65f,
        };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        characterWorld.AddChild(character);
        stackedWallSlideTree.Root.AddChild(characterWorld);
        stackedWallSlideTree.ProcessFrame(stackedWallSlideTree.PhysicsDelta);

        var start = character.GlobalPosition;
        var maxXBeforeWallEnd = float.MinValue;
        var stackedWallTrace = new List<string>();
        for (var tick = 0; tick < 20; tick++)
        {
            character.Velocity = new Vector3(8f, 0f, 8f);
            character.MoveAndSlide();
            stackedWallSlideTree.ProcessFrame(stackedWallSlideTree.PhysicsDelta);
            stackedWallTrace.Add($"{tick}:{character.GlobalPosition} s={character.LastSlideCount}");
            if (character.GlobalPosition.Z <= 3.8f)
            {
                maxXBeforeWallEnd = MathF.Max(maxXBeforeWallEnd, character.GlobalPosition.X);
            }
        }

        Check(
            "多层体素墙边缘沿墙滑动并从墙端脱离",
            character.GlobalPosition.Z > 3.8f && character.GlobalPosition.X > 1.4f &&
            maxXBeforeWallEnd > 1.0f && character.GlobalPosition.Y < 1.95f,
            $"start={start} end={character.GlobalPosition} slides={character.LastSlideCount} " +
            $"maxXBeforeWallEnd={maxXBeforeWallEnd:F3} " +
            $"trace={string.Join('|', stackedWallTrace)} " +
            $"normals={string.Join(';', Enumerable.Range(0, character.LastSlideCount).Select(i => character.GetSlideCollision(i).Normal.ToString()))}");
    }

    using (var stackedWallApproachTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "StackedWallApproachWorld", Gravity = Vector3.Zero };
        var floor = new StaticBody3D { Name = "StackedWallFloor", Position = new Vector3(0f, -0.5f, 1.5f) };
        floor.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(8f, 1f, 6f) } });
        characterWorld.AddChild(floor);
        for (var layer = 0; layer < 3; layer++)
        {
            var wallLayer = new StaticBody3D
            {
                Name = $"ApproachWallLayer{layer}",
                Position = new Vector3(1.5f, 0.5f + layer, 1.5f),
            };
            wallLayer.AddChild(new CollisionShape3D
            {
                Shape = new BoxShape3D { Size = new Vector3(1f, 1f, 4f) },
            });
            characterWorld.AddChild(wallLayer);
        }

        var character = new CharacterBody3D
        {
            Name = "StackedWallApproachPlayer",
            Position = new Vector3(0f, 1.5f, 1.5f),
            MaxStepHeight = 0.65f,
        };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f },
        });
        characterWorld.AddChild(character);
        stackedWallApproachTree.Root.AddChild(characterWorld);
        stackedWallApproachTree.ProcessFrame(stackedWallApproachTree.PhysicsDelta);

        for (var tick = 0; tick < 12; tick++)
        {
            character.Velocity = new Vector3(8f, 0f, 0f);
            character.MoveAndSlide();
            stackedWallApproachTree.ProcessFrame(stackedWallApproachTree.PhysicsDelta);
        }

        Check(
            "多层体素墙正面不能逐层自动跨上去",
            character.GlobalPosition.X <= 0.7f && character.GlobalPosition.Y < 1.95f,
            $"position={character.GlobalPosition} slides={character.LastSlideCount} " +
            $"normals={string.Join(';', Enumerable.Range(0, character.LastSlideCount).Select(i => character.GetSlideCollision(i).Normal.ToString()))}");
    }

    using (var highSpeedCharacterTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "HighSpeedCharacterWorld" };
        var thinWall = new StaticBody3D { Name = "ThinWall", Position = new Vector3(100.2f, 0f, 0f) };
        thinWall.AddChild(new CollisionShape3D
        {
            Shape = new BoxShape3D { Size = new Vector3(0.01f, 2f, 2f) },
        });
        var character = new CharacterBody3D { Name = "HighSpeedPlayer" };
        character.AddChild(new CollisionShape3D
        {
            Shape = new SphereShape3D { Radius = 0.05f },
        });
        characterWorld.AddChild(thinWall);
        characterWorld.AddChild(character);
        highSpeedCharacterTree.Root.AddChild(characterWorld);
        highSpeedCharacterTree.ProcessFrame(highSpeedCharacterTree.PhysicsDelta);

        character.Velocity = new Vector3(float.MaxValue, 0f, 0f);
        character.MoveAndSlide();
        highSpeedCharacterTree.ProcessFrame(highSpeedCharacterTree.PhysicsDelta);
        var limitDiagnostic = characterWorld.Diagnostics.Snapshot().Any(diagnostic =>
            diagnostic.Code == "physics.character.motion-limit");
        Check(
            "CharacterBody3D rejects unsafe high-speed motion before a thin obstacle",
            character.GlobalPosition == Vector3.Zero && character.LastSlideCount == 0 && limitDiagnostic,
            $"position={character.GlobalPosition} slides={character.LastSlideCount} diagnostic={limitDiagnostic}");
    }

    using (var overflowingPositionCharacterTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "OverflowingPositionCharacterWorld" };
        var character = new CharacterBody3D { Name = "OverflowingPositionPlayer" };
        character.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        characterWorld.AddChild(character);
        overflowingPositionCharacterTree.Root.AddChild(characterWorld);
        overflowingPositionCharacterTree.ProcessFrame(overflowingPositionCharacterTree.PhysicsDelta);

        character.Position = new Vector3(float.MaxValue, 0f, 0f);
        character.Velocity = new Vector3(float.MaxValue, 0f, 0f);
        character.MoveAndSlide();
        var motionError = CaptureException(() =>
            overflowingPositionCharacterTree.ProcessFrame(overflowingPositionCharacterTree.PhysicsDelta));
        var motionLimitDiagnostic = characterWorld.Diagnostics.Snapshot().Any(diagnostic =>
            diagnostic.Code == "physics.character.motion-limit");
        Check(
            "CharacterBody3D rejects finite position and velocity overflow before constructing a transform",
            motionError is null && character.GlobalPosition.X == float.MaxValue &&
            character.LastSlideCount == 0 && motionLimitDiagnostic,
            $"error={motionError?.GetType().Name ?? "none"} position={character.GlobalPosition} diagnostic={motionLimitDiagnostic}");
    }

    using (var grazingCharacterTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "GrazingCharacterWorld" };
        var grazingObstacle = new StaticBody3D { Name = "GrazingObstacle", Position = new Vector3(0.1f, 0.999f, 0f) };
        grazingObstacle.AddChild(new CollisionShape3D
        {
            Shape = new SphereShape3D { Radius = 0.5f },
        });
        var character = new CharacterBody3D { Name = "GrazingPlayer", Position = new Vector3(-1f, 0f, 0f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new SphereShape3D { Radius = 0.5f },
        });
        characterWorld.AddChild(grazingObstacle);
        characterWorld.AddChild(character);
        grazingCharacterTree.Root.AddChild(characterWorld);
        grazingCharacterTree.ProcessFrame(grazingCharacterTree.PhysicsDelta);

        character.Velocity = new Vector3(40f, 0f, 0f);
        character.MoveAndSlide();
        grazingCharacterTree.ProcessFrame(grazingCharacterTree.PhysicsDelta);
        var ambiguousDiagnostic = characterWorld.Diagnostics.Snapshot().Any(diagnostic =>
            diagnostic.Code == "physics.character.ambiguous-sweep");
        Check(
            "CharacterBody3D rejects an unresolved within-budget grazing sweep",
            character.GlobalPosition == new Vector3(-1f, 0f, 0f) && character.LastSlideCount == 0 && ambiguousDiagnostic,
            $"position={character.GlobalPosition} slides={character.LastSlideCount} diagnostic={ambiguousDiagnostic}");
    }

    using (var sameStepCharacterTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "SameStepCharacterWorld" };
        var first = new CharacterBody3D { Name = "FirstMover", Position = new Vector3(-10f, 0f, 0f) };
        first.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        var second = new CharacterBody3D { Name = "SecondMover", Position = new Vector3(1f, 0f, 0f) };
        second.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        characterWorld.AddChild(first);
        characterWorld.AddChild(second);
        sameStepCharacterTree.Root.AddChild(characterWorld);
        sameStepCharacterTree.ProcessFrame(sameStepCharacterTree.PhysicsDelta);

        first.Velocity = new Vector3(200f, 0f, 0f);
        second.Velocity = new Vector3(-40f, 0f, 0f);
        first.MoveAndSlide();
        second.MoveAndSlide();
        sameStepCharacterTree.ProcessFrame(sameStepCharacterTree.PhysicsDelta);
        Check(
            "CharacterBody3D refreshes moved dynamic proxies within one fixed step",
            second.LastSlideCount == 1 && second.GlobalPosition.X > 0f &&
            ReferenceEquals(second.GetSlideCollision(0).Collider, first),
            $"position={second.GlobalPosition} slides={second.LastSlideCount}");
    }

    using (var penetratingCharacterTree = new SceneTree())
    {
        var characterWorld = new PhysicsWorld3D { Name = "PenetrationRecoveryWorld", Gravity = Vector3.Zero };
        var wall = new StaticBody3D { Name = "RecoveryWall", Position = new Vector3(2f, 1.5f, 0f) };
        wall.AddChild(new CollisionShape3D
        {
            Shape = new BoxShape3D { Size = new Vector3(1f, 3f, 4f) },
        });
        var character = new CharacterBody3D { Name = "EmbeddedPlayer", Position = new Vector3(2.2f, 1.5f, 0f) };
        character.AddChild(new CollisionShape3D
        {
            Shape = new CapsuleShape3D { Radius = 0.5f, CylinderHeight = 1f },
        });
        characterWorld.AddChild(wall);
        characterWorld.AddChild(character);
        penetratingCharacterTree.Root.AddChild(characterWorld);
        penetratingCharacterTree.ProcessFrame(penetratingCharacterTree.PhysicsDelta);

        character.Velocity = new Vector3(8f, 0f, 0f);
        character.MoveAndSlide();
        penetratingCharacterTree.ProcessFrame(penetratingCharacterTree.PhysicsDelta);
        var overlaps = new List<PhysicsOverlapHit3D>();
        var shape = character.Children.OfType<CollisionShape3D>().Single().Shape
            ?? throw new InvalidOperationException("嵌入角色缺少碰撞形状");
        characterWorld.Overlap(
            shape,
            character.Children.OfType<CollisionShape3D>().Single().GlobalTransform,
            new PhysicsQueryFilter(exclude: character),
            overlaps);
        Check(
            "CharacterBody3D 从初始嵌入状态恢复而不保留穿模",
            overlaps.Count == 0,
            $"position={character.GlobalPosition} overlaps={overlaps.Count}");
    }

    using (var rigidBodyPhysicsTree = new SceneTree())
    {
        var rigidWorld = new PhysicsWorld3D { Name = "RigidBodyWorld", Gravity = new Vector3(0f, -10f, 0f) };
        var body = new RigidBody3D { Name = "ImpulseBody", Mass = 2f, Position = new Vector3(0f, 3f, 0f) };
        body.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        rigidWorld.AddChild(body);
        rigidBodyPhysicsTree.Root.AddChild(rigidWorld);
        rigidBodyPhysicsTree.ProcessFrame(rigidBodyPhysicsTree.PhysicsDelta);

        var velocityBeforeImpulse = body.LinearVelocity;
        body.ApplyCentralImpulse(new Vector3(4f, 0f, 0f));
        Check("RigidBody3D queues impulses before the next fixed step", body.LinearVelocity == velocityBeforeImpulse);
        rigidBodyPhysicsTree.ProcessFrame(rigidBodyPhysicsTree.PhysicsDelta);
        Check(
            "RigidBody3D applies impulse by inverse mass and gravity",
            MathF.Abs(body.LinearVelocity.X - 2f) < 0.0001f && body.LinearVelocity.Y < velocityBeforeImpulse.Y && !body.IsSleeping,
            $"velocity={body.LinearVelocity} sleeping={body.IsSleeping}");
        var velocityBeforeForce = body.LinearVelocity;
        body.ApplyCentralForce(new Vector3(4f, 0f, 0f));
        Check("RigidBody3D queues forces before the next fixed step", body.LinearVelocity == velocityBeforeForce);
        rigidBodyPhysicsTree.ProcessFrame(rigidBodyPhysicsTree.PhysicsDelta);
        Check(
            "RigidBody3D applies force by inverse mass on the next fixed step",
            MathF.Abs(body.LinearVelocity.X - 2.1f) < 0.0001f,
            $"velocity={body.LinearVelocity}");
        Check(
            "RigidBody3D solver contract types exist",
            typeof(PhysicsContact) is not null && typeof(PhysicsSolver) is not null);
    }

    using (var rigidContactPhysicsTree = new SceneTree())
    {
        var rigidWorld = new PhysicsWorld3D { Name = "RigidContactWorld", Gravity = Vector3.Zero };
        var floor = new StaticBody3D { Name = "RigidFloor", Position = new Vector3(0f, -0.5f, 0f) };
        floor.PhysicsMaterial = new PhysicsMaterial3D { Friction = 0.25f, Restitution = 0.8f };
        floor.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(8f, 1f, 8f) } });
        var body = new RigidBody3D { Name = "MaterialBody", Position = new Vector3(0f, 0.75f, 0f) };
        body.PhysicsMaterial = new PhysicsMaterial3D { Friction = 1f, Restitution = 0.2f };
        body.LinearVelocity = new Vector3(20f, -10f, 0f);
        body.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        rigidWorld.AddChild(floor);
        rigidWorld.AddChild(body);
        rigidContactPhysicsTree.Root.AddChild(rigidWorld);
        for (var tick = 0; tick < 3; tick++)
        {
            rigidContactPhysicsTree.ProcessFrame(rigidContactPhysicsTree.PhysicsDelta);
        }

        Check(
            "RigidBody3D combines restitution and friction on exact contacts",
            MathF.Abs(body.LinearVelocity.Y - 8f) < 0.001f && MathF.Abs(body.LinearVelocity.X - 11f) < 0.001f,
            $"velocity={body.LinearVelocity}");
        Check("RigidBody3D contact solving never moves a static body", floor.GlobalPosition == new Vector3(0f, -0.5f, 0f));

        var sleeper = new RigidBody3D { Name = "Sleeper", Position = new Vector3(2f, 0.49f, 0f) };
        sleeper.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        rigidWorld.AddChild(sleeper);
        for (var tick = 0; tick < 64; tick++)
        {
            rigidContactPhysicsTree.ProcessFrame(rigidContactPhysicsTree.PhysicsDelta);
        }

        Check("RigidBody3D sleeps after stable resting contacts", sleeper.IsSleeping);
        sleeper.ApplyCentralImpulse(Vector3.UnitX);
        rigidContactPhysicsTree.ProcessFrame(rigidContactPhysicsTree.PhysicsDelta);
        Check("RigidBody3D wakes after a queued impulse", !sleeper.IsSleeping && sleeper.LinearVelocity.X > 0f);
    }

    using (var deepPenetrationPhysicsTree = new SceneTree())
    {
        var rigidWorld = new PhysicsWorld3D { Name = "DeepPenetrationWorld", Gravity = Vector3.Zero };
        var floor = new StaticBody3D { Name = "DeepPenetrationFloor", Position = new Vector3(0f, -0.5f, 0f) };
        floor.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(8f, 1f, 8f) } });
        var body = new RigidBody3D { Name = "DeepPenetrationBody", Position = Vector3.Zero };
        body.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 100f } });
        rigidWorld.AddChild(floor);
        rigidWorld.AddChild(body);
        deepPenetrationPhysicsTree.Root.AddChild(rigidWorld);
        for (var tick = 0; tick < 31; tick++)
        {
            deepPenetrationPhysicsTree.ProcessFrame(deepPenetrationPhysicsTree.PhysicsDelta);
        }

        Check(
            "RigidBody3D does not sleep while deep contact still needs positional correction",
            !body.IsSleeping,
            $"position={body.GlobalPosition} sleeping={body.IsSleeping}");
    }

    {
        var firstBox = new BoxShape3D { Size = new Vector3(2f, 0.8f, 1.2f) };
        var secondBox = new BoxShape3D { Size = new Vector3(1.8f, 1.1f, 1.4f) };
        var firstTransform = new Transform3D(
            new Vector3(0.65f, 0.1f, 0.2f),
            Quaternion.CreateFromYawPitchRoll(0.75f, 0.3f, -0.15f),
            1f);
        var secondTransform = new Transform3D(
            Vector3.Zero,
            Quaternion.CreateFromYawPitchRoll(-0.4f, -0.2f, 0.35f),
            1f);
        var hasContact = ShapeGeometry.TryGetContact(
            firstBox,
            firstTransform,
            secondBox,
            secondTransform,
            out var contact);
        var resolvedTransform = hasContact
            ? firstTransform.WithPosition(firstTransform.Position + contact.Normal * (contact.Penetration + 0.002f))
            : firstTransform;
        Check(
            "ShapeGeometry resolves a rotated Box contact with its normal and penetration",
            hasContact && contact.FeatureId != 0 &&
            !ShapeGeometry.Overlaps(firstBox, resolvedTransform, secondBox, secondTransform),
            $"hasContact={hasContact} normal={contact.Normal} penetration={contact.Penetration} feature={contact.FeatureId}");
    }

    {
        var sphere = new SphereShape3D { Radius = 0.5f };
        var capsule = new CapsuleShape3D { Radius = 0.5f, CylinderHeight = 1f };
        var sphereTransform = new Transform3D(new Vector3(0.65f, 0.6f, 0.1f), Quaternion.Identity, 1f);
        var capsuleTransform = new Transform3D(
            Vector3.Zero,
            Quaternion.CreateFromAxisAngle(Vector3.UnitZ, 0.45f),
            1f);
        var hasContact = ShapeGeometry.TryGetContact(sphere, sphereTransform, capsule, capsuleTransform, out var contact);
        var resolvedTransform = hasContact
            ? sphereTransform.WithPosition(sphereTransform.Position + contact.Normal * (contact.Penetration + 0.002f))
            : sphereTransform;
        Check(
            "ShapeGeometry resolves a rotated Sphere and Capsule contact analytically",
            hasContact && !ShapeGeometry.Overlaps(sphere, resolvedTransform, capsule, capsuleTransform),
            $"hasContact={hasContact} normal={contact.Normal} penetration={contact.Penetration}");
    }

    {
        var contactCapsule = new CapsuleShape3D { Radius = 0.45f, CylinderHeight = 1.2f };
        var contactBox = new BoxShape3D { Size = new Vector3(1.4f, 1.1f, 1.6f) };
        var capsuleTransform = new Transform3D(
            new Vector3(0.35f, 0.55f, 0.1f),
            Quaternion.CreateFromAxisAngle(Vector3.UnitZ, 0.55f),
            1f);
        var boxTransform = new Transform3D(
            Vector3.Zero,
            Quaternion.CreateFromAxisAngle(Vector3.UnitY, -0.35f),
            1f);
        var hasContact = ShapeGeometry.TryGetContact(contactCapsule, capsuleTransform, contactBox, boxTransform, out var contact);
        var resolvedTransform = hasContact
            ? capsuleTransform.WithPosition(capsuleTransform.Position + contact.Normal * (contact.Penetration + 0.002f))
            : capsuleTransform;
        Check(
            "ShapeGeometry resolves a rotated Capsule and Box contact with bounded EPA",
            hasContact && contact.FeatureId != 0 &&
            !ShapeGeometry.Overlaps(contactCapsule, resolvedTransform, contactBox, boxTransform),
            $"hasContact={hasContact} normal={contact.Normal} penetration={contact.Penetration} feature={contact.FeatureId}");
    }

    {
        var separatedCapsule = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f };
        var separatedBox = new BoxShape3D { Size = new Vector3(1f, 1f, 1f) };
        var capsuleTransform = new Transform3D(new Vector3(1.4f, 0.75f, 0f), Quaternion.Identity, 1f);
        var boxTransform = new Transform3D(new Vector3(0f, 0.5f, 0f), Quaternion.Identity, 1f);
        var hasContact = ShapeGeometry.TryGetContact(
            separatedCapsule,
            capsuleTransform,
            separatedBox,
            boxTransform,
            out var contact);
        Check(
            "ShapeGeometry rejects horizontally separated axis-aligned Capsule and Box",
            !hasContact && !ShapeGeometry.Overlaps(
                separatedCapsule,
                capsuleTransform,
                separatedBox,
                boxTransform),
            $"hasContact={hasContact} normal={contact.Normal} penetration={contact.Penetration}");

        var grazingCapsule = new CapsuleShape3D { Radius = 0.35f, CylinderHeight = 1f };
        var grazingBox = new BoxShape3D { Size = Vector3.One };
        var grazingStart = new Transform3D(new Vector3(0f, 0.75f, 0f), Quaternion.Identity, 1f);
        var grazingTarget = new Transform3D(new Vector3(1f, 0.5f, 1f), Quaternion.Identity, 1f);
        Check(
            "ShapeGeometry rejects a diagonal Capsule sweep outside a Box corner",
            !ShapeGeometry.Sweep(
                grazingCapsule,
                grazingStart,
                new Vector3(0.25f, 0f, 0.25f),
                grazingBox,
                grazingTarget,
                out var sweep),
            $"fraction={sweep.Fraction} position={sweep.Position} normal={sweep.Normal}");
    }

    var rigidInsertionHashA = SimulateRigidInsertionHash(reverseInsertion: false);
    var rigidInsertionHashB = SimulateRigidInsertionHash(reverseInsertion: true);
    Check(
        "RigidBody3D preserves state for reversed scene insertion order",
        rigidInsertionHashA == rigidInsertionHashB,
        $"forward={rigidInsertionHashA:X16} reverse={rigidInsertionHashB:X16}");

    using (var warmRigidPhysicsTree = new SceneTree())
    {
        var warmWorld = new PhysicsWorld3D { Name = "WarmRigidWorld", Gravity = Vector3.Zero };
        var warmFloor = new StaticBody3D { Name = "WarmFloor", Position = new Vector3(0f, -0.5f, 0f) };
        warmFloor.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(8f, 1f, 8f) } });
        var warmBody = new RigidBody3D { Name = "WarmBody", Position = new Vector3(0f, 0.49f, 0f) };
        warmBody.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
        warmWorld.AddChild(warmFloor);
        warmWorld.AddChild(warmBody);
        warmRigidPhysicsTree.Root.AddChild(warmWorld);
        for (var tick = 0; tick < 64; tick++)
        {
            warmRigidPhysicsTree.ProcessFrame(warmRigidPhysicsTree.PhysicsDelta);
        }

        var allocatedBefore = GC.GetAllocatedBytesForCurrentThread();
        for (var tick = 0; tick < 1_000; tick++)
        {
            warmRigidPhysicsTree.ProcessFrame(warmRigidPhysicsTree.PhysicsDelta);
        }

        var allocated = GC.GetAllocatedBytesForCurrentThread() - allocatedBefore;
        Check("RigidBody3D warm contact step has no managed allocations", allocated == 0, $"bytes={allocated}");
    }

    var characterHashA = SimulateCharacterSlideHash();
    var characterHashB = SimulateCharacterSlideHash();
    Check(
        "CharacterBody3D preserves a deterministic 1000-tick state hash",
        characterHashA == characterHashB,
        $"first={characterHashA:X16} second={characterHashB:X16}");

    System.Reflection.Assembly? physicsAssembly = null;
    try
    {
        physicsAssembly = System.Reflection.Assembly.Load("Cubit.Physics");
        Check("Cubit.Physics assembly loadable", true, physicsAssembly.FullName ?? "");
    }
    catch (Exception ex)
    {
        Check("Cubit.Physics assembly loadable", false, ex.Message);
    }

    if (physicsAssembly is not null)
    {
        Check(
            "CubitPhysicsPlugin type exists",
            physicsAssembly.GetType("Cubit.Physics.CubitPhysicsPlugin") is not null,
            "Cubit.Physics.CubitPhysicsPlugin");
        Check(
            "PhysicsWorld3D type exists",
            physicsAssembly.GetType("Cubit.Physics.Scene.PhysicsWorld3D") is not null,
            "Cubit.Physics.Scene.PhysicsWorld3D");
    }

    Console.WriteLine(failures == 0 ? "physicscheck passed" : $"physicscheck failed {failures}");
    return failures == 0 ? 0 : 1;
}

static ulong SimulateCharacterSlideHash()
{
    using var tree = new SceneTree();
    var world = new PhysicsWorld3D();
    var floor = new StaticBody3D { Position = new Vector3(0f, -0.5f, 0f) };
    floor.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(16f, 1f, 16f) } });
    var wall = new StaticBody3D { Position = new Vector3(2f, 1.5f, 0f) };
    wall.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(1f, 3f, 16f) } });
    var character = new CharacterBody3D { Position = new Vector3(0f, 1.5f, 0f) };
    character.AddChild(new CollisionShape3D
    {
        Shape = new CapsuleShape3D { Radius = 0.5f, CylinderHeight = 1f },
    });
    world.AddChild(floor);
    world.AddChild(wall);
    world.AddChild(character);
    tree.Root.AddChild(world);
    tree.ProcessFrame(tree.PhysicsDelta);

    var hash = 14695981039346656037UL;
    for (var tick = 0; tick < 1_000; tick++)
    {
        character.Velocity = new Vector3(12f, -20f, 3f);
        character.MoveAndSlide();
        tree.ProcessFrame(tree.PhysicsDelta);
        hash = MixCharacterHash(hash, character.GlobalPosition.X);
        hash = MixCharacterHash(hash, character.GlobalPosition.Y);
        hash = MixCharacterHash(hash, character.GlobalPosition.Z);
        hash ^= character.IsOnFloor ? 1UL : 0UL;
        hash *= 1099511628211UL;
        hash ^= (uint)character.LastSlideCount;
        hash *= 1099511628211UL;
    }

    return hash;
}

static ulong SimulateRigidInsertionHash(bool reverseInsertion)
{
    using var tree = new SceneTree();
    var world = new PhysicsWorld3D { Gravity = new Vector3(0f, -10f, 0f) };
    var floor = new StaticBody3D { Name = "Floor", Position = new Vector3(0f, -0.5f, 0f) };
    floor.AddChild(new CollisionShape3D { Shape = new BoxShape3D { Size = new Vector3(8f, 1f, 8f) } });
    var lower = new RigidBody3D { Name = "Lower", Position = new Vector3(0f, 0.5f, 0f) };
    lower.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
    var upper = new RigidBody3D { Name = "Upper", Position = new Vector3(0f, 1.5f, 0f) };
    upper.AddChild(new CollisionShape3D { Shape = new SphereShape3D { Radius = 0.5f } });
    world.AddChild(floor);
    if (reverseInsertion)
    {
        world.AddChild(upper);
        world.AddChild(lower);
    }
    else
    {
        world.AddChild(lower);
        world.AddChild(upper);
    }

    tree.Root.AddChild(world);
    for (var tick = 0; tick < 120; tick++)
    {
        tree.ProcessFrame(tree.PhysicsDelta);
    }

    var hash = 14695981039346656037UL;
    MixRigidHash(ref hash, lower.GlobalPosition);
    MixRigidHash(ref hash, lower.LinearVelocity);
    hash ^= lower.IsSleeping ? 1UL : 0UL;
    hash *= 1099511628211UL;
    MixRigidHash(ref hash, upper.GlobalPosition);
    MixRigidHash(ref hash, upper.LinearVelocity);
    hash ^= upper.IsSleeping ? 1UL : 0UL;
    return hash * 1099511628211UL;
}

static void MixRigidHash(ref ulong hash, Vector3 value)
{
    hash = MixCharacterHash(hash, value.X);
    hash = MixCharacterHash(hash, value.Y);
    hash = MixCharacterHash(hash, value.Z);
}

static ulong MixCharacterHash(ulong hash, float value)
{
    hash ^= (uint)BitConverter.SingleToInt32Bits(value);
    return hash * 1099511628211UL;
}

static void CreateDirectoryJunction(string linkPath, string targetPath)
{
    if (!OperatingSystem.IsWindows())
    {
        Directory.CreateSymbolicLink(linkPath, targetPath);
        return;
    }

    var command = Environment.GetEnvironmentVariable("COMSPEC") ?? "cmd.exe";
    using var process = Process.Start(new ProcessStartInfo
    {
        FileName = command,
        Arguments = $"/d /c mklink /J \"{linkPath}\" \"{targetPath}\"",
        UseShellExecute = false,
        CreateNoWindow = true,
        RedirectStandardOutput = true,
        RedirectStandardError = true,
    }) ?? throw new InvalidOperationException("无法启动 mklink 创建 Junction");
    var standardOutput = process.StandardOutput.ReadToEnd();
    var standardError = process.StandardError.ReadToEnd();
    process.WaitForExit();
    if (process.ExitCode != 0)
    {
        throw new InvalidOperationException(
            $"创建 Junction 失败（exit={process.ExitCode}）: {standardOutput}{standardError}");
    }
}

static void DeleteDirectoryJunction(string linkPath)
{
    if (Directory.Exists(linkPath))
    {
        Directory.Delete(linkPath);
    }
}

/// <summary>临时正式项目的运行会话，释放时同时清理其项目目录。</summary>
file sealed class VoxelProjectTestSession(
    string projectRoot,
    GameScene scene,
    InputServer input,
    VoxelInputState voxelInput) : IDisposable
{
    private bool _disposed;

    public GameScene Scene { get; } = scene;

    public InputServer Input { get; } = input;

    public VoxelInputState VoxelInput { get; } = voxelInput;

    public void Dispose()
    {
        if (_disposed)
        {
            return;
        }

        _disposed = true;
        try
        {
            Scene.Dispose();
        }
        finally
        {
            if (Directory.Exists(projectRoot))
            {
                Directory.Delete(projectRoot, recursive: true);
            }
        }
    }
}

/// <summary>无 GPU 的渲染服务替身：记录调用次数，用于模拟测试。</summary>
file sealed class FakeRenderBackend : IRenderBackend
{
    private readonly HashSet<ulong> _activeMeshes = [];

    public int MeshUploadCount { get; private set; }

    public int MeshRemovalCount { get; private set; }

    public int MeshTransformUpdateCount { get; private set; }

    public Matrix4x4 LastMeshTransform { get; private set; } = Matrix4x4.Identity;

    public Vector4 LastMeshModulation { get; private set; } = Vector4.One;

    public Vector4 LastEnvironmentModulation { get; private set; } = Vector4.One;

    public int ActiveMeshCount => _activeMeshes.Count;

    /// <summary>仅供自检确认指定网格 RID 的后端生命周期。</summary>
    public bool IsMeshActive(RID rid) => rid.IsValid && _activeMeshes.Contains(rid.Value);

    public int CameraUpdateCount { get; private set; }

    public (int Width, int Height) FramebufferSize => (1280, 720);

    public void UpdateCamera(in Matrix4x4 view, in Matrix4x4 projection) => CameraUpdateCount++;

    public void SetTexture(RID rid, TextureData texture)
    {
    }

    public void RemoveTexture(RID rid)
    {
    }

    public void SetMaterial(RID rid, MaterialData material)
    {
    }

    public void RemoveMaterial(RID rid)
    {
    }

    public void SetMesh(RID rid, MeshData mesh)
    {
        MeshUploadCount++;
        LastMeshModulation = mesh.Modulation;
        _activeMeshes.Add(rid.Value);
    }

    public void UpdateMeshTransform(RID rid, in Matrix4x4 transform)
    {
        MeshTransformUpdateCount++;
        LastMeshTransform = transform;
    }

    public void UpdateMeshModulation(RID rid, in Vector4 modulation)
    {
        LastMeshModulation = modulation;
    }

    public void SetEnvironmentModulation(in Vector4 modulation)
    {
        LastEnvironmentModulation = modulation;
    }

    public void RemoveMesh(RID rid)
    {
        MeshRemovalCount++;
        _activeMeshes.Remove(rid.Value);
    }
}

/// <summary>Engine 生命周期检查用窗口：可控地阻塞主循环且不创建 Vulkan 表面。</summary>
file sealed class EngineCheckWindow : IGameWindow
{
    public ManualResetEventSlim RunEntered { get; } = new(false);

    private readonly ManualResetEventSlim _runGate = new(false);

    public (int Width, int Height) FramebufferSize => (1280, 720);

    public bool SurfaceMayChange => false;

    public string[] RequiredVulkanExtensions => [];

    public event Action? Load;

    public event Action<int, int>? Resize;

    public event Action<double>? Render;

    public unsafe Silk.NET.Vulkan.SurfaceKHR CreateVulkanSurface(Silk.NET.Vulkan.Vk vk, Silk.NET.Vulkan.Instance instance) =>
        throw new InvalidOperationException("enginecheck 不应创建 Vulkan 表面");

    public void Run()
    {
        RunEntered.Set();
        _runGate.Wait();
    }

    public void Close() => _runGate.Set();

    public void RaiseLoad() => Load?.Invoke();

