file class CountingRenderBackendProxy : DispatchProxy
{
    private readonly Dictionary<string, int> _calls = new(StringComparer.Ordinal);

    public int CallCount(string methodName) => _calls.GetValueOrDefault(methodName);

    protected override object? Invoke(MethodInfo? targetMethod, object?[]? args)
    {
        var name = targetMethod?.Name ?? throw new InvalidOperationException("渲染后端调用缺少方法信息");
        _calls[name] = CallCount(name) + 1;
        return name == "get_FramebufferSize" ? (1280, 720) : null;
    }
}

