}

file sealed class CoordinatedContentImporter : IContentImporter, IDisposable
{
    private readonly ManualResetEventSlim _bothCallsEntered = new(false);
    private readonly ManualResetEventSlim _release = new(false);
    private int _callCount;

    public string Id => "content.concurrent";

    public Version Version => new(1, 0, 0);

    public IReadOnlyCollection<string> Extensions => [".race"];

    public bool WaitForBothCalls(TimeSpan timeout) => _bothCallsEntered.Wait(timeout);

    public void Release() => _release.Set();

    public ContentArtifact Import(ContentImportContext context)
    {
        ArgumentNullException.ThrowIfNull(context);
        if (Interlocked.Increment(ref _callCount) == 2)
        {
            _bothCallsEntered.Set();
        }

        _release.Wait();
        return new ContentArtifact(
            ".bin",
            context.SourceData.ToArray(),
            JsonSerializer.Serialize(new
            {
                importer = Id,
                importerVersion = Version.ToString(),
                cacheKey = context.CacheKey,
            }));
    }

    public void Dispose()
    {
        _bothCallsEntered.Dispose();
        _release.Dispose();
    }
}

file sealed class ExtensionSensitiveContentImporter : IContentImporter
{
    public string Id => "content.extension-sensitive";

    public Version Version => new(1, 0, 0);

    public IReadOnlyCollection<string> Extensions => [".first", ".second"];

    public ContentArtifact Import(ContentImportContext context)
    {
        ArgumentNullException.ThrowIfNull(context);
        var extension = Path.GetExtension(context.SourcePath).ToLowerInvariant();
        return new ContentArtifact(
            extension == ".first" ? ".first-artifact" : ".second-artifact",
            context.SourceData.ToArray(),
            JsonSerializer.Serialize(new
            {
                importer = Id,
                importerVersion = Version.ToString(),
                cacheKey = context.CacheKey,
            }));
    }
}

