public sealed class EditorPreviewProbe : IProjectPreviewBootstrap
{
    public static int ConfigureCalls { get; private set; }

    public static int FixedSystemCalls { get; private set; }

    public static void Reset()
    {
        ConfigureCalls = 0;
        FixedSystemCalls = 0;
    }

        public void ConfigurePreview(ProjectPreviewContext context)
        {
            ConfigureCalls++;
            var ecs = new EcsNode { Name = "PreviewEcs" };
            var entity = ecs.World.CreateEntity();
            ecs.World.AddComponent(entity, Vector3.Zero);
            ecs.AddSystem(new EcsProbeSystem(
                new EcsSystemDescriptor(
                    "editor-preview.probe",
                    EcsSystemPhase.FixedUpdate,
                    new HashSet<Type> { typeof(Vector3) },
                    new HashSet<Type> { typeof(Vector3) },
                    RequiresMainThread: true),
                systemContext =>
                {
                    FixedSystemCalls++;
                    foreach (var item in systemContext.World.Query<Vector3>())
                    {
                        item.Component.X += 1f;
                    }
                }));
        context.SceneRoot.AddChild(ecs);
        context.SceneRoot.AddChild(new BoxMesh3D
        {
            Name = "PreviewAnchor",
            Position = new Vector3(32f, 30f, 32f),
            Size = 2f,
        });
    }
}

public sealed class ScriptingProbe : CubitScript
{
    private readonly List<string> _log = [];

    [Export("ExportedValue")]
    public int ExportedValue { get; set; }

    [Export("ExportedField")]
    public int ExportedField;

    public int NonExportedValue { get; set; }

    private int _throwingValue;

    [Export("ThrowingValue")]
    public int ThrowingValue
    {
        get => _throwingValue;
        set
        {
            if (value == 13)
            {
                throw new InvalidOperationException("setter failure");
            }

            _throwingValue = value;
        }
    }

    [Export("ThrowOnProcess")]
    public bool ThrowOnProcess { get; set; }

    [Export("ThrowScriptRuntimeException")]
    public bool ThrowScriptRuntimeException { get; set; }

    public IReadOnlyList<string> Log => _log;

    protected override void OnEnterTree() => _log.Add("enter");

    protected override void OnReady() => _log.Add("ready");

    protected override void OnPhysicsProcess(double delta) => _log.Add("physics");

    protected override void OnProcess(double delta)
    {
        _log.Add("process");
        if (ThrowScriptRuntimeException)
        {
            throw new ScriptRuntimeException("user failure", "UserType", "/User", "user");
        }

        if (ThrowOnProcess)
        {
            throw new InvalidOperationException("scripting probe failure");
        }
    }

    protected override void OnExitTree() => _log.Add("exit");
}

