sealed class DelayedChunkStorage(TimeSpan delay) : IChunkStorageWriter, IDisposable
{
    private readonly object _sync = new();
    private readonly Dictionary<(int X, int Z), PersistedChunk> _chunks = [];
    private readonly ManualResetEventSlim _saveStarted = new(false);
    private bool _disposed;
    private int _saveCalls;

    public int SaveCalls => Volatile.Read(ref _saveCalls);

    public bool WaitForSaveStart(TimeSpan timeout) => _saveStarted.Wait(timeout);

    public bool TryLoadChunk(int cx, int cz, out PersistedChunk chunk)
    {
        lock (_sync)
        {
            ObjectDisposedException.ThrowIf(_disposed, this);
            return _chunks.TryGetValue((cx, cz), out chunk);
        }
    }

    public void SaveChunk(int cx, int cz, PersistedChunk chunk)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        _saveStarted.Set();
        Thread.Sleep(delay);
        lock (_sync)
        {
            ObjectDisposedException.ThrowIf(_disposed, this);
            _chunks[(cx, cz)] = chunk;
            Interlocked.Increment(ref _saveCalls);
        }
    }

    public void Dispose()
    {
        lock (_sync)
        {
            _disposed = true;
            _chunks.Clear();
            _saveStarted.Dispose();
        }
    }
}

sealed class FailOnceChunkStorage : IChunkStorage
{
    private int _hasFailed;

    public bool TryLoadChunk(int cx, int cz, out PersistedChunk chunk)
    {
        if (Interlocked.Exchange(ref _hasFailed, 1) == 0)
        {
            throw new IOException("测试用一次性区块读取失败");
        }

        chunk = default;
        return false;
    }
}

sealed class FailOnceSavingChunkStorage : IChunkStorageWriter, IDisposable
{
    private readonly object _sync = new();
    private readonly Dictionary<(int X, int Z), PersistedChunk> _chunks = [];
    private int _saveCalls;
    private bool _disposed;

    public int SaveCalls => Volatile.Read(ref _saveCalls);

    public bool TryLoadChunk(int cx, int cz, out PersistedChunk chunk)
    {
        lock (_sync)
        {
            ObjectDisposedException.ThrowIf(_disposed, this);
            return _chunks.TryGetValue((cx, cz), out chunk);
        }
    }

    public void SaveChunk(int cx, int cz, PersistedChunk chunk)
    {
        ObjectDisposedException.ThrowIf(_disposed, this);
        var saveNumber = Interlocked.Increment(ref _saveCalls);
        if (saveNumber == 1)
        {
            throw new IOException("测试用一次性区块保存失败");
        }

        lock (_sync)
        {
            ObjectDisposedException.ThrowIf(_disposed, this);
            _chunks[(cx, cz)] = chunk;
        }
    }

    public void Dispose()
    {
        lock (_sync)
        {
            _disposed = true;
            _chunks.Clear();
        }
    }
}

