    public int CreateCount { get; private set; }

    public int Revision { get; set; }

    public IMcpExtensionProvider Create(McpProjectExtensionContext context)
    {
        CreateCount++;
        return new McpCompositionProbeProvider(this);
    }
}

sealed class McpCompositionProbeProvider(McpCompositionProbeModule module) : IMcpExtensionProvider
{
    public IEnumerable<McpToolDescriptor> GetTools()
    {
        yield return new McpToolDescriptor(
            $"probe.{module.PluginId["cubit.".Length..]}.tool.{module.Revision}",
            "MCP composition probe tool",
            new { type = "object", properties = new { } },
            _ => module.PluginId);
    }

    public IEnumerable<McpResourceDescriptor> GetResources()
    {
        yield return new McpResourceDescriptor(
            $"cubit://probe/{module.PluginId["cubit.".Length..]}/{module.Revision}",
            "MCP composition probe resource",
            "text/plain",
            () => module.PluginId);
    }

    public IEnumerable<McpPromptDescriptor> GetPrompts()
    {
        yield return new McpPromptDescriptor(
            $"probe.{module.PluginId["cubit.".Length..]}.prompt.{module.Revision}",
            "MCP composition probe prompt",
            Array.Empty<object>(),
            _ => module.PluginId);
    }
}

file sealed class ToolCrossChunkFeaturePass : IVoxelFeaturePass
{
    public string Id => "tool.cross-chunk-oak";

    public FeaturePlacementBuffer Generate(
        in ChunkGenerationContext context,
        int originX,
        int originY,
        int originZ,
        uint seed)
    {
        var builder = FeaturePlacementBuffer.CreateBuilder(context);
        builder.Add(originX + 8, 300, originZ, BlockRegistry.GetKey(BlockRegistry.Wood));
        return builder.Build();
    }
}

file sealed class ToolTerrainPass(
    string id,
    ToolTerrainPass.EvaluateDelegate evaluate) : IVoxelTerrainPass
{
    public delegate VoxelTerrainColumn EvaluateDelegate(
        in VoxelTerrainColumnContext context,
        in VoxelTerrainColumn column);

    public string Id { get; } = id;

    public VoxelTerrainColumn Evaluate(
        in VoxelTerrainColumnContext context,
        in VoxelTerrainColumn column) => evaluate(in context, in column);
}

file sealed class ToolTerrainProbeFeaturePass(int x, int z) : IVoxelFeaturePass
{
    public string Id => "tool.terrain-query-probe";

    public int ObservedSurfaceY { get; private set; }

    public BlockState ObservedBlock { get; private set; }

    public FeaturePlacementBuffer Generate(
        in ChunkGenerationContext context,
        int originX,
        int originY,
        int originZ,
        uint seed)
    {
        ObservedSurfaceY = context.GetSurfaceY(x, z);
        ObservedBlock = context.GetBlock(x, ObservedSurfaceY - 1, z);
        return FeaturePlacementBuffer.Empty;
    }
}

file sealed class ToolRepeatedTerrainQueryFeaturePass(int repeats, int x, int z) : IVoxelFeaturePass
{
    public string Id => "tool.repeated-terrain-query";

    public FeaturePlacementBuffer Generate(
        in ChunkGenerationContext context,
        int originX,
        int originY,
        int originZ,
        uint seed)
    {
        for (var i = 0; i < repeats; i++)
        {
            var surfaceY = context.GetSurfaceY(x, z);
            _ = context.GetBlock(x, surfaceY - 1, z);
        }

        return FeaturePlacementBuffer.Empty;
    }
}

file sealed class ToolCrossChunkFeatureBurstPass : IVoxelFeaturePass
{
    public const int PlacementCount = 64;

    public string Id => "tool.cross-chunk-oak-burst";

    public FeaturePlacementBuffer Generate(
        in ChunkGenerationContext context,
        int originX,
        int originY,
        int originZ,
        uint seed)
    {
        if (context.ChunkX != 0 || context.ChunkZ != 0)
        {
            return FeaturePlacementBuffer.Empty;
        }

        var builder = FeaturePlacementBuffer.CreateBuilder(context);
        for (var offset = 0; offset < PlacementCount; offset++)
        {
            builder.Add(Chunk.SizeX, 200 + offset, 8, BlockRegistry.GetKey(BlockRegistry.Leaves));
        }

        return builder.Build();
    }
}

file sealed class RecordingProjectEditorUiContext : IProjectEditorUiContext
{
    public List<string> Texts { get; } = [];

    public List<string> ButtonLabels { get; } = [];

    public List<string> InputTextLabels { get; } = [];

    public Func<string, bool>? ButtonHandler { get; init; }

    public Func<string, string, string?>? InputTextHandler { get; init; }

    public void Text(string text) => Texts.Add(text);

    public bool Button(string label)
    {
        ButtonLabels.Add(label);
        return ButtonHandler?.Invoke(label) == true;
    }

    public bool InputText(string label, ref string value, int maxLength)
    {
        InputTextLabels.Add(label);
        var replacement = InputTextHandler?.Invoke(label, value);
        if (replacement is null)
        {
            return false;
        }

        value = replacement;
        return true;
    }

    public void Separator()
    {
    }
}
